def migrate_backup_dir(root):
    """Renames a mod's old _balance_backups folder to BACKUP_DIR (or merges it in if both exist)."""
    try:
        old, new = Path(root) / OLD_BACKUP_DIR, Path(root) / BACKUP_DIR
        if old.is_dir() and not new.exists():
            old.rename(new)
        elif old.is_dir():
            for x in list(old.iterdir()):
                if not (new / x.name).exists():
                    shutil.move(str(x), str(new / x.name))
            try:
                old.rmdir()
            except OSError:
                pass
    except Exception:
        pass

