# =============================================================== internal error log
ERRLOG = []                                 # [(time, where, text)] - every error the editor itself ran into; shown in the Debug tab


CRASH_LOG = None                            # balance_editor_crash.log next to the editor: errors, "breadcrumbs" and hard crashes (set up in main())


def crumb(msg):
    """One line in the crash log, flushed at once - after a crash the last lines show where it happened."""
    try:
        if CRASH_LOG is not None:
            CRASH_LOG.write("%s  %s\n" % (time.strftime("%H:%M:%S"), msg))
            CRASH_LOG.flush()
    except Exception:
        pass


def start_crash_log():
    global CRASH_LOG
    import faulthandler, tempfile
    for base in (Path(__file__).resolve().parent, Path(tempfile.gettempdir())):
        try:
            path = base / "balance_editor_crash.log"
            if path.exists():
                try:
                    os.replace(path, base / "balance_editor_crash_previous.log")
                except OSError:
                    pass
            CRASH_LOG = open(path, "w", encoding="utf-8", errors="replace")
            CRASH_LOG.write("StarDrive Balance Editor %s - started %s\nPython %s\n" % (VERSION, time.strftime("%Y-%m-%d %H:%M:%S"), sys.version.split()[0]))
            CRASH_LOG.flush()
            faulthandler.enable(file=CRASH_LOG, all_threads=True)       # a hard crash (not a normal error) writes where Python was
            def hook(et, ev, tb):
                import traceback
                crumb("UNCAUGHT " + "".join(traceback.format_exception(et, ev, tb)))
                sys.__excepthook__(et, ev, tb)
            sys.excepthook = hook
            try:
                threading.excepthook = lambda a: crumb("THREAD ERROR %s" % "".join(__import__("traceback").format_exception(a.exc_type, a.exc_value, a.exc_traceback)))
            except Exception:
                pass
            return str(path)
        except Exception:
            CRASH_LOG = None
    return ""


def log_exc(where="", info=None):
    """Remember the exception being handled (or `info` = (type, value, tb)) and print it. Nothing is lost silently any more."""
    import traceback
    ei = info or sys.exc_info()
    try:
        txt = "".join(traceback.format_exception(*ei)).strip()
    except Exception:
        txt = str(ei[1])
    ERRLOG.append((time.strftime("%H:%M:%S"), where, txt))
    del ERRLOG[:-200]
    crumb("ERROR in %s: %s" % (where, txt))
    try:
        print(txt, file=sys.stderr)
    except Exception:
        pass


