class ImageCache:
    """Mixin: self.img(path, size) loads a picture once and remembers it; pictures that can't be read are listed in Debug."""
    def img(self, path, size):
        imgs = self.__dict__.setdefault("imgs", {})
        key = (str(path), size)
        if key not in imgs:
            try:
                imgs[key] = load_image(path, size)
            except Exception as e:
                self.proj.bad_icons[str(path)] = "%s: %s" % (type(e).__name__, e)
                imgs[key] = None
        return imgs[key]


# =============================================================== file helpers
_PREREAD = {}


def prefetch(paths, workers=8):
    """Read many files at once on several threads (disk waits overlap, which is most of the time on Windows). read_file() then finds them ready."""
    paths = [str(p) for p in paths]
    if len(paths) < 8:
        return
    from concurrent.futures import ThreadPoolExecutor

    def get(p):
        try:
            with open(p, "rb") as f:
                return p, f.read()
        except OSError:
            return p, None
    try:
        with ThreadPoolExecutor(workers) as ex:
            for p, raw in ex.map(get, paths):
                if raw is not None:
                    _PREREAD[p] = raw
    except Exception:
        pass


def read_file(path):
    raw = _PREREAD.pop(str(path), None)
    if raw is None:
        raw = Path(path).read_bytes()
    bom = raw.startswith(b"\xef\xbb\xbf")
    if bom:
        raw = raw[3:]
    try:
        return raw.decode("utf-8"), bom, "utf-8"
    except UnicodeDecodeError:
        return raw.decode("cp1252"), bom, "cp1252"


def encode(text, bom, enc):
    return (b"\xef\xbb\xbf" if bom else b"") + text.encode(enc)


def yaml_unescape(s):
    table = {'"': '"', "\\": "\\", "n": "\n", "t": "\t"}
    return re.sub(r'\\(["\\nt])', lambda m: table[m.group(1)], s)


def yaml_escape(s):
    s = s.replace("\r\n", "\n")
    return (s.replace("\\", "\\\\").replace('"', '\\"')
             .replace("\n", "\\n").replace("\t", "\\t"))


def parse_yaml_str(raw):
    """Value part of an ' ENG: "..."' line. Tolerates a missing closing quote."""
    raw = raw.strip()
    if raw.startswith('"'):
        body = raw[1:]
        if body.endswith('"') and not body.endswith('\\"'):
            body = body[:-1]
        return yaml_unescape(body)
    return raw


# ---- .dds without Pillow: a small built-in reader (uncompressed RGB(A), DXT1/3/5 = BC1/2/3) -> RGBA -> PNG for Tk
def _c565(c):
    return (((c >> 11) & 31) * 255 + 15) // 31, (((c >> 5) & 63) * 255 + 31) // 63, ((c & 31) * 255 + 15) // 31


def decode_dds(path, raw=None):
    """-> (width, height, RGBA bytearray) of the top image in a .dds file (or in `raw` bytes of one)."""
    if raw is None:
        raw = Path(path).read_bytes()
    if len(raw) < 128 or raw[:4] != b"DDS ":
        raise ValueError("not a DDS file")
    h, w = struct.unpack_from("<II", raw, 12)
    pf_flags, fourcc = struct.unpack_from("<I4s", raw, 80)
    bits, rm, gm, bm, am = struct.unpack_from("<5I", raw, 88)
    if not (0 < w <= 4096 and 0 < h <= 4096):
        raise ValueError("unsupported DDS size %dx%d" % (w, h))
    off, kind = 128, None
    if pf_flags & 0x4:                                   # compressed (FourCC)
        if fourcc == b"DX10":
            fmt = struct.unpack_from("<I", raw, 128)[0]
            off = 148
            kind = {71: "bc1", 72: "bc1", 74: "bc2", 75: "bc2", 77: "bc3", 78: "bc3"}.get(fmt)
            if fmt in (28, 29):
                kind, bits, rm, gm, bm, am, pf_flags = "raw", 32, 0xFF, 0xFF00, 0xFF0000, 0xFF000000, 0x41
            elif fmt in (87, 91):
                kind, bits, rm, gm, bm, am, pf_flags = "raw", 32, 0xFF0000, 0xFF00, 0xFF, 0xFF000000, 0x41
            if kind is None:
                raise ValueError("unsupported DDS format (DXGI %d)" % fmt)
        else:
            kind = {b"DXT1": "bc1", b"DXT2": "bc2", b"DXT3": "bc2", b"DXT4": "bc3", b"DXT5": "bc3"}.get(fourcc)
            if kind is None:
                raise ValueError("unsupported DDS compression %r" % fourcc)
    elif pf_flags & 0x40 and bits in (24, 32):
        kind = "raw"
    else:
        raise ValueError("unsupported DDS pixel format")
    out = bytearray(w * h * 4)
    if kind == "raw":
        bpp = bits // 8
        if len(raw) < off + w * h * bpp:
            raise ValueError("DDS file is truncated")
        chans = []
        for mask in (rm, gm, bm, am if pf_flags & 0x1 else 0):
            if mask:
                sh = (mask & -mask).bit_length() - 1
                mx = mask >> sh
                chans.append((sh, mx, 255.0 / mx))
            else:
                chans.append(None)
        for i in range(w * h):
            v = int.from_bytes(raw[off + i * bpp:off + (i + 1) * bpp], "little")
            for c, ch in enumerate(chans):
                out[i * 4 + c] = 255 if (ch is None and c == 3) else 0 if ch is None else int(((v >> ch[0]) & ch[1]) * ch[2] + 0.5)
        return w, h, out
    bsz = 8 if kind == "bc1" else 16
    bw, bh = (w + 3) // 4, (h + 3) // 4
    if len(raw) < off + bw * bh * bsz:
        raise ValueError("DDS file is truncated")
    pos = off
    for by in range(bh):
        for bx in range(bw):
            blk = raw[pos:pos + bsz]
            pos += bsz
            c0, c1, bitsx = struct.unpack_from("<HHI", blk, bsz - 8)
            p0, p1 = _c565(c0), _c565(c1)
            if kind == "bc1" and c0 <= c1:
                cols = [p0, p1, tuple((a + b) // 2 for a, b in zip(p0, p1)), (0, 0, 0)]
                alph = [255, 255, 255, 0]
            else:
                cols = [p0, p1, tuple((2 * a + b) // 3 for a, b in zip(p0, p1)), tuple((a + 2 * b) // 3 for a, b in zip(p0, p1))]
                alph = [255] * 4
            if kind == "bc3":
                a0, a1 = blk[0], blk[1]
                if a0 > a1:
                    tab = [a0, a1] + [((7 - k) * a0 + k * a1) // 7 for k in range(1, 7)]
                else:
                    tab = [a0, a1] + [((5 - k) * a0 + k * a1) // 5 for k in range(1, 5)] + [0, 255]
                abits = int.from_bytes(blk[2:8], "little")
            for py in range(4):
                y = by * 4 + py
                if y >= h:
                    break
                for px in range(4):
                    x = bx * 4 + px
                    if x >= w:
                        break
                    n = py * 4 + px
                    r, g, b = cols[(bitsx >> (2 * n)) & 3]
                    if kind == "bc1":
                        a = alph[(bitsx >> (2 * n)) & 3]
                    elif kind == "bc2":
                        a = ((blk[n // 2] >> (4 * (n & 1))) & 15) * 17
                    else:
                        a = tab[(abits >> (3 * n)) & 7]
                    o = (y * w + x) * 4
                    out[o], out[o + 1], out[o + 2], out[o + 3] = r, g, b, a
    return w, h, out


# ---- .xnb (XNA / MonoGame content) textures: Texture2D, uncompressed. Colour, 565 / 5551 / 4444 and DXT1/3/5 -> RGBA
def _xnb_7bit(b, pos):
    n = shift = 0
    while True:
        c = b[pos]
        pos += 1
        n |= (c & 0x7F) << shift
        shift += 7
        if not c & 0x80:
            return n, pos


def decode_xnb(path):
    """-> (width, height, RGBA bytearray) of the picture in an .xnb file that holds a Texture2D."""
    b = Path(path).read_bytes()
    if len(b) < 20 or b[:3] != b"XNB":
        raise ValueError("not an XNB file")
    ver, flags = b[4], b[5]
    if flags & 0x80:
        raise ValueError("this .xnb is LZX-compressed, which this editor can't read yet")
    pos = 10
    n, pos = _xnb_7bit(b, pos)
    names = []
    for _ in range(n):
        ln, pos = _xnb_7bit(b, pos)
        names.append(b[pos:pos + ln].decode("utf-8", "replace"))
        pos += ln + 4
    _shared, pos = _xnb_7bit(b, pos)
    tid, pos = _xnb_7bit(b, pos)
    if not (1 <= tid <= len(names)) or "Texture2DReader" not in names[tid - 1]:
        raise ValueError("this .xnb is not a texture (%s)" % (names[tid - 1].split(",")[0].rsplit(".", 1)[-1] if 1 <= tid <= len(names) else "unknown"))
    fmt, w, h, mips = struct.unpack_from("<iiii", b, pos)
    pos += 16
    size = struct.unpack_from("<I", b, pos)[0]
    data = b[pos + 4:pos + 4 + size]
    if not (0 < w <= 4096 and 0 < h <= 4096):
        raise ValueError("unsupported .xnb size %dx%d" % (w, h))
    kinds = ({0: "rgba", 1: "565", 2: "5551", 3: "4444", 4: "bc1", 5: "bc2", 6: "bc3"} if ver >= 5 else
             {1: "bgra", 2: "bgra", 23: "565", 25: "5551", 26: "4444", 28: "bc1", 29: "bc2", 30: "bc3"}).get(fmt)
    if kinds is None:
        raise ValueError("unsupported .xnb pixel format %d" % fmt)
    if kinds in ("bc1", "bc2", "bc3"):
        hdr = bytearray(128)
        hdr[:4] = b"DDS "
        struct.pack_into("<II", hdr, 12, h, w)
        struct.pack_into("<I4s", hdr, 80, 4, {"bc1": b"DXT1", "bc2": b"DXT3", "bc3": b"DXT5"}[kinds])
        out = decode_dds(None, raw=bytes(hdr) + data)[2]
    elif kinds in ("rgba", "bgra"):
        if len(data) < w * h * 4:
            raise ValueError(".xnb is truncated")
        out = bytearray(data[:w * h * 4])
        if kinds == "bgra":
            out[0::4], out[2::4] = data[2:w * h * 4:4], data[0:w * h * 4:4]
        if kinds == "bgra" and fmt == 2:                       # Bgr32: no alpha
            out[3::4] = b"\xff" * (w * h)
    else:
        if len(data) < w * h * 2:
            raise ValueError(".xnb is truncated")
        out = bytearray(w * h * 4)
        for i in range(w * h):
            v = data[2 * i] | (data[2 * i + 1] << 8)
            if kinds == "565":
                r, g, bl, a = (v >> 11) * 255 // 31, ((v >> 5) & 63) * 255 // 63, (v & 31) * 255 // 31, 255
            elif kinds == "5551":
                r, g, bl, a = ((v >> 10) & 31) * 255 // 31, ((v >> 5) & 31) * 255 // 31, (v & 31) * 255 // 31, 255 if v & 0x8000 else 0
            else:
                r, g, bl, a = ((v >> 8) & 15) * 17, ((v >> 4) & 15) * 17, (v & 15) * 17, (v >> 12) * 17
            out[4 * i:4 * i + 4] = bytes((r, g, bl, a))
    if ver >= 5:                                              # XNA 4 stores premultiplied alpha
        for i in range(0, w * h * 4, 4):
            a = out[i + 3]
            if 0 < a < 255:
                out[i] = min(255, out[i] * 255 // a)
                out[i + 1] = min(255, out[i + 1] * 255 // a)
                out[i + 2] = min(255, out[i + 2] * 255 // a)
    return w, h, out


def pil_open(path):
    """A Pillow image for any picture this editor reads (including .xnb through the built-in reader)."""
    path = Path(path)
    if path.suffix.lower() == ".xnb":
        w, h, rgba = decode_xnb(path)
        return Image.frombytes("RGBA", (w, h), bytes(rgba))
    return Image.open(path)


def rgba_to_png(w, h, rgba):
    def chunk(t, d):
        return struct.pack(">I", len(d)) + t + d + struct.pack(">I", zlib.crc32(t + d) & 0xFFFFFFFF)
    rows = b"".join(b"\x00" + bytes(rgba[y * w * 4:(y + 1) * w * 4]) for y in range(h))
    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 6, 0, 0, 0))
            + chunk(b"IDAT", zlib.compress(rows, 6)) + chunk(b"IEND", b""))


# ================================================================ data model
KIND_ROOT = {"shipmodules": "ShipModule", "weapons": "Weapon", "technology": "Technology", "buildings": "Building"}   # xml root element of each kind
NOT_CONTENT = {"textures", "sounds", "audio", "video", "videos", "model", "models", "fonts", "races", "localization"}


def sniff_root(path):
    """Name of the root element of an xml file, '' if it cannot be told."""
    try:
        head = Path(path).read_bytes()[:4096].decode("utf-8", "ignore")
    except OSError:
        return ""
    head = re.sub(r"<\?.*?\?>|<!--.*?-->", "", head, flags=re.S)
    m = re.search(r"<\s*([A-Za-z_][\w.\-]*)", head)
    return m.group(1) if m else ""


class FieldDoc:
    """A thing with named string fields: orig = as on disk, cur = as edited."""

    def __init__(self):
        self.orig, self.cur, self.base = {}, {}, {}      # base = the "default" value (see Project.load_defaults)

    def differs_default(self, tag):
        return tag in self.base and self.cur.get(tag) != self.base.get(tag)

    def defaultable(self, tag):
        return not self.ro(tag)

    def set_default(self, tag):
        if tag in self.base:
            self.cur[tag] = self.base[tag]
            return True
        return False

    def get(self, tag):
        return self.cur.get(tag, "")

    def set(self, tag, value):
        self.cur[tag] = value
        rt = getattr(self, "removed_tags", None)
        if rt:
            rt.discard(tag)

    def ro(self, tag):
        return False

    def changed(self, tag):
        return self.cur.get(tag) != self.orig.get(tag)

    def revert(self, tag):
        rt = getattr(self, "removed_tags", None)
        if rt:
            rt.discard(tag)
        if tag in self.orig:
            self.cur[tag] = self.orig[tag]
        else:
            self.cur.pop(tag, None)

    def changes(self):
        out = [(t, self.orig.get(t), v) for t, v in self.cur.items() if self.changed(t)]
        out += [(t, self.orig.get(t), "(tag removed from the file)") for t in sorted(getattr(self, "removed_tags", ())) if t not in self.cur]
        return out

    def has_changes(self):
        return any(self.changed(t) for t in self.cur) or bool(getattr(self, "removed_tags", None))

    def can_remove(self, tag):
        return False


class XmlDoc(FieldDoc):
    """One ShipModule / Weapon xml file. Edits are spliced into the raw text."""

    def __init__(self, path, root, text=None, bom=False, enc="utf-8"):
        super().__init__()
        self.path = Path(path)
        self.rel = self.path.relative_to(root)
        if text is None:
            self.text, self.bom, self.enc = read_file(self.path)
        else:                                       # a file that does not exist yet
            self.text, self.bom, self.enc = text, bom, enc
        self.new = text is not None                 # not on disk yet
        self.nested = set()
        self.removed_tags = set()                   # tags deleted from the file (taken out of the text when saved)
        body = re.sub(r"^\s*<\?xml[^>]*\?>", "", self.text, count=1)
        el = ET.fromstring(body)
        self.root_tag = el.tag
        for ch in el:                       # comments are dropped by ElementTree
            if not isinstance(ch.tag, str) or ch.tag in self.orig:
                continue
            if len(ch):
                self.nested.add(ch.tag)
                self.orig[ch.tag] = "{nested}"
            else:
                self.orig[ch.tag] = ch.text or ""
        self.cur = dict(self.orig)
        self.base = dict(self.orig)

    def ro(self, tag):
        return tag in READ_ONLY_TAGS or tag in self.nested

    def can_remove(self, tag):
        return tag in self.cur and not self.ro(tag) and tag not in ("UID", "Name")

    def remove_tag(self, tag):
        """Delete a tag from this file (done when you Save). 'Revert' on it puts it back."""
        if not self.can_remove(tag):
            return False
        self.cur.pop(tag, None)
        if tag in self.orig:
            self.removed_tags.add(tag)
        return True

    @staticmethod
    def _find(text, tag):
        spans = [m.span() for m in re.finditer(r"<!--.*?-->", text, re.S)]
        t = re.escape(tag)
        pat = re.compile(r"<%s(\s[^>]*?)?(?:/>|>(.*?)</%s\s*>)" % (t, t), re.S)
        for m in pat.finditer(text):
            if not any(a <= m.start() < b for a, b in spans):
                return m
        return None

    def flat_changes(self):
        return FieldDoc.changes(self)

    def changes(self):
        out = FieldDoc.changes(self)
        if self.new:
            out.append(("NEW FILE", "", str(self.rel)))
        return out

    def has_changes(self):
        return self.new or FieldDoc.has_changes(self)

    def render(self):
        text = self.text
        nl = "\r\n" if "\r\n" in text else "\n"
        for tag, _old, new in self.flat_changes():
            if tag in self.removed_tags and tag not in self.cur:             # a deleted tag: its whole line goes
                m = self._find(text, tag)
                if m:
                    a, b = m.span()
                    ls = text.rfind("\n", 0, a) + 1
                    if not text[ls:a].strip():
                        a = ls
                        if text[b:b + 2] == "\r\n":
                            b += 2
                        elif text[b:b + 1] == "\n":
                            b += 1
                    text = text[:a] + text[b:]
                continue
            val = xml_escape(new).replace("\r\n", "\n").replace("\n", nl)
            m = self._find(text, tag)
            if m:
                text = text[:m.start()] + "<%s%s>%s</%s>" % (tag, m.group(1) or "", val, tag) + text[m.end():]
            else:                           # field didn't exist in this file: add it
                i = text.rfind("</%s" % self.root_tag)
                pre = "" if text[:i].endswith("\n") else nl
                text = text[:i] + pre + "  <%s>%s</%s>" % (tag, val, tag) + nl + text[i:]
        return text

    def encode(self, text):
        return encode(text, self.bom, self.enc)

    def mark_saved(self, text):
        self.text = text
        self.orig = dict(self.cur)
        self.removed_tags = set()
        self.new = False


def bonus_get(b, tag, default=""):
    return next((v for t, v, isx in b if t == tag and not isx), default)


def bonus_make(name, btype, amount, index, old=None):
    """An upgrade as a tuple of (tag, value, is_xml); the parts of `old` this editor does not edit are kept."""
    vals = {"Name": name, "BonusType": btype, "Bonus": amount, "BonusIndex": index}
    out, done = [], set()
    for t, v, isx in (old or ()):
        if t in vals and not isx:
            done.add(t)
            if vals[t] != "" or t in ("Name", "BonusIndex"):
                out.append((t, vals[t], False))
        else:
            out.append((t, v, isx))
    for t in ("Name", "BonusType", "Bonus", "BonusIndex"):
        if t not in done and vals[t] != "":
            out.append((t, vals[t], False))
    return tuple(out)


def bonus_summary(b):
    n, ty, a = bonus_get(b, "Name"), bonus_get(b, "BonusType"), bonus_get(b, "Bonus")
    return "%s%s%s" % (n or ty or "(unnamed)", (" [%s]" % ty) if ty and n else "", (" = %s" % a) if a != "" else "")


