def bonus_category(name, info=""):
    """Which group an upgrade belongs to in the Upgrades tab (a guess from its name, then from what it does)."""
    for text in (name.lower(), (info or "").lower()):
        for cat, words in BONUS_CATS:
            if any(w in text for w in words):
                return cat
    return "Other"


BONUS_TAG_NOTE = ("An upgrade is one <UnlockedBonus> inside the tech's <BonusUnlocked>: Name (shown to the player), BonusType (what it changes - the list below), "
                  "Bonus (the amount; 0.1 = 10%), Tags (only for Weapon_* and ShipRoleLevels: which weapon types / ship roles), Type (who gets it: a race "
                  "trait name such as a race key, empty = everybody), BonusIndex (GameText id of its description). The tech's MaxLevel and "
                  "MultiLevelCostMultiplier (Details tab) make it repeatable: the bonus is applied once per level.")


def scan_bonus_usage(proj):
    """{upgrade key: {'src': {source label: count}, 'amt': [amounts]}} over this mod (live), BB+ and every other mod's Technology files."""
    use = {}

    def add(key, label, amount):
        if key:
            u = use.setdefault(key, {"src": {}, "amt": []})
            u["src"][label] = u["src"].get(label, 0) + 1
            if amount and amount not in u["amt"] and len(u["amt"]) < 4:
                u["amt"].append(amount)
    for t in proj.techs:
        for b in t.bonuses:
            add(bonus_get(b, "BonusType") or bonus_get(b, "Name"), "This mod", bonus_get(b, "Bonus"))
    for label, top in proj.library_sources():
        if label == "This mod":
            continue
        td = next((x for x in top.iterdir() if x.is_dir() and x.name.lower() == "technology"), None) if top.is_dir() else None
        if td is None:
            continue
        for f in td.rglob("*.xml"):
            try:
                txt = f.read_text(encoding="utf-8-sig", errors="ignore")
            except OSError:
                continue
            for blk in re.findall(r"<UnlockedBonus>(.*?)</UnlockedBonus>", txt, re.S):
                g = lambda tag: (re.search("<%s>(.*?)</%s>" % (tag, tag), blk, re.S) or [None, ""])[1].strip()
                add(g("BonusType") or g("Name"), label, g("Bonus"))
    return use


class TechDoc(XmlDoc):
    """A Technology xml = one node of the research tree. Besides the flat fields (Cost, NameIndex ...) it edits the two
    lists the tree is made of: LeadsTo (follow-on techs) and ModulesUnlocked (module + race). Everything else in the
    file is left exactly as it was."""

    def __init__(self, path, root, text=None, bom=False, enc="utf-8"):
        super().__init__(path, root, text, bom, enc)
        self.new = text is not None                 # not on disk yet
        body = re.sub(r"^\s*<\?xml[^>]*\?>", "", self.text, count=1)
        el = ET.fromstring(body)
        if el.tag != "Technology":
            raise ValueError("not a Technology file")
        leads, unl = [], []
        for lt in el.findall("LeadsTo"):
            for x in lt.findall("LeadsToTech"):
                u = (x.findtext("UID") or "").strip()
                if u and u not in leads:
                    leads.append(u)
        for um in el.findall("ModulesUnlocked"):
            for x in um.findall("UnlockedMod"):
                mu = (x.findtext("ModuleUID") or "").strip()
                if mu:
                    unl.append((mu, (x.findtext("Type") or "").strip()))
        self.orig_leads, self.leads = list(leads), list(leads)
        self.orig_unlocks, self.unlocks = list(unl), list(unl)
        bon = []                                    # upgrades: each is a tuple of (tag, value, is_xml) - unknown parts are kept as they were
        for bu in el.findall("BonusUnlocked"):
            for x in bu.findall("UnlockedBonus"):
                bon.append(tuple((c.tag, (ET.tostring(c, encoding="unicode").strip() if len(c) else (c.text or "").strip()), len(c) > 0) for c in x))
        self.orig_bonuses, self.bonuses = list(bon), list(bon)
        bld = []                                    # BuildingsUnlocked > UnlockedBuilding > Name
        for bu in el.findall("BuildingsUnlocked"):
            for x in bu.findall("UnlockedBuilding"):
                n = (x.findtext("Name") or "").strip()
                if n and n not in bld:
                    bld.append(n)
        self.orig_buildings, self.buildings = list(bld), list(bld)
        self.root_dir, self.orig_path = Path(root), self.path          # a tech can be moved to another Technology folder
        self.troops = [((x.findtext("Name") or "").strip(), (x.findtext("Type") or "").strip()) for tu in el.findall("TroopsUnlocked")
                       for x in tu.findall("UnlockedTroop") if (x.findtext("Name") or "").strip()]      # troops this tech unlocks (name, race type)
        self.orig_troops = list(self.troops)
        self.hulls = [(x.findtext("Name") or "").strip() for hu in el.findall("HullsUnlocked") for x in hu.findall("UnlockedHull")
                      if (x.findtext("Name") or "").strip()]            # ships this tech unlocks
        self.orig_hulls = list(self.hulls)
        # each unlocked hull carries <ShipType> = the race that gets it. It MUST be written back, or the hull unlocks for every race.
        self.hull_type = {(x.findtext("Name") or "").strip().lower(): (x.findtext("ShipType") or "").strip() for hu in el.findall("HullsUnlocked")
                          for x in hu.findall("UnlockedHull") if (x.findtext("Name") or "").strip() and (x.findtext("ShipType") or "").strip()}
        self.orig_hull_type = dict(self.hull_type)

    @property
    def uid(self):
        return (self.get("UID") or self.path.stem).strip()

    @property
    def root_node(self):
        """RootNode >= 1 marks the head of a line of research: its position in the game's list of research lines (0 = ordinary tech)."""
        v = self.get("RootNode").strip()
        return int(v) if v.isdigit() else 0

    def moved(self):
        return self.path != self.orig_path

    @property
    def max_level(self):
        v = self.get("MaxLevel").strip()
        return int(v) if v.isdigit() else 1

    def move_to(self, folder):
        """Put this tech's file in Technology\\<folder> (done when you Save; the old file is backed up, then removed)."""
        tech = self.orig_path.parent
        while tech.name.lower() != "technology" and tech.parent != tech:
            tech = tech.parent
        self.path = tech / folder / self.orig_path.name
        self.rel = self.path.relative_to(self.root_dir)

    def struct_changed(self):
        return self.leads != self.orig_leads or self.unlocks != self.orig_unlocks or self.bonuses != self.orig_bonuses or self.buildings != self.orig_buildings or self.troops != self.orig_troops or self.hulls != self.orig_hulls or self.types_changed() or self.moved()

    def types_changed(self):
        return any(self.hull_type.get(n.lower(), "") != self.orig_hull_type.get(n.lower(), "") for n in self.hulls)

    def revert_struct(self):
        self.leads, self.unlocks = list(self.orig_leads), list(self.orig_unlocks)
        self.bonuses = list(self.orig_bonuses)
        self.buildings = list(self.orig_buildings)
        self.hulls = list(self.orig_hulls)
        self.troops = list(self.orig_troops)
        self.hull_type = dict(self.orig_hull_type)
        self.path = self.orig_path
        self.rel = self.path.relative_to(self.root_dir)

    def has_changes(self):
        return self.new or self.struct_changed() or super().has_changes()

    def flat_changes(self):
        return FieldDoc.changes(self)

    def changes(self):
        out = FieldDoc.changes(self)
        if self.new:
            out.append(("NEW FILE", "", str(self.rel)))
        if self.moved():
            out.append(("MOVED TO", str(self.orig_path.relative_to(self.root_dir)), str(self.rel)))
        if self.leads != self.orig_leads:
            out.append(("LeadsTo", ", ".join(self.orig_leads), ", ".join(self.leads)))
        if self.unlocks != self.orig_unlocks:
            f = lambda L: ", ".join("%s%s" % (m, (" [%s]" % t) if t else "") for m, t in L)
            out.append(("ModulesUnlocked", f(self.orig_unlocks), f(self.unlocks)))
        if self.buildings != self.orig_buildings:
            out.append(("BuildingsUnlocked", ", ".join(self.orig_buildings), ", ".join(self.buildings)))
        if self.hulls != self.orig_hulls:
            out.append(("HullsUnlocked", ", ".join(self.orig_hulls), ", ".join(self.hulls)))
        elif self.types_changed():
            k = sum(1 for n in self.hulls if self.hull_type.get(n.lower(), "") != self.orig_hull_type.get(n.lower(), ""))
            out.append(("HullsUnlocked ShipType", "", "restored on %d unlocked hull(s)" % k))
        if self.troops != self.orig_troops:
            f = lambda L: ", ".join("%s [%s]" % (n, t) for n, t in L)
            out.append(("TroopsUnlocked", f(self.orig_troops), f(self.troops)))
        if self.bonuses != self.orig_bonuses:
            out.append(("BonusUnlocked", "; ".join(bonus_summary(b) for b in self.orig_bonuses), "; ".join(bonus_summary(b) for b in self.bonuses)))
        return out

    def mark_saved(self, text):
        super().mark_saved(text)
        self.orig_leads, self.orig_unlocks = list(self.leads), list(self.unlocks)
        self.orig_bonuses = list(self.bonuses)
        self.orig_buildings = list(self.buildings)
        self.orig_hulls = list(self.hulls)
        self.orig_troops = list(self.troops)
        wt = {}                                              # the types as written to the file (a hull added this session keeps its type)
        for mm in re.finditer(r"<UnlockedHull>(.*?)</UnlockedHull>", text, re.S):
            nm = re.search(r"<Name>(.*?)</Name>", mm.group(1))
            ty = re.search(r"<ShipType>(.*?)</ShipType>", mm.group(1))
            if nm and ty and nm.group(1).strip() and ty.group(1).strip():
                wt[nm.group(1).strip().lower()] = ty.group(1).strip()
        self.hull_type = wt
        self.orig_hull_type = dict(wt)
        self.orig_path = self.path
        self.new = False

    # ---- writing the two lists back
    def _leads_xml(self, nl):
        if not self.leads:
            return ""
        out = ["  <LeadsTo>"]
        for u in self.leads:
            out += ["    <LeadsToTech>", "      <UID>%s</UID>" % xml_escape(u), "    </LeadsToTech>"]
        out.append("  </LeadsTo>")
        return nl.join(out)

    def _unlocks_xml(self, nl):
        if not self.unlocks:
            return "  <ModulesUnlocked />"
        out = ["  <ModulesUnlocked>"]
        for m, t in self.unlocks:
            out += ["    <UnlockedMod>", "      <ModuleUID>%s</ModuleUID>" % xml_escape(m)]
            if t:
                out.append("      <Type>%s</Type>" % xml_escape(t))
            out.append("    </UnlockedMod>")
        out.append("  </ModulesUnlocked>")
        return nl.join(out)

    def _buildings_xml(self, nl):
        if not self.buildings:
            return "  <BuildingsUnlocked />"
        out = ["  <BuildingsUnlocked>"]
        for n in self.buildings:
            out += ["    <UnlockedBuilding>", "      <Name>%s</Name>" % xml_escape(n), "    </UnlockedBuilding>"]
        out.append("  </BuildingsUnlocked>")
        return nl.join(out)

    def _troops_xml(self, nl):
        if not self.troops:
            return "  <TroopsUnlocked />"
        out = ["  <TroopsUnlocked>"]
        for n, t in self.troops:
            out += ["    <UnlockedTroop>", "      <Name>%s</Name>" % xml_escape(n)]
            if t:
                out.append("      <Type>%s</Type>" % xml_escape(t))
            out.append("    </UnlockedTroop>")
        out.append("  </TroopsUnlocked>")
        return nl.join(out)

    hull_style_of = None            # set by Project: hull name -> its Style, the ShipType a newly added hull is unlocked for

    def written_type(self, n):
        ty = self.hull_type.get(n.lower(), "")
        if not ty and n not in self.orig_hulls and TechDoc.hull_style_of is not None:
            try:
                ty = (TechDoc.hull_style_of(n) or "").strip()
            except Exception:
                ty = ""
        return ty

    def _hulls_xml(self, nl):
        if not self.hulls:
            return "  <HullsUnlocked />"
        out = ["  <HullsUnlocked>"]
        for n in self.hulls:
            out += ["    <UnlockedHull>", "      <Name>%s</Name>" % xml_escape(n)]
            ty = self.written_type(n)
            if ty:
                out.append("      <ShipType>%s</ShipType>" % xml_escape(ty))
            out.append("    </UnlockedHull>")
        out.append("  </HullsUnlocked>")
        return nl.join(out)

    def _bonuses_xml(self, nl):
        if not self.bonuses:
            return "  <BonusUnlocked />"
        out = ["  <BonusUnlocked>"]
        for b in self.bonuses:
            out.append("    <UnlockedBonus>")
            for tag, val, isx in b:
                out.append(("      " + val) if isx else "      <%s>%s</%s>" % (tag, xml_escape(val), tag))
            out.append("    </UnlockedBonus>")
        out.append("  </BonusUnlocked>")
        return nl.join(out)

    @staticmethod
    def _swap(text, tag, block, before, nl):
        """Replace every <tag> block in text by ONE block (or none when block is empty). With no <tag> yet the block goes in front
        of the first tag in `before`, else at the end of the root element."""
        spans = [m.span() for m in re.finditer(r"<!--.*?-->", text, re.S)]
        pat = re.compile(r"<%s(\s[^>]*?)?(?:/>|>(.*?)</%s\s*>)" % (tag, tag), re.S)
        found = [m for m in pat.finditer(text) if not any(a <= m.start() < b for a, b in spans)]

        def widen(a, b):                            # take the line's indentation and line break with the block
            ls = text.rfind("\n", 0, a) + 1
            if text[ls:a].strip() == "":
                a = ls
            e = b
            while e < len(text) and text[e] in " \t":
                e += 1
            if text.startswith("\r\n", e):
                e += 2
            elif text.startswith("\n", e):
                e += 1
            return a, e
        if found:
            for k, m in reversed(list(enumerate(found))):
                a, e = widen(*m.span())
                text = text[:a] + ((block + nl) if (k == 0 and block) else "") + text[e:]
            return text
        if not block:
            return text
        for b in before:
            m = XmlDoc._find(text, b)
            if m:
                ls = text.rfind("\n", 0, m.start()) + 1
                at = ls if text[ls:m.start()].strip() == "" else m.start()
                return text[:at] + block + nl + text[at:]
        i = text.rfind("</Technology")
        pre = "" if text[:i].endswith("\n") else nl
        return text[:i] + pre + block + nl + text[i:]

    def render(self):
        saved = self.text
        try:
            fresh = [c[0] for c in self.flat_changes() if c[0] in ("MultiLevelCostMultiplier", "MaxLevel") and not self._find(self.text, c[0])]
            m = self._find(self.text, "Cost") if fresh else None
            if m:                                   # repeatable-upgrade tags sit right after Cost, as in the game's own files
                nl0 = "\r\n" if "\r\n" in self.text else "\n"
                self.text = self.text[:m.end()] + "".join("%s  <%s></%s>" % (nl0, t, t) for t in fresh) + self.text[m.end():]
            text = super().render()
        finally:
            self.text = saved
        nl = "\r\n" if "\r\n" in text else "\n"
        if self.leads != self.orig_leads:
            text = self._swap(text, "LeadsTo", self._leads_xml(nl), ("ModulesUnlocked", "BuildingsUnlocked"), nl)
        if self.unlocks != self.orig_unlocks:
            text = self._swap(text, "ModulesUnlocked", self._unlocks_xml(nl), ("BuildingsUnlocked", "BonusUnlocked"), nl)
        if self.buildings != self.orig_buildings:
            text = self._swap(text, "BuildingsUnlocked", self._buildings_xml(nl), ("BonusUnlocked", "TroopsUnlocked"), nl)
        if self.bonuses != self.orig_bonuses:
            text = self._swap(text, "BonusUnlocked", self._bonuses_xml(nl), ("TroopsUnlocked", "HullsUnlocked"), nl)
        if self.troops != self.orig_troops:
            text = self._swap(text, "TroopsUnlocked", self._troops_xml(nl), ("HullsUnlocked",), nl)
        if self.hulls != self.orig_hulls or self.types_changed():
            text = self._swap(text, "HullsUnlocked", self._hulls_xml(nl), ("TroopsUnlocked",), nl)
        return text


HULL_ROLES = ("fighter", "frigate", "destroyer", "cruiser", "battleship", "capital", "carrier", "freighter", "platform", "station")


class GameDoc(FieldDoc):
    """A race (EmpireData), troop (Troop) or solar system (SolarSystemData) xml file. Every single-valued tag is a field named by its
    path ('PortraitName', 'Traits/HomeworldName'); repeated blocks are lists (trait weights, trait sets, the rings of a system). Only what
    you change is written back into the file text; comments and the rest of the layout stay."""
    vanilla, deleted = False, False
    ROOTS = {"EmpireData": "races", "Troop": "troops", "SolarSystemData": "systems"}
    LISTS = {"EmpireData": (("personality", "PersonalityTraitsWeights", "string"), ("economic", "EconomicTraitsWeights", "string")),
             "Troop": (), "SolarSystemData": (("rings", "RingList", "Ring"),)}

    def __init__(self, path, root, text=None, bom=False, enc="utf-8"):
        super().__init__()
        self.path = Path(path)
        self.rel = self.path.relative_to(root)
        if text is None:
            self.text, self.bom, self.enc = read_file(self.path)
        else:
            self.text, self.bom, self.enc = text, bom, enc
        self.new = text is not None
        self.nested, self.removed_tags = set(), set()
        body = re.sub(r"^\s*<\?xml[^>]*\?>", "", self.text, count=1)
        el = ET.fromstring(body)
        self.root_tag = el.tag
        if el.tag not in self.ROOTS:
            raise ValueError("not a race, troop or solar system file (<%s>)" % el.tag)
        self.kind = self.ROOTS[el.tag]
        self.lists, self.cpaths = {}, {}              # key -> list of items ; key -> path of the container element
        for key, cont, item in self.LISTS[el.tag]:
            self.cpaths[key] = (cont, item)
            c = el.find(cont)
            self.lists[key] = self._items(c, item) if c is not None else []
        if el.tag == "EmpireData":                    # one list per trait set: key 'traits0', 'traits1' ...
            for i, ts in enumerate(el.findall("Traits/TraitSets/TraitSet")):
                c = ts.find("TraitOptions")
                self.cpaths["traits%d" % i] = ("Traits/TraitSets/TraitSet[%d]/TraitOptions" % i, "string")
                self.lists["traits%d" % i] = self._items(c, "string") if c is not None else []
        skip = {cont for _k, cont, _i in self.LISTS[el.tag]}
        self._walk(el, "", skip)
        self.orig_lists = {k: list(v) for k, v in self.lists.items()}
        self.cur, self.base = dict(self.orig), dict(self.orig)

    @staticmethod
    def _items(c, item):
        out = []
        for ch in c.findall(item):
            if len(ch):
                out.append(tuple((g.tag, (g.text or "").strip() if len(g) == 0 else "") for g in ch if isinstance(g.tag, str)))
            else:
                out.append((ch.text or "").strip())
        return out

    def _walk(self, el, prefix, skip):
        tags = [c.tag for c in el if isinstance(c.tag, str)]
        for ch in el:
            if not isinstance(ch.tag, str):
                continue
            path = prefix + ch.tag
            if path in skip or tags.count(ch.tag) > 1 or ch.tag == "TraitSets":
                continue
            if len(ch):
                self._walk(ch, path + "/", skip)
            else:
                self.orig[path] = ch.text or ""

    # ---- locating elements in the raw text
    @staticmethod
    def _spans(text):
        return [m.span() for m in re.finditer(r"<!--.*?-->", text, re.S)]

    @classmethod
    def _find_el(cls, text, tag, a, b, idx=0):
        """Span info of the idx-th <tag> inside text[a:b] (comments skipped): (start, end, inner_start, inner_end, attrs) or None."""
        spans = cls._spans(text)
        pat = re.compile(r"<%s(\s[^>]*?)?(?:/>|>(.*?)</%s\s*>)" % (re.escape(tag), re.escape(tag)), re.S)
        n = 0
        for m in pat.finditer(text, a, b):
            if any(x <= m.start() < y for x, y in spans):
                continue
            if n == idx:
                if m.group(2) is None:
                    return m.start(), m.end(), None, None, m.group(1) or ""
                return m.start(), m.end(), m.start(2), m.end(2), m.group(1) or ""
            n += 1
        return None

    @classmethod
    def locate(cls, text, path):
        a, b, hit = 0, len(text), None
        for seg in path.split("/"):
            m = re.fullmatch(r"(\w+)\[(\d+)\]", seg)
            tag, idx = (m.group(1), int(m.group(2))) if m else (seg, 0)
            hit = cls._find_el(text, tag, a, b, idx)
            if hit is None:
                return None
            if hit[2] is None:
                a = b = hit[1]
            else:
                a, b = hit[2], hit[3]
        return hit

    def has_changes(self):
        return self.new or FieldDoc.has_changes(self) or self.lists_changed()

    def lists_changed(self):
        return self.lists != self.orig_lists

    def edited(self):
        return FieldDoc.has_changes(self) or self.lists_changed()

    def revert_lists(self):
        self.lists = {k: list(v) for k, v in self.orig_lists.items()}

    def changes(self):
        out = FieldDoc.changes(self)
        for k in self.lists:
            if self.lists[k] != self.orig_lists.get(k):
                out.append((k, "%d entries" % len(self.orig_lists.get(k, ())), "%d entries" % len(self.lists[k])))
        if self.new:
            out.append(("NEW FILE", "", str(self.rel)))
        return out

    def render(self):
        text = self.text
        nl = "\r\n" if "\r\n" in text else "\n"
        for tag, _old, new in FieldDoc.changes(self):
            if tag in self.removed_tags and tag not in self.cur:
                continue
            val = xml_escape(new).replace("\r\n", "\n").replace("\n", nl)
            hit = self.locate(text, tag)
            if hit:
                text = text[:hit[0]] + "<%s%s>%s</%s>" % (tag.rsplit("/", 1)[-1], hit[4], val, tag.rsplit("/", 1)[-1]) + text[hit[1]:]
            else:
                text = self._insert(text, tag.rsplit("/", 1)[0] if "/" in tag else "", tag.rsplit("/", 1)[-1],
                                    "<%s>%s</%s>" % (tag.rsplit("/", 1)[-1], val, tag.rsplit("/", 1)[-1]), nl)
        for k in self.lists:
            if self.lists[k] == self.orig_lists.get(k) or k not in self.cpaths:
                continue
            cont, item = self.cpaths[k]
            text = self._set_list(text, cont, item, self.lists[k], nl)
        return text

    def _insert(self, text, parent, tag, xml, nl):
        """Add <tag> as the last child of `parent` ('' = the root element)."""
        if parent:
            hit = self.locate(text, parent)
            if hit is None:
                pn = re.sub(r"\[\d+\]$", "", parent.rsplit("/", 1)[-1])
                return self._insert(text, parent.rsplit("/", 1)[0] if "/" in parent else "", pn, "<%s>%s</%s>" % (pn, xml, pn), nl)
            if hit[2] is None:                               # <Parent/>
                return text[:hit[0]] + "<%s>%s</%s>" % (parent.rsplit("/", 1)[-1], xml, parent.rsplit("/", 1)[-1]) + text[hit[1]:]
            at, ind = hit[3], self._indent(text, hit[0]) + "  "
            inner = text[hit[2]:hit[3]]
            tail = inner[len(inner.rstrip()):] if inner.strip() else nl + self._indent(text, hit[0])
            return text[:hit[2]] + inner.rstrip() + nl + ind + xml + tail + text[hit[3]:]
        i = text.rfind("</%s" % self.root_tag)
        pre = "" if text[:i].endswith(("\n", "\r\n")) else nl
        return text[:i] + pre + "  " + xml + nl + text[i:]

    @staticmethod
    def _indent(text, pos):
        ls = text.rfind("\n", 0, pos) + 1
        m = re.match(r"[ \t]*", text[ls:pos + 1])
        return m.group(0) if m else ""

    def _set_list(self, text, cont, item, items, nl):
        hit = self.locate(text, cont)
        name = re.sub(r"\[\d+\]$", "", cont.rsplit("/", 1)[-1])
        base_ind = self._indent(text, hit[0]) if hit else "  "
        ind = base_ind + "  "

        def one(it):
            if isinstance(it, tuple):
                kids = "".join("%s%s<%s>%s</%s>%s" % (ind, "  ", t, xml_escape(v), t, nl) for t, v in it)
                return "%s<%s>%s%s%s</%s>" % (ind, item, nl, kids, ind, item)
            return "%s<%s>%s</%s>" % (ind, item, xml_escape(it), item)
        inner = (nl + nl.join(one(i) for i in items) + nl + base_ind) if items else ""
        if hit is None:
            return self._insert(text, cont.rsplit("/", 1)[0] if "/" in cont else "", name, "<%s>%s</%s>" % (name, inner, name), nl)
        if hit[2] is None:
            return text[:hit[0]] + "<%s%s>%s</%s>" % (name, hit[4], inner, name) + text[hit[1]:]
        return text[:hit[2]] + inner + text[hit[3]:]

    def encode(self, text):
        return encode(text, self.bom, self.enc)

    def mark_saved(self, text):
        self.text = text
        self.orig = dict(self.cur)
        self.orig_lists = {k: list(v) for k, v in self.lists.items()}
        self.new = False

    # ---- convenience
    def name(self):
        return self.get("Traits/Name") or self.get("Name") or self.get("Traits/Singular") or self.path.stem


