# how the game words a trait value: "pct" 0.25 -> +25%, "mult" 1.5 -> +50% (1 = normal), "pts" 0.2 -> +20 out of 100
TRAIT_PCT = {"ConsumptionModifier": "food use", "GroundCombatModifier": "ground combat", "ResearchMod": "research", "TargetingModifier": "weapon accuracy",
             "DodgeMod": "dodge", "ProductionMod": "production", "MaintMod": "upkeep cost", "TaxMod": "tax income", "ModHpModifier": "module hit points",
             "ResearchBenefitFromAlliance": "research from allies", "ShipCostMod": "ship cost", "HomeworldSizeMod": "homeworld size",
             "RepairMod": "repair speed", "HomeworldFertMod": "homeworld fertility", "HomeworldRichMod": "homeworld richness"}
TRAIT_MULT = {"ConstructionRateMultiplier": "construction speed", "EnvTerranMultiplier": "Terran planets", "EnvOceanicMultiplier": "Oceanic planets",
              "EnvSteppeMultiplier": "Steppe planets", "EnvTundraMultiplier": "Tundra planets", "EnvSwampMultiplier": "Swamp planets",
              "EnvDesertMultiplier": "Desert planets", "EnvIceMultiplier": "Ice planets", "ExploreDistanceMultiplier": "exploration range"}


def trait_effect_text(tag, val):
    """What a trait effect value means in the game's own terms (percent etc.), or '' when there is nothing sensible to say."""
    try:
        v = float(str(val).strip())
    except ValueError:
        return ""
    sg = lambda x: ("+" if x > 0 else "") + ("%d" % round(x) if abs(x - round(x)) < 1e-9 else ("%.1f" % x).rstrip("0").rstrip("."))
    if tag in TRAIT_PCT:
        return "= %s%% %s" % (sg(v * 100), TRAIT_PCT[tag])
    if tag in TRAIT_MULT:
        return "= %s%% %s  (1 = normal)" % (sg((v - 1) * 100), TRAIT_MULT[tag])
    if tag == "DiplomacyMod":
        return "= %s (out of 100) starting relationship" % sg(v * 100)
    if tag in ("PopGrowthMin", "PopGrowthMax"):
        return "= %s million people per turn (the game text shows %s)" % (sg(v * 1000), sg(v * 10))
    if tag in ("CreditsPerKilledSlot", "PenaltyPerKilledSlot"):
        return "= %s%%" % sg(v * 100)
    return ""

TRAIT_CORE = ("TraitName", "TraitIndex", "Category", "Cost", "Description", "Excludes")


def trait_describe(name, it):
    """A description for a trait written from its effect tags, in the game's wording: 'Savage races gain +30% ground combat ...'."""
    INV = ("ConsumptionModifier", "MaintMod", "ShipCostMod")            # for these a rise is the bad direction
    gain, have, suffer = [], [], []
    for tag, v in it:
        if tag in TRAIT_CORE:
            continue
        t = trait_effect_text(tag, v)
        if not t:
            if tag in ("Militaristic", "Mercantile", "Spiritual", "Cybernetic", "Pack", "Aquatic", "Prototype") and str(v).strip() not in ("", "0"):
                have.append("a %s nature" % tag.lower())
            continue
        t = t[2:].split("  (")[0].replace("starting relationship", "starting relationship with other races")
        mm = re.match(r"([-+]?)([\d.]+)%\s+(.*)$", t)
        up = not t.startswith("-")
        if mm and tag in INV:
            (suffer if up else have).append("%s%% %s %s" % (mm.group(2), "more" if up else "less", mm.group(3)))
        elif mm:
            (gain if up else suffer).append("+%s%% %s" % (mm.group(2), mm.group(3)) if up else "a %s%% penalty to %s" % (mm.group(2), mm.group(3)))
        else:
            (gain if up else suffer).append(t if up else "a %s penalty" % t)
    base = (name or "This trait").strip()
    parts = []
    if gain:
        parts.append("%s races gain %s" % (base, ", ".join(gain)))
    if have:
        parts.append(("%s races have %s" % (base, " and ".join(have))) if not parts else "have %s" % " and ".join(have))
    if suffer:
        parts.append(("%s races suffer %s" % (base, ", ".join(suffer))) if not parts else "suffer %s" % ", ".join(suffer))
    if not parts:
        return "%s races have no special effects." % base
    txt = parts[0]
    if len(parts) > 1:
        txt += (", but " if suffer and not have else ", and ").join([""] + parts[1:])[0:0] if False else ""
        txt = parts[0] + "".join((", but " if p.startswith("suffer") else ", and ") + p for p in parts[1:])
    return txt + "."


def trait_get(it, tag, default=""):
    for t, v in it:
        if t == tag:
            return v
    return default


def trait_set(it, tag, val):
    """A copy of the trait item with `tag` set (added at the end if it was not there). Excludes values are tuples of names."""
    out, done = [], False
    for t, v in it:
        if t == tag:
            if not done:
                out.append((t, val))
            done = True
        else:
            out.append((t, v))
    if not done:
        out.append((tag, val))
    return tuple(out)


def trait_drop(it, tag):
    return tuple((t, v) for t, v in it if t != tag)


def trait_item_xml(it, nl):
    nm = trait_get(it, "TraitName")
    out = ["  <RacialTraitOption>", "    <!-- %s -->" % nm.replace("--", "-")]
    for tag, val in it:
        if tag == "Excludes":
            if val:
                out += ["    <Excludes>"] + ["      <string>%s</string>" % xml_escape(x) for x in val] + ["    </Excludes>"]
        else:
            out.append("    <%s>%s</%s>" % (tag, xml_escape(val), tag))
    out.append("  </RacialTraitOption>")
    return nl.join(out)


class TraitsDoc(GameDoc):
    """RacialTraits.xml: one <RacialTraitOption> per trait. Each trait is a tuple of (tag, value) pairs (Excludes holds a tuple of names).
    A trait you did not touch is written back exactly as it was (comments and all); changed and new traits are written fresh."""
    root_tag = "RacialTraits"

    def __init__(self, path, root, text=None, bom=False, enc="utf-8"):
        FieldDoc.__init__(self)
        self.path = Path(path)
        self.rel = self.path.relative_to(root)
        if text is None:
            self.text, self.bom, self.enc = read_file(self.path)
        else:
            self.text, self.bom, self.enc = text, bom, enc
        self.new = text is not None
        self.nested, self.removed_tags = set(), set()
        self.kind = "traits"
        self.cpaths = {"traits": ("TraitList", "RacialTraitOption")}
        self._index()
        self.orig_lists = {k: list(v) for k, v in self.lists.items()}

    @staticmethod
    def item_of(o):
        out = []
        for c in o:
            if not isinstance(c.tag, str):
                continue
            if c.tag == "Excludes":
                out.append(("Excludes", tuple((x.text or "").strip() for x in c if isinstance(x.tag, str) and (x.text or "").strip())))
            elif len(c) == 0:
                out.append((c.tag, (c.text or "").strip()))
        return tuple(out)

    def _index(self):
        body = re.sub(r"^\s*<\?xml[^>]*\?>", "", self.text, count=1)
        el = ET.fromstring(body)
        if el.tag != "RacialTraits":
            raise ValueError("not a racial traits file (<%s>)" % el.tag)
        c = el.find("TraitList")
        items = [self.item_of(o) for o in (c.findall("RacialTraitOption") if c is not None else [])]
        self.lists = {"traits": items}
        self.raw = {}
        hit = self.locate(self.text, "TraitList")
        if hit and hit[2] is not None:
            for i, it in enumerate(items):
                h = self._find_el(self.text, "RacialTraitOption", hit[2], hit[3], i)
                if h:
                    self.raw.setdefault(it, self.text[h[0]:h[1]])

    def render(self):
        text = self.text
        if self.lists == self.orig_lists:
            return text
        nl = "\r\n" if "\r\n" in text else "\n"
        parts = [("  " + self.raw[it]) if it in self.raw else trait_item_xml(it, nl) for it in self.lists["traits"]]
        inner = (nl + nl.join(parts) + nl + "  ") if parts else nl + "  "
        hit = self.locate(text, "TraitList")
        if hit is None:
            return self._insert(text, "", "TraitList", "<TraitList>%s</TraitList>" % inner, nl)
        if hit[2] is None:
            return text[:hit[0]] + "<TraitList>%s</TraitList>" % inner + text[hit[1]:]
        return text[:hit[2]] + inner + text[hit[3]:]

    def mark_saved(self, text):
        self.text = text
        self._index()
        self.orig_lists = {k: list(v) for k, v in self.lists.items()}
        self.new = False

    def changes(self):
        old = {trait_get(i, "TraitName"): i for i in self.orig_lists.get("traits", ())}
        new = {trait_get(i, "TraitName"): i for i in self.lists["traits"]}
        out = []
        for n, it in new.items():
            if n not in old:
                out.append((n, "", "NEW trait"))
            elif old[n] != it:
                a, b = dict(old[n]), dict(it)
                diff = ["%s: %s -> %s" % (k, a.get(k, "(none)"), b.get(k, "(none)")) for k in list(b) + [x for x in a if x not in b] if a.get(k) != b.get(k)]
                out.append((n, "", "; ".join(str(x) for x in diff)[:200]))
        for n in old:
            if n not in new:
                out.append((n, "trait", "(removed)"))
        if [trait_get(i, "TraitName") for i in self.lists["traits"] if trait_get(i, "TraitName") in old] != [n for n in old if n in new] and not out:
            out.append(("order", "", "changed"))
        if self.new:
            out.append(("NEW FILE", "", str(self.rel)))
        return out

    def name(self):
        return "Racial traits"


def open_gdoc(path, root, text=None, bom=False, enc="utf-8"):
    """A GameDoc for a race / troop / system file, or a TraitsDoc for RacialTraits.xml."""
    head = text if text is not None else read_file(path)[0]
    h = head[:2000]
    cls = (TraitsDoc if re.search(r"<RacialTraits[\s>/]", h) else EventDoc if re.search(r"<ExplorationEvent[\s>/]", h)
           else EncounterDoc if re.search(r"<Encounter[\s>/]", h)
           else DialogueDoc if re.search(r"<DiplomacyDialog[\s>/]", h) else GameDoc)
    return cls(path, root, text=text, bom=bom, enc=enc)


class DesignDoc(FieldDoc):
    """Edits to one mod .design file. Only the Hull=, ModuleUIDs=, Role=, Style= and Name= lines are ever rewritten (by the Debug auto-fixes or the
    Designs tab); everything else in the file stays byte for byte. Staged like every other change: written, with a backup, when you Save."""
    vanilla, kind, new, deleted = False, "designs", False, False

    def __init__(self, path, root):
        super().__init__()
        self.path, self.root_dir = Path(path), Path(root)
        self.orig_path = self.path                          # the file may be renamed (Debug auto-fix): written under the new name on Save
        self.rel = self.path.relative_to(root)
        self.text, self.bom, self.enc = read_file(self.path)
        self.nested, self.removed_tags, self.root_tag = set(), set(), "Design"
        for ln in self.text.splitlines():
            m = re.match(r"^\s*(Hull|ModuleUIDs|Role|Style|Name)=(.*)$", ln.lstrip("\ufeff"))
            if m and m.group(1) not in self.orig:
                self.orig[m.group(1)] = m.group(2) if m.group(1) == "Name" else m.group(2).strip()
        self.cur, self.base = dict(self.orig), dict(self.orig)

    def render(self):
        nl = "\r\n" if "\r\n" in self.text else "\n"
        out, done = [], set()
        missing = [k for k in ("Role", "Style") if k in self.cur and k not in self.orig]
        for ln in self.text.splitlines():
            m = re.match(r"^(\s*)(Hull|ModuleUIDs|Role|Style|Name)=(.*)$", ln)
            if m and m.group(2) in self.orig and m.group(2) not in done:
                k = m.group(2)
                done.add(k)
                out.append(ln if self.cur.get(k) == self.orig.get(k) else "%s%s=%s" % (m.group(1), k, self.cur.get(k, "")))
            else:
                out.append(ln)
            if m and m.group(2) == "Hull" and missing:      # a Role / Style line the file did not have yet
                out += ["%s=%s" % (k, self.cur[k]) for k in missing]
                missing = []
        return nl.join(out) + (nl if self.text.endswith("\n") else "")

    def encode(self, text):
        return encode(text, self.bom, self.enc)

    def mark_saved(self, text):
        self.text = text
        self.orig = dict(self.cur)
        self.orig_path = self.path

    def has_changes(self):
        return FieldDoc.has_changes(self) or self.path != self.orig_path

    def changes(self):
        out = FieldDoc.changes(self)
        if self.path != self.orig_path:
            out.insert(0, ("RENAMED FILE", self.orig_path.name, self.path.name))
        return out

    def rename_file(self, stem):
        """Give the file a new name (same folder, same extension); done when you Save."""
        self.path = self.orig_path.with_name(stem + self.orig_path.suffix)
        self.rel = self.path.relative_to(self.root_dir)


class GlobalsDoc(FieldDoc):
    """Globals.yaml: every simple 'Key: value' line is a field. Only the values you change are rewritten; comments and layout stay."""
    vanilla, kind, deleted = False, "globals", False
    LINE = re.compile(r"(?m)^(\s+)([A-Za-z_]\w*)(\s*:\s*)([^#\n]*?)(\s*(?:#.*)?)$")

    def __init__(self, path, root, text=None, bom=False, enc="utf-8"):
        super().__init__()
        self.path = Path(path)
        self.rel = self.path.relative_to(root)
        self.new = text is not None                       # the file is in the base game: the edited copy goes into the mod
        if text is None:
            self.text, self.bom, self.enc = read_file(self.path)
        else:
            self.text, self.bom, self.enc = text, bom, enc
        self.nested, self.removed_tags, self.root_tag = set(), set(), "Globals"
        for m in self.LINE.finditer(self.text):
            if m.group(4).strip():
                self.orig.setdefault(m.group(2), m.group(4).strip())
        self.cur, self.base = dict(self.orig), dict(self.orig)

    def has_changes(self):
        return FieldDoc.has_changes(self)

    def render(self):
        text = self.text
        for key, _old, new in FieldDoc.changes(self):
            rx = re.compile(r"(?m)^(\s+%s\s*:\s*)([^#\n]*?)(\s*(?:#.*)?)$" % re.escape(key))
            text = rx.sub(lambda m: m.group(1) + str(new).strip() + m.group(3), text, count=1)
        return text

    def encode(self, text):
        return encode(text, self.bom, self.enc)

    def mark_saved(self, text):
        self.text = text
        self.orig = dict(self.cur)
        self.new = False


class EncounterDoc(GameDoc):
    """One file of the Encounter Dialogs folder: what a pirate / minor faction says to the player, how much money it asks for and where each
    answer leads. Every value is a field named by its path (repeated Message / Response blocks are numbered: MessageList/Message[1]/Text)."""
    root_tag = ROOT = "Encounter"
    KIND_NAME = "encounters"

    def __init__(self, path, root, text=None, bom=False, enc="utf-8"):
        FieldDoc.__init__(self)
        self.path = Path(path)
        self.rel = self.path.relative_to(root)
        if text is None:
            self.text, self.bom, self.enc = read_file(self.path)
        else:
            self.text, self.bom, self.enc = text, bom, enc
        self.new = text is not None
        self.nested, self.removed_tags = set(), set()
        self.kind = self.KIND_NAME
        self.cpaths, self.lists, self.orig_lists = {}, {}, {}
        el = ET.fromstring(re.sub(r"^\s*<\?xml[^>]*\?>", "", self.text, count=1))
        if el.tag != self.ROOT:
            raise ValueError("not a %s file (<%s>)" % (self.ROOT, el.tag))

        def walk(e, prefix):
            kids = [c for c in e if isinstance(c.tag, str)]
            count, seen = {}, {}
            for c in kids:
                count[c.tag] = count.get(c.tag, 0) + 1
            for c in kids:
                i = seen.get(c.tag, 0)
                seen[c.tag] = i + 1
                path_ = prefix + c.tag + ("[%d]" % i if count[c.tag] > 1 else "")
                if len(c):
                    walk(c, path_ + "/")
                else:
                    self.orig[path_] = c.text or ""
        walk(el, "")
        self.cur, self.base = dict(self.orig), dict(self.orig)

    _TAG = re.compile(r"<!--.*?-->|<\?.*?\?>|<(/?)([A-Za-z_][\w.:\-]*)((?:[^>\"']|\"[^\"]*\"|'[^']*')*?)(/?)>", re.S)

    @classmethod
    def _children(cls, text, a, b):
        """Direct child elements of the text range: (tag, start, end, inner_start, inner_end, attrs)."""
        out, stack = [], []
        for m in cls._TAG.finditer(text, a, b):
            if m.group(2) is None:
                continue
            close, tag, attrs, selfc = m.groups()
            if close:
                if stack:
                    t, s0, ins, at = stack.pop()
                    if not stack:
                        out.append((t, s0, m.end(), ins, m.start(), at))
            elif selfc:
                if not stack:
                    out.append((tag, m.start(), m.end(), None, None, attrs))
            else:
                stack.append((tag, m.start(), m.end(), attrs))
        return out

    @classmethod
    def _find_el(cls, text, tag, a, b, idx=0):
        kids = [c for c in cls._children(text, a, b) if c[0] == tag]
        if idx >= len(kids):
            return None
        _t, s0, e0, ins, ine, at = kids[idx]
        return s0, e0, ins, ine, at or ""

    @classmethod
    def locate(cls, text, path):
        root = cls._find_el(text, cls.ROOT, 0, len(text), 0)
        if root is None or root[2] is None:
            return None
        a, b, hit = root[2], root[3], None
        for seg in path.split("/"):
            m = re.fullmatch(r"(\w+)\[(\d+)\]", seg)
            tag, idx = (m.group(1), int(m.group(2))) if m else (seg, 0)
            hit = cls._find_el(text, tag, a, b, idx)
            if hit is None:
                return None
            if hit[2] is None:
                a = b = hit[1]
            else:
                a, b = hit[2], hit[3]
        return hit

    def add_block(self, parent, tag, fields):
        """Add a new repeated block <tag> (e.g. Message, Response, DialogLine) under `parent` with the given (sub path, value) fields.
        Returns its index (None when it is the only one). A lone un-numbered block is renumbered [0] first so the paths stay unique."""
        pre = parent + "/" + tag
        rx = re.compile(r"^" + re.escape(pre) + r"(?:\[(\d+)\])?(/.*)$")
        idxs, lone = set(), False
        for k in self.cur:
            m = rx.match(k)
            if m:
                if m.group(1) is None:
                    lone = True
                else:
                    idxs.add(int(m.group(1)))
        if lone and not idxs:
            for dct in (self.cur, self.orig, self.base):
                items = list(dct.items())
                dct.clear()
                for k, v in items:
                    m = rx.match(k)
                    dct[pre + "[0]" + m.group(2) if m and m.group(1) is None else k] = v
            idxs = {0}
        new = (max(idxs) + 1) if idxs else None
        for sub, val in fields:
            self.set(pre + ("[%d]" % new if new is not None else "") + "/" + sub, val)
        return new

    def faction(self):
        return self.get("Faction").strip()

    def name(self):
        return "%s: %s" % (self.get("Step").strip() or "?", self.get("Name").strip() or self.path.stem)

    def money(self):
        """(percent of treasury demanded or '', [credit amounts asked in the answers])."""
        pct = self.get("PercentMoneyDemanded").strip()
        amts = [v.strip() for k, v in self.cur.items() if k.endswith("MoneyToThem") and v.strip()]
        return pct, amts


class EventDoc(EncounterDoc):
    """An exploration event (Exploration Events\\*.xml): a name, optionally the Remnant story it belongs to and its step, and one or more outcomes
    (title, text, chance, rewards, ships and troops that appear ...). Values are fields named by path (PotentialOutcomes/Outcome[1]/TitleText);
    the lists of ships / troops that spawn are real lists, one per outcome, keyed 'o<n>/<Tag>'."""
    root_tag = ROOT = "ExplorationEvent"
    KIND_NAME = "events"
    LIST_TAGS = ("RemnantShipsToSpawn", "FriendlyShipsToSpawn", "PirateShipsToSpawn", "TroopsToSpawn")

    def __init__(self, path, root, text=None, bom=False, enc="utf-8"):
        EncounterDoc.__init__(self, path, root, text=text, bom=bom, enc=enc)
        el = ET.fromstring(re.sub(r"^\s*<\?xml[^>]*\?>", "", self.text, count=1))
        outs = el.findall("PotentialOutcomes/Outcome")
        self.nout = len(outs)
        self.lists, self.orig_lists, self.cpaths = {}, {}, {}
        for i, o in enumerate(outs):
            pre = self.opath(i)
            for tag in self.LIST_TAGS:
                for dct in (self.orig, self.cur, self.base):
                    for k in [k for k in dct if k == pre + "/" + tag or k.startswith(pre + "/" + tag + "/")]:
                        del dct[k]
                c = o.find(tag)
                if c is not None:
                    self.lists["o%d/%s" % (i, tag)] = [(x.text or "").strip() for x in c.findall("string")]
        self.orig_lists = {k: list(v) for k, v in self.lists.items()}
        self._sync()

    def opath(self, i):
        return "PotentialOutcomes/Outcome[%d]" % i if self.nout > 1 else "PotentialOutcomes/Outcome"

    def _sync(self):
        self.cpaths = {k: (self.opath(int(k[1:].split("/")[0])) + "/" + k.split("/", 1)[1], "string") for k in self.lists}

    def get_list(self, i, tag):
        return list(self.lists.get("o%d/%s" % (i, tag), []))

    def set_list(self, i, tag, items):
        k = "o%d/%s" % (i, tag)
        items = [x for x in (s_.strip() for s_ in items) if x]
        if items or k in self.orig_lists:
            self.lists[k] = items
        else:
            self.lists.pop(k, None)
        self._sync()

    def render(self):
        self._sync()
        return EncounterDoc.render(self)

    def add_outcome(self, fields):
        """A new outcome after the last one; returns its index. A lone outcome is renumbered [0] first (the paths must stay unique)."""
        self.add_block("PotentialOutcomes", "Outcome", fields)
        self.nout += 1
        self._sync()
        return self.nout - 1

    def story(self):
        return self.get("Story").strip()

    def step(self):
        v = self.get("StoryStep").strip()
        return int(v) if v.isdigit() else 0

    def name(self):
        return self.get("Name").strip() or self.path.stem

    def spawned(self):
        """{Tag: [names]} of every ship / troop this event can spawn, over all outcomes."""
        out = {}
        for k, v in self.lists.items():
            out.setdefault(k.split("/", 1)[1], []).extend(v)
        return out


class DialogueDoc(EncounterDoc):
    """A diplomacy dialogue file (DiplomacyDialogs/<language>/<Race>.xml): DialogLine blocks, each a DialogType and one text per mood
    (Friendly / Neutral / Hostile / Default) or personality (DL_Ruth ...). Fields are named Dialogs/DialogLine[3]/Friendly."""
    root_tag = ROOT = "DiplomacyDialog"
    KIND_NAME = "dialogs"

    def name(self):
        return self.path.stem

    def line_count(self):
        return len({k.split("/")[1] for k in self.orig if k.startswith("Dialogs/DialogLine")})


class DesignInfo:
    """A .design file (read only): header fields, ModuleUIDs and the placed modules (x,y;index;sizeX,sizeY;angle;rot;hangarShip)."""

    def __init__(self, path, base, is_base, text=None):
        self.path, self.is_base, self.doc = Path(path), is_base, None
        self.sub = self.path.relative_to(base).as_posix()
        if text is None:
            text = read_file(self.path)[0]
        self.f, self._uids, self.slots, self.mods_declared, self.size = {}, [], [], None, None
        for ln in text.splitlines():
            ln = ln.strip().lstrip("\ufeff")
            if not ln or ln.startswith("#"):
                continue
            m = re.match(r"^([A-Za-z_]\w*)=(.*)$", ln)
            if m:
                k, v = m.group(1), m.group(2).strip()
                if k == "ModuleUIDs":
                    self._uids = [u.strip() for u in v.split(";") if u.strip()]
                elif k == "Modules":
                    try:
                        self.mods_declared = int(v)
                    except ValueError:
                        pass
                else:
                    self.f.setdefault(k, v)
                continue
            parts = ln.split(";")
            try:
                x, y = (int(a) for a in parts[0].split(","))
                idx = int(parts[1])
            except (ValueError, IndexError):
                continue
            sz = (1, 1)
            if len(parts) > 2 and "," in parts[2]:
                try:
                    sz = tuple(int(a) for a in parts[2].split(","))[:2]
                except ValueError:
                    pass
            self.slots.append((x, y, idx, parts[5].strip() if len(parts) > 5 else "", sz))
        try:
            self.size = tuple(int(a) for a in self.f.get("Size", "").split(","))[:2] or None
        except ValueError:
            self.size = None

    name = property(lambda self: self.f.get("Name", ""))
    hull = property(lambda self: (self.doc.get("Hull") if self.doc is not None and "Hull" in self.doc.cur else self.f.get("Hull", "")).strip())
    uids = property(lambda self: [u.strip() for u in self.doc.get("ModuleUIDs").split(";") if u.strip()]
                    if self.doc is not None and "ModuleUIDs" in self.doc.cur else self._uids)
    role = property(lambda self: (self.doc.get("Role") if self.doc is not None and "Role" in self.doc.cur else self.f.get("Role", "")).strip())
    style = property(lambda self: (self.doc.get("Style") if self.doc is not None and "Style" in self.doc.cur else self.f.get("Style", "")).strip())

    def uid_at(self, i):
        return self.uids[i] if 0 <= i < len(self.uids) else "?"

    def counts(self):
        c = {}
        for _x, _y, i, _h, _s in self.slots:
            c[self.uid_at(i)] = c.get(self.uid_at(i), 0) + 1
        return c


# ======================================================================================================================
# SHIP RULES - how the game reads hulls, modules and designs, and the numbers it derives from them.
# Built from the "Ship content reference" written by crunchy gremlin of the BB+ team (pinned to game commit f575899f).
# Every rule below names the section of that reference it comes from (§). Numbers are BASELINES: empire bonuses, tech bonuses and the
# game's production pace are not in the content files, so they are not included.
# ======================================================================================================================
SHIP_RULES_CREDIT = "Ship rules from the 'Ship content reference' by crunchy gremlin (BB+ team)"
HULL_CLASS_FLAG = {"drone": "DroneModule", "fighter": "FighterModule", "corvette": "CorvetteModule", "frigate": "FrigateModule",
                   "destroyer": "DestroyerModule", "cruiser": "CruiserModule", "battleship": "BattleshipModule", "capital": "CapitalModule",
                   "freighter": "FreighterModule", "platform": "PlatformModule", "station": "StationModule"}


def slot_letters(cell):
    """The slot kinds (I inner, O outer, E engine) a hull cell offers; 'C' (grid centre) and '_' are not kinds. (§2.2)"""
    return set(str(cell or "").upper()) & set("IOE")


def slot_accepts(restr, cell):
    """Can a module with this Restrictions value sit on this hull cell? (§2.3) IOE fits anywhere; x-forms need the identical letters;
    otherwise one shared letter is enough."""
    letters = slot_letters(cell)
    if not letters:
        return False
    r = str(restr or "").strip()
    if not r:
        return True
    excl = r[0] in "xX"
    want = set(r.upper().lstrip("X")) & set("IOE")
    if not want:
        return True
    if excl:
        return letters == want
    return want == set("IOE") or want == letters or bool(want & letters)


def _n(m, tag, d=0.0):
    v = num(m.get(tag)) if m is not None else None
    return d if v is None else v


def _b(m, tag):
    return m is not None and str(m.get(tag)).strip().lower() == "true"


def hull_geometry(h):
    """(cols, rows, {(x, y): cell text}, centre (x, y) or None) of a HullDoc. (§2.2)"""
    cells, centre = {}, None
    for y, row in enumerate(h.slots):
        for x, c in enumerate(row):
            if c:
                cells[(x, y)] = c
                if "C" in c.upper() and centre is None:
                    centre = (x, y)
    return h.cols(), len(h.slots), cells, centre


def mod_footprint(m):
    sx, sy = int(_n(m, "XSize", 1)) or 1, int(_n(m, "YSize", 1)) or 1
    return sx, sy


def design_layout(proj, di, ctx):
    """Every placed module with its module record and covered cells, plus the problems of the placement itself (§2.3, §6.2, §8):
    returns (placed [(x, y, uid, module, cells)], issues [(severity, text)])."""
    issues, placed = [], []
    h = ctx["find"](di.hull) if di.hull else None
    modmap = ctx.get("modmap", {})
    cells = {}
    centre = None
    if h is not None:
        _c, _r, cells, centre = hull_geometry(h)
    used = {}
    bad_cell = bad_fit = overlap = 0
    for x, y, idx, _hs, sz in di.slots:
        uid = di.uid_at(idx)
        m = modmap.get(uid.lower())
        sx, sy = sz if sz and sz[0] and sz[1] else (1, 1)
        cov = [(xx, yy) for yy in range(y, y + sy) for xx in range(x, x + sx)]
        placed.append((x, y, uid, m, cov))
        if h is None:
            continue
        restr = m.get("Restrictions").strip() if m is not None else ""
        for c in cov:
            if c not in cells:
                bad_cell += 1
                if bad_cell <= 3:
                    issues.append(("ERROR", "%s at %d,%d covers cell %d,%d, which is not a slot on the hull (§6.2)." % (uid, x, y, c[0], c[1])))
                continue
            if m is not None and not slot_accepts(restr, cells[c]):
                bad_fit += 1
                if bad_fit <= 3:
                    issues.append(("ERROR", "%s (Restrictions %s) cannot sit on the %s slot at %d,%d (§2.3)." % (uid, restr or "none", cells[c], c[0], c[1])))
            if c in used and used[c] != (x, y):
                overlap += 1
                if overlap <= 3:
                    issues.append(("ERROR", "%s at %d,%d overlaps the module at %d,%d - the parser loads it, the game rejects it later (§6.2)." % (
                        uid, x, y, used[c][0], used[c][1])))
            used[c] = (x, y)
    for lab, n in (("outside the hull", bad_cell), ("on a slot that does not accept them", bad_fit), ("overlapping another module", overlap)):
        if n > 3:
            issues.append(("ERROR", "... %d placements in total are %s." % (n, lab)))
    if h is None:
        return placed, issues
    role = (di.role or h.get("Role") or "").strip().lower()
    hull_role = (h.get("Role") or "").strip().lower()
    flag = HULL_CLASS_FLAG.get(hull_role)
    for uid in sorted({p[2] for p in placed}):
        m = modmap.get(uid.lower())
        if m is None:
            continue
        if flag and m.get(flag).strip().lower() == "false":
            issues.append(("WARN", "%s is not allowed on %s hulls (%s=false, §3.1)." % (uid, hull_role, flag)))
        lim = _n(m, "PercentLimitOnShips")
        n = sum(1 for p in placed if p[2] == uid)
        if lim > 0 and cells and n > max(1, lim * 0.01 * len(cells)):
            issues.append(("WARN", "%d x %s is more than the %g%% of the hull's %d slots it may use (§3.1)." % (n, uid, lim, len(cells))))
        if 0 < _n(m, "HealthMax") < 1:
            issues.append(("ERROR", "%s has HealthMax %g: it dies on the first damage tick (§8.10)." % (uid, _n(m, "HealthMax"))))
        if m.get("ModuleType").strip() == "Engine" and m.get("Restrictions").strip().upper() in ("IO", "XIO", "I", "O", "XI", "XO"):
            issues.append(("ERROR", "Engine %s has Restrictions %s: it can never be placed on an engine slot (§8.8)." % (uid, m.get("Restrictions").strip())))
    cmd = sum(1 for p in placed if p[3] is not None and (p[3].get("ModuleType").strip() == "Command" or _b(p[3], "IsCommandModule")))
    if cmd == 0 and role not in ("platform",) and all(p[3] is not None for p in placed):      # unknown modules are reported elsewhere; one may be the cockpit
        issues.append(("ERROR", "No command module (Cockpit / Bridge ...): the ship cannot be crewed (§8.1)."))
    elif cmd == 1 and len(cells) >= 500:
        issues.append(("WARN", "Only one command module on a %d-slot ship: no backup (§8.1)." % len(cells)))
    if di.f.get("GridCenter", "").strip() and centre is not None:
        try:
            gc = tuple(int(a) for a in di.f["GridCenter"].split(","))[:2]
            if gc != centre:
                issues.append(("WARN", "GridCenter %d,%d differs from the hull's centre cell %d,%d: the grid and the model will disagree (§8.2)." % (
                    gc[0], gc[1], centre[0], centre[1])))
        except ValueError:
            pass
    elif centre is None and cells:
        issues.append(("INFO", "The hull has no centre cell (a slot containing C): the game logs 'invalid GridCenter' (§2.2)."))
    return placed, issues


def tech_maps(proj):
    """Lookups over the research tree, built once per set of techs: {uid: tech}, {uid: [parent uids]}, {module uid: tech}, {hull key: tech}.
    If two techs unlock the same module the last one wins, as in the game (§5.2)."""
    key = (id(proj.techs), len(proj.techs))
    c = getattr(proj, "_tech_maps", None)
    if c and c[0] == key:
        return c[1]
    by_uid, parents, mod_tech, hull_tech, dup, mod_types = {}, {}, {}, {}, {}, {}
    for t in proj.techs:
        by_uid[t.uid.strip().lower()] = t
    for t in proj.techs:
        u = t.uid.strip().lower()
        for ch in t.leads:
            parents.setdefault(ch.strip().lower(), []).append(u)
        for mu, _typ in t.unlocks:
            k = mu.strip().lower()
            mod_types.setdefault(k, set()).add(_typ)
            if k in mod_tech and mod_tech[k] is not t:
                dup.setdefault(k, {mod_tech[k].uid}).add(t.uid)
            mod_tech[k] = t
        for hn in t.hulls:
            hull_tech[hn.strip().replace("\\", "/").lower()] = t
    res = {"by_uid": by_uid, "parents": parents, "mod_tech": mod_tech, "hull_tech": hull_tech, "dup": dup, "mod_types": mod_types}
    proj._tech_maps = (key, res)
    return res


def tech_path(proj, tech, tm=None):
    """[tech, parent, grandparent ...] without the free root nodes (§5.3)."""
    tm = tm or tech_maps(proj)
    out, seen, stack = [], set(), [tech.uid.strip().lower()]
    while stack:
        u = stack.pop()
        if u in seen:
            continue
        seen.add(u)
        t = tm["by_uid"].get(u)
        if t is None:
            continue
        ps = tm["parents"].get(u, [])
        if not ps:
            continue                                       # a root: free
        out.append(t)
        stack.extend(ps)
    return out


def design_research(proj, di, ctx, placed=None):
    """(techs needed, total research cost, modules no tech lists, hull without tech) - the game's TechsNeeded closure (§5.3)."""
    tm = tech_maps(proj)
    need, missing, seen = {}, [], set()
    placed = placed if placed is not None else design_layout(proj, di, ctx)[0]
    for _x, _y, uid, _m, _c in placed:
        if uid.lower() in seen:
            continue
        seen.add(uid.lower())
        t = tm["mod_tech"].get(uid.lower())
        if t is None:
            missing.append(uid)
            continue
        for p in tech_path(proj, t, tm):
            need[p.uid] = p
    h = ctx["find"](di.hull) if di.hull else None
    hull_missing = False
    if h is not None:
        ht = tm["hull_tech"].get(proj.hull_key(h).lower())
        if ht is not None:
            for p in tech_path(proj, ht, tm):
                need[p.uid] = p
        elif tm["hull_tech"]:
            hull_missing = True
    cost = sum(_n(t, "Cost") for t in need.values())
    return list(need.values()), cost, missing, hull_missing


def module_defense(m, area, slot_count, shields_max):
    """§7.7 defence of one module."""
    d = _n(m, "HealthMax") * 0.005
    if shields_max > 0:
        sd = shields_max * 0.02
        cov = ((_n(m, "ShieldRadius") + 8) ** 2 * math.pi) / 256 / max(1, slot_count)
        sd *= min(cov, 1.0)
        for t in ("ShieldKineticResist", "ShieldEnergyResist", "ShieldBeamResist", "ShieldExplosiveResist", "ShieldPlasmaResist"):
            sd *= 1 + min(_n(m, t), 1.0) * 0.2
        rr, dl, rc = _n(m, "ShieldRechargeRate"), _n(m, "ShieldRechargeDelay"), _n(m, "ShieldRechargeCombatRate")
        if rr > 0:
            sd *= rr / (shields_max * 0.01)
        if dl > 0:
            sd *= 1 / dl
        if rc > 0:
            sd *= 1 + rc / (shields_max * 0.04)
        sd *= 1 + _n(m, "ShieldDeflection") / 50
        d += sd
    for t in ("BeamResist", "KineticResist", "EnergyResist", "PlasmaResist", "ExplosiveResist"):
        d *= 1 + min(_n(m, t), 1.0) * 0.2
    d *= 1 + _n(m, "Deflection") * 0.01
    ap = _n(m, "APResist")
    if m.get("ModuleType").strip() == "Armor" or ap != 0:
        d *= 1 + ap * 0.5
    d += _n(m, "ECM")
    d *= 1 + _n(m, "EMPProtection") / max(1, area) * 0.002
    d += (_n(m, "TurnThrust") + _n(m, "WarpThrust") + _n(m, "Thrust")) / 15000
    d += _n(m, "PowerFlowMax") * 0.02 + _n(m, "PowerStoreMax") * 0.002 + _n(m, "TroopCapacity") * 50
    d += _n(m, "BonusRepairRate") * 0.5 + _n(m, "AmplifyShields") * 0.05 + _n(m, "Regenerate") * 0.1
    return d


def weapon_offense(m, w, area):
    """§7.7 offence of the weapon a module carries (the game's own strength estimate, not the Balance page's combat model)."""
    if w is None:
        return 0.0
    beam = _b(w, "IsBeam") or _b(w, "Tag_Beam")
    fd = max(_n(w, "FireDelay"), 0.016)
    salvo, proj_n = max(1.0, _n(w, "SalvoCount", 1)), max(1.0, _n(w, "ProjectileCount", 1))
    bdur = _n(w, "BeamDuration", 2.0) or 2.0
    net = fd + (bdur if beam else _n(w, "SalvoTimer"))
    shots = 1.0 / max(net, 0.016)
    dmg = _n(w, "DamageAmount")
    if beam:
        dmg = dmg or _n(w, "PowerDamage")
        off = dmg * 60 * bdur * shots + _n(w, "TractorDamage") * 30 * shots
        off += (_n(w, "PowerDamage") + _n(w, "RepulsionDamage") + _n(w, "SiphonDamage")) * 45 * shots + _n(w, "TroopDamageChance") * shots
    else:
        off = dmg * salvo * proj_n * shots + (_n(w, "EMPDamage") * 0.5 + _n(w, "PowerDamage") * 0.75) * salvo * proj_n * shots
    guided = _b(w, "Tag_Guided")
    rng = _n(w, "Range")
    if guided:
        off *= 2.5
    off *= 1 + _n(w, "ArmorPen") * 0.2
    for t in ("EffectVsArmor", "EffectVsShields"):
        off *= 1 + (_n(w, t, 1.0) - 1) * 0.5
    truepd = _b(w, "TruePD")
    if truepd:
        off *= 0.2
    spd = _n(w, "ProjectileSpeed")
    if spd > 1 and rng > 0:
        off *= spd / rng
    flight = 1.0
    if _b(w, "Tag_Intercept"):
        flight *= 0.8
        rad = _n(w, "ProjectileRadius")
        if _n(w, "RotationRadsPerSecond") > 0 and rad > 0:
            flight *= 1 + _n(w, "HitPoints") * 0.02 / rad
    dly = _n(w, "DelayedIgnition")
    if dly > 0:
        flight *= 1 - min(dly * 0.1, 0.95)
    off *= flight
    er = _n(w, "ExplosionRadius")
    if er > 16 and not truepd:
        off *= er * 0.0625
    off *= 1 + _n(w, "ShieldPenChance") * 0.01
    for t, v in (("ExcludesFighters", 0.15), ("ExcludesCorvettes", 0.15), ("ExcludesCapitals", 0.45), ("ExcludesStations", 0.25)):
        if _b(w, t):
            off *= 1 - v
    reach = rng * 0.00025
    if guided:
        off *= reach * math.sqrt(max(reach, 0))
    else:
        off *= max(0.1, 1 - _n(w, "FireCone") * 0.01 * rng * 0.0005)
        off *= reach * reach
    if m.get("ModuleType").strip() == "Turret":
        off *= 1.25
    fof = math.radians(_n(m, "FieldOfFire"))
    off *= min(max(fof / (math.pi * 0.34), 1.0), 4.0)
    pw = _n(w, "PowerRequiredToFire")
    sustained = (_n(w, "BeamPowerCostPerSecond") * bdur + pw * proj_n * salvo) / max(net, 0.016)
    if _b(w, "Tag_Kinetic") and (pw > 10 * area or sustained > 2 * area):
        off *= 0.5
    off *= _n(w, "OffPowerMod", 1.0) or 1.0
    return off


def design_numbers(proj, di, ctx, placed=None):
    """Cost, mass, power, speed and strength of a design from the content files alone. (§7.1-§7.6)"""
    placed = placed if placed is not None else design_layout(proj, di, ctx)[0]
    h = ctx["find"](di.hull) if di.hull else None
    slot_count = sum(1 for r in h.slots for c in r if c) if h is not None else max(1, sum(len(p[4]) for p in placed))
    role = (di.role or (h.get("Role") if h is not None else "") or "").strip().lower()
    mods = [(p[3], p[2]) for p in placed if p[3] is not None]
    out = {"slots": slot_count, "placed": len(placed), "unknown": [p[2] for p in placed if p[3] is None]}
    cost = sum(_n(m, "Cost") for m, _u in mods)
    if role in ("platform", "station"):
        cost *= 0.7
    out["cost"] = int(cost)
    minm = int(slot_count * 0.5 * (1 + slot_count * 0.002))
    pos, neg = float(minm), 0.0
    for m, _u in mods:
        v = _n(m, "Mass")
        if v >= 0:
            pos += v
        else:
            neg += v
    mass = max(max(pos + neg, pos * 0.5), minm)
    out["mass"], out["min_mass"] = mass, minm
    flow, store = sum(_n(m, "PowerFlowMax") for m, _u in mods), sum(_n(m, "PowerStoreMax") for m, _u in mods)
    draw = sum(_n(m, "PowerDraw") for m, _u in mods)
    out.update({"power_flow": flow, "power_store": store, "power_draw": draw,
                "power_seconds": (store / (draw - flow)) if draw > flow else None})
    thrust, warp, turn = (sum(_n(m, t) for m, _u in mods) for t in ("Thrust", "WarpThrust", "TurnThrust"))
    out.update({"thrust": thrust, "warp": warp, "stl": thrust / mass if mass else 0.0, "ftl": warp / mass if mass else 0.0,
                "turn": turn / mass / 700 if mass else 0.0})
    main = [m for m, _u in mods if m.get("ModuleType").strip() == "Shield" and _n(m, "ShieldPowerMax") > 0]
    amp = sum(_n(m, "AmplifyShields") for m, _u in mods)
    per = amp / len(main) if main else 0.0
    off = dfn = off_area = 0.0
    for m, _u in mods:
        sx, sy = mod_footprint(m)
        area = sx * sy
        smax = _n(m, "ShieldPowerMax")
        if m.get("ModuleType").strip() == "Shield" and smax > 0:
            smax += per
        w = proj.weapon_for(m)
        off += weapon_offense(m, w, area) + (50 if _b(m, "IsTroopBay") else 0)
        dfn += module_defense(m, area, slot_count, smax)
        if w is not None or _b(m, "IsTroopBay") or _b(m, "IsSupplyBay") or _n(m, "MaximumHangarShipSize") > 0:
            off_area += area
    ratio = off_area / slot_count if slot_count else 0
    strength = off * 2 + dfn * 0.1 if (dfn > off and ratio < 0.1) else off + dfn
    if role in ("platform", "station"):
        strength *= 0.5
    wpow = 0.0
    for m, _u in mods:
        w = proj.weapon_for(m)
        if w is not None:                                    # §7.4: power a weapon takes per second while firing
            net = max(_n(w, "FireDelay"), 0.016) + ((_n(w, "BeamDuration", 2.0) or 2.0) if (_b(w, "IsBeam") or _b(w, "Tag_Beam")) else _n(w, "SalvoTimer"))
            wpow += (_n(w, "BeamPowerCostPerSecond") * (_n(w, "BeamDuration", 2.0) or 2.0) + _n(w, "PowerRequiredToFire") * max(1.0, _n(w, "ProjectileCount", 1))
                     * max(1.0, _n(w, "SalvoCount", 1))) / max(net, 0.016)
    surplus = flow - draw
    out.update({"weapon_power": wpow, "excess_wpn": max(0.0, wpow - surplus), "wpn_seconds": (store / (wpow - surplus)) if wpow > surplus and store else None,
                "efficiency": min(1.0, max(0.0, surplus) / wpow) if wpow > 0 else 1.0,
                "hp": sum(_n(m, "HealthMax") for m, _u in mods), "shield_power": sum(_n(m, "ShieldPowerMax") for m, _u in mods), "amplify": amp,
                "emp": sum(_n(m, "EMPProtection") for m, _u in mods), "sensor": max([_n(m, "SensorRange") for m, _u in mods] or [0.0]),
                "warp_draw": draw * 1.0 + sum(_n(m, "PowerDrawAtWarp") for m, _u in mods) * 0.5,
                "ftl_spool": max([_n(m, "FTLSpoolTime") for m, _u in mods] or [0.0])})
    out.update({"offense": off, "defense": dfn, "strength": strength, "weapon_modules": sum(1 for m, _u in mods if proj.weapon_for(m) is not None)})
    return out


def design_report(proj, di, ctx):
    """Everything the shipyard-style checks can say about one design: (rows [(label, text)], issues [(sev, text)], numbers). Used by the Designs tab."""
    placed, issues = design_layout(proj, di, ctx)
    nums = design_numbers(proj, di, ctx, placed)
    techs, rcost, missing, hull_missing = design_research(proj, di, ctx, placed)
    rows = [("Cost (baseline)", fmtv(nums["cost"])),
            ("Mass (baseline)", "%s  (the hull alone weighs %s)" % (fmtv(nums["mass"]), fmtv(nums["min_mass"])))]
    role = (di.role or "").strip().lower()
    if role not in ("platform", "station"):
        typ = get_profile(proj, ctx, build=False).get(role, di.style)       # what the designs that exist have (once it has been worked out)
        t_stl, t_ftl, t_turn = (typ["stl"], typ["ftl"], typ["turn"]) if typ else (0, 0, 0)

        def vs(v, t, fmt):
            return (fmt % v) + (("   (average %s: %s)" % (role, fmt % t)) if t else "")
        rows.append(("Sub-light speed (thrust / mass)", vs(nums["stl"], t_stl, "%.0f") if nums["thrust"] else "none - no thrust"))
        rows.append(("Warp speed (warp thrust / mass)", vs(nums["ftl"], t_ftl, "%.0f") if nums["warp"] else "none - no warp thrust"))
        rows.append(("Turn rate (turn thrust / mass)", (("%.2f rad/s = %.0f deg/s" % (nums["turn"], nums["turn"] * 57.2958)) + (
            ("   (average %s: %.2f)" % (role, t_turn)) if t_turn else "")) if nums["turn"] else "none - no turn thrust"))
        if role != "fighter" and nums["placed"]:
            if not nums["thrust"]:
                issues.append(("WARN", "No sub-light thrust: the ship cannot move in a system (§7.6)."))
            if not nums["warp"]:
                issues.append(("WARN", "No warp thrust: the ship cannot travel between stars (§7.6)."))
            if not nums["turn"] and nums["thrust"]:
                issues.append(("INFO", "No turn thrust: the ship turns very slowly or not at all."))
        for lab, a, t in (("Sub-light speed", nums["stl"], t_stl), ("Warp speed", nums["ftl"], t_ftl), ("Turn rate", nums["turn"], t_turn)):
            if t and a and a < 0.5 * t:
                issues.append(("INFO", "%s is only %d%% of the average %s design." % (lab, 100 * a / t, role)))
    mil = get_profile(proj, ctx, build=False).get("military", di.style)
    if role not in ("platform", "station", "fighter") and mil and nums["warp"] and nums["ftl"] < 0.9 * mil["ftl"]:
        issues.append(("WARN", "Slow Warp Speed: the warp speed (%.0f) is below the average of the military designs (%.0f). In a fleet it holds the others back. "
                       "Add warp engines and power them (the game's own design issue)." % (nums["ftl"], mil["ftl"])))
    if nums["weapon_power"] > 0 and nums["efficiency"] < 0.98:
        issues.append(("WARN", "Partial Weapon Efficiency: the weapons use %s power a second in combat but the reactors make only %s above the ship's own draw, so "
                       "combat efficiency drops to about %d%% once the power store is empty. Add reactors or power storage (the game's own design issue)." % (
                           fmtv(nums["weapon_power"]), fmtv(max(0.0, nums["power_flow"] - nums["power_draw"])), round(100 * nums["efficiency"]))))
    rows.append(("Strength estimate", "%s   (offence %s + defence %s) - the game's own AI estimate" % (
        fmtv(nums["strength"]), fmtv(nums["offense"]), fmtv(nums["defense"]))))
    if nums["power_draw"] or nums["power_flow"]:
        sec = nums["power_seconds"]
        rows.append(("Power", "makes %s, uses %s%s" % (fmtv(nums["power_flow"]), fmtv(nums["power_draw"]), "" if sec is None else "  - runs dry after %.0f s" % sec)))
        if nums["power_draw"] > nums["power_flow"] and not nums["power_store"]:
            issues.append(("WARN", "The modules draw more power (%s) than the plants make (%s) and there is no storage (§7.4)." % (
                fmtv(nums["power_draw"]), fmtv(nums["power_flow"]))))
    if nums["weapon_power"] > 0:
        rows.append(("Weapon power use / excess drain", "%s / s   (excess over the reactors: %s%s)" % (
            fmtv(nums["weapon_power"]), fmtv(nums["excess_wpn"]), ("; weapons run %.1f s on the store" % nums["wpn_seconds"]) if nums["wpn_seconds"] else "")))
    for lab, key in (("Total hitpoints (modules)", "hp"), ("Shield power", "shield_power"), ("Shield amplify", "amplify"), ("EMP protection", "emp"),
                     ("Sensor range", "sensor")):
        if nums[key]:
            rows.append((lab, fmtv(nums[key])))
    if techs or missing:
        rows.append(("Research cost to unlock", ("%s  (%d techs)" % (fmtv(rcost), len(techs))) if not missing else "cannot be unlocked - see problems"))
    if missing:
        names = sorted(set(missing))
        issues.append(("WARN", "No tech unlocks %s, so no empire can ever build this design (§5.3, §8.7)." % ", ".join(names[:4])
                       + (" and %d more" % (len(names) - 4) if len(names) > 4 else "")))
    if hull_missing:
        issues.append(("INFO", "No tech unlocks this hull (§5.3)."))
    used = {p[2].lower() for p in placed}
    for k, ts in tech_maps(proj)["dup"].items():
        if k in used:
            issues.append(("WARN", "Module %s is unlocked by %d techs (%s); only the last one loaded counts (§5.2)." % (k, len(ts), ", ".join(sorted(ts)[:3]))))
    return rows, issues, nums


COMBAT_ROLES = ("battleship", "cruiser", "frigate", "corvette", "capital", "carrier", "bomber")


class DesignProfile:
    """What the designs that already exist look like, per role: the share of the hull's slots given to weapons / armour / shields / power /
    engines, how much of the armour sits in the bow, and the typical sub-light speed, warp speed and turn rate. The generator copies these
    proportions, so new designs look like the ones people (and the game) already made. Takes about a second for a big mod, once."""

    MAX_MISSING = 0.25            # a design with more than this share of unknown modules is not used for the proportions

    def __init__(self, proj, ctx):
        self.by_role, self.usage, self.style_n = {}, {}, {}
        for _ in self.fill_steps(proj, ctx):
            pass

    def fill_steps(self, proj, ctx):
        """The work of __init__ as a generator (one step per design) so the window can stay responsive while it runs."""
        for d in proj.load_designs():
            yield
            role = (d.role or "").strip().lower()
            h = ctx["find"](d.hull) if d.hull else None
            if h is None or not d.slots or not role:
                continue
            try:
                placed, _iss = design_layout(proj, d, ctx)
                st = re.sub(r"\W", "", d.style or "").lower()
                self.style_n[st] = self.style_n.get(st, 0) + 1
                for u in {p[2].lower() for p in placed if p[3] is not None}:
                    self.usage.setdefault(st, set()).add(u)
                cells = sum(1 for r in h.slots for c in r if c)
                if cells < 20 or sum(1 for p in placed if p[3] is None) > self.MAX_MISSING * max(1, len(placed)):
                    continue
                rr = [r for r, row in enumerate(h.slots) for c in row if c]
                top, span = min(rr), max(1, max(rr) - min(rr))
                nums = design_numbers(proj, d, ctx, placed)
            except Exception:
                continue
            area, fr = {}, {}
            for p in placed:
                m = p[3]
                if m is None:
                    continue
                t = m.get("ModuleType").strip()
                k = "W" if proj.weapon_for(m) is not None else {"Armor": "A", "Shield": "S", "PowerPlant": "P", "Engine": "E", "Command": "C"}.get(t, "x")
                for (_cx, cy) in p[4]:
                    area[k] = area.get(k, 0) + 1
                    if (cy - top) / span < 0.35:
                        fr[k] = fr.get(k, 0) + 1
            self.by_role.setdefault(role, []).append({
                "style": (d.style or "").strip().lower(), "n": cells, "frac": {k: v / cells for k, v in area.items()},
                "front": {k: fr.get(k, 0) / v for k, v in area.items() if v}, "stl": nums["stl"], "ftl": nums["ftl"], "turn": nums["turn"]})

    def favourites(self, style):
        """The modules the designs of this race already use (None when the race has fewer than 3 designs): the generator prefers these."""
        st = re.sub(r"\W", "", style or "").lower()
        return self.usage.get(st) if self.style_n.get(st, 0) >= 3 else None

    def get(self, role, style=""):
        """Median numbers for a role (the designs of that race first when there are enough), or None when too few designs exist."""
        rows = [r for k in COMBAT_ROLES for r in self.by_role.get(k, [])] if role == "military" else self.by_role.get(role, [])
        if len(rows) < 4 and role in COMBAT_ROLES:
            rows = [r for k in COMBAT_ROLES for r in self.by_role.get(k, [])]
        st = re.sub(r"\W", "", style or "").lower()
        mine = [r for r in rows if st and re.sub(r"\W", "", r["style"]) == st]
        rows = mine if len(mine) >= 6 else rows
        if len(rows) < 4:
            return None

        def med(vals):
            vals = sorted(vals)
            return vals[len(vals) // 2] if vals else 0.0

        def avg(vals):                                       # the average of the middle 80%: the odd very slow / very fast ship does not skew it
            vals = sorted(vals)
            k = len(vals) // 10
            vals = vals[k:len(vals) - k] or vals
            return sum(vals) / len(vals) if vals else 0.0
        keys = ("W", "A", "S", "P", "E")
        return {"n": len(rows), "frac": {k: med([r["frac"].get(k, 0.0) for r in rows]) for k in keys},
                "front": {k: med([r["front"].get(k, 0.0) for r in rows if k in r["front"]]) for k in keys},
                "stl": avg([r["stl"] for r in rows]), "ftl": avg([r["ftl"] for r in rows]), "turn": avg([r["turn"] for r in rows])}


class _ProfileCache:
    def __init__(self, prof):
        self.prof = prof

    def get(self, role, style=""):
        return self.prof.get(role, style) if self.prof is not None else None

    def favourites(self, style):
        return self.prof.favourites(style) if self.prof is not None else None


_PROFILES = {}


def get_profile(proj, ctx, build=True):
    """The (cached) DesignProfile of this project; with build=False only what is already worked out (None-safe wrapper otherwise)."""
    key = id(proj)
    n = len(proj.load_designs())
    hit = _PROFILES.get(key)
    if hit is None or hit[0] != n:
        if not build:
            return _ProfileCache(None)
        hit = _PROFILES[key] = (n, DesignProfile(proj, ctx))
    return _ProfileCache(hit[1])


GEN_GOALS = {      # weap/shield/armor are the fallback shares when no existing designs are known; wm/sm/am scale what the existing designs do
    "Warship - balanced": {"weap": 0.20, "shield": 0.08, "armor": 1.0, "cargo": 0.0, "wm": 1.0, "sm": 1.0, "am": 1.0, "speed": 1.0,
                           "about": "Proportions of the existing designs of that hull type: thick armour on the bow, weapons behind it, shields, power."},
    "Gunship - weapons first": {"weap": 0.35, "shield": 0.05, "armor": 0.6, "cargo": 0.0, "wm": 1.7, "sm": 0.6, "am": 0.6, "speed": 0.9,
                                "about": "Far more weapons than usual, thinner armour, fewer shields."},
    "Defender - armour and shields": {"weap": 0.12, "shield": 0.14, "armor": 1.0, "cargo": 0.0, "wm": 0.6, "sm": 1.7, "am": 1.4, "speed": 0.9,
                                      "about": "Built to survive: thick bow armour, bigger shields, a few guns."},
    "Scout - fast and light": {"weap": 0.0, "shield": 0.0, "armor": 0.15, "cargo": 0.0, "wm": 0.0, "sm": 0.0, "am": 0.3, "speed": 1.3,
                               "about": "Engines, power and a cockpit; nothing else."},
    "Freighter - cargo": {"weap": 0.0, "shield": 0.0, "armor": 0.2, "cargo": 0.6, "wm": 0.0, "sm": 0.0, "am": 0.3, "speed": 1.0,
                          "about": "Cargo holds in every inner slot that is left."},
}


class DesignGenerator:
    """Builds a .design for a hull from the real placement rules (§2.3, §6.2) and checks the result with the same rules the Designs tab uses.
    Order: command module in the centre, engines on the engine slots, weapons outside, shields inside, power plants until the draw is covered,
    armour on what is left. Based on crunchy gremlin's 'Ship content reference' (BB+ team)."""

    def __init__(self, proj, ctx=None):
        self.proj, self.ctx = proj, ctx or proj.design_context()

    # ---- candidate modules
    def catalog(self, hull, style="", only_unlocked=True, research_limit=0.0):
        P = self.proj
        tm = tech_maps(P)
        flag = HULL_CLASS_FLAG.get((hull.get("Role") or "").strip().lower())
        st = re.sub(r"\W", "", style or "").lower()
        out = []
        for uid, m in self.ctx["modmap"].items():
            real = m.get("UID").strip() or m.path.stem
            if re.match(r"(?i)(remnant|ancient|pirate|borg\w*cube)", real):
                continue
            try:
                if any(p.lower() in ("secret", "pirates", "remnant") for p in m.path.parts):
                    continue
            except Exception:
                pass
            if flag and m.get(flag).strip().lower() == "false":
                continue
            if _n(m, "XSize", 0) <= 0 or _n(m, "YSize", 0) <= 0:
                continue
            if 0 < _n(m, "HealthMax") < 1:
                continue
            t = tm["mod_tech"].get(uid)
            if only_unlocked and tm["mod_tech"] and t is None:
                continue
            if t is not None:
                types = {x for x in tm["mod_types"].get(uid, set()) if x}
                if types and st and not any(re.sub(r"\W", "", x).lower() == st for x in types):
                    continue                                  # unlocked only for other races
                if research_limit and sum(_n(x, "Cost") for x in tech_path(P, t, tm)) > research_limit:
                    continue
            sx, sy = mod_footprint(m)
            out.append({"uid": real, "m": m, "w": P.weapon_for(m), "type": m.get("ModuleType").strip(), "size": (sx, sy), "area": sx * sy,
                        "restr": m.get("Restrictions").strip(), "rot_ok": not _b(m, "DisableRotation") and sx != sy,
                        "limit": _n(m, "PercentLimitOnShips")})
        return out

    # ---- the build
    def build(self, hull, goal, name, style, only_unlocked=True, research_limit=0.0, kinds=("energy", "ordnance")):
        """(text, notes, di, report, grid) - a complete .design file text, what could not be done, and the checks on the result. The engine mix
        (sub-light / warp / turning) is tuned over a few tries until the speeds reach what the existing designs of that role have."""
        P = self.proj
        cat = self.catalog(hull, style, only_unlocked, research_limit)
        role = (hull.get("Role") or "").strip().lower()
        pc = get_profile(P, self.ctx)
        prof = pc.get(role, style)
        fav = pc.favourites(style)
        if fav:                                              # prefer modules this race's existing designs already use, type by type
            by_type = {}
            for c in cat:
                by_type.setdefault(c["type"], []).append(c)
            full = cat
            cat = [c for cs in by_type.values() for c in ([x for x in cs if x["uid"].lower() in fav] or cs)]
            for tag in ("Thrust", "WarpThrust", "TurnThrust"):    # the race's own engines may lack one kind of movement: borrow the best other one
                if not any(c["type"] == "Engine" and _n(c["m"], tag) > 0 for c in cat):
                    extra = sorted((c for c in full if c["type"] == "Engine" and _n(c["m"], tag) > 0), key=lambda c: -_n(c["m"], tag) / c["area"])[:1]
                    cat = cat + [c for c in extra if c not in cat]
        g = GEN_GOALS.get(goal) or GEN_GOALS["Warship - balanced"]
        tgt = None
        if prof and prof.get("stl") and role not in ("platform", "station"):
            tgt = (prof["stl"] * g.get("speed", 1.0), prof["ftl"] * g.get("speed", 1.0), prof["turn"] * g.get("speed", 1.0))
        mix, best, tries = [1.0, 1.0, 0.6], None, []
        for _i in range(4 if tgt else 1):
            res = self._once(hull, goal, name, style, cat, prof, tuple(mix), kinds)
            nums = res[3][2]
            act = (nums["stl"], nums["ftl"], nums["turn"])
            score = sum(min(1.0, a / t) for a, t in zip(act, tgt) if t) if tgt else 0.0
            tries.append(score)
            if best is None or score > best[0] + 1e-9:
                best = (score, res)
            if not tgt or all((not t) or a >= 0.95 * t for a, t in zip(act, tgt)):
                break
            for k in range(3):
                if tgt[k]:
                    mix[k] = max(0.15, min(4.0, mix[k] * max(0.6, min(2.0, (tgt[k] / max(act[k], 1e-9)) ** 0.6))))
        text, notes, di, rep, grid = best[1]
        nums = rep[2]
        if tgt:
            for lab, a, t in (("sub-light", nums["stl"], tgt[0]), ("warp", nums["ftl"], tgt[1]), ("turning", nums["turn"], tgt[2])):
                if t and a < 0.8 * t:
                    notes.append("%s speed %.0f%% of what %s designs have (engine slots are limited on this hull)" % (lab, 100 * a / t, role or "such"))
        if prof:
            notes.append("proportions follow %d existing %s designs" % (prof["n"], role or "ship"))
        return text, notes, di, rep, grid

    def _once(self, hull, goal, name, style, cat, prof, mix, kinds=("energy", "ordnance")):
        P = self.proj
        g = GEN_GOALS.get(goal) or GEN_GOALS["Warship - balanced"]
        cols, rows, cells, centre = hull_geometry(hull)
        total = len(cells)
        notes = []
        if total < 4:
            raise ValueError("That hull has too few slots to build on.")
        used, placed, uids = {}, [], []
        cx = sum(x for x, _ in cells) / total
        cy = sum(y for _, y in cells) / total
        centre_pt = centre or (round(cx), round(cy))
        by_center = sorted(cells, key=lambda c: (c[0] - centre_pt[0]) ** 2 + (c[1] - centre_pt[1]) ** 2)
        top_y, bot_y = min(y for _, y in cells), max(y for _, y in cells)
        span = max(1, bot_y - top_y)
        rear = sorted(cells, key=lambda c: (-c[1], abs(c[0] - cx)))

        def rel(c):                                          # 0 = the bow (top of the grid), 1 = the stern
            return (c[1] - top_y) / span
        depth, frontier = {}, [c for c in cells if any((c[0] + dx, c[1] + dy) not in cells for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)))]
        for c in frontier:
            depth[c] = 0
        while frontier:                                      # how many cells in from the hull's edge: 0 = the outside rim
            nxt = []
            for c in frontier:
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    n = (c[0] + dx, c[1] + dy)
                    if n in cells and n not in depth:
                        depth[n] = depth[c] + 1
                        nxt.append(n)
            frontier = nxt
        counts = {}

        blocked = set()                                      # cells kept free for the power plants and shields until they have been placed

        def eff(c, v):                                       # a heavy module is worth less: it slows the ship
            return v / (1.0 + max(0.0, _n(c["m"], "Mass")) / c["area"]) ** 0.5

        def fits(c, x, y, sx, sy):
            for yy in range(y, y + sy):
                for xx in range(x, x + sx):
                    if (xx, yy) in used or (xx, yy) in blocked or (xx, yy) not in cells or not slot_accepts(c["restr"], cells[(xx, yy)]):
                        return False
            return True

        def put(c, order, limit=1, require=None):
            n = 0
            for (x, y) in order:
                if n >= limit:
                    break
                if c["limit"] > 0 and counts.get(c["uid"], 0) + 1 > max(1, c["limit"] * 0.01 * total):
                    break
                for (sx, sy, rot) in ([(c["size"][0], c["size"][1], 0)] + ([(c["size"][1], c["size"][0], 1)] if c["rot_ok"] else [])):
                    if require is not None and not all(require(cells[(xx, yy)]) for yy in range(y, y + sy) for xx in range(x, x + sx) if (xx, yy) in cells):
                        continue
                    if fits(c, x, y, sx, sy):
                        if c["uid"] not in uids:
                            uids.append(c["uid"])
                        placed.append((x, y, uids.index(c["uid"]), (sx, sy), rot))
                        for yy in range(y, y + sy):
                            for xx in range(x, x + sx):
                                used[(xx, yy)] = c["uid"]
                        counts[c["uid"]] = counts.get(c["uid"], 0) + 1
                        n += 1
                        break
            return n

        def ranked(types, key, need=lambda c: True):
            return sorted((c for c in cat if c["type"] in types and need(c)), key=key, reverse=True)

        def fill_area(cs, order, budget):
            """Cover up to `budget` cells along `order` with the biggest of the good modules `cs`, so a rim is made of a few large pieces."""
            got = 0
            for (x, y) in order:
                if got >= budget:
                    break
                if (x, y) in used:
                    continue
                for c in cs:
                    if put(c, [(x, y)], 1):
                        got += c["area"]
                        break
            return got

        def share(key, default):                             # the fraction of the hull's slots the existing designs give to a kind of module
            return (prof or {}).get("frac", {}).get(key, default)

        # 1. command module in the centre
        cmd = ranked(("Command",), lambda c: (-c["area"], -_n(c["m"], "Cost"))) or sorted(
            (c for c in cat if re.search(r"(?i)cockpit|bridge|command", c["uid"])), key=lambda c: c["area"])
        if cmd:
            c = next((k for k in cmd if k["area"] <= max(4, total // 12)), cmd[-1])
            if not put(c, by_center, 1):
                notes.append("the command module %s did not fit near the centre" % c["uid"])
        else:
            notes.append("no command module was found among the allowed modules")
        # 2. engines: a mix of sub-light, warp and turning modules (the mix is tuned by build() until the speeds are right)
        e_cells = [c for c in rear if "E" in slot_letters(cells[c])]
        engines = [c for c in cat if c["type"] == "Engine" and "E" in (c["restr"].upper() or "E")]
        classes = []
        for tag in ("Thrust", "WarpThrust", "TurnThrust"):
            classes.append(sorted((c for c in engines if _n(c["m"], tag) > 0), key=lambda c: -_n(c["m"], tag) / c["area"])[:3])
        if e_cells and engines:
            msum = sum(mix) or 1.0
            need = [m / msum * len(e_cells) for m in mix]
            got = [0.0, 0.0, 0.0]
            is_e = lambda cell: "E" in slot_letters(cell)
            for cell in e_cells:
                if cell in used:
                    continue
                for k in sorted(range(3), key=lambda k: -(need[k] - got[k])):
                    if any(put(c, [cell], 1, require=is_e) and not got.__setitem__(k, got[k] + c["area"]) for c in classes[k]):
                        break
            for c in sorted(engines, key=lambda c: -(_n(c["m"], "Thrust") + _n(c["m"], "WarpThrust") * 0.5) / c["area"]):
                put(c, [x for x in e_cells if x not in used], 999, require=is_e)      # whatever engine slots are still empty
        elif not engines:
            notes.append("no engine module was found")
        # 3. armour on the bow first: the front shell, where most of the damage arrives
        aq = lambda c: eff(c, module_defense(c["m"], c["area"], total, 0) / c["area"])
        arm = ranked(("Armor",), aq)
        pool = []
        if arm:
            q0 = aq(arm[0])
            pool = sorted([c for c in arm if aq(c) >= 0.7 * q0], key=lambda c: -c["area"])
        free = [c for c in by_center if c not in used]       # keep the middle free for power and shields
        blocked.update(free[:int((share("P", 0.06) + share("S", 0.08) * g.get("sm", 1.0)) * total * 1.4) + 2])
        a_target = share("A", 0.33) * g.get("am", 1.0) * total
        if pool and g["armor"] > 0:
            bow = sorted([c for c in cells if rel(c) < 0.42], key=lambda c: (min(depth[c], 3), rel(c)))
            fill_area(pool, bow, max(1.0, max((prof or {}).get("front", {}).get("A", 0.0), 0.5) * a_target))
        # 4. weapons: outside, toward the bow and the flanks, behind that first layer of armour
        wcells = int(min(0.5, share("W", 0.2) * g.get("wm", 1.0)) * total) if g["weap"] > 0 else 0
        weaps = ranked(("Turret", "MainGun", "MissileLauncher"), lambda c: eff(c, weapon_offense(c["m"], c["w"], c["area"]) / c["area"]), lambda c: c["w"] is not None)
        if weaps and 0 < len(set(kinds) & {"energy", "ordnance"}) < 2:      # only energy weapons, or only ones that use ordnance
            want_ord = "ordnance" in kinds
            keep = [c for c in weaps if (_n(c["w"], "OrdinanceRequiredToFire") > 0) == want_ord]
            if keep:
                weaps = keep
            elif wcells:
                notes.append("no %s weapons exist for this design, so the other kind was used" % ("ordnance-based" if want_ord else "energy"))
        if wcells and weaps:
            fam = {}
            for c in weaps:                                  # a mix of kinds (beam / kinetic / missile ...) instead of one type only
                w = c["w"]
                k = "beam" if (_b(w, "IsBeam") or _b(w, "Tag_Beam")) else "missile" if _b(w, "Tag_Missile") else "plasma" if _b(w, "Tag_Plasma") else "kinetic"
                fam.setdefault(k, []).append(c)
            order = [v[0] for v in sorted(fam.values(), key=lambda v: -weapon_offense(v[0]["m"], v[0]["w"], v[0]["area"]) / v[0]["area"])][:3]
            wide = sorted(cells, key=lambda c: (min(depth[c], 4) * 0.15 + rel(c) * 0.6, c[1], c[0]))
            wset = {c["uid"] for c in weaps}
            i = 0
            while sum(1 for u in used.values() if u in wset) < wcells and order:
                c = order[i % len(order)]
                i += 1
                if not put(c, wide, 1):
                    order = [k for k in order if k is not c]
                    if not order:
                        break
        elif wcells:
            notes.append("no weapon modules were found")
        # ordnance for weapons that use it
        if any(_n(c["w"], "OrdinanceRequiredToFire") > 0 for c in weaps if c["uid"] in counts):
            ordn = ranked(("Ordnance",), lambda c: _n(c["m"], "OrdinanceCapacity") / c["area"])
            n_w = sum(counts.get(c["uid"], 0) for c in weaps)
            if ordn:
                for _ in range(max(1, n_w // 5)):
                    put(ordn[0], by_center, 1)
        # 5. power plants and shields together: a shield is kept only if the plants to feed it still fit
        blocked.clear()
        plants = ranked(("PowerPlant",), lambda c: _n(c["m"], "PowerFlowMax") / c["area"] - _n(c["m"], "PowerDraw") / c["area"] * 0.1)
        shields = ranked(("Shield",), lambda c: eff(c, module_defense(c["m"], c["area"], total, _n(c["m"], "ShieldPowerMax")) / c["area"]), lambda c: _n(c["m"], "ShieldPowerMax") > 0)

        def balance():
            flow = draw = 0.0
            for u, cnt in counts.items():
                m = self.ctx["modmap"].get(u.lower())
                flow += _n(m, "PowerFlowMax") * cnt
                draw += _n(m, "PowerDraw") * cnt
            return flow, draw

        def power_ok():
            guard = 0
            while True:
                flow, draw = balance()
                guard += 1
                if flow >= draw * 1.05:
                    return True
                if guard > total or not plants:
                    return False
                if not (put(plants[0], by_center, 1) or (len(plants) > 1 and put(plants[1], by_center, 1))):
                    return False

        if not plants:
            notes.append("no power plant module was found")
        else:
            if not power_ok():
                notes.append("the engines and weapons alone need more power than the plants that fit can make")
            scells, n = int(min(0.3, share("S", 0.08) * g.get("sm", 1.0)) * total) if g["shield"] > 0 else 0, 0
            for c in shields:
                while n < scells:
                    snap = (list(placed), dict(used), list(uids), dict(counts))
                    if put(c, by_center, 1) and power_ok():
                        n += c["area"]
                    else:
                        placed.clear(); used.clear(); uids.clear(); counts.clear()
                        placed.extend(snap[0]); used.update(snap[1]); uids.extend(snap[2]); counts.update(snap[3])
                        break
                if n >= scells:
                    break
        # 6. cargo (freighters), then armour on what is left, the rim and the bow first
        if g["cargo"]:
            hold = ranked(("Storage",), lambda c: _n(c["m"], "CargoCapacity") / c["area"], lambda c: _n(c["m"], "CargoCapacity") > 0)
            if hold:
                want = int(g["cargo"] * total)
                for c in hold:
                    while sum(1 for u in used.values() if u == c["uid"]) < want and put(c, by_center, 1):
                        pass
        if pool and g["armor"] > 0:
            left = sorted([c for c in cells if c not in used], key=lambda c: (min(depth[c], 3), rel(c)))
            fill_area(pool, left, int(g["armor"] * len(left)))
            if any(c not in used for c in cells):            # the odd gaps: any armour piece, however small
                fill_area(sorted(arm, key=lambda c: c["area"]), [c for c in left if c not in used], len(left))
        # 7. write the file
        nl = "\n"
        gx, gy = centre_pt
        head = ["Version=1", "Name=" + name, "Hull=" + P.hull_key(hull), "Role=" + (hull.get("Role").strip() or "frigate"), "ModName=" + P.root.name,
                "Style=" + (style or hull.get("Style").strip()), "Size=%d,%d" % (cols, rows), "GridCenter=%d,%d" % (gx, gy), "DefaultCombatState=AttackRuns",
                "ShipCategory=Unclassified", "HangarDesignation=General", "IsShipyard=false", "IsOrbitalDefense=false", "IsCarrierOnly=false",
                "# Made by the Balance Editor's design generator - ship rules after crunchy gremlin's Ship content reference (BB+ team)",
                "# Maps module UIDs to Index, first UID has index 0", "ModuleUIDs=" + ";".join(uids), "Modules=%d" % len(placed),
                "# gridX,gridY;moduleUIDIndex;sizeX,sizeY;turretAngle;moduleRot;hangarShipUID"]
        body = []
        for x, y, i, (sx, sy), rot in sorted(placed, key=lambda p: (p[1], p[0])):
            ln = "%d,%d;%d" % (x, y, i)
            if (sx, sy) != (1, 1) or rot:
                ln += ";%d,%d" % (sx, sy)
            if rot:
                ln += ";0;%d" % rot
            body.append(ln)
        text = nl.join(head + body) + nl
        di = DesignInfo(P.root / "ShipDesigns" / (name + ".design"), P.root / "ShipDesigns", False, text=text)
        rep = design_report(P, di, self.ctx)
        grid = self.ascii(hull, cells, placed, uids, cols, rows)
        return text, notes, di, rep, grid

    def ascii(self, hull, cells, placed, uids, cols, rows):
        """A text picture of the result: C command, E engine, P power, W weapon, S shield, A armour, H cargo, o ordnance, # other; . empty slot."""
        sym = {"Command": "C", "Engine": "E", "PowerPlant": "P", "Turret": "W", "MainGun": "W", "MissileLauncher": "W", "Shield": "S", "Armor": "A",
               "Storage": "H", "Ordnance": "o"}
        pic = [[" "] * cols for _ in range(rows)]
        for (x, y) in cells:
            pic[y][x] = "."
        for x, y, i, (sx, sy), _r in placed:
            m = self.ctx["modmap"].get(uids[i].lower())
            ch = sym.get(m.get("ModuleType").strip() if m is not None else "", "#")
            for yy in range(y, y + sy):
                for xx in range(x, x + sx):
                    pic[yy][xx] = ch
        return "\n".join(" ".join(r) for r in pic)


class HullDoc(FieldDoc):
    """A .hull file: Key=Value lines, Thruster lines and a Slots grid (rows of cells separated by |, each cell the letters of the slot
    kinds it holds: I inner, O outer, E engine, C command; ___ = no slot). Only what you edit is rewritten; every other line stays."""
    vanilla, kind = False, "hulls"

    def __init__(self, path, root, text=None, bom=False, enc="utf-8"):
        super().__init__()
        self.path = Path(path)
        self.rel = self.path.relative_to(root)
        self.root_dir = Path(root)
        if text is None:
            self.text, self.bom, self.enc = read_file(self.path)
        else:
            self.text, self.bom, self.enc = text, bom, enc
        self.new = text is not None
        self.nested, self.removed_tags, self.root_tag = set(), set(), "Hull"
        slots, thr, ins = [], [], False
        for ln in self.text.splitlines():
            if ins:
                if ln.strip():
                    slots.append([("" if not (t := c.strip()).strip("_") else t) for c in ln.split("|")])
            elif ln.strip() == "Slots":
                ins = True
            elif ln.startswith("Thruster="):
                thr.append(ln[len("Thruster="):].strip())
            else:
                m = re.match(r"^([A-Za-z_]\w*)=(.*)$", ln)
                if m and m.group(1) not in self.orig:
                    self.orig[m.group(1)] = m.group(2).strip()
        w = max((len(r) for r in slots), default=0)
        for r in slots:
            r.extend([""] * (w - len(r)))
        self.orig_slots, self.slots = [list(r) for r in slots], slots
        self.orig_thr, self.thrusters = list(thr), list(thr)
        self.cur = dict(self.orig)
        self.base = dict(self.orig)

    # ---- slots
    def cols(self):
        return max((len(r) for r in self.slots), default=0)

    def _size(self):
        self.set("Size", "%d,%d" % (self.cols(), len(self.slots)))

    def add_row(self, bottom=True):
        self.slots.insert(len(self.slots) if bottom else 0, [""] * max(1, self.cols()))
        self._size()

    def del_row(self, bottom=True):
        if len(self.slots) > 1:
            self.slots.pop(-1 if bottom else 0)
            self._size()

    def add_col(self, right=True):
        for r in self.slots:
            r.insert(len(r) if right else 0, "")
        self._size()

    def del_col(self, right=True):
        if self.cols() > 1:
            for r in self.slots:
                r.pop(-1 if right else 0)
            self._size()

    def grow(self, top=0, bottom=0, left=0, right=0):
        """Add empty rows / columns round the grid."""
        w = self.cols() + left + right
        for r in self.slots:
            r[0:0] = [""] * left
            r.extend([""] * right)
        self.slots[0:0] = [[""] * w for _ in range(top)]
        self.slots.extend([[""] * w for _ in range(bottom)])
        self._size()

    def resize(self, cols, rows):
        """Exactly cols x rows: new cells are empty, extra cells on the right / bottom are cut."""
        rows, cols = max(1, rows), max(1, cols)
        self.slots = [(r + [""] * cols)[:cols] for r in self.slots][:rows]
        while len(self.slots) < rows:
            self.slots.append([""] * cols)
        self._size()

    def flood(self, r, c, val):
        """Bucket fill: every connected cell holding the same as (r, c) becomes val. Returns the cells changed."""
        if not (0 <= r < len(self.slots) and 0 <= c < self.cols()):
            return 0
        old, n, stack = self.slots[r][c], 0, [(r, c)]
        if old == val:
            return 0
        while stack:
            i, j = stack.pop()
            if 0 <= i < len(self.slots) and 0 <= j < self.cols() and self.slots[i][j] == old:
                self.slots[i][j] = val
                n += 1
                stack += [(i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)]
        return n

    def kinds(self):
        """{'all': cells with a slot, 'I': .., 'O': .., 'E': .., 'C': ..}"""
        out = {"all": 0, "I": 0, "O": 0, "E": 0, "C": 0}
        for r in self.slots:
            for v in r:
                if v:
                    out["all"] += 1
                    for ch in set(v):
                        if ch in out:
                            out[ch] += 1
        return out

    def mirror(self):
        """Copy the left half of every row onto the right half, flipped."""
        for r in self.slots:
            n = len(r)
            for i in range(n // 2):
                r[n - 1 - i] = r[i]

    def slots_changed(self):
        return self.slots != self.orig_slots

    def revert_slots(self):
        self.slots = [list(r) for r in self.orig_slots]
        self.thrusters = list(self.orig_thr)

    def struct_changed(self):
        return self.slots_changed() or self.thrusters != self.orig_thr

    # ---- FieldDoc / save interface
    def edited(self):
        return FieldDoc.has_changes(self) or self.struct_changed()

    def has_changes(self):
        return self.new or self.edited()

    def changes(self):
        out = FieldDoc.changes(self)
        if self.slots_changed():
            n = sum(1 for a, b in zip(self.orig_slots, self.slots) for x, y in zip(a, b) if x != y) if len(self.orig_slots) == len(self.slots) else 0
            out.append(("Slots", "%d x %d" % (max((len(r) for r in self.orig_slots), default=0), len(self.orig_slots)),
                        "%d x %d%s" % (self.cols(), len(self.slots), (" (%d cells changed)" % n) if n else "")))
        if self.thrusters != self.orig_thr:
            out.append(("Thruster", "; ".join(self.orig_thr), "; ".join(self.thrusters)))
        if self.new:
            out.append(("NEW FILE", "", str(self.rel)))
        return out

    def render(self):
        text = self.text
        nl = "\r\n" if "\r\n" in text else "\n"
        lines = text.splitlines()
        si = next((i for i, l in enumerate(lines) if l.strip() == "Slots"), len(lines))
        head, new_head, done, thr_done = lines[:si], [], set(), False
        for ln in head:
            if ln.startswith("Thruster="):
                if not thr_done:
                    new_head += ["Thruster=" + t for t in self.thrusters]
                    thr_done = True
                continue
            m = re.match(r"^([A-Za-z_]\w*)=(.*)$", ln)
            if m and m.group(1) in self.orig:
                k = m.group(1)
                if k in done:
                    new_head.append(ln)
                    continue
                done.add(k)
                new_head.append(ln if self.cur.get(k) == self.orig.get(k) else "%s=%s" % (k, self.cur.get(k, "")))
            else:
                new_head.append(ln)
        at = next((i for i, l in enumerate(new_head) if l.startswith("#Thruster") or l.startswith("Thruster=")), len(new_head))
        extra = ["%s=%s" % (k, v) for k, v in self.cur.items() if k not in self.orig and v != ""]
        new_head[at:at] = extra
        if not thr_done and self.thrusters:
            new_head += ([] if any(l.startswith("#Thruster") for l in new_head) else ["#Thruster PosX,PosY,PosZ,Scale"]) + ["Thruster=" + t for t in self.thrusters]
        if self.slots_changed() or si == len(lines):
            tail_blank = 0
            for l in reversed(lines):
                if l.strip():
                    break
                tail_blank += 1
            rows = ["|".join(("___" if not c else (c + "   ")[:3]) for c in r) for r in self.slots]
            out = new_head + ["Slots"] + rows + [""] * (tail_blank if si < len(lines) else 0)
        else:
            out = new_head + lines[si:]
        return nl.join(out) + (nl if text.endswith("\n") or si == len(lines) else "")

    def encode(self, text):
        return encode(text, self.bom, self.enc)

    def mark_saved(self, text):
        self.text = text
        self.orig = dict(self.cur)
        self.orig_slots = [list(r) for r in self.slots]
        self.orig_thr = list(self.thrusters)
        self.new = False


class FileCopyDoc:
    """A picture copied into the mod (Textures\\Modules\\<UID>.png ...). Staged in memory; written when you Save."""
    new = True

    def __init__(self, src, path, root, tex):
        self.src, self.path, self.tex = Path(src), Path(path), tex          # tex = "TechIcons/<UID>" (texture path, no extension)
        self.rel = self.path.relative_to(root)

    def has_changes(self):
        return True

    def changes(self):
        return [("NEW FILE", "", "%s   (copy of %s)" % (self.rel, self.src))]

    def render(self):
        return self.src.read_bytes()

    def encode(self, data):
        return data

    def mark_saved(self, _data):
        self.new = False


class TextFileDoc(FileCopyDoc):
    """A brand-new small text file (for example a copied ship design) staged in memory; written, with the folder made, when you Save."""
    def __init__(self, path, root, text, bom=False, enc="utf-8", tex="", note=""):
        self.src, self.path, self.tex = Path(path), Path(path), tex
        self.rel = self.path.relative_to(root)
        self.text, self.bom, self.enc, self.note = text, bom, enc, note

    def changes(self):
        return [("NEW FILE", "", "%s   %s" % (self.rel, self.note))]

    def render(self):
        return self.text

    def encode(self, data):
        return encode(data, self.bom, self.enc)


def tech_template(header, uid, ttype, cost, name_i, desc_i, nl="\n", root_node=None, icon=""):
    """The text of a brand-new Technology file (same shape as the mod's own tech files). root_node makes it the head of a new
    line of research (the left-hand list in the game's research screen); icon is that line's IconPath."""
    lines = ['<?xml version="1.0" encoding="utf-8"?>', header or "<Technology>",
             "  <Version>2</Version>",
             "  <UID>%s</UID>" % xml_escape(uid),
             "  <TechnologyType>%s</TechnologyType>" % xml_escape(ttype),
             "  <Cost>%s</Cost>" % xml_escape(str(cost))]
    if root_node is not None:
        lines += ["  <RootNode>%d</RootNode>" % root_node, "  <Name>%s</Name>" % xml_escape(uid)]
    lines += ["  <NameIndex>%s</NameIndex>" % name_i,
              "  <DescriptionIndex>%s</DescriptionIndex>" % desc_i]
    if icon:
        lines.append("  <IconPath>%s</IconPath>" % xml_escape(icon))
    lines += ["  <ModulesUnlocked />", "  <BuildingsUnlocked />", "  <BonusUnlocked />",
              "  <TroopsUnlocked />", "  <HullsUnlocked />", "</Technology>", ""]
    return nl.join(lines)


def module_template(header, v, restrictions, weapon, nl="\n"):
    """Blank ShipModule file with every tag the game's own modules carry, in the same order and grouping."""
    e = lambda k: xml_escape(str(v.get(k, "")))
    lines = ['<?xml version="1.0"?>', header, "",
             "  <DroneModule>false</DroneModule>", "",
             "  <Cost>10</Cost>", "  <TechLevel>1</TechLevel>",
             "  <!-- common traits shared by all ship modules -->",
             "  <ModuleType>%s</ModuleType>" % e("ModuleType"),
             "  <XSize>%s</XSize>" % e("XSize"), "  <YSize>%s</YSize>" % e("YSize"),
             "  <Name>%s</Name>" % e("Name"),
             "  <Restrictions>%s</Restrictions>" % xml_escape(restrictions),
             "  <UID>%s</UID>" % e("UID"),
             "  <IconTexturePath>%s</IconTexturePath>" % e("IconTexturePath"),
             "  <Mass>1</Mass>", "  <HealthMax>100</HealthMax>",
             "  <Description>%s</Description>" % e("Description"), "",
             "  <PowerDraw>0</PowerDraw>", "",
             "  <NameIndex>%s</NameIndex>" % e("NameIndex"),
             "  <DescriptionIndex>%s</DescriptionIndex>" % e("DescriptionIndex"), "",
             "  <!-- for shield items -->",
             "  <ShieldPowerMax>0</ShieldPowerMax>", "  <ShieldRechargeDelay>0</ShieldRechargeDelay>",
             "  <ShieldRechargeRate>0</ShieldRechargeRate>", "  <ShieldRadius>0</ShieldRadius>", "  <radius>0</radius>", "",
             "  <!-- for PowerPlant Items -->",
             "  <PowerFlowMax>0</PowerFlowMax>", "  <PowerStoreMax>0</PowerStoreMax>", "",
             "  <!-- for Weapons -->",
             "  <WeaponType>%s</WeaponType>" % e("WeaponType"),
             "  <FieldOfFire>%d</FieldOfFire>" % (180 if weapon else 0),
             "  <OrdinanceCapacity>0</OrdinanceCapacity>", "",
             "  <!-- for Engines -->", "  <Thrust>0</Thrust>", "", "</ShipModule>", ""]
    return nl.join(lines)


def tech_layout(proj, cat):
    """Lay the techs of one category out like the game: a column per step along LeadsTo, a row per branch (the first follow-on
    stays in its parent's row, every further one starts a new row). Returns (nodes [(tech, col, row)], edges [(a, b)])."""
    techs = [t for t in proj.techs if proj.tech_category(t) == cat]
    # Like the game, which follows the LeadsTo links and ignores folders: a tech filed in another folder whose ONLY parents
    # are in this category (e.g. Advanced Materials, in Physics, led to by Armor Theory) is drawn here, in its place in the chain.
    by_uid = {t.uid.lower(): t for t in proj.techs}
    parents = {}
    for t in proj.techs:
        for u in t.leads:
            k = by_uid.get(u.lower())
            if k is not None:
                parents.setdefault(id(k), []).append(t)
    inside = {id(t) for t in techs}
    for t in proj.techs:
        if id(t) in inside or t.root_node:
            continue
        ps = parents.get(id(t))
        if ps and all(id(p) in inside for p in ps):
            techs.append(t)
    mine = {t.uid.lower(): t for t in techs}
    kids = {id(t): [mine[u.lower()] for u in t.leads if u.lower() in mine] for t in techs}
    has_parent = {id(k) for ks in kids.values() for k in ks}
    pos, row = {}, [0]

    def lay(t, col):
        if id(t) in pos:
            return
        pos[id(t)] = (col, row[0])
        for i, k in enumerate(kids[id(t)]):
            if id(k) in pos:
                continue
            if i > 0:
                row[0] += 1
            lay(k, col + 1)
    roots = sorted((t for t in techs if id(t) not in has_parent), key=lambda t: (sort_key(t.get("Cost")), t.uid.lower()))
    for r in roots + sorted(techs, key=lambda t: t.uid.lower()):     # 2nd pass: anything only reachable through a loop
        if id(r) not in pos:
            lay(r, 0)
            row[0] += 1
    nodes = [(t, pos[id(t)][0], pos[id(t)][1]) for t in techs]
    edges = [(t, k) for t in techs for k in kids[id(t)]]
    return nodes, edges



class TextEntry(FieldDoc):
    def __init__(self, key, id_):
        super().__init__()
        self.key, self.id, self.idx, self.id_line = key, id_, None, None   # idx = line of the ENG value
        self.key_line = self.end_line = None     # first / one-past-last line of this entry's block in the file
        self.new = False            # created by an auto-fix, not written to the file yet
        self.external = False       # belongs to the base game's GameText (shown, never edited)
        self.orig = {"Id": str(id_)}
        self.cur = dict(self.orig)
        self.base = dict(self.orig)

    def ro(self, tag):
        return self.external or tag == "Id" or (self.idx is None and not self.new)

    def defaultable(self, tag):                  # the Id can't be typed in, but "default" may restore it
        return not self.external and (tag == "Id" or not self.ro(tag))

    def has_changes(self):
        return self.new or super().has_changes()


class GameText:
    """GameText.yaml, parsed line by line (the file has quirks a YAML parser
    would choke on), so only the ENG / Id lines you edit are ever rewritten."""

    def __init__(self, path, root):
        self.path = Path(path)
        self.rel = self.path.relative_to(root)
        self.text, self.bom, self.enc = read_file(self.path)
        self.indent = "  "                    # indentation of the Id / ENG lines (copied for entries added by auto-fix)
        self.removed = []                    # entries deleted by an auto-fix (their lines go when saved)
        self._parse()

    def _parse(self):
        self.lines = re.findall(r"[^\n]*\n|[^\n]+", self.text)
        self.entries, self.by_id, self.dups = [], {}, 0
        key = ent = None
        key_line = None
        first = True
        for i, ln in enumerate(self.lines):
            s = ln.rstrip("\r\n")
            if s.startswith("#") or not s.strip():
                continue
            if not s[0].isspace():
                if s.rstrip().endswith(":"):
                    key, ent, key_line = s.rstrip()[:-1].strip(), None, i
                continue
            m = re.match(r"\s+Id:\s*(\d+)\s*$", s)
            if m and key is not None:
                ent = TextEntry(key, int(m.group(1)))
                ent.id_line, ent.key_line = i, key_line
                if first:
                    self.indent, first = re.match(r"\s*", s).group(0), False
                self.entries.append(ent)
                if ent.id in self.by_id:
                    self.dups += 1
                else:
                    self.by_id[ent.id] = ent
                continue
            m = re.match(r"\s+ENG:\s?(.*)$", s)
            if m and ent is not None and ent.idx is None:
                ent.idx = i
                ent.orig["ENG"] = parse_yaml_str(m.group(1))
                ent.cur["ENG"] = ent.orig["ENG"]
                ent.base["ENG"] = ent.orig["ENG"]
        self._block_ends()

    def _block_ends(self):
        """end_line of every entry: the block runs to the next key line (trailing blank / comment lines belong to the next one)."""
        keys = sorted({e.key_line for e in self.entries if e.key_line is not None})
        end = {}
        for n, k in enumerate(keys):
            t = keys[n + 1] if n + 1 < len(keys) else len(self.lines)
            while t > k + 1 and (not self.lines[t - 1].strip() or self.lines[t - 1].lstrip().startswith("#")):
                t -= 1
            end[k] = t
        for e in self.entries:
            e.end_line = end.get(e.key_line)

    def remove_entry(self, e):
        """Delete an entry (its whole block) when saved."""
        if e in self.entries:
            self.entries.remove(e)
            if not e.new:
                self.removed.append(e)
            self.reindex()

    def can_remove(self, e):
        """Only a block that holds nothing but this entry can be cut out of the file safely."""
        return e.new or (e.key_line is not None and e.end_line is not None
                         and sum(1 for x in self.entries if x.key_line == e.key_line) == 1)

    def restore_removed(self):
        if self.removed:
            self.entries.extend(self.removed)
            self.removed = []
            self.reindex()

    def reindex(self):
        """Rebuild the Id lookup (after an Id was changed or reverted)."""
        self.by_id, self.dups = {}, 0
        for e in self.entries:
            try:
                e.id = int(str(e.cur.get("Id", e.id)).strip())
            except ValueError:
                pass
            if e.id in self.by_id:
                self.dups += 1
            else:
                self.by_id[e.id] = e

    def add_entry(self, key, id_, eng):
        """A new text entry, appended to the end of the file when saved. Layout = the Id / ENG lines the
        file already uses (same indentation and line endings)."""
        used = {e.key for e in self.entries}
        base = re.sub(r"[^\w.\-]", "_", key) or "Text"
        k, n = base, 2
        while k in used:
            k, n = "%s_%d" % (base, n), n + 1
        e = TextEntry(k, int(id_))
        e.new = True
        e.orig["ENG"] = e.cur["ENG"] = e.base["ENG"] = eng
        self.entries.append(e)
        self.reindex()
        return e

    def has_changes(self):
        return bool(self.removed) or any(e.has_changes() for e in self.entries)

    def changes(self):
        out = [("DELETE text entry Id %s (%s)" % (e.orig.get("Id"), e.key), e.orig.get("ENG"), "(deleted)") for e in self.removed]
        for e in self.entries:
            if e.new:
                out.append(("NEW text entry Id %s (%s)" % (e.cur.get("Id"), e.key), None, e.cur.get("ENG")))
                continue
            for tag, old, new in e.changes():
                out.append(("Id %s (%s) %s" % (e.orig.get("Id"), e.key, tag), old, new))
        return out

    def render(self):
        lines = list(self.lines)
        for e in self.entries:
            if e.new:
                continue
            if e.idx is not None and e.changed("ENG"):
                ln = lines[e.idx]
                s = ln.rstrip("\r\n")
                indent = re.match(r"\s*", s).group(0)
                lines[e.idx] = '%sENG: "%s"%s' % (indent, yaml_escape(e.cur["ENG"]), ln[len(s):])
            if e.id_line is not None and e.changed("Id"):
                digits = re.sub(r"\D", "", e.cur["Id"]) or e.orig["Id"]
                lines[e.id_line] = re.sub(r"(Id:\s*)\d+", lambda m: m.group(1) + digits, lines[e.id_line], count=1)
        drop = set()
        for e in self.removed:
            drop.update(range(e.key_line, e.end_line))
        out = "".join(l for i, l in enumerate(lines) if i not in drop)
        added = [e for e in self.entries if e.new]
        if added:
            nl = "\r\n" if "\r\n" in self.text else "\n"
            if out and not out.endswith("\n"):
                out += nl
            for e in added:
                digits = re.sub(r"\D", "", e.cur.get("Id", "")) or str(e.id)
                out += "%s:%s%sId: %s%s%sENG: \"%s\"%s" % (e.key, nl, self.indent, digits, nl, self.indent,
                                                           yaml_escape(e.cur.get("ENG", "")), nl)
        return out

    def encode(self, text):
        return encode(text, self.bom, self.enc)

    def mark_saved(self, text):
        self.text = text
        self.lines = re.findall(r"[^\n]*\n|[^\n]+", text)
        for e in self.entries:
            if e.new:                           # now part of the file: remember where its lines are
                e.new = False
                for k in range(len(self.lines) - 1, -1, -1):
                    if self.lines[k].strip() == e.key + ":" and k + 2 < len(self.lines) + 1:
                        e.key_line, e.id_line, e.idx = k, k + 1, k + 2
                        break
            e.orig = dict(e.cur)
        if self.removed:                        # lines moved up: re-read every entry's position
            self.removed = []
            keep = self.entries
            self._parse()
            fresh = {(e.key, e.id): e for e in self.entries}
            for e in keep:
                f = fresh.get((e.key, e.id))
                if f is not None:
                    e.key_line, e.id_line, e.idx, e.end_line = f.key_line, f.id_line, f.idx, f.end_line
            self.entries = keep
            self.reindex()
        else:
            self._block_ends()


class DelFile:
    """Stands in for a file that is going to be deleted on Save (shows in the review list and the unsaved-change count)."""
    deleted, new, vanilla = True, False, False

    def __init__(self, doc):
        self.doc, self.path, self.rel = doc, doc.path, doc.rel

    def has_changes(self):
        return True

    def changes(self):
        return [("DELETE this file", self.rel.as_posix(), "(deleted - a copy goes to %s)" % BACKUP_DIR)]


class Project:
    def _mark(self, name):
        """Startup timing: how long each loading step took (shown after opening, and saved next to the backups)."""
        now = time.perf_counter()
        self.timings.append((name, now - self._t_last))
        self._t_last = now
        self.log_step("%-40s %6.2f s" % (name, self.timings[-1][1]))

    progress = None                        # set by the loading bar while a mod loads: called with each step's text

    def log_step(self, msg, reset=False):
        """Writes one line at once to Test Reports and Backups/startup_log.txt, so if loading ever hangs the last line shows where."""
        cb = Project.progress
        if cb is not None and not reset:
            try:
                cb(msg)
            except Exception:
                pass
        try:
            d = Path(self.root) / BACKUP_DIR
            d.mkdir(exist_ok=True)
            with open(d / "startup_log.txt", "w" if reset else "a", encoding="utf-8") as f:
                f.write("%s  %s\n" % (time.strftime("%H:%M:%S"), msg))
        except Exception:
            pass

    def __init__(self, root):
        self.root = Path(root)
        migrate_backup_dir(self.root)
        self.log_step("loading %s  (%s)" % (root, VERSION), reset=True)
        self.errors = []
        self.timings, self._t_last = [], time.perf_counter()
        self.settings = self._load_settings()
        self.dirs, self._bad = {}, set()
        self.modules = self._load_xml("shipmodules")
        self._mark("mod modules")
        self.weapons = self._load_xml("weapons")
        self._mark("mod weapons")
        self.buildings = self._load_xml("buildings")
        self._mark("mod buildings")
        self.hulls, self.base_hulls = self._load_hulls(), []
        self._mark("mod hulls")
        self.events, self.base_events = [], []
        self.races, self.troops, self.systems, self.traits, self.encounters, self.dialogs = [], [], [], [], [], []                  # race / troop / solar system files of the mod
        self.base_races, self.base_troops, self.base_systems, self.base_traits, self.base_encounters, self.base_dialogs = [], [], [], [], [], []   # the same from the base game (copied into the mod when edited)
        self._load_gdocs()
        self._mark("mod races / troops / systems / traits")
        self.base_modules, self.base_weapons, self.base_buildings = [], [], []      # base-game (vanilla) items, read only until edited
        self.techs = self._load_xml("technology", TechDoc)
        self._mark("mod technology")
        self.text = None
        tp = self._find_text()
        if tp:
            try:
                self.text = GameText(tp, self.root)
            except Exception as e:
                self.errors.append("%s: %s" % (tp.name, e))
        self._mark("GameText.yaml")
        self.rebuild_maps()
        self._mark("maps")
        self._icons = {}
        self._tex = None
        self.tex_counts = {}                # {texture folder: number of images}, filled by texture_index()
        self.bad_icons = {}                 # {image path: why it could not be loaded}  (filled while displaying)
        self.icon_probe = lambda path: None  # the GUI swaps in a real "can this image be opened?" check
        self.icon_guessed = set()           # UIDs whose icon was guessed from the module name (no usable IconTexturePath)
        self.log, self.log_path, self.log_error, self.log_sig = None, None, "", None
        self.game_dir = None
        self.ext_text, self.ext_by_id, self.ext_files = [], {}, []
        self.file_docs = []                         # FileCopyDoc: pictures to copy into the mod on Save
        TechDoc.hull_style_of = lambda n: ((self.hull_by_name(n).get("Style") if self.hull_by_name(n) is not None else "") or "")
        self.deleted = []                           # items deleted this session (files removed on Save): dicts doc/weapon/techs
        self.extra_docs, self._refidx = [], None    # other xml files (techs ...) opened because an auto-fix must change them
        self.reload_log()
        self._mark("game log")
        self.setup_dirs()
        self._mark("find game folders")
        self.load_external_text()
        self._mark("base game text")
        self.load_defaults()
        self._mark("defaults")
        self.load_base()
        _PREREAD.clear()
        self.save_timings()

    STORY_RX = re.compile(r"remnant|stor(?:y|ies)|quest|scenario|saga|campaign", re.I)

    def find_story_files(self):
        """Looks through the mod and the base game for files / folders that could hold the Remnant stories. Returns text lines and writes
        Test Reports and Backups/remnant_story_search.txt."""
        tops = [("mod", self.root)] + [("game", b / "Content") for b in getattr(self, "base_roots", [])] + [("game", b) for b in getattr(self, "base_roots", [])]
        seen, names, inside = set(), [], []
        skip = {"textures", "sounds", "audio", "video", "videos", "fonts", "model", "models", BACKUP_DIR.lower(), "shipdesigns"}
        for label, top in tops:
            try:
                if not top.is_dir():
                    continue
            except OSError:
                continue
            for dp, dns, fns in os.walk(top):
                rel0 = Path(dp).relative_to(top)
                dns[:] = [d for d in dns if d.lower() not in skip]
                if len(rel0.parts) > 6:
                    dns[:] = []
                for nm in list(dns) + list(fns):
                    full = Path(dp) / nm
                    if full in seen:
                        continue
                    seen.add(full)
                    if self.STORY_RX.search(nm):
                        names.append("%-5s %s" % (label, full))
                for fn in fns:
                    full = Path(dp) / fn
                    if fn.lower().endswith((".xml", ".yaml", ".txt")) and "Races" not in rel0.parts:
                        try:
                            if full.stat().st_size > 400000:
                                continue
                            txt = full.read_text(encoding="utf-8-sig", errors="ignore")
                        except OSError:
                            continue
                        m = re.search(r"remnant", txt, re.I)
                        if m and not self.STORY_RX.search(fn):
                            a_ = max(0, m.start() - 40)
                            inside.append("%-5s %s   ...%s..." % (label, full, re.sub(r"\s+", " ", txt[a_:m.end() + 60])))
        lines = ["Remnant story search %s" % time.strftime("%Y-%m-%d %H:%M:%S"), "Looked in: %s" % ", ".join(str(t[1]) for t in tops), "",
                 "FILES AND FOLDERS WITH A STORY-LIKE NAME (%d) - story / quest / scenario names first:" % len(names)] + sorted(
                     names, key=lambda x: 0 if re.search(r"stor(?:y|ies)|quest|scenario|saga|campaign", x.split(None, 1)[1].rsplit(os.sep, 1)[-1], re.I) else 1)[:200] + [
                 "", "OTHER FILES THAT MENTION 'Remnant' (outside the Races folder) (%d):" % len(inside)] + inside[:200]
        try:
            d = self.root / BACKUP_DIR
            d.mkdir(exist_ok=True)
            (d / "remnant_story_search.txt").write_text("\n".join(lines) + "\n", encoding="utf-8")
        except OSError:
            pass
        return lines

    def disk_stamps(self):
        """{file: (modified time, size)} of every file the editor has read - used to notice changes made outside the editor."""
        out = {}
        for d in self.all_docs():
            p = getattr(d, "path", None)
            if p is None or str(p) in out:
                continue
            try:
                st = os.stat(p)
                out[str(p)] = (st.st_mtime_ns, st.st_size)
            except OSError:
                out[str(p)] = None
        return out

    def external_changes(self):
        """(changed, removed) file paths: files that are different on disk from when the editor read / last saved them."""
        old = getattr(self, "_stamps", None)
        if not old:
            return [], []
        now = self.disk_stamps()
        changed = [k for k, v in now.items() if k in old and v != old[k] and v is not None]
        gone = [k for k, v in now.items() if k in old and v is None and old[k] is not None]
        return changed, gone

    def timing_text(self):
        tot = sum(t for _n, t in self.timings)
        return "Loaded in %.1f s: " % tot + ", ".join("%s %.1f" % (n, t) for n, t in self.timings if t >= 0.05)

    def save_timings(self):
        try:
            d = self.root / BACKUP_DIR
            d.mkdir(parents=True, exist_ok=True)
            (d / "startup_timing.txt").write_text("\n".join("%7.2f s  %s" % (t, n) for n, t in self.timings)
                                                 + "\n%7.2f s  TOTAL (project data only)\n" % sum(t for _n, t in self.timings), encoding="utf-8")
        except OSError:
            pass

    # ---- settings (kept next to the backups)
    def _settings_path(self):
        return self.root / BACKUP_DIR / SETTINGS_FILE

    def _load_settings(self):
        try:
            d = json.loads(self._settings_path().read_text(encoding="utf-8"))
            if not isinstance(d, dict):
                d = {}
        except Exception:
            d = {}
        d.setdefault("extra_texture_dirs", [])
        d.setdefault("ignored", [])
        d.setdefault("log_path", "")
        return d

    def save_settings(self):
        try:
            p = self._settings_path()
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(json.dumps(self.settings, indent=1), encoding="utf-8")
        except Exception:
            pass

    # ---- the game's blackbox.log
    def candidate_logs(self):
        """blackbox.log files found next to the mod, the game, or this program."""
        out, seen = [], set()
        bases = [self.root, Path(__file__).resolve().parent] + list(self.root.parents)[:4]
        if self.game_dir:
            bases.insert(0, self.game_dir)
        home = Path.home()                                  # some builds write the log under Documents / AppData instead
        for extra in (home / "Documents", os.environ.get("APPDATA"), os.environ.get("LOCALAPPDATA")):
            if not extra:
                continue
            extra = Path(extra)
            bases.append(extra)
            try:
                bases += [extra / n for n in os.listdir(extra) if re.search(r"(?i)stardrive|blackbox", n)]
            except OSError:
                pass
        for b in bases:
            try:
                for n in os.listdir(b):
                    p = Path(b) / n
                    if n.lower() in LOG_NAMES and p.is_file() and str(p).lower() not in seen:
                        seen.add(str(p).lower())
                        out.append(p)
            except OSError:
                pass
        return out

    def reload_log(self, path=None):
        """(Re)read the game log. Returns True when something new was loaded. path = the user picked a file."""
        if path:
            self.settings["log_path"] = str(path)
            self.save_settings()
        chosen = None
        pick = self.settings.get("log_path")
        if pick and Path(pick).is_file():
            chosen = Path(pick)
        else:
            c = self.candidate_logs()
            if c:
                chosen = max(c, key=lambda p: p.stat().st_mtime)
        if not chosen:
            changed = self.log is not None or self.log_sig is not None
            self.log, self.log_path, self.log_sig = None, None, None
            self.log_error = ""
            return changed
        try:
            st = chosen.stat()
            sig = (str(chosen), st.st_mtime, st.st_size)
        except OSError:
            return False
        if sig == self.log_sig:
            return False
        self.log_sig, self.log_path, self.log_error = sig, chosen, ""
        try:
            self.log = parse_game_log(chosen)
        except Exception as e:
            self.log, self.log_error = None, "Could not read %s: %s" % (chosen.name, e)
        old = self.game_dir
        if self.log and self.log.game_dir and Path(self.log.game_dir).is_dir():
            self.game_dir = Path(self.log.game_dir)
        if old != self.game_dir and hasattr(self, "icon_dirs"):      # the log told us where the game is
            self.setup_dirs()
            self.load_external_text()
            self.load_base()
        return True

    # ---- where textures / base text live
    def setup_dirs(self):
        dirs = [self.root / "Textures"]
        bases = ([self.game_dir] if self.game_dir else []) + list(self.root.parents)[:3]
        for anc in bases:                               # the base game's textures, e.g. ...\StarDrivePlus64\Content
            dirs += [anc / "Content" / "Textures", anc / "Content"]
        extra = [Path(x) for x in self.settings.get("extra_texture_dirs", [])]
        dirs += extra + [self.root]
        seen, out = set(), []
        for d in dirs:
            k = str(d).lower()
            if k not in seen and d.is_dir():
                seen.add(k)
                out.append(d)
        self.icon_dirs = out
        self.other_mod_dirs = []                        # the Textures of the other mods next to this one: only offered in the picture pickers, never counted as 'found'
        try:
            for sib in sorted(self.root.parent.iterdir(), key=lambda x: x.name.lower()):
                if sib.is_dir() and sib.resolve() != self.root.resolve() and (sib / "Textures").is_dir():
                    self.other_mod_dirs.append((sib.name, sib / "Textures"))
        except (OSError, ValueError):
            pass
        self.extra_dirs = {str(d).lower() for d in extra}
        self.base_roots, _seen = [], set()
        for a in bases:
            if (a / "Content").is_dir() and str(a).lower() not in _seen:
                _seen.add(str(a).lower())
                self.base_roots.append(a)
        if not self.game_dir and self.base_roots:
            self.game_dir = self.base_roots[0]
        self._icons.clear()
        self._tex = None
        self._any = None
        self.tex_counts = {}

    def load_external_text(self):
        """The base game's GameText (read only): modules copied from the game may use its text Ids."""
        self.ext_text, self.ext_by_id, self.ext_files = [], {}, []
        own = self.text.path.resolve() if self.text else None
        seen = set()
        for base in self.base_roots:
            top = base / "Content"
            for dp, dns, fns in os.walk(top):
                depth = len(Path(dp).relative_to(top).parts)
                dns[:] = [d for d in dns if d.lower() not in TEXT_SKIP_DIRS] if depth < 4 else []
                for fn in fns:
                    low = fn.lower()
                    if not (low.startswith("gametext") and low.endswith((".yaml", ".yml"))):
                        continue
                    p = Path(dp) / fn
                    try:
                        rp = p.resolve()
                    except OSError:
                        continue
                    if rp in seen or rp == own or self.root.resolve() in rp.parents:
                        continue
                    seen.add(rp)
                    try:
                        g = GameText(p, p.parent)
                    except Exception:
                        continue
                    for e in g.entries:
                        e.external = True
                        self.ext_by_id.setdefault(e.id, e)
                    self.ext_text.append(g)
                    self.ext_files.append((p, len(g.entries)))

    def text_display(self, m, tag):
        """The text a module shows in game - from this mod, else from the base game. For DISPLAY only."""
        e = self.text_for(m, tag)
        if e:
            return e
        v = m.get(tag).strip()
        return self.ext_by_id.get(int(v)) if v.isdigit() else None

    BUILDING_IDENTITY = ("Name", "Icon", "NameTranslationIndex", "DescriptionIndex", "ShortDescriptionIndex", "ShortDescription", "Cost", "Maintenance")

    def building_effect_tags(self):
        """Every building tag the game's building files use apart from name / picture / text ids / cost, commonest first."""
        n = {}
        for d in self.buildings + self.base_buildings:
            for t in d.cur:
                if t not in self.BUILDING_IDENTITY and t not in d.nested:
                    n[t] = n.get(t, 0) + 1
        return sorted(n, key=lambda t: (-n[t], t))

    def create_building_spec(self, sp):
        """The New building wizard's result -> a new building file (+ GameText entries, picture), staged until Save.
        sp: name desc short folder cost maint icon(key, path) effects[(tag, value)]. Returns the building's XmlDoc."""
        name = sp["name"].strip()
        if not name or not re.fullmatch(r"[^\\/:*?\"<>|]+", name):
            raise ValueError("The building's name is empty or has characters a file name cannot hold.")
        if self.building_by_name(name) is not None:
            raise ValueError("A building called '%s' already exists (mod or base game)." % name)
        folder = (sp.get("folder") or "").strip().strip("\\/")
        if folder and not re.fullmatch(r"[^\\/:*?\"<>|]+", folder):
            raise ValueError("Folder name is not valid.")
        path = self.vanilla_dest("buildings", Path(folder) / (name + ".xml"))
        if path.exists():
            raise ValueError("%s already exists." % path.name)
        sib = next((d for d in self.buildings if not d.new), None) or next(iter(self.base_buildings), None)
        nl = "\r\n" if sib and "\r\n" in sib.text else "\n"
        ni = di = si = 0
        if self.text:
            ni = self.next_text_id()
            di, si = ni + 1, ni + 2
            self.text.add_entry("BB_Building_%s_Name" % re.sub(r"\W+", "_", name), ni, name)
            self.text.add_entry("BB_Building_%s_Desc" % re.sub(r"\W+", "_", name), di, sp.get("desc", "").strip() or name)
            self.text.add_entry("BB_Building_%s_ShortDesc" % re.sub(r"\W+", "_", name), si, sp.get("short", "").strip() or sp.get("desc", "").strip() or name)
        icon = ""
        k, pic = sp.get("icon") or ("__none", None)
        safe = re.sub(r"\W+", "_", name).strip("_") or "Building"
        if k == "__import":                          # BB+ naming: Textures\Buildings\icon_<Icon>_64x64.png and <Icon>safe in the xml
            self.stage_copy(pic, "Buildings", "icon_%s_64x64" % safe)
            icon = safe
        elif k not in ("__none", "__same"):
            m = re.fullmatch(r"icon_(.+?)_\d+x\d+", k, re.I)
            icon = m.group(1) if m else k
        elif k == "__same":
            icon = sp.get("same_icon", "")
        E = lambda v: xml_escape(str(v))
        lines = ['<?xml version="1.0" encoding="utf-8"?>', "<Building>", "  <Name>%s</Name>" % E(name)]
        if icon:
            lines.append("  <Icon>%s</Icon>" % E(icon))
        lines.append("")
        if str(sp.get("cost", "")).strip():
            lines.append("  <Cost>%s</Cost>" % E(sp["cost"]))
        if str(sp.get("maint", "")).strip():
            lines.append("  <Maintenance>%s</Maintenance>" % E(sp["maint"]))
        lines.append("")
        for tag, val in sp.get("effects") or []:
            lines.append("  <%s>%s</%s>" % (tag, E(val), tag))
        lines += ["", "  <!-- For localization in GameText.yaml -->", "  <NameTranslationIndex>%d</NameTranslationIndex>" % ni,
                  "  <DescriptionIndex>%d</DescriptionIndex>" % di, "  <ShortDescriptionIndex>%d</ShortDescriptionIndex>" % si, "</Building>", ""]
        doc = XmlDoc(path, self.root, text=nl.join(lines), bom=sib.bom if sib else True, enc=sib.enc if sib else "utf-8")
        self.buildings.append(doc)
        self.rebuild_maps()
        self._icons.clear()
        return doc

    def is_building(self, d):
        return any(d is b for b in self.buildings) or any(d is b for b in self.base_buildings)

    def pic_for(self, d):
        """The picture of a module or a building."""
        return self.building_pic(d) if self.is_building(d) else self.find_icon(d)

    def set_icon(self, kind, obj, key, path):
        """Change a tech's / module's / building's picture. key = '__import' (path = a file on the computer) or an existing picture's name
        (path = where it is); the picture is copied into the mod's Textures folder when you Save."""
        if key in ("__keep", "__none") or obj is None:
            return
        if kind == "module":
            uid = (obj.get("UID") or obj.path.stem).strip()
            if key == "__import":
                self.stage_copy(path, "Modules", uid, replace=True)
                key = uid
            obj.set("IconTexturePath", "Modules/" + key)
        elif kind == "building":
            if key == "__import":
                safe = re.sub(r"\W+", "_", doc_key(obj)).strip("_") or "Building"
                self.stage_copy(path, "Buildings", "icon_%s_64x64" % safe, replace=True)
                icon = safe
            else:
                m = re.fullmatch(r"icon_(.+?)_\d+x\d+", key, re.I)
                icon = m.group(1) if m else key
            obj.set("Icon", icon)
        elif kind == "tech":
            self.stage_copy(path, "TechIcons", obj.uid, replace=True)          # TechIcons\<tech UID> is the picture the game looks for
        self._icons.clear()

    # ---- deleting (staged until Save; the files go into the backup folder first, so the Recycle Bin can bring them back)
    def unlock_refs(self, doc):
        """[(tech, [entries])] of the techs that unlock this module / building."""
        key, isb, out = doc_key(doc).strip().lower(), self.is_building(doc), []
        for t in self.techs:
            n = [b for b in t.buildings if b.strip().lower() == key] if isb else [p for p in t.unlocks if p[0].strip().lower() == key]
            if n:
                out.append((t, n))
        return out

    def exclusive_weapon(self, doc):
        """The module's own weapon file when no other module fires it (and it is a mod file), else None."""
        if self.is_building(doc):
            return None
        w = self.weapon_for(doc)
        if w is None or getattr(w, "vanilla", False) or not any(w is x for x in self.weapons):
            return None
        wt = doc.get("WeaponType").strip().lower()
        if any(m is not doc and m.get("WeaponType").strip().lower() == wt for m in self.modules + self.base_modules):
            return None
        return w

    # ---- undo: snapshots of everything editable
    def snapshot(self):
        lists = {n: list(getattr(self, n)) for n in ("modules", "weapons", "techs", "buildings", "hulls", "extra_docs", "file_docs", "deleted",
                                                      "races", "troops", "systems", "traits", "encounters", "dialogs", "events")}
        docs = list(self.modules) + list(self.weapons) + list(self.techs) + list(self.buildings) + self.base_modules + self.base_weapons \
            + self.base_buildings + list(self.hulls) + self.base_hulls + list(self.extra_docs) + self.gdocs()
        if self.text:
            lists["t_entries"], lists["t_removed"] = list(self.text.entries), list(self.text.removed)
            docs += list(self.text.entries) + list(self.text.removed)
        out = {}
        for d in docs:
            ex = None
            if isinstance(d, TechDoc):
                ex = (list(d.leads), list(d.unlocks), list(d.bonuses), list(d.buildings), d.path, list(d.hulls), list(d.troops), dict(d.hull_type))
            elif isinstance(d, HullDoc):
                ex = ("hull", [list(r) for r in d.slots], list(d.thrusters))
            elif isinstance(d, GameDoc):
                ex = ("gdoc", {k: list(v) for k, v in d.lists.items()}, dict(d.cpaths))
            out[id(d)] = (d, dict(d.cur), frozenset(getattr(d, "removed_tags", ())), ex)
        return {"lists": lists, "docs": out}

    @staticmethod
    def snap_diff(a, b):
        """How many files / entries differ between two snapshots (0 = identical)."""
        n = 0 if a["lists"] == b["lists"] else 1
        for k in set(a["docs"]) | set(b["docs"]):
            x, y = a["docs"].get(k), b["docs"].get(k)
            if x is None or y is None or x[1:] != y[1:]:
                n += 1
        return n

    def restore_snapshot(self, snap):
        """Put everything back as it was in the snapshot. Returns True when files / entries were added or removed (tables must be rebuilt)."""
        grew = False
        for n, l in snap["lists"].items():
            if n.startswith("t_"):
                continue
            cur = getattr(self, n)
            if cur != l:
                grew = True
                cur[:] = l
                if n == "file_docs":
                    self.designs = None
        if self.text and "t_entries" in snap["lists"]:
            if self.text.entries != snap["lists"]["t_entries"]:
                grew = True
            self.text.entries[:] = snap["lists"]["t_entries"]
            self.text.removed[:] = snap["lists"]["t_removed"]
        for d, cur, rt, ex in snap["docs"].values():
            d.cur.clear()
            d.cur.update(cur)
            if hasattr(d, "removed_tags"):
                d.removed_tags = set(rt)
            if ex is not None and ex[0] == "gdoc":
                d.lists = {k: list(v) for k, v in ex[1].items()}
                d.cpaths = dict(ex[2])
            elif ex is not None and ex[0] == "hull":
                d.slots, d.thrusters = [list(r) for r in ex[1]], list(ex[2])
            elif ex is not None:
                d.leads, d.unlocks, d.bonuses, d.buildings = list(ex[0]), list(ex[1]), list(ex[2]), list(ex[3])
                d.hulls = list(ex[5])
                d.troops = list(ex[6]) if len(ex) > 6 else d.troops
                d.hull_type = dict(ex[7]) if len(ex) > 7 else d.hull_type
                d.path = ex[4]
                d.rel = d.path.relative_to(d.root_dir)
        if self.text:
            self.text.reindex()
        self._races = None
        self._icons.clear()
        self.rebuild_maps()
        return grew

    def can_delete(self, doc):
        return not getattr(doc, "vanilla", False) and (any(doc is m for m in self.modules) or any(doc is b for b in self.buildings)
                                                       or any(doc is h for h in self.hulls) or any(doc is g for g in self.gdocs(False)))

    def delete_item(self, doc):
        """Take a module / building (and its own weapon, and every tech unlock of it) out. Files go when you Save."""
        if not self.can_delete(doc):
            raise ValueError("Items of the base game cannot be deleted from the mod (they are not in the mod's folder).")
        isb = self.is_building(doc)
        w = self.exclusive_weapon(doc)
        techs = []
        for t, n in self.unlock_refs(doc):
            if isb:
                t.buildings[:] = [b for b in t.buildings if b not in n]
            else:
                t.unlocks[:] = [p for p in t.unlocks if p not in n]
            techs.append((t, n))
        (self.buildings if isb else self.modules).remove(doc)
        if w is not None:
            self.weapons.remove(w)
        rec = {"doc": doc, "weapon": w, "techs": techs, "building": isb}
        if doc.path.exists() or (w is not None and w.path.exists()):
            self.deleted.append(rec)
        elif self.text:                                   # never saved: its new text entries go with it
            ids = set()
            for x in (doc, w):
                for tag in ("NameIndex", "DescriptionIndex", "NameTranslationIndex", "ShortDescriptionIndex"):
                    v = x.get(tag).strip() if x is not None else ""
                    if v.isdigit():
                        ids.add(int(v))
            keep = [e for e in self.text.entries if not (e.new and e.id in ids)]
            if len(keep) != len(self.text.entries):
                self.text.entries = keep
                self.text.reindex()
        self._races = None
        self.modules_dropped = True
        self._icons.clear()
        self.rebuild_maps()
        return rec

    def delete_tech(self, t, branch=False):
        """Take a tech out (and, with branch, everything that only follows from it). Techs that led to it lead to what it led to
        instead, so the tree stays joined. The files go when you Save. Returns the list of techs removed."""
        group = self.branch_of(t) if branch else [t]
        if not branch and t.root_node and t.leads:
            raise ValueError("%s heads a line of research: delete the whole branch, or move its follow-on techs first." % self.tech_name(t))
        recs = []
        for x in group:
            x.path = x.orig_path
            x.rel = x.path.relative_to(x.root_dir)
            edits = []
            for o in self.techs:
                if any(o is g for g in group) or not any(u.lower() == x.uid.lower() for u in o.leads):
                    continue
                o.leads[:] = [u for u in o.leads if u.lower() != x.uid.lower()]
                added = []
                if not branch:
                    for u in x.leads:
                        if u.lower() not in {a.lower() for a in o.leads} and u.lower() != o.uid.lower():
                            o.leads.append(u)
                            added.append(u)
                edits.append((o, x.uid, added))
            recs.append({"doc": x, "weapon": None, "techs": [], "building": False, "kind": "tech", "leads": edits})
        for rec in recs:
            x = rec["doc"]
            self.techs[:] = [y for y in self.techs if y is not x]
            if x.path.exists():
                self.deleted.append(rec)
            elif self.text:
                ids = {int(x.get(tag).strip()) for tag in ("NameIndex", "DescriptionIndex") if x.get(tag).strip().isdigit()}
                keep = [e for e in self.text.entries if not (e.new and e.id in ids)]
                if len(keep) != len(self.text.entries):
                    self.text.entries = keep
                    self.text.reindex()
        self.rebuild_maps()
        return [r["doc"] for r in recs]

    def undelete(self, rec):
        if rec not in self.deleted:
            return
        self.deleted.remove(rec)
        if rec.get("kind") == "gdoc":
            getattr(self, rec["doc"].kind).append(rec["doc"])
            return
        if rec.get("kind") == "hull":
            self.hulls.append(rec["doc"])
            for t, n in rec["techs"]:
                t.hulls.extend(h for h in n if h not in t.hulls)
            self._hulls = None
            return
        if rec.get("kind") == "file":
            self.extra_docs.append(rec["doc"])
            self.designs = None
            self._design_files = None
            return
        if rec.get("kind") == "tech":
            self.techs.append(rec["doc"])
            for o, uid, added in rec.get("leads", ()):
                o.leads[:] = [u for u in o.leads if u not in added]
                if uid not in o.leads:
                    o.leads.append(uid)
            self.rebuild_maps()
            return
        (self.buildings if rec["building"] else self.modules).append(rec["doc"])
        if rec["weapon"] is not None:
            self.weapons.append(rec["weapon"])
        for t, n in rec["techs"]:
            for e in n:
                if rec["building"] and e not in t.buildings:
                    t.buildings.append(e)
                elif not rec["building"] and e not in t.unlocks:
                    t.unlocks.append(e)
        self._races = None
        self.modules_dropped = True
        self.rebuild_maps()

    def recycle_entries(self):
        """Every file in the backup folders: [{stamp, rel, backup, current, exists, same, size}] newest first."""
        rows, base = [], self.root / BACKUP_DIR
        if not base.is_dir():
            return rows
        for sd in sorted(base.iterdir(), key=lambda p: p.name, reverse=True):
            if not (sd.is_dir() and re.fullmatch(r"\d{8}_\d{6}", sd.name)):
                continue
            for dp, _dn, fns in os.walk(sd):
                for fn in sorted(fns):
                    p = Path(dp) / fn
                    rel = p.relative_to(sd)
                    cur = self.root / rel
                    size = p.stat().st_size
                    same = False
                    if cur.exists():
                        try:
                            same = cur.stat().st_size == size and cur.read_bytes() == p.read_bytes()
                        except OSError:
                            pass
                    rows.append({"stamp": sd.name, "rel": rel, "backup": p, "current": cur, "exists": cur.exists(), "same": same, "size": size})
        return rows

    def restore_backup(self, e):
        """Copy a backed-up file back (the file it replaces is backed up first). The caller reloads the project."""
        stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        cur = e["current"]
        data = e["backup"].read_bytes()                                  # read first: the new backup may land in the same folder
        if cur.exists():
            keep = self.root / BACKUP_DIR / stamp / e["rel"]
            if keep.exists():
                keep = keep.with_name(keep.name + ".prev")
            keep.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(cur, keep)
        cur.parent.mkdir(parents=True, exist_ok=True)
        cur.write_bytes(data)
        log = self.root / BACKUP_DIR / "changelog.csv"
        fresh = not log.exists()
        with open(log, "a", newline="", encoding="utf-8") as f:
            w = csv.writer(f)
            if fresh:
                w.writerow(["timestamp", "file", "field", "old", "new"])
            w.writerow([stamp, e["rel"].as_posix(), "RESTORED file", "", "from backup " + e["stamp"]])

    def building_pic(self, bd):
        """The picture of a building: its <Icon> as a texture (Buildings\\<icon>, <icon>), else any image of that name in the game's Content."""
        ic = bd.get("Icon").strip()
        if not ic:
            return None
        for cand in ("Buildings/icon_%s_64x64" % ic, "Buildings/icon_%s_48x48" % ic, "Buildings/icon_" + ic,      # BB+: Textures\\Buildings\\icon_<Icon>_64x64
                     "Buildings/" + ic, ic, "UI/Buildings/" + ic):
            p = self.find_file(cand)
            if p:
                return p
        hits = self.find_by_name(ic)
        return hits[0] if hits else None

    def building_by_name(self, name):
        n = (name or "").strip().lower()
        return next((d for d in self.buildings + self.base_buildings if doc_key(d).lower() == n), None)

    def text_display_by_id(self, i):
        return (self.text.by_id.get(i) if self.text else None) or self.ext_by_id.get(i)

    def text_known(self, i):
        return bool((self.text and i in self.text.by_id) or i in self.ext_by_id)

    UINT16_TAGS = ("NameIndex", "DescriptionIndex")        # a module's text Ids are 16-bit numbers in the game (0 - 65535)

    def next_text_id(self):
        top = max([e.id for e in self.text.entries] or [0]) if self.text else 0
        if self.ext_by_id:
            top = max(top, max(self.ext_by_id))
        if top + 1 > 65535:                       # a module's NameIndex / DescriptionIndex cannot be bigger: stay in the mod's own range
            used = {e.id for e in self.text.entries} if self.text else set()
            used |= set(self.ext_by_id or ())
            mine = [e.id for e in self.text.entries] if self.text else []
            for i in range(max(mine or [0]) + 1, 65536):
                if i not in used:
                    return i
            for i in range(max(min(mine or [1]), 1), 65536):
                if i not in used:
                    return i
        return top + 1

    def number_problems(self):
        """[(module, tag, value)] for text Ids the game cannot read (it loads the whole mod as 'failed' and drops back to vanilla)."""
        out = []
        for m in self.modules:
            for tag in self.UINT16_TAGS:
                v = m.get(tag).strip()
                if v and not (re.fullmatch(r"\d+", v) and int(v) <= 65535):
                    out.append((m, tag, v))
        return out

    def prune_added(self):
        """Drop auto-fix text entries nothing points at any more (e.g. after 'Revert changes')."""
        t = self.text
        if not t or not any(e.new for e in t.entries):
            return
        used = set()
        for m in self.modules + self.techs + self.extra_docs:
            for tag in ("NameIndex", "DescriptionIndex"):
                v = m.get(tag).strip()
                if v.isdigit():
                    used.add(int(v))
        for tc in self.techs:
            for bn in tc.bonuses:
                v = bonus_get(bn, "BonusIndex")
                if v.isdigit():
                    used.add(int(v))
        for td in list(self.traits) + list(self.base_traits):           # racial traits point at their texts by TraitIndex / Description
            try:
                for it in td.lists.get("traits", ()):
                    for tg in ("TraitIndex", "Description"):
                        v = str(trait_get(it, tg)).strip()
                        if v.isdigit():
                            used.add(int(v))
            except Exception:
                pass
        keep = [e for e in t.entries if not e.new or e.id in used]
        if len(keep) != len(t.entries):
            t.entries = keep
            t.reindex()

    def load_defaults(self):
        """'Default' = the value a field had in the OLDEST backup of its file (i.e. before this editor ever
        changed it). With no backups yet it is simply the value found when the mod was opened."""
        broot = self.root / BACKUP_DIR
        try:
            stamps = sorted(d for d in broot.iterdir() if d.is_dir())
        except Exception:
            return
        for doc in self.modules + self.weapons:
            for st in stamps:
                p = st / doc.rel
                if p.is_file():
                    try:
                        doc.base = dict(XmlDoc(p, st).orig)
                    except Exception:
                        pass
                    break
        if self.text:
            for st in stamps:
                p = st / self.text.rel
                if p.is_file():
                    try:
                        entries = GameText(p, st).entries
                        old = {(e.key, e.id): e for e in entries}
                        keys = {}
                        for e in entries:
                            keys.setdefault(e.key, []).append(e)
                        mine = {}
                        for e in self.text.entries:
                            mine.setdefault(e.key, []).append(e)
                        for e in self.text.entries:
                            o = old.get((e.key, e.id))
                            if o is None and len(keys.get(e.key, [])) == 1 and len(mine[e.key]) == 1:
                                o = keys[e.key][0]                  # same key, Id was changed since
                                e.base["Id"] = o.orig["Id"]
                            if o is not None and "ENG" in o.orig:
                                e.base["ENG"] = o.orig["ENG"]
                    except Exception:
                        pass
                    break

    def img_exts(self):
        return (".png", ".gif", ".dds", ".xnb") + (tuple(e for e in PIL_EXTS if e != ".dds") if Image else ())     # .dds / .xnb: built-in readers

    def texture_index(self):
        """{lower-case file name without extension: [path relative to a Textures folder, no extension]}"""
        if self._tex is None:
            idx, exts = {}, self.img_exts()
            for d in self.icon_dirs:
                if d.name.lower() != "textures" and str(d).lower() not in self.extra_dirs:
                    continue
                n = 0
                try:
                    for p in d.rglob("*"):
                        if p.is_file() and p.suffix.lower() in exts and BACKUP_DIR not in p.parts:
                            idx.setdefault(p.stem.lower(), []).append(p.relative_to(d).with_suffix("").as_posix())
                            n += 1
                except Exception:
                    pass
                self.tex_counts[d] = n
            self._tex = idx
        return self._tex

    def any_image_index(self):
        """{lower-case file name without extension: [paths]} for every image-like file (incl. .xnb) in the mod and the
        game's Content folder - for textures the game keeps outside Textures\\ (projectile textures, models ...)."""
        if self._any is None:
            idx, exts = {}, {".png", ".gif", ".dds", ".tga", ".bmp", ".jpg", ".jpeg", ".xnb"}
            skip = {"shipmodules", "weapons", "sounds", "audio", "video", "videos", "fonts", BACKUP_DIR.lower()}
            for top in [self.root] + [b / "Content" for b in self.base_roots]:
                for dp, dns, fns in os.walk(top):
                    dns[:] = [d for d in dns if d.lower() not in skip]
                    for fn in fns:
                        st, ext = os.path.splitext(fn)
                        if ext.lower() in exts:
                            idx.setdefault(st.lower(), []).append(Path(dp) / fn)
            self._any = idx
        return self._any

    def find_by_name(self, rel):
        """Files whose NAME matches the last part of a texture path, wherever they are (viewable formats first)."""
        leaf = (rel or "").replace("\\", "/").rsplit("/", 1)[-1]
        for e in (".png", ".gif", ".xnb") + PIL_EXTS:
            if leaf.lower().endswith(e):
                leaf = leaf[:-len(e)]
        hits = list(self.any_image_index().get(leaf.lower(), []))
        hits.sort(key=lambda p: (p.suffix.lower() not in self.img_exts(), len(str(p))))
        return hits

    def revert_all(self):
        n = len(self.deleted)
        for rec in list(self.deleted):
            self.undelete(rec)
        gone_m = [m for m in self.modules if m.new]                 # modules created in this session
        if gone_m:
            self.modules = [m for m in self.modules if not m.new]
            self.modules_dropped = True
            self._races = None
            n += len(gone_m)
        gone_w = [w for w in self.weapons if w.new]                  # weapons created in this session
        if gone_w:
            self.weapons = [w for w in self.weapons if not w.new]
            self.modules_dropped = True
            n += len(gone_w)
        if self.file_docs:
            n += len(self.file_docs)
            self.file_docs = []
            self._icons.clear()
            self.designs = None
        for kn in ("races", "troops", "systems", "traits", "encounters", "dialogs", "events"):          # race / troop / system / trait files created in this session
            gone_g = [g for g in getattr(self, kn) if g.new]
            if gone_g:
                getattr(self, kn)[:] = [g for g in getattr(self, kn) if not g.new]
                n += len(gone_g)
        for g in self.gdocs():
            if g.lists_changed():
                g.revert_lists()
                n += 1
        gone_h = [h for h in self.hulls if h.new]                    # ships created in this session
        if gone_h:
            self.hulls[:] = [h for h in self.hulls if not h.new]
            n += len(gone_h)
        for h in self.hulls + self.base_hulls:
            if h.struct_changed():
                h.revert_slots()
                n += 1
        gone = [t for t in self.techs if t.new]                      # techs created in this session
        if gone:
            self.techs = [t for t in self.techs if not t.new]
            n += len(gone)
        for t in self.techs:
            if t.struct_changed():
                t.revert_struct()
                n += 1
        docs = (list(self.modules) + list(self.weapons) + list(self.techs) + list(self.buildings) + self.base_modules + self.base_weapons
                + self.base_buildings + self.hulls + self.base_hulls + list(self.extra_docs) + self.gdocs() + (list(self.text.entries) if self.text else []))
        for d in docs:
            for tag in list(d.cur) + list(getattr(d, "removed_tags", ())):
                if d.changed(tag):
                    d.revert(tag)
                    n += 1
        if self.text and self.text.removed:                          # entries deleted by an auto-fix: back again
            self.text.restore_removed()
            n += 1
        if self.text and any(e.new for e in self.text.entries):     # text entries made by auto-fixes: gone again
            self.text.entries = [e for e in self.text.entries if not e.new]
            n += 1
        if self.text:
            self.text.reindex()
        self._icons.clear()
        self.rebuild_maps()
        return n

    def default_all(self):
        n = 0
        docs = list(self.modules) + list(self.weapons) + (list(self.text.entries) if self.text else [])
        for d in docs:
            for tag in list(d.base):
                if d.defaultable(tag) and d.differs_default(tag):
                    d.set_default(tag)
                    n += 1
        return n

    def find_file(self, rel):
        """Find a .png/.gif by a texture path like 'Modules/Assault_Cannon_Type20' (mod folder first, then game)."""
        rel = (rel or "").strip().replace("\\", "/").lstrip("/")
        if not rel:
            return None
        if rel in self._icons:
            return self._icons[rel]
        key = re.sub(r"^textures/", "", os.path.splitext(rel)[0] if rel.lower().endswith(self.img_exts()) else rel, flags=re.I).lower()
        for fd in self.file_docs:                               # a picture that is staged but not saved yet
            if fd.tex.lower() == key and fd.src.is_file():
                self._icons[rel] = fd.src
                return fd.src
        exts = self.img_exts()
        names = [rel] if rel.lower().endswith(exts) else [rel + e for e in exts]
        if rel.lower().startswith("textures/"):
            names += [n[9:] for n in names]
        found = None
        for d in self.icon_dirs:
            for n in names:
                if (d / n).is_file():
                    found = d / n
                    break
            if found:
                break
        self._icons[rel] = found
        return found

    def find_icon(self, m):
        """The module's icon file. If its IconTexturePath is missing / wrong, try Modules/<UID> (the usual naming) so
        the editor still shows something; such modules are listed in icon_guessed and flagged in the Debug tab."""
        uid = m.get("UID") or m.path.stem
        p = self.find_file(m.get("IconTexturePath"))
        if p:
            self.icon_guessed.discard(uid)
            return p
        for rel in ("Modules/" + uid, "Modules/" + m.path.stem):
            p = self.find_file(rel)
            if p:
                self.icon_guessed.add(uid)
                return p
        self.icon_guessed.discard(uid)
        return None

    def find_other(self, rel):
        """A file for this texture path in a format this editor can't display (.xnb, or .dds without Pillow), if one exists."""
        rel = (rel or "").strip().replace("\\", "/").lstrip("/")
        leaf = rel.rsplit("/", 1)[-1]
        base = rel[:rel.rfind(".")] if "." in leaf else rel
        skip = PIL_EXTS if Image else (".dds",)
        for d in self.icon_dirs:
            for e in OTHER_EXTS:
                if e not in skip and (d / (base + e)).is_file():
                    return d / (base + e)
        return None

    def find_anim(self, rel):
        """Check an AnimationPath like 'Kinetic_Red/Kinetic_Red_cc_' (a folder + frame-name prefix)."""
        rel = (rel or "").strip().replace("\\", "/").strip("/")
        parent, _sep, prefix = rel.rpartition("/")
        folder_seen = False
        for d in self.icon_dirs:
            dd = d / parent if parent else d
            if dd.is_dir():
                folder_seen = True
                if any(f.name.lower().startswith(prefix.lower()) for f in dd.iterdir() if f.is_file()):
                    return "ok"
        return "no frames" if folder_seen else "no folder"

    def race_info(self):
        if getattr(self, "_races", None) is None:
            self._races = build_race_info(self)
        return self._races

    def extra_doc(self, path):
        """An xml file outside ShipModules / Weapons opened for editing (saved and backed up like the others)."""
        for d in self.techs + self.extra_docs:
            if d.path == Path(path):
                return d
        try:
            d = XmlDoc(path, self.root)
        except Exception:
            return None
        self.extra_docs.append(d)
        return d

    def salvage_designs(self):
        """[(design name, file)] for the salvage ship designs in the mod: files in any folder called *salvage*
        (fallback: any design / xml file with 'salvage' in its name). The name is the file name, or the Name written inside."""
        if getattr(self, "_salvage", None) is None:
            found, skip = [], {"textures", "sounds", "audio", "video", "videos", "model", "models", "fonts", BACKUP_DIR.lower()}
            skip_ext = {".png", ".gif", ".dds", ".xnb", ".tga", ".jpg", ".bmp", ".log", ".csv", ".txt", ".md", ".json", ".hull"}
            for want_dir in (True, False):
                for dp, dns, fns in os.walk(self.root):
                    dns[:] = [d for d in dns if d.lower() not in skip]
                    in_dir = "salvage" in Path(dp).name.lower()
                    for fn in fns:
                        p = Path(dp) / fn
                        if p.suffix.lower() in skip_ext:
                            continue
                        if (in_dir if want_dir else ("salvage" in p.stem.lower() and p.suffix.lower() in (".design", ".xml", ".yaml"))):
                            names = []                       # the design's own Name= line is what races refer to; file name only as a fallback
                            try:
                                for line in read_file(p)[0].split("\n")[:40]:
                                    m = re.match(r"^\s*(?:Name\s*=\s*(.+?)|Name:\s*[\"']?(.+?)[\"']?|<Name>\s*(.+?)\s*</Name>)\s*$", line)
                                    if m:
                                        names.append(next(g for g in m.groups() if g).strip())
                                        break
                            except Exception:
                                pass
                            names = names or [p.stem]
                            found += [(n, p) for n in dict.fromkeys(names)]
                if found:
                    break
            self._salvage = found
        return self._salvage

    def race_docs(self):
        """XmlDocs of the race files (xml in a folder called Races)."""
        out = []
        for dp, dns, fns in os.walk(self.root):
            dns[:] = [d for d in dns if d != BACKUP_DIR]
            if Path(dp).name.lower() == "races":
                for fn in sorted(fns):
                    if fn.lower().endswith(".xml"):
                        d = self.extra_doc(Path(dp) / fn)
                        if d is not None:
                            out.append(d)
        return out

    def resolve_game_path(self, rel):
        """A path the game printed ('Content\\Buildings\\x.xml') -> the real file, looked up in the mod and the game folder."""
        rel = (rel or "").replace("\\", "/").strip().lstrip("/")
        bases = [self.root] + ([self.game_dir] if self.game_dir else []) + list(self.root.parents)[:3]
        for b in bases:
            p = Path(b) / rel
            if rel and p.is_file():
                return p
        return None

    def grep_first(self, needle, folders=(), exts=(".xml", ".yaml", ".yml", ".txt"), limit=3000):
        """[(path, line)] of the first file under the given folder names (any case, up to 2 levels down) that contains
        needle. Used to point a log message at the file that probably caused it."""
        key = (needle.lower(), tuple(folders))
        cache = self.__dict__.setdefault("_grep", {})
        if key in cache:
            return cache[key]
        hit, n, nl = [], 0, needle.lower()
        tops = []
        for dp, dns, _fns in os.walk(self.root):
            depth = len(Path(dp).relative_to(self.root).parts)
            dns[:] = [d for d in dns if d != BACKUP_DIR] if depth < 2 else []
            for d in dns:
                if d.lower() in folders:
                    tops.append(Path(dp) / d)
        for top in sorted(tops):
            for dp, _dns, fns in os.walk(top):
                for fn in sorted(fns):
                    if not fn.lower().endswith(exts):
                        continue
                    n += 1
                    if n > limit:
                        break
                    try:
                        text = read_file(Path(dp) / fn)[0]
                    except Exception:
                        continue
                    if nl in text.lower():
                        ln = next(k for k, line in enumerate(text.split("\n"), 1) if nl in line.lower())
                        hit = [(Path(dp) / fn, ln)]
                        break
                if hit or n > limit:
                    break
            if hit or n > limit:
                break
        cache[key] = hit
        return hit

    def kind_dirs(self, kind):
        """The folder(s) holding one kind of file (modules / weapons / techs). The usual name is used when it exists; a mod that
        names its folders differently is recognised by what the xml files inside are (their root element)."""
        try:
            tops = [p for p in self.root.iterdir() if p.is_dir() and p.name != BACKUP_DIR and not p.name.startswith(".")]
        except OSError:
            return []
        named = [p for p in tops if p.name.lower() == kind]
        if named:
            return named
        want, out = KIND_ROOT[kind], []
        for p in sorted(tops):
            if p.name.lower() in NOT_CONTENT:
                continue
            n = hit = 0
            for f in p.rglob("*.xml"):
                n += 1
                hit += sniff_root(f) == want
                if n >= 6:
                    break
            if n and hit == n:
                out.append(p)
        return out

    def _load_xml(self, folder, cls=XmlDoc):
        docs = []
        self.dirs[folder] = self.kind_dirs(folder)
        for d in self.dirs[folder]:
            files = [p for p in sorted(d.rglob("*")) if p.is_file() and p.suffix.lower() == ".xml"]
            prefetch(files)
            for p in files:
                if True:
                    try:
                        docs.append(cls(p, self.root))
                    except Exception as e:
                        self._bad.add(p)
                        self.errors.append("%s: %s" % (p.relative_to(self.root), e))
        return docs

    # ---- hulls (.hull files: slot grids)
    def hull_root(self):
        ds = self.dirs.get("hulls") or []
        return ds[0] if ds else self.root / "Hulls"

    def _load_hulls(self):
        docs = []
        try:
            self.dirs["hulls"] = [p for p in self.root.iterdir() if p.is_dir() and p.name.lower() == "hulls"]
        except OSError:
            self.dirs["hulls"] = []
        for d in self.dirs["hulls"]:
            for p in sorted(d.rglob("*.hull")):
                try:
                    docs.append(HullDoc(p, self.root))
                except Exception as e:
                    self.errors.append("%s: %s" % (p.relative_to(self.root), e))
        return docs

    def load_base_hulls(self):
        self.base_hulls = []
        mine = set()
        for h in self.hulls:
            mine.add(self.hull_key(h).lower())
            try:
                mine.add(h.path.relative_to(self.hull_root()).with_suffix("").as_posix().lower())
            except ValueError:
                pass
        done = set()
        for d in self.base_kind_dirs("hulls"):
            hfiles = sorted(d.rglob("*.hull"))
            prefetch(hfiles)
            for f in hfiles:
                done.add(str(f).lower())
                sub = f.relative_to(d)
                key = sub.with_suffix("").as_posix().lower()
                if key in mine:
                    continue
                try:
                    doc = HullDoc(f, d.parent)
                except Exception as e:
                    self.errors.append("base hull %s: %s" % (f.name, e))
                    continue
                hk = doc.get("HullName").strip().replace("\\", "/").lower()
                if hk and hk in mine:
                    continue
                mine.add(key)
                if hk:
                    mine.add(hk)
                doc.vanilla, doc.vrel, doc.sub, doc.dest = True, doc.rel, sub, self.hull_root() / sub
                self.base_hulls.append(doc)
        # hulls the game keeps in other places (not in a folder called Hulls): found anywhere under the game folder; the key is
        # <parent folder>/<file name>, which is how designs and techs name them
        self.deep_hulls = 0
        for f in self.deep_hull_files():
            if str(f).lower() in done:
                continue
            sub = Path(f.parent.name) / f.name
            key = sub.with_suffix("").as_posix().lower()
            if key in mine:
                continue
            try:
                doc = HullDoc(f, f.parent.parent)
            except Exception as e:
                self.errors.append("base hull %s: %s" % (f.name, e))
                continue
            mine.add(key)
            doc.vanilla, doc.vrel, doc.sub, doc.dest = True, doc.rel, sub, self.hull_root() / sub
            self.base_hulls.append(doc)
            self.deep_hulls += 1

    def deep_hull_files(self):
        """Every .hull file under the game folders (outside the mod), whatever its folder is called."""
        out, skip = [], self.BASE_SKIP | {"mods", "mod", "saves", "save"}
        for b in getattr(self, "base_roots", []):
            for dp, dns, fns in os.walk(b):
                dp = Path(dp)
                if dp == self.root or self.root in dp.parents:
                    dns[:] = []
                    continue
                try:
                    depth = len(dp.relative_to(b).parts)
                except ValueError:
                    continue
                dns[:] = [x for x in dns if x.lower() not in skip] if depth < 7 else []
                out += [dp / fn for fn in fns if fn.lower().endswith(".hull")]
        return out

    # ---- ship designs (.design files; read only - the game's own design tool edits them)
    def design_dirs(self):
        out = []
        try:
            out += [(p, False) for p in self.root.iterdir() if p.is_dir() and p.name.lower() == "shipdesigns"]
        except OSError:
            pass
        try:
            out += [(p, True) for p in self.base_kind_dirs("shipdesigns")]
        except Exception:
            pass
        return out

    def load_designs(self, force=False):
        if getattr(self, "designs", None) is not None and not force:
            return self.designs
        res, seen = [], set()
        for d, is_base in self.design_dirs():
            for f in sorted(d.rglob("*.design")):
                try:
                    di = DesignInfo(f, d, is_base)
                except Exception as e:
                    self.errors.append("%s: %s" % (f.name, e))
                    continue
                k = di.sub.lower()
                if is_base and k in seen:
                    continue
                seen.add(k)
                res.append(di)
        return self.finish_designs(res)

    def finish_designs(self, res):
        mod_dir = next((p for p, base in self.design_dirs() if not base), self.root / "ShipDesigns")
        for fd in self.file_docs:                         # designs copied for a new race, staged until Save
            if isinstance(fd, TextFileDoc) and fd.path.suffix.lower() == ".design" and not fd.path.exists():
                try:
                    res.append(DesignInfo(fd.path, mod_dir, False, text=fd.text))
                except Exception:
                    pass
        for di in res:                                    # edits made by auto-fixes survive a rescan
            di.doc = next((d for d in self.extra_docs if isinstance(d, DesignDoc) and d.path == di.path), None)
        self.designs = res
        return res

    def saved_designs_dir(self):
        """The folder where the game saves the designs you make (AppData\\...\\StarDrive\\Saved Designs), or None."""
        bases = []
        for env in ("APPDATA", "LOCALAPPDATA"):
            if os.environ.get(env):
                bases.append(Path(os.environ[env]))
        for sub in ("AppData/Roaming", "AppData/Local", "AppData/LocalLow", ".config", "Documents"):
            bases.append(Path.home() / sub)
        for b in bases:
            try:
                if not b.is_dir():
                    continue
                for sd in b.iterdir():
                    if not sd.is_dir() or "stardrive" not in sd.name.lower():
                        continue
                    for dp, dns, _fns in os.walk(sd):
                        if len(Path(dp).relative_to(sd).parts) > 3:
                            dns[:] = []
                        for dn in dns:
                            if re.sub(r"[\s_]", "", dn.lower()) == "saveddesigns":
                                return Path(dp) / dn
            except OSError:
                continue
        return None

    def import_candidates(self, folder):
        """[(DesignInfo, status, target path)] for every .design file in the game's saved-designs folder."""
        folder = Path(folder)
        mod_dir = next((p for p, base in self.design_dirs() if not base), self.root / "ShipDesigns")
        out = []
        for f in sorted(folder.rglob("*.design")):
            try:
                di = DesignInfo(f, folder, False)
            except Exception:
                continue
            seg = di.hull.replace("\\", "/").split("/")[0] if "/" in di.hull.replace("\\", "/") else (di.style or "Imported")
            seg = re.sub(r"[^\w\- ]+", "", seg).strip() or "Imported"
            target = mod_dir / seg / f.name
            if target.exists():
                try:
                    status = "same as the mod's" if target.read_bytes() == f.read_bytes() else "different version in mod"
                except OSError:
                    status = "different version in mod"
            elif any(d.name.strip().lower() == di.name.strip().lower() and not d.is_base for d in self.load_designs()):
                status = "name already used in mod"
            else:
                status = "new"
            out.append((di, status, target))
        return out

    def import_design_file(self, src, target):
        """Copy one saved design into the mod. An older file of that name is backed up first. Returns True if it replaced one."""
        src, target = Path(src), Path(target)
        replaced = target.exists()
        if replaced:
            b = self.root / BACKUP_DIR / (time.strftime("%Y%m%d_%H%M%S") + "_designs") / target.relative_to(self.root)
            b.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(target, b)
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, target)
        return replaced

    def design_doc(self, di):
        """The editable doc behind a mod design (created on first use, kept in extra_docs so Save / Undo / Revert treat it like any file)."""
        if di.is_base:
            raise ValueError("Base-game designs are not changed (copy the design in the game first).")
        if di.doc is None:
            di.doc = next((d for d in self.extra_docs if isinstance(d, DesignDoc) and d.path == di.path), None)
        if di.doc is None:
            di.doc = DesignDoc(di.path, self.root)
            self.extra_docs.append(di.doc)
        return di.doc

    def design_files(self):
        """Every .design file in the mod (cached per scan)."""
        got = getattr(self, "_design_files", None)
        if got is None:
            skip = {"textures", "sounds", "audio", "video", "videos", "model", "models", "fonts", BACKUP_DIR.lower(), "shipmodules", "weapons"}
            got = []
            for dp, dns, fns in os.walk(self.root):
                dns[:] = [x for x in dns if x.lower() not in skip]
                got += [Path(dp) / fn for fn in fns if fn.lower().endswith(".design")]
            self._design_files = got
        return got

    def design_doc_for_path(self, path):
        """Like design_doc but from a file path (the salvage fix has no DesignInfo)."""
        path = Path(path)
        doc = next((d for d in self.extra_docs if isinstance(d, DesignDoc) and path in (d.path, d.orig_path)), None)
        if doc is None:
            doc = DesignDoc(path, self.root)
            self.extra_docs.append(doc)
        return doc

    def design_fix_plan(self, di, ctx):
        """What an auto-fix could safely change in one design: ({'Hull': new} or {}, {old_uid: new_uid}, fuzzy?)."""
        import difflib
        hull_fix, uid_fix, fuzzy = {}, {}, False
        if di.hull:
            h = ctx["find"](di.hull)
            if h is not None:
                key = self.hull_key(h)
                if key.lower() != di.hull.replace("\\", "/").strip().lower():
                    hull_fix["Hull"] = key
            else:
                keys = {k: h2 for k, h2 in ctx["hull_keys"].items()}
                low = di.hull.replace("\\", "/").strip().lower()
                m = difflib.get_close_matches(low, list(keys), n=1, cutoff=0.82)
                if not m:
                    stems = {}
                    for k in keys:
                        stems.setdefault(k.rsplit("/", 1)[-1], []).append(k)
                    sm = difflib.get_close_matches(low.rsplit("/", 1)[-1], list(stems), n=1, cutoff=0.9)
                    if sm and len(stems[sm[0]]) == 1:
                        m = stems[sm[0]]
                if m:
                    hull_fix["Hull"] = self.hull_key(keys[m[0]])
                    fuzzy = True
        names = {u.lower(): u for u in ctx["mod_names"]}
        for u in di.uids:
            ul = u.lower()
            if ul in ctx["mods"] and ul not in ctx["deleted"]:
                continue
            m = difflib.get_close_matches(ul, list(names), n=1, cutoff=0.88)
            if m:
                uid_fix[u] = names[m[0]]
                fuzzy = fuzzy or m[0] != ul
        return hull_fix, uid_fix, fuzzy

    def apply_design_fix(self, di, hull_fix, uid_fix):
        doc = self.design_doc(di)
        if hull_fix.get("Hull") and "Hull" in doc.cur:
            doc.set("Hull", hull_fix["Hull"])
        if uid_fix and "ModuleUIDs" in doc.cur:
            doc.set("ModuleUIDs", ";".join(uid_fix.get(u, u) for u in [x for x in doc.cur["ModuleUIDs"].split(";") if x.strip()]))
        return True

    def design_problems(self, di, ctx=None):
        """[(severity, text)] for one design. ctx = shared lookups from design_context()."""
        c = ctx or self.design_context()
        out = []
        if not di.hull:
            out.append(("ERROR", "The design has no Hull= line."))
        else:
            h = c["find"](di.hull)
            if h is None:
                out.append(("ERROR", "Hull '%s' does not exist (no such .hull file in the mod or the base game)." % di.hull))
            else:
                key = self.hull_key(h)
                if key.lower() != di.hull.replace("\\", "/").strip().lower():
                    out.append(("WARN", "Hull '%s' only matches by file name; the full name is '%s'." % (di.hull, key)))
                try:
                    hs = tuple(int(x) for x in h.get("Size").split(","))
                    if di.size and hs and tuple(di.size) != hs:
                        out.append(("WARN", "Design grid is %dx%d but the hull is %dx%d." % (di.size[0], di.size[1], hs[0], hs[1])))
                except ValueError:
                    pass
                if c["hull_locked"].get(key.lower()) is False and not di.is_base:
                    out.append(("INFO", "No tech unlocks hull '%s', so players cannot build this until it is unlocked some other way." % key))
        if not di.name.strip():
            out.append(("ERROR", "The design has no Name."))
        else:
            same = c["names"].get(di.name.strip().lower(), ())
            exact = [x for x in same if x is not di and x.name.strip() == di.name.strip()]
            if exact:
                out.append(("WARN", "Another design has the same name '%s' (%s)." % (di.name, ", ".join(sorted(x.sub for x in exact)[:3]))))
            elif len(same) > 1:
                out.append(("INFO", "Another design has the same name apart from capitals '%s' (%s) - the game compares names exactly, so these count as different." % (di.name, ", ".join(sorted(x.sub for x in same if x is not di)[:3]))))
            if di.name.strip().lower() != di.path.stem.strip().lower():
                out.append(("INFO", "Name '%s' differs from the file name '%s'." % (di.name, di.path.stem)))
        if di.style and di.hull and "/" in di.hull:
            race = di.hull.split("/")[0]
            if re.sub(r"\W", "", race).lower() != re.sub(r"\W", "", di.style).lower() and re.sub(r"\W", "", di.style).lower() not in re.sub(r"\W", "", race).lower():
                out.append(("INFO", "Style '%s' differs from the hull's folder '%s'." % (di.style, race)))
        if di.mods_declared is not None and di.mods_declared != len(di.slots):
            out.append(("WARN", "Modules=%d but the file lists %d placed modules." % (di.mods_declared, len(di.slots))))
        bad_idx = sorted({i for _x, _y, i, *_r in di.slots if i < 0 or i >= len(di.uids)})
        if bad_idx:
            out.append(("ERROR", "Modules use index %s which is not in ModuleUIDs (only %d entries)." % (", ".join(map(str, bad_idx[:5])), len(di.uids))))
        for u in di.uids:
            ul = u.lower()
            if ul in c["deleted"]:
                out.append(("ERROR", "Module '%s' was deleted (it is in the Recycle Bin)." % u))
            elif ul not in c["mods"]:
                out.append(("ERROR", "Module '%s' does not exist in the mod or the base game." % u))
            elif ul not in c["unlocked"] and not di.is_base:
                out.append(("INFO", "Module '%s' is not unlocked by any tech." % u))
        for hs in sorted({r[3] for r in di.slots if len(r) > 3 and r[3]}):
            if hs.lower() not in c["names"]:
                out.append(("WARN", "Hangar ship '%s' is not the name of any design." % hs))
        return out

    def design_context(self):
        ds = self.load_designs()
        docs = {d.path: d for d in self.extra_docs if isinstance(d, DesignDoc)}
        for di in ds:                                      # follows Undo / Revert: an edit that is gone no longer shows
            di.doc = docs.get(di.path)
        names = {}
        for d in ds:
            names.setdefault(d.name.strip().lower(), []).append(d)
        mods = {(m.get("UID") or m.path.stem).strip().lower() for m in list(self.modules) + list(self.base_modules)}
        modmap = {}
        for m in list(self.modules) + list(self.base_modules):
            modmap.setdefault((m.get("UID") or m.path.stem).strip().lower(), m)
        deleted = set()
        for r in getattr(self, "deleted", []):
            if r.get("kind") in (None, "") and r.get("doc") is not None and not self.is_building(r["doc"]):
                try:
                    deleted.add((r["doc"].get("UID") or r["doc"].path.stem).strip().lower())
                except Exception:
                    pass
        deleted -= {m for m in mods}
        unlocked = {p[0].strip().lower() for t in self.techs for p in t.unlocks}
        unl_h = {n.strip().lower() for t in self.techs for n in t.hulls}
        hull_locked = {}
        for h in list(self.hulls) + list(self.base_hulls):
            k = self.hull_key(h).lower()
            hull_locked[k] = (k in unl_h) if self.techs else None
        by_key, by_stem = {}, {}
        for h in list(self.hulls) + list(self.base_hulls):
            by_key.setdefault(self.hull_key(h).lower(), h)
            by_stem.setdefault(h.path.stem.lower(), h)

        def find(name):
            k = (name or "").strip().replace("\\", "/").lower()
            if k.endswith(".hull"):
                k = k[:-5]
            return by_key.get(k) or by_stem.get(k.rsplit("/", 1)[-1])
        mod_names = [(m.get("UID") or m.path.stem).strip() for m in list(self.modules) + list(self.base_modules)]
        return {"find": find, "modmap": modmap, "hull_keys": by_key, "mod_names": mod_names, "names": names, "mods": mods, "deleted": deleted, "unlocked": unlocked if self.techs else mods, "hull_locked": hull_locked}

    # ---- races, troops, solar systems
    GDOC_SKIP = {"shipmodules", "weapons", "technology", "buildings", "hulls", "shipdesigns", BACKUP_DIR.lower()}

    def gdocs(self, base=True):
        out = list(self.races) + list(self.troops) + list(self.systems) + list(self.traits) + list(self.encounters) + list(self.dialogs) + list(self.events)
        return out + self.base_gdocs() if base else out

    def base_gdocs(self):
        return list(self.base_races) + list(self.base_troops) + list(self.base_systems) + list(self.base_traits) + list(self.base_encounters) + list(self.base_dialogs) + list(self.base_events)

    @staticmethod
    def _english_dialog(p):
        """Diplomacy dialogue files: only the English ones (DiplomacyDialogs/English/...) are listed."""
        parts = [x.lower() for x in Path(p).parts]
        if "diplomacydialogs" in parts:
            rest = parts[parts.index("diplomacydialogs") + 1:-1]
            return not rest or rest[0] == "english"
        return True

    @staticmethod
    def _gdoc_root(p):
        try:
            raw = _PREREAD.get(str(p))
            if raw is not None:
                head = raw[:1200].decode("utf-8", "ignore")
            else:
                with open(p, "rb") as f:
                    head = f.read(1200).decode("utf-8", "ignore")
        except OSError:
            return None
        m = re.search(r"<(EmpireData|Troop|SolarSystemData|RacialTraits|Encounter|DiplomacyDialog|ExplorationEvent)[\s>/]", head)
        return m.group(1) if m else None

    def _load_gdocs(self):
        for dp, dns, fns in os.walk(self.root):
            dns[:] = [d for d in dns if d.lower() not in self.GDOC_SKIP and d.lower() not in ("textures", "sounds", "model", "models", "videos")]
            for fn in sorted(fns):
                if not fn.lower().endswith(".xml"):
                    continue
                p = Path(dp) / fn
                if self._gdoc_root(p) is None:
                    continue
                try:
                    d = open_gdoc(p, self.root)
                    if d.kind == "dialogs" and not self._english_dialog(p):
                        continue
                except Exception as e:
                    self.errors.append("%s: %s" % (p.relative_to(self.root), e))
                    continue
                getattr(self, d.kind).append(d)

    def load_base_gdocs(self):
        for kn in ("races", "troops", "systems", "traits", "encounters", "dialogs", "events"):
            setattr(self, "base_" + kn, [])
        mine = {(d.kind, d.path.stem.lower()) for d in self.gdocs(False)}
        skip = self.BASE_SKIP | self.GDOC_SKIP | {"mods", "mod", "saves", "save"}
        want = {"races", "troops", "solarsystems", "racialtraits", "encounter dialogs", "diplomacydialogs", "exploration events", "explorationevents"}

        def candidates(b):
            """Fast path: the game keeps these files in folders called Races / Troops / SolarSystems / RacialTraits, so only those are read.
            If none exist, every folder is searched like before."""
            tops = [b, b / "Content"]
            fast = []
            for t in tops:
                try:
                    fast += [x for x in t.iterdir() if x.is_dir() and x.name.lower() in want]
                except OSError:
                    pass
            fast = [x for x in fast if not (x == self.root or self.root in x.parents)]
            if fast:
                for x in fast:
                    for f in sorted(x.rglob("*.xml")):
                        yield f
                return
            for dp, dns, fns in os.walk(b):
                dp = Path(dp)
                if dp == self.root or self.root in dp.parents:
                    dns[:] = []
                    continue
                try:
                    depth = len(dp.relative_to(b).parts)
                except ValueError:
                    continue
                dns[:] = [x for x in dns if x.lower() not in skip] if depth < 6 else []
                for fn in sorted(fns):
                    if fn.lower().endswith(".xml"):
                        yield dp / fn
        for b in getattr(self, "base_roots", []):
            cand = list(candidates(b))
            prefetch(cand)
            for f in cand:
                if True:
                    if self._gdoc_root(f) is None:
                        continue
                    try:
                        top = b / "Content" if (b / "Content") in f.parents else b
                        d = open_gdoc(f, top)
                        if d.kind == "dialogs" and not self._english_dialog(f):
                            continue
                    except Exception:
                        continue
                    key = (d.kind, f.stem.lower())
                    if key in mine:
                        continue
                    mine.add(key)
                    d.vanilla, d.vrel, d.dest = True, d.rel, self.root / d.rel
                    getattr(self, "base_" + d.kind).append(d)

    def gdoc_folder(self, kind):
        """The folder of the mod that holds this kind of file (where new ones go)."""
        if kind != "events":
            for d in getattr(self, kind):
                return d.path.parent
        return self.root / {"races": "Races", "troops": "Troops", "systems": "SolarSystems", "traits": "RacialTraits", "encounters": "Encounter Dialogs", "dialogs": Path("DiplomacyDialogs") / "English", "events": "Exploration Events"}[kind]

    TEMPLATES = {
        "events": "<ExplorationEvent>\n  <Name>{name}</Name>\n  <PotentialOutcomes>\n    <Outcome>\n      <Chance>100</Chance>\n      <TitleText>{name}</TitleText>\n"
                  "      <DescriptionText></DescriptionText>\n      <ConfirmText>OK</ConfirmText>\n      <RemoveTrigger>true</RemoveTrigger>\n    </Outcome>\n  </PotentialOutcomes>\n</ExplorationEvent>\n",
        "traits": "<RacialTraits>\n  <TraitList>\n  </TraitList>\n</RacialTraits>\n",
        "races": ("<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<EmpireData xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xmlns:xsd=\"http://www.w3.org/2001/XMLSchema\">\n"
                  "  <PortraitName></PortraitName>\n  <MusicCue></MusicCue>\n  <DiplomacyDialogPath></DiplomacyDialogPath>\n"
                  "  <StartingShip></StartingShip>\n  <StartingScout></StartingScout>\n  <PrototypeShip></PrototypeShip>\n"
                  "  <DefaultSmallTransport></DefaultSmallTransport>\n  <DefaultTroopShip></DefaultTroopShip>\n  <DefaultColonyShip></DefaultColonyShip>\n"
                  "  <DefaultConstructor></DefaultConstructor>\n  <DefaultAssaultShuttle></DefaultAssaultShuttle>\n  <DefaultSupplyShuttle></DefaultSupplyShuttle>\n"
                  "  <DefaultResearchStation></DefaultResearchStation>\n  <DefaultMiningShip></DefaultMiningShip>\n  <DefaultMiningStation></DefaultMiningStation>\n"
                  "  <DefaultSalvageShip></DefaultSalvageShip>\n"
                  "  <ThrustColor0R>200</ThrustColor0R>\n  <ThrustColor0G>200</ThrustColor0G>\n  <ThrustColor0B>255</ThrustColor0B>\n"
                  "  <ThrustColor1R>150</ThrustColor1R>\n  <ThrustColor1G>150</ThrustColor1G>\n  <ThrustColor1B>255</ThrustColor1B>\n"
                  "  <PersonalityTraitsWeights>\n  </PersonalityTraitsWeights>\n  <EconomicTraitsWeights>\n  </EconomicTraitsWeights>\n"
                  "  <RebelName></RebelName>\n  <RebelSing></RebelSing>\n  <RebelPlur></RebelPlur>\n"
                  "  <TroopNameIndex>0</TroopNameIndex>\n  <TroopDescriptionIndex>0</TroopDescriptionIndex>\n"
                  "  <Traits>\n    <Name>{name}</Name>\n    <Singular>{name}</Singular>\n    <Plural>{name}</Plural>\n    <VideoPath></VideoPath>\n"
                  "    <ShipType></ShipType>\n    <Adj1></Adj1>\n    <Adj2></Adj2>\n    <HomeSystemName></HomeSystemName>\n    <HomeworldName></HomeworldName>\n"
                  "    <FlagIndex>0</FlagIndex>\n    <R>128</R>\n    <G>128</G>\n    <B>128</B>\n"
                  "    <TraitSets>\n      <TraitSet>\n        <TraitOptions>\n        </TraitOptions>\n      </TraitSet>\n    </TraitSets>\n  </Traits>\n</EmpireData>\n"),
        "troops": ("<Troop>\n  <Name>{name}</Name>\n  <Description></Description>\n  <Icon>{name}</Icon>\n  <RaceType></RaceType>\n"
                   "  <Cost>50</Cost>\n  <Strength>10</Strength>\n  <MaxStrength>10</MaxStrength>\n  <MaintenanceCost>1</MaintenanceCost>\n"
                   "  <Range>1</Range>\n  <HardAttack>30</HardAttack>\n  <BoardingStrength>50</BoardingStrength>\n  <SoftAttack>35</SoftAttack>\n"
                   "  <TargetType>Soft</TargetType>\n  <Class>Infantry</Class>\n</Troop>\n"),
        "systems": ("<SolarSystemData>\n  <Name>{name}</Name>\n  <RingList>\n    <Ring>\n      <Planet>{home}</Planet>\n"
                    "      <WhichPlanet>25</WhichPlanet>\n      <HomePlanet>true</HomePlanet>\n    </Ring>\n  </RingList>\n</SolarSystemData>\n"),
    }

    def new_gdoc(self, kind, name, base=None, folder=None, template=None):
        """A new race / troop / system file (staged until Save): a copy of `base`, or a small template."""
        name = name.strip()
        if not name or not re.fullmatch(r"[^\\/:*?\"<>|]+", name):
            raise ValueError("The name is empty or has characters a file name cannot hold.")
        path = Path(folder) / (name + ".xml") if folder else self.gdoc_folder(kind) / (name + ".xml")
        if path.exists() or any(d.path == path for d in self.gdocs(False)):
            if any(r["doc"].path == path for r in self.deleted):
                raise ValueError("%s was deleted earlier but the deletion is not saved yet, so the file is still there. Save (Ctrl+S) first, then try again - or use another name." % path.name)
            raise ValueError("%s already exists." % path.name)
        if base is not None:
            text, bom, enc = base.render(), base.bom, base.enc
        else:
            text, bom, enc = self.TEMPLATES[template or kind].format(name=name, home=name + " Prime", ship=re.sub(r"\W+", "", name) or "npc"), False, "utf-8"
        doc = open_gdoc(path, self.root, text=text, bom=bom, enc=enc)
        getattr(self, kind).append(doc)
        return doc

    def delete_gdoc(self, doc):
        if getattr(doc, "vanilla", False) or not any(doc is g for g in self.gdocs(False)):
            raise ValueError("Files of the base game cannot be deleted from the mod.")
        getattr(self, doc.kind)[:] = [g for g in getattr(self, doc.kind) if g is not doc]
        rec = {"doc": doc, "weapon": None, "techs": [], "building": False, "kind": "gdoc"}
        if doc.path.exists():
            self.deleted.append(rec)
        return rec

    TRAIT_SKIP = {"textures", "sounds", "audio", "video", "videos", "fonts", "shipmodules", "weapons", "shipdesigns", "hulls", "model", "models", "gametext",
                  BACKUP_DIR.lower()}

    def _text_files(self, exts):
        out, seen = [], set()
        for top in [self.root] + [b / "Content" for b in self.base_roots] + list(self.base_roots):
            if not top.is_dir():
                continue
            for dp, dns, fns in os.walk(top):
                dns[:] = [d for d in dns if d.lower() not in self.TRAIT_SKIP]
                if len(Path(dp).relative_to(top).parts) > 4:
                    dns[:] = []
                for fn in fns:
                    p = Path(dp) / fn
                    if p.suffix.lower() in exts and p not in seen:
                        seen.add(p)
                        out.append(p)
        return out

    def planet_types(self, reload=False):
        """{number: (name or '', picture path or None)} for the planet numbers a solar system ring can use (WhichPlanet). Found from planet pictures
        (a Planets folder, number at the end of the file name), from any xml that lists planet types, and from the numbers existing systems use."""
        if getattr(self, "_planet_types", None) is not None and not reload:
            return self._planet_types
        names, pics = {}, {}
        exts = self.img_exts()
        tops = [self.root] + [b / "Content" for b in self.base_roots] + list(self.base_roots)
        for top in tops:
            if not top.is_dir():
                continue
            for dp, dns, fns in os.walk(top):
                depth = len(Path(dp).relative_to(top).parts)
                if depth > 3:
                    dns[:] = []
                dns[:] = [d for d in dns if d.lower() not in ("sounds", "audio", "video", "videos", "fonts", "shipmodules", "weapons", "shipdesigns", "model", "models",
                                                              BACKUP_DIR.lower())]
                if Path(dp).name.lower() in ("planets", "planet", "planettypes"):
                    for fn in fns:
                        st, ext = os.path.splitext(fn)
                        m = re.search(r"(\d+)$", st)
                        if m and ext.lower() in exts:
                            pics.setdefault(int(m.group(1)), Path(dp) / fn)
        for p in self._text_files((".xml",)):
            low = p.stem.lower()
            if "planet" not in low or "solar" in low:
                continue
            try:
                root = ET.fromstring(read_file(p)[0].encode("utf-8"))
            except Exception:
                continue
            for el in root.iter():
                kids = {c.tag.lower(): (c.text or "").strip() for c in el if len(c) == 0}
                nm = next((kids[k] for k in ("name", "displayname", "type", "category", "planettype", "title") if kids.get(k)), "")
                nu = next((kids[k] for k in ("id", "whichplanet", "index", "number", "planetid", "typeid") if kids.get(k, "").isdigit()), "")
                if nu and nm and not nm.isdigit():
                    names.setdefault(int(nu), nm)
        used = set()
        for sy in self.systems + self.base_systems:
            for r in sy.lists.get("rings", []):
                v = ring_get(r, "WhichPlanet").strip()
                if v.isdigit():
                    used.add(int(v))
        self._planet_types = {n: (names.get(n, ""), pics.get(n)) for n in sorted(set(names) | set(pics) | used)}
        self._planet_names_found = bool(names)
        return self._planet_types

    def find_dialog(self, name):
        """The diplomacy dialogue file a race's DiplomacyDialogPath names (an .xml with that file name; folders called Diplomacy / Dialog preferred), or None."""
        stem = re.split(r"[\\/]", (name or "").strip())[-1].lower()
        if stem.endswith(".xml"):
            stem = stem[:-4]
        if not stem:
            return None
        hits = [p for p in self._text_files((".xml",)) if p.stem.lower() == stem]
        hits = [p for p in hits if not re.search(r"(^|[\\/])(races|troops|solarsystems)[\\/]", str(p).lower())] or hits
        hits.sort(key=lambda p: (not re.search(r"diplomacydialogs", str(p).lower()), not re.search(r"[\\/]english[\\/]", str(p).lower()),
                                 not re.search(r"diplo|dialog", str(p).lower()), not str(p).lower().startswith(str(self.root).lower())))
        return hits[0] if hits else None

    def video_sources(self, stem):
        """Playable video files for a race's VideoPath: picked-but-unsaved ones first, then this mod, then the base game and the other mods."""
        stem = re.split(r"[\\/]", (stem or "").strip())[-1].lower()
        stem = stem.rsplit(".", 1)[0] if stem.rsplit(".", 1)[-1] in ("xnb", "wmv", "mp4", "asf", "avi", "mov") else stem
        if not stem:
            return []
        out = [Path(f.src) for f in self.file_docs if isinstance(f, FileCopyDoc) and Path(f.src).stem.lower() == stem and Path(f.src).suffix.lower() in self.VID_EXTS + (".asf",)]
        try:
            rows = self.library_scan()
        except Exception:
            rows = []
        mine = []
        for label, top, rel, ext, size, kinds in rows:
            if ext in self.VID_EXTS + (".asf",) and Path(rel).stem.lower() == stem:
                (mine if Path(top) == Path(self.root) else out).append(Path(top) / rel)
        return mine + [x for x in out if x not in mine]

    def encounters_of(self, race):
        """Encounter files (mod and base game) whose Faction is this race (matched by its name or file name)."""
        keys = {race.path.stem.strip().lower(), race.get("Traits/Name").strip().lower()} - {""}
        return [e for e in self.encounters + self.base_encounters if e.faction().lower() in keys]

    def dialog_doc(self, name):
        """The editable dialogue file a race's DiplomacyDialogPath names (the mod's, else the base game's)."""
        stem = re.split(r"[\\/]", (name or "").strip())[-1].lower()
        if stem.endswith(".xml"):
            stem = stem[:-4]
        return next((d for d in self.dialogs + self.base_dialogs if d.path.stem.lower() == stem), None) if stem else None

    def dialog_users(self, d):
        stem = d.path.stem.lower()
        return [r for r in self.races + self.base_races if re.split(r"[\\/]", r.get("DiplomacyDialogPath").strip())[-1].lower().removesuffix(".xml") == stem]

    def encounter_factions(self):
        return sorted({e.faction() for e in self.encounters + self.base_encounters if e.faction()}, key=str.lower)

    def text_entry_by_key(self, key):
        for t in ([self.text] if self.text else []) + list(self.ext_text):
            for e in t.entries:
                if e.key == key:
                    return e
        return None

    def new_npc_race(self, name, kind, base=None):
        """Create a non-player race (pirate / remnant / other) from a template or as a copy of another one."""
        doc = self.new_gdoc("races", name, base=base, template="npc_" + kind)
        for path, v in (("Traits/Name", name), ("Traits/Singular", name), ("Traits/Plural", name)):
            doc.set(path, v)
        if base is None:
            doc.set("Traits/ShipType", re.sub(r"\W+", "", name) or "npc")
        return doc

    def traits_doc(self, create=False):
        """The racial traits file (the mod's, else the base game's). create=True starts an empty one in the mod when there is none."""
        d = self.traits[0] if self.traits else (self.base_traits[0] if self.base_traits else None)
        if d is None and create:
            d = self.new_gdoc("traits", "RacialTraits")
        return d

    def defined_traits(self):
        d = self.traits_doc()
        return [trait_get(i, "TraitName") for i in d.lists["traits"] if trait_get(i, "TraitName")] if d is not None else []

    def trait_users(self, name):
        """Races (mod and base game) that list this trait in any of their trait sets."""
        n = (name or "").strip().lower()
        return [r for r in self.races + self.base_races if any(k.startswith("traits") and any(isinstance(x, str) and x.strip().lower() == n for x in v) for k, v in r.lists.items())]

    def rename_trait(self, old, new):
        """Rename a trait everywhere: races that use it and the Excludes of other traits. Returns how many places changed."""
        n = 0
        for r in self.races + self.base_races:
            for k, v in r.lists.items():
                if k.startswith("traits") and old in v:
                    r.lists[k] = [new if x == old else x for x in v]
                    n += 1
        d = self.traits_doc()
        if d is not None:
            L = d.lists["traits"]
            for i, it in enumerate(L):
                ex = trait_get(it, "Excludes", ())
                if old in ex:
                    L[i] = trait_set(it, "Excludes", tuple(new if x == old else x for x in ex))
                    n += 1
        self._trait_costs = None
        return n

    def trait_names(self):
        out = set(self.defined_traits())
        for r in self.races + self.base_races:
            for k, v in r.lists.items():
                if k.startswith("traits"):
                    out.update(x for x in v if isinstance(x, str))
        return out

    def trait_costs(self, reload=False):
        """{trait name: points} read from the game's trait definition files (xml or yaml, wherever a Name and a Cost sit together). Empty if none found."""
        if getattr(self, "_trait_costs", None) is not None and not reload and self.traits_doc() is None:
            return self._trait_costs
        td = self.traits_doc()
        if td is not None and td.lists["traits"]:
            out = {}
            for it in td.lists["traits"]:
                try:
                    out[trait_get(it, "TraitName")] = float(trait_get(it, "Cost") or 0)
                except ValueError:
                    pass
            self._trait_costs, self._trait_src = out, {k: td.path.name for k in out}
            return out
        names = self.trait_names()
        found, src = {}, {}
        low = {n.lower(): n for n in names}
        for p in self._text_files((".xml", ".yaml", ".yml")):
            try:
                if p.stat().st_size > 3000000:
                    continue
                text = read_file(p)[0]
            except Exception:
                continue
            if not any(n in text for n in names):
                continue
            if p.suffix.lower() == ".xml":
                try:
                    root = ET.fromstring(text.encode("utf-8"))
                except Exception:
                    continue
                for el in root.iter():
                    kids = {c.tag.lower(): (c.text or "").strip() for c in el if len(c) == 0}
                    nm = kids.get("name") or kids.get("traitname") or kids.get("id")
                    cs = next((kids[k] for k in ("cost", "points", "pointcost", "traitcost") if k in kids), None)
                    if nm and cs is not None and nm.lower() in low and re.fullmatch(r"-?\d+(\.\d+)?", cs):
                        found.setdefault(low[nm.lower()], float(cs))
                        src.setdefault(low[nm.lower()], p.name)
            else:
                for n in names:
                    if n in found or n not in text:
                        continue
                    m = (re.search(r"(?is)(?:name|traitname|id)\s*:\s*['\"]?%s['\"]?\s*\n.{0,300}?(?:cost|points|pointcost)\s*:\s*(-?\d+(?:\.\d+)?)" % re.escape(n), text)
                         or re.search(r"(?is)(?:cost|points|pointcost)\s*:\s*(-?\d+(?:\.\d+)?)\s*\n.{0,300}?(?:name|traitname|id)\s*:\s*['\"]?%s['\"]?\s*\n" % re.escape(n), text)
                         or re.search(r"(?im)^\s*['\"]?%s['\"]?\s*:\s*(-?\d+(?:\.\d+)?)\s*$" % re.escape(n), text))
                    if m:
                        found[n] = float(m.group(1))
                        src[n] = p.name
        self._trait_costs, self._trait_src = found, src
        return found

    def trait_limit(self, reload=False):
        """(key, value, file name) of the racial-trait points limit in Globals.yaml (any number whose key mentions traits, 'point' preferred), or None."""
        gd = next((d for d in self.extra_docs if isinstance(d, GlobalsDoc)), None)
        if gd is not None:
            ks = sorted((k for k in gd.cur if "trait" in k.lower()), key=lambda k: "point" not in k.lower())
            if ks:
                try:
                    return (ks[0], float(gd.get(ks[0])), gd.path.name)
                except ValueError:
                    pass
        if getattr(self, "_trait_limit", 0) != 0 and not reload:
            return self._trait_limit
        best = None
        for p in self._text_files((".yaml", ".yml")):
            if p.stem.lower() not in ("global", "globals"):
                continue
            try:
                text = read_file(p)[0]
            except Exception:
                continue
            for m in re.finditer(r"(?m)^\s*([A-Za-z_][\w.]*)\s*:\s*(-?\d+(?:\.\d+)?)\s*(?:#.*)?$", text):
                k = m.group(1)
                if "trait" in k.lower():
                    sc = (2 if "point" in k.lower() else 0) + (1 if p.is_relative_to(self.root) else 0)
                    if best is None or sc > best[0]:
                        best = (sc, k, float(m.group(2)), p.name, p)
        self._trait_limit = (best[1], best[2], best[3]) if best else None
        self._trait_limit_path = best[4] if best else None
        return self._trait_limit

    def globals_path(self):
        best = None
        for p in self._text_files((".yaml", ".yml")):
            if p.stem.lower() in ("global", "globals") and (best is None or (p.is_relative_to(self.root) and not best.is_relative_to(self.root))):
                best = p
        return best

    def globals_doc(self):
        """The editable Globals.yaml (the mod's file, or a copy of the base game's that will be saved into the mod)."""
        gd = next((d for d in self.extra_docs if isinstance(d, GlobalsDoc)), None)
        if gd is None:
            src = self.globals_path()
            if src is None:
                raise ValueError("No Globals.yaml was found.")
            if src.is_relative_to(self.root):
                gd = GlobalsDoc(src, self.root)
            else:
                text, bom, enc = read_file(src)
                gd = GlobalsDoc(self.root / "Globals.yaml", self.root, text=text, bom=bom, enc=enc)
            self.extra_docs.append(gd)
        return gd

    def global_value(self, key, default=""):
        gd = next((d for d in self.extra_docs if isinstance(d, GlobalsDoc)), None)
        if gd is not None:
            return gd.cur.get(key, default)
        src = self.globals_path()
        if src is None:
            return default
        try:
            m = re.search(r"(?m)^\s+%s\s*:\s*([^#\n]*?)\s*(?:#.*)?$" % re.escape(key), read_file(src)[0])
        except Exception:
            return default
        return m.group(1).strip() if m else default

    def set_global(self, key, value):
        gd = self.globals_doc()
        if key not in gd.cur:
            raise ValueError("No '%s' line was found in %s." % (key, gd.path.name))
        gd.set(key, str(value).strip())
        self._trait_limit = 0
        return gd

    def set_trait_limit(self, value):
        """Stage a new racial trait points limit in Globals.yaml (a copy goes into the mod when the file only exists in the base game)."""
        lim = self.trait_limit(reload=True)
        if lim is None:
            raise ValueError("No TraitPoints line was found in Globals.yaml.")
        v = ("%d" % value) if float(value) == int(float(value)) else str(value)
        return self.set_global(lim[0], v)

    def troops_of_race(self, race):
        """Troop files whose RaceType is this race's ShipType (or its name)."""
        keys = {race.get("Traits/ShipType").strip().lower(), race.path.stem.lower(), race.get("Traits/Name").strip().lower()} - {""}
        return [t for t in self.troops + self.base_troops if t.get("RaceType").strip().lower() in keys]

    def system_by_name(self, name):
        n = (name or "").strip().lower()
        return next((s for s in self.systems + self.base_systems if (s.get("Name").strip().lower() == n or s.path.stem.lower() == n)), None)

    def hull_key(self, d):
        """The name techs and designs use for a hull: the HullName written inside the hull file ('Terran/Gunboat'), else its path under
        Hulls without .hull."""
        hn = d.get("HullName").strip().replace("\\", "/")
        if hn:
            return hn
        try:
            if getattr(d, "vanilla", False):
                return d.sub.with_suffix("").as_posix()
            return d.path.relative_to(self.hull_root()).with_suffix("").as_posix()
        except (ValueError, AttributeError):
            return d.get("HullName").strip() or d.path.stem

    def hull_by_name(self, name):
        key = (name or "").strip().replace("\\", "/").lower()
        if key.endswith(".hull"):
            key = key[:-5]
        ds = list(self.hulls) + list(self.base_hulls)
        return next((d for d in ds if self.hull_key(d).lower() == key), None) or \
            next((d for d in ds if d.path.stem.lower() == key.rsplit("/", 1)[-1]), None)

    def model_tops(self):
        """Folders a ModelPath can be relative to: the mod, then BB+ (Content and the game folder)."""
        tops = [self.root, self.root / "Content"] + [b / "Content" for b in getattr(self, "base_roots", [])] + list(getattr(self, "base_roots", []))
        if self.game_dir:
            tops += [Path(self.game_dir) / "Content", Path(self.game_dir)]
        return tops

    def model_file(self, mp):
        """The model file a ModelPath names. 'mod Model/Cardassia/X' is the folder called 'mod Model' inside the mod; BB+'s 'Model/Ships/X' is
        in Content. The path is tried as written first, then without a leading 'mod '. -> Path or None."""
        raw = re.sub(r"\.(obj|fbx|xnb)$", "", (mp or "").strip().replace("\\", "/").strip("/"), flags=re.I)
        if not raw:
            return None
        rels = [raw]
        if re.match(r"mod\s", raw, re.I):
            rels.append(re.sub(r"^mod\s+", "", raw, flags=re.I))
        for rel in rels:
            for fd in self.file_docs:
                if fd.tex.lower() == rel.lower() and fd.src.suffix.lower() in (".obj", ".fbx", ".xnb"):
                    return fd.src
            for top in self.model_tops():
                for ext in (".xnb", ".fbx", ".obj"):
                    c = top / (rel + ext)
                    if c.is_file():
                        return c
        return None

    def model_stem_index(self):
        """{file stem: [paths]} of the models under every folder with 'model' in its name, in the mod, BB+ and the other mods (built once)."""
        idx = self.__dict__.get("_model_stems")
        if idx is None:
            idx = self._model_stems = {}
            roots = list(self.model_tops())
            try:
                for m in self.root.parent.iterdir():
                    if m.is_dir() and m != self.root:
                        roots.append(m)
            except OSError:
                pass
            seen = set()
            for top in roots:
                try:
                    dirs = [d for d in top.iterdir() if d.is_dir() and "model" in d.name.lower()]
                except OSError:
                    continue
                for md in dirs:
                    if md in seen:
                        continue
                    seen.add(md)
                    n = 0
                    for q in md.rglob("*"):
                        if q.suffix.lower() in (".obj", ".fbx", ".xnb"):
                            idx.setdefault(q.stem.lower(), []).append(q)
                            n += 1
                            if n > 20000:
                                break
        return idx

    @staticmethod
    def norm_model(x):
        return re.sub(r"\.(obj|fbx|xnb)$", "", re.sub(r"^mod\s+", "", (x or "").strip(), flags=re.I).replace("\\", "/").strip("/"), flags=re.I).lower()

    def model_users(self):
        """{normalised ModelPath: [hulls that use it]}"""
        out = {}
        for d in list(self.hulls) + list(self.base_hulls):
            k = self.norm_model(d.get("ModelPath"))
            if k:
                out.setdefault(k, []).append(d)
        return out

    def icon_users(self, sub="ShipIcons"):
        """{picture name (lower case): [names of the ships using it]} for the pictures a ship's IconPath points at."""
        out = {}
        for d in list(self.hulls) + list(self.base_hulls):
            ip = (d.get("IconPath") or "").strip().replace("\\", "/")
            if ip:
                out.setdefault(ip.rsplit("/", 1)[-1].lower().rsplit(".", 1)[0], []).append(d.get("VisibleName") or d.path.stem)
        return out

    def model_examples(self, style="", role="", n=6):
        """Existing ships of the same style (then role) whose model can be read: [(ship name, ModelPath, extents, triangles)]."""
        out, seen = [], set()
        hulls = list(self.hulls) + list(self.base_hulls)
        order = [d for d in hulls if style and (d.get("Style") or "").strip().lower() == style.lower()] + \
                [d for d in hulls if role and (d.get("Role") or "").strip().lower() == role.lower()]
        for d in order:
            mp = (d.get("ModelPath") or "").strip()
            if not mp or mp in seen:
                continue
            seen.add(mp)
            om = self.model_outline(mp)
            if om and om.get("ext"):
                out.append((d.get("VisibleName") or d.path.stem, mp, om["ext"], om.get("tris") or 0))
                if len(out) >= n:
                    break
        return out

    def model_outline(self, mp):
        """The outline of the ship model named by a ModelPath: its top-down shadow, read from the .obj or .fbx file (mod folder, staged imports, then the
        game). -> {'mask', 'aspect', 'src'} or None when the file is missing or is a compiled .xnb the editor cannot read."""
        mp0 = (mp or "").strip()
        if not mp0:
            return None
        cache = self.__dict__.setdefault("_outlines", {})
        turn = self.__dict__.setdefault("outline_turn", {})
        why = self.__dict__.setdefault("outline_why", {})
        if mp0 in cache:
            om = cache[mp0]
        else:
            om = None
            why[mp0] = ""
            try:
                rel = re.sub(r"\.(obj|fbx|xnb)$", "", mp0.replace("\\", "/").strip("/"), flags=re.I)
                f0 = self.model_file(mp0)
                found = [f0] if f0 is not None else self.model_stem_index().get(rel.rsplit("/", 1)[-1].lower(), [])[:3]
                if not found:
                    why[mp0] = ("no .obj / .fbx / .xnb file named '%s' was found. Looked for %s, and under every 'model' folder of the mod, BB+ and the other mods. "
                                "The model file may be missing from the mod." % (rel.rsplit("/", 1)[-1], self.root / (rel + ".xnb")))
                for c in found:
                    try:
                        om = model_silhouette(c)
                    except Exception as e:
                        why[mp0] = "%s could not be read (%s: %s)" % (c.name, type(e).__name__, e)
                        ERRLOG.append((time.strftime("%H:%M:%S"), "model outline " + c.name, "%s: %s" % (type(e).__name__, e)))
                        continue
                    if om is not None:
                        om["src"] = c.name
                        why[mp0] = ""
                        break
                    why[mp0] = "%s was found but no ship shape could be read from it" % c.name
            except Exception as e:
                ERRLOG.append((time.strftime("%H:%M:%S"), "model outline", str(e)))
                why[mp0] = "%s: %s" % (type(e).__name__, e)
                om = None
            if om is not None:
                cache[mp0] = om
        if om is None:
            return None
        upc = self.__dict__.get("outline_up", {}).get(mp0)
        if upc is not None and om.get("mesh") and om.get("up") != upc:
            k2 = (mp0, "up", upc)
            if k2 not in cache:
                o2 = _mesh_silhouette(*om["mesh"], up=upc)
                if o2 is not None:
                    o2["src"] = om["src"]
                cache[k2] = o2
            if cache[k2] is not None:
                om = cache[k2]
        t = turn.get(mp0, 0)
        if not t:
            return om
        mk = orient_mask(om["mask"], t)
        return {"mask": mk, "aspect": len(mk[0]) / float(len(mk)), "src": om["src"], "ext": om.get("ext"), "tris": om.get("tris"), "mesh": om.get("mesh"), "turn": t, "up": om.get("up")}

    def model_shade(self, mp):
        """The shaded top-down picture of a ship model (turned like its outline) or None."""
        om = self.model_outline(mp)
        if not om or not om.get("mesh"):
            return None
        mp0 = (mp or "").strip()
        t = self.__dict__.get("outline_turn", {}).get(mp0, 0)
        cache = self.__dict__.setdefault("_shades", {})
        k = (mp0, t)
        if k not in cache:
            base = cache.get((mp0, "base", om.get("up")))
            if base is None:
                base = cache[(mp0, "base", om.get("up"))] = _mesh_shade(*om["mesh"], up=om.get("up"))
            if base is None:
                return None
            cache[k] = {"px": orient_grid(base["px"], t)} if t else base
        return cache[k]

    def auto_orient(self, mp, slots):
        """Pick the up axis and turn of the outline that best covers the ship's existing slots (overlap of the stretched outline and the slots)."""
        mp0 = (mp or "").strip()
        done = self.__dict__.setdefault("outline_auto", set())
        if mp0 in done:
            return
        done.add(mp0)
        om = self.model_outline(mp0)
        occ = {(r, c) for r, row in enumerate(slots) for c, v in enumerate(row) if v}
        if not om or not om.get("mesh") or len(occ) < 4:
            return
        rows, cols = len(slots), max(len(r) for r in slots)
        best = None
        for up in range(3):
            o = _mesh_silhouette(*om["mesh"], up=up)
            if o is None:
                continue
            for t in range(4):
                cells = outline_cells(orient_mask(o["mask"], t), rows, cols)
                score = len(cells & occ) / float(len(cells | occ) or 1)
                if best is None or score > best[0] + 1e-9:
                    best = (score, up, t)
        if best:
            self.__dict__.setdefault("outline_up", {})[mp0] = best[1]
            self.__dict__.setdefault("outline_turn", {})[mp0] = best[2]

    def turn_outline(self, mp):
        mp0 = (mp or "").strip()
        t = self.__dict__.setdefault("outline_turn", {})
        t[mp0] = (t.get(mp0, 0) + 1) % 4

    def model_choices(self):
        """[(ModelPath, label)]: models staged now, then the ones other hulls use, then every model file the game and this mod have.
        The mod's own models live in a folder called 'mod Model' (ModelPath 'mod Model/<race>/<name>'); BB+'s in Content\\Model."""
        out, seen = [], set()
        for fd in self.file_docs:
            if fd.tex.lower().startswith("mod model/") and fd.src.suffix.lower() in (".obj", ".fbx", ".xnb"):
                out.append((fd.tex, fd.tex + "     (imported now, saved with your next Save)"))
                seen.add(fd.tex.lower())
        for d in list(self.hulls) + list(self.base_hulls):
            mp = d.get("ModelPath").strip()
            if mp and mp.lower() not in seen:
                seen.add(mp.lower())
                out.append((mp, "%s     (used by %s)" % (mp, d.get("VisibleName") or d.path.stem)))
        if getattr(self, "_models", None) is None:
            files = []
            scans = [(b / "Content", b / "Content" / "Model") for b in getattr(self, "base_roots", [])]
            try:
                scans += [(self.root, d) for d in self.root.iterdir() if d.is_dir() and "model" in d.name.lower()]
            except OSError:
                pass
            for top, md in scans:
                if not md.is_dir():
                    continue
                n = 0
                for q in md.rglob("*"):
                    if q.suffix.lower() in (".xnb", ".obj", ".fbx"):
                        files.append(q.relative_to(top).with_suffix("").as_posix())
                        n += 1
                        if n > 6000:
                            break
            self._models = sorted(set(files), key=str.lower)
        for m in self._models:
            if m.lower() not in seen:
                seen.add(m.lower())
                out.append((m, m))
        return out

    def create_hull_spec(self, sp):
        """The Ships tab's New ship wizard -> a new .hull file (staged until Save). Returns the HullDoc."""
        name = sp["name"].strip()
        if not name or not re.fullmatch(r"[^\\/:*?\"<>|]+", name):
            raise ValueError("The ship's name is empty or has characters a file name cannot hold.")
        folder = (sp.get("folder") or "").strip().strip("\\/")
        if folder and not all(re.fullmatch(r"[^\\/:*?\"<>|]+", x) for x in re.split(r"[\\/]+", folder)):
            raise ValueError("Folder name is not valid.")
        key = (folder.replace("\\", "/") + "/" if folder else "") + name
        if self.hull_by_name(key) is not None and self.hull_by_name(key).path.stem.lower() == name.lower() and self.hull_key(self.hull_by_name(key)).lower() == key.lower():
            raise ValueError("A ship called '%s' already exists." % key)
        path = self.hull_root().joinpath(*([x for x in re.split(r"[\\/]+", folder) if x] + [name + ".hull"]))
        if path.exists():
            raise ValueError("%s already exists." % path.name)
        base = sp.get("base")
        if base is not None:
            text, bom, enc = base.render(), base.bom, base.enc
        else:
            cols, rows = int(sp.get("cols") or 6), int(sp.get("rows") or 10)
            g = sp.get("grid")
            if g and len(g) and len(g[0]):
                rows, cols = len(g), max(len(r) for r in g)
                body = ["|".join((c.ljust(3) if c else "___") for c in (list(r) + [""] * (cols - len(r)))) for r in g]
            else:
                body = ["|".join(["IO "] * cols) for _ in range(rows - 1)] + ["|".join(["E  "] * cols)]
            text = "\n".join(["Version=1", "HullName=" + key, "VisibleName=" + name, "Role=frigate", "Style=", "Size=%d,%d" % (cols, rows), "MeshOffset=0,0",
                              "IconPath=", "ModelPath=", "Animated=false", "IsShipyard=false", "IsOrbitalDefense=false",
                              "#Thruster PosX,PosY,PosZ,Scale", "Thruster=0,%d,0,36" % (rows * 8), "Slots"] + body + [""]) + "\n"
            sib = next(iter(self.hulls), None) or next(iter(self.base_hulls), None)
            bom, enc = (sib.bom, sib.enc) if sib else (False, "utf-8")
        doc = HullDoc(path, self.root, text=text, bom=bom, enc=enc)
        for k, v in (("HullName", key), ("VisibleName", sp.get("visible") or name), ("Role", sp.get("role")), ("Style", sp.get("style")), ("ModelPath", sp.get("model"))):
            if v is not None and (k in doc.cur or str(v).strip()):
                doc.set(k, str(v).strip())
        ik, ipath = sp.get("icon") or ("__none", None)
        safe = re.sub(r"\W+", "_", name).strip("_") or "ship"
        if ik == "__import":
            self.stage_copy(ipath, "ShipIcons", safe)
            doc.set("IconPath", "ShipIcons/" + safe)
        elif ik not in ("__none", "__same", "__keep"):
            doc.set("IconPath", "ShipIcons/" + ik)
        self.hulls.append(doc)
        self._hulls = None
        self._icons.clear()
        return doc

    def copy_design_for_race(self, di, race_name, style=None, taken=()):
        """Stage a copy of design `di` for a new race: new name '<old name> (<Race>)' (the game overwrites a design's name with its FILE name, so
        the file gets the same name), in ShipDesigns\\<Race>\\. Returns the new design name."""
        bad = r'[\\/:*?"<>|]+'
        race_safe = re.sub(bad, "", race_name).strip() or "NewRace"
        base_name = re.sub(bad, "", "%s (%s)" % (di.name.strip() or di.path.stem, race_name)).strip()
        used = {d.name.strip().lower() for d in self.load_designs()} | {t.lower() for t in taken}
        name, n = base_name, 2
        while name.lower() in used:
            name = "%s %d" % (base_name, n)
            n += 1
        text, bom, enc = read_file(di.path)
        nl = "\r\n" if "\r\n" in text else "\n"
        lines, did_name, did_style = [], False, False
        for ln in text.splitlines():
            m = re.match(r"^(\s*\ufeff?\s*)(Name|Style)=(.*)$", ln)
            if m and m.group(2) == "Name" and not did_name:
                ln, did_name = "%sName=%s" % (m.group(1), name), True
            elif m and m.group(2) == "Style" and style and not did_style:
                ln, did_style = "%sStyle=%s" % (m.group(1), style), True
            lines.append(ln)
        if not did_name:
            lines.insert(0, "Name=" + name)
        text = nl.join(lines) + (nl if text.endswith("\n") else "")
        mod_dir = next((p for p, base in self.design_dirs() if not base), self.root / "ShipDesigns")
        path = mod_dir / race_safe / (name + ".design")
        if path.exists() or any(fd.path == path for fd in self.file_docs):
            raise ValueError("%s already exists." % path.name)
        self.file_docs.append(TextFileDoc(path, self.root, text, bom, enc, tex="Designs/" + race_safe + "/" + name,
                                          note="(copy of design '%s' for %s)" % (di.name, race_name)))
        self.designs = None
        return name

    # ---- starter designs: a simple, loadable design on a hull, so the person can open it in the game's ship designer and finish it
    STARTER_RECIPES = {
        "StartingShip": ("cmd", "power", "engine", ("weapon", 3), "shield", ("armor", 8)),
        "StartingScout": ("cmd", "power", "engine", ("armor", 2)),
        "PrototypeShip": ("cmd", "power", ("engine", 6), ("weapon", 4), "shield", ("armor", 10)),
        "DefaultSmallTransport": ("cmd", "power", "engine", ("cargo", 8)),
        "DefaultTroopShip": ("cmd", "power", "engine", ("troop", 4), ("cargo", 2)),
        "DefaultColonyShip": ("cmd", "power", "engine", "colony", ("cargo", 2)),
        "DefaultConstructor": ("cmd", "power", "engine", "construct", ("cargo", 2)),
        "DefaultAssaultShuttle": ("cmd", "power", "engine", ("troop", 2)),
        "DefaultSupplyShuttle": ("cmd", "power", "engine", ("cargo", 4)),
        "DefaultResearchStation": ("cmd", "power", "research", ("armor", 4)),
        "DefaultMiningShip": ("cmd", "power", "engine", "mining", ("cargo", 2)),
        "DefaultMiningStation": ("cmd", "power", "mining", ("armor", 4)),
        "DefaultSalvageShip": ("cmd", "power", "engine", "salvage", ("armor", 2)),
    }
    STARTER_PICK = {        # what to look for: (well-known UIDs, ModuleTypes, words in the UID/name, restriction letter needed)
        "cmd": (("Cockpit",), ("Command",), ("cockpit", "bridge", "command"), ""),
        "power": (("NuclearReactorSmall",), ("PowerPlant",), (), "I"),
        "engine": (("Engine",), ("Engine",), (), "E"),
        "weapon": ((), ("MainGun",), (), "O"),
        "armor": (("SteelArmorSmall",), ("Armor",), (), "O"),
        "shield": ((), ("Shield",), (), "I"),
        "cargo": (("BasicCargoHold",), ("Storage", "Cargo"), ("cargo",), "I"),
        "troop": ((), ("Troop",), ("troop", "barrack"), "I"),
        "colony": (("ColonyModule",), ("Colony",), ("colony",), "I"),
        "construct": ((), (), ("construct",), "I"),
        "research": (("ResearchArray",), (), ("research",), "I"),
        "mining": (("ProcessingUnit",), (), ("mining",), "I"),
        "salvage": (("SalvageUnit",), (), ("salvage",), "I"),
    }
    STARTER_STATIONS = ("DefaultResearchStation", "DefaultMiningStation")

    def starter_catalog(self):
        """{uid: {size, restr, type, tech, cost}} for every module the game, the mod and the existing designs know."""
        cat = {}

        def num(v, d):
            try:
                return float(v)
            except (TypeError, ValueError):
                return d
        for m in list(self.modules) + list(self.base_modules):
            uid = m.get("UID").strip()
            if not uid or uid in cat:
                continue
            try:
                secret = any(p.lower() in ("secret", "pirates", "remnant") for p in m.path.parts)
            except Exception:
                secret = False
            if re.match(r"(?i)(remnant|ancient|pirate)", uid):
                secret = True
            sx, sy = int(num(m.get("XSize"), 0)), int(num(m.get("YSize"), 0))
            cat[uid] = {"size": (sx, sy) if sx and sy else None, "restr": m.get("Restrictions").strip().upper(), "type": m.get("ModuleType").strip(),
                        "tech": num(m.get("TechLevel"), 9), "cost": num(m.get("Cost"), 9999), "secret": secret, "name": m.get("Name").strip()}
        for di in self.load_designs():                 # modules used by existing designs: their size is known from where they are placed
            for _x, _y, idx, _h, sz in di.slots:
                uid = di.uid_at(idx)
                if uid == "?":
                    continue
                e = cat.setdefault(uid, {"size": None, "restr": "", "type": "", "tech": 9, "cost": 9999, "secret": False, "name": ""})
                if e["size"] is None:
                    e["size"] = tuple(sz)
        return cat

    def starter_pick(self, cat, what):
        uids, types, words, need = self.STARTER_PICK[what]
        low = {u.lower(): u for u in cat}
        for u in uids:
            if u.lower() in low:
                return low[u.lower()]
        best = []
        for u, e in cat.items():
            if e["secret"] or not e["size"]:
                continue
            ok = e["type"] in types or any(w in (u + " " + e["name"]).lower() for w in words)
            if not ok:
                continue
            if e["restr"] and need and not (set(need) & set(e["restr"])) and what != "cmd":
                continue
            if what == "weapon" and e["restr"] and "O" not in e["restr"]:
                continue
            if what == "armor" and e["size"] != (1, 1):
                continue
            if what in ("power", "armor", "weapon", "shield") and e["size"][0] * e["size"][1] > 4:
                continue
            best.append((e["tech"], e["size"][0] * e["size"][1], e["cost"], u))
        return min(best)[3] if best else None

    def starter_hull_order(self, tag, hulls):
        """The hull docs best suited to this ship slot first: scouts and shuttles on the smallest hulls, the prototype on the biggest, stations on platforms."""
        def area(h):
            return sum(1 for r in h.slots for c in r if c)
        usable = [h for h in hulls if area(h) >= 6]
        if not usable:
            return []
        usable.sort(key=area)
        if tag in self.STARTER_STATIONS:
            plat = [h for h in usable if h.get("Role").strip().lower() in ("platform", "station")]
            return plat + [h for h in usable if h not in plat]
        ship = [h for h in usable if h.get("Role").strip().lower() not in ("platform", "station")] or usable
        n = len(ship)
        if tag in ("StartingScout", "DefaultAssaultShuttle", "DefaultSupplyShuttle"):
            want = 0
        elif tag == "PrototypeShip":
            want = n - 1
        else:
            want = n // 2
        return sorted(ship, key=lambda h: abs(ship.index(h) - want))

    def starter_design_text(self, hull, tag, name, race_key, cat=None):
        """(text, notes, placed_role_module) for a simple design of this ship slot on `hull` (a HullDoc)."""
        cat = cat or self.starter_catalog()
        grid = hull.slots
        rows, cols = len(grid), hull.cols()
        cells = [(x, y) for y in range(rows) for x in range(cols) if grid[y][x]]
        cx = sum(x for x, _ in cells) / max(1, len(cells))
        cy = sum(y for _, y in cells) / max(1, len(cells))
        center = sorted(cells, key=lambda c: (c[0] - cx) ** 2 + (c[1] - cy) ** 2)
        front = sorted(cells, key=lambda c: (c[1], abs(c[0] - cx)))
        rear = sorted(cells, key=lambda c: (-c[1], abs(c[0] - cx)))
        has_c = [c for c in cells if "C" in grid[c[1]][c[0]]]
        used, placed, uids, notes = set(), [], [], []

        def fits(uid, x, y, command=False):
            if cat[uid]["size"] is None:
                cat[uid]["size"] = (1, 1)
            sx, sy = cat[uid]["size"]
            for yy in range(y, y + sy):
                for xx in range(x, x + sx):
                    if yy >= rows or xx >= cols or (xx, yy) in used or not grid[yy][xx]:
                        return False
                    if not slot_accepts(cat[uid]["restr"], grid[yy][xx]):       # the game's real rule (§2.3), incl. IOE and the x-forms
                        return False
            return True

        def put(uid, order, count, command=False):
            n = 0
            for x, y in order:
                if n >= count:
                    break
                if fits(uid, x, y, command):
                    sx, sy = cat[uid]["size"]
                    if uid not in uids:
                        uids.append(uid)
                    placed.append((x, y, uids.index(uid), (sx, sy)))
                    used.update((xx, yy) for yy in range(y, y + sy) for xx in range(x, x + sx))
                    n += 1
            return n

        station = tag in self.STARTER_STATIONS
        role_ok = True
        for step in self.STARTER_RECIPES.get(tag, ()):
            what, count = (step, 1) if isinstance(step, str) else step
            if what == "engine" and station:
                continue
            uid = self.starter_pick(cat, what)
            if uid is None:
                if what not in ("cmd",):
                    notes.append("no %s module found" % what)
                if what in ("colony", "salvage", "troop", "construct", "mining", "research"):
                    role_ok = False
                continue
            if what == "power":
                count = 1 + len(cells) // 60
            if what == "engine":
                count = min(count if not isinstance(step, str) else 4, max(1, sum(1 for c in cells if "E" in grid[c[1]][c[0]])))
            order = {"cmd": has_c or center, "engine": rear, "weapon": front, "armor": front[::-1]}.get(what, center)
            if what == "cmd" and not has_c:
                order = center
            got = put(uid, order, count, command=(what == "cmd"))
            if got == 0:
                notes.append("%s did not fit on %s" % (uid, hull.get("VisibleName") or hull.path.stem))
                if what in ("colony", "salvage", "troop", "construct", "mining", "research"):
                    role_ok = False
        w, h = cols, rows
        nl = "\n"
        head = ["Version=1", "Name=" + name, "Hull=" + self.hull_key(hull), "Role=" + (hull.get("Role").strip() or "frigate"), "ModName=" + self.root.name,
                "Style=" + race_key, "Size=%d,%d" % (w, h), "GridCenter=%d,%d" % ((has_c[0] if has_c else (w // 2, (h + 1) // 2))), "DefaultCombatState=Artillery",
                "ShipCategory=Unclassified", "HangarDesignation=General", "IsShipyard=false", "IsOrbitalDefense=false", "IsCarrierOnly=false",
                "# Maps module UIDs to Index, first UID has index 0", "ModuleUIDs=" + ";".join(uids), "Modules=%d" % len(placed),
                "# gridX,gridY;moduleUIDIndex;sizeX,sizeY;turretAngle;moduleRot;hangarShipUID"]
        body = []
        for x, y, i, (sx, sy) in sorted(placed, key=lambda p: (p[1], p[0])):
            body.append("%d,%d;%d" % (x, y, i) + (";%d,%d" % (sx, sy) if (sx, sy) != (1, 1) else ""))
        return nl.join(head + body) + nl, notes, role_ok

    def stage_design_text(self, race_name, name, text, note):
        bad = r'[\\/:*?"<>|]+'
        race_safe = re.sub(bad, "", race_name).strip() or "NewRace"
        mod_dir = next((p for p, base in self.design_dirs() if not base), self.root / "ShipDesigns")
        path = mod_dir / race_safe / (name + ".design")
        if path.exists() or any(fd.path == path for fd in self.file_docs):
            raise ValueError("%s already exists." % path.name)
        bom = False
        self.file_docs.append(TextFileDoc(path, self.root, text, bom, "utf-8", tex="Designs/%s/%s" % (race_safe, name), note=note))
        self.designs = None

    # ship slots the design generator builds; the others (colony, troops, constructor, stations, salvage) need special modules: the simple recipes above
    GEN_SLOT_GOAL = {"StartingShip": "Warship - balanced", "PrototypeShip": "Warship - balanced", "StartingScout": "Scout - fast and light",
                     "DefaultSmallTransport": "Freighter - cargo", "DefaultSupplyShuttle": "Freighter - cargo"}

    def race_hulls(self, shiptype):
        pre = (shiptype or "").strip().lower() + "/"
        return [h for h in self.hulls if shiptype and self.hull_key(h).lower().startswith(pre)]

    def starter_name(self, label, race_name, taken=()):
        bad = r'[\\/:*?"<>|]+'
        base = re.sub(bad, "", "%s (%s)" % (label, race_name)).strip()
        used = {d.name.strip().lower() for d in self.load_designs()} | {t.lower() for t in taken}
        name, n = base, 2
        while name.lower() in used:
            name = "%s %d" % (base, n)
            n += 1
        return name

    def make_starter_design(self, tag, label, race_name, race_key, hulls, taken=(), name=None):
        """Stage one starter design for ship slot `tag` on the best of `hulls` (HullDocs). `name` = the exact name the race file already uses
        (else one is made up). Returns (name, notes)."""
        cat = self.starter_catalog()
        if name:
            name = re.sub(r'[\\/:*?"<>|]+', "", name).strip()
        if not name:
            name = self.starter_name(label, race_name, taken)
        goal = self.GEN_SLOT_GOAL.get(tag)
        if goal:                                                  # the design generator (placement rules, engine mix, armour on the bow ...)
            gen = DesignGenerator(self)
            for h in self.starter_hull_order(tag, hulls) or []:
                try:
                    gtext, gnotes, _di, _rep, _grid = gen.build(h, goal, name, race_key, only_unlocked=False)
                except Exception:
                    continue
                if "ModuleUIDs=" in gtext:
                    self.stage_design_text(race_name, name, gtext, "(generated design on %s)" % (h.get("VisibleName") or h.path.stem))
                    return name, gnotes
        best = None
        for h in self.starter_hull_order(tag, hulls) or []:
            text, notes, ok = self.starter_design_text(h, tag, name, race_key, cat)
            if best is None or (ok and not best[3]):
                best = (text, notes, h, ok)
            if ok:
                break
        if best is None:
            return None, ["no hull of at least 6 slots was chosen"]
        text, notes, h, _ok = best
        self.stage_design_text(race_name, name, text, "(starter design on %s)" % (h.get("VisibleName") or h.path.stem))
        return name, notes

    def race_unlock_types(self):
        """{race type: (module unlock entries, techs)} over the mod's techs (the <Type> of each unlocked module); 'ALL' is for every race."""
        out = {}
        for t in self.techs:
            seen = set()
            for _m, ty in t.unlocks:
                if ty:
                    a, b = out.get(ty, (0, 0))
                    out[ty] = (a + 1, b + (0 if ty in seen else 1))
                    seen.add(ty)
        return out

    def copy_type_unlocks(self, src, dst):
        """Every module a tech unlocks for race type `src` is also unlocked for `dst`. Returns [(tech, [module uids added])]."""
        done = []
        if not src or not dst or src.lower() == dst.lower():
            return done
        for t in self.techs:
            have = {(m.lower(), ty.lower()) for m, ty in t.unlocks}
            add = [m for m, ty in t.unlocks if ty.lower() == src.lower() and (m.lower(), dst.lower()) not in have]
            if add:
                t.unlocks = list(t.unlocks) + [(m, dst) for m in add]
                done.append((t, add))
        return done

    def unlock_new_hulls(self, pairs, dst_type=""):
        """pairs = [(old hull key or '', new hull key)]. A new hull goes into every tech that unlocks the hull it was copied from; a hull with no such
        tech (a hull from your PC, or one no tech unlocks) goes into the Colonization tech. Returns (added, fallback count, fallback tech uid)."""
        norm = lambda k: (k or "").strip().replace("\\", "/").lower()
        added, lost = 0, []
        for old, new in pairs:
            hit = [t for t in self.techs if old and norm(old) in {norm(h) for h in t.hulls}]
            for t in hit:
                if norm(new) not in {norm(h) for h in t.hulls}:
                    t.hulls = list(t.hulls) + [new]
                    if dst_type:
                        t.hull_type[new.lower()] = dst_type
                    added += 1
            if not hit:
                lost.append(new)
        fb = next((t for t in self.techs if t.uid.lower() == "colonization"), None)
        if lost and fb is not None:
            fb.hulls = list(fb.hulls) + [h for h in lost if norm(h) not in {norm(x) for x in fb.hulls}]
            if dst_type:
                for h in lost:
                    fb.hull_type[h.lower()] = dst_type
        return added, (len(lost) if fb is not None else 0), (fb.uid if fb is not None else "")

    def unlock_new_troops(self, troops, dst_type):
        """Each new troop (dict name, base) is unlocked, for race type dst_type, by the tech(s) that unlock the troop it was copied from
        (else by the Colonization tech). Returns the number of unlock entries added."""
        n = 0
        for tr in troops:
            base = (tr["base"].get("Name").strip() or tr["base"].path.stem) if tr.get("base") is not None else ""
            hit = [t for t in self.techs if base and any(nm.lower() == base.lower() for nm, _ty in t.troops)]
            if not hit:
                hit = [t for t in self.techs if t.uid.lower() == "colonization"][:1]
            for t in hit:
                if (tr["name"].lower(), dst_type.lower()) not in {(a.lower(), b.lower()) for a, b in t.troops}:
                    t.troops = list(t.troops) + [(tr["name"], dst_type)]
                    n += 1
        return n

    def race_links(self, race):
        """Everything in the mod that belongs to this race: its own home system, troops, hulls, designs, dialogue, encounters and the tech unlocks
        written for its ship type. Things another race also uses are left out."""
        key = race.get("Traits/ShipType").strip()
        kl = key.lower()
        names = {x.lower() for x in (race.name(), race.path.stem) if x}
        allr = [r for r in self.races + self.base_races if r is not race]
        shared = bool(kl) and any(r.get("Traits/ShipType").strip().lower() == kl for r in allr)
        out = {"system": None, "troops": [], "hulls": [], "designs": [], "staged": [], "dialog": None, "encounters": [], "techs": [], "shared": shared}
        hs = race.get("Traits/HomeSystemName").strip().lower()
        if hs and not any(r.get("Traits/HomeSystemName").strip().lower() == hs for r in allr):
            out["system"] = next((x for x in self.systems if x.get("Name").strip().lower() == hs or x.path.stem.lower() == hs), None)
        if kl and not shared:
            out["troops"] = [t for t in self.troops if t.get("RaceType").strip().lower() == kl]
            out["hulls"] = [h for h in self.hulls if h.get("Style").strip().lower() == kl]
        hk = {self.hull_key(h).replace("\\", "/").lower() for h in out["hulls"]}
        if kl and not shared:
            for t in self.techs:
                mods = [p for p in t.unlocks if p[1].lower() == kl]
                trs = [p for p in t.troops if p[1].lower() == kl]
                hh = [h for h in t.hulls if h.strip().replace("\\", "/").lower() in hk]
                if mods or trs or hh:
                    out["techs"].append((t, mods, trs, hh))
        for di in self.load_designs():
            if di.is_base:
                continue
            if (kl and not shared and di.style.lower() == kl) or di.path.parent.name.lower() in names:
                out["designs"].append(di.path)
        for fd in self.file_docs:
            if isinstance(fd, TextFileDoc) and fd.path.suffix.lower() == ".design" and fd.path.parent.name.lower() in names:
                out["staged"].append(fd)
        dd = self.dialog_doc(race.get("DiplomacyDialogPath"))
        if dd is not None and not getattr(dd, "vanilla", False) and any(dd is d for d in self.dialogs) and all(r is race for r in self.dialog_users(dd)):
            out["dialog"] = dd
        out["encounters"] = [e for e in self.encounters if e.faction().lower() in names]
        return out

    def race_links_text(self, links):
        L = []
        if links["system"] is not None:
            L.append("home solar system: %s" % (links["system"].get("Name") or links["system"].path.stem))
        if links["troops"]:
            L.append("%d troop(s): %s" % (len(links["troops"]), ", ".join((t.name() or t.path.stem) for t in links["troops"][:5]) + (" ..." if len(links["troops"]) > 5 else "")))
        if links["hulls"]:
            L.append("%d hull(s) of its ship set" % len(links["hulls"]))
        if links["designs"] or links["staged"]:
            L.append("%d ship design file(s)" % (len(links["designs"]) + len(links["staged"])))
        if links["dialog"] is not None:
            L.append("diplomacy dialogue %s" % links["dialog"].path.stem)
        if links["encounters"]:
            L.append("%d encounter file(s)" % len(links["encounters"]))
        if links["techs"]:
            L.append("tech unlocks in %d tech(s): %d module, %d troop and %d hull entries" % (
                len(links["techs"]), sum(len(m) for _t, m, _r, _h in links["techs"]), sum(len(r) for _t, _m, r, _h in links["techs"]), sum(len(h) for _t, _m, _r, h in links["techs"])))
        return L

    def delete_race_links(self, links):
        """Remove everything race_links found (the race file itself is deleted by the caller). Files go when you Save; Undo / Revert bring them back."""
        for t, mods, trs, hh in links["techs"]:
            t.unlocks = [p for p in t.unlocks if p not in mods]
            t.troops = [p for p in t.troops if p not in trs]
        for h in links["hulls"]:
            self.delete_hull(h)
        for g in [links["system"], links["dialog"]] + links["troops"] + links["encounters"]:
            if g is not None:
                self.delete_gdoc(g)
        for path in links["designs"]:
            doc = self.design_doc_for_path(path)
            self.extra_docs[:] = [d for d in self.extra_docs if d is not doc]
            if doc.path.exists():
                self.deleted.append({"doc": doc, "weapon": None, "techs": [], "building": False, "kind": "file"})
        if links["staged"]:
            self.file_docs = [f for f in self.file_docs if not any(f is x for x in links["staged"])]
        self.designs = None
        self._design_files = None
        self._hulls = None

    def tech_type_map(self):
        """{hull name (lower): ShipType} from the mod's own tech files and, oldest first, from every backed-up copy of a tech file."""
        m = {}
        for t in self.techs:
            for n in t.hulls:
                ty = t.orig_hull_type.get(n.lower())
                if ty:
                    m.setdefault(n.lower(), ty)
        bd = self.root / BACKUP_DIR
        if bd.is_dir():
            for p in sorted(bd.rglob("*.xml")):
                if "technology" not in [x.lower() for x in p.parts]:
                    continue
                try:
                    txt = read_file(p)[0]
                except Exception:
                    continue
                for mm in re.finditer(r"<UnlockedHull>(.*?)</UnlockedHull>", txt, re.S):
                    nm = re.search(r"<Name>(.*?)</Name>", mm.group(1))
                    ty = re.search(r"<ShipType>(.*?)</ShipType>", mm.group(1))
                    if nm and ty and nm.group(1).strip() and ty.group(1).strip():
                        m.setdefault(nm.group(1).strip().lower(), ty.group(1).strip())
        return m

    def tech_type_plan(self):
        """[(tech, hull name, ShipType)] for hull unlocks that have lost their <ShipType> and whose type is known from another tech, a backup,
        or (for a hull whose Style is a race's ship type) the hull itself."""
        known = self.tech_type_map()
        keys = {r.get("Traits/ShipType").strip() for r in self.races + self.base_races if r.get("Traits/ShipType").strip()}
        out = []
        for t in self.techs:
            for n in t.hulls:
                if t.hull_type.get(n.lower()):
                    continue
                ty = known.get(n.lower())
                if not ty:
                    h = self.hull_by_name(n)
                    st = h.get("Style").strip() if h is not None else ""
                    if st in keys and h is not None and not getattr(h, "vanilla", False):
                        ty = st
                if ty:
                    out.append((t, n, ty))
        return out

    def hull_sets(self):
        """{ship set (the Style written in the hull files): [hull docs]} for the game's hulls and this mod's."""
        out = {}
        for d in list(self.hulls) + list(self.base_hulls):
            out.setdefault(d.get("Style").strip(), []).append(d)
        return out

    def add_hull_copy(self, src, key, imported=False):
        """Stage a copy of hull `src` (a HullDoc, or a (text, bom, enc, stem) tuple for a file from the PC) as part of ship set `key`.
        The new hull is Hulls\\<key>\\<name>.hull with HullName <key>/<name> and Style <key>. Returns the new HullDoc."""
        if isinstance(src, tuple):
            text, bom, enc, stem = src

            class _B:
                pass
            b = _B()
            b.render, b.bom, b.enc = (lambda t=text: t), bom, enc
            vis = stem
        else:
            b, stem = src, src.path.stem
            vis = src.get("VisibleName").strip() or stem
        stem = re.sub(r'[\\/:*?"<>|]+', "", stem).strip() or "hull"
        # The game identifies a hull by its FILE NAME: two hull files with the same name in different folders replace each other
        # ("Using newer source ..."), which would break the original. So the copy's file name carries the race's key.
        pre = re.sub(r'[\\/:*?"<>|]+', "", key).strip()
        if pre and not stem.lower().startswith(pre.lower() + "_"):
            stem = "%s_%s" % (pre, stem)
        name, n = stem, 2
        taken = {self.hull_key(h).lower() for h in list(self.hulls) + list(self.base_hulls)}
        stems = {h.path.stem.lower() for h in list(self.hulls) + list(self.base_hulls)}
        while ("%s/%s" % (key, name)).lower() in taken or name.lower() in stems or (self.hull_root() / key / (name + ".hull")).exists():
            name = "%s %d" % (stem, n)
            n += 1
        return self.create_hull_spec({"name": name, "folder": key, "base": b, "visible": vis, "style": key})

    def delete_hull(self, doc):
        if not self.can_delete(doc):
            raise ValueError("Ships of the base game cannot be deleted from the mod.")
        key = self.hull_key(doc).lower()
        techs = []
        for t in self.techs:
            n = [h for h in t.hulls if h.strip().replace("\\", "/").lower() == key]
            if n:
                t.hulls[:] = [h for h in t.hulls if h not in n]
                techs.append((t, n))
        self.hulls[:] = [h for h in self.hulls if h is not doc]
        rec = {"doc": doc, "weapon": None, "techs": techs, "building": False, "kind": "hull"}
        if doc.path.exists():
            self.deleted.append(rec)
        self._hulls = None
        return rec

    def rescan(self):
        """Pick up xml files (and whole new folders) added to the mod since it was opened. Returns the new docs."""
        added = []
        for kind, cls, lst in (("shipmodules", XmlDoc, self.modules), ("weapons", XmlDoc, self.weapons),
                               ("technology", TechDoc, self.techs), ("buildings", XmlDoc, self.buildings)):
            have = {d.path for d in lst} | {getattr(d, "orig_path", d.path) for d in lst}
            self.dirs[kind] = self.kind_dirs(kind)
            for d in self.dirs[kind]:
                for p in sorted(d.rglob("*")):
                    if p.is_file() and p.suffix.lower() == ".xml" and p not in have and p not in self._bad:
                        try:
                            doc = cls(p, self.root)
                        except Exception as e:
                            self._bad.add(p)
                            self.errors.append("%s: %s" % (p.relative_to(self.root), e))
                            continue
                        lst.append(doc)
                        added.append(doc)
        if added:
            self._races = None
            self.rebuild_maps()
        self._hulls = None                                  # hull files may have been added too
        return added

    def module_root(self):
        ds = self.dirs.get("shipmodules") or []
        return ds[0] if ds else self.root / "ShipModules"

    def module_folders(self):
        """Folders a new module can go in: the module root itself and every sub-folder, relative, '/' separated."""
        out = [""]
        for d in self.dirs.get("shipmodules") or []:
            for p in sorted(d.rglob("*")):
                if p.is_dir():
                    out.append(p.relative_to(d).as_posix())
        return out

    def unlock_types(self):
        seen, out = set(), []
        for t in self.techs:
            for _m, ty in t.unlocks:
                if ty and ty.lower() not in seen:
                    seen.add(ty.lower())
                    out.append(ty)
        return out

    def new_module(self, uid, name, desc, mtype, xs, ys, folder="", weapon="", base=None):
        """Create a module (file + its two text entries) in memory; nothing is written until Save. Returns the XmlDoc.
        Without `base` the file is a blank template (every tag the game's modules have, safe starting values); with a base module
        its file is copied and only identity / size / type / text are changed."""
        uid, mtype = uid.strip(), mtype.strip()
        if not re.fullmatch(r"[A-Za-z0-9_]+", uid):
            raise ValueError("The UID may only use letters, digits and _ .")
        if uid.lower() in {(m.get("UID") or m.path.stem).strip().lower() for m in self.modules}:
            raise ValueError("A module with UID '%s' already exists." % uid)
        if not mtype:
            raise ValueError("Pick a module type.")
        if not (str(xs).strip().isdigit() and str(ys).strip().isdigit() and int(xs) > 0 and int(ys) > 0):
            raise ValueError("Size must be whole numbers, at least 1.")
        parts = [x for x in re.split(r"[\\/]+", folder.strip()) if x]
        if any(not re.fullmatch(r"[^\\/:*?\"<>|]+", x) or x in (".", "..") for x in parts):
            raise ValueError("Folder name is not valid.")
        path = self.module_root().joinpath(*parts, uid + ".xml")
        if path.exists():
            raise ValueError("%s already exists." % path.name)
        sib = base or next((m for m in self.modules if not m.new), None)
        nl = "\r\n" if sib and "\r\n" in sib.text else "\n"
        ni = di = 0
        if self.text:
            ni = self.next_text_id()
            di = ni + 1
            self.text.add_entry("BB_Module_%s_Name" % uid, ni, name.strip() or uid)
            self.text.add_entry("BB_Module_%s_Desc" % uid, di, desc.strip() or name.strip() or uid)
        vals = {"UID": uid, "Name": uid, "Description": desc.strip() or name.strip() or uid, "ModuleType": mtype,
                "XSize": str(int(xs)), "YSize": str(int(ys)), "NameIndex": str(ni), "DescriptionIndex": str(di),
                "IconTexturePath": "Modules/" + uid}
        if weapon:
            vals["WeaponType"] = weapon
        if base is not None:
            tmp = XmlDoc(path, self.root, text=base.text, bom=base.bom, enc=base.enc)
            for k, v in vals.items():
                if k in tmp.orig or k in ("UID", "Name", "NameIndex", "DescriptionIndex"):
                    tmp.set(k, v)
            text = tmp.render()
        else:
            same = [m.get("Restrictions").strip() for m in self.modules if m.get("ModuleType").strip().lower() == mtype.lower()
                    and m.get("Restrictions").strip()]
            restr = max(set(same), key=same.count) if same else "IO"
            m = re.search(r"<ShipModule\b[^>]*>", sib.text) if sib else None
            text = module_template(m.group(0) if m else "<ShipModule>", vals, restr, bool(weapon), nl)
        doc = XmlDoc(path, self.root, text=text, bom=sib.bom if sib else False, enc=sib.enc if sib else "utf-8")
        self.modules.append(doc)
        self._races = None
        self.rebuild_maps()
        return doc

    def _find_text(self):
        names = ("gametext.yaml", "gametext.yml")
        p = next((p for p in self.root.iterdir() if p.is_file() and p.name.lower() in names), None)
        if p:
            return p
        for p in self.root.rglob("*"):
            if p.is_file() and p.name.lower() in names and BACKUP_DIR not in p.parts:
                return p
        return None

    def rebuild_maps(self):
        self.weap = {}
        for w in list(self.weapons) + list(getattr(self, "base_weapons", [])):
            self.weap.setdefault((w.get("UID") or w.path.stem).strip().lower(), w)
        self.weapon_users, self.text_users = {}, {}
        for m in list(self.modules) + list(getattr(self, "base_modules", [])):
            uid = m.get("UID") or m.path.stem
            self.weapon_users.setdefault(m.get("WeaponType").strip().lower(), []).append(uid)
            for tag in ("NameIndex", "DescriptionIndex"):
                if m.get(tag).strip().isdigit():
                    self.text_users.setdefault(int(m.get(tag)), []).append(uid)
        self.tech_by_uid, self.tech_parents, self.unlocked_by = {}, {}, {}
        for t in self.techs:
            self.tech_by_uid.setdefault(t.uid.lower(), t)
        for t in self.techs:
            for u in t.leads:
                self.tech_parents.setdefault(u.lower(), []).append(t)
            for mu, ty in t.unlocks:
                self.unlocked_by.setdefault(mu.lower(), []).append((t, ty))
        if self.text:
            self.text.reindex()

    def tech_category(self, t):
        parts = t.rel.parts
        return parts[1] if len(parts) > 2 else "(Technology folder)"

    def tech_categories(self):
        """Categories (Technology sub-folders), in the order of the game's research list (RootNode), then by name."""
        cats = {self.tech_category(t) for t in self.techs}
        try:                                                   # empty sub-folders count too: a new branch can start there
            d = next((p for p in self.root.iterdir() if p.is_dir() and p.name.lower() == "technology"), None)
            cats |= {p.name for p in d.iterdir() if p.is_dir()} if d else set()
        except OSError:
            pass

        def key(c):
            h = self.category_head(c)
            return (c.startswith("("), h.root_node if h is not None and h.root_node else 99, c.lower())
        return sorted(cats, key=key)

    def category_head(self, cat):
        """The tech that heads a category: one with RootNode >= 1 (a line of research), else the first tech nothing leads to."""
        ts = [t for t in self.techs if self.tech_category(t) == cat]
        heads = sorted((t for t in ts if t.root_node), key=lambda t: (t.root_node, t.uid.lower()))
        if heads:
            return heads[0]
        r = self.tech_roots(cat)
        return r[0] if r else None

    def next_root_node(self):
        return max([t.root_node for t in self.techs] or [0]) + 1

    def root_icon_paths(self):
        """IconPath values the existing lines of research use (for the New category dialog)."""
        out = []
        for t in sorted((t for t in self.techs if t.root_node), key=lambda t: t.root_node):
            v = t.get("IconPath").strip()
            if v and v not in out:
                out.append(v)
        return out

    def rail_icon_path(self, t):
        """The picture of a line of research (its IconPath: icons_techroot_*), mod folder first, then the game."""
        v = t.get("IconPath").strip().replace("\\", "/") if t is not None else ""
        if v:
            for rel in (v, "TechIcons/" + v, "ResearchMenu/" + v, "UI/" + v):
                p = self.find_file(rel)
                if p:
                    return p
            try:                                                   # anywhere in the mod / game by file name (viewable formats only)
                hits = [h for h in self.find_by_name(v) if h.suffix.lower() in self.img_exts()]
            except Exception:
                hits = []
            if hits:
                return hits[0]
        return self.tech_icon_path(t) if t is not None else None

    def new_category(self, name, uid, folder, position, icon, desc):
        """A new line of research: a root tech (RootNode = position) in its own Technology sub-folder. Nothing is written until Save."""
        if not str(position).strip().isdigit() or int(position) < 1:
            raise ValueError("Position must be a whole number, 1 or more.")
        if not name.strip():
            raise ValueError("Give the line of research a name.")
        return self.new_tech(uid, folder, "General", 50, name, desc, None, root_node=int(position), icon=icon)

    def hull_index(self):
        """{hull path under Hulls\\ without .hull, lower case: file} (and by bare file name)."""
        if getattr(self, "_hulls", None) is None:
            idx, stem = {}, {}
            try:
                tops = [p for p in self.root.iterdir() if p.is_dir() and p.name.lower() == "hulls"] or [self.root]
                for d in tops:
                    for p in d.rglob("*.hull"):
                        if BACKUP_DIR in p.parts:
                            continue
                        idx[p.relative_to(d).with_suffix("").as_posix().lower()] = p
                        stem.setdefault(p.stem.lower(), p)
            except OSError:
                pass
            self._hulls, self._hull_stem, self._hull_info = idx, stem, {}
        return self._hulls

    def hull_info(self, name):
        """{'icon': IconPath, 'visible': VisibleName} of a hull a tech unlocks ('Misc/Shadow Scout'), or {} if its file is missing."""
        d = self.hull_by_name(name)
        if d is not None:
            return {"icon": d.get("IconPath").strip(), "visible": d.get("VisibleName").strip()}
        idx = self.hull_index()
        key = name.strip().replace("\\", "/").lower()
        if key.endswith(".hull"):
            key = key[:-5]
        if key in self._hull_info:
            return self._hull_info[key]
        path = idx.get(key) or self._hull_stem.get(key.rsplit("/", 1)[-1])
        info = {}
        if path:
            try:
                text = read_file(path)[0]
                for tag, k in (("IconPath", "icon"), ("VisibleName", "visible")):
                    m = re.search(r"^%s=(.*)$" % tag, text, re.M)
                    if m:
                        info[k] = m.group(1).strip()
            except OSError:
                pass
        self._hull_info[key] = info
        return info

    def tech_icon_path(self, t):
        """Textures\\TechIcons\\<UID>.png (or one named like the tech's TechnologyType), mod folder first, then the game."""
        for n in (t.uid, t.get("TechnologyType").strip()):
            if n:
                p = self.find_file("TechIcons/" + n)
                if p:
                    return p
        v = t.get("IconPath").strip().replace("\\", "/")
        if v:
            for rel in (v, "TechIcons/" + v, "ResearchMenu/" + v):
                p = self.find_file(rel)
                if p:
                    return p
        return None

    def tech_ship_icons(self, t, limit=6):
        out = []
        for n in t.hulls:
            ic = self.hull_info(n).get("icon")
            p = self.find_file(ic) if ic else None
            if p and p not in out:
                out.append(p)
                if len(out) >= limit:
                    break
        return out

    def tech_building_icons(self, t, limit=6):
        out = []
        for n in t.buildings:
            bd = self.building_by_name(n)
            p = (self.find_file("TechIcons/" + n) or (self.building_pic(bd) if bd is not None else None))
            if p and p not in out:
                out.append(p)
                if len(out) >= limit:
                    break
        return out

    def tech_module_icons(self, t, limit=6):
        mods = {(m.get("UID") or m.path.stem).strip().lower(): m for m in self.modules}
        out, seen = [], set()
        for mu, _ty in t.unlocks:
            k = mu.lower()
            if k in seen:
                continue
            seen.add(k)
            m = mods.get(k)
            p = self.find_file("TechIcons/" + mu)                  # the research screen has its own picture for what a tech unlocks
            if not p:
                p = self.find_icon(m) if m is not None else self.find_file("Modules/" + mu)
            if p and p not in out:
                out.append(p)
                if len(out) >= limit:
                    break
        return out

    def tech_roots(self, cat):
        """Techs of a category that no other tech of that category leads to (the first one is the category's head)."""
        ts = [t for t in self.techs if self.tech_category(t) == cat]
        kids = {u.lower() for t in ts for u in t.leads}
        roots = [t for t in ts if t.uid.lower() not in kids]
        return sorted(roots, key=lambda t: (sort_key(t.get("Cost")), t.uid.lower()))

    def tech_name(self, t):
        e = self.text_display(t, "NameIndex")
        return (e.get("ENG").strip() if e else "") or t.uid

    def new_tech(self, uid, folder, ttype, cost, name, desc, parent=None, root_node=None, icon=""):
        """Create a tech (file + its two text entries) in memory; nothing is written until Save. Returns the TechDoc."""
        uid, folder = uid.strip(), folder.strip().strip("\\/")
        if not re.fullmatch(r"[A-Za-z0-9_]+", uid):
            raise ValueError("The UID may only use letters, digits and _ .")
        if uid.lower() in self.tech_by_uid:
            raise ValueError("A tech with UID '%s' already exists." % uid)
        if not re.fullmatch(r"[^\\/:*?\"<>|]+", folder or "?"):
            raise ValueError("Folder name is not valid.")
        if not str(cost).strip().isdigit():
            raise ValueError("Cost must be a whole number.")
        path = self.root / "Technology" / folder / (uid + ".xml")
        if path.exists():
            raise ValueError("%s already exists." % path.name)
        sib = next((t for t in self.techs if not t.new), None)
        m = re.search(r"<Technology\b[^>]*>", sib.text) if sib else None
        nl = "\r\n" if sib and "\r\n" in sib.text else "\n"
        ni = di = 0
        if self.text:
            ni = self.next_text_id()
            di = ni + 1
            self.text.add_entry("BB_Tech_%s_Name" % uid, ni, name.strip() or uid)
            self.text.add_entry("BB_Tech_%s_Desc" % uid, di, desc.strip() or name.strip() or uid)
        doc = TechDoc(path, self.root, tech_template(m.group(0) if m else "", uid, ttype.strip() or "ShipWeapons", int(cost), ni, di, nl,
                                                     root_node, icon.strip()),
                      bom=sib.bom if sib else False, enc=sib.enc if sib else "utf-8")
        self.techs.append(doc)
        if parent is not None and uid not in parent.leads:
            parent.leads.append(uid)
        self.rebuild_maps()
        return doc

    # ---- pictures
    def _idpic_index(self):
        sig = (len(self.modules), len(self.base_modules), len(self.buildings), len(self.base_buildings), len(self.hulls), len(self.base_hulls), len(self.techs))
        if self.__dict__.get("_idx_sig") == sig:
            return self._idx
        ix = {}

        def add(k, v):
            k = (k or "").strip().lower().replace("\\", "/")
            if k and k not in ix:
                ix[k] = v
        for d in list(self.modules) + list(self.base_modules):
            add(d.get("UID") or d.path.stem, ("module", d))
        for d in list(self.buildings) + list(self.base_buildings):
            add(doc_key(d), ("building", d))
        for d in list(self.hulls) + list(self.base_hulls):
            add(self.hull_key(d), ("hull", d))
            add(d.path.stem, ("hull", d))
        for t in self.techs:
            add(t.uid, ("tech", t))
        for d in list(self.modules) + list(self.base_modules):                 # then the names the player sees
            try:
                add(module_name(self, d), ("module", d))
            except Exception:
                pass
        for d in list(self.buildings) + list(self.base_buildings):
            try:
                add(module_name(self, d), ("building", d))
            except Exception:
                pass
        for d in list(self.hulls) + list(self.base_hulls):
            add(d.get("VisibleName"), ("hull", d))
        for t in self.techs:
            try:
                add(self.tech_name(t), ("tech", t))
            except Exception:
                pass
        self._idx, self._idx_sig, self._idpic = ix, sig, {}
        return ix

    def id_picture(self, text):
        """A picture file for an id or a name shown in a picker (module / building / ship / tech UID or name, or a texture of that name) - from this mod or the base game."""
        text = (text or "").strip()
        if not text:
            return None
        ix = self._idpic_index()
        if text in self._idpic:
            return self._idpic[text]
        cands = [text]
        m = re.search(r"\(([^()]*)\)\s*$", text)
        if m:
            cands.append(m.group(1))
        cands.append(re.split(r"\s{2,}|\s\[", text)[0])
        path = None
        for c in cands:
            hit = ix.get(c.strip().lower().replace("\\", "/"))
            try:
                if hit:
                    kind, d = hit
                    if kind == "module":
                        path = self.module_pic(d)
                    elif kind == "building":
                        path = self.building_pic(d)
                    elif kind == "hull":
                        ic = d.get("IconPath").strip()
                        path = self.find_file(ic) if ic else None
                    else:
                        path = self.tech_icon_path(d) or next(iter(self.tech_ship_icons(d) + self.tech_module_icons(d) + self.tech_building_icons(d)), None)
                if not path and len(c) > 2 and not hit:
                    path = self.find_file("TechIcons/" + c) or self.find_file("Modules/" + c)
            except Exception:
                path = None
            if path:
                break
        self._idpic[text] = path
        return path

    def module_pic(self, m):
        """The picture to show for a module in lists: its research-screen picture (TechIcons\\<UID>) else its module icon."""
        uid = (m.get("UID") or m.path.stem).strip()
        return self.find_file("TechIcons/" + uid) or self.find_icon(m)

    def texture_choices(self, sub):
        """[(stem, path, 'mod' or 'game')] of the pictures in Textures\\<sub> (mod first, then the base game) that this editor can show."""
        out, seen, exts = [], set(), self.img_exts()
        for d, label in [(d, None) for d in self.icon_dirs] + [(d, "other mod: " + n) for n, d in getattr(self, "other_mod_dirs", [])]:
            cand = [d / sub] if (d / sub).is_dir() else []
            if not cand and d.is_dir():
                try:
                    cand = [x for x in d.iterdir() if x.is_dir() and x.name.lower() == sub.lower()]
                except OSError:
                    cand = []
            for c in cand:
                origin = label or ("mod" if str(c).lower().startswith(str(self.root).lower()) else "game")
                try:
                    files = sorted(c.iterdir(), key=lambda x: x.name.lower())
                except OSError:
                    continue
                for f in files:
                    if f.is_file() and f.suffix.lower() in exts and f.stem.lower() not in seen:
                        seen.add(f.stem.lower())
                        out.append((f.stem, f, origin))
        for fd in self.file_docs:                                # staged but not saved
            if fd.tex.lower().startswith(sub.lower() + "/") and fd.tex.rsplit("/", 1)[-1].lower() not in seen:
                seen.add(fd.tex.rsplit("/", 1)[-1].lower())
                out.insert(0, (fd.tex.rsplit("/", 1)[-1], fd.src, "new"))
        return out

    def stage_copy(self, src, sub, uid, replace=False):
        """Copy a picture to Textures\\<sub>\\<uid><ext> when you Save. Returns the texture path ('<sub>/<uid>').
        replace=True lets it overwrite a picture of that name the mod already has (same file type only)."""
        src = Path(src)
        tex = "%s/%s" % (sub, uid)
        tdir = next((x for x in self.root.iterdir() if x.is_dir() and x.name.lower() == "textures"), self.root / "Textures")
        sd = tdir / sub
        if tdir.is_dir():
            sd = next((x for x in tdir.iterdir() if x.is_dir() and x.name.lower() == sub.lower()), sd)
        dest = sd / (uid + src.suffix.lower())
        if dest == src:
            return tex
        if dest.exists() and not replace:
            raise ValueError("%s already exists in the mod." % dest.relative_to(self.root))
        if replace and sd.is_dir():
            other = [x.name for x in sd.iterdir() if x.is_file() and x.stem.lower() == uid.lower() and x.suffix.lower() != dest.suffix.lower()
                     and x.suffix.lower() in self.img_exts()]
            if other:
                raise ValueError("The mod already has %s; pick a %s picture so it replaces that file (or delete the old one first)."
                                 % (other[0], other[0].rsplit(".", 1)[-1]))
        self.file_docs = [f for f in self.file_docs if f.tex.lower() != tex.lower()]
        self.file_docs.append(FileCopyDoc(src, dest, self.root, tex))
        self._icons.clear()
        return tex

    # ---- the asset library: this mod, BB+ (the base game) and the other mods in the Mods folder as one shared pool of pictures, sounds, videos, models ...
    LIB_KINDS = (("all", "Everything"), ("picture", "Pictures & textures"), ("race", "Race pictures, flags & portraits"), ("sound", "Sounds & music"),
                 ("video", "Videos (race intro, diplomacy ...)"), ("model", "3D models"), ("anim", "Animations & effects"), ("data", "Data files (xml / yaml / hull ...)"))
    PIC_EXTS = (".png", ".jpg", ".jpeg", ".gif", ".dds", ".bmp", ".tga", ".xnb")
    VID_EXTS = (".wmv", ".mp4", ".webm", ".avi", ".mov", ".ogv")
    MODEL_EXTS = (".fbx", ".obj", ".mtl", ".xnb", ".dds", ".png")
    LIB_KNOWN = ("textures", "audio", "video", "model", "flags", "technology", "shipmodules", "weapons", "races", "hulls")

    def library_sources(self):
        """[(label, folder)] this mod first, then BB+ / the base game, then every other mod next to this one."""
        out = [("This mod", self.root)]
        for a in self.base_roots:
            out.append(("BB+ (base game)" if len(out) == 1 else "Base: " + a.name, a / "Content"))
        try:
            for sib in sorted(self.root.parent.iterdir(), key=lambda x: x.name.lower()):
                if sib.is_dir() and sib.resolve() != self.root.resolve() and any((sib / k).is_dir() or (sib / k.title()).is_dir() for k in self.LIB_KNOWN):
                    out.append(("Mod: " + sib.name, sib))
        except (OSError, ValueError):
            pass
        return out

    @classmethod
    def lib_kinds_of(cls, rel, ext):
        parts = [x.lower() for x in rel.split("/")]
        top, low = parts[0], rel.lower()
        k = set()
        if ext in cls.VID_EXTS or top == "video":
            k.add("video")
        elif ext in (".wav", ".ogg", ".mp3", ".m4a", ".aac", ".wma", ".flac", ".aif", ".aiff") or top == "audio":
            k.add("sound")
        elif top == "model":
            k.add("model")
        elif ext in cls.PIC_EXTS:
            k.add("picture")
            if top == "flags" or any(w in low for w in ("portrait", "/races/", "race_", "leader", "emblem", "flag")):
                k.add("race")
            if any(w in low for w in ("_cc_", "anim", "explosion", "particle", "trail", "muzzle")) or top in ("3dparticles", "effects"):
                k.add("anim")
        elif ext in (".xml", ".yaml", ".yml", ".hull", ".design", ".txt"):
            k.add("data")
        if top in ("3dparticles", "effects"):
            k.add("anim")
        return k or {"data"}

    def library_scan(self, force=False):
        """Every file of every source: [(source label, folder, relative path with /, extension, size, kinds)]. Remembered until force=True."""
        if getattr(self, "_lib", None) is not None and not force:
            return self._lib
        out, skip = [], {BACKUP_DIR.lower(), ".git", "__pycache__"}
        for label, top in self.library_sources():
            if not top.is_dir():
                continue
            for dp, dns, fns in os.walk(top):
                dns[:] = [d for d in dns if d.lower() not in skip]
                rd = Path(dp).relative_to(top).as_posix()
                for fn in fns:
                    ext = os.path.splitext(fn)[1].lower()
                    rel = fn if rd == "." else rd + "/" + fn
                    try:
                        size = os.path.getsize(os.path.join(dp, fn))
                    except OSError:
                        size = 0
                    out.append((label, top, rel, ext, size, self.lib_kinds_of(rel, ext)))
        self._lib = out
        return out

    def stage_asset(self, src, rel, replace=False):
        """Copy any file into the mod at the same relative path (Textures/Flags/x.png, Audio/..., Video/...) when you Save.
        Returns (dest, 'staged' | 'exists' | 'same')."""
        src, rel = Path(src), rel.replace("\\", "/").strip("/")
        dest = self.root / rel
        if dest == src or (dest.exists() and dest.samefile(src)):
            return dest, "same"
        if dest.exists() and not replace:
            return dest, "exists"
        parts = rel.split("/")
        tex = ("/".join(parts[1:]).rsplit(".", 1)[0]) if parts[0].lower() == "textures" and len(parts) > 2 else "asset:" + rel
        self.file_docs = [f for f in self.file_docs if f.tex.lower() != tex.lower()]
        self.file_docs.append(FileCopyDoc(src, dest, self.root, tex))
        self._icons.clear()
        self._snd = None
        return dest, "staged"

    def stage_model(self, src, sub="Custom"):
        """Copy a model (.xnb / .obj / .fbx) from the computer into the mod's 'mod Model\\<sub>' folder when you Save.
        Returns the ModelPath to use ('mod Model/<sub>/<name>')."""
        src = Path(src)
        if src.suffix.lower() not in (".xnb", ".obj", ".fbx"):
            raise ValueError("Pick a model file: .obj, .fbx or a compiled .xnb.")
        sub = re.sub(r"[^\w .-]+", "_", sub or "").strip() or "Custom"
        if src.suffix.lower() == ".obj":                                   # the material file and the textures it names travel with the model
            side = [src.with_suffix(".mtl")]
            for m in side[:1]:
                if m.is_file():
                    try:
                        for ln in m.read_text(errors="ignore").splitlines():
                            parts = ln.strip().split(None, 1)
                            if len(parts) == 2 and parts[0].lower().startswith("map_"):
                                side.append(src.parent / parts[1].strip().split()[-1])
                    except OSError:
                        pass
            for sf in side:
                sdest = self.root / "mod Model" / sub / sf.name
                if sf.is_file() and sdest != sf and not sdest.exists():
                    self.file_docs = [f for f in self.file_docs if f.path != sdest]
                    self.file_docs.append(FileCopyDoc(sf, sdest, self.root, "ModelFiles/%s/%s" % (sub, sf.name)))
        dest = self.root / "mod Model" / sub / src.name
        tex = "mod Model/%s/%s" % (sub, src.stem)
        if dest != src:
            if dest.exists():
                if dest.read_bytes() != src.read_bytes():
                    raise ValueError("The mod already has a different model called %s in 'mod Model\\%s'. Rename your file first." % (src.name, sub))
            else:
                self.file_docs = [f for f in self.file_docs if f.tex.lower() != tex.lower()]
                self.file_docs.append(FileCopyDoc(src, dest, self.root, tex))
        self._models = self._model_stems = None
        return tex

    # ---- weapons
    # ---- base-game (vanilla) modules, weapons, buildings
    BASE_KINDS = (("shipmodules", "base_modules", "ShipModules"), ("weapons", "base_weapons", "Weapons"), ("buildings", "base_buildings", "Buildings"))
    BASE_SKIP = {"textures", "sounds", "audio", "video", "videos", "fonts", "model", "models", "localization", BACKUP_DIR.lower()}

    def base_kind_dirs(self, kind):
        """Folders of the base game that hold this kind of file, found by folder name: under Content (four levels down) and directly
        in the game folder (two levels down; the Mods folder is never searched)."""
        out, seen = [], set()
        for b in getattr(self, "base_roots", []):
            for top, maxd in ((b / "Content", 6), (b, 3)):
                for dp, dns, _fns in os.walk(top):
                    try:
                        depth = len(Path(dp).relative_to(top).parts)
                    except ValueError:
                        continue
                    skip = self.BASE_SKIP | {"mods", "mod", "saves", "content"} if top == b else self.BASE_SKIP
                    dns[:] = [d for d in dns if d.lower() not in skip] if depth < maxd else []
                    for d in list(dns):
                        q = Path(dp) / d
                        if d.lower() == kind and str(q).lower() not in seen and self.root not in q.parents and q != self.root:
                            seen.add(str(q).lower())
                            out.append(q)
        return out

    def load_base(self):
        """Read the base game's modules / weapons / buildings (those the mod does not already replace). Editing one of them writes a
        copy into the mod on Save - the game's own files are never touched."""
        self.base_found = {}
        for kind, attr, _dn in self.BASE_KINDS:
            mine = {doc_key(d).lower() for d in getattr(self, {"shipmodules": "modules", "weapons": "weapons", "buildings": "buildings"}[kind])}
            docs, dirs = [], self.base_kind_dirs(kind)
            for d in dirs:
                root = d.parent
                files = sorted(d.rglob("*.xml"))
                prefetch(files)
                for f in files:
                    try:
                        doc = XmlDoc(f, root)
                    except Exception:
                        continue
                    want = KIND_ROOT.get(kind)
                    if kind != "buildings" and doc.root_tag != want:
                        continue
                    uid = doc_key(doc).lower()
                    if uid in mine:
                        continue
                    mine.add(uid)
                    doc.vanilla, doc.kind, doc.vrel, doc.sub = True, kind, doc.rel, f.relative_to(d)
                    doc.dest = self.vanilla_dest(kind, f.relative_to(d))
                    docs.append(doc)
            setattr(self, attr, docs)
            self.base_found[kind] = (len(docs), [str(x) for x in dirs])
            self._mark("base " + kind)
        self.load_base_hulls()
        self._mark("base hulls")
        self.load_base_gdocs()
        self._mark("base races / troops / systems")
        self.rebuild_maps()
        self._mark("maps (2)")

    def vanilla_dest(self, kind, sub):
        dn = {k: n for k, _a, n in self.BASE_KINDS}[kind]
        top = (self.dirs.get(kind) or [self.root / dn])[0]
        return Path(top) / sub

    def adopt(self, d):
        """A base-game item that was just saved into the mod becomes an ordinary mod item."""
        d.vanilla = False
        if isinstance(d, GameDoc):
            lst = getattr(self, "base_" + d.kind)
            lst[:] = [x for x in lst if x is not d]
            getattr(self, d.kind).append(d)
            return
        if isinstance(d, HullDoc):
            self.base_hulls[:] = [h for h in self.base_hulls if h is not d]
            self.hulls.append(d)
            self._hulls = None
            return
        for kind, attr, _dn in self.BASE_KINDS:
            lst = getattr(self, attr)
            if d in lst:
                lst.remove(d)
                getattr(self, {"shipmodules": "modules", "weapons": "weapons", "buildings": "buildings"}[kind]).append(d)
        self.rebuild_maps()

    def compare_docs(self):
        return self.modules + self.buildings + self.base_modules + self.base_buildings

    # ---- sounds / picture facts
    AUDIO_EXTS = (".wav", ".ogg", ".mp3", ".m4a", ".wma", ".flac", ".aif", ".aiff")

    def sound_index(self):
        """{lower-case file stem: [paths]} of separate sound files in the mod and the game folders (not the .xwb / .xsb sound banks)."""
        if getattr(self, "_snd", None) is None:
            idx, skip = {}, {BACKUP_DIR.lower(), "shipmodules", "weapons", "technology", "textures", "shipdesigns", "hulls"}
            tops = [self.root] + [b / "Content" for b in self.base_roots] + ([Path(self.game_dir)] if self.game_dir else [])
            seen = set()
            for top in tops:
                if str(top).lower() in seen or not top.is_dir():
                    continue
                seen.add(str(top).lower())
                for dp, dns, fns in os.walk(top):
                    dns[:] = [d for d in dns if d.lower() not in skip]
                    for fn in fns:
                        st, ext = os.path.splitext(fn)
                        if ext.lower() in self.AUDIO_EXTS:
                            lst = idx.setdefault(st.lower(), [])
                            if Path(dp) / fn not in lst:
                                lst.append(Path(dp) / fn)
            self._snd = idx
        return self._snd

    def has_sound_banks(self):
        for top in [self.root] + [b / "Content" for b in self.base_roots]:
            try:
                if any(p.suffix.lower() in (".xwb", ".xsb") for p in top.rglob("*")):
                    return True
            except OSError:
                pass
        return False

    def find_sound(self, cue):
        """Separate sound files whose name matches a sound cue name (exact first, then names that contain it)."""
        key = (cue or "").strip().lower()
        if not key:
            return []
        idx = self.sound_index()
        hits = list(idx.get(key, []))
        if not hits:
            hits = [p for st, ps in idx.items() if key in st or (len(st) > 5 and st in key) for p in ps]
        return hits

    def picture_facts(self, sub):
        """One sentence on the pictures already in Textures\\<sub>: how many, and the usual size / format (read from the file headers)."""
        files = [p for _st, p, _o in self.texture_choices(sub)]
        if not files:
            return "There are no pictures in Textures\\%s yet." % sub
        sizes, fmts = {}, {}
        for p in files[:150]:
            try:
                with open(p, "rb") as f:
                    head = f.read(32)
                if head[:8] == b"\x89PNG\r\n\x1a\n":
                    w, h = struct.unpack(">II", head[16:24])
                elif head[:4] == b"DDS ":
                    h, w = struct.unpack("<II", head[12:20])
                else:
                    continue
            except (OSError, struct.error):
                continue
            sizes[(w, h)] = sizes.get((w, h), 0) + 1
            fmts[p.suffix.lower().lstrip(".").upper()] = fmts.get(p.suffix.lower().lstrip(".").upper(), 0) + 1
        ext = {}
        for p in files:
            ext[p.suffix.lower().lstrip(".").upper()] = ext.get(p.suffix.lower().lstrip(".").upper(), 0) + 1
        out = "Textures\\%s has %d pictures (%s)" % (sub, len(files), ", ".join("%d %s" % (n, e) for e, n in sorted(ext.items(), key=lambda x: -x[1])))
        if sizes:
            top = sorted(sizes, key=lambda z: -sizes[z])[:2]
            out += "; most are " + " or ".join("%d × %d px" % z for z in top)
        return out + "."

    def tag_values(self, tag):
        """The values weapon files use for a tag, most used first (for pick lists of sounds, effects, projectile pictures ...)."""
        c = {}
        for w in self.weapons:
            v = w.orig.get(tag, "").strip()
            if v and v != "{nested}":
                c[v] = c.get(v, 0) + 1
        return sorted(c, key=lambda v: (-c[v], v.lower()))

    def weapon_tags(self):
        """Every flat tag used by any weapon file, with a typical value: [(tag, value)] sorted by name."""
        seen = {}
        for w in self.weapons:
            for tag, v in w.orig.items():
                if v != "{nested}" and tag != "UID":
                    seen.setdefault(tag, []).append(v.strip())
        out = []
        for tag in sorted(seen, key=str.lower):
            vals = [v for v in seen[tag] if v]
            out.append((tag, max(set(vals), key=vals.count) if vals else ""))
        return out

    def new_weapon(self, uid, base, damage="", rng="", delay="", traits=None):
        """traits (optional) = {tag: value}: the weapon file keeps exactly these tags (plus UID); tags of the base file that are not in it
        are removed, new ones are added."""
        """A new Weapons file made as a copy of `base` (same folder), with its own UID. Written when you Save."""
        uid = uid.strip()
        if not re.fullmatch(r"[A-Za-z0-9_]+", uid):
            raise ValueError("The weapon UID may only use letters, digits and _ .")
        if uid.lower() in self.weap:
            raise ValueError("A weapon with UID '%s' already exists." % uid)
        sib = base or next((w for w in self.weapons if not w.new), None)
        wdir = base.path.parent if (base is not None and not getattr(base, "vanilla", False)) else (self.dirs.get("weapons") or [self.root / "Weapons"])[0]
        path = wdir / (uid + ".xml")
        if path.exists():
            raise ValueError("%s already exists." % path.name)
        if base is None:                                           # a blank weapon file: just the root element and the UID
            nl = "\r\n" if sib is not None and "\r\n" in sib.text else "\n"
            head = re.match(r"\s*<\?xml[^>]*\?>\s*", sib.text) if sib is not None else None
            m = re.search(r"<Weapon\b[^>]*>", sib.text) if sib is not None else None
            base = type("Blank", (), {"text": (head.group(0).strip() + nl if head else "") + (m.group(0) if m else "<Weapon>") + nl
                                      + "  <UID>%s</UID>" % uid + nl + "</Weapon>" + nl,
                                      "bom": sib.bom if sib is not None else False, "enc": sib.enc if sib is not None else "utf-8", "orig": {}})()
        text = base.text
        if traits is not None:
            for tag, v in base.orig.items():
                if tag != "UID" and v != "{nested}" and tag not in traits:
                    m = XmlDoc._find(text, tag)
                    if m:
                        ls = text.rfind("\n", 0, m.start()) + 1
                        le = text.find("\n", m.end())
                        le = len(text) if le < 0 else le + 1
                        if not text[ls:m.start()].strip() and not text[m.end():le].strip():
                            text = text[:ls] + text[le:]               # the tag was alone on its line: remove the line
                        else:
                            text = text[:m.start()] + text[m.end():]
        doc = XmlDoc(path, self.root, text=text, bom=base.bom, enc=base.enc)
        pairs = [("UID", uid)] + (list(traits.items()) if traits is not None else [("DamageAmount", damage), ("Range", rng), ("FireDelay", delay)])
        for tag, val in pairs:
            if tag == "UID" or (str(val).strip() != "" and (traits is not None or tag in doc.orig)) :
                doc.set(tag, str(val).strip())
        doc.text = doc.render()                                   # fold the edits into the text, so the new file starts clean
        doc = XmlDoc(path, self.root, text=doc.text, bom=base.bom, enc=base.enc)
        self.weapons.append(doc)
        self.rebuild_maps()
        return doc

    def default_folder(self, mtype):
        """The module folder most modules of this type live in ('' = the module root)."""
        root, seen = self.module_root(), {}
        for m in self.modules:
            if m.get("ModuleType").strip().lower() == (mtype or "").strip().lower():
                try:
                    f = m.path.parent.relative_to(root).as_posix()
                except ValueError:
                    continue
                f = "" if f == "." else f
                seen[f] = seen.get(f, 0) + 1
        return max(seen, key=seen.get) if seen else ""

    def create_module_spec(self, sp):
        """Build everything the New module wizard collected: module file, weapon file, text entries, pictures (all staged until Save).
        sp keys: uid name desc mtype x y folder base weapon_mode('none'|'existing'|'new') weapon wbase wdmg wrng wdelay stats pic2 pic3
        where pic2 / pic3 = (key, path) with key '__none', '__same' (pic3 only), '__import', or an existing picture's name.
        Returns the new module's XmlDoc."""
        uid = sp["uid"].strip()
        weapon, neww = "", None
        if sp.get("weapon_mode") == "existing":
            weapon = sp.get("weapon") or ""
        elif sp.get("weapon_mode") in ("new", "blank"):
            if sp.get("weapon_mode") == "new" and sp.get("wbase") is None:
                raise ValueError("Pick the weapon file to copy.")
            wuid = uid if uid.lower() not in self.weap else uid + "_Weapon"
            neww = self.new_weapon(wuid, sp.get("wbase") if sp.get("weapon_mode") == "new" else None, sp.get("wdmg", ""), sp.get("wrng", ""), sp.get("wdelay", ""), sp.get("traits"))
            weapon = wuid
        try:
            doc = self.new_module(uid, sp["name"], sp.get("desc", ""), sp["mtype"], sp["x"], sp["y"], sp.get("folder", ""), weapon, sp.get("base"))
        except ValueError:
            if neww is not None:
                self.weapons.remove(neww)
                self.rebuild_maps()
            raise
        for tag, val in (sp.get("stats") or {}).items():
            if str(val).strip():
                doc.set(tag, str(val).strip())
        src2 = None
        k2, path2 = sp.get("pic2") or ("__none", None)
        if k2 == "__import":
            self.stage_copy(path2, "Modules", uid)
            src2 = path2
        elif k2 != "__none":
            doc.set("IconTexturePath", "Modules/" + k2)
            src2 = path2
        k3, path3 = sp.get("pic3") or ("__none", None)
        if k3 == "__same":
            if src2:
                self.stage_copy(src2, "TechIcons", uid)
        elif k3 != "__none":
            self.stage_copy(path3, "TechIcons", uid)
        self._icons.clear()
        return doc

    # ---- moving branches of the research tree
    def branch_of(self, t):
        """t and every tech reachable from it through LeadsTo."""
        out, todo = [], [t]
        while todo:
            x = todo.pop()
            if any(x is o for o in out):
                continue
            out.append(x)
            todo.extend(self.tech_by_uid[u.lower()] for u in x.leads if u.lower() in self.tech_by_uid)
        return out

    def move_branch(self, t, target=None, cat=None):
        """Move tech t with everything that follows it. target = the tech it should now follow; or cat = a category (it then
        follows that category's head tech); or neither = it follows nothing. Files move to the target's folder on Save.
        Returns a message; raises ValueError when the move makes no sense."""
        if cat is not None and target is None:
            target = self.category_head(cat)
            if target is None:
                raise ValueError("'%s' has no head tech to attach to." % cat)
        self.rebuild_maps()
        branch = self.branch_of(t)
        if target is not None and any(target is b for b in branch):
            raise ValueError("A branch can't be moved into itself (%s follows %s)." % (self.tech_name(target), self.tech_name(t)))
        parents = list(self.tech_parents.get(t.uid.lower(), []))
        if target is not None and target in parents and self.tech_category(target) == self.tech_category(t) and len(parents) == 1:
            raise ValueError("That is where %s already is." % self.tech_name(t))
        if t.root_node and target is not None:
            if sum(1 for x in self.techs if x.root_node) <= 1:
                raise ValueError("%s is the only line of research; it can't be moved under another tech." % self.tech_name(t))
        newcat = self.tech_category(target) if target is not None else self.tech_category(t)
        clash = [b for b in branch if self.tech_category(b) != newcat and (self.root / "Technology" / newcat / b.path.name).exists()
                 and (self.root / "Technology" / newcat / b.path.name) != b.orig_path]
        if clash:
            raise ValueError("%s already has a file called %s." % (newcat, clash[0].path.name))
        for pt in parents:
            pt.leads = [u for u in pt.leads if u.lower() != t.uid.lower()]
        if target is not None and t.uid not in target.leads:
            target.leads.append(t.uid)
        was_head = bool(t.root_node)
        if target is not None and was_head:
            t.set("RootNode", "0")
        oldcat = self.tech_category(t)
        n = 0
        if target is not None and newcat != oldcat:
            for b in branch:
                if self.tech_category(b) == oldcat:
                    b.move_to(newcat)
                    n += 1
        self.rebuild_maps()
        msg = "Moved %s and %d follow-on tech(s)" % (self.tech_name(t), len(branch) - 1)
        if target is not None:
            msg += " to follow %s" % self.tech_name(target)
        else:
            msg += " off its parent (nothing leads to it now - the game only shows it if a head tech or another tech leads to it)"
        if n:
            msg += "; %d file(s) go to Technology\\%s when you save" % (n, newcat)
        return msg + "."

    def move_category(self, cat, delta):
        """Swap the position (RootNode) of a line of research with its neighbour in the game's list."""
        heads = sorted((t for t in self.techs if t.root_node), key=lambda t: (t.root_node, t.uid.lower()))
        h = self.category_head(cat)
        if h is None or h not in heads:
            raise ValueError("'%s' is not a line of research of its own (its head tech has no RootNode)." % cat)
        i = heads.index(h)
        j = i + delta
        if j < 0 or j >= len(heads):
            raise ValueError("It is already %s in the list." % ("first" if delta < 0 else "last"))
        a, b = heads[i], heads[j]
        va, vb = a.get("RootNode"), b.get("RootNode")
        if va == vb:                                            # same number: spread them out
            vb = str(int(va) + (1 if delta < 0 else -1))
        a.set("RootNode", vb)
        b.set("RootNode", va)

    def weapon_for(self, m):
        return self.weap.get(m.get("WeaponType").strip().lower())

    def text_for(self, m, tag):
        v = m.get(tag).strip()
        return self.text.by_id.get(int(v)) if self.text and v.isdigit() else None

    def all_docs(self):
        return (self.modules + self.weapons + self.techs + self.buildings + self.base_modules + self.base_weapons + self.base_buildings
                + self.hulls + self.base_hulls + self.extra_docs + self.file_docs + self.gdocs() + ([self.text] if self.text else []))

    def other_text_refs(self, i):
        """[(XmlDoc, tag)] for xml files OUTSIDE ShipModules / Weapons (techs, hulls ...) that point at text Id i with an
        <...Index> tag. Only direct child tags are returned, so the edit can be spliced into the file safely."""
        if self._refidx is None:
            idx = {}
            skip = {"shipmodules", "weapons", BACKUP_DIR.lower(), "textures", "sounds", "audio", "video", "videos",
                    "model", "models", "fonts"}
            pat = re.compile(r"<(\w*Index)>\s*(\d+)\s*</\1>")
            for dp, dns, fns in os.walk(self.root):
                dns[:] = [d for d in dns if d.lower() not in skip]
                for fn in fns:
                    if fn.lower().endswith(".xml"):
                        try:
                            text = read_file(Path(dp) / fn)[0]
                        except Exception:
                            continue
                        for m in pat.finditer(text):
                            idx.setdefault(int(m.group(2)), []).append((Path(dp) / fn, m.group(1)))
            self._refidx = idx
        out = []
        for path, tag in self._refidx.get(int(i), []):
            doc = next((d for d in self.techs + self.extra_docs if d.path == path), None)
            if doc is None:
                try:
                    doc = XmlDoc(path, self.root)
                except Exception:
                    continue
                self.extra_docs.append(doc)
            if tag in doc.orig and tag not in doc.nested and (doc, tag) not in out:
                out.append((doc, tag))
        return out

    def pending(self):
        self.prune_added()
        for d in self.base_modules + self.base_weapons + self.base_buildings + self.base_hulls + self.base_gdocs():      # an edited base-game item becomes a NEW file in the mod
            ed = d.edited() if isinstance(d, (HullDoc, GameDoc)) else FieldDoc.has_changes(d)
            d.new = ed
            d.rel = d.dest.relative_to(self.root) if ed else d.vrel
        return [d for d in self.all_docs() if d.has_changes()] + [DelFile(x) for r in self.deleted for x in (r["doc"], r["weapon"])
                                                                    if x is not None and x.path.exists()]

    def save(self):
        docs = self.pending()
        if not docs:
            return 0, 0, []
        bad = [(m, t, v) for m, t, v in self.number_problems() if m.has_changes()]
        if bad:
            return 0, 0, ["NOT SAVED - the game cannot load these numbers (a module's NameIndex / DescriptionIndex must be a whole number from 0 to 65535, "
                          "otherwise the whole mod fails to load): " + "; ".join("%s %s=%s" % (m.path.name, t, v) for m, t, v in bad[:8])]
        stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        bdir = self.root / BACKUP_DIR / stamp
        bdir.mkdir(parents=True, exist_ok=True)
        log = self.root / BACKUP_DIR / "changelog.csv"
        fresh = not log.exists()
        errors, nfiles, nfields = [], 0, 0
        with open(log, "a", newline="", encoding="utf-8") as f:
            w = csv.writer(f)
            if fresh:
                w.writerow(["timestamp", "file", "field", "old", "new"])
            for d in docs:
                try:
                    if getattr(d, "deleted", False):                    # a deleted item: back the file up, then remove it
                        dest = bdir / d.rel
                        dest.parent.mkdir(parents=True, exist_ok=True)
                        shutil.copy2(d.path, dest)
                        d.path.unlink()
                        w.writerow([stamp, d.rel.as_posix(), "DELETED file", "", ""])
                        nfiles += 1
                        nfields += 1
                        continue
                    if getattr(d, "vanilla", False):                    # base-game item: write its copy into the mod
                        if d.dest.exists():
                            raise ValueError("%s already exists in the mod" % d.dest.name)
                        d.path = d.dest
                    dest = bdir / d.rel
                    old = getattr(d, "orig_path", None)
                    if old is not None and old != d.path and old.exists():         # a moved tech: back up the old file, remove it after
                        dest = bdir / old.relative_to(self.root)
                    elif not d.path.exists():
                        old = None
                    if old is None or old == d.path:
                        old = None
                        if d.path.exists():
                            dest.parent.mkdir(parents=True, exist_ok=True)
                            shutil.copy2(d.path, dest)
                        else:
                            d.path.parent.mkdir(parents=True, exist_ok=True)
                    else:
                        dest.parent.mkdir(parents=True, exist_ok=True)
                        shutil.copy2(old, dest)
                        d.path.parent.mkdir(parents=True, exist_ok=True)
                    ch = d.changes()
                    text = d.render()
                    d.path.write_bytes(d.encode(text))
                    if old is not None:
                        try:
                            same = d.path.exists() and os.path.samefile(old, d.path)       # a rename that only changes capitals: one file on Windows
                        except OSError:
                            same = False
                        if same:
                            os.replace(old, d.path)
                        else:
                            old.unlink()
                    d.mark_saved(text)
                    if getattr(d, "vanilla", False):
                        self.adopt(d)
                    for tag, old, new in ch:
                        w.writerow([stamp, str(d.rel), tag, old, new])
                    nfiles += 1
                    nfields += len(ch)
                except Exception as e:
                    errors.append("%s: %s" % (d.rel, e))
        self.file_docs = [f for f in self.file_docs if f.new]
        self.deleted = [r for r in self.deleted if any(x is not None and x.path.exists() for x in (r["doc"], r["weapon"]))]
        self._icons.clear()
        self._tex = None
        self._any = None
        self._design_files = None
        self.designs = None
        return nfiles, nfields, errors



PIRATE_SHIPS = tuple(("Pirate%s%s" % (g, lv), "%s - %s" % (gl, ll), "Design the pirates use for their %s at the %s level (they move up through basic, improved and advanced as the game goes on)." % (gl.lower(), ll))
                     for g, gl in (("Slaver", "Slaver ship"), ("Fighter", "Fighter"), ("Frigate", "Frigate"), ("Base", "Asteroid base"), ("Station", "Station"))
                     for lv, ll in (("Basic", "basic"), ("Improved", "improved"), ("Advanced", "advanced"))) + (
    ("PirateFlagShip", "Pirate flagship", "The pirates' flagship design."),)
REMNANT_SHIPS = tuple(("Remnant" + t, re.sub(r"(?<=[a-z])(?=[A-Z])", " ", t), "Design the Remnant use as their %s." % re.sub(r"(?<=[a-z])(?=[A-Z])", " ", t).lower())
                      for t in ("Fighter", "Corvette", "BeamCorvette", "BattleCorvette", "SupportSmall", "Frigate", "Cruiser", "TorpedoCruiser", "Battleship", "Carrier",
                                "Assimilator", "Bomber", "BomberLight", "BomberMedium", "MotherShip", "Exterminator", "Inhibitor", "Portal", "Behemoth"))
REMNANT_ENVS = ("Terran", "Oceanic", "Steppe", "Tundra", "Swamp", "Desert", "Ice", "Barren", "Volcanic")
NPC_FIELDS = {"Faction", "IsPirateFaction", "PiratePaymentPeriodTurns", "MinimumColoniesForStartPayment", "IsRemnantFaction", "BaseShipLevel",
              "PreferredEnv"} | {"Env" + e for e in REMNANT_ENVS}


def npc_template(kind):
    L = ['<?xml version="1.0" encoding="utf-8"?>', '<EmpireData xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema">',
         "  <Faction>1</Faction>"]
    if kind == "pirate":
        L += ["  <IsPirateFaction>true</IsPirateFaction>", "  <PiratePaymentPeriodTurns>250</PiratePaymentPeriodTurns>", "  <MinimumColoniesForStartPayment>5</MinimumColoniesForStartPayment>"]
    if kind == "remnant":
        L += ["  <IsRemnantFaction>true</IsRemnantFaction>", "  <BaseShipLevel>3</BaseShipLevel>"]
    L += ["  <PortraitName>unknown</PortraitName>", "  <DiplomacyDialogPath>Human</DiplomacyDialogPath>", "  <StartingShip></StartingShip>"]
    if kind == "remnant":
        L.append("  <StartingScout></StartingScout>")
    for tag, _l, _h in (PIRATE_SHIPS if kind == "pirate" else REMNANT_SHIPS if kind == "remnant" else ()):
        L.append("  <%s></%s>" % (tag, tag))
    if kind == "remnant":
        L += ["  <Env%s>1</Env%s>" % (e, e) for e in REMNANT_ENVS] + ["  <PreferredEnv>Terran</PreferredEnv>"]
    L += ["  <Traits>", "    <Name>{name}</Name>", "    <Singular>{name}</Singular>", "    <Plural>{name}</Plural>", "    <ShipType>{ship}</ShipType>",
          "    <HomeSystemName></HomeSystemName>", "    <HomeworldName></HomeworldName>", "    <FlagIndex>64</FlagIndex>", "    <R>200</R>", "    <G>120</G>", "    <B>40</B>",
          "  </Traits>", "</EmpireData>", ""]
    return "\n".join(L)


for _k in ("pirate", "remnant", "minor"):
    Project.TEMPLATES["npc_" + _k] = npc_template(_k)


# ----------------------------------------------------------------- row adapters
Col = namedtuple("Col", "src tag header width")


class Row:
    """A table row. target(col) -> (FieldDoc, tag) or None."""

    def target(self, col):
        return None

    def compare_doc(self):
        return None

    def special(self, col):
        return ""

    def objs(self):
        return []

    def get(self, col):
        t = self.target(col)
        return t[0].get(t[1]) if t else self.special(col)

    def editable(self, col):
        t = self.target(col)
        return bool(t) and not t[0].ro(t[1])

    def set(self, col, val):
        t = self.target(col)
        if t and (t[1] in t[0].cur or val.strip()):
            t[0].set(t[1], val)

    def revert(self, col):
        t = self.target(col)
        if t:
            t[0].revert(t[1])

    def revert_all(self):
        for o in self.objs():
            for tag in list(o.cur) + list(getattr(o, "removed_tags", ())):
                o.revert(tag)

    def differs(self, col):
        t = self.target(col)
        return bool(t) and t[0].changed(t[1])

    def differs_default(self, col):
        t = self.target(col)
        return bool(t) and not t[0].ro(t[1]) and t[0].differs_default(t[1])

    def set_default(self, col):
        t = self.target(col)
        return bool(t) and not t[0].ro(t[1]) and t[0].set_default(t[1])

    def set_default_all(self):
        n = 0
        for o in self.objs():
            for tag in list(o.base):
                if o.defaultable(tag) and o.differs_default(tag):
                    o.set_default(tag)
                    n += 1
        return n

    def info(self, col):
        """(current, value on disk, default, editable) - for tooltips"""
        t = self.target(col)
        if not t:
            return self.special(col), None, None, False
        d, tag = t
        return d.get(tag), d.orig.get(tag), d.base.get(tag), not d.ro(tag)

    def dirty(self):
        return any(o.has_changes() for o in self.objs())


def source_label(doc):
    return "base game" if getattr(doc, "vanilla", False) else "mod"


BUILDING_ORDER = [
    ("M", "Name"), ("T", "Name"), ("T", "Desc"), ("M", "Icon"), ("X", "Category"), ("M", "Cost"), ("M", "Maintenance"),
    # economy
    ("M", "PlusFlatProductionAmount"), ("M", "PlusProdPerColonist"), ("M", "PlusProdPerRichness"), ("M", "PlusFlatFoodAmount"),
    ("M", "PlusFoodPerColonist"), ("M", "PlusFlatResearchAmount"), ("M", "PlusResearchPerColonist"), ("M", "Income"),
    ("M", "CreditsPerColonist"), ("M", "PlusTaxPercentage"), ("M", "StorageAdded"),
    # population / planet
    ("M", "MaxPopIncrease"), ("M", "PlusFlatPopulation"), ("M", "Infrastructure"), ("M", "MaxFertilityOnBuild"), ("M", "IncreaseRichness"),
    # defence
    ("M", "Strength"), ("M", "CombatStrength"), ("M", "SoftAttack"), ("M", "HardAttack"), ("M", "Defense"), ("M", "Weapon"),
    ("M", "PlanetaryShieldStrengthAdded"), ("M", "DefenseShipsCapacity"), ("M", "DefenseShipsRole"), ("M", "ShipRepair"), ("M", "SensorRange"),
    # rules
    ("M", "Scrappable"), ("M", "CanBuildAnywhere"), ("M", "BuildOnlyOnce"), ("M", "Unique"), ("M", "CannotBeBombed"),
]


def building_category(d):
    """The folder a building file sits in (Civilian, Food, Military ...), the way the game groups them."""
    sub = getattr(d, "sub", None)
    if sub is not None:
        return sub.parts[0] if len(sub.parts) > 1 else "Other"
    parts = d.rel.parts
    return parts[1] if len(parts) > 2 else "Other"


class BuildingRow(Row):
    def __init__(self, proj, b):
        self.p, self.b = proj, b

    NAME, DESC = "NameTranslationIndex", "DescriptionIndex"

    def target(self, col):
        if col.src == "M":
            return self.b, col.tag
        if col.src == "T":
            e = self.p.text_for(self.b, self.NAME if col.tag == "Name" else self.DESC)
            return (e, "ENG") if e else None
        return None

    def special(self, col):
        if col.tag == "Source":
            return source_label(self.b)
        if col.tag == "Category":
            return building_category(self.b)
        e = self.p.text_display(self.b, self.NAME if col.tag == "Name" else self.DESC)       # base-game text: shown, not editable
        return e.get("ENG").strip() if e else ""

    def objs(self):
        return [o for o in (self.b, self.p.text_for(self.b, self.NAME), self.p.text_for(self.b, self.DESC)) if o]

    def compare_doc(self):
        return self.b


class ModRow(Row):
    def __init__(self, proj, m):
        self.p, self.m = proj, m

    def compare_doc(self):
        return self.m

    def special(self, col):
        if col.tag == "Source":
            return source_label(self.m)
        if col.src == "T":
            e = self.p.text_display(self.m, "NameIndex" if col.tag == "Name" else "DescriptionIndex")
            return e.get("ENG").strip() if e else ""
        return ""

    def target(self, col):
        if col.src == "X":
            return None
        if col.src == "M":
            return self.m, col.tag
        if col.src == "W":
            w = self.p.weapon_for(self.m)
            return (w, col.tag) if w else None
        e = self.p.text_for(self.m, "NameIndex" if col.tag == "Name" else "DescriptionIndex")
        return (e, "ENG") if e else None

    def objs(self):
        out = [self.m, self.p.weapon_for(self.m),
               self.p.text_for(self.m, "NameIndex"), self.p.text_for(self.m, "DescriptionIndex")]
        return [o for o in out if o]


class WeaponRow(Row):
    def __init__(self, proj, w):
        self.p, self.w = proj, w

    def target(self, col):
        return (self.w, col.tag) if col.src == "W" else None

    def special(self, col):
        if col.tag == "Source":
            return source_label(self.w)
        uid = (self.w.get("UID") or self.w.path.stem).strip().lower()
        return ", ".join(self.p.weapon_users.get(uid, []))

    def objs(self):
        return [self.w]


class TextRow(Row):
    def __init__(self, proj, e):
        self.p, self.e = proj, e

    def target(self, col):
        return (self.e, "ENG") if col.tag == "ENG" else None

    def special(self, col):
        if col.tag == "Id":
            return str(self.e.id)
        if col.tag == "Key":
            return self.e.key
        return ", ".join(self.p.text_users.get(self.e.id, []))

    def objs(self):
        return [self.e]


def doc_key(doc):
    """The name other files use for a module / weapon / building: its UID, else (buildings) its <Name>, else the file name."""
    return (doc.get("UID") or doc.get("Name") or doc.path.stem).strip()


def module_name(proj, m):
    e = proj.text_display(m, "NameIndex") or proj.text_display(m, "NameTranslationIndex")
    return (e.get("ENG").strip() if e else "") or m.get("UID") or m.get("Name") or m.path.stem


