def weapon_tag_tip(proj, tag):
    """Hover text for a weapon tag: what it does, how many weapons use it and which values they give it."""
    info = WEAPON_TAG_INFO.get(tag) or next((v for k, v in WEAPON_TAG_INFO.items() if k.lower() == tag.lower()), None)
    lines = [tag, ""]
    if info:
        lines.append(info)
        if tag in WEAPON_TAG_GUESS:
            lines.append("(I'm not certain about this one - tell me if you know what it really does.)")
    elif tag.lower().startswith("tag_"):
        lines.append("A category tag for weapons. Techs and bonuses can target weapons by these.")
    else:
        lines.append("No description yet - this tag is not one I know. Look at which weapons use it (below) and tell me what it does.")
    c, n = {}, 0
    for w in proj.weapons:
        if tag in w.orig and w.orig[tag] != "{nested}":
            n += 1
            v = w.orig[tag].strip()
            c[v] = c.get(v, 0) + 1
    if n:
        top = sorted(c, key=lambda v: (-c[v], v))[:5]
        lines += ["", "Used by %d of %d weapons." % (n, len(proj.weapons)),
                  "Common values: " + ", ".join("%s (%d)" % (v if v else "(empty)", c[v]) for v in top)]
        nums = []
        for v in c:
            try:
                nums.append(float(v))
            except ValueError:
                pass
        if len(nums) >= 3:
            lines.append("Range seen: %g to %g" % (min(nums), max(nums)))
    else:
        lines += ["", "No weapon in this mod uses it yet."]
    return "\n".join(lines)


def module_stats(proj, m):
    """[(label, value, edited, obj, tag)] for the non-zero stats of a module and its weapon."""
    if proj.is_building(m):
        return building_stats(proj, m)
    w, out = proj.weapon_for(m), []
    for label, src, tag in STAT_FIELDS:
        obj = m if src == "M" else w
        if obj is None:
            continue
        v = obj.get(tag).strip()
        if v.lower() in ("", "0", "0.0", "false"):
            continue
        out.append((label, v, obj.changed(tag), obj, tag))
    return out


class RaceInfo:
    def __init__(self):
        self.names = []          # race names, sorted
        self.of = {}             # module UID (lower case) -> set of race names; empty = generic (every race)
        self.notes = ""          # where the races / assignments came from


def _norm(x):
    return re.sub(r"[^a-z0-9]", "", (x or "").lower())


def _alias_match(a, b):
    return bool(a and b) and (a == b or (min(len(a), len(b)) >= 4 and (a in b or b in a)))


def build_race_info(proj):
    """Which race(s) each module belongs to. Races come from the race files (Races\\*.xml), the names the game log uses and the
    Style= of the ship designs. A module is tied to a race by (1) a race-name prefix in its UID (Car_..., Kling_...),
    (2) a race-name folder in its path or its weapon's path, or (3) failing that, by the designs that use it - when only
    one or two races do. Everything else is generic (usable by all races)."""
    info = RaceInfo()
    races = {}                                           # display name -> normalised aliases
    alias_to = {}

    def find_races(als):
        return [d for d, a in races.items() if any(_alias_match(x, y) for x in als for y in a)]

    def add_race(disp, *aliases):
        disp = (disp or "").strip()
        if not disp:
            return None
        als = {_norm(a) for a in (disp,) + aliases if _norm(a)}
        hit = find_races(als)
        if hit:
            first = hit[0]
            races[first] |= als
            for other in hit[1:]:                    # one race known under several names: merge them
                races[first] |= races.pop(other)
                for k, v in list(alias_to.items()):
                    if v == other:
                        alias_to[k] = first
            for a in als:
                alias_to[a] = first
            return first
        races[disp] = als
        for a in als:
            alias_to[a] = disp
        return disp

    def match_race(name, *aliases):
        """The known race a name belongs to, or None (never creates one)."""
        als = {_norm(a) for a in (name,) + aliases if _norm(a)}
        hit = find_races(als)
        return hit[0] if hit else None
    for d in proj.race_docs():
        names = [d.get(t).strip() for t in ("Name", "RaceName", "Singular", "Plural", "ShipType", "Adjective")
                 if t in d.cur and d.get(t).strip()]
        add_race(names[0] if names else d.path.stem, d.path.stem, *names)
    n_files = len(races)
    if proj.log:
        for it in proj.log.items:
            if it.kind == "salvage":
                add_race(it.data["race"])
    usage, skip = {}, {"textures", "sounds", "audio", "video", "videos", "model", "models", "fonts", BACKUP_DIR.lower(), "shipmodules", "weapons"}
    n_designs = 0
    for dp, dns, fns in os.walk(proj.root):
        dns[:] = [x for x in dns if x.lower() not in skip]
        for fn in fns:
            if not fn.lower().endswith(".design"):
                continue
            try:
                lines = read_file(Path(dp) / fn)[0].split("\n")[:80]
            except Exception:
                continue
            style, uids = None, None
            for ln in lines:
                if ln.startswith("Style="):
                    style = ln[6:].strip()
                elif ln.startswith("ModuleUIDs="):
                    uids = [u.strip() for u in ln[11:].split(";") if u.strip()]
            if style and uids:
                n_designs += 1
                for u in uids:
                    usage.setdefault(u.lower(), set()).add(style)
    # a design's Style only counts when it names a race the mod already has (Platforms, Misc, Meteors ... are not races)
    style_race = {st: match_race(st) for st in {x for v in usage.values() for x in v}}
    # the tech files say it outright: <UnlockedMod><ModuleUID/><Type>race</Type>
    syn = {"fed": ("starfleet", "federation", "unitedfederation")}
    type_race = {}
    for t in proj.techs:
        for _m, ty in t.unlocks:
            if ty and ty not in type_race:
                type_race[ty] = add_race(ty, *syn.get(ty.lower(), ()))
    unlock_races = {}
    for t in proj.techs:
        for mu, ty in t.unlocks:
            if ty:
                unlock_races.setdefault(mu.lower(), set()).add(type_race[ty])
    via_tech = 0
    specific = 0
    for m in proj.modules:
        uid = (m.get("UID") or m.path.stem).strip()
        found = set()
        parts = list(m.rel.parts[1:-1])
        w = proj.weapon_for(m)
        if w is not None:
            parts += list(w.rel.parts[1:-1])
        for part in parts:
            pn = _norm(part)
            if len(pn) >= 4:
                found |= {d for d, als in races.items() if any(_alias_match(pn, a) for a in als)}
        if "_" in uid:
            tok = _norm(uid.split("_")[0])
            if len(tok) >= 3:
                found |= {d for d, als in races.items() if any(a.startswith(tok) for a in als)}
        if not found:
            used = {style_race[st] for st in usage.get(uid.lower(), ()) if style_race.get(st)}
            if 0 < len(used) <= 2:
                found |= used
        if uid.lower() in unlock_races:                  # a tech names the races: that beats any guess
            found = set(unlock_races[uid.lower()])
            via_tech += 1
        info.of[uid.lower()] = found
        specific += bool(found)
    info.names = sorted(races, key=str.lower)
    info.notes = ("%d race file(s), %d race(s) in all, %d design(s) read; %d of %d modules are tied to a race (%d of them by the "
                  "races a tech unlocks them for), %d are generic") % (
        n_files, len(races), n_designs, specific, len(proj.modules), via_tech, len(proj.modules) - specific)
    return info


def module_fits(m):
    ships = [t[:-6] for t in m.cur if t.endswith("Module") and m.get(t).strip().lower() == "true"]
    return ", ".join(ships), m.get("Restrictions").strip()


def ordered_union(lists, first=()):
    seen, out = set(), []
    for lst in lists:
        for t in lst:
            if t not in seen:
                seen.add(t)
                out.append(t)
    return [t for t in first if t in seen] + [t for t in out if t not in first]


def width_for(header):
    if "Desc" in header or header.endswith("ENG"):
        return 320
    return max(70, min(240, 9 * len(header) + 24))


def make_switch(parent, var, on_change=None):
    """An ON / OFF switch for a true / false value held in the StringVar `var` ('true' / 'false')."""
    def paint():
        on = var.get().strip().lower() == "true"
        b.configure(text=SWITCH_ON if on else SWITCH_OFF, bg=GREEN_ON if on else PANEL2, fg="#10131a" if on else DIM)

    def flip():
        var.set("false" if var.get().strip().lower() == "true" else "true")
        paint()
        if on_change:
            on_change()
    b = tk.Button(parent, width=8, relief="flat", bd=1, cursor="hand2", command=flip, font=("Segoe UI", 9, "bold"),
                  activebackground=GREEN_ON, highlightthickness=0)
    paint()
    var.trace_add("write", lambda *_a: paint())
    return b


def arrange(cols, order):
    """Listed columns first (in the listed order), other '...Module' ship flags next, then the rest."""
    by = {(c.src, c.tag): c for c in cols}
    first = [by[k] for k in order if k in by]
    extra = [c for c in cols if c.src == "M" and c.tag.endswith("Module") and c not in first]
    used = set(first) | set(extra)
    return first + extra + [c for c in cols if c not in used]


def validate(old, new):
    o, n = old.strip().lower(), new.strip()
    if o in ("true", "false"):
        return None if n.lower() in ("true", "false") else "This field must be true or false."
    if NUM_RE.match(old.strip()):
        return None if NUM_RE.match(n) else "This field must be a number."
    return None


def fmt_num(x):
    s = ("%.6f" % x).rstrip("0").rstrip(".")
    return "0" if s in ("-0", "") else s


def bulk_value(old, op, a, b, round_whole):
    if op == "Set to":
        return a
    if op == "Find / replace":
        return old.replace(a, b)
    r = float(old) * float(a) if op == "Multiply by" else float(old) + float(a)
    if round_whole and INT_RE.match(old.strip()):
        return str(int(math.floor(r + 0.5)))
    return fmt_num(r)


def sort_key(v):
    v = v.strip()
    if not v:
        return (2, 0.0, "")
    try:
        return (0, float(v), "")
    except ValueError:
        return (1, 0.0, v.lower())


# ------------------------------------------------------------ comparison metrics
def num(v):
    try:
        return float(str(v).strip())
    except (TypeError, ValueError):
        return None


def fmtv(v):
    if v is None:
        return "–"
    a = abs(v)
    s = ("%.0f" % v) if a >= 100 else ("%.1f" % v) if a >= 10 else ("%.2f" % v)
    if "." in s:
        s = s.rstrip("0").rstrip(".")
    return "0" if s in ("-0", "") else s


def _g(obj, tag, default=None):
    if obj is None or tag not in obj.cur:
        return default
    v = num(obj.get(tag))
    return default if v is None else v


def _burst(w, o):
    """Damage of one volley: damage x salvo count x projectile count (each switchable)."""
    dmg = _g(w, "DamageAmount")
    if not dmg:
        return None
    if o.get("salvo", True):
        dmg *= _g(w, "SalvoCount", 1) or 1
    if o.get("proj", True):
        dmg *= _g(w, "ProjectileCount", 1) or 1
    return dmg


class BalCtx:
    """The Balance page's own calculation, worked out once for a set of Compare numbers (support tiles are shared by all modules)."""

    def __init__(self, proj):
        self.proj, self.v = proj, None

    def row(self, m):
        p = self.proj
        w = p.weapon_for(m)
        if w is None:
            return None
        if self.v is None:
            o = dict(bal_opts_from_cfg(getattr(p, "bal_cfg", None)), _depths=bal_depths(p))
            self.v = (o, bal_support(list(p.modules) + list(p.base_modules), p, o))
        return bal_row(p, m, w, self.v[0], self.v[1])


def _dpsb(m, w, o):
    """DPS for the Compare tab: the Balance page's adjusted DPS (range, travel, point defence, spread, shields ...) when that is switched on."""
    ctx = o.get("bal_ctx")
    if ctx is not None:
        r = ctx.row(m)
        if r is not None:
            return r["eff"]
    return _dps(w, o)


def _dps(w, o):
    b = _burst(w, o)
    if b is None:
        return None
    d = _g(w, "FireDelay")
    return b / (d if d and d > 0 else 1.0)


def _ratio(a, b):
    return None if a is None or not b else a / b


def _mul(a, b):
    return None if a is None or b is None else a * b


def _area(m):
    x, y = _g(m, "XSize"), _g(m, "YSize")
    return x * y if x and y else None


# (key, label, fn(module, weapon, opts))
DERIVED = [
    ("dps", "DPS (approx.)", lambda m, w, o: _dpsb(m, w, o)),
    ("alpha", "Damage per volley", lambda m, w, o: _burst(w, o)),
    ("dps_armor", "DPS vs armor", lambda m, w, o: _mul(_dps(w, o), _g(w, "EffectVsArmor", 1.0))),
    ("dps_shield", "DPS vs shields", lambda m, w, o: _mul(_dps(w, o), _g(w, "EffectVsShields", 1.0))),
    ("bal_eff", "Balance: adjusted DPS", None),
    ("bal_tile", "Balance: DPS per tile", None),
    ("bal_tiles", "Balance: tiles incl. support", None),
    ("bal_flight", "Balance: flight time (s)", None),
    ("dps_power", "DPS per power draw", lambda m, w, o: _ratio(_dpsb(m, w, o), _g(m, "PowerDraw"))),
    ("dps_cost", "DPS per cost", lambda m, w, o: _ratio(_dpsb(m, w, o), _g(m, "Cost"))),
    ("dps_mass", "DPS per mass", lambda m, w, o: _ratio(_dpsb(m, w, o), _g(m, "Mass"))),
    ("dps_slot", "DPS per slot", lambda m, w, o: _ratio(_dpsb(m, w, o), _area(m))),
    ("dmg_ord", "Damage per ordnance", lambda m, w, o: _ratio(_burst(w, o), _g(w, "OrdinanceRequiredToFire"))),
    ("hp_cost", "Health per cost", lambda m, w, o: _ratio(_g(m, "HealthMax"), _g(m, "Cost"))),
    ("hp_mass", "Health per mass", lambda m, w, o: _ratio(_g(m, "HealthMax"), _g(m, "Mass"))),
    ("hp_slot", "Health per slot", lambda m, w, o: _ratio(_g(m, "HealthMax"), _area(m))),
]


def metric_value(proj, m, key, opts=None):
    """key is a derived-metric name, or ('M'|'W', tag) for a raw number in the module / weapon file."""
    opts = opts or {}
    w = proj.weapon_for(m)
    if isinstance(key, str) and key.startswith("bal_"):
        return bal_metric(proj, m, key)
    if isinstance(key, tuple):
        return _g(m if key[0] == "M" else w, key[1])
    for k, _label, fn in DERIVED:
        if k == key:
            return fn(m, w, opts)
    return None


def metric_catalog(proj, mods, opts=None):
    """[(key, label)] of everything that can be plotted for these modules."""
    cat = [(k, label) for k, label, _fn in DERIVED if any(metric_value(proj, m, k, opts) is not None for m in mods)]
    ws = [w for w in (proj.weapon_for(m) for m in mods) if w is not None]
    for src, docs in (("M", mods), ("W", ws)):
        for tag in ordered_union([d.cur for d in docs]):
            if tag not in READ_ONLY_TAGS and any(_g(d, tag) is not None for d in docs):
                cat.append(((src, tag), ("W:" if src == "W" else "") + tag))
    return cat


def key_to_str(k):
    return "%s:%s" % k if isinstance(k, tuple) else k


def str_to_key(s):
    return (s[0], s[2:]) if len(s) > 2 and s[1] == ":" and s[0] in "MWT" else s


def nice_ticks(lo, hi, n=5):
    if hi <= lo:
        hi = lo + 1.0
    raw = (hi - lo) / float(n)
    mag = 10 ** math.floor(math.log10(raw))
    step = next((f * mag for f in (1, 2, 2.5, 5, 10) if raw <= f * mag), 10 * mag)
    start, out = math.floor(lo / step) * step, []
    v = start
    while v <= math.ceil(hi / step) * step + step * 1e-6:
        out.append(round(v, 10))
        v += step
    return out


def trend_fit(xs, ys):
    """Least-squares line y = a + b*x over the points where both are numbers.
    Returns (a, b, sd_of_residuals, [(index, y, predicted)]) or None if it can't be fitted."""
    pts = [(i, x, y) for i, (x, y) in enumerate(zip(xs, ys)) if x is not None and y is not None]
    if len(pts) < 3:
        return None
    n = float(len(pts))
    mx, my = sum(p[1] for p in pts) / n, sum(p[2] for p in pts) / n
    sxx = sum((p[1] - mx) ** 2 for p in pts)
    if sxx == 0:
        return None
    b = sum((p[1] - mx) * (p[2] - my) for p in pts) / sxx
    a = my - b * mx
    res = [(i, y, a + b * x) for i, x, y in pts]
    return a, b, math.sqrt(sum((y - pr) ** 2 for _i, y, pr in res) / n), res


