# ------------------------------------------------------------ the game's blackbox.log
LogItem = namedtuple("LogItem", "kind line ts text data")          # data = what the line says, picked apart
_TS = re.compile(r"^(\d\d:\d\d:\d\d(?:\.\d+)?)ms: ?(.*)$")


class GameLog:
    """blackbox.log, written by the game every run. Parsed into header facts + a list of LogItems worth a look."""

    def __init__(self, path):
        self.path = Path(path)
        self.version = self.user = self.game_dir = self.mod = self.mod_version = self.mod_path = ""
        self.started = None                 # datetime (UTC) from the header
        self.exited_normally, self.exit_code = False, None
        self.load_ms, self.slow = None, []  # total load time, [(loader, ms)] slowest first
        self.updates = []                   # (what, running, latest)
        self.items, self.lines = [], []

    def count(self, *kinds):
        return sum(1 for i in self.items if i.kind in kinds)

    @property
    def crashed(self):
        return bool(self.lines) and not self.exited_normally


def parse_game_log(path):
    text, _bom, _enc = read_file(path)
    lg = GameLog(path)
    lg.lines = text.replace("\r\n", "\n").split("\n")
    upd = None
    last = None
    timing = False

    def add(kind, n, ts, msg, **data):
        it = LogItem(kind, n, ts, msg, data)
        lg.items.append(it)
        return it
    for n, raw in enumerate(lg.lines, 1):
        mt = _TS.match(raw)
        if not mt:
            hd = re.match(r"^\s*=+\s*(.*?)\s*=+\s*$", raw)
            if hd and hd.group(1):
                inner = hd.group(1)
                if inner.startswith("UTC:"):
                    try:
                        lg.started = datetime.datetime.strptime(inner[4:].strip(), "%m/%d/%Y %H:%M:%S")
                    except ValueError:
                        pass
                elif not lg.version:
                    lg.version = inner
            elif raw.strip() and last is not None and last.kind == "error":      # stack trace lines etc.
                last.data.setdefault("more", []).append(raw.rstrip())
            continue
        ts, msg = mt.group(1), mt.group(2).rstrip()
        if timing:
            tm = re.match(r"^(\w+)\s+([\d.]+)ms\s+([\d.]+)%$", msg)
            if tm:
                lg.slow.append((tm.group(1), float(tm.group(2))))
                continue
            timing = False
        last = None
        if msg.startswith("User="):
            lg.user = msg[5:].split()[0] if msg[5:].split() else ""
        elif msg.startswith("GameDir="):
            lg.game_dir = msg[8:].strip()
        elif msg.startswith("Load ModPath:"):
            m = re.match(r"Load ModPath:(.*?)\s+Mod:(.*?)\s+ModVersion:(\S+)", msg)
            if m:
                lg.mod_path, lg.mod, lg.mod_version = m.group(1).strip(), m.group(2).strip(), m.group(3)
        elif msg.startswith("Load Total Elapsed:"):
            m = re.search(r"([\d.]+)ms", msg)
            lg.load_ms = float(m.group(1)) if m else None
            timing = True
        elif msg.startswith("AutoUpdater: latest"):
            upd = [msg.split()[-1], None]
        elif msg.startswith("AutoUpdater: current") and upd:
            upd[1] = msg.split()[-1]
        elif msg.startswith("Latest Version:") and upd and upd[1]:
            m = re.match(r"Latest Version:\s*(.+?)\s+v?[\d.]+\s+at\b", msg)
            lg.updates.append((m.group(1) if m else "update", upd[1], upd[0]))
            upd = None
        elif msg.startswith("The game exited normally"):
            lg.exited_normally = True
        elif msg.startswith("RunCleanupAndExit"):
            m = re.search(r"\((-?\d+)\)", msg)
            lg.exit_code = int(m.group(1)) if m else None
        elif msg.startswith("Warning:"):
            w = msg[8:].strip()
            m = re.match(r"Race (.+?) has no salvage ship design in DefaultSalvageShip \('(.*?)'\)", w)
            if m:
                add("salvage", n, ts, w, race=m.group(1), design=m.group(2))
                continue
            m = re.match(r"File name '(.*)' does not match ship name '(.*)'\.?$", w)
            if m:
                add("shipname", n, ts, w, file=m.group(1), ship=m.group(2))
                continue
            m = re.match(r"LoadBuildings UID='(.*?)' mismatches FileName='(.*?)' at (.+)$", w)
            if m:
                add("building", n, ts, w, uid=m.group(1), file=m.group(2), path=m.group(3).strip())
                continue
            m = re.match(r"Ship\.BaseCanWarp is false: .*?prototype '(.*?)'", w)
            if m:
                add("nowarp", n, ts, w, name=m.group(1).strip())
                continue
            m = re.match(r"ScreenMediaPlayer\.Draw GetTexture failed for '(.*?)'", w)
            if m:
                add("video", n, ts, w, name=m.group(1))
                continue
            add("warning", n, ts, w)
        elif msg.startswith("WeCanBuildThis:false"):
            m = re.match(r"WeCanBuildThis:false\s+Reason:(\w+)(?:=(\S+))?\s+Design:(.*)$", msg)
            if m:
                add("locked", n, ts, msg, reason=m.group(1), what=m.group(2) or "", design=m.group(3).strip())
        elif re.search(r"(?i)\b(error|exception|fatal|crash|unhandled|failed)\b", msg):
            last = add("error", n, ts, msg)
    return lg


def mentioned_modules(proj, text):
    """('module'|'weapon', uid) for every known UID that appears in a log line."""
    known = {}
    for m in proj.modules:
        known.setdefault((m.get("UID") or m.path.stem).strip().lower(), ("module", (m.get("UID") or m.path.stem).strip()))
    for w in proj.weapons:
        known.setdefault((w.get("UID") or w.path.stem).strip().lower(), ("weapon", (w.get("UID") or w.path.stem).strip()))
    out = []
    for tok in dict.fromkeys(re.findall(r"[A-Za-z0-9_+\-]{4,}", text)):
        if tok.lower() in known and known[tok.lower()] not in out:
            out.append(known[tok.lower()])
    return out[:3]


def best_salvage_design(proj, race, wanted):
    """The real salvage design in the mod that a race most likely means: (name, file, score) or None.
    Typos in the file / ship name are tolerated ('FreeBorg Salvage Ship' -> 'Borg Salvage Ship')."""
    def norm(x):
        return re.sub(r"[^a-z0-9]", "", x.lower())

    def core(x):
        return re.sub(r"salvage|ship|design", "", norm(x))
    best = None
    for name, path in proj.salvage_designs():
        if norm(name) == norm(wanted):
            return name, path, 1.0
        c, w, r = core(name), core(wanted), core(race)
        sc = max(difflib.SequenceMatcher(None, c, w).ratio(), difflib.SequenceMatcher(None, c, r).ratio())
        if c and r and (c in r or r in c) and min(len(c), len(r)) >= 3:
            sc = max(sc, 0.9)
        if sc >= 0.7 and (best is None or sc > best[2]):
            best = (name, path, sc)
    return best


def pick_option(title, message, options):
    """Ask the person to choose one of several things to do (returns it, or None). Tests replace this."""
    return ask_choice(tk._default_root, title, message, list(options), options[0] if options else "")


def model_candidates(proj, mp, has=None, limit=10):
    """Models that could replace a missing ModelPath, best guess first: a close spelling in the same folder (ship09e -> ship09esmall),
    the same file name elsewhere, then close spellings anywhere. The base game renames / moves models between updates."""
    import difflib
    norm = lambda m: re.sub(r"^mod\s+", "", m.strip(), flags=re.I).replace("\\", "/")
    want = norm(mp)
    wdir, _, wstem = want.rpartition("/")
    wstem = wstem.lower()
    known = [m for m, _l in proj.model_choices() if (has is None or has(m))]
    split = [(m, norm(m).rpartition("/")) for m in known if norm(m).lower() != want.lower()]
    out = []

    def add(m):
        if m not in out:
            out.append(m)
    ratio = lambda st: difflib.SequenceMatcher(None, wstem, st.lower()).ratio()
    same_dir = sorted([x for x in split if x[1][0].lower() == wdir.lower()], key=lambda x: -ratio(x[1][2]))
    for m, (_d, _s, st) in same_dir:
        if ratio(st) >= 0.6:
            add(m)
    race = "/".join(wdir.split("/")[:3]).lower()
    for m, (d, _s, st) in sorted([x for x in split if x[1][2].lower() == wstem], key=lambda x: (not x[1][0].lower().startswith(race))):
        add(m)
    for m, (_d, _s, st) in sorted(split, key=lambda x: -ratio(x[1][2])):
        if ratio(st) >= 0.6 and norm(m).lower().startswith(race):
            add(m)
    return out[:limit]


def pick_model(hull_name, mp, cands):
    """Ask which model the hull should use; returns the choice or None. (Tests replace this.)"""
    root = tk._default_root
    return ask_choice(root, "Missing hull model",
                      "%s uses the model\n   %s\nwhich the game cannot find.\nPick the model it should use (nothing changes if you cancel):"
                      % (hull_name, mp), cands, cands[0] if cands else "")


def model_fix(proj, hull_file, mp):
    """A Fix that lets you choose a replacement model for a hull whose ModelPath is missing (None when there is no candidate)."""
    h = next((x for x in proj.hulls if x.path.name.lower() == hull_file.lower()), None)
    if h is None:
        return None
    tops = [proj.root] + [b / "Content" for b in getattr(proj, "base_roots", [])] + list(getattr(proj, "base_roots", []))
    if proj.game_dir:
        tops += [Path(proj.game_dir) / "Content", Path(proj.game_dir)]

    def has(m):
        m0 = m
        m = re.sub(r"^mod\s+", "", (m or "").strip(), flags=re.I).replace("\\", "/").strip("/")
        return bool(m) and (proj.model_file(m0) is not None or any((t / (m + ".xnb")).is_file() or (t / m).is_file() or (t / m).is_dir() for t in tops))
    cands = model_candidates(proj, mp, has)
    if not cands:           # nothing on disk to compare with: offer what the mod's other hulls use
        for x in proj.hulls:
            v = x.get("ModelPath").strip()
            if x is not h and v and v not in cands and (x.path.parent == h.path.parent):
                cands.append(v)
        cands = cands[:10]
    if not cands:
        return None

    def run(p, h=h, cands=cands):
        v = pick_model(h.path.name, mp, cands)
        if not v:
            return False
        h.set("ModelPath", v)
        return True
    return Fix("%s: ModelPath '%s' is missing - you choose one of %d model(s) (best guess: '%s')" % (h.path.name, mp, len(cands), cands[0]), run)


def log_issues(proj, add):
    """Turn blackbox.log into Issues (with suggestions). add(sev, cat, item, detail, hint, ref, locs, fix)."""
    lg = proj.log
    if not lg:
        add("INFO", "Game log", "blackbox.log",
            proj.log_error or "no blackbox.log found next to the mod, the game, or this program",
            "Run the game once (it writes blackbox.log every run), then press 'Game log…' to pick it - or put it "
            "next to the game / this program and press Rescan.")
        return
    lp = [(lg.path, 1)]
    when = lg.started.strftime("%Y-%m-%d %H:%M:%S") + " UTC" if lg.started else "unknown time"
    n_err, n_warn = lg.count("error"), lg.count("warning", "salvage", "shipname", "building", "nowarp", "video")
    add("INFO", "Game log", lg.path.name,
        "run at %s  ·  %s  ·  mod %s %s  ·  loaded in %s  ·  %s  ·  %d error line(s), %d warning(s)"
        % (when, lg.version or "?", lg.mod or "?", lg.mod_version, ("%.1fs" % (lg.load_ms / 1000.0)) if lg.load_ms else "?",
           "exited normally" if lg.exited_normally else "DID NOT EXIT NORMALLY", n_err, n_warn),
        "The editor re-reads the log when you come back to this tab after running the game ('Game log…' picks another file).",
        None, lp)
    if lg.crashed:
        tail = [x for x in lg.lines if x.strip()][-6:]
        add("ERROR", "Game log: crash", lg.path.name,
            "the log never says 'The game exited normally' - the game probably crashed or was closed from the task manager. "
            "Last lines:  " + "   |   ".join(t.strip() for t in tail),
            "Look at the last lines for the file or ship it was loading, fix that, and run the game again.",
            None, [(lg.path, max(1, len(lg.lines) - 1))])
    for what, running, latest in lg.updates:
        if running.lower().lstrip("v") != latest.lower().lstrip("v"):
            add("INFO", "Game log: update available", what, "%s: running %s, latest is %s" % (what, running, latest),
                "Updating can fix bugs reported in this log. If you edited the mod, merge your changes rather than overwrite them.",
                None, lp)
    if lg.slow and lg.load_ms and lg.load_ms > 15000:
        add("INFO", "Game log: slow load", "%.1fs" % (lg.load_ms / 1000.0),
            "slowest loaders: " + ", ".join("%s %.1fs" % (k, v / 1000.0) for k, v in lg.slow[:3]),
            "Loading time grows with the number of ship designs, hulls and textures.", None, lp)
    mods = {(m.get("UID") or m.path.stem).strip().lower(): m for m in proj.modules}

    # ---- one issue per distinct problem
    for it in lg.items:
        loc = [(lg.path, it.line)]
        d = it.data
        if it.kind == "error":
            more = d.get("more", [])
            refs = mentioned_modules(proj, it.text)
            fx = None
            mm = re.search(r"Could not find ModelPath=(.+?) for hull (.+?\.hull)", " ".join([it.text] + list(more)))
            if mm:
                try:
                    fx = model_fix(proj, mm.group(2).strip(), mm.group(1).strip())
                except Exception:
                    fx = None
            add("ERROR", "Game log: error", clip_text(it.text, 70),
                it.text + ((("   |   " + "   |   ".join(x.strip() for x in more[:5])) if more else "")),
                "Open the log at this line. An error right after a 'Load ...' line names the file or item that failed - "
                "fix it, run the game, and the entry disappears.", refs[0] if refs else None,
                loc + [loc_tag(proj_obj(proj, r), "UID") for r in refs if proj_obj(proj, r)], fx)
        elif it.kind == "warning":
            refs = mentioned_modules(proj, it.text)
            add("WARN", "Game log: warning", clip_text(it.text, 70), it.text,
                "Usually something the game could not find or understand. Open the log line for the surrounding context.",
                refs[0] if refs else None, loc + [loc_tag(proj_obj(proj, r), "UID") for r in refs if proj_obj(proj, r)])
        elif it.kind == "salvage":
            where = proj.grep_first(d["design"], ("races",)) or proj.grep_first(d["race"], ("races",))
            fx, extra = None, ""
            best = best_salvage_design(proj, d["race"], d["design"])
            rdoc = next((r for r in proj.race_docs() if r.get("DefaultSalvageShip").strip().lower() == d["design"].lower()), None)
            if rdoc is None and any(r.get("DefaultSalvageShip").strip() != d["design"] for r in proj.race_docs()
                                    if (r.get("Name") or r.path.stem).strip() == d["race"] or r.path.stem == d["race"]):
                continue            # already pointed somewhere else in the editor - the old log line only goes away once the game is run again
            if best:
                name, dpath, _sc = best
                raw = ""
                try:
                    for line in read_file(dpath)[0].split("\n")[:40]:
                        mm = re.match(r"^\s*Name\s*=(.*)$", line.rstrip("\r"))
                        if mm:
                            raw = mm.group(1)
                            break
                except Exception:
                    pass
                same = re.sub(r"[^a-z0-9]", "", name.lower()) == re.sub(r"[^a-z0-9]", "", d["design"].lower())
                if name == d["design"] and (not raw or raw.strip() == d["design"]) and (rdoc is None or rdoc.get("DefaultSalvageShip").strip() == d["design"]):
                    # the race and the design file already agree exactly: the warning is from an older run of the game (a fix was saved since)
                    add("INFO", "Game log: salvage ship already fixed", d["race"],
                        "The game log says '%s' had no salvage ship called '%s', but the race and the design file '%s' now agree exactly - this is an old log line."
                        % (d["race"], d["design"], Path(dpath).name),
                        "Nothing to fix. Start the game once; the new blackbox.log will not have this warning. (If it comes back, the design may fail to load - "
                        "look for an error right after 'Loading ... Ship Templates' in the log.)", None, loc)
                    continue
                pend = next((x for x in proj.extra_docs if isinstance(x, DesignDoc) and x.path == Path(dpath)), None)
                if same and pend is not None and pend.cur.get("Name") == d["design"]:
                    continue            # the design's name was already corrected in the editor (Save, then run the game to clear the old log line)
                if same and Path(dpath).suffix.lower() == ".design" and Path(dpath).stem != d["design"]:
                    # the game uses the FILE name as the ship name when the two differ ("Overwriting ship name to ..."),
                    # so the race and the name inside must both say exactly the file name

                    def run(p, dpath=dpath, want=Path(dpath).stem, rdoc=rdoc):
                        p.design_doc_for_path(dpath).set("Name", want)
                        if rdoc is not None and rdoc.get("DefaultSalvageShip").strip() != want and "DefaultSalvageShip" in rdoc.orig:
                            rdoc.set("DefaultSalvageShip", want)
                        p._salvage = None
                        return True
                    fx = Fix("%s: make the race and the name inside %s say exactly '%s' (the file name - the game uses it)" % (d["race"], Path(dpath).name, Path(dpath).stem), run)
                    extra = "  The game takes the FILE name '%s' as the ship's name, but the race asks for '%s'." % (Path(dpath).stem, d["design"])
                elif rdoc is not None and "DefaultSalvageShip" in rdoc.orig:
                    def run(p, rdoc=rdoc, name=name, dpath=dpath, raw=raw):
                        use = name
                        if Path(dpath).suffix.lower() == ".design":
                            dd = p.design_doc_for_path(dpath)
                            cur = (dd.get("Name") or "").strip() if dd is not None else ""
                            if cur:
                                use = cur                                    # the design's name as it is NOW (an earlier fix may have changed it)
                            if raw and raw != raw.strip():
                                dd.set("Name", use)                          # also drop a trailing space from the design's own name
                        if rdoc.get("DefaultSalvageShip").strip() == use:
                            return False                                     # nothing would change - do not pretend it fixed something
                        rdoc.set("DefaultSalvageShip", use)
                        p._salvage = None
                        return True
                    fx = Fix("%s: change DefaultSalvageShip '%s' to '%s' (design file %s)" % (
                        d["race"], d["design"], name, Path(dpath).name), run)
                    extra = "  The closest real design is '%s' (%s)." % (name, dpath)
            elif proj.salvage_designs():
                extra = "  Salvage designs found in the mod: %s." % ", ".join(sorted({n for n, _p in proj.salvage_designs()})[:10])
            add("WARN", "Game log: missing salvage ship", d["race"],
                "race '%s' wants a salvage ship design called '%s' (DefaultSalvageShip) but no such design exists.%s"
                % (d["race"], d["design"], extra),
                "Usually a small typo in the race's DefaultSalvageShip or in the design's file / ship name. Auto-fix (when a close "
                "match exists in the salvage ships folder) points the race at the real design name, or corrects the design's own name "
                "(capitals / a stray trailing space). The game log is only read when the game runs, so the warning stays until you "
                "Save and run the game again.", None,
                ([(rdoc.path, tag_line(rdoc, "DefaultSalvageShip") or 1)] if rdoc is not None else where) + loc, fx)
        elif it.kind == "shipname":
            fname, ship = d["file"], d["ship"]
            norm = lambda t: re.sub(r"[^a-z0-9]", "", t.lower())
            cand = [x for x in proj.design_files() if x.stem == fname] or [x for x in proj.design_files() if norm(x.stem) == norm(fname) and norm(ship) == norm(fname)]
            fx, where, extra = None, [], ""
            done = [x for x in proj.design_files() if x.stem == fname or x.stem == ship]
            dd0 = None
            for x in done:
                y = proj.design_doc_for_path(x)
                if (y.cur.get("Name") or "") == y.path.stem:
                    dd0 = y
                    break
            if dd0 is not None:
                add("INFO", "Game log: file name already fixed", ship.strip(),
                    "The log said the file '%s' and the ship name '%s' differ, but the file '%s' and the name inside it now match exactly - an old log line."
                    % (fname, ship, dd0.path.name), "Nothing to fix. Save (if the editor says there are changes) and start the game once; the new log will not have this warning.",
                    None, loc)
                continue
            if cand:
                dp = cand[0]
                where = [(dp, 1)]
                clean = dp.stem == dp.stem.strip()

                def run(p, dp=dp, ship=ship, fname=fname, clean=clean):
                    opts = ["Rename the FILE to '%s%s'   (the ship name stays; races and designs that use the name keep working)" % (ship, dp.suffix)]
                    if clean:
                        opts.append("Change the ship NAME inside the file to '%s'   (the file keeps its name; races that use the old name are changed too)" % fname)
                    pick = pick_option("Names do not match", "File:  %s\nShip name inside it:  %s\n\nThe game wants both to be exactly the same "
                                       "(capitals, spaces and _ count).\nWhich one is right?" % (dp.name, ship), opts)
                    if not pick:
                        return False
                    dd = p.design_doc_for_path(dp)
                    if pick == opts[0]:
                        dd.rename_file(ship)
                        if (dd.cur.get("Name") or "") != ship:
                            dd.set("Name", ship)                  # the name inside must say it too
                    else:
                        for r in p.race_docs():
                            if r.get("DefaultSalvageShip").strip() == ship and "DefaultSalvageShip" in r.orig:
                                r.set("DefaultSalvageShip", fname)
                        dd.set("Name", fname)
                    p._salvage = None
                    return True
                fx = Fix("%s: make the file name and the ship name the same (you choose which one to change)" % dp.name, run)
            else:
                extra = "  The editor did not find that design file in the mod (it may be a base-game design)."
            add("WARN" if cand else "INFO", "Game log: file name / ship name differ", fname.strip() or "(blank)",
                "The design file '%s' says its ship is '%s'.%s" % (fname, ship, extra),
                "The game wants the file name and the ship name to be exactly the same - capitals, spaces and underscores all count. "
                "Auto-fix asks which of the two to rewrite. The log is read again when the game runs.", None, where + loc, fx)
        elif it.kind == "building":
            p = proj.resolve_game_path(d["path"])
            ln = 1
            inside = bool(p and proj.root.resolve() in p.resolve().parents)
            if p:
                try:
                    for k, line in enumerate(read_file(p)[0].split("\n"), 1):
                        if "uid" in line.lower() and d["uid"].lower() in line.lower():
                            ln = k
                            break
                except Exception:
                    pass
            hint = "Harmless - the game still loads it. " + (
                "To silence it, rename the file to '%s.xml' (safer than changing the UID, which other files may refer to)." % d["uid"]
                if inside or not p else
                "This file belongs to the base game, not your mod - nothing to fix on your side; you can Ignore it.")
            add("WARN" if (inside or not p) else "INFO", "Game log: building UID / file name", d["uid"],
                "building UID '%s' does not match its file name '%s'  (%s)" % (d["uid"], d["file"], d["path"]),
                hint, None, ([(p, ln)] if p else []) + loc)
        elif it.kind == "nowarp":
            add("INFO", "Game log: prototype cannot warp", d["name"],
                "prototype ship '%s' has no way to warp" % d["name"],
                "Expected for stations and platforms. If it should fly between systems, give the design an engine / warp module.",
                None, loc)
        elif it.kind == "video":
            add("INFO", "Game log: splash video", d["name"],
                "the loading video '%s' could not be drawn (null texture)" % d["name"],
                "Cosmetic - a video codec / graphics driver quirk. It does not affect the mod; Ignore it.", None, loc)
    # ---- ships that cannot be built: grouped, they repeat a lot
    locked = [i for i in lg.items if i.kind == "locked"]
    hulls = [i for i in locked if i.data["reason"] == "LockedHull"]
    if hulls:
        wip = sum(1 for i in hulls if i.data["design"].upper().endswith("_WIP"))
        add("INFO", "Game log: designs with a locked hull", "%d designs" % len(hulls),
            "%d ship design(s) can't be built at game start because their hull isn't unlocked yet%s:  %s"
            % (len(hulls), (" (%d are marked _WIP)" % wip) if wip else "",
               ", ".join(clip_text(i.data["design"], 32) for i in hulls[:12]) + (" ..." if len(hulls) > 12 else "")),
            "Normal for tech-gated hulls. Worth a look only if one of these should be available from the start - then "
            "give its hull a tech / unlock. _WIP designs that aren't meant to ship can be deleted.",
            None, [(lg.path, hulls[0].line)])
    by_mod = {}
    for i in locked:
        if i.data["reason"] != "LockedHull" and i.data["what"]:
            by_mod.setdefault(i.data["what"], []).append(i)
    for name, its in sorted(by_mod.items()):
        m = mods.get(name.lower())
        if m is None:
            add("ERROR", "Game log: design uses unknown module", name,
                "module '%s' is not in ShipModules (used by %s)" % (name, ", ".join(clip_text(i.data["design"], 30) for i in its[:4])),
                "Create the module, or remove it from those designs - otherwise they can never be built.",
                None, [(lg.path, its[0].line)])
        else:
            add("INFO", "Game log: design needs a locked module", name,
                "module '%s' is not unlocked at game start, so %s can't be built yet"
                % (name, ", ".join(clip_text(i.data["design"], 30) for i in its[:4])),
                "Normal for tech-gated modules. If it should be available from the start, lower its TechLevel or unlock it "
                "with a starting tech.", ("module", (m.get("UID") or m.path.stem)), [loc_tag(m, "UID"), (lg.path, its[0].line)])


def proj_obj(proj, ref):
    kind, uid = ref
    for d in (proj.modules if kind == "module" else proj.weapons):
        if (d.get("UID") or d.path.stem).strip() == uid:
            return d
    return None


# ------------------------------------------------------------ debug / health check
def pick_keep(key, entries):
    """Ask which duplicate to keep; returns an index into entries, or None to cancel. (Tests replace this.)"""
    lines = "\n".join("%d)  Id %d:  %s" % (n + 1, e.id, clip_text(e.get("ENG"), 70)) for n, e in enumerate(entries))
    if len(entries) == 2:
        r = messagebox.askyesnocancel("Duplicate text key",
                                      "Key: %s\n\n%s\n\nYES = keep Id %d (1)\nNO = keep Id %d (2)\nCancel = change nothing"
                                      % (key, lines, entries[0].id, entries[1].id))
        return None if r is None else (0 if r else 1)
    from tkinter import simpledialog
    n = simpledialog.askinteger("Duplicate text key", "Key: %s\n\n%s\n\nNumber to keep (1-%d):" % (key, lines, len(entries)),
                                minvalue=1, maxvalue=len(entries))
    return None if n is None else n - 1


Fix = namedtuple("Fix", "label apply risky", defaults=(False,))                  # apply(proj) edits the loaded data (nothing is written until Save)
Issue = namedtuple("Issue", "sev cat item detail where hint ref locs fix")
SEV_RANK = {"ERROR": 0, "WARN": 1, "INFO": 2}


def issue_key(i):
    return "%s|%s" % (i.cat, i.item)


def tag_line(doc, tag):
    """1-based line of <tag> in an xml file's text, or None."""
    m = XmlDoc._find(doc.text, tag) if tag else None
    return doc.text.count("\n", 0, m.start()) + 1 if m else None


def loc_tag(doc, tag):
    return (doc.path, tag_line(doc, tag) or tag_line(doc, "UID") or 1)


def loc_entry(t, e, eng=False):
    ln = e.idx if (eng and e.idx is not None) else e.id_line
    return (t.path, (ln if ln is not None else 0) + 1)


def where_text(proj, locs):
    if not locs:
        return ""
    p, ln = locs[0]
    try:
        rel = str(Path(p).relative_to(proj.root))
    except Exception:
        rel = str(p)
    return "%s : line %d%s" % (rel, ln, ("   (+%d more)" % (len(locs) - 1)) if len(locs) > 1 else "")


def pretty_name(uid):
    s = re.sub(r"(?<=[a-z0-9])(?=[A-Z])", " ", uid)
    return re.sub(r"[_\s]+", " ", s).strip() or uid


def origin_of(doc):
    """Which part of the mod a module lives in, for the 'where are the missing icons' summary."""
    parts = list(doc.rel.parts)
    if any("bb+" in p.lower() for p in parts):
        return "bb+ folder"
    return parts[1] if len(parts) > 2 else "(top level)"


def diagnose(proj):
    """Scan the loaded mod for problems. Returns [Issue], worst first. Each issue carries the file positions it
    refers to (locs) and, when the program can repair it, a Fix."""
    out = []
    proj._design_files = None

    def add(sev, cat, item, detail, hint="", ref=None, locs=None, fix=None):
        locs = list(locs or [])
        out.append(Issue(sev, cat, item, detail, where_text(proj, locs), hint, ref, locs, fix))

    def set_fix(label, doc, tag, value):
        def run(p):
            doc.set(tag, value)
            return True
        return Fix(label, run)
    texdirs = proj.icon_dirs
    dirs = ", ".join(str(d) for d in texdirs) or "(no texture folders found)"
    uid_of = lambda d: d.get("UID") or d.path.stem
    bymod = {uid_of(m): m for m in proj.modules}
    for e in proj.errors:
        first = e.split(": ", 1)[0]
        p = proj.root / first
        add("ERROR", "Unreadable file", "", e, "Open the file and fix the XML / YAML so it can be read.",
            locs=[(p, 1)] if p.is_file() else None)
    # ---- upgrades whose name is the game's name spelled differently (Shield_Power_Bonus vs 'Shield Power Bonus'): the game ignores them
    try:
        _norm = lambda k: re.sub(r"[\s_\-]+", "", k.lower())
        _canon = {_norm(k): k for k in BONUS_INFO}
        for t in proj.techs:
            for i, b in enumerate(list(t.bonuses)):
                key = bonus_get(b, "BonusType") or bonus_get(b, "Name")
                if not key or key in BONUS_INFO or _norm(key) not in _canon:
                    continue
                good = _canon[_norm(key)]

                def run(p, t=t, i=i, key=key, good=good):
                    if i >= len(t.bonuses):
                        return False
                    o = t.bonuses[i]
                    nm, bt = bonus_get(o, "Name"), bonus_get(o, "BonusType")
                    if (bt or nm) != key:
                        return False
                    t.bonuses[i] = bonus_make(good if (nm == key or not nm) else nm, good if bt else "",
                                              bonus_get(o, "Bonus"), bonus_get(o, "BonusIndex") or "0", o)
                    return True
                add("WARN", "Upgrade the game does not know", "%s: %s" % (t.uid, key),
                    "Tech '%s' has an upgrade named '%s' (%s). The game's name is '%s', so the game ignores this upgrade and the tech does nothing." % (
                        t.uid, key, bonus_get(b, "Bonus") or "no amount", good),
                    "Auto-fix renames it to '%s'." % good, None, [(t.path, 1)],
                    Fix("%s: rename upgrade '%s' to '%s'" % (t.uid, key, good), run))
    except Exception as e:
        ERRLOG.append((time.strftime("%H:%M:%S"), "diagnose upgrade names", str(e)))
    # ---- hulls whose 3D model is missing (the game refuses to load the whole mod: "Could not find ModelPath=...")
    try:
        mtops = [proj.root] + [b / "Content" for b in getattr(proj, "base_roots", [])] + list(getattr(proj, "base_roots", []))
        if proj.game_dir:
            mtops += [Path(proj.game_dir) / "Content", Path(proj.game_dir)]

        def has_model(mp):
            raw_mp = mp
            mp = re.sub(r"^mod\s+", "", (mp or "").strip(), flags=re.I).replace("\\", "/").strip("/")
            if not mp:
                return True
            return proj.model_file(raw_mp) is not None or any((t / (mp + ".xnb")).is_file() or (t / mp).is_file() or (t / mp).is_dir() for t in mtops)
        have_base = any((t / "Model").is_dir() for t in mtops[1:])
        if have_base:
            mod_has_models = any(d.is_dir() and "model" in d.name.lower() for d in proj.root.iterdir())
            bad = [h for h in proj.hulls if h.get("ModelPath").strip() and not has_model(h.get("ModelPath"))
                   and (mod_has_models or not re.match(r"mod\s", h.get("ModelPath").strip(), re.I))]
            if len(bad) > max(5, len(proj.hulls) // 3):
                add("INFO", "Hull model check", "%d hulls" % len(bad),
                    "most hulls point at models the editor cannot find in the folders it knows (e.g. %s) - the game folder was probably "
                    "not found completely, so the model check was skipped." % bad[0].get("ModelPath"),
                    "Run the game once so blackbox.log tells the editor where the game is, then press Rescan.")
                bad = []
            for h in bad:
                mp = h.get("ModelPath").strip()
                fx = model_fix(proj, h.path.name, mp)
                add("ERROR", "Hull model missing", h.path.name,
                    "ModelPath=%s is not in the mod or the game's Content folder. The game stops loading the whole mod "
                    "('Mod load failed. Disabling mod and loading vanilla')." % mp,
                    "Auto-fix lists the likely models and you choose (a close spelling like ship09e -> ship09esmall is shown first); otherwise pick a model on the Ships tab, "
                    "or put the missing model folder back into the mod.", None, [(h.path, 1)], fx)
    except Exception:
        pass

    # ---- where things are searched
    proj.texture_index()
    src = ["%s (%s)" % (d, ("%d images" % proj.tex_counts[d]) if d in proj.tex_counts else "searched by name")
           for d in texdirs]
    base_txt = ("base game text: %s" % ", ".join("%s (%d entries)" % (p, n) for p, n in proj.ext_files)) \
        if proj.ext_files else "base game GameText.yaml: not found"
    outside = [d for d in texdirs if d != proj.root and d != proj.root / "Textures"]
    add("INFO", "Search sources", "textures + text",
        "textures searched in:  " + "   |   ".join(src) + "   ·   " + base_txt,
        ("Modules copied from BlackBox / bb+ borrow textures and text from the game folder. "
         + ("" if outside else "NO game folder was found - press 'Texture folder…' and pick <game>\\Content\\Textures. ")
         + ("" if proj.ext_files else "No base-game GameText.yaml was found, so text Ids that live there look 'missing' here.")),
        None, [])

    try:
        ri = proj.race_info()
        add("INFO", "Race filter", "%d races" % len(ri.names), "races: %s   ·   %s" % (", ".join(ri.names), ri.notes),
            "The Tech Tree's race filter ties a module to a race by a race-name prefix in its UID (Car_, Kling_ ...), a race-name "
            "folder in its path, or - if neither - the designs (Style=) that use it. If a race is missing or a module is under the "
            "wrong race, tell me how your files name it and I'll add the rule.", None, [])
    except Exception as e:
        add("INFO", "Race filter", "-", "could not be built: %s" % e)

    try:
        def fl(kind, n):
            ds = proj.dirs.get(kind) or []
            return "%s: %s (%d files)" % (kind, ", ".join(d.relative_to(proj.root).as_posix() for d in ds) if ds else "NOT FOUND", n)
        add("INFO", "Folders", "mod layout", "   ·   ".join((fl("shipmodules", len(proj.modules)), fl("weapons", len(proj.weapons)),
                                                          fl("technology", len(proj.techs)))),
            "Folders are found by name (ShipModules / Weapons / Technology) or, if the mod names them differently, by what the xml files "
            "inside are. Any sub-folder, however deep, is read, and the editor re-checks the folders each time you come back to it, so "
            "files and folders added later appear on their own.", None, [])
    except Exception:
        pass

    # ---- research tree
    if proj.techs:
        by_uid = {}
        for t in proj.techs:
            by_uid.setdefault(t.uid.lower(), []).append(t)
        for u, ts in sorted(by_uid.items()):
            if len(ts) > 1:
                add("WARN", "Duplicate tech UID", ts[0].uid, "%d tech files use this UID: %s" % (len(ts), ", ".join(str(x.rel) for x in ts)),
                    "Only one of them can be used by the game. Delete or rename the others.", ("tech", ts[0].uid), [])
        for t in proj.techs:
            for u in t.leads:
                if u.lower() not in by_uid:
                    add("INFO", "Tech link to unknown tech", "%s -> %s" % (t.uid, u),
                        "LeadsTo names a tech that is not in this mod's Technology folder", "Fine if it is a base-game tech; otherwise a typo "
                        "- open the Tech Tree & Module Builder tab and fix the link.", ("tech", t.uid), [])
        mods = {(m.get("UID") or m.path.stem).strip().lower() for m in proj.modules}
        unlocked = {mu.lower() for t in proj.techs for mu, _ in t.unlocks}
        missing = sorted({mu for t in proj.techs for mu, _ in t.unlocks if mu.lower() not in mods}, key=str.lower)
        if missing:
            add("INFO", "Tech unlocks unknown module", "%d module UIDs" % len(missing),
                "not found in this mod's ShipModules: %s%s" % (", ".join(missing[:12]), " ..." if len(missing) > 12 else ""),
                "Normal for base-game modules. A UID in this list that SHOULD be yours is a typo in the tech's ModulesUnlocked.", None, [])
        never = sorted((m.get("UID") or m.path.stem).strip() for m in proj.modules
                       if (m.get("UID") or m.path.stem).strip().lower() not in unlocked)
        if never:
            add("INFO", "Module not unlocked by any tech", "%d modules" % len(never),
                "no tech in this mod unlocks: %s%s" % (", ".join(never[:12]), " ..." if len(never) > 12 else ""),
                "Base-game techs may unlock some of these. For your own new modules, add them to a tech in the Tech Tree & Module Builder tab.", None, [])

    # ---- images
    def suggest_tex(rel, uid):
        """A texture that really exists and looks like the one meant (same name, or very similar)."""
        rel = (rel or "").replace("\\", "/")
        leaf = (rel or uid).rsplit("/", 1)[-1].lower()
        for e in (".png", ".gif") + PIL_EXTS:
            if leaf.endswith(e):
                leaf = leaf[:-len(e)]
        idx = proj.texture_index()
        hits = idx.get(leaf)
        if not hits:
            near = difflib.get_close_matches(leaf, list(idx), n=1, cutoff=0.88)
            hits = idx.get(near[0]) if near else None
        if not hits:
            return None
        want = rel.rsplit("/", 1)[0].lower() if "/" in rel else ""
        return next((h for h in hits if want and h.lower().startswith(want)), hits[0])

    def texrel(path):
        """'Modules/Aegis' for <Textures>/Modules/Aegis.png - the form IconTexturePath uses."""
        for d in texdirs:
            if d in path.parents:
                r = path.relative_to(d).with_suffix("").as_posix()
                return r[9:] if r.lower().startswith("textures/") else r
        return None

    state = {}                                   # origin -> {"ok": n, "guessed": n, "format": n, "missing": n}
    probed = {}
    elsewhere = {}                               # folder -> {(texture path, extension)} found by NAME outside Textures\\
    fmt_ext, fixable = {}, {"n": 0}              # what the 'format' icons are stored as / how many 'missing' ones have a fix

    def tally(doc, st):
        d = state.setdefault(origin_of(doc), {"ok": 0, "guessed": 0, "format": 0, "missing": 0})
        d[st] += 1

    def check_tex(doc, uid, ref, count=False):
        for tag in [t for t in doc.cur if t.endswith("TexturePath")]:
            rel = doc.get(tag).strip()
            locs = [loc_tag(doc, tag)]
            if not rel:
                if tag == "IconTexturePath":
                    s = suggest_tex("", uid)
                    add("WARN", "Missing image", uid, "%s is empty" % tag, "Set %s, e.g. Modules/%s" % (tag, uid), ref, locs,
                        set_fix("%s: set %s to '%s'" % (uid, tag, s), doc, tag, s) if s else None)
                    if count:
                        tally(doc, "guessed" if proj.find_icon(doc) else "missing")
                continue
            f = proj.find_file(rel)
            if f:
                if count and tag == "IconTexturePath":
                    tally(doc, "ok")
                if str(f) not in probed:
                    probed[str(f)] = proj.icon_probe(f) or proj.bad_icons.get(str(f))
                if probed[str(f)]:
                    add("WARN", "Image can't be read", uid, "%s: %s" % (f, probed[str(f)]),
                        ("Install Pillow (pip install pillow) - it opens PNG variants Tk can't. " if not Image else "")
                        + "If it still fails the file is damaged: re-export it as a normal 32-bit PNG.", ref, locs)
                continue
            if tag != "IconTexturePath":
                hit = proj.find_by_name(rel)
                if hit:                                  # e.g. projectile textures live in Model\\Projectiles\\Textures
                    elsewhere.setdefault(str(hit[0].parent), set()).add((rel, hit[0].suffix.lower()))
                    continue
            other = proj.find_other(rel)
            if other:
                add("INFO", "Unsupported image format", uid,
                    "%s '%s' exists as %s - this editor can only display %s" % (tag, rel, other.suffix, "/".join(proj.img_exts())),
                    "Nothing wrong for the game; add a .png copy if you want to see it here."
                    + ("" if Image or other.suffix.lower() not in PIL_EXTS else " (Pillow shows .dds/.tga: pip install pillow)"),
                    ref, locs)
                if count and tag == "IconTexturePath":
                    tally(doc, "format")
                    fmt_ext[other.suffix.lower()] = fmt_ext.get(other.suffix.lower(), 0) + 1
            else:
                s = suggest_tex(rel, uid)
                if not s and count and tag == "IconTexturePath":        # fall back to the usual Modules/<UID> name
                    g = proj.find_icon(doc)
                    s = texrel(g) if g else None
                fx = set_fix("%s: change %s '%s' to '%s'" % (uid, tag, rel, s), doc, tag, s) \
                    if s and s.lower() != rel.replace("\\", "/").lower() else None
                add("WARN", "Missing image", uid, "%s = '%s' - no image found%s" % (
                    tag, rel, ("  (but %s exists)" % s) if fx else ""),
                    "Not found by path or by file name (any extension) in the mod or the game's Content folder. Add the file or correct the path. "
                    "Searched: %s" % dirs, ref, locs, fx)
                if count and tag == "IconTexturePath":
                    tally(doc, "guessed" if proj.find_icon(doc) else "missing")
                    fixable["n"] += 1 if fx else 0
    for m in proj.modules:
        uid = uid_of(m)
        if "IconTexturePath" not in m.cur:
            s = suggest_tex("", uid)
            add("WARN", "Missing image", uid, "this module has no IconTexturePath tag",
                "Add <IconTexturePath>Modules/%s</IconTexturePath>" % uid, ("module", uid), [loc_tag(m, "UID")],
                set_fix("%s: add IconTexturePath '%s'" % (uid, s), m, "IconTexturePath", s) if s else None)
            tally(m, "guessed" if proj.find_icon(m) else "missing")
        check_tex(m, uid, ("module", uid), count=True)
    for w in proj.weapons:
        uid = uid_of(w)
        check_tex(w, uid, ("weapon", uid))
        rel = w.get("AnimationPath").strip() if "AnimationPath" in w.cur else ""
        if rel:
            status = proj.find_anim(rel)
            if status != "ok":
                add("WARN", "Missing animation frames", uid,
                    "AnimationPath '%s': %s" % (rel, "folder not found" if status == "no folder" else "no frames found"),
                    "Searched: %s" % dirs, ("weapon", uid), [loc_tag(w, "AnimationPath")])
    if elsewhere:
        tot_n = sum(len(v) for v in elsewhere.values())
        add("INFO", "Textures found outside Textures\\", "%d textures" % tot_n,
            "found by file name (not by the path in the XML) in:  " + "   |   ".join(
                "%s  (%d, e.g. %s%s)" % (d, len(v), sorted(v)[0][0], sorted(v)[0][1]) for d, v in sorted(elsewhere.items(), key=lambda kv: -len(kv[1]))[:6]),
            "Fine if that is where the game keeps them (projectile textures normally live in Model\\Projectiles\\Textures, often as "
            ".xnb). Only the names that exist NOWHERE are reported as 'Missing image'.", None, [])
    for path, why in proj.bad_icons.items():
        if path not in probed:
            add("WARN", "Image can't be read", Path(path).stem, "%s: %s" % (path, why),
                ("Install Pillow (pip install pillow). " if not Image else "") + "Otherwise re-export it as a normal 32-bit PNG.",
                None, [(Path(path), 1)])
    tot = {k: sum(v[k] for v in state.values()) for k in ("ok", "guessed", "format", "missing")}
    if tot["guessed"] + tot["format"] + tot["missing"]:
        n = len(proj.modules)
        rows = sorted(state.items(), key=lambda kv: -(kv[1]["missing"] + kv[1]["guessed"] + kv[1]["format"]))
        brk = "   |   ".join("%s: %d of %d" % (k, v["missing"] + v["guessed"] + v["format"], sum(v.values()))
                             for k, v in rows if v["missing"] + v["guessed"] + v["format"])
        why, todo = [], []
        if not outside:
            why.append("the game folder was not found, so anything the mod borrows from the base game can't be seen")
            todo.append("press 'Texture folder…' and pick <game>\\Content\\Textures (or run the game once - blackbox.log tells the "
                        "editor where the game is)")
        if tot["format"]:
            pil = [e for e in fmt_ext if e in PIL_EXTS]
            if pil and not Image:
                why.append("%d icons are %s files, which this editor can only show with Pillow" % (
                    sum(fmt_ext[e] for e in pil), "/".join(pil)))
                todo.append("run  pip install pillow  and restart the editor")
            xnb = fmt_ext.get(".xnb", 0)
            if xnb:
                why.append("%d icons are compiled .xnb files - the game reads them, this editor can't draw them" % xnb)
                todo.append("nothing to fix for the game; those boxes are just a viewer limitation")
        if tot["missing"] + tot["guessed"]:
            bb = state.get("bb+ folder", {})
            nb = bb.get("missing", 0) + bb.get("guessed", 0)
            bits = "%d module(s) have no icon file anywhere in the searched folders" % tot["missing"] if tot["missing"] else ""
            if nb and nb * 2 >= tot["missing"] + tot["guessed"]:
                bits += ("; " if bits else "") + "most of them (%d) are in the bb+ folder(s) - copied from BlackBox / bb+ without their textures" % nb
            if bits:
                why.append(bits)
            if fixable["n"]:
                todo.append("%d 'Missing image' row(s) have an auto-fix (the file exists under another path) - use 'Fixable' + 'Auto-fix all'" % fixable["n"])
            todo.append("for the rest, copy the textures into <mod>\\Textures\\Modules, or add their folder with 'Texture folder…'")
        add("WARN", "Icons summary", "%d of %d modules" % (tot["guessed"] + tot["format"] + tot["missing"], n),
            "%d show their real icon, %d show a guessed one, %d are in a format this editor can't draw, %d have no image.   "
            "Without a normal icon, by folder:  %s.   Why:  %s." % (tot["ok"], tot["guessed"], tot["format"], tot["missing"], brk,
                                                                   "; ".join(why) or "see the 'Missing image' rows"),
            "What to do:  " + ";  ".join(todo) + ".", None, [])

    # ---- weapon links
    for m in proj.modules:
        wt = m.get("WeaponType").strip()
        if wt and wt.lower() != "none" and not proj.weapon_for(m):
            near = difflib.get_close_matches(wt.lower(), list(proj.weap), n=1, cutoff=0.75)
            fx = None
            if near:
                w = proj.weap[near[0]]
                wuid = w.get("UID") or w.path.stem
                fx = set_fix("%s: change WeaponType '%s' to '%s'" % (uid_of(m), wt, wuid), m, "WeaponType", wuid)
            add("ERROR", "Missing weapon", uid_of(m), "WeaponType '%s' matches no <UID> in the Weapons folder" % wt,
                "Create the weapon file or fix the WeaponType.", ("module", uid_of(m)), [loc_tag(m, "WeaponType")], fx)
    for w in proj.weapons:
        if uid_of(w).strip().lower() not in proj.weapon_users:
            add("INFO", "Unused weapon", uid_of(w), "no module uses this weapon file",
                "Harmless, but it may be left over.", ("weapon", uid_of(w)), [loc_tag(w, "UID")])

    # ---- numbers the game cannot read (the mod then fails to load and the game drops back to vanilla)
    for m, tag, v in proj.number_problems():
        fx = None
        if re.fullmatch(r"\d+", v) and proj.text is not None:
            ents = [e for e in proj.text.entries if e.id == int(v)]
            if ents:
                def run(p, m=m, tag=tag, ents=ents):
                    n = p.next_text_id()
                    for e in ents:
                        e.set("Id", str(n))
                    m.set(tag, str(n))
                    p.text.reindex()
                    p.rebuild_maps()
                    return True
                fx = Fix("%s: move text Id %s to a free Id inside the game's range and point %s at it" % (uid_of(m), v, tag), run)
        add("ERROR", "Number the game cannot read", uid_of(m), "%s is %s - the game needs a whole number from 0 to 65535 here" % (tag, v),
            "With a bad number the game reports 'Mod load failed ... Value was either too large or too small for a UInt16' and loads vanilla. "
            "Auto-fix moves the text to a free Id inside the range and points the module at it.", ("module", uid_of(m)), [loc_tag(m, tag)], fx)

    # ---- duplicate UIDs
    def dup_fix(kind, docs, ds):
        """Keep the UID on the file whose name matches it; give each other file its own UID (its file name if that is free)."""
        uid = uid_of(ds[0]).strip()
        keep = next((d for d in ds if d.path.stem.lower() == uid.lower()), ds[0])
        taken = {uid_of(x).strip().lower() for x in docs}
        plan = []
        for d in ds:
            if d is keep:
                continue
            new = None
            for c in (d.path.stem, "%s_%s" % (uid, d.path.parent.name)):
                if c and c.lower() not in taken:
                    new = c
                    break
            k = 2
            while new is None:
                c = "%s_%d" % (uid, k)
                if c.lower() not in taken:
                    new = c
                k += 1
            taken.add(new.lower())
            plan.append((d, new))

        def run(p):
            for d, new in plan:
                d.set("UID", new)
            p.rebuild_maps()
            return True
        return Fix("%s '%s': %s keeps it; %s" % (kind, uid, keep.rel, "; ".join("%s becomes '%s'" % (d.rel, n) for d, n in plan)), run)
    for docs, kind in ((proj.modules, "module"), (proj.weapons, "weapon")):
        seen = {}
        for d in docs:
            seen.setdefault(uid_of(d).strip().lower(), []).append(d)
        for uid, ds in sorted(seen.items()):
            if len(ds) > 1:
                users = proj.weapon_users.get(uid, []) if kind == "weapon" else []
                add("ERROR", "Duplicate UID", uid, "%d %s files use this UID: %s%s" % (
                    len(ds), kind, ", ".join(str(d.rel) for d in ds),
                    ("   |   modules using it: " + ", ".join(users[:6])) if users else ""),
                    "Every UID must be unique. Auto-fix keeps the UID on the file whose name matches it and renames the others "
                    "(a renamed file simply becomes its own, separate %s). Anything that refers to the old UID keeps using the file "
                    "that kept it." % kind, (kind, uid_of(ds[0])), [loc_tag(d, "UID") for d in ds], dup_fix(kind, docs, ds))
        for d in docs:
            u = d.get("UID").strip()
            if u and u.lower() != d.path.stem.lower():
                add("INFO", "UID differs from file name", u, "file is %s" % d.path.name,
                    "Usually fine; just easy to trip over.", (kind, u), [loc_tag(d, "UID")])

    # ---- text ids
    t = proj.text
    if t:
        ids = sorted(t.by_id)
        nxt = proj.next_text_id()
        add("INFO", "GameText summary", "GameText.yaml", "%d entries, highest Id %d  ->  next free Id: %d" % (len(t.entries), ids[-1] if ids else 0, nxt),
            "Use the next free Id for any new text." + ((" (counts the base game's Ids too: %d entries)" % len(proj.ext_by_id)) if proj.ext_by_id else ""),
            None, [(t.path, 1)])
        style_cache = {}

        def key_style(tag):
            if tag not in style_cache:
                cnt = {}
                for m in proj.modules:
                    e, u = proj.text_for(m, tag), uid_of(m)
                    if e and not e.new:
                        i = e.key.lower().find(u.lower())
                        if i >= 0:
                            k = (e.key[:i], e.key[i + len(u):])
                            cnt[k] = cnt.get(k, 0) + 1
                style_cache[tag] = max(cnt, key=cnt.get) if cnt else ("", "_Name" if tag == "NameIndex" else "_Desc")
            return style_cache[tag]

        def new_text(m, tag):
            uid = uid_of(m)
            if tag == "DescriptionIndex":
                return m.get("Description").strip() or "TODO: description for %s" % uid
            return pretty_name(uid)

        def key_for(m, tag):
            pre, post = key_style(tag)
            return pre + uid_of(m) + post

        def add_text_fix(m, tag, wanted_id=None):
            """Create the missing GameText entry (the module's own Id), or - when wanted_id is None - a NEW Id."""
            uid = uid_of(m)

            def run(p):
                i = wanted_id if wanted_id is not None else p.next_text_id()
                if wanted_id is not None and p.text_known(i):
                    return False                                   # another fix already created it
                if wanted_id is None and m.get("NameIndex").strip() != m.get("DescriptionIndex").strip():
                    return False                                   # already separated
                p.text.add_entry(key_for(m, tag), i, new_text(m, tag))
                m.set(tag, str(i))
                p.rebuild_maps()
                return True
            what = "name" if tag == "NameIndex" else "description"
            if wanted_id is not None:
                label = "%s: add the missing GameText entry Id %s (%s \"%s\")" % (uid, wanted_id, what, clip_text(new_text(m, tag), 36))
            else:
                label = "%s: give the %s its own new GameText entry (next free Id, \"%s\") and point %s at it" % (
                    uid, what, clip_text(new_text(m, tag), 36), tag)
            return Fix(label, run, risky=wanted_id is not None and not proj.ext_by_id)   # no base text to check against
        byid, bykey = {}, {}
        for e in t.entries:
            byid.setdefault(e.id, []).append(e)
            bykey.setdefault(e.key, []).append(e)
            if e.idx is None:
                add("WARN", "Text entry without ENG", "Id %d" % e.id, "key '%s' has no ENG line" % e.key, "",
                    ("text", e.id), [loc_entry(t, e)])
        dups = {i: es for i, es in byid.items() if len(es) > 1}
        def entry_score(e, uid, inline=""):
            """How well a text entry fits a module / tech: its key mentions the UID, its text is the module's name / description."""
            k, sc = e.key.lower(), 0.0
            if uid and uid.lower() in k:
                sc += 3
            txt = e.get("ENG").strip().lower() if e.idx is not None else ""
            if txt and (txt == pretty_name(uid).lower() or (inline.strip() and txt == inline.strip().lower())):
                sc += 2
            toks = set(re.findall(r"[a-z0-9]+", re.sub(r"(?<=[a-z0-9])(?=[A-Z])", " ", uid).lower()))
            return sc + 0.5 * len(toks & set(re.findall(r"[a-z0-9]+", k)))
        for i, es in sorted(dups.items()):
            used = proj.text_users.get(i, [])
            refs = [(m, tag, uid_of(m), m.get("Description")) for m in proj.modules
                    for tag in ("NameIndex", "DescriptionIndex") if m.get(tag).strip() == str(i)]
            refs += [(d, tag, d.get("UID") or d.path.stem, "") for d, tag in proj.other_text_refs(i)]
            plan = {}                                   # position in es -> [(xml doc, tag)] that belong to that later entry
            for doc, tag, u, inl in refs:
                sc = [entry_score(e, u, inl) for e in es]
                best = max(range(len(es)), key=lambda k: (sc[k], -k))
                if best > 0 and sc[best] > sc[0]:
                    plan.setdefault(best, []).append((doc, tag))
            moved = [(doc, tag) for v in plan.values() for doc, tag in v]

            def renum(p, es=es, plan=plan):
                n = p.next_text_id()                    # the end of the current list
                for k, e in enumerate(es[1:], 1):
                    e.set("Id", str(n))
                    for doc, tag in plan.get(k, []):    # ...and the xml that uses that entry follows it
                        doc.set(tag, str(n))
                    n += 1
                p.text.reindex()
                p.rebuild_maps()
                return True
            add("ERROR", "Duplicate text Id", "Id %d" % i,
                "%d entries share this Id:  %s" % (len(es), "   |   ".join(
                    "%s (line %s): %s" % (e.key, (e.id_line + 1) if e.id_line is not None else "?", clip_text(e.orig.get("ENG", ""))) for e in es))
                + (("   |   used by: " + ", ".join(used)) if used else ""),
                "Auto-fix gives each later entry a new Id at the end of the list (next free: %d) and changes the xml file(s) that "
                "belong to it to the new number. An xml is matched to an entry by its UID appearing in the entry's key / text; "
                "anything it can't tell stays on the first entry - check those by hand." % nxt,
                ("text", i), [loc_entry(t, e) for e in es] + [loc_tag(d, tg) for d, tg in moved[:6]],
                Fix("Id %d: the %d later entr%s (%s) get new Ids from %d up (end of the list); %s; the first keeps Id %d"
                    % (i, len(es) - 1, "y" if len(es) == 2 else "ies", ", ".join(e.key for e in es[1:]), nxt,
                       ("xml updated: " + ", ".join("%s %s" % (d.path.name, tg) for d, tg in moved[:8])) if moved
                       else "NO xml changed (could not tell which file uses the later entries)", i), renum))
        def junk_text(e):
            tx = e.get("ENG").strip()
            return not tx or tx.startswith(">")             # '>orbital cannons mk1': a leftover placeholder copy

        def dupkey_fix(k, es):
            """One key, several entries. Exactly one has real text: delete the placeholder copies. All have real text: ask which Id
            to keep when the fix is applied. Either way the losers are deleted and whatever used their Ids (modules, techs ...)
            is pointed at the kept entry."""
            good = [e for e in es if not junk_text(e)]
            bad = [e for e in es if junk_text(e)]
            if not all(t.can_remove(e) for e in es):
                return None

            def refs_of(e):
                return [(m, tag) for m in proj.modules for tag in ("NameIndex", "DescriptionIndex") if m.get(tag).strip() == str(e.id)] \
                    + proj.other_text_refs(e.id)

            def drop(p, keep, losers):
                for e in losers:
                    for doc, tag in refs_of(e):
                        doc.set(tag, str(keep.id))
                    p.text.remove_entry(e)
                p.rebuild_maps()
                return True
            if len(good) == 1 and bad:
                keep = good[0]
                n = sum(len(refs_of(e)) for e in bad)
                return Fix("Key '%s': keep Id %d (\"%s\"); delete the placeholder cop%s Id %s (\"%s\")%s" % (
                    k, keep.id, clip_text(keep.get("ENG"), 28), "y" if len(bad) == 1 else "ies", ", ".join(str(e.id) for e in bad),
                    clip_text(bad[0].get("ENG"), 20), ("; %d xml reference(s) switched to Id %d" % (n, keep.id)) if n else
                    "; nothing refers to it"), lambda p: drop(p, keep, bad))
            pool = good if len(good) > 1 else (es if not good else [])
            if pool:
                def choose(p):
                    i = pick_keep(k, pool)
                    if i is None:
                        return False
                    return drop(p, pool[i], [e for e in es if e is not pool[i]])
                return Fix("Key '%s': you choose which of Ids %s to keep (asked when you apply); the other%s deleted and anything "
                           "using %s switched to the one you keep" % (k, ", ".join(str(e.id) for e in pool),
                                                                      " is" if len(es) == 2 else "s are", "it is" if len(es) == 2 else "them is"), choose)
            return None
        for k, es in sorted(bykey.items()):
            if len(es) > 1:
                add("WARN", "Duplicate text key", k, "key appears %d times (Ids %s)%s" % (
                    len(es), ", ".join(str(e.id) for e in es),
                    "   |   texts: " + "  /  ".join("'%s'" % clip_text(e.get("ENG"), 30) for e in es)),
                    "Auto-fix: if one copy has real text and the other is a placeholder (empty or starting with '>'), the placeholder is "
                    "deleted and anything using its Id is moved to the real entry. If all copies have real text, you are asked which "
                    "Id to keep when you apply the fix.", ("text", es[0].id), [loc_entry(t, e) for e in es], dupkey_fix(k, es))
        from_base = {}
        for m in proj.modules:
            uid = uid_of(m)
            for tag in ("NameIndex", "DescriptionIndex"):
                v = m.get(tag).strip()
                loc = [loc_tag(m, tag)]
                if not v:
                    add("WARN", "Missing text index", uid, "no %s set" % tag, "", ("module", uid), loc)
                elif not v.isdigit():
                    digits = re.sub(r"\D", "", v)
                    fx = set_fix("%s: change %s '%s' to %s" % (uid, tag, v, digits), m, tag, digits) \
                        if digits and proj.text_known(int(digits)) else None
                    add("ERROR", "Bad text index", uid, "%s = '%s' is not a number" % (tag, v), "", ("module", uid), loc, fx)
                elif int(v) not in t.by_id:
                    if int(v) in proj.ext_by_id:                   # defined by the base game: fine
                        from_base.setdefault(uid, []).append(tag)
                    else:
                        warn = "" if proj.ext_files else \
                            "  CAREFUL: no base-game GameText was found, so if this Id really lives there, adding it here would override it."
                        add("ERROR", "Text Id not found", uid, "%s %s has no entry in GameText.yaml%s" % (
                            tag, v, "" if proj.ext_files else " (and no base-game GameText was found to check)"),
                            "Add an entry with Id %s, or point the module at an existing Id.%s" % (v, warn), ("module", uid), loc,
                            add_text_fix(m, tag, int(v)))
                elif int(v) in dups:
                    add("WARN", "Index points at a duplicate Id", uid, "%s %s is defined %d times in GameText.yaml" % (tag, v, len(dups[int(v)])),
                        "Fix the duplicate Id first (see the Duplicate text Id entry).", ("text", int(v)),
                        loc + [loc_entry(t, e) for e in dups[int(v)]])
            n, d = m.get("NameIndex").strip(), m.get("DescriptionIndex").strip()
            if n and n == d:
                shared = proj.text_display(m, "NameIndex")
                txt = shared.get("ENG").strip() if shared else ""
                inline = m.get("Description").strip()
                looks_desc = bool(txt) and (len(txt) > 60 or txt.endswith(".") or (inline and txt.lower() == inline.lower()))
                tag = "NameIndex" if looks_desc else "DescriptionIndex"
                add("ERROR", "Name and description share an index", uid, "NameIndex and DescriptionIndex are both %s" % n,
                    "They need different Ids, otherwise the name and description show the same text. The text there reads like a "
                    "%s, so auto-fix gives the %s its own new entry." % ("description" if looks_desc else "name",
                                                                       "name" if looks_desc else "description"),
                    ("module", uid), [loc_tag(m, "NameIndex"), loc_tag(m, "DescriptionIndex")], add_text_fix(m, tag))
            ne, de = proj.text_for(m, "NameIndex"), proj.text_for(m, "DescriptionIndex")
            if ne and de and ne is not de:
                dt = de.get("ENG").strip().lower()
                if dt and dt in (ne.get("ENG").strip().lower(), uid.lower()):
                    inline = m.get("Description").strip()
                    fx = None
                    if inline:
                        def copy_desc(p, de=de, m=m):
                            de.set("ENG", m.get("Description").strip())
                            return True
                        fx = Fix("%s: copy the inline <Description> into GameText Id %d" % (uid, de.id), copy_desc)
                    add("INFO", "Placeholder description text", uid, "the GameText description is just '%s'" % de.get("ENG").strip(),
                        "The real description may be in the module's inline <Description>; write it into GameText too.",
                        ("module", uid), [loc_entry(t, de, True), loc_tag(m, "Description")], fx)
        if from_base:
            add("INFO", "Text from the base game", "%d modules" % len(from_base),
                "these modules use text Ids that are defined in the base game's GameText, not in the mod's: %s"
                % ", ".join(list(from_base)[:10]) + (" ..." if len(from_base) > 10 else ""),
                "That is fine - the game merges both. (They would be 'Text Id not found' errors if the editor didn't look at the base game.)",
                None, [(proj.ext_files[0][0], 1)] if proj.ext_files else [])
        for tag in ("NameIndex", "DescriptionIndex"):
            groups = {}
            for m in proj.modules:
                v = m.get(tag).strip()
                if v.isdigit():
                    groups.setdefault(int(v), []).append(m)
            for i, ms in sorted(groups.items()):
                if len(ms) > 1:
                    us = [uid_of(x) for x in ms]
                    add("WARN", "Shared index", "%s %d" % (tag, i), "used by %d modules: %s" % (len(ms), ", ".join(us)),
                        "Fine if they should share text, otherwise give each its own Id.", ("module", us[0]),
                        [loc_tag(x, tag) for x in ms])
        nm = {int(m.get("NameIndex")) for m in proj.modules if m.get("NameIndex").strip().isdigit()}
        ds = {int(m.get("DescriptionIndex")) for m in proj.modules if m.get("DescriptionIndex").strip().isdigit()}
        for i in sorted(nm & ds):
            if i not in t.by_id:
                continue
            users = proj.text_users.get(i, [])
            add("WARN", "Index used as name and description", "Id %d" % i,
                "used as a name by some modules and a description by others: %s" % ", ".join(users), "", ("text", i),
                [loc_entry(t, t.by_id[i])] + [loc_tag(bymod[u], "NameIndex") for u in users[:4] if u in bymod])

    # ---- ship designs of the mod (the base game's own designs are not checked here)
    try:
        if proj.design_dirs():
            ctx = proj.design_context()
            mine = [d for d in proj.load_designs() if not d.is_base]
            for d in mine:
                ps = [p for p in proj.design_problems(d, ctx) if p[0] in ("ERROR", "WARN")]
                if not ps:
                    continue
                sev = "ERROR" if any(p[0] == "ERROR" for p in ps) else "WARN"
                shown = "; ".join(t for _s, t in ps[:3]) + ("; +%d more" % (len(ps) - 3) if len(ps) > 3 else "")
                fx = None
                try:
                    hf, uf, fuzzy = proj.design_fix_plan(d, ctx)
                    if hf or uf:
                        parts = (["Hull '%s' → '%s'" % (d.hull, hf["Hull"])] if hf else []) + ["module '%s' → '%s'" % kv for kv in list(uf.items())[:4]]
                        if len(uf) > 4:
                            parts.append("+%d more modules" % (len(uf) - 4))

                        def run(p, d=d, hf=hf, uf=uf):
                            return p.apply_design_fix(d, hf, uf)
                        fx = Fix("Design '%s' (%s): %s" % (d.name or d.sub, d.sub, "; ".join(parts)), run, risky=fuzzy)
                except Exception:
                    log_exc("design fix plan")
                if fx is None and any(t.startswith("Another design has the same name '") for _s, t in ps):
                    others = [x for x in ctx["names"].get(d.name.strip().lower(), ()) if x is not d and x.name.strip() == d.name.strip() and not x.is_base]
                    if others:
                        def run(p, d=d, others=others):
                            pair = [d] + others[:1]
                            opts = ["Rename the one in '%s'  (%s)" % (x.sub, x.path.name) for x in pair] + ["Leave both as they are"]
                            pick = pick_option("Two designs have the same name",
                                               "'%s' is used by both:\n  %s\n  %s\n\nThe second one overrides the first in the game. Which one gets a new name "
                                               "(its folder is added: '%s (folder)')? Ships that refer to the old name by name will need updating."
                                               % (d.name, pair[0].sub, pair[1].sub, d.name), opts)
                            if not pick or pick == opts[-1]:
                                return False
                            x = pair[opts.index(pick)]
                            new = "%s (%s)" % (x.name.strip(), re.sub(r"[\\/:*?\"<>|]", " ", x.sub.split("/")[0].split("\\")[0]).strip() or "copy")
                            dd = p.design_doc_for_path(x.path)
                            dd.set("Name", new)
                            if dd.path.suffix.lower() == ".design":
                                dd.rename_file(new)
                            p._salvage = None
                            return True
                        fx = Fix("%s: two designs share the name - you choose which one to rename" % (d.name or d.sub), run, risky=True)
                add(sev, "Ship design problem", d.name or d.sub, shown,
                    "Open the Ships tab to see the design on its hull. Auto-fix (⚙) fixes a hull / module name that is only spelled or "
                    "capitalised differently, or has one clear close match; close-match fixes are not part of 'Auto-fix all' - pick them one by one. "
                    "Otherwise fix it in the game's design screen, or restore the missing hull / module.",
                    None, [(d.path, 1)], fx)
            add("INFO", "Hull search", "%d hulls" % len(ctx["hull_keys"]),
                "mod hulls: %d   ·   base-game hulls: %d (%d found outside a folder called Hulls)   ·   searched: %s" % (
                    len(proj.hulls), len(proj.base_hulls), getattr(proj, "deep_hulls", 0),
                    ", ".join(str(b) for b in getattr(proj, "base_roots", [])) or "(no game folder found - press 'Texture folder…' or open the mod from inside the game's Mods folder)"),
                "Designs and techs name hulls like Terran/Gunboat. If a hull you know exists is reported missing, copy this row and send it to me.")
            have = set()
            for d in proj.load_designs():
                h = ctx["find"](d.hull) if d.hull else None
                if h is not None:
                    have.add(proj.hull_key(h).lower())
            lone = [proj.hull_key(h) for h in proj.hulls if proj.hull_key(h).lower() not in have]
            if lone:
                add("INFO", "Hull with no design", "%d of your hulls" % len(lone),
                    ", ".join(lone[:8]) + (" ..." if len(lone) > 8 else ""),
                    "Players cannot start with a ready-made ship of these hulls. Fine for hulls meant to be designed by the player.")
    except Exception as e:
        add("INFO", "Ship designs", "-", "could not be checked: %s" % e)

    # ---- the ship names in each race file must match a design's name AND its file name exactly (the game compares exactly)
    try:
        RACE_SHIP_TAGS = ("StartingShip", "StartingScout", "PrototypeShip", "DefaultSmallTransport", "DefaultTroopShip", "DefaultColonyShip", "DefaultConstructor",
                          "DefaultAssaultShuttle", "DefaultSupplyShuttle", "DefaultResearchStation", "DefaultMiningShip", "DefaultMiningStation",
                          "DefaultSalvageShip")
        designs = proj.load_designs() if proj.design_dirs() else []
        if designs:
            norm = lambda t: re.sub(r"[^a-z0-9]", "", t.lower())
            pend = {x.orig_path: x for x in proj.extra_docs if isinstance(x, DesignDoc)}
            nm = lambda dsg: ((pend[dsg.path].cur.get("Name") or "") if dsg.path in pend else (dsg.name or "")).strip()
            st = lambda dsg: pend[dsg.path].path.stem if dsg.path in pend else dsg.path.stem
            by_exact = {}
            for dsg in designs:
                by_exact.setdefault(nm(dsg), []).append(dsg)
            by_norm = {}
            for dsg in designs:
                by_norm.setdefault(norm(nm(dsg)), []).append(dsg)
            for rdoc in proj.race_docs():
                rname = (rdoc.get("Name") or rdoc.path.stem).strip()
                blanks = []
                for tag in RACE_SHIP_TAGS:
                    raw = rdoc.get(tag)
                    val = (raw or "").strip()
                    if not val:
                        if rdoc.get("Faction").strip() in ("", "0") and rdoc.get("IsRemnantFaction").strip().lower() != "true" and not getattr(rdoc, "vanilla", False):
                            blanks.append(tag)
                        continue
                    loc_r = [(rdoc.path, tag_line(rdoc, tag) or 1)]
                    ex = by_exact.get(val, [])
                    if ex and raw == val:
                        d0 = ex[0]
                        if d0.path.suffix.lower() == ".design" and not d0.is_base and st(d0) != val:
                            def run(p, d0=d0, rdoc=rdoc, tag=tag, val=val):
                                stem = st(d0)
                                p.design_doc_for_path(d0.path).set("Name", stem)        # the game uses the file name when the two differ
                                for r2 in p.race_docs():
                                    for t2 in RACE_SHIP_TAGS:
                                        if r2.get(t2).strip() == val and t2 in r2.orig:
                                            r2.set(t2, stem)
                                p._salvage = None
                                return True
                            add("WARN", "Race ship tag: file name differs", "%s  %s" % (rname, tag),
                                "%s = '%s' but the design file is called '%s'. The game uses the file name, so the ship may not be found." % (tag, val, d0.path.name),
                                "Auto-fix sets the name inside the design and every race tag that used it to the file name.", None, loc_r + [(d0.path, 1)],
                                Fix("%s: make %s, the design name and its file name all say '%s'" % (rname, tag, st(d0)), run))
                        continue
                    close = by_exact.get(val) or by_norm.get(norm(val), [])
                    if close:
                        d0 = close[0]
                        want = st(d0) if (d0.path.suffix.lower() == ".design" and not d0.is_base) else nm(d0)

                        def run(p, d0=d0, rdoc=rdoc, tag=tag, want=want):
                            if d0.path.suffix.lower() == ".design" and not d0.is_base and (nm(d0) != want.strip() or st(d0) != want.strip()):
                                dd = p.design_doc_for_path(d0.path)
                                want = want.strip()
                                dd.set("Name", want)
                                if dd.path.stem != want:
                                    dd.rename_file(want)                    # a stray space in the file name too
                            rdoc.set(tag, want)
                            return True
                        add("WARN", "Race ship tag: spelling differs", "%s  %s" % (rname, tag),
                            "%s = '%s' but the design is '%s' (capitals / spaces / _ count).%s" % (tag, raw, nm(d0), "  The value has stray spaces." if raw != val else ""),
                            "Auto-fix writes the exact design name into the race file.", None, loc_r + [(d0.path, 1)],
                            Fix("%s: set %s to exactly '%s'" % (rname, tag, want), run))
                    elif proj.base_roots:
                        add("WARN", "Race ship tag: no such design", "%s  %s" % (rname, tag),
                            "%s = '%s' but no design has that name (searched the mod%s)." % (tag, val, " and the base game's designs"),
                            "Pick an existing design name or add the design. (Check the designs on the Ships tab.)", None, loc_r)
                if blanks:
                    ROLES = {"StartingShip": ("frigate", "corvette"), "StartingScout": ("scout",), "PrototypeShip": ("prototype", "capital"),
                             "DefaultSmallTransport": ("freighter",), "DefaultTroopShip": ("troopship", "troop"), "DefaultColonyShip": ("colony",),
                             "DefaultConstructor": ("construction",), "DefaultAssaultShuttle": ("troop", "troopship"), "DefaultSupplyShuttle": ("supply",),
                             "DefaultResearchStation": ("station", "platform"), "DefaultMiningShip": ("freighter", "support"),
                             "DefaultMiningStation": ("station", "platform"), "DefaultSalvageShip": ("support", "scout", "freighter")}
                    _m = re.search(r"<ShipType>\s*([^<]*?)\s*</ShipType>", rdoc.text or "")
                    shiptype = _m.group(1).strip() if _m else ""
                    rhulls = proj.race_hulls(shiptype)

                    def run(p, rdoc=rdoc, rname=rname, shiptype=shiptype, blanks=list(blanks), rhulls=rhulls):
                        made, n = [], 0
                        for t in blanks:
                            lab = re.sub(r"(?<!^)(?=[A-Z])", " ", t.replace("Default", "")).strip()
                            nm_, _notes = p.make_starter_design(t, lab, rname, shiptype, rhulls, made)
                            if nm_:
                                made.append(nm_)
                                rdoc.set(t, nm_)
                                n += 1
                        return n > 0
                    add("ERROR" if "StartingScout" in blanks else "WARN", "Race ship slot empty", "%s  %s" % (rname, ", ".join(blanks[:4]) + (" ..." if len(blanks) > 4 else "")),
                        "%d ship slot(s) of this race are empty. The game then falls back to its own default ships, which this mod may not have: "
                        "the AI cannot build a scout / colony ship and the game can stop at the start of a new game (blackbox.log: 'Assert Ship Exists failed' ... 'not able to find any Scout ships')." % len(blanks),
                        "Auto-fix makes a NEW design for each empty slot on this race's own hulls (Hulls/%s/): warships, scouts and freighters with the design generator, "
                        "the other kinds with a simple recipe. Open them in the game's designer to finish them. A game cannot share designs between races." % (shiptype or "<ship type>"),
                        None, [(rdoc.path, 1)],
                        Fix("%s: generate designs for %d empty ship slot(s) on its own hulls" % (rname, len(blanks)), run) if rhulls else None)
    except Exception as e:
        add("INFO", "Race ship tags", "-", "could not be checked: %s" % e)

    # ---- tags the game does not read, and values it cannot read (checked against the game's own classes, see game_tags())
    try:
        g = game_tags()
        sets = (("Weapons", proj.weapons), ("ShipModules", proj.modules), ("Technology", proj.techs), ("Buildings", proj.buildings),
                ("Races", proj.races), ("Troops", proj.troops), ("SolarSystems", proj.systems), ("Encounter Dialogs", proj.encounters),
                ("DiplomacyDialogs", proj.dialogs), ("Exploration Events", proj.events))
        for folder, docs in sets:
            cname = g["files"].get(folder)
            if not cname or not docs:
                continue
            unknown, badval = {}, {}
            for d in docs:
                for t in list(d.cur):
                    if d.cur.get(t) == "{nested}":
                        continue
                    ok, spec, valid = game_tag_resolve(g, cname, t)
                    if not ok:
                        unknown.setdefault(t, []).append((d, game_tag_suggest(t, valid)))
                    elif spec and "/" not in t and d.cur.get(t) is not None:
                        why = game_value_problem(spec, d.cur[t])
                        if why:
                            badval.setdefault(t, []).append((d, why))
            for t, lst in sorted(badval.items()):
                add("ERROR", "Value the game cannot read", "%s: <%s>" % (folder, t),
                    "%d file(s) have a value the game cannot read for <%s> (%s), e.g. %s = '%s'. The game fails to load such a file." % (
                        len(lst), t, lst[0][1], lst[0][0].path.name, short((lst[0][0].cur.get(t) or "").strip(), 30)),
                    "Open the file and correct the value.", None, [(d.path, tag_line(d, t) or 1) for d, _w in lst[:6]])
            sug = {}
            for t, lst in unknown.items():
                if lst[0][1]:
                    sug[t] = lst
            for t, lst in sorted(sug.items()):
                new = lst[0][1]
                targets = [d for d, _s in lst if "/" not in t and hasattr(d, "remove_tag") and new not in d.cur]

                def run(p, t=t, new=new, targets=targets):
                    for d in targets:
                        if t in d.cur and new not in d.cur:
                            d.set(new, d.cur[t])
                            d.remove_tag(t)
                    return True
                add("WARN", "Tag the game does not read", "%s: <%s>" % (folder, t),
                    "%d file(s) use <%s> but the game reads <%s>. XML tags are case-sensitive and the game skips tags it does not know, so the value is IGNORED and the game's default is used." % (
                        len(lst), t, new),
                    "Auto-fix renames the tag in every file where that is safe.", None, [(d.path, tag_line(d, t) or 1) for d, _s in lst[:6]],
                    Fix("Rename <%s> to <%s> in %d file(s)" % (t, new, len(targets)), run, True) if targets else None)
            rest = {t: lst for t, lst in unknown.items() if t not in sug}
            if rest:
                items = sorted(rest.items(), key=lambda kv: -len(kv[1]))
                add("INFO", "Tags the game does not read", "%s (%d tag name(s))" % (folder, len(rest)),
                    "The game never reads these, so they have no effect (harmless leftovers or notes): " + ", ".join(
                        "%s (%d)" % (t, len(lst)) for t, lst in items[:14]) + (" ..." if len(items) > 14 else ""),
                    "Nothing to fix unless you expected one of them to do something. The Help topic 'Game tags' explains how the list is made.",
                    None, [(items[0][1][0][0].path, tag_line(items[0][1][0][0], items[0][0]) or 1)])
    except Exception as e:
        log_exc("tag check")
        add("INFO", "Tag check", "-", "could not be checked: %s" % e)

    # ---- hull unlocks in the tech files carry <ShipType>; without it a hull unlocks for every race
    try:
        plan = proj.tech_type_plan()
        if plan:
            byt = {}
            for t, n, ty in plan:
                byt.setdefault(t.uid, []).append("%s -> %s" % (n, ty))

            def run(p):
                for t2, n2, ty2 in p.tech_type_plan():
                    t2.hull_type[n2.lower()] = ty2
                return True
            add("WARN", "Tech hull unlock lost its ShipType", "%d hull unlock(s) in %d tech(s)" % (len(plan), len(byt)),
                "These hull unlocks have no <ShipType>, so every race gets those ships in the research screen. The race is known from another tech file or from a backup: " +
                "; ".join("%s: %s" % (u, ", ".join(v[:2]) + (" ..." if len(v) > 2 else "")) for u, v in list(byt.items())[:4]),
                "Auto-fix writes the missing <ShipType> back (taken from the same hull in another tech file, from your backups, or the hull's own Style).",
                None, [(t.path, 1) for t, _n, _ty in plan[:6]], Fix("Restore the <ShipType> of %d hull unlock(s)" % len(plan), run))
    except Exception as e:
        add("INFO", "Tech hull unlocks", "-", "could not be checked: %s" % e)

    # ---- a race finds its ships through the Style written in the hull files: it must equal the race's ShipType exactly
    try:
        styles = {}
        for h in list(proj.hulls) + list(proj.base_hulls):
            styles.setdefault(h.get("Style").strip(), []).append(h)
        low = {k.lower(): k for k in styles if k}
        for rdoc in list(proj.races) + list(proj.base_races):
            key = (rdoc.get("Traits/ShipType") or rdoc.get("ShipType") or "").strip()
            if not key or rdoc.get("IsPirateFaction").strip().lower() == "true" or rdoc.get("IsRemnantFaction").strip().lower() == "true":
                continue
            rname = (rdoc.get("Traits/Name") or rdoc.get("Name") or rdoc.path.stem).strip()
            loc_r = [(rdoc.path, tag_line(rdoc, "ShipType") or 1)]
            if key in styles:
                continue
            if key.lower() in low:
                add("WARN", "Race ship type: capitals differ from the hulls' Style", rname,
                    "ShipType is '%s' but the hulls use Style=%s (%d hull(s)). The game compares them exactly, so this race may not get its own ships." % (key, low[key.lower()], len(styles[low[key.lower()]])),
                    "Make the race's ShipType and the hulls' Style=... lines identical (capitals count).", None, loc_r)
            else:
                add("INFO", "Race has no hulls of its own", rname,
                    "No hull file has Style=%s (the race's ShipType), so this race has no ship set of its own." % key,
                    "Give hulls Style=%s (the New race wizard's 'Ship set and hulls' page does this), or pick the ship type of a race whose hulls you want." % key, None, loc_r)
    except Exception as e:
        add("INFO", "Race ship sets", "-", "could not be checked: %s" % e)

    for tm, where, txt in ERRLOG[-30:]:
        add("WARN", "Editor internal error", where or "(editor)", "%s  -  %s" % (tm, txt.splitlines()[-1][:200] if txt else ""),
            "The editor itself hit this while you were working. Press 'Copy report' and send it to me - it includes the full trace.")
    # ---- the game's own log
    try:
        log_issues(proj, add)
    except Exception as e:
        add("INFO", "Game log", "blackbox.log", "could not be analysed: %s" % e, "Press 'Game log…' and pick the file again.")
    out.sort(key=lambda x: (SEV_RANK[x.sev], x.cat, x.item))
    return out


def clip_text(s, n=50):
    s = " ".join((s or "").split())
    return s if len(s) <= n else s[:n - 1] + "…"


# ===== GUI =====
import tkinter as tk
import tkinter.font as tkfont
from tkinter import filedialog, messagebox, ttk
from tkinter.scrolledtext import ScrolledText

try:                                        # optional: smooth icon scaling (pip install pillow)
    from PIL import Image, ImageTk
except Exception:
    Image = ImageTk = None

