_GAME_TAGS = [None]


def game_tags():
    """{'files': {mod folder: class}, 'classes': {class: {tag: {t: type, of: inner type, d: default, h: comment}}}, 'enums': {name: [values]}}"""
    if _GAME_TAGS[0] is None:
        try:
            _GAME_TAGS[0] = json.loads(zlib.decompress(base64.b64decode("".join(GAME_TAGS_BLOB))).decode("utf-8"))
        except Exception:
            log_exc("game tags")
            _GAME_TAGS[0] = {"files": {}, "classes": {}, "enums": {}}
    return _GAME_TAGS[0]


_GAME_INFO = {}


def game_tag_info(tag):
    """(default value, comment from the game's code) for a tag of a weapon / module / tech / building / troop / race file, or None."""
    if tag in _GAME_INFO:
        return _GAME_INFO[tag]
    g = game_tags()
    res = None
    for folder in ("Weapons", "ShipModules", "Technology", "Buildings", "Troops", "Races"):
        spec = g["classes"].get(g["files"].get(folder, ""), {}).get(tag)
        if spec:
            res = (spec.get("d"), spec.get("h", ""))
            if res[0] or res[1]:
                break
    _GAME_INFO[tag] = res
    return res


def game_tag_resolve(g, cname, tag):
    """Is <tag> (a 'A/B' path for the nested ones) a tag the game reads for this class? -> (known, spec, valid tags at the level where it failed)."""
    cur, spec = cname, None
    segs = [re.sub(r"\[\d+\]$", "", x) for x in tag.split("/")]
    for i, sg in enumerate(segs):
        cl = g["classes"].get(cur)
        if cl is None:                                   # a class the table does not cover: cannot judge
            return True, spec, {}
        if sg not in cl:
            return False, None, cl
        spec = cl[sg]
        if i < len(segs) - 1:
            if spec["t"] == "obj" and spec.get("of"):    # lists (items named differently from their class) are not followed
                cur = spec["of"]
            else:
                return True, spec, {}
    return True, spec, {}


def game_tag_suggest(tag, valid):
    """The tag the game does read that this one was most likely meant to be (same letters in another case, or one slip), or None."""
    last = tag.split("/")[-1]
    low = {k.lower(): k for k in valid}
    if last.lower() in low:
        return low[last.lower()]
    near = difflib.get_close_matches(last, list(valid), n=1, cutoff=0.88)
    return near[0] if near else None


def game_value_problem(spec, text):
    """Why the game cannot read this value (it would fail to load the file), or '' if it is fine."""
    v = (text or "").strip()
    k = spec.get("t")
    if k == "float" and not re.match(r"^[-+]?(\d+\.?\d*|\.\d+)([eE][-+]?\d+)?$|^(NaN|-?INF)$", v):
        return "a number is expected"
    if k == "int" and not re.match(r"^[-+]?\d+$", v):
        return "a whole number is expected"
    if k == "bool" and v not in ("true", "false", "1", "0"):
        return "true or false (lower case) is expected"
    return ""



def help_for(tag):
    if tag in FIELD_HELP:
        return FIELD_HELP[tag]
    if tag.endswith("TexturePath"):
        return "Picture path, relative to the Textures folder, without extension."
    if tag.startswith("Tag_"):
        return "Weapon tag (true / false) the game uses to classify this weapon."
    if tag.startswith("Excludes"):
        return "If true, this weapon cannot target that ship class."
    if tag.endswith("Module"):
        return "If true, the module can be fitted to this ship class."
    return ""


