GITHUB_REPO = "TeamStarDrive/StarDrive"
_SRC_SKIP = ("UnitTests", "SDAnalyzers", "obj", "bin")


def tag_updater():
    """The tools/update_game_tags.py script, embedded, as a module (build(folder) makes the tag table from a source folder)."""
    import types
    mod = types.ModuleType("update_game_tags")
    exec(compile(zlib.decompress(base64.b64decode("".join(TAG_UPDATER_BLOB))).decode("utf-8"), "update_game_tags", "exec"), mod.__dict__)
    return mod


def read_versions(root, log=None):
    """{'mod': mod version from its Globals.yaml, 'branch': game branch the mod supports, 'game': game version from blackbox.log}."""
    out = {"mod": "", "branch": "", "game": ""}
    try:
        t = (Path(root) / "Globals.yaml").read_text(encoding="utf-8-sig", errors="replace")
        m = re.search(r"^\s+Version:\s*[\"']?([^\"'\s#]+)", t, re.M)
        out["mod"] = m.group(1) if m else ""
        m = re.search(r"SupportedBlackBoxVersions:\s*[\"']?([^\"'#\n]+)", t)
        if m:
            names = [x.strip() for x in m.group(1).split(",") if x.strip()]
            out["branch"] = next((x for x in reversed(names) if x != "main"), names[0] if names else "")
    except OSError:
        pass
    try:
        v = (getattr(log, "version", "") or "").strip()
        out["game"] = v
        if not out["branch"] and v.split():
            out["branch"] = v.split()[-1]
    except Exception:
        pass
    return out


def fetch_game_source(branch, dest, progress=None, fetch=None, workers=12):
    """Download the game's C# files (only those that changed since last time) from GitHub into dest. fetch(url) -> bytes is replaceable for tests.
    Returns the number of files downloaded."""
    import urllib.request
    from concurrent.futures import ThreadPoolExecutor
    if fetch is None:
        def fetch(url):
            req = urllib.request.Request(url, headers={"User-Agent": "StarDriveBalanceEditor"})
            with urllib.request.urlopen(req, timeout=60) as r:
                return r.read()
    dest = Path(dest)
    dest.mkdir(parents=True, exist_ok=True)
    idx_file = dest / "index.json"
    try:
        have = json.loads(idx_file.read_text(encoding="utf-8"))
    except Exception:
        have = {}
    tree = json.loads(fetch("https://api.github.com/repos/%s/git/trees/%s?recursive=1" % (GITHUB_REPO, branch)).decode("utf-8"))
    files = [(e["path"], e["sha"]) for e in tree.get("tree", []) if e.get("type") == "blob" and e["path"].endswith(".cs")
             and not any(x in e["path"].split("/") for x in _SRC_SKIP)]
    if not files:
        raise ValueError("GitHub returned no source files for '%s'." % branch)
    todo = [(p, sh) for p, sh in files if have.get(p) != sh or not (dest / p).exists()]
    n = [0]

    def get(item):
        p, sh = item
        data = fetch("https://raw.githubusercontent.com/%s/%s/%s" % (GITHUB_REPO, branch, p.replace(" ", "%20")))
        f = dest / p
        f.parent.mkdir(parents=True, exist_ok=True)
        f.write_bytes(data)
        n[0] += 1
        if progress and n[0] % 50 == 0:
            progress("downloading the game's source: %d of %d files" % (n[0], len(todo)))
        return p, sh
    with ThreadPoolExecutor(workers) as ex:
        for p, sh in ex.map(get, todo):
            have[p] = sh
    keep = {p for p, _s in files}
    for p in list(have):
        if p not in keep:
            have.pop(p)
            try:
                (dest / p).unlink()
            except OSError:
                pass
    idx_file.write_text(json.dumps(have), encoding="utf-8")
    return len(todo)


def game_tags_diff(old, new):
    """Readable lines: tags added / removed / with a changed default between two tag tables, per file type."""
    out = []
    inv = {c: f for f, c in new.get("files", {}).items()}
    for cname in sorted(set(old.get("classes", {})) | set(new.get("classes", {}))):
        a, b = old.get("classes", {}).get(cname, {}), new.get("classes", {}).get(cname, {})
        label = inv.get(cname, cname)
        add = sorted(set(b) - set(a))
        rem = sorted(set(a) - set(b))
        chg = sorted(t for t in set(a) & set(b) if a[t].get("d") != b[t].get("d") or a[t].get("t") != b[t].get("t"))
        if add:
            out.append("%s: NEW  %s" % (label, ", ".join(add)))
        if rem:
            out.append("%s: REMOVED  %s" % (label, ", ".join(rem)))
        if chg:
            out.append("%s: CHANGED default/type  %s" % (label, ", ".join("%s (%s -> %s)" % (t, a[t].get("d"), b[t].get("d")) for t in chg[:12])))
    return out


def use_game_tags(data):
    _GAME_TAGS[0] = data
    _GAME_INFO.clear()



def help_game(tag):
    """The game's own default and code comment for a tag, as text ('' if the game's source has neither)."""
    try:
        info = game_tag_info(tag)
    except Exception:
        return ""
    if not info:
        return ""
    out = []
    if info[0]:
        out.append("The game uses %s when the tag is missing." % info[0])
    if info[1]:
        out.append("Game code: " + info[1])
    return " ".join(out)


def field_tip(obj, tag):
    parts = []
    h = help_for(tag)
    if h:
        parts.append(h)
    g = help_game(tag)
    if g:
        parts.append(g)
    if obj is not None:
        cur, orig, base = obj.get(tag), obj.orig.get(tag), obj.base.get(tag)
        if orig is not None and orig != cur:
            parts.append("on disk: " + short(orig, 70))
        if base is not None and base != cur:
            parts.append("default: " + short(base, 70))
    parts.append("Right-click: copy / paste / revert / set to default")
    return "\n".join(parts)


class ToolTip:
    """Small hover hint. text is a string, or a function returning one (called just before it shows)."""

    def __init__(self, widget, text, delay=550):
        self.widget, self.text, self.delay = widget, text, delay
        self.job = self.win = None
        widget.bind("<Enter>", self.arm, add="+")
        widget.bind("<Leave>", self.hide, add="+")
        widget.bind("<ButtonPress>", self.hide, add="+")
        widget.bind("<Destroy>", self.hide, add="+")
        widget.bind("<Unmap>", self.hide, add="+")

    def _under_pointer(self):
        """True while the pointer is still over the widget (or something inside it); a hint never outlives that."""
        try:
            w = self.widget
            o = w.winfo_containing(w.winfo_pointerx(), w.winfo_pointery())
            while o is not None:
                if o is w:
                    return True
                o = o.master
        except Exception:
            return False
        return False

    def _watch(self):
        self.watch = None
        if self.win is None:
            return
        if not self._under_pointer():
            self.close()
            return
        try:
            self.watch = self.widget.after(250, self._watch)
        except tk.TclError:
            self.close()

    def arm(self, _e=None):
        self.hide()
        try:
            self.job = self.widget.after(self.delay, self.show)
        except tk.TclError:
            pass

    def show(self):
        self.job = None
        if getattr(self, "dead", False):
            return
        try:
            if not self._under_pointer():
                return
            text = self.text() if callable(self.text) else self.text
            if text:
                self.pop(text, self.widget.winfo_pointerx() + 14, self.widget.winfo_pointery() + 20)
                self.watch = self.widget.after(250, self._watch)
        except tk.TclError:
            pass

    def pop(self, text, x, y):
        self.close()
        win = self.win = tk.Toplevel(self.widget)
        win.withdraw()
        win.overrideredirect(True)
        win.configure(bg=ORANGE)
        try:
            win.attributes("-topmost", True)
        except Exception:
            pass
        tk.Label(win, text=text, bg=PANEL2, fg=FG, justify="left", wraplength=380, padx=8, pady=5,
                 font=("Segoe UI", 9)).pack(padx=1, pady=1)
        win.update_idletasks()
        x = max(0, min(x, win.winfo_screenwidth() - win.winfo_reqwidth() - 6))
        y = min(y, win.winfo_screenheight() - win.winfo_reqheight() - 40)
        win.geometry("+%d+%d" % (x, y))
        win.deiconify()

    def close(self):
        w, self.watch = getattr(self, "watch", None), None
        if w is not None:
            try:
                self.widget.after_cancel(w)
            except Exception:
                pass
        if self.win is not None:
            try:
                self.win.destroy()
            except Exception:
                pass
            self.win = None

    def hide(self, _e=None):
        if self.job is not None:
            try:
                self.widget.after_cancel(self.job)
            except Exception:
                pass
            self.job = None
        self.close()


def tip(widget, text, delay=550):
    old = getattr(widget, "_tip", None)
    if old is not None:
        old.dead = True                       # a newer hint replaces an older one (the automatic hints give way to written ones)
    widget._tip = ToolTip(widget, text, delay)
    return widget


