def _tip_key(text):
    t = re.sub(r"^[^\w]+", "", str(text or "")).rstrip(" .…:").strip().lower()
    return re.sub(r"\s+", " ", t)


def _tip_for_button(text):
    k = _tip_key(text)
    if k in TIP_TEXTS:
        return TIP_TEXTS[k]
    base = re.sub(r"\s*\(.*?\)\s*$", "", k)
    if base in TIP_TEXTS:
        return TIP_TEXTS[base]
    if not k:
        return ""
    if k.startswith("new "):
        return "Create a new %s." % k[4:]
    if k.startswith("add "):
        return "Add %s." % k[4:]
    if k.startswith(("open", "show", "edit", "copy", "import", "save", "remove", "pick", "choose", "make", "write", "generate", "look", "play", "unlock")):
        return k[0].upper() + k[1:] + "."
    return ""


def _tip_label_before(w):
    """The text of the label just before an entry / combobox in the same row (or the label in the cell to its left)."""
    try:
        par = w.master
        mgr = w.winfo_manager()
        cand = None
        if mgr == "grid":
            gi = w.grid_info()
            col, row = int(gi.get("column", 0)), int(gi.get("row", 0))
            for o in par.grid_slaves(row=row):
                if int(o.grid_info().get("column", 0)) < col and isinstance(o, (tk.Label, ttk.Label)):
                    if cand is None or int(o.grid_info().get("column", 0)) > int(cand.grid_info().get("column", 0)):
                        cand = o
        else:
            kids = par.winfo_children()
            i = kids.index(w)
            for o in reversed(kids[:i]):
                if isinstance(o, (tk.Label, ttk.Label)):
                    cand = o
                    break
                if isinstance(o, (ttk.Entry, ttk.Combobox, ttk.Button, ttk.Checkbutton)):
                    break
        return re.sub(r"[:\s]+$", "", str(cand.cget("text"))) if cand is not None else ""
    except Exception:
        return ""


class _NbTip(ToolTip):
    def __init__(self, nb):
        super().__init__(nb, self.text_at)
        self.at = ""
        nb.bind("<Motion>", self.moved, add="+")

    def moved(self, e):
        try:
            self.at = self.widget.tab("@%d,%d" % (e.x, e.y), "text")
        except Exception:
            self.at = ""

    def _under_pointer(self):
        try:
            w = self.widget
            if w.winfo_containing(w.winfo_pointerx(), w.winfo_pointery()) is not w:
                return False                                   # over a page's contents, not the tab strip
            return bool(w.tab("@%d,%d" % (w.winfo_pointerx() - w.winfo_rootx(), w.winfo_pointery() - w.winfo_rooty()), "text"))
        except Exception:
            return False

    def text_at(self):
        k = _tip_key(self.at)
        k = re.sub(r"\s*\(\d+\)$", "", k)
        for name, tx in TAB_TIPS.items():
            if k == name or k.startswith(name):
                return tx
        return ("Switch to: %s." % k) if k else ""


def auto_tips(root):
    """Gives a hover hint to every button, tick box, entry, list box and tab under root that has none yet. Hand-written hints are never replaced."""
    n = 0
    stack = [root]
    while stack:
        w = stack.pop()
        try:
            kids = w.winfo_children()
        except Exception:
            continue
        stack.extend(kids)
        if getattr(w, "_tip", None) is not None or getattr(w, "_auto_tip", False):
            continue
        try:
            if isinstance(w, (ttk.Button, tk.Button)):
                tx = _tip_for_button(w.cget("text"))
                if tx:
                    tip(w, tx)
            elif isinstance(w, (ttk.Checkbutton, ttk.Radiobutton, tk.Checkbutton, tk.Radiobutton)):
                t = re.sub(r"\s+", " ", str(w.cget("text"))).strip()
                if t:
                    tip(w, "Tick / untick: %s." % t if isinstance(w, (ttk.Checkbutton, tk.Checkbutton)) else "Choose: %s." % t)
            elif isinstance(w, (ttk.Combobox, ttk.Entry, tk.Entry, ttk.Spinbox)):
                lab = _tip_label_before(w)
                if lab:
                    h = help_for(lab.replace(" ", ""))
                    tip(w, (h + "\n\n" if h else "") + "%s: type a value%s." % (lab, " or pick one from the list" if isinstance(w, ttk.Combobox) else ""))
            elif isinstance(w, ttk.Notebook):
                w._tip = _NbTip(w)
            elif isinstance(w, ttk.Treeview) and not getattr(w, "_tip", None):
                tip(w, "Click a row to select it. Right-click for more actions where there are any.")
        except Exception:
            pass
        w._auto_tip = True
        n += 1
    return n


def install_auto_tips(root):
    """Scans a window shortly after anything appears in it (a tab, a wizard page, a dialog): cheap, and once per widget."""
    state = {"job": None, "tops": set()}

    def run():
        state["job"] = None
        tops, state["tops"] = list(state["tops"]), set()
        for t in tops:
            try:
                if t.winfo_exists():
                    auto_tips(t)
            except Exception:
                pass

    def on_map(e):
        try:
            state["tops"].add(e.widget.winfo_toplevel())
            if state["job"] is None:
                state["job"] = root.after(250, run)
        except Exception:
            pass
    root.bind_all("<Map>", on_map, add="+")
    run_first = root.after(800, lambda: (state["tops"].add(root), run()))
    return run_first



class DesignPreview:
    """A hover card for a ship design: the hull's picture, its slot counts and a drawing of the hull layout with the design's modules marked."""
    CELL = {"E": "#d08a3a", "C": "#d05050", "IO": "#6f9c9c", "I": "#5a9a5a", "O": "#4a78b0"}

    def __init__(self, owner):
        self.owner, self.win = owner, None

    def close(self, *_a):
        if self.win is not None:
            try:
                self.win.destroy()
            except Exception:
                pass
            self.win = None

    def cell_color(self, v):
        if "E" in v:
            return self.CELL["E"]
        if "C" in v:
            return self.CELL["C"]
        if "I" in v and "O" in v:
            return self.CELL["IO"]
        return self.CELL["I"] if "I" in v else self.CELL["O"]

    def show(self, widget, name, x, y, hint=""):
        self.close()
        o = self.owner
        d = o.design_by_name(name)
        win = self.win = tk.Toplevel(widget)
        win.withdraw()
        win.overrideredirect(True)
        win.configure(bg=ORANGE)
        try:
            win.attributes("-topmost", True)
        except Exception:
            pass
        box = tk.Frame(win, bg=PANEL2)
        box.pack(padx=1, pady=1)
        if d is None:
            tk.Label(box, text=(hint + "\n\n" if hint else "") + o.design_text(name), bg=PANEL2, fg=FG, justify="left", wraplength=380, padx=8, pady=5,
                     font=("Segoe UI", 9)).pack()
        else:
            P = o.proj
            hull = P.hull_by_name(d.hull) if d.hull else None
            top = tk.Frame(box, bg=PANEL2)
            top.pack(fill="x", padx=8, pady=(6, 2))
            try:
                pic = P.find_file(hull.get("IconPath").strip()) if hull is not None and hull.get("IconPath").strip() else None
                if pic:
                    self._img = o.app.icon(pic, 72, d.hull)
                    tk.Label(top, image=self._img, bg=PANEL2).pack(side="left", padx=(0, 8))
            except Exception:
                pass
            lines = [d.name, "Hull: %s" % (d.hull or "-"), "Role: %s     Style: %s" % (d.role or "-", d.style or "-")]
            if hull is not None:
                k = hull.kinds()
                lines.append("Slots: %d   (inner %d, outer %d, engine %d, command %d)" % (k["all"], k["I"], k["O"], k["E"], k["C"]))
            else:
                lines.append("Hull file not found")
            lines.append("Modules placed: %d      %s" % (len(d.slots), "base game" if d.is_base else "mod"))
            tk.Label(top, text="\n".join(lines), bg=PANEL2, fg=FG, justify="left", anchor="w", font=("Segoe UI", 9)).pack(side="left")
            if hint:
                tk.Label(box, text=hint, bg=PANEL2, fg=DIM, justify="left", wraplength=360, padx=8, font=("Segoe UI", 8)).pack(fill="x")
            if hull is not None and hull.slots:
                rows, cols = len(hull.slots), max(1, hull.cols())
                sc = max(2, min(6, int(260 // cols), int(240 // rows)))
                cv = tk.Canvas(box, width=cols * sc + 2, height=rows * sc + 2, bg=PANEL2, highlightthickness=0)
                cv.pack(padx=8, pady=6)
                for r, row in enumerate(hull.slots):
                    for c, v in enumerate(row):
                        if v:
                            cv.create_rectangle(c * sc + 1, r * sc + 1, (c + 1) * sc + 1, (r + 1) * sc + 1, fill=self.cell_color(v), outline="")
                for mx, my, _i, _h, (sx, sy) in d.slots:
                    cv.create_rectangle(mx * sc + 1, my * sc + 1, (mx + sx) * sc + 1, (my + sy) * sc + 1, fill="#f2e6b8", outline="")
                tk.Label(box, text="blue = outer   green = inner   teal = either   orange = engine   red = command   pale = a module is placed",
                         bg=PANEL2, fg=DIM, font=("Segoe UI", 7), padx=8).pack(anchor="w", pady=(0, 6))
        win.update_idletasks()
        x = max(0, min(x, win.winfo_screenwidth() - win.winfo_reqwidth() - 6))
        y = max(0, min(y, win.winfo_screenheight() - win.winfo_reqheight() - 40))
        win.geometry("+%d+%d" % (x, y))
        win.deiconify()


def attach_design_preview(cb, owner, var, hint=""):
    """Hover cards for a ship-name combobox: on the box itself (the design picked) and on every name of its drop-down list."""
    pv = DesignPreview(owner)
    st = {"job": None, "last": None, "hooked": set()}
    cb._design_preview = pv

    def cancel():
        if st["job"] is not None:
            try:
                cb.after_cancel(st["job"])
            except Exception:
                pass
            st["job"] = None

    def arm(_e=None):
        cancel()
        try:
            st["job"] = cb.after(450, lambda: pv.show(cb, var.get(), cb.winfo_pointerx() + 14, cb.winfo_pointery() + 20, hint))
        except tk.TclError:
            pass

    def hide(_e=None):
        cancel()
        pv.close()
        st["last"] = None

    def motion(lst, pop, y):
        try:
            i = int(cb.tk.call(lst, "nearest", int(y)))
            val = str(cb.tk.call(lst, "get", i))
            if val != st["last"]:
                st["last"] = val
                rx = int(cb.tk.call("winfo", "rootx", pop)) + int(cb.tk.call("winfo", "width", pop)) + 8
                pv.show(cb, val, rx, max(0, cb.winfo_pointery() - 60))
        except Exception:
            pass

    def hook(_e=None):
        def go():
            try:
                pop = str(cb.tk.call("ttk::combobox::PopdownWindow", str(cb)))
                lst = pop + ".f.l"
                if lst in st["hooked"]:
                    return
                st["hooked"].add(lst)
                cb.tk.call("bind", lst, "<Motion>", "+" + cb.register(lambda y, _l=lst, _p=pop: motion(_l, _p, y)) + " %y")
                cb.tk.call("bind", lst, "<Leave>", "+" + cb.register(hide))
                cb.tk.call("bind", pop, "<Unmap>", "+" + cb.register(hide))
            except Exception:
                pass
        cb.after(80, go)

    cb.bind("<Enter>", arm, add="+")
    cb.bind("<Leave>", hide, add="+")
    cb.bind("<ButtonPress>", lambda e: (cancel(), pv.close()), add="+")
    cb.bind("<ButtonRelease-1>", hook, add="+")
    cb.bind("<Down>", hook, add="+")
    cb.bind("<<ComboboxSelected>>", hide, add="+")
    cb.bind("<Destroy>", lambda _e: pv.close(), add="+")
    return cb


def popup(menu, ev):
    try:
        menu.tk_popup(ev.x_root, ev.y_root)
    finally:
        menu.grab_release()


def select_all(w):
    try:
        w.select_range(0, "end")
        w.icursor("end")
    except Exception:
        try:
            w.tag_add("sel", "1.0", "end-1c")
        except Exception:
            pass


AI_APP = [None]        # the App, so the right-click menus can open the AI helper


def edit_menu(widget, ev, extra=()):
    """Right-click menu for an Entry / Text: Cut, Copy, Paste, Select all, then extra (label, command, enabled) items."""
    try:
        widget.focus_set()
    except Exception:
        pass
    try:
        ro = bool(widget.instate(["readonly"]) or widget.instate(["disabled"]))
    except Exception:
        try:
            ro = str(widget.cget("state")) in ("disabled", "readonly")
        except Exception:
            ro = False
    m = tk.Menu(widget, tearoff=0, **MENU_OPTS)
    s = "disabled" if ro else "normal"
    m.add_command(label="Cut", accelerator="Ctrl+X", state=s, command=lambda: widget.event_generate("<<Cut>>"))
    m.add_command(label="Copy", accelerator="Ctrl+C", command=lambda: widget.event_generate("<<Copy>>"))
    m.add_command(label="Paste", accelerator="Ctrl+V", state=s, command=lambda: widget.event_generate("<<Paste>>"))
    m.add_command(label="Select all", accelerator="Ctrl+A", command=lambda: select_all(widget))
    if extra:
        m.add_separator()
        for label, cmd, ok in extra:
            m.add_command(label=label, command=cmd, state="normal" if ok else "disabled")
    if AI_APP[0] is not None and not any(str(x[0]).startswith("Ask an AI") for x in extra):
        m.add_separator()
        m.add_command(label="Ask an AI about this text…", command=lambda: AI_APP[0].ai_text_widget(widget))
    popup(m, ev)


def apply_theme(root):
    try:
        fam = "Segoe UI" if "Segoe UI" in tkfont.families(root) else None
        for name in ("TkDefaultFont", "TkTextFont", "TkMenuFont", "TkHeadingFont"):
            f = tkfont.nametofont(name)
            f.configure(size=10, **({"family": fam} if fam else {}))
    except Exception:
        pass
    root.configure(bg=BG)
    for opt, val in (("background", PANEL2), ("foreground", FG), ("selectBackground", ORANGE),
                     ("selectForeground", "#000000")):
        root.option_add("*TCombobox*Listbox." + opt, val)
    st = ttk.Style(root)
    st.theme_use("clam")
    st.configure(".", background=BG, foreground=FG, fieldbackground=PANEL2, bordercolor=EDGE,
                 lightcolor=EDGE, darkcolor=EDGE, troughcolor=PANEL)
    st.configure("TFrame", background=BG)
    st.configure("TLabel", background=BG, foreground=FG)
    st.configure("Status.TLabel", background=PANEL, foreground=PEACH, padding=(10, 6))
    st.configure("TButton", background=PURPLE, foreground="#14101a", padding=(14, 6), borderwidth=0,
                 focusthickness=0, relief="flat")
    st.map("TButton", background=[("pressed", "#b080b0"), ("active", "#e0b8e0")])
    st.configure("Save.TButton", background=ORANGE)
    st.map("Save.TButton", background=[("pressed", "#e0842a"), ("active", "#ffb866")])
    st.configure("TEntry", fieldbackground=PANEL2, foreground=FG, insertcolor=ORANGE, padding=4)
    st.map("TEntry", bordercolor=[("focus", ORANGE)], fieldbackground=[("readonly", PANEL)],
           foreground=[("readonly", DIM)])
    st.configure("TCombobox", fieldbackground=PANEL2, background=PURPLE, foreground=FG,
                 arrowcolor="#14101a", padding=4)
    st.map("TCombobox", fieldbackground=[("readonly", PANEL2)], foreground=[("readonly", FG)],
           selectbackground=[("readonly", PANEL2)], selectforeground=[("readonly", FG)])
    for w in ("TCheckbutton", "TRadiobutton"):
        st.configure(w, background=BG, foreground=FG, indicatorcolor=PANEL2)
        st.map(w, indicatorcolor=[("selected", ORANGE)], background=[("active", BG)])
    st.configure("TScrollbar", background="#3b3656", troughcolor=PANEL, bordercolor=PANEL,
                 arrowcolor=FG, gripcount=0)
    st.map("TScrollbar", background=[("active", "#5a5280")])
    st.configure("TNotebook", background=BG, borderwidth=0, tabmargins=(0, 4, 0, 0))
    st.configure("TNotebook.Tab", background="#2a2540", foreground=FG, padding=(16, 7), borderwidth=0)
    st.map("TNotebook.Tab", background=[("selected", ORANGE), ("active", "#3a3458")],
           foreground=[("selected", "#000000")])
    st.configure("Treeview", background=PANEL, fieldbackground=PANEL, foreground=FG, borderwidth=0)
    st.map("Treeview", background=[("selected", SEL)], foreground=[("selected", "#ffffff")])
    st.configure("Treeview.Heading", background="#2a2540", foreground=PEACH, relief="flat", padding=(6, 6))
    st.map("Treeview.Heading", background=[("active", "#3a3458")])


def dark_titlebar(win):
    """Dark title bar on Windows 10/11; silently does nothing elsewhere."""
    try:
        import ctypes
        win.update_idletasks()
        hwnd = ctypes.windll.user32.GetParent(win.winfo_id())
        on = ctypes.c_int(1)
        for attr in (20, 19):
            if ctypes.windll.dwmapi.DwmSetWindowAttribute(hwnd, attr, ctypes.byref(on), ctypes.sizeof(on)) == 0:
                break
    except Exception:
        pass


def short(v, n=60):
    v = " ".join((v or "").split())
    return v if len(v) <= n else v[:n - 1] + "…"


class Grid(ttk.Frame):
    def __init__(self, master, app, cols, rows, facet_tag=None, hide_in_preset=()):
        super().__init__(master)
        self.app, self.cols, self.rows = app, cols, rows
        self.visible = list(range(len(cols)))
        self.hide_in_preset = set(hide_in_preset)
        self.sort_col, self.sort_rev = None, False
        self.shown = []
        self.wrap_idx = {i for i, c in enumerate(cols) if c.tag in ("Description", "Desc", "ENG")}
        self.wrap_on = bool(self.wrap_idx)
        self.max_lines = DESC_MAX_LINES
        self.font = tkfont.nametofont("TkDefaultFont")
        self.charw = max(5.0, self.font.measure("abcdefghijklmnopqrstuvwxyz") / 26.0)
        self.style_name = "Wrap%d.Treeview" % id(self)
        self._wrap_widths = ()
        self.facet_idx = next((i for i, c in enumerate(cols) if c.src in ("M", "X") and c.tag == facet_tag), None) \
            if facet_tag else None

        bar = ttk.Frame(self)
        bar.pack(fill="x", padx=4, pady=3)
        ttk.Label(bar, text="Filter:").pack(side="left")
        self.q = tk.StringVar()
        self.q.trace_add("write", lambda *_: self.populate())
        fe = ttk.Entry(bar, textvariable=self.q, width=28)
        fe.pack(side="left", padx=4)
        tip(fe, "Type to filter: rows are kept if any visible column contains the text.")
        self.facet_var = tk.StringVar(value="(all)")
        if self.facet_idx is not None:
            ttk.Label(bar, text=cols[self.facet_idx].header + ":").pack(side="left", padx=(10, 2))
            self.facet_cb = ttk.Combobox(bar, textvariable=self.facet_var, state="readonly", width=20)
            self.facet_cb.pack(side="left")
            tip(self.facet_cb, "Show only one kind of %s." % ("building" if cols[self.facet_idx].tag == "Category" else "module"))
            self.facet_cb.bind("<<ComboboxSelected>>", lambda _: self.populate())
        self.count = ttk.Label(bar)
        self.count.pack(side="right")

        wrap = ttk.Frame(self)
        wrap.pack(fill="both", expand=True)
        ids = ["c%d" % i for i in range(len(cols))]
        self.tree = ttk.Treeview(wrap, columns=ids, show="headings", selectmode="extended", style=self.style_name)
        vsb = ttk.Scrollbar(wrap, orient="vertical", command=self.tree.yview)
        hsb = ttk.Scrollbar(wrap, orient="horizontal", command=self.tree.xview)
        self.tree.configure(yscrollcommand=vsb.set, xscrollcommand=hsb.set)
        self.tree.grid(row=0, column=0, sticky="nsew")
        vsb.grid(row=0, column=1, sticky="ns")
        hsb.grid(row=1, column=0, sticky="ew")
        wrap.rowconfigure(0, weight=1)
        wrap.columnconfigure(0, weight=1)
        for i, c in enumerate(cols):
            self.tree.heading(ids[i], text=c.header, command=lambda i=i: self.sort_by(i))
            self.tree.column(ids[i], width=c.width, minwidth=40, stretch=False)
        self.tree.tag_configure("dirty", background=DIRTY_BG, foreground=DIRTY_FG)
        self.apply_rowheight()
        self.cur_ci, self._hk = None, None
        self.tree.bind("<Double-1>", self.on_double)
        self.tree.bind("<ButtonRelease-1>", self.on_release, add="+")
        self.tree.bind("<ButtonPress-1>", self.note_col, add="+")
        self.tree.bind("<Control-c>", lambda _e: self.copy_cells() or "break")
        self.tree.bind("<Control-v>", lambda _e: self.paste_cells() or "break")
        self.tree.bind("<Control-a>", lambda _e: self.tree.selection_set(self.tree.get_children()) or "break")
        for b in ("<Button-3>", "<Button-2>"):
            self.tree.bind(b, self.on_menu)
        self.menu = tk.Menu(self, tearoff=0, **MENU_OPTS)
        self.menu_hit = None
        self.cell_tip = ToolTip(self.tree, self.hover_text, delay=500)
        self.tree.bind("<Motion>", self._hover, add="+")
        self._stale = True
        self.count["text"] = "(loads when you open this table)"
        self.bind("<Map>", lambda e: self.ensure() if e.widget is self else None, add="+")
        self.populate()

    # ---- display
    def ensure(self):
        """Fill the table now if it was waiting for its tab to be opened."""
        if self._stale:
            self._populate()

    def populate(self):
        """Refill the table - but a table nobody can see waits until its tab is opened (building thousands of rows is what made starting slow)."""
        if not self.winfo_ismapped():
            self._stale = True
            return
        self._populate()

    def _populate(self):
        self._stale = False
        _t = time.perf_counter()
        try:
            self._populate2()
        finally:
            try:
                self.app.proj.log_step("table filled: %d rows in %.2f s" % (len(self.shown), time.perf_counter() - _t))
            except Exception:
                pass

    def _populate2(self):
        try:
            keep = [self.shown[int(i)] for i in self.tree.selection() if int(i) < len(self.shown)]
        except Exception:
            keep = []
        q = self.q.get().lower().strip()
        facet = self.facet_var.get()
        if self.facet_idx is not None:
            vals = sorted({r.get(self.cols[self.facet_idx]) for r in self.rows} - {""})
            self.facet_cb["values"] = ["(all)"] + vals
            if facet not in vals:
                facet = "(all)"
                self.facet_var.set("(all)")
        self.shown = []
        for r in self.rows:
            if self.facet_idx is not None and facet != "(all)" and r.get(self.cols[self.facet_idx]) != facet:
                continue
            if q and not any(q in r.get(self.cols[i]).lower() for i in self.visible):
                continue
            self.shown.append(r)
        if self.sort_col is not None:
            c = self.cols[self.sort_col]
            self.shown.sort(key=lambda r: sort_key(r.get(c)), reverse=self.sort_rev)
        self.tree.delete(*self.tree.get_children())
        self._wrap_widths = self.wrap_widths()
        for n, r in enumerate(self.shown):
            self.tree.insert("", "end", iid=str(n), values=self.cell_values(r),
                             tags=("dirty",) if r.dirty() else ())
        self.tree["displaycolumns"] = ["c%d" % i for i in self.visible]
        self.count["text"] = "%d / %d rows" % (len(self.shown), len(self.rows))
        if keep:                                     # keep the selection across refreshes
            pos = {id(r): n for n, r in enumerate(self.shown)}
            sel = [str(pos[id(r)]) for r in keep if id(r) in pos]
            if sel:
                self.tree.selection_set(sel)

    # ---- multi-line text cells (Treeview rows share one height, so all rows in the table get taller)
    def wrap_widths(self):
        return tuple(int(self.tree.column("c%d" % i, "width")) for i in sorted(self.wrap_idx))

    def apply_rowheight(self):
        lines = self.max_lines if self.wrap_on else 1
        ttk.Style().configure(self.style_name, rowheight=self.font.metrics("linespace") * lines + 6)

    def wrap_text(self, text, i):
        text = " ".join(text.split())
        chars = max(10, int((int(self.tree.column("c%d" % i, "width")) - 14) / self.charw))
        lines = textwrap.wrap(text, chars) or [""]
        if len(lines) > self.max_lines:
            lines = lines[:self.max_lines]
            lines[-1] = lines[-1][:max(1, chars - 1)].rstrip() + "…"
        return "\n".join(lines)

    def cell_values(self, r):
        out = []
        for i, c in enumerate(self.cols):
            v = r.get(c)
            if c.src in ("M", "W") and v.strip().lower() in ("true", "false"):          # true / false tags read as a switch
                out.append(SWITCH_ON if v.strip().lower() == "true" else SWITCH_OFF)
                continue
            out.append(self.wrap_text(v, i) if self.wrap_on and i in self.wrap_idx else " ".join(v.split()))
        return out

    def set_wrap(self, on):
        self.wrap_on = bool(on) and bool(self.wrap_idx)
        self.apply_rowheight()
        self.populate()

    def on_release(self, _ev):
        if self.wrap_on and self.wrap_widths() != self._wrap_widths:      # a column was resized: re-wrap
            self.populate()

    def sort_by(self, i):
        self.sort_rev = (not self.sort_rev) if self.sort_col == i else False
        self.sort_col = i
        for j, c in enumerate(self.cols):
            arrow = (" ▼" if self.sort_rev else " ▲") if j == i else ""
            self.tree.heading("c%d" % j, text=c.header + arrow)
        self.populate()

    def focus_uid(self, uid):
        self.ensure()
        self.facet_var.set("(all)")
        self.q.set(uid)
        self.populate()
        col = next((c for c in self.cols if c.src == "M" and c.tag == "UID"), None)
        for n, r in enumerate(self.shown):
            if col and r.get(col) == uid:
                self.tree.selection_set(str(n))
                self.tree.see(str(n))
                break

    # ---- selection, copy / paste
    def note_col(self, ev):
        if self.tree.identify_region(ev.x, ev.y) == "cell":
            try:
                self.cur_ci = self.visible[int(self.tree.identify_column(ev.x)[1:]) - 1]
            except Exception:
                pass

    def selected_rows(self):
        return [self.shown[int(i)] for i in self.tree.selection() if int(i) < len(self.shown)]

    def _col(self):
        ci = self.cur_ci if self.cur_ci in self.visible else (self.visible[0] if self.visible else None)
        return self.cols[ci] if ci is not None else None

    def copy_cells(self, whole_rows=False):
        rows, col = self.selected_rows(), self._col()
        if not rows or col is None:
            self.app.say("Click a cell first, then copy.")
            return
        if whole_rows:
            text = "\n".join("\t".join(" ".join(r.get(self.cols[i]).split()) for i in self.visible) for r in rows)
        elif len(rows) == 1:
            text = rows[0].get(col)
        else:
            text = "\n".join(" ".join(r.get(col).split()) for r in rows)
        self.clipboard_clear()
        self.clipboard_append(text)
        self.app.say("Copied %d %s." % (len(rows), "row(s)" if whole_rows else "cell(s) from '%s'" % col.header))

    def set_quiet(self, row, col, new):
        if not row.editable(col):
            return False
        old = row.get(col)
        if old.strip().lower() in ("true", "false"):
            new = new.strip().lower()
        elif NUM_RE.match(old.strip()):
            new = new.strip()
            if INT_RE.match(old.strip()) and not INT_RE.match(new):
                return False
        if validate(old, new):
            return False
        row.set(col, new)
        return True

    def paste_cells(self):
        rows, col = self.selected_rows(), self._col()
        if not rows or col is None:
            self.app.say("Click a cell first, then paste.")
            return
        try:
            text = self.clipboard_get()
        except tk.TclError:
            self.app.say("The clipboard is empty.")
            return
        lines = text.replace("\r\n", "\n").rstrip("\n").split("\n")
        if len(rows) > 1 and len(lines) == len(rows):
            vals = lines                                  # one line per selected row (e.g. copied from a spreadsheet)
        else:
            vals = [text.replace("\r\n", "\n").rstrip("\n")] * len(rows)
        ok = sum(1 for r, v in zip(rows, vals) if self.set_quiet(r, col, v))
        self.app.refresh()
        self.app.say("Pasted into %d cell(s) of '%s'%s." % (
            ok, col.header, ("; skipped %d (read-only, or not valid for that field)" % (len(rows) - ok)) if ok < len(rows) else ""))

    # ---- hover hints
    def _hover(self, ev):
        key = (self.tree.identify_region(ev.x, ev.y), self.tree.identify_row(ev.y), self.tree.identify_column(ev.x))
        if key != self._hk:
            self._hk = key
            self.cell_tip.arm()

    def hover_text(self):
        x = self.tree.winfo_pointerx() - self.tree.winfo_rootx()
        y = self.tree.winfo_pointery() - self.tree.winfo_rooty()
        region = self.tree.identify_region(x, y)
        try:
            ci = self.visible[int(self.tree.identify_column(x)[1:]) - 1]
        except Exception:
            return ""
        col = self.cols[ci]
        h = help_for(col.tag)
        if region == "heading":
            return "%s%s\nClick to sort - drag the edge to resize" % (col.header, ("\n" + h) if h else "")
        iid = self.tree.identify_row(y)
        if region != "cell" or not iid or int(iid) >= len(self.shown):
            return ""
        row = self.shown[int(iid)]
        cur, orig, base, editable = row.info(col)
        parts = [col.header + (": " + h if h else "")]
        if cur and (len(cur) > 40 or "\n" in cur or (self.wrap_on and ci in self.wrap_idx)):
            parts.append(cur if len(cur) < 700 else cur[:700] + "...")
        if orig is not None and orig != cur:
            parts.append("on disk: " + short(orig, 80))
        if base is not None and base != cur:
            parts.append("default: " + short(base, 80))
        parts.append(("Double-click to edit" if editable else "Read-only") + "  -  right-click for more")
        return "\n".join(parts)

    # ---- editing
    def _hit(self, ev):
        if self.tree.identify_region(ev.x, ev.y) != "cell":
            return None
        iid, colid = self.tree.identify_row(ev.y), self.tree.identify_column(ev.x)
        if not iid:
            return None
        return iid, colid, self.visible[int(colid[1:]) - 1]

    def on_double(self, ev):
        hit = self._hit(ev)
        if not hit:
            return
        iid, colid, ci = hit
        row, col = self.shown[int(iid)], self.cols[ci]
        if not row.editable(col):
            self.app.say("That cell is read-only (or this row has no such field).")
            return
        old = row.get(col)
        if col.src in ("M", "W") and old.strip().lower() in ("true", "false"):          # a switch: double-click flips it
            self.commit(row, col, "false" if old.strip().lower() == "true" else "true")
            return
        if "\n" in old or len(old) > 60 or col.src == "T" or col.tag in ("Description", "ENG"):
            new = self.app.text_dialog(col.header, old)
            if new is not None and new != old:
                self.commit(row, col, new)
        else:
            self.inline(iid, colid, row, col, old)

    def inline(self, iid, colid, row, col, old):
        x, y, w, h = self.tree.bbox(iid, colid)
        e = ttk.Entry(self.tree)
        e.insert(0, old)
        e.select_range(0, "end")
        e.place(x=x, y=y, width=max(w, 90), height=h)
        e.focus_set()
        done = []

        def finish(ok):
            if done:
                return
            done.append(1)
            val = e.get()
            e.destroy()
            if ok and val != old:
                self.commit(row, col, val)
        e.bind("<Return>", lambda _: finish(True))
        e.bind("<Escape>", lambda _: finish(False))
        e.bind("<FocusOut>", lambda _: finish(True))

    def commit(self, row, col, new):
        old = row.get(col)
        if old.strip().lower() in ("true", "false") or NUM_RE.match(old.strip()):
            new = new.strip().lower() if old.strip().lower() in ("true", "false") else new.strip()
        err = validate(old, new)
        if err:
            messagebox.showwarning("Not applied", err)
            return
        if INT_RE.match(old.strip()) and NUM_RE.match(new) and not INT_RE.match(new):
            if not messagebox.askyesno("Decimal in a whole-number field?",
                                       "'%s' was a whole number and you entered '%s'.\n"
                                       "If the game expects an integer here it may ignore or reject it.\n\nKeep it?" % (old.strip(), new)):
                return
        row.set(col, new)
        self.app.refresh()

    def delete_cells(self):
        rows, col = self.selected_rows(), self._col()
        tg = [t for t in (r.target(col) for r in rows) if t and t[0].can_remove(t[1])] if col is not None else []
        if not tg:
            self.app.say("Nothing to delete there: the tag is not in the file (or cannot be removed).")
            return
        tag = tg[0][1]
        if not messagebox.askyesno("Delete tag", "Remove <%s> from %d file(s)?\n\nThe line is taken out of the xml when you Save. "
                                   "'Revert to last save' or Undo puts it back." % (tag, len(tg)), icon="warning", default="no"):
            return
        for d, tg_ in tg:
            d.remove_tag(tg_)
        self.app.refresh()
        self.app.say("Removed <%s> from %d file(s). Save (Ctrl+S) to write it; Undo brings it back." % (tag, len(tg)))

    def on_menu(self, ev):
        hit = self._hit(ev)
        if not hit:
            return
        iid, _colid, ci = hit
        if iid not in self.tree.selection():
            self.tree.selection_set(iid)
        self.cur_ci = ci
        self.menu_hit = hit
        rows, col = self.selected_rows(), self.cols[ci]
        n = len(rows)
        row = self.shown[int(iid)]
        try:
            self.clipboard_get()
            has_clip = True
        except tk.TclError:
            has_clip = False
        m = self.menu
        m.delete(0, "end")
        m.add_command(label="Copy", accelerator="Ctrl+C", command=self.copy_cells)
        m.add_command(label="Copy row%s as text" % ("s" if n > 1 else ""), command=lambda: self.copy_cells(True))
        m.add_command(label="Paste" + (" into %d rows" % n if n > 1 else ""), accelerator="Ctrl+V",
                      command=self.paste_cells, state="normal" if has_clip and row.editable(col) else "disabled")
        m.add_separator()
        m.add_command(label="Revert this cell  (to value on disk)", command=lambda: self.revert(True),
                      state="normal" if any(r.differs(col) for r in rows) else "disabled")
        m.add_command(label="Revert row%s" % ("s" if n > 1 else ""), command=lambda: self.revert(False),
                      state="normal" if any(r.dirty() for r in rows) else "disabled")
        m.add_separator()
        m.add_command(label="Set this cell to default", command=lambda: self.to_default(True),
                      state="normal" if any(r.differs_default(col) for r in rows) else "disabled")
        m.add_command(label="Set row%s to default" % ("s" if n > 1 else ""), command=lambda: self.to_default(False))
        m.add_separator()
        m.add_command(label="Delete this tag from the file%s…" % ("s" if n > 1 else ""), foreground="#e06060", command=self.delete_cells,
                      state="normal" if any((lambda t: bool(t) and t[0].can_remove(t[1]))(r.target(col)) for r in rows) else "disabled")
        tg = row.target(col)
        m.add_separator()
        if tg:
            m.add_command(label="Ask an AI about this field…", command=lambda: self.app.ai_field(tg[0], tg[1], None, None, self.tree))
        cd = row.compare_doc()
        if cd is not None:
            m.add_command(label="Make a picture with an AI…", command=lambda: self.app.ai_picture(self.app.ai_kind(cd), cd))
        if cd is not None:
            cuid = doc_key(cd)
            m.add_separator()
            m.add_command(label="Copy this %s as a new one…" % ("building" if self.app.proj.is_building(cd) else "module"),
                          command=lambda: self.app.copy_item(cd))
            m.add_command(label=("Remove from compare" if cuid in self.app.compare_uids else "★ Tag for compare"),
                          command=lambda: (self.app.toggle_compare(cuid), self.app.say("Compare list: %d tagged." % len(self.app.compare_uids))))
            m.add_separator()
            m.add_command(label="Delete this %s…" % ("building" if self.app.proj.is_building(cd) else "module"), foreground="#e06060",
                          command=lambda: self.app.delete_item(cd))
        popup(m, ev)

    def revert(self, cell):
        if not self.menu_hit:
            return
        col = self.cols[self.menu_hit[2]]
        for r in self.selected_rows():
            r.revert(col) if cell else r.revert_all()
        self.app.refresh()

    def to_default(self, cell):
        if not self.menu_hit:
            return
        col = self.cols[self.menu_hit[2]]
        n = 0
        for r in self.selected_rows():
            if cell:
                n += 1 if r.set_default(col) else 0
            else:
                n += r.set_default_all()
        self.app.refresh()
        self.app.say("Set %d value(s) to default (the value before this editor first changed them)." % n)

    # ---- columns
    def set_visible(self, idxs):
        self.visible = idxs or list(range(len(self.cols)))
        self.populate()

    def preset(self):
        return [i for i, c in enumerate(self.cols)
                if c.tag in ESSENTIALS and (c.src, c.tag) not in self.hide_in_preset]


def load_image(path, size):
    """Icon fitted into a size x size box (keeps aspect ratio; scales up small icons too)."""
    path = Path(path)
    is_xnb = path.suffix.lower() == ".xnb"
    is_dds = path.suffix.lower() == ".dds" or is_xnb
    if Image and not is_xnb:
        try:
            im = Image.open(path).convert("RGBA")
            k = size / float(max(im.size))
            im = im.resize((max(1, int(im.width * k)), max(1, int(im.height * k))),
                           getattr(Image, "Resampling", Image).LANCZOS)
            return ImageTk.PhotoImage(im)
        except Exception:
            if not is_dds:
                raise                                   # a .dds Pillow can't open: try the built-in reader below
    if is_dds:
        w, h, rgba = decode_xnb(path) if is_xnb else decode_dds(path)
        img = tk.PhotoImage(data=base64.b64encode(rgba_to_png(w, h, rgba)))
    else:
        img = tk.PhotoImage(file=str(path))
    big = max(img.width(), img.height())
    if big > size:
        img = img.subsample(-(-big // size))
    elif big * 2 <= size:
        img = img.zoom(size // big)
    return img


def read_photo(path):
    """The picture at its own size as a Tk image, without Pillow (.png / .gif natively, .dds / .xnb with the built-in readers)."""
    path = Path(path)
    ext = path.suffix.lower()
    if ext in (".dds", ".xnb"):
        w, h, rgba = decode_xnb(path) if ext == ".xnb" else decode_dds(path)
        return tk.PhotoImage(data=base64.b64encode(rgba_to_png(w, h, rgba)))
    return tk.PhotoImage(file=str(path))


def stretch_photo(img, w, h):
    """img scaled to about w x h pixels with Tk's own zoom / subsample (whole-number ratios, so it is approximate)."""
    from fractions import Fraction
    fx, fy = Fraction(w, max(1, img.width())).limit_denominator(8), Fraction(h, max(1, img.height())).limit_denominator(8)
    fx, fy = max(fx, Fraction(1, 12)), max(fy, Fraction(1, 12))
    out = img
    if fx.numerator > 1 or fy.numerator > 1:
        out = out.zoom(max(1, fx.numerator), max(1, fy.numerator))
    if fx.denominator > 1 or fy.denominator > 1:
        out = out.subsample(max(1, fx.denominator), max(1, fy.denominator))
    return out


def try_set(obj, tag, new):
    """Validate and apply one edit. Returns (applied, message_to_show_or_None)."""
    old = obj.get(tag)
    o = old.strip().lower()
    if o in ("true", "false"):
        new = new.strip().lower()
    elif NUM_RE.match(old.strip()):
        new = new.strip()
    err = validate(old, new)
    if err:
        return False, err
    if INT_RE.match(old.strip()) and NUM_RE.match(new) and not INT_RE.match(new):
        if not messagebox.askyesno("Decimal in a whole-number field?",
                                   "'%s' was a whole number and you entered '%s'." % (old.strip(), new)
                                   + chr(10) + "If the game expects an integer here it may ignore or reject it."
                                   + chr(10) + chr(10) + "Keep it?"):
            return False, None
    if tag not in obj.cur and not new.strip():
        return True, None
    obj.set(tag, new)
    return True, None


def placeholder(size, seed):
    img = tk.PhotoImage(width=size, height=size)
    img.put((ORANGE, PURPLE, BLUE, PEACH)[sum(map(ord, seed)) % 4], to=(0, 0, size, size))
    img.put(BG, to=(3, 3, size - 3, size - 3))
    return img


class ScrollFrame(tk.Frame):
    """A vertically scrolling container: put widgets in .inner; mouse wheel is handled by App._wheel."""

    def __init__(self, master, bg=PANEL, scrollbar=True, hscroll=False):
        super().__init__(master, bg=bg)
        self.canvas = tk.Canvas(self, bg=bg, highlightthickness=0, yscrollincrement=24)
        self.on_scroll = None
        if scrollbar:
            vsb = ttk.Scrollbar(self, orient="vertical", command=self.canvas.yview)
            self.canvas.configure(yscrollcommand=lambda a, b: (vsb.set(a, b), self.on_scroll() if self.on_scroll else None))
            vsb.pack(side="right", fill="y")
        if hscroll:
            hsb = ttk.Scrollbar(self, orient="horizontal", command=self.canvas.xview)
            self.canvas.configure(xscrollcommand=lambda a, b: (hsb.set(a, b), self.on_scroll() if self.on_scroll else None))
            hsb.pack(side="bottom", fill="x")
        self.canvas.pack(side="left", fill="both", expand=True)
        self.inner = tk.Frame(self.canvas, bg=bg)
        self.win = self.canvas.create_window((0, 0), window=self.inner, anchor="nw")
        self.inner.bind("<Configure>", lambda _e: (self.canvas.configure(scrollregion=self.canvas.bbox("all")), self.on_scroll() if self.on_scroll else None))
        self.canvas.bind("<Configure>", lambda e: None if hscroll else self.canvas.itemconfigure(self.win, width=e.width))

    def clear(self):
        for w in self.inner.winfo_children():
            w.destroy()
        self.canvas.yview_moveto(0)


class FrozenScroll(ScrollFrame):
    """A scrolling table whose left columns and top heading row stay on screen. Three canvases (left, top, body) are kept in step by the
    scrollbars, so nothing is repositioned while scrolling (fast, no flicker). Put the left widgets in .left, the headings in .top and the
    cells in .inner; call settle() after building so rows and columns line up."""

    def __init__(self, master, bg=PANEL, left_w=250):
        tk.Frame.__init__(self, master, bg=bg)
        self.on_scroll = None
        self.left_w, self.top_h, self._pending = left_w, 40, False
        self._rows, self._cols = [], []
        self.corner = tk.Frame(self, bg=bg, width=left_w, height=40)
        self.corner.grid(row=0, column=0, sticky="nsew")
        self.topcv = tk.Canvas(self, bg=bg, height=40, highlightthickness=0)
        self.topcv.grid(row=0, column=1, sticky="ew")
        self.leftcv = tk.Canvas(self, bg=bg, width=left_w, highlightthickness=0, yscrollincrement=24)
        self.leftcv.grid(row=1, column=0, sticky="ns")
        self.canvas = tk.Canvas(self, bg=bg, highlightthickness=0, yscrollincrement=24)
        self.canvas.grid(row=1, column=1, sticky="nsew")
        self.vsb = ttk.Scrollbar(self, orient="vertical", command=self.canvas.yview)
        self.vsb.grid(row=1, column=2, sticky="ns")
        self.hsb = ttk.Scrollbar(self, orient="horizontal", command=self.canvas.xview)
        self.hsb.grid(row=2, column=1, sticky="ew")
        self.columnconfigure(1, weight=1)
        self.rowconfigure(1, weight=1)
        self.inner = tk.Frame(self.canvas, bg=bg)
        self.win = self.canvas.create_window((0, 0), window=self.inner, anchor="nw")
        self.left = tk.Frame(self.leftcv, bg=bg)
        self.leftcv.create_window((0, 0), window=self.left, anchor="nw")
        self.top = tk.Frame(self.topcv, bg=bg)
        self.topcv.create_window((0, 0), window=self.top, anchor="nw")
        self.canvas.configure(yscrollcommand=self._ys, xscrollcommand=self._xs)
        for f in (self.inner, self.left, self.top):
            f.bind("<Configure>", lambda _e: self._regions())

    def _ys(self, a, b):
        self.vsb.set(a, b)
        self.leftcv.yview_moveto(a)

    def _xs(self, a, b):
        self.hsb.set(a, b)
        self.topcv.xview_moveto(a)

    def _regions(self):
        if not self._pending:
            self._pending = True
            self.after_idle(self._do_regions)

    def _do_regions(self):
        self._pending = False
        try:
            w = max(self.inner.winfo_reqwidth(), self.top.winfo_reqwidth())
            h = max(self.inner.winfo_reqheight(), self.left.winfo_reqheight())
            self.canvas.configure(scrollregion=(0, 0, w, h))
            self.leftcv.configure(scrollregion=(0, 0, self.left_w, h))
            self.topcv.configure(scrollregion=(0, 0, w, self.top_h))
        except tk.TclError:
            pass

    def settle(self):
        """Make every row as tall in the left list as in the body, and every column as wide under its heading as in the body."""
        try:
            self.update_idletasks()
            for r in range(max(self.inner.grid_size()[1], self.left.grid_size()[1])):
                h = max(self.inner.grid_bbox(0, r)[3], self.left.grid_bbox(0, r)[3])
                self.inner.rowconfigure(r, minsize=h)
                self.left.rowconfigure(r, minsize=h)
                self._rows.append(r)
            for c in range(max(self.inner.grid_size()[0], self.top.grid_size()[0])):
                w = max(self.inner.grid_bbox(c, 0)[2], self.top.grid_bbox(c, 0)[2])
                self.inner.columnconfigure(c, minsize=w)
                self.top.columnconfigure(c, minsize=w)
                self._cols.append(c)
            self.update_idletasks()
            self.top_h = max(24, self.top.winfo_reqheight())
            self.topcv.configure(height=self.top_h)
            self.corner.configure(height=self.top_h)
            self._do_regions()
        except tk.TclError:
            pass

    def clear(self):
        for f in (self.inner, self.left, self.top, self.corner):
            for w in f.winfo_children():
                w.destroy()
        for r in self._rows:
            self.inner.rowconfigure(r, minsize=0)
            self.left.rowconfigure(r, minsize=0)
        for c in self._cols:
            self.inner.columnconfigure(c, minsize=0)
            self.top.columnconfigure(c, minsize=0)
        self._rows, self._cols = [], []
        self.canvas.yview_moveto(0)
        self.canvas.xview_moveto(0)
        self.leftcv.yview_moveto(0)
        self.topcv.xview_moveto(0)


class TechTree(ttk.Frame):
    """Category icons down the left; hover one for a scrollable module list; hover a module for a stat card."""
    STRIP_W, FLY_W = 104, 410
    ALL_RACES, GENERIC = "All races", "(generic - no race)"

    def race_ok(self, m):
        sel = self.race_var.get() if self.races is not None else self.ALL_RACES
        rs = self.races.of.get((m.get("UID") or m.path.stem).strip().lower(), set()) if self.races is not None else set()
        if sel == self.ALL_RACES:
            return bool(rs) or not self.only_specific.get() if self.races is not None else True
        if sel == self.GENERIC:
            return not rs
        return sel in rs if rs else not self.only_specific.get()

    def apply_race_filter(self):
        self.hide_fly()
        self.cats = {c: [m for m in ms if self.race_ok(m)] for c, ms in self.all_cats.items()}
        self.cats = {c: ms for c, ms in self.cats.items() if ms}
        n = sum(len(v) for v in self.cats.values())
        self.race_note["text"] = "%d of %d modules" % (n, len(self.proj.modules))
        self.catlist.clear()
        self.cat_w = {}
        self._build_strip()
        if self.stage_box is not None:
            self.stage_box.destroy()
        self._build_stage()

    def __init__(self, master, app):
        super().__init__(master)
        self.app, self.proj = app, app.proj
        self.cache, self.jobs = {}, set()
        self.cat_open = self.hover_m = self.hover_widgets = None
        self.pop_job = self.hide_job = self.poll_job = None
        self.out_count = 0
        self.cat_w = {}
        self.editor = self.stage_box = None
        self.editing = False
        self.all_cats = {}
        for m in self.proj.modules:
            self.all_cats.setdefault(m.get("ModuleType").strip() or "(no type)", []).append(m)
        for lst in self.all_cats.values():
            lst.sort(key=lambda m: (sort_key(m.get("TechLevel")), module_name(self.proj, m).lower()))
        self.cats = dict(self.all_cats)
        self.races = None
        try:
            self.races = self.proj.race_info()
        except Exception:
            log_exc()
        self.bar = tk.Frame(self, bg=PANEL)                    # race filter
        self.bar.pack(side="top", fill="x")
        if self.races is not None:
            tk.Label(self.bar, text="Race", bg=PANEL, fg=PEACH, font=("Segoe UI", 10, "bold")).pack(side="left", padx=(12, 6), pady=6)
            self.race_var = tk.StringVar(value=self.ALL_RACES)
            self.race_cb = ttk.Combobox(self.bar, textvariable=self.race_var, state="readonly", width=30,
                                        values=[self.ALL_RACES] + self.races.names + [self.GENERIC])
            self.race_cb.pack(side="left")
            self.race_cb.bind("<<ComboboxSelected>>", lambda _e: self.apply_race_filter())
            tip(self.race_cb, "Show only the modules a race can use: modules tied to that race plus the generic ones. "
                              "How modules are tied to races is explained in the Debug tab ('Race filter').")
            self.only_specific = tk.BooleanVar(value=False)
            cb = ttk.Checkbutton(self.bar, text="Hide generic modules", variable=self.only_specific, command=self.apply_race_filter)
            cb.pack(side="left", padx=12)
            tip(cb, "Leave out modules that every race can use, so only the race's own modules remain.")
            self.race_note = tk.Label(self.bar, bg=PANEL, fg=DIM)
            self.race_note.pack(side="right", padx=12)
        self.strip = tk.Frame(self, bg=PANEL, width=self.STRIP_W)
        self.strip.pack(side="left", fill="y")
        self.strip.pack_propagate(False)
        self.catlist = ScrollFrame(self.strip, bg=PANEL, scrollbar=False)
        self.catlist.pack(fill="both", expand=True)
        self.stage = tk.Frame(self, bg=BG)
        self.stage.pack(side="left", fill="both", expand=True)
        self.fly = tk.Frame(self, bg=PANEL2, highlightthickness=2, highlightbackground=ORANGE)
        hdr = tk.Frame(self.fly, bg=HOVER_BG)
        hdr.pack(fill="x")
        self.fly_cmp = tk.Label(hdr, bg=HOVER_BG, fg=PEACH, cursor="hand2", padx=10)
        self.fly_cmp.pack(side="right")
        tip(self.fly_cmp, "Open the Compare tab with the starred modules")
        self.fly_cmp.bind("<Button-1>", lambda _e: self.go_compare())
        self.fly_title = tk.Label(hdr, bg=HOVER_BG, fg=ORANGE, font=("Segoe UI", 12, "bold"),
                                  anchor="w", padx=10, pady=6)
        self.fly_title.pack(side="left", fill="x", expand=True)
        self.list = ScrollFrame(self.fly, bg=PANEL2)
        self.list.pack(fill="both", expand=True)
        self._build_popup()
        self._build_strip()
        self._build_stage()

    # ---- plumbing
    def _after(self, ms, fn):
        job = None

        def run():
            self.jobs.discard(job)
            fn()
        job = self.after(ms, run)
        self.jobs.add(job)
        return job

    def _cancel(self, job):
        if job:
            self.jobs.discard(job)
            try:
                self.after_cancel(job)
            except Exception:
                pass

    def destroy(self):
        for j in list(self.jobs):
            self._cancel(j)
        super().destroy()

    @staticmethod
    def _paint(widgets, bg):
        for w in widgets:
            try:
                w.configure(bg=bg)
            except tk.TclError:
                pass

    @staticmethod
    def _inside(w, x, y):
        try:
            return (w.winfo_rootx() <= x < w.winfo_rootx() + w.winfo_width()
                    and w.winfo_rooty() <= y < w.winfo_rooty() + w.winfo_height())
        except Exception:
            return False

    def icon(self, path, size, seed):
        key = (str(path), size, seed if not path else "")
        if key not in self.cache:
            img = None
            if path:
                try:
                    img = load_image(path, size)
                except Exception as e:                  # shows as a coloured box; the Debug tab lists why
                    self.proj.bad_icons[str(path)] = "%s: %s" % (type(e).__name__, e)
                    img = None
            self.cache[key] = img or placeholder(size, seed)
        return self.cache[key]

    def refresh_icons(self):
        """Forget cached images and rebuild the category strip + intro (after texture folders changed)."""
        self.hide_fly()
        self.cache.clear()
        self.proj._icons.clear()
        self.proj.bad_icons.clear()
        self.catlist.clear()
        self.cat_w = {}
        self._build_strip()
        if self.stage_box is not None:
            self.stage_box.destroy()
        self._build_stage()

    # ---- left strip + stage
    def _build_strip(self):
        for cat in sorted(self.cats, key=str.lower):
            mods = self.cats[cat]
            path = self.proj.find_file(CATEGORY_ICONS.get(cat)) if CATEGORY_ICONS.get(cat) else None
            for m in mods[:15]:
                if path:
                    break
                path = self.proj.find_icon(m)
            f = tk.Frame(self.catlist.inner, bg=PANEL, cursor="hand2")
            f.pack(fill="x", pady=1)
            il = tk.Label(f, image=self.icon(path, 44, cat), bg=PANEL)
            il.pack(pady=(8, 0))
            tl = tk.Label(f, text=cat, bg=PANEL, fg=PEACH, font=("Segoe UI", 8), wraplength=self.STRIP_W - 14)
            tl.pack(pady=(0, 8))
            self.cat_w[cat] = (f, il, tl)
            for w in (f, il, tl):
                w.bind("<Enter>", lambda _e, c=cat: self.show_cat(c))
                w.bind("<Button-1>", lambda _e, c=cat: self.show_cat(c, force=True))

    def _build_stage(self):
        mods = [m for ms in self.cats.values() for m in ms]
        found = sum(1 for m in mods if self.proj.find_icon(m))
        guessed = len(self.proj.icon_guessed)
        box = self.stage_box = tk.Frame(self.stage, bg=BG)
        box.place(relx=0.5, rely=0.42, anchor="center")
        tk.Label(box, text="SHIP MODULES", bg=BG, fg=ORANGE, font=("Segoe UI", 30, "bold")).pack()
        tk.Label(box, text="Hover a category on the left  ›  hover a module for its stats  ›  click it to open its editor",
                 bg=BG, fg=PEACH, font=("Segoe UI", 11)).pack(pady=(4, 16))
        tk.Label(box, text="%d modules in %d categories   ·   icons found: %d of %d%s"
                 % (len(mods), len(self.cats), found, len(mods),
                    ("  (%d guessed from the module name)" % guessed) if guessed else ""), bg=BG, fg=FG).pack()
        if found < len(mods):
            tk.Label(box, text="Missing icons show as coloured boxes - the Debug tab ('Icons summary') says why. Searched:",
                     bg=BG, fg=DIM).pack(pady=(10, 0))
            tk.Label(box, text=chr(10).join(str(d) for d in self.proj.icon_dirs) or "(no texture folders found)",
                     bg=BG, fg=DIM, justify="center").pack()
        if not Image:
            tk.Label(box, text="Tip: run  pip install pillow  for smoother icons.", bg=BG, fg=DIM).pack(pady=(10, 0))

    # ---- flyout list
    def _highlight_cat(self, cat):
        for c, ws in self.cat_w.items():
            self._paint(ws, HOVER_BG if c == cat else PANEL)

    def show_cat(self, cat, force=False):
        if self.cat_open == cat and not force:
            return
        self.hide_popup()
        self.cat_open = cat
        self._highlight_cat(cat)
        mods = self.cats[cat]
        self.fly_title["text"] = "%s    ·    %d" % (cat, len(mods))
        self.fly_cmp["text"] = "★ Compare (%d)" % len(self.app.compare_uids)
        self.list.clear()
        for m in mods:
            self.add_row(m)
        bh = self.bar.winfo_height() if self.bar.winfo_height() > 1 else self.bar.winfo_reqheight()
        self.fly.place(x=self.STRIP_W, y=bh, width=self.FLY_W, relheight=1.0, height=-bh)
        self.fly.lift()
        self.out_count = 0
        if self.poll_job is None:
            self.poll_job = self._after(150, self._poll)

    def hide_fly(self):
        self._cancel(self.poll_job)
        self.poll_job = None
        self.hide_popup()
        self.fly.place_forget()
        self.cat_open = None
        self._highlight_cat(None)

    def _poll(self):                      # close the flyout once the pointer has left the strip and the list
        self.poll_job = None
        if self.cat_open is None:
            return
        if self.editing:
            self.poll_job = self._after(120, self._poll)
            return
        x, y = self.winfo_pointerxy()
        inside = (self._inside(self.fly, x, y) or self._inside(self.strip, x, y)
                  or (self.pop.winfo_viewable() and self._inside(self.pop, x, y)))
        self.out_count = 0 if inside else self.out_count + 1
        if self.out_count >= 2:
            self.hide_fly()
        else:
            self.poll_job = self._after(120, self._poll)

    def add_row(self, m):
        uid = m.get("UID") or m.path.stem
        edited = ModRow(self.proj, m).dirty()
        row = tk.Frame(self.list.inner, bg=PANEL2, cursor="hand2")
        row.pack(fill="x", padx=4, pady=1)
        tagged = uid in self.app.compare_uids
        star = tk.Label(row, text="★" if tagged else "☆", bg=PANEL2, fg=ORANGE if tagged else DIM,
                        font=("Segoe UI", 14), cursor="hand2", padx=4)
        star.pack(side="right")
        tip(star, "Tag / untag this module for the Compare tab")
        tl = tk.Label(row, text="T" + (m.get("TechLevel").strip() or "?"), bg=PANEL2, fg=ORANGE)
        tl.pack(side="right", padx=8)
        il = tk.Label(row, image=self.icon(self.proj.find_icon(m), 40, uid), bg=PANEL2, width=44)
        il.pack(side="left", padx=(4, 6), pady=3)
        tf = tk.Frame(row, bg=PANEL2)
        tf.pack(side="left", fill="x", expand=True)
        nl = tk.Label(tf, text=module_name(self.proj, m), bg=PANEL2, fg=EDITED_FG if edited else FG, anchor="w")
        nl.pack(fill="x")
        ul = tk.Label(tf, text=uid, bg=PANEL2, fg=DIM, anchor="w", font=("Segoe UI", 8))
        ul.pack(fill="x")
        ws = (row, il, tf, nl, ul, tl, star)
        for w in ws:
            w.bind("<Enter>", lambda _e, m=m, ws=ws: self.item_enter(m, ws))
            w.bind("<Leave>", lambda _e: self.item_leave())
            if w is not star:
                w.bind("<Button-1>", lambda _e, m=m: self.open_module(m))
            for bn in ("<Button-3>", "<Button-2>"):
                w.bind(bn, lambda e, m=m: self.row_menu(m, e))
        star.bind("<Button-1>", lambda _e, uid=uid, st=star: self._toggle_star(uid, st))

    def row_menu(self, d, e):
        isb = self.proj.is_building(d)
        m = tk.Menu(self, tearoff=0)
        m.add_command(label="Copy this %s as a new one…" % ("building" if isb else "module"), command=lambda: (self.hide_fly(), self.app.copy_item(d)))
        key = doc_key(d)
        m.add_command(label="Remove from compare" if key in self.app.compare_uids else "★ Tag for compare",
                      command=lambda: self.app.toggle_compare(key))
        m.add_command(label="Make a picture with an AI…", command=lambda: (self.hide_fly(), self.app.ai_picture("building" if isb else "module", d)))
        m.add_separator()
        m.add_command(label="Delete this %s…" % ("building" if isb else "module"), foreground="#e06060",
                      command=lambda: (self.hide_fly(), self.app.delete_item(d)))
        self.editing = True                    # keep the flyout open while the menu is up
        try:
            m.tk_popup(e.x_root, e.y_root)
        finally:
            m.grab_release()
            self.editing = False
        return "break"

    def _toggle_star(self, uid, star):
        on = self.app.toggle_compare(uid)
        star.configure(text="★" if on else "☆", fg=ORANGE if on else DIM)
        self.fly_cmp["text"] = "★ Compare (%d)" % len(self.app.compare_uids)

    def go_compare(self):
        self.hide_fly()
        self.app.show_compare()

    def open_module(self, m):
        self.hide_fly()
        self.stage_box.place_forget()
        if self.editor:
            self.editor.destroy()
        self.editor = ModuleEditor(self.stage, self.app, self, m)
        self.editor.pack(fill="both", expand=True)

    def close_editor(self):
        if self.editor:
            self.editor.destroy()
            self.editor = None
        self.stage_box.place(relx=0.5, rely=0.42, anchor="center")

    def open_in_table(self, m):
        uid = m.get("UID") or m.path.stem
        self.hide_fly()
        self.app.goto_module(uid)

    # ---- hover card
    def _build_popup(self):
        self.pop = tk.Toplevel(self)
        self.pop.withdraw()
        self.pop.overrideredirect(True)
        self.pop.configure(bg=ORANGE)
        try:
            self.pop.attributes("-topmost", True)
        except Exception:
            pass
        body = tk.Frame(self.pop, bg=PANEL)
        body.pack(padx=2, pady=2)
        head = tk.Frame(body, bg=PANEL)
        head.pack(fill="x", padx=14, pady=(14, 6))
        self.pop_img = tk.Label(head, bg=PANEL)
        self.pop_img.pack(side="left")
        tf = tk.Frame(head, bg=PANEL)
        tf.pack(side="left", padx=16, anchor="n")
        self.pop_title = tk.Label(tf, bg=PANEL, fg=ORANGE, font=("Segoe UI", 14, "bold"), anchor="w",
                                  justify="left", wraplength=250)
        self.pop_title.pack(anchor="w")
        self.pop_sub = tk.Label(tf, bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=250)
        self.pop_sub.pack(anchor="w")
        self.pop_fits = tk.Label(tf, bg=PANEL, fg=PEACH, anchor="w", justify="left", wraplength=250)
        self.pop_fits.pack(anchor="w", pady=(6, 0))
        self.pop_desc = tk.Label(body, bg=PANEL, fg=FG, anchor="w", justify="left", wraplength=430)
        self.pop_desc.pack(fill="x", padx=14, pady=(0, 6))
        self.pop_stats = tk.Frame(body, bg=PANEL)
        self.pop_stats.pack(fill="x", padx=14, pady=(0, 6))
        tk.Label(body, text="double-click a name or value to edit", bg=PANEL, fg=DIM,
                 font=("Segoe UI", 8)).pack(pady=(0, 8))
        for wdg, fn in ((self.pop_title, self.edit_name), (self.pop_desc, self.edit_desc),
                        (self.pop_fits, self.edit_slot)):
            wdg.configure(cursor="hand2")
            wdg.bind("<Double-1>", lambda _e, fn=fn: fn(self.hover_m))

    def item_enter(self, m, ws):
        self._cancel(self.hide_job)
        self._cancel(self.pop_job)
        self.hide_job = None
        if self.hover_widgets is not ws:
            if self.hover_widgets:
                self._paint(self.hover_widgets, PANEL2)
            self._paint(ws, HOVER_BG)
            self.hover_widgets = ws
        self.hover_m = m
        self.pop_job = self._after(30 if self.pop.winfo_viewable() else 160, lambda: self.show_popup(m, ws[0]))

    def item_leave(self):
        self._cancel(self.pop_job)
        self._cancel(self.hide_job)
        self.hide_job = self._after(250, self._maybe_hide)

    def _maybe_hide(self):                # don't hide while the pointer is on the card (so it can be edited)
        self.hide_job = None
        x, y = self.winfo_pointerxy()
        if self.editing or (self.pop.winfo_viewable() and self._inside(self.pop, x, y)):
            self.hide_job = self._after(200, self._maybe_hide)
            return
        self.hide_popup()

    def hide_popup(self):
        self._cancel(self.pop_job)
        self._cancel(self.hide_job)
        self.pop_job = self.hide_job = None
        self.pop.withdraw()
        if self.hover_widgets:
            self._paint(self.hover_widgets, PANEL2)
        self.hover_widgets = self.hover_m = None

    def _render_popup(self, m):
        p = self.proj
        w = p.weapon_for(m)
        uid = m.get("UID") or m.path.stem
        self.pop_img.configure(image=self.icon(p.find_icon(m), 150, uid))
        self.pop_title["text"] = module_name(p, m)
        self.pop_sub["text"] = uid + (("    ·    weapon: " + (w.get("UID") or w.path.stem)) if w else "")
        ships, slot = module_fits(m)
        rs = sorted(self.races.of.get(uid.strip().lower(), ())) if self.races is not None else []
        self.pop_fits["text"] = "   ·   ".join(x for x in (("Fits: " + ships) if ships else "",
                                                           ("Slot: " + slot) if slot else "",
                                                           ("Race: " + ", ".join(rs)) if rs else "") if x)
        e = p.text_display(m, "DescriptionIndex")
        desc = " ".join(m.get("Description").split()) or (e.get("ENG") if e else "")
        self.pop_desc.configure(text=desc or "(no description - double-click to add one)", fg=FG if desc else DIM)
        for c in self.pop_stats.winfo_children():
            c.destroy()
        for i, (label, val, edited, obj, tag) in enumerate(module_stats(p, m)):
            r, c = divmod(i, 2)
            lb = tk.Label(self.pop_stats, text=label, bg=PANEL, fg=DIM, anchor="w", cursor="hand2")
            lb.grid(row=r, column=c * 2, sticky="w", padx=(0, 8), pady=1)
            vl = tk.Label(self.pop_stats, text=val, bg=PANEL, fg=EDITED_FG if edited else FG, anchor="e",
                          cursor="hand2")
            vl.grid(row=r, column=c * 2 + 1, sticky="e", padx=(0, 26), pady=1)
            for wdg in (lb, vl):
                wdg.bind("<Double-1>", lambda _e, lab=label, o=obj, t=tag: self.edit_target(lab, o, t))

    def show_popup(self, m, anchor):
        if self.hover_m is not m:
            return
        self._render_popup(m)
        self.pop.update_idletasks()
        x = self.fly.winfo_rootx() + self.fly.winfo_width()          # touches the list so the pointer can cross
        x = min(x, self.winfo_screenwidth() - self.pop.winfo_reqwidth() - 10)
        y = max(10, min(anchor.winfo_rooty() - 12, self.winfo_screenheight() - self.pop.winfo_reqheight() - 60))
        self.pop.geometry("+%d+%d" % (x, y))
        self.pop.deiconify()
        self.pop.lift()

    def edit_target(self, label, obj, tag, multiline=False):
        m = self.hover_m
        self.editing = True
        self.pop.withdraw()                # so it can't cover the edit window
        try:
            self.app.edit_field(label, obj, tag, multiline)
        finally:
            self.editing = False
        if m is not None and self.hover_m is m:
            self._render_popup(m)
            self.pop.deiconify()
            self.pop.lift()

    def edit_name(self, m):
        e = self.proj.text_for(m, "NameIndex") if m else None
        if e:
            self.edit_target("Name", e, "ENG")
        else:
            self.app.say("This module has no GameText name entry to edit.")

    def edit_desc(self, m):
        if not m:
            return
        e = self.proj.text_for(m, "DescriptionIndex")
        if m.get("Description").strip() or not e:
            self.edit_target("Description", m, "Description", True)
        else:
            self.edit_target("Description", e, "ENG", True)

    def edit_slot(self, m):
        if m and "Restrictions" in m.cur:
            self.edit_target("Restrictions (slot)", m, "Restrictions")

WEAPON_SWITCHES = ("Tag_Kinetic", "Tag_Energy", "Tag_Guided", "Tag_Missile", "Tag_Plasma", "Tag_Beam", "Tag_Cannon", "Tag_Intercept", "Tag_PD",
                   "Tag_Torpedo", "Tag_Bomb", "Tag_Drone", "Tag_BioWeapon")
# true / false building fields (Building.cs); Scrappable and Unique are true when the tag is missing
BUILDING_SWITCHES = ("Scrappable", "Unique", "BuildOnlyOnce", "CanBuildAnywhere", "CannotBeBombed", "NoRandomSpawn", "AllowShipBuilding", "AllowInfantry",
                     "IsCommodity", "ShowOnPlanetList", "WinsGame", "IsPlayerAdded", "DetectsRemnantFleet", "CanBeCreatedFromLava", "ImmueToLava", "CanBeTerraformed")
SWITCH_DEFAULT_TRUE = ("Scrappable", "Unique")


def value_scale(parent, vals, var, commit, tag, width=120):
    """A small ruler under a number: the spread of this tag in the other files (bars), the typical value (line) and this value (orange marker).
    Hover for the figures; click or drag to set the value on the ruler."""
    vals = sorted(vals)
    W, H = width, 20
    cv = tk.Canvas(parent, width=W, height=H, bg=BG, highlightthickness=0, cursor="hand2" if len(vals) >= 3 else "")
    if len(vals) < 3:
        tip(cv, "Too few other files use this tag to draw a scale.")
        return cv
    n = len(vals)
    pick = lambda q: vals[min(n - 1, max(0, int(q * (n - 1) + 0.5)))]
    lo, hi, med = pick(0.02), pick(0.98), pick(0.5)
    if hi <= lo:
        lo, hi = vals[0], vals[-1]
    isint = all(v == int(v) for v in vals)
    state = {"lo": lo, "hi": hi}

    def cur():
        try:
            return float(var.get().strip())
        except ValueError:
            return None

    def x_of(v):
        a, b = state["lo"], state["hi"]
        return 4 + (W - 8) * (min(max(v, a), b) - a) / ((b - a) or 1.0)

    def draw(*_a):
        cv.delete("all")
        c = cur()
        a, b = lo, hi
        if c is not None:
            a, b = min(lo, c), max(hi, c)
        state["lo"], state["hi"] = a, b
        bins = [0] * 12
        for v in vals:
            bins[min(11, int((min(max(v, a), b) - a) / ((b - a) or 1.0) * 12))] += 1
        top = float(max(bins)) or 1.0
        for i, k in enumerate(bins):
            if k:
                h = 2 + 10 * k / top
                x0 = 4 + (W - 8) * i / 12.0
                cv.create_rectangle(x0 + 1, 14 - h, x0 + (W - 8) / 12.0 - 1, 14, fill=EDGE, outline="")
        cv.create_line(4, 15, W - 4, 15, fill=DIM)
        cv.create_line(x_of(med), 3, x_of(med), 17, fill=BLUE)
        if c is not None:
            x = x_of(c)
            cv.create_polygon(x - 4, 19, x + 4, 19, x, 13, fill=ORANGE, outline="")
    draw()
    var.trace_add("write", lambda *_a: draw())

    def val_at(ev):
        a, b = state["lo"], state["hi"]
        v = a + (b - a) * min(1.0, max(0.0, (ev.x - 4) / float(W - 8)))
        if isint:
            v = round(v)
        else:
            v = float("%.3g" % v)
        return fmt_num(v)

    def setv(ev):
        var.set(val_at(ev))

    def release(ev):
        commit()
    cv.bind("<B1-Motion>", setv)
    cv.bind("<Button-1>", setv)
    cv.bind("<ButtonRelease-1>", release)

    def info():
        c = cur()
        pct = ""
        if c is not None:
            pct = "\nThis value: %s  (bigger than %d%% of the %d files that use it)" % (fmt_num(c), round(100.0 * sum(1 for v in vals if v < c) / n), n)
        return ("Scale of %s in the other files (%d with a value)%s\nSmallest %s    typical %s    largest %s\nBars: how many files sit at each level.  Blue line: typical.  "
                "Orange: this value.\nClick or drag here to set the value on this ruler; or type one." % (tag, n, pct, fmt_num(vals[0]), fmt_num(med), fmt_num(vals[-1])))
    tip(cv, info)
    return cv


def numeric_vals(docs, tag):
    out = []
    for d in docs:
        v = (d.get(tag) or "").strip()
        if v and NUM_RE.match(v):
            out.append(float(v))
    return out


def entry_scale(parent, var, docs, tag, width=12, bg=PANEL, commit=None):
    """An entry with the scale ruler beside it (how the other files set this tag)."""
    f = tk.Frame(parent, bg=bg)
    e = ttk.Entry(f, textvariable=var, width=width)
    e.pack(side="left")
    value_scale(f, numeric_vals(docs, tag), var, commit or (lambda: None), tag, width=110).pack(side="left", padx=(8, 0))
    f.entry = e
    return f


class ModuleEditor(ttk.Frame):
    """Opens when you click a module in the tech tree: its data split into a few tabs, all editable."""

    # (tab title, [(section title, [(source, tag)...] or callable(editor) -> that list)])
    GROUPS = [
        ("Damage, Effects & Ammo", [
            ("Damage", [("W", "DamageAmount"), ("W", "ProjectileCount"), ("W", "SalvoCount"), ("W", "ExplosionRadius"), ("W", "DamageRadius"),
                        ("W", "EMPDamage"), ("W", "PowerDamage"), ("W", "TractorDamage"), ("W", "RepulsionDamage"), ("W", "SiphonDamage"),
                        ("W", "TroopDamageChance"), ("W", "ArmorPen")]),
            ("Against armour & shields", [("W", "EffectVsArmor"), ("W", "EffectVsShields"), ("W", "EffectVsShield"), ("M", "EffectVsShield"),
                                          ("W", "ShieldPenChance"), ("W", "WeaponEffectType")]),
            ("Rate of fire, reach & aiming", [("W", "FireDelay"), ("W", "fireDelay"), ("W", "SalvoTimer"), ("W", "Range"), ("W", "ProjectileSpeed"),
                                              ("W", "FireArc"), ("W", "FireCone"), ("M", "FieldOfFire"), ("W", "RotationRadsPerSecond"),
                                              ("W", "WeaponRotation"), ("W", "TargetChangeTimer"), ("M", "AccuracyPercent"), ("M", "TargetTracking"),
                                              ("M", "TargetAccuracy"), ("M", "WeaponInaccuracyBase"), ("M", "IndirectPower"), ("M", "DisableRotation")]),
            ("Beams", [("W", "IsBeam"), ("W", "BeamDuration"), ("W", "BeamThickness"), ("W", "BeamPowerCostPerSecond")]),
            ("Projectile behaviour", [("W", "ProjectileRadius"), ("W", "HitPoints"), ("W", "explodes"), ("W", "DelayedIgnition"),
                                      ("W", "CanCollideProjectiles"), ("W", "HitsFriendlies"), ("W", "TruePD"), ("W", "TerminalPhaseAttack"),
                                      ("W", "TerminalPhaseDistance"), ("W", "TerminalPhaseSpeedMod"), ("W", "MirvWeapon"),
                                      ("W", "MirvSeparationDistance"), ("W", "IsRepairDrone")]),
            ("Ammo / ordnance & power to fire", [("W", "OrdinanceRequiredToFire"), ("W", "PowerRequiredToFire"), ("M", "OrdinanceCapacity"),
                                                 ("M", "OrdnanceAddedPerSecond")]),
            ("Weapon tags", lambda ed: [("W", t) for t in dict.fromkeys([t for t in (ed.w.cur if ed.w else []) if t.startswith("Tag_")] + (list(WEAPON_SWITCHES) if ed.w else []))]),
        ]),
        ("Power & Defence", [
            ("Power", [("M", "PowerDraw"), ("M", "PowerFlowMax"), ("M", "PowerStoreMax"), ("M", "PowerDrawAtWarp"), ("M", "OffPowerMod"),
                       ("W", "OffPowerMod"), ("M", "PowerRadius")]),
            ("Shields", [("M", "ShieldPowerMax"), ("M", "ShieldRechargeDelay"), ("M", "ShieldRechargeRate"), ("M", "ShieldRechargeCombatRate"),
                         ("M", "ShieldRadius"), ("M", "AmplifyShields"), ("M", "ShieldDeflection"), ("M", "ShieldPower"), ("M", "ShieldBubbleColor")]),
            ("Shield resistances", [("M", "ShieldKineticResist"), ("M", "ShieldEnergyResist"), ("M", "ShieldBeamResist"), ("M", "ShieldMissileResist"), ("M", "ShieldExplosiveResist"), ("M", "ShieldPlasmaResist")]),
            ("Armour, health & resistances", [("M", "HealthMax"), ("M", "Deflection"), ("M", "KineticResist"), ("M", "EnergyResist"),
                                              ("M", "BeamResist"), ("M", "PlasmaResist"), ("M", "ExplosiveResist"), ("M", "APResist"),
                                              ("M", "EMPProtection"), ("M", "Regenerate"), ("M", "MechanicalBoardingDefense"), ("M", "ECM"), ("M", "TargetValue")]),
            ("When it is destroyed", [("M", "ExplosionDamage"), ("M", "ExplosionRadius")]),
            ("Repair", [("M", "RepairDifficulty"), ("M", "BonusRepairRate"), ("M", "HealPerTurn"), ("M", "IsRepairModule")]),
            ("Engines & movement", [("M", "Thrust"), ("M", "WarpThrust"), ("M", "TurnThrust"), ("M", "FTLSpoolTime"), ("M", "FTLSpeed"), ("M", "WarpMassCapacity")]),
        ]),
        ("Special Systems", [
            ("Sensors & fields", [("M", "SensorRange"), ("M", "SensorBonus"), ("M", "InhibitionRadius"), ("M", "radius"), ("M", "modRadius")]),
            ("Hangars", [("M", "hangarShipUID"), ("M", "HangarTimerConstant"), ("M", "hangerTimerConstant"), ("M", "MaximumHangarShipSize"),
                         ("M", "PermittedHangarRoles"), ("M", "HangarTimer")]),
            ("Troops & transporters", [("M", "TroopCapacity"), ("M", "TroopsSupplied"), ("M", "IsTroopBay"), ("M", "IsSupplyBay"), ("M", "TransporterTroopAssault"), ("M", "TransporterTimerConstant"),
                                       ("M", "TransporterRange"), ("M", "TransporterPower"), ("M", "TransporterOrdnance"),
                                       ("M", "TransporterTroopLanding")]),
            ("Cargo, crew & economy", [("M", "CargoCapacity"), ("M", "CrewRequired"), ("M", "ResearchPerTurn"), ("M", "Refining"), ("M", "Salvage"),
                                      ("M", "NumberOfColonists"), ("M", "NumberOfEquipment"), ("M", "NumberOfFood"), ("M", "ResourceStored"),
                                      ("M", "ResourceStorageAmount"), ("M", "ResourceRequired"), ("M", "DeployBuildingOnColonize"), ("M", "BombType")]),
        ]),
        ("Fitting & Ships", [
            ("Module", [("M", "ModuleType"), ("M", "Restrictions"), ("M", "TechLevel"), ("M", "TechBranch"), ("M", "Cost"), ("M", "Mass"),
                        ("M", "XSize"), ("M", "YSize"), ("M", "CanRotate"), ("M", "Reserved"), ("M", "IsCommandModule"), ("M", "PercentLimitOnShips"),
                        ("M", "MountLeft"), ("M", "MountRight"), ("M", "MountRear"), ("M", "Powered")]),
            ("Ship classes it fits", lambda ed: [("M", t) for t in ed.m.cur if t.endswith("Module")]
             + [("W", t) for t in (ed.w.cur if ed.w else []) if t.startswith("Excludes")]),
        ]),
        ("Look & Sound", [
            ("Module picture", [("M", "IconTexturePath"), ("M", "TexturePath")]),
            ("Projectile & beam look", [("W", "ModelPath"), ("W", "ProjectileTexturePath"), ("W", "Scale"), ("W", "BeamTexture"), ("W", "Light"),
                                        ("W", "Animated"), ("W", "Frames"), ("W", "AnimationPath"), ("W", "LoopAnimation"), ("W", "ExpColor"),
                                        ("W", "WeaponTrailEffect"), ("W", "TrailOffset")]),
            ("Effects", [("W", "MuzzleFlash"), ("W", "WeaponHitEffect"), ("W", "WeaponShieldHitEffect"), ("W", "WeaponDeathEffect")]),
            ("Sounds", [("W", "FireCueName"), ("W", "fireCueName"), ("W", "DieCue"), ("W", "dieCue"), ("W", "InFlightCue"), ("W", "ToggleSoundName"),
                        ("W", "PlaySoundOncePerSalvo")]),
        ]),
    ]
    NAME_IDX, DESC_IDX, INLINE_DESC, THING = "NameIndex", "DescriptionIndex", True, "module"

    # what differs for a building (BuildingEditor below): where the picture, weapon, text and table row come from
    def _find_weapon(self):
        return self.proj.weapon_for(self.m)

    def _icon_path(self):
        return self.proj.find_icon(self.m)

    def _techs(self):
        """The research (tech) files that unlock this module: their Cost is the research cost, editable here."""
        uid = (self.m.get("UID") or self.m.path.stem).strip().lower()
        return [t for t in self.proj.techs if any(mu.strip().lower() == uid for mu, _ty in t.unlocks)]

    def _row(self):
        return ModRow(self.proj, self.m)

    def _goto(self):
        self.app.goto_module(self.uid)

    def _subtitle(self):
        return self.uid + (("    ·    weapon file: " + (self.w.get("UID") or self.w.path.stem)) if self.w else "")

    def __init__(self, master, app, tech, m):
        super().__init__(master)
        self.app, self.tech, self.m, self.proj = app, tech, m, app.proj
        p = self.proj
        self.w = self._find_weapon()
        self.name_e, self.desc_e = p.text_for(m, self.NAME_IDX), p.text_for(m, self.DESC_IDX)
        self._busy = False
        uid = self.uid = doc_key(m) if self.THING == "building" else (m.get("UID") or m.path.stem)

        head = tk.Frame(self, bg=BG)
        head.pack(fill="x", padx=14, pady=(12, 6))
        self.pic = tk.Label(head, image=tech.icon(self._icon_path(), 120, uid), bg=BG, cursor="hand2")
        self.pic.pack(side="left")
        self.pic.bind("<Button-3>", self._pic_menu)
        self.pic.bind("<Button-2>", self._pic_menu)
        self.pic.bind("<Control-Button-1>", self._pic_menu)
        self.pic.bind("<Double-Button-1>", lambda _e: self.change_pic())
        tip(self.pic, "This %s's picture. Right-click (or double-click) to change it." % self.THING)
        tf = tk.Frame(head, bg=BG)
        tf.pack(side="left", padx=16, anchor="n")
        tk.Label(tf, text=module_name(p, m), bg=BG, fg=ORANGE, font=("Segoe UI", 18, "bold"),
                 anchor="w").pack(anchor="w")
        tk.Label(tf, text=self._subtitle(), bg=BG, fg=DIM).pack(anchor="w")
        bf = tk.Frame(tf, bg=BG)
        bf.pack(anchor="w", pady=(8, 0))
        for text, cmd, hint, kw in (
                (getattr(tech, "back_text", "◀  Back to tree"), tech.close_editor, getattr(tech, "back_hint", "Close this editor and go back to the tech tree."), {}),
                ("Show in spreadsheet", self._goto, "Jump to this %s's row in the table." % self.THING, {})):
            b = ttk.Button(bf, text=text, command=cmd, **kw)
            b.pack(side="left", padx=(0, 6) if text.startswith("◀") else 6)
            tip(b, hint)
        self.cmp_btn = ttk.Button(bf, command=self._toggle_cmp)
        self.cmp_btn.pack(side="left", padx=6)
        tip(self.cmp_btn, "Add / remove this %s from the Compare tab." % self.THING)
        self._sync_cmp()
        b = ttk.Button(bf, text="Revert this module", command=self.revert)
        b.pack(side="left", padx=6)
        tip(b, "Undo unsaved edits of this module, its weapon and its text (back to what is on disk).")
        b = ttk.Button(bf, text="Set to default", command=self.to_default)
        b.pack(side="left", padx=6)
        tip(b, "Put this module, its weapon and its text back to their original values (before this editor first changed them).")
        b = ttk.Button(bf, text="Save all  (Ctrl+S)", style="Save.TButton", command=app.save)
        b.pack(side="left", padx=6)
        tip(b, "Review and write all changes to the files.")

        self.nb = ttk.Notebook(self)
        self.nb.pack(fill="both", expand=True, padx=10, pady=(4, 10))
        used = {("M", "Description")}
        self._text_tab()
        for title, sections in self.GROUPS:
            self._group_tab(title, sections, used)
        self._other_tab(used)
        keep = getattr(tech, "_tab_memory", None)
        if keep is not None:                                      # after adding / deleting a tag the editor is rebuilt on the same tab
            tech._tab_memory = None
            try:
                self.nb.select(min(keep, len(self.nb.tabs()) - 1))
            except Exception:
                pass

    # ---- tabs
    def _pic_menu(self, e):
        m = tk.Menu(self, tearoff=0)
        m.add_command(label="Change picture…", command=self.change_pic)
        try:
            m.tk_popup(e.x_root, e.y_root)
        finally:
            m.grab_release()
        return "break"

    def change_pic(self):
        """The tech tree's own Change picture window (import a file, pick an existing picture or make one with an AI), then this editor is rebuilt."""
        kind = "building" if self.THING == "building" else "module"
        self.tech.change_icon(kind, self.m)
        self.after_idle(self._reopen)

    def _tab(self, title):
        sf = ScrollFrame(self.nb, bg=BG)
        self.nb.add(sf, text=title)
        body = tk.Frame(sf.inner, bg=BG)
        body.pack(fill="both", expand=True, padx=16, pady=10)
        return body

    def _note(self, body, text, fg=DIM):
        tk.Label(body, text=text, bg=BG, fg=fg, anchor="w", justify="left", wraplength=760).pack(fill="x", pady=(0, 6))

    def _text_tab(self):
        body = self._tab("Description & Text")
        self._section_title(body, "Name")
        shown = self.proj.text_display(self.m, self.NAME_IDX)
        if self.name_e:
            grid = tk.Frame(body, bg=BG)
            grid.pack(fill="x")
            self._field(grid, 0, 0, self.name_e, "ENG", "Name  (GameText ENG)", width=46)
        elif shown is not None and shown.get("ENG").strip():
            self._note(body, "Name (the base game's text, shown here read-only): " + shown.get("ENG").strip(), FG)
            self._own_text_button(body, self.NAME_IDX, "name")
        else:
            self._note(body, "No GameText entry is linked to this %s's %s." % (self.THING, self.NAME_IDX))
        if self.INLINE_DESC or "Description" in self.m.cur:
            self._text_box(body, "Description  (inline, in the %s XML)" % self.THING, self.m, "Description", 7)
        if self.THING == "building":
            se = self.proj.text_for(self.m, "ShortDescriptionIndex")
            if se:
                self._text_box(body, "Short description  (GameText ENG)", se, "ENG", 3)
        dshown = self.proj.text_display(self.m, self.DESC_IDX)
        if self.desc_e:
            self._text_box(body, "Description  (GameText ENG)", self.desc_e, "ENG", 5)
        elif dshown is not None and dshown.get("ENG").strip():
            self._section_title(body, "Description  (the base game's text, read-only)")
            t = tk.Text(body, wrap="word", height=4, **TEXT_OPTS)
            t.insert("1.0", dshown.get("ENG").strip())
            t.configure(state="disabled")
            t.pack(fill="x")
            self._own_text_button(body, self.DESC_IDX, "description")
            self._note(body, "The base game's own text file is never changed. The button above puts a copy of this text into the mod's GameText so you can edit it.")
        if self.INLINE_DESC or self.desc_e:
            self._note(body, "Both descriptions are editable. Keep them in sync until you have checked in game which one is shown.")
            ab = ttk.Button(body, text="Write the description with an AI…", command=self.ai_write)
            ab.pack(anchor="w", pady=6)
            tip(ab, "Builds a prompt (this module's facts + the descriptions of similar modules) to paste into any AI; paste its answer back and it is put into both descriptions.")

    def _own_text_button(self, body, tag, what):
        b = ttk.Button(body, text="Edit the %s: make my own copy in the mod…" % what, command=lambda: self.own_text(tag, what))
        b.pack(anchor="w", pady=(2, 6))
        tip(b, "Adds a new entry to the mod's GameText with a copy of the base game's %s and points this %s at it. The base game is not touched." % (what, self.THING))

    def own_text(self, tag, what):
        p = self.proj
        if not p.text:
            messagebox.showwarning("No mod text file", "This mod has no GameText.yaml to add the text to.")
            return
        shown = p.text_display(self.m, tag)
        eng = shown.get("ENG").strip() if shown is not None else ""
        uid = re.sub(r"[^\w.\-]", "_", self.uid) or "Item"
        e = p.text.add_entry("%s_%s" % (uid, "Name" if what == "name" else "Desc"), p.next_text_id(), eng)
        self.m.set(tag, str(e.id))
        p.rebuild_maps()
        self.app.refresh()
        self.app.say("New mod text Id %d for the %s of %s. Save (Ctrl+S) to write it." % (e.id, what, self.uid))
        self.after_idle(self._reopen)

    def ai_write(self):
        ex = ai_style_examples(self.proj, self.m)
        limit = int(max([len(e) for e in ex] + [120]) * 1.3)

        def apply(t):
            for obj, tag in ((self.m, "Description"), (self.desc_e, "ENG")):
                if obj is not None:
                    ok, msg = try_set(obj, tag, t)
                    if msg:
                        messagebox.showwarning("Not applied", msg)
            self.app.refresh()
            self.app.say("Description changed. Save (Ctrl+S) to write it.")
        d = AiTextDialog(self, "Write a description - %s" % module_name(self.proj, self.m), "Write the short in-game description of this ship module.",
                         ai_about(self.proj, "module", self.m), ex, apply, "Use as the description", limit)
        self.wait_window(d)

    def _switches(self):
        """{(source, tag)} of true / false tags always listed as an ON / OFF switch, even when the file does not have them yet."""
        if self.THING == "building":
            return {("M", t) for t in BUILDING_SWITCHES}
        return {("W", t) for t in WEAPON_SWITCHES} if self.w is not None else set()

    def _listed(self):
        """{(source, tag)} shown on the tabs even when the file does not have them yet (empty box: type a value to add the tag)."""
        out = set(self._switches())
        for _title, secs in self.GROUPS:
            for _st, spec in secs:
                if not callable(spec):
                    out.update((s_, t) for s_, t in spec if self.THING == "building" or (s_ == "W" and self.w is not None))
        if self.THING == "building":
            out.update(("M", t) for t in self.BUILDING_KNOWN)
        return out

    def _resolve(self, spec, used):
        spec = spec(self) if callable(spec) else spec
        out = []
        sw = self._listed()
        for src, tag in spec:
            obj = self.m if src == "M" else self.w
            if obj is not None and (tag in obj.cur or (src, tag) in sw) and (src, tag) not in used:
                used.add((src, tag))
                out.append((obj, tag))
        return out

    def _group_tab(self, title, sections, used):
        resolved = [(t, self._resolve(spec, used)) for t, spec in sections]
        damage = title.startswith("Damage")
        real = [t for _s, f in resolved for o, t in f if t != "FieldOfFire" and t in o.cur]       # a field of fire alone does not make a weapon tab
        research = title in ("Cost & Rules", "Fitting & Ships")
        if research and self._techs():
            real.append("research")
        if self.THING == "building":
            real.append("fields")                                # every building tab is always listed, with all its tags (weapon tabs too)
        if not real and not (damage and self.w is None and self.m.get("WeaponType").strip()):
            return                                               # nothing of this kind on this %s: no empty tab
        body = self._tab(title)
        if self.THING == "building" and self.w is None and title.startswith(("Damage", "Weapon:")):
            self._weapon_link(body)
            return
        if damage:
            if self.w is None:
                self._note(body, "No weapon is linked to this module (its WeaponType is empty or there is no matching file in the Weapons folder).")
            else:
                users = self.proj.weapon_users.get((self.w.get("UID") or self.w.path.stem).strip().lower(), [])
                if len(users) > 1:
                    self._note(body, "This weapon file is shared by %d modules - changes here affect all of them." % len(users), EDITED_FG)
        for sec_title, fields in resolved:
            if fields:
                self._section(body, sec_title, fields)
        if research:
            ts = self._techs()
            if ts:
                self._section_title(body, "Research that unlocks it")
                grid = tk.Frame(body, bg=BG)
                grid.pack(fill="x")
                for i, t in enumerate(ts[:8]):
                    self._field(grid, i, 0, t, "Cost", "Research cost  (%s)" % short(module_name(self.proj, t), 34))
                self._note(body, "This is the Cost of the technology file that unlocks it, so it changes the whole tech, "
                                 "and everything else that tech unlocks%s." % ("" if len(ts) < 2 else " (%d techs unlock it - each is listed)" % len(ts)))

    def _weapon_link(self, body):
        cur = self.m.get("Weapon").strip()
        self._note(body, ("This building's <Weapon> is '%s', but no file with that UID is in the Weapons folders." % cur) if cur else
                   "This building has no weapon. Give it one and it fires it into space (the weapon's damage, range and look are then edited here).")
        b = ttk.Button(body, text="Choose a weapon for this building…", command=self.pick_weapon)
        b.pack(anchor="w", pady=6)
        tip(b, "Sets the building's <Weapon> tag to the weapon file you pick. Many buildings can share one weapon file: edits to it affect them all.")

    def pick_weapon(self):
        p = self.proj
        uids = sorted({(w.get("UID") or w.path.stem).strip() for w in list(p.weapons) + list(p.base_weapons)}, key=str.lower)
        pick = ask_choice(self, "Weapon", "Choose the weapon this building fires (or type a weapon UID):", uids)
        if not pick:
            return
        pick = pick.strip()
        ok, msg = try_set(self.m, "Weapon", pick)
        if msg:
            messagebox.showwarning("Not applied", msg)
        self.app.refresh()
        self.app.say("Weapon of %s set to %s. Save (Ctrl+S) to write it." % (self.uid, pick))
        self.after_idle(self._reopen)

    def _other_tab(self, used):
        body = self._tab("Everything else")
        for src, obj, title in (("M", self.m, "Other module fields"), ("W", self.w, "Other weapon fields")):
            if obj is None:
                continue
            fields = self._resolve([(src, t) for t in obj.cur], used)
            if fields:
                self._section(body, title, fields)

    # ---- widgets
    def _section_title(self, body, text):
        tk.Label(body, text=text.upper(), bg=BG, fg=ORANGE, font=("Segoe UI", 10, "bold"),
                 anchor="w").pack(fill="x", pady=(12, 4))

    def _section(self, body, title, fields):
        self._section_title(body, title)
        grid = tk.Frame(body, bg=BG)
        grid.pack(fill="x")
        for i, (obj, tag) in enumerate(fields):
            r, c = divmod(i, 2)
            self._field(grid, r, c, obj, tag, tag + ("   (weapon)" if obj is self.w else ""))

    def _field(self, grid, row, col, obj, tag, label, width=None):
        absent = tag not in obj.cur
        is_sw = (("M" if obj is self.m else "W"), tag) in self._switches()
        dflt = ("true" if (self.THING == "building" and tag in SWITCH_DEFAULT_TRUE) else "false") if is_sw else ""
        value = dflt if absent else obj.get(tag)
        lab = tk.Label(grid, text=label, bg=BG, fg=EDITED_FG if obj.changed(tag) else FG, anchor="w")
        lab.grid(row=row, column=col * 2, sticky="w", padx=(0, 10), pady=3)
        ro = obj.ro(tag)
        var = tk.StringVar(value=value.strip().lower() if value.strip().lower() in ("true", "false") else value)

        def commit(_e=None):
            if self._busy or ro:
                return
            new = var.get()
            if new == (dflt if tag not in obj.cur else obj.get(tag)):
                return
            self._busy = True
            try:
                ok, msg = try_set(obj, tag, new)
                var.set(obj.get(tag) if tag in obj.cur else dflt)
                if msg:
                    messagebox.showwarning("Not applied", msg)
                lab.configure(fg=EDITED_FG if obj.changed(tag) else FG)
                self.app.refresh()
            finally:
                self._busy = False
        host = None
        if not ro and value.strip().lower() in ("true", "false"):
            w = make_switch(grid, var, commit)
        else:
            numeric = (not ro) and bool(NUM_RE.match(value.strip())) and tag not in ("UID", "Version") and not tag.endswith(("Index", "Id", "ID"))
            if numeric:
                host = tk.Frame(grid, bg=BG)
                w = ttk.Entry(host, textvariable=var, width=width or 12)
            else:
                w = ttk.Entry(grid, textvariable=var, width=width or (16 if len(value) <= 16 else min(48, len(value) + 2)))
            if ro:
                w.state(["readonly"])
            else:
                w.bind("<Return>", commit)
                w.bind("<FocusOut>", commit)
            if numeric:
                w.pack(side="left")
                try:
                    self._scale(host, obj, tag, var, commit).pack(side="left", padx=(8, 0))
                except Exception:
                    pass
        (host or w).grid(row=row, column=col * 2 + 1, sticky="w", padx=(0, 30), pady=3)
        tip(lab, lambda: field_tip(obj, tag))

        def after():
            try:
                lab.configure(fg=EDITED_FG if obj.changed(tag) else FG)
            except tk.TclError:
                pass
            if tag not in obj.cur:                                   # the tag was deleted: show the tab without it
                self.after_idle(self._reopen)
        self.app.attach_field_menu(w, obj, tag, var.set, after)

    def _tag_values(self, obj, tag):
        """Sorted numbers this tag has in the files of the same kind (modules: the same ModuleType when there are enough), cached."""
        p = self.proj
        cache = p.__dict__.setdefault("_tag_stats", {})
        if self.THING == "building":
            kind, docs = "b", list(p.buildings) + list(p.base_buildings)
        elif obj is self.w:
            kind, docs = "w", list(p.weapons) + list(p.base_weapons)
        else:
            mt = (self.m.get("ModuleType") or "").strip()
            kind, docs = "m:" + mt, [d for d in list(p.modules) + list(p.base_modules) if (d.get("ModuleType") or "").strip() == mt]
        key = (kind, tag, len(docs))
        if key not in cache:
            vals = []
            for d in docs:
                v = (d.get(tag) or "").strip()
                if v and NUM_RE.match(v):
                    vals.append(float(v))
            if len(vals) < 5 and kind.startswith("m:"):                       # too few of this module type: use every module
                vals = [float(d.get(tag).strip()) for d in list(p.modules) + list(p.base_modules) if NUM_RE.match((d.get(tag) or "").strip())]
            cache[key] = sorted(vals)
        return cache[key]

    def _scale(self, parent, obj, tag, var, commit):
        """A small ruler under a number: the spread of this tag in the other files (bars), the typical value (line) and this value (orange marker)."""
        return value_scale(parent, self._tag_values(obj, tag), var, commit, tag)

    def _text_box(self, body, label, obj, tag, height):
        self._section_title(body, label)
        t = tk.Text(body, wrap="word", height=height, undo=True, **TEXT_OPTS)
        t.insert("1.0", obj.get(tag))
        t.pack(fill="x")

        def commit(_e=None):
            if self._busy:
                return
            new = t.get("1.0", "end-1c")
            if new == obj.get(tag):
                return
            self._busy = True
            try:
                ok, msg = try_set(obj, tag, new)
                if msg:
                    messagebox.showwarning("Not applied", msg)
                self.app.refresh()
            finally:
                self._busy = False
        t.bind("<FocusOut>", commit)
        self.app.attach_field_menu(t, obj, tag, lambda v: (t.delete("1.0", "end"), t.insert("1.0", v)))

    def _toggle_cmp(self):
        self.app.toggle_compare(self.uid)
        self._sync_cmp()

    def _sync_cmp(self):
        self.cmp_btn.configure(text="★  Tagged for compare" if self.uid in self.app.compare_uids
                               else "☆  Tag for compare")

    # ---- add / remove tags
    BUILDING_KNOWN = ("NoRandomSpawn", "AllowShipBuilding", "ShortDescriptionIndex", "ResourceCreated", "ResourceConsumed", "ConsumptionPerTurn",
                      "OutputPerTurn", "CommodityRequired", "IsCommodity", "ShowOnPlanetList", "WinsGame", "BuildOnlyOnce", "EventOnBuild",
                      "EventTriggerUID", "EventSpawnChance", "CanBuildAnywhere", "PlusTerraformPoints", "PlusProdPerRichness",
                      "PlanetaryShieldStrengthAdded", "PlusFlatPopulation", "MaxFertilityOnBuild", "Strength", "Scrappable", "Unique", "Weapon",
                      "WeaponTimer", "AttackTimer", "AvailableAttackActions", "CombatStrength", "SoftAttack", "HardAttack", "Defense",
                      "PlusTaxPercentage", "AllowInfantry", "Maintenance", "Income", "Cost", "StorageAdded", "PlusResearchPerColonist",
                      "ExcludesPlanetType", "PlusFlatResearchAmount", "CreditsPerColonist", "PlusFlatFoodAmount", "PlusFoodPerColonist",
                      "MaxPopIncrease", "PlusProdPerColonist", "PlusFlatProductionAmount", "SensorRange", "ShipRepair", "Category", "IsPlayerAdded",
                      "InvadeInjurePoints", "DefenseShipsCapacity", "DefenseShipsRole", "Infrastructure", "DetectsRemnantFleet", "CannotBeBombed",
                      "IncreaseRichness", "FoodCache", "ProdCache", "CanBeCreatedFromLava", "ImmueToLava", "CanBeTerraformed")

    def _reopen(self):
        try:
            self.tech._tab_memory = self.nb.index(self.nb.select())
        except Exception:
            self.tech._tab_memory = None
        self.tech.open_module(self.m)

    def _addable(self):
        """{label: (object, tag, typical value)} for every tag this file could have but does not."""
        p = self.proj
        where = {}
        for title, secs in self.GROUPS:
            for st, spec in secs:
                if not callable(spec):
                    for src, t in spec:
                        where.setdefault((src, t), "%s > %s" % (title, st))
        if self.THING == "building":
            docs = {"M": list(p.buildings) + list(p.base_buildings), "W": list(p.weapons) + list(p.base_weapons)}
            for t in self.BUILDING_KNOWN:
                where.setdefault(("M", t), "other")
        else:
            docs = {"M": list(p.modules) + list(p.base_modules), "W": list(p.weapons) + list(p.base_weapons)}
        skip = {"UID", "Name", "NameIndex", "NameTranslationIndex", "DescriptionIndex", "Version", "WeaponType"}
        out = {}
        for src, obj in (("M", self.m), ("W", self.w)):
            if obj is None:
                continue
            tags = [t for (sr, t) in where if sr == src] + [t for d in docs.get(src, []) for t in d.cur]
            for t in dict.fromkeys(tags):
                if t in obj.cur or t in skip or obj.ro(t) or (src, t) in self._listed():
                    continue
                vals = collections.Counter(d.cur.get(t, "").strip() for d in docs.get(src, []) if d.cur.get(t, "").strip())
                typ = vals.most_common(1)[0][0] if vals else "0"
                out["%s   [%s]%s" % (t, where.get((src, t), "seen in other files"), "  (weapon file)" if src == "W" else "")] = (obj, t, typ)
        return out

    def add_tag(self):
        cands = self._addable()
        pick = ask_choice(self, "Add a tag", "Choose a tag this %s does not have yet (or type its exact name; tag names are case-sensitive):" % self.THING,
                          sorted(cands, key=str.lower))
        if not pick:
            return
        if pick in cands:
            obj, tag, typ = cands[pick]
        else:
            tag = pick.split()[0]
            if not re.fullmatch(r"[A-Za-z_]\w*", tag):
                messagebox.showwarning("Not applied", "A tag name is letters, digits and _ only (and starts with a letter).")
                return
            obj = self.w if (self.w is not None and tag.startswith(("Tag_", "Excludes"))) else self.m
            if tag in obj.cur:
                messagebox.showinfo("Add a tag", "<%s> is already in this file: it is on one of the tabs." % tag)
                return
            typ = "0"
        val = self.app.line_dialog("value of <%s>" % tag, typ)
        if val is None:
            return
        ok, msg = try_set(obj, tag, val) if tag in obj.cur else (True, None)
        if tag not in obj.cur:
            obj.set(tag, val.strip())
        if msg:
            messagebox.showwarning("Not applied", msg)
        self.app.refresh()
        self.app.say("Added <%s> = %s. Save (Ctrl+S) to write it." % (tag, val.strip()))
        self.after_idle(self._reopen)

    def revert(self):
        self._row().revert_all()
        self.app.refresh()
        self.tech.open_module(self.m)

    def to_default(self):
        n = self._row().set_default_all()
        self.app.refresh()
        self.app.say("Set %d value(s) of %s to default." % (n, self.uid))
        self.tech.open_module(self.m)


BUILDING_IDENTITY = ("UID", "Name", "NameTranslationIndex", "DescriptionIndex", "ShortDescriptionIndex", "Version", "Icon")


def _weapon_only(titles):
    out = []
    for title, secs in ModuleEditor.GROUPS:
        if title in titles:
            keep = [(st, sp) for st, sp in secs if callable(sp) or any(s == "W" for s, _t in sp)]
            keep = [(st, sp if callable(sp) else [(s, t) for s, t in sp if s == "W"]) for st, sp in keep]
            out.append(("Weapon: " + title if title.startswith("Look") else title, keep))
    return out


class BuildingEditor(ModuleEditor):
    """The module editor's screen for a building: text, cost and rules, economy, population, defence - every field editable, no sub-tables.
    The field list is the game's own Building class (Ship_Game/Building.cs, TeamStarDrive/StarDrive); a tag it does not know is sorted by its name."""
    GROUPS = [
        ("Cost & Rules", [
            ("Cost", [("M", "Cost"), ("M", "Maintenance"), ("M", "Icon")]),
            ("Rules", [("M", "Scrappable"), ("M", "Unique"), ("M", "BuildOnlyOnce"), ("M", "CanBuildAnywhere"), ("M", "CannotBeBombed"), ("M", "NoRandomSpawn"), ("M", "AllowShipBuilding"), ("M", "AllowInfantry"), ("M", "IsCommodity"), ("M", "CommodityRequired"), ("M", "ShowOnPlanetList"), ("M", "WinsGame"), ("M", "IsPlayerAdded"), ("M", "ExcludesPlanetType"), ("M", "Category")]),
            ("Events", [("M", "EventOnBuild"), ("M", "EventTriggerUID"), ("M", "EventSpawnChance")]),
            ("Other rules and requirements", lambda ed: [("M", t) for t in ed.m.cur if re.search(r"^(Can|Is|Only|Build|Needs?|Requires?|Allow|Unique|Scrap|Cannot|Not|Category)", t) and t not in BUILDING_IDENTITY]),
        ]),
        ("Economy", [
            ("Production & food", [("M", "PlusFlatProductionAmount"), ("M", "PlusProdPerColonist"), ("M", "PlusProdPerRichness"), ("M", "PlusFlatFoodAmount"), ("M", "PlusFoodPerColonist"), ("M", "FoodCache"), ("M", "ProdCache")]),
            ("Research & money", [("M", "PlusFlatResearchAmount"), ("M", "PlusResearchPerColonist"), ("M", "Income"), ("M", "CreditsPerColonist"), ("M", "PlusTaxPercentage"), ("M", "StorageAdded")]),
            ("Resources made and used", [("M", "ResourceCreated"), ("M", "ResourceConsumed"), ("M", "OutputPerTurn"), ("M", "ConsumptionPerTurn")]),
            ("Other economy fields", lambda ed: [("M", t) for t in ed.m.cur if re.search(r"(Plus|Prod|Food|Research|Income|Credit|Tax|Storage|Commodit|Resource|Flat|PerColonist)", t) and t not in BUILDING_IDENTITY]),
        ]),
        ("Population & Planet", [
            ("Population", [("M", "MaxPopIncrease"), ("M", "PlusFlatPopulation"), ("M", "Infrastructure")]),
            ("Land & terraforming", [("M", "MaxFertilityOnBuild"), ("M", "IncreaseRichness"), ("M", "PlusTerraformPoints"), ("M", "CanBeTerraformed"), ("M", "CanBeCreatedFromLava"), ("M", "ImmueToLava")]),
            ("Other population and land fields", lambda ed: [("M", t) for t in ed.m.cur if re.search(r"(Pop|Fertil|Richness|Infrastructure|Terraform|Lava)", t) and t not in BUILDING_IDENTITY]),
        ]),
        ("Defence & Ships", [
            ("Planetary defence", [("M", "Strength"), ("M", "CombatStrength"), ("M", "SoftAttack"), ("M", "HardAttack"), ("M", "Defense"), ("M", "InvadeInjurePoints"), ("M", "PlanetaryShieldStrengthAdded")]),
            ("Building weapon", [("M", "Weapon"), ("M", "WeaponTimer"), ("M", "AttackTimer"), ("M", "AvailableAttackActions")]),
            ("Ships & sensors", [("M", "DefenseShipsCapacity"), ("M", "DefenseShipsRole"), ("M", "ShipRepair"), ("M", "SensorRange"), ("M", "DetectsRemnantFleet")]),
            ("Other defence, ship and troop fields", lambda ed: [("M", t) for t in ed.m.cur if re.search(r"(Strength|Attack|Defen|Weapon|Shield|Ship|Sensor|Repair|Troop|Combat|Damage|Range|Fire|Hull|Remnant)", t) and t not in BUILDING_IDENTITY]),
        ]),
    ]
    GROUPS = GROUPS + _weapon_only(("Damage, Effects & Ammo", "Look & Sound"))      # a building that fires a weapon gets the weapon's tabs
    NAME_IDX, DESC_IDX, INLINE_DESC, THING = "NameTranslationIndex", "DescriptionIndex", False, "building"

    def _find_weapon(self):
        """Some buildings fire a weapon into space: their <Weapon> tag names a file in the Weapons folder."""
        return self.proj.weap.get(self.m.get("Weapon").strip().lower()) if self.m.get("Weapon").strip() else None

    def _icon_path(self):
        return self.proj.building_pic(self.m)

    def _techs(self):
        n = self.m.get("Name").strip()
        return [t for t in self.proj.techs if n and n in t.buildings]

    def _row(self):
        return BuildingRow(self.proj, self.m)

    def _goto(self):
        self.tech.open_in_table(self.m)

    def _subtitle(self):
        return self.uid + "    ·    " + building_category(self.m) + ("    ·    base game (a copy goes into the mod when you save)" if getattr(self.m, "vanilla", False) else "")


# ---- charts: drawn straight onto a tk.Canvas (no extra libraries needed)
FONT = ("Segoe UI", 9)
MOD_COLORS = [ORANGE, BLUE, PURPLE, "#7fd18b", "#e06c6c", "#e0d36c", PEACH, "#6ce0d6"]
TIER_COLORS = ["#6c8cff", BLUE, "#7fd18b", "#e0d36c", ORANGE, "#e06c6c", PURPLE, PEACH, "#6ce0d6"]
NL = chr(10)


def tier_color(t):
    return DIM if t is None else TIER_COLORS[int(t) % len(TIER_COLORS)]


def clip(text, n):
    return text if len(text) <= n else text[:n - 1] + "…"


def draw_message(cv, w, h, text):
    cv.create_text(w / 2.0, h / 2.0, text=text, fill=DIM, font=("Segoe UI", 11), width=w - 80, justify="center")
    return []


def draw_legend(cv, items, x, y, wmax):
    cx, cy = x, y
    for color, text in items:
        tw = 26 + len(text) * 6
        if cx + tw > wmax and cx > x:
            cx, cy = x, cy + 16
        cv.create_rectangle(cx, cy, cx + 10, cy + 10, fill=color, outline="")
        cv.create_text(cx + 15, cy + 5, text=text, anchor="w", fill=FG, font=FONT)
        cx += tw
    return cy + 16


def draw_cartesian(cv, w, h, kind, labels, tiers, series, norm, show_vals, trend, title, tech_order, icons=None):
    """Bar or line chart: one position per module (in the chosen order), one bar/line per ticked field.
    Every bar / point / icon is registered in cv.drags so it can be dragged up and down to edit the value."""
    notes = []
    n = len(labels)
    data = []
    for name, raw in series:
        big = max([v for v in raw if v is not None and v > 0] or [0])
        f = (100.0 / big) if (norm and big) else 1.0
        data.append((name, raw, [None if v is None else v * f for v in raw], f))
    allv = [v for d in data for v in d[2] if v is not None]
    if not n or not allv:
        return draw_message(cv, w, h, "No numeric values for this selection. Tick a field in the list on the right.")
    cv.create_text(16, 14, text=title, anchor="w", fill=ORANGE, font=("Segoe UI", 11, "bold"))
    if len(data) > 1:
        items = [(MOD_COLORS[j % len(MOD_COLORS)], d[0]) for j, d in enumerate(data)]
    else:
        items = [(tier_color(t), "Tier %d" % t) for t in sorted({t for t in tiers if t is not None})]
    ly = draw_legend(cv, items, 16, 30, w - 20)
    x0, y0, x1 = 80, ly + 10, w - 24
    y1 = h - (84 if n > 5 else 60)
    lo, hi = min(allv), max(allv)
    if kind == "Bar":
        lo = min(0, lo)
    else:
        pad = (hi - lo) * 0.1 or 1.0
        lo, hi = (max(0, lo - pad) if lo >= 0 else lo - pad), hi + pad
    if icons:
        hi += (hi - lo) * 0.2                    # headroom for the icons above the bars / points
    ticks = nice_ticks(lo, hi)
    if cv.freeze and "y" in cv.freeze:           # while dragging the axis stays put, so the bar follows the mouse
        ticks = cv.freeze["y"]
    else:
        cv.axes["y"] = ticks
    bot, topt = ticks[0], ticks[-1]
    span = float(topt - bot) or 1.0

    def ymap(v):
        return min(y1, max(y0 - 8, y1 - (v - bot) / span * (y1 - y0)))

    def upp(f):                                  # raw value change per pixel
        return span / max(1.0, y1 - y0) / (f or 1.0)
    unit = "%" if norm else ""
    for t in ticks:
        cv.create_line(x0, ymap(t), x1, ymap(t), fill=EDGE)
        cv.create_text(x0 - 8, ymap(t), text=fmtv(t) + unit, anchor="e", fill=DIM, font=FONT)
    base = ymap(max(bot, 0))
    cv.create_line(x0, y0, x0, y1, fill=DIM)
    cv.create_line(x0, base, x1, base, fill=DIM)
    slot = (x1 - x0) / float(n)
    k = len(data)
    for i, lab in enumerate(labels):
        cx = x0 + slot * (i + 0.5)
        if n > 5:
            cv.create_text(cx + 4, y1 + 8, text=clip(lab, 20), anchor="ne", angle=35, fill=FG, font=FONT)
        else:
            cv.create_text(cx, y1 + 8, text=clip(lab, 30), anchor="n", fill=FG, font=FONT,
                           width=max(60, slot - 8), justify="center")
    pos, tops = {}, {}
    if kind == "Bar":
        bw = slot * 0.74 / k
        for j, (name, raw, sc, f) in enumerate(data):
            for i, v in enumerate(sc):
                if v is None:
                    continue
                xa, ya = x0 + slot * (i + 0.13) + bw * j, ymap(v)
                col = tier_color(tiers[i]) if k == 1 else MOD_COLORS[j % len(MOD_COLORS)]
                it = cv.create_rectangle(xa, min(ya, base), xa + bw - 1, max(ya, base), fill=col, outline="")
                cv.tips[it] = "%s%s%s: %s%sdrag up / down to change it" % (labels[i], NL, name, fmtv(raw[i]), NL)
                cv.drags[it] = (j, i, raw[i], upp(f))
                pos[(j, i)] = (xa + bw / 2.0, ya)
                tops[i] = min(tops.get(i, 1e9), ya, base)
                if show_vals and bw > 24:
                    cv.create_text(xa + bw / 2.0, min(ya, base) - 9, text=fmtv(raw[i]), fill=FG, font=FONT)
        for i, ytop in tops.items():
            if icons and icons[i] is not None:
                tip = labels[i] + NL + NL.join("%s: %s" % (d[0], fmtv(d[1][i])) for d in data)
                it = cv.create_image(x0 + slot * (i + 0.5), ytop - (22 if show_vals and bw > 24 else 6),
                                     image=icons[i], anchor="s")
                cv.tips[it] = tip
                if k == 1 and data[0][1][i] is not None:       # one field only: the icon is a handle too
                    cv.drags[it] = (0, i, data[0][1][i], upp(data[0][3]))
    else:
        for j, (name, raw, sc, f) in enumerate(data):
            col = MOD_COLORS[j % len(MOD_COLORS)]
            pts = [(x0 + slot * (i + 0.5), ymap(v), i) for i, v in enumerate(sc) if v is not None]
            if len(pts) > 1:
                cv.create_line(*[c for p in pts for c in p[:2]], fill=col, width=2)
            for px, py, i in pts:
                ic = icons[i] if icons else None
                ring = tier_color(tiers[i]) if k == 1 else col
                tip = "%s%s%s: %s%sdrag up / down to change it" % (labels[i], NL, name, fmtv(raw[i]), NL)
                if ic is not None:
                    its = [cv.create_oval(px - 17, py - 17, px + 17, py + 17, fill=PANEL2, outline=ring, width=2),
                           cv.create_image(px, py, image=ic)]
                else:
                    its = [cv.create_oval(px - 5, py - 5, px + 5, py + 5, outline=BG, width=2, fill=ring)]
                for it in its:
                    cv.tips[it] = tip
                    cv.drags[it] = (j, i, raw[i], upp(f))
                pos[(j, i)] = (px, py)
                if show_vals:
                    cv.create_text(px, py - (24 if ic is not None else 13), text=fmtv(raw[i]), fill=FG, font=FONT)
    if trend:
        for j, (name, raw, sc, f) in enumerate(data):
            fit = trend_fit(tiers, raw)
            if not fit:
                notes.append("%s: a trend needs 3+ modules spread over 2+ tech levels." % name)
                continue
            a, b, sd, res = fit
            notes.append("%s: trend %s per tech level" % (name, "%+.3g" % b))
            line = []
            for i, y, pred in res:
                yy, xc = ymap(pred * f), x0 + slot * (i + 0.5)
                cv.create_line(xc - slot * 0.4, yy, xc + slot * 0.4, yy, fill=FG, dash=(3, 2))
                line += [xc, yy]
            if tech_order and len(line) >= 4:
                cv.create_line(*line, fill=FG, dash=(4, 4))
            if len(res) >= 4:
                for i, y, pred in res:
                    if pred and abs(y - pred) > sd and abs(y - pred) > 0.1 * abs(pred) and (j, i) in pos:
                        px, py = pos[(j, i)]
                        rr = 21 if (icons and icons[i] is not None) else 10
                        cv.create_oval(px - rr, py - rr, px + rr, py + rr, outline="#e06c6c", width=2)
                        notes.append("%s · %s: %+.0f%% vs the tier trend" % (labels[i], name, (y - pred) / abs(pred) * 100))
    notes.append("Drag a bar / point / icon up or down to edit its value (speed: see 'Drag speed'; Shift = finer, Ctrl = coarser; right-click for more).")
    return notes


def draw_scatter(cv, w, h, labels, tiers, xs, ys, sizes, xname, yname, show_labels, trend, icons=None):
    notes = []
    pts = [(i, x, y) for i, (x, y) in enumerate(zip(xs, ys)) if x is not None and y is not None]
    if not pts:
        return draw_message(cv, w, h, "No tagged module has a number for both axes.")
    cv.create_text(16, 14, text="%s  vs  %s" % (yname, xname), anchor="w", fill=ORANGE, font=("Segoe UI", 11, "bold"))
    items = [(tier_color(t), "Tier %d" % t) for t in sorted({tiers[i] for i, _x, _y in pts if tiers[i] is not None})]
    ly = draw_legend(cv, items, 16, 30, w - 20)
    x0, y0, x1, y1 = 84, ly + 10, w - 30, h - 56

    def axis(vals):
        lo, hi = min(vals), max(vals)
        pad = (hi - lo) * 0.12 or (abs(hi) * 0.1 or 1.0)
        return nice_ticks(max(0, lo - pad) if lo >= 0 else lo - pad, hi + pad)
    tx, ty = axis([p[1] for p in pts]), axis([p[2] for p in pts])
    if cv.freeze and "sx" in cv.freeze:
        tx, ty = cv.freeze["sx"], cv.freeze["sy"]
    else:
        cv.axes["sx"], cv.axes["sy"] = tx, ty
    sx, sy = float(tx[-1] - tx[0]) or 1.0, float(ty[-1] - ty[0]) or 1.0

    def xmap(v):
        return min(x1, max(x0, x0 + (v - tx[0]) / sx * (x1 - x0)))

    def ymap(v):
        return min(y1, max(y0 - 8, y1 - (v - ty[0]) / sy * (y1 - y0)))
    upp_y = sy / max(1.0, y1 - y0)
    for t in tx:
        cv.create_line(xmap(t), y0, xmap(t), y1, fill=EDGE)
        cv.create_text(xmap(t), y1 + 6, text=fmtv(t), anchor="n", fill=DIM, font=FONT)
    for t in ty:
        cv.create_line(x0, ymap(t), x1, ymap(t), fill=EDGE)
        cv.create_text(x0 - 8, ymap(t), text=fmtv(t), anchor="e", fill=DIM, font=FONT)
    cv.create_line(x0, y0, x0, y1, fill=DIM)
    cv.create_line(x0, y1, x1, y1, fill=DIM)
    cv.create_text((x0 + x1) / 2.0, y1 + 30, text=xname, fill=PEACH, font=FONT)
    cv.create_text(20, (y0 + y1) / 2.0, text=yname, fill=PEACH, font=FONT, angle=90)
    sv = [sizes[i] for i, _x, _y in pts if sizes and sizes[i] is not None]
    smin, smax = (min(sv), max(sv)) if sv else (0, 0)
    for i, x, y in pts:
        s = sizes[i] if sizes else None
        r = 7 if (s is None or smax == smin) else 5 + 12 * (s - smin) / float(smax - smin)
        px, py = xmap(x), ymap(y)
        ic = icons[i] if icons else None
        if ic is not None:
            r += 11                              # icon sits inside a tier-coloured ring; bubble size still shows
        tip = "%s%s%s: %s%s%s: %s" % (labels[i], NL, xname, fmtv(x), NL, yname, fmtv(y))
        tip += (("%ssize: %s" % (NL, fmtv(s))) if s is not None else "")
        its = [cv.create_oval(px - r, py - r, px + r, py + r, width=2,
                              fill=PANEL2 if ic is not None else tier_color(tiers[i]),
                              outline=tier_color(tiers[i]) if ic is not None else BG)]
        if ic is not None:
            its.append(cv.create_image(px, py, image=ic))
        for it in its:
            cv.tips[it] = tip + NL + "drag up / down to change " + yname
            cv.drags[it] = (0, i, y, upp_y)
        if show_labels:
            cv.create_text(px + r + 4, py, text=clip(labels[i], 18), anchor="w", fill=FG, font=FONT)
    if trend:
        fit = trend_fit([p[1] for p in pts], [p[2] for p in pts])
        if not fit:
            notes.append("A trend needs 3+ modules with different X values.")
        else:
            a, b, sd, res = fit
            xa, xb = min(p[1] for p in pts), max(p[1] for p in pts)
            cv.create_line(xmap(xa), ymap(a + b * xa), xmap(xb), ymap(a + b * xb), fill=FG, dash=(4, 4))
            mean_y = sum(p[2] for p in pts) / float(len(pts))
            ss_tot = sum((p[2] - mean_y) ** 2 for p in pts)
            r2 = 1 - sum((y - pr) ** 2 for _i, y, pr in res) / ss_tot if ss_tot else 1.0
            notes.append("Trend: %s = %.3g + %.3g x %s   (R² %.2f)" % (yname, a, b, xname, r2))
            for k, y, pred in res:
                if len(res) >= 4 and pred and abs(y - pred) > sd and abs(y - pred) > 0.1 * abs(pred):
                    i, x, _y = pts[k]
                    cv.create_oval(xmap(x) - 13, ymap(y) - 13, xmap(x) + 13, ymap(y) + 13, outline="#e06c6c", width=2)
                    notes.append("%s: %+.0f%% vs the trend line" % (labels[i], (y - pred) / abs(pred) * 100))
    return notes


def draw_radar(cv, w, h, labels, series, title, icons=None):
    if len(series) < 3:
        return draw_message(cv, w, h, "Radar needs 3 or more ticked fields. Tick them in the list on the right.")
    n = len(series)
    cv.create_text(16, 14, text=title, anchor="w", fill=ORANGE, font=("Segoe UI", 11, "bold"))
    ly = draw_legend(cv, [(MOD_COLORS[i % len(MOD_COLORS)], lab) for i, lab in enumerate(labels)], 16, 30, w - 20)
    cx, cy = w / 2.0, (ly + h) / 2.0 + 6
    R = max(40.0, min(w / 2.0 - 130, (h - ly) / 2.0 - 40))
    big = [max([v for v in s[1] if v is not None and v > 0] or [0]) for s in series]

    def at(a, r):
        ang = -math.pi / 2 + 2 * math.pi * a / n
        return cx + r * math.cos(ang), cy + r * math.sin(ang)
    for ring in (0.25, 0.5, 0.75, 1.0):
        cv.create_polygon(*[c for a in range(n) for c in at(a, R * ring)], outline=EDGE, fill="")
    for a, (name, _raw) in enumerate(series):
        cv.create_line(cx, cy, *at(a, R), fill=EDGE)
        lx, ly2 = at(a, R + 16)
        cv.create_text(lx, ly2, text=clip(name, 22), fill=PEACH, font=FONT,
                       anchor="w" if lx > cx + 8 else ("e" if lx < cx - 8 else "s"))
    for mi, lab in enumerate(labels):
        col = MOD_COLORS[mi % len(MOD_COLORS)]
        pts = []
        for a, (name, raw) in enumerate(series):
            v = raw[mi]
            frac = 0.0 if (v is None or not big[a]) else max(0.0, v / big[a])
            px, py = at(a, R * frac)
            pts += [px, py]
            tip = "%s%s%s: %s" % (lab, NL, name, fmtv(v))
            if icons and icons[mi] is not None:
                cv.tips[cv.create_oval(px - 14, py - 14, px + 14, py + 14, fill=PANEL2, outline=col, width=2)] = tip
                cv.tips[cv.create_image(px, py, image=icons[mi])] = tip
            else:
                cv.tips[cv.create_oval(px - 4, py - 4, px + 4, py + 4, fill=col, outline=BG)] = tip
        cv.create_polygon(*pts, outline=col, fill="", width=2)
    return ["Each axis is scaled so the largest tagged value reaches the outer ring."]


class ChartCanvas(tk.Canvas):
    """Canvas for the compare charts. Items registered in self.drags can be dragged up / down: the callbacks
    on_press(j, i) -> bool, on_drag(j, i, raw_value, start_value) -> (label, value), on_release() and
    on_context(j, i, event) are supplied by the CompareView; gain() returns how much of the mouse movement counts."""

    def __init__(self, master):
        super().__init__(master, bg=PANEL, highlightthickness=0)
        self.paint, self.tips, self.notes, self._job = None, {}, [], None
        self.drags, self.axes, self.freeze, self.dstate = {}, {}, None, None
        self.on_press = self.on_drag = self.on_release = self.on_context = None
        self.gain = lambda: 0.12
        self.bind("<Configure>", self._resized)
        self.bind("<Motion>", self._motion)
        self.bind("<Leave>", lambda _e: self.delete("tip"))
        self.bind("<ButtonPress-1>", self._press)
        self.bind("<B1-Motion>", self._drag_move)
        self.bind("<ButtonRelease-1>", self._release)
        for b in ("<Button-3>", "<Button-2>") if sys.platform == "darwin" else ("<Button-3>",):
            self.bind(b, self._ctx)

    def set(self, painter):
        self.paint = painter
        self.redraw()

    def _resized(self, _e):
        if self._job:
            self.after_cancel(self._job)
        self._job = self.after(60, self.redraw)

    def destroy(self):
        if self._job:
            try:
                self.after_cancel(self._job)
            except Exception:
                pass
        super().destroy()

    def redraw(self):
        self._job = None
        self.delete("all")
        self.tips, self.drags = {}, {}
        if self.paint:
            self.notes = self.paint(self, max(320, self.winfo_width()), max(240, self.winfo_height())) or []

    def _items(self, e):
        return self.find_overlapping(e.x - 3, e.y - 3, e.x + 3, e.y + 3)

    def _hit_drag(self, e):
        return next((self.drags[i] for i in reversed(self._items(e)) if i in self.drags), None)

    def _motion(self, e):
        self.delete("tip")
        items = self._items(e)
        self.configure(cursor="sb_v_double_arrow" if any(i in self.drags for i in items) else "")
        text = next((self.tips[i] for i in reversed(items) if i in self.tips), None)
        if not text:
            return
        right = e.x > self.winfo_width() * 0.6
        t = self.create_text(e.x + (-14 if right else 14), e.y - 14, text=text, anchor="se" if right else "sw",
                             fill=FG, font=FONT, tags="tip", justify="left")
        bb = self.bbox(t)
        self.create_rectangle(bb[0] - 6, bb[1] - 4, bb[2] + 6, bb[3] + 4, fill=PANEL2, outline=ORANGE, tags="tip")
        self.tag_raise(t)

    # ---- dragging a value
    def _press(self, e):
        d = self._hit_drag(e)
        if not d or not self.on_press or not self.on_press(d[0], d[1]):
            return
        self.freeze = dict(self.axes)
        self.dstate = {"j": d[0], "i": d[1], "cur": d[2], "start": d[2], "upp": d[3], "y": e.y}
        self.delete("tip")
        self.configure(cursor="sb_v_double_arrow")

    def _drag_move(self, e):
        s = self.dstate
        if not s:
            return
        mod = 0.2 if e.state & 0x1 else (5.0 if e.state & 0x4 else 1.0)       # Shift = finer, Ctrl = coarser
        s["cur"] += (s["y"] - e.y) * s["upp"] * self.gain() * mod
        s["y"] = e.y
        label, s["cur"] = self.on_drag(s["j"], s["i"], s["cur"], s["start"])
        if label:
            t = self.create_text(e.x + 18, e.y - 18, text=label, anchor="sw", fill=FG, font=FONT, tags="tip", justify="left")
            bb = self.bbox(t)
            self.create_rectangle(bb[0] - 6, bb[1] - 4, bb[2] + 6, bb[3] + 4, fill=PANEL2, outline=ORANGE, tags="tip")
            self.tag_raise(t)

    def _release(self, _e):
        if not self.dstate:
            return
        self.dstate, self.freeze = None, None
        self.configure(cursor="")
        if self.on_release:
            self.on_release()

    def _ctx(self, e):
        d = self._hit_drag(e)
        if d and self.on_context:
            self.on_context(d[0], d[1], e)


def building_stats(proj, b):
    """[(label, value, edited, obj, tag)] for a building's numbers and ON switches (zero / empty / false ones are left out)."""
    order = [t for (_s, t) in BUILDING_ORDER if t in b.cur]
    rest = [t for t in b.cur if t not in order and t not in b.nested and t not in ("Name", "Icon", "NameTranslationIndex", "DescriptionIndex",
                                                                                   "ShortDescriptionIndex", "ShortDescription")]
    out = []
    for t in order + rest:
        if t in ("Name", "Icon"):
            continue
        v = b.get(t).strip()
        if t not in ("Cost", "Maintenance") and v.lower() in ("", "0", "0.0", "false"):
            continue
        out.append((t, SWITCH_ON if v.lower() == "true" else v, b.changed(t), b, t))
    return out


class BuildingTree(TechTree):
    """The Ship Modules tab's look for buildings: the game's categories down the left, hover one for the list (with the game's own
    icons), hover a building for its numbers, double-click a number to change it, click a building to find it in the table."""

    def items(self):
        p = self.proj
        return list(p.buildings) + (list(p.base_buildings) if p.settings.get("show_base", True) else [])

    def __init__(self, master, app):
        ttk.Frame.__init__(self, master)
        self.app, self.proj = app, app.proj
        self.cache, self.jobs = {}, set()
        self.cat_open = self.hover_m = self.hover_widgets = None
        self.pop_job = self.hide_job = self.poll_job = None
        self.out_count = 0
        self.cat_w = {}
        self.editor = self.stage_box = None
        self.editing = False
        self.races = None
        self.all_cats = {}
        for b in self.items():
            self.all_cats.setdefault(building_category(b), []).append(b)
        for lst in self.all_cats.values():
            lst.sort(key=lambda b: (sort_key(b.get("Cost")), module_name(self.proj, b).lower()))
        self.cats = dict(self.all_cats)
        self.bar = tk.Frame(self, bg=PANEL)
        self.bar.pack(side="top", fill="x")
        self.race_note = tk.Label(self.bar, bg=PANEL, fg=DIM, text="%d buildings (the base game's and this mod's)" % len(self.items()))
        self.race_note.pack(side="left", padx=12, pady=6)
        self.strip = tk.Frame(self, bg=PANEL, width=self.STRIP_W)
        self.strip.pack(side="left", fill="y")
        self.strip.pack_propagate(False)
        self.catlist = ScrollFrame(self.strip, bg=PANEL, scrollbar=False)
        self.catlist.pack(fill="both", expand=True)
        self.stage = tk.Frame(self, bg=BG)
        self.stage.pack(side="left", fill="both", expand=True)
        self.fly = tk.Frame(self, bg=PANEL2, highlightthickness=2, highlightbackground=ORANGE)
        hdr = tk.Frame(self.fly, bg=HOVER_BG)
        hdr.pack(fill="x")
        self.fly_cmp = tk.Label(hdr, bg=HOVER_BG, fg=PEACH, cursor="hand2", padx=10)
        self.fly_cmp.pack(side="right")
        tip(self.fly_cmp, "Open the Compare tab with the starred buildings")
        self.fly_cmp.bind("<Button-1>", lambda _e: self.go_compare())
        self.fly_title = tk.Label(hdr, bg=HOVER_BG, fg=ORANGE, font=("Segoe UI", 12, "bold"), anchor="w", padx=10, pady=6)
        self.fly_title.pack(side="left", fill="x", expand=True)
        self.list = ScrollFrame(self.fly, bg=PANEL2)
        self.list.pack(fill="both", expand=True)
        self._build_popup()
        self.pop_stats_hint = None
        self._build_strip()
        self._build_stage()

    def apply_race_filter(self):
        pass

    def refresh_icons(self):
        TechTree.refresh_icons(self)

    def _build_strip(self):
        for cat in sorted(self.cats, key=str.lower):
            path = None
            for b in self.cats[cat][:25]:
                path = self.proj.building_pic(b)
                if path:
                    break
            f = tk.Frame(self.catlist.inner, bg=PANEL, cursor="hand2")
            f.pack(fill="x", pady=1)
            il = tk.Label(f, image=self.icon(path, 44, cat), bg=PANEL)
            il.pack(pady=(8, 0))
            tl = tk.Label(f, text=cat, bg=PANEL, fg=PEACH, font=("Segoe UI", 8), wraplength=self.STRIP_W - 14)
            tl.pack(pady=(0, 8))
            self.cat_w[cat] = (f, il, tl)
            for w in (f, il, tl):
                w.bind("<Enter>", lambda _e, c=cat: self.show_cat(c))
                w.bind("<Button-1>", lambda _e, c=cat: self.show_cat(c, force=True))

    def _build_stage(self):
        blds = [b for bs in self.cats.values() for b in bs]
        found = sum(1 for b in blds if self.proj.building_pic(b))
        box = self.stage_box = tk.Frame(self.stage, bg=BG)
        box.place(relx=0.5, rely=0.42, anchor="center")
        tk.Label(box, text="BUILDINGS", bg=BG, fg=ORANGE, font=("Segoe UI", 30, "bold")).pack()
        tk.Label(box, text="Hover a category on the left  ›  hover a building for its numbers  ›  double-click a number to change it  ›  "
                           "click a building to find it in the table", bg=BG, fg=PEACH, font=("Segoe UI", 11), wraplength=620).pack(pady=(4, 16))
        tk.Label(box, text="%d buildings in %d categories   ·   icons found: %d of %d" % (len(blds), len(self.cats), found, len(blds)), bg=BG, fg=FG).pack()
        tk.Label(box, text="Icons come from the game's Textures\\Buildings (icon_<name>_64x64). Edit a base-game building and Save: "
                           "a copy goes into the mod.", bg=BG, fg=DIM, wraplength=620).pack(pady=(10, 0))

    def show_cat(self, cat, force=False):
        TechTree.show_cat(self, cat, force)

    def add_row(self, b):
        key = doc_key(b)
        edited = BuildingRow(self.proj, b).dirty()
        row = tk.Frame(self.list.inner, bg=PANEL2, cursor="hand2")
        row.pack(fill="x", padx=4, pady=1)
        tagged = key in self.app.compare_uids
        star = tk.Label(row, text="★" if tagged else "☆", bg=PANEL2, fg=ORANGE if tagged else DIM, font=("Segoe UI", 14), cursor="hand2", padx=4)
        star.pack(side="right")
        tip(star, "Tag / untag this building for the Compare tab")
        tl = tk.Label(row, text=b.get("Cost").strip() or "-", bg=PANEL2, fg=ORANGE)
        tl.pack(side="right", padx=8)
        tip(tl, "Cost")
        il = tk.Label(row, image=self.icon(self.proj.building_pic(b), 40, key), bg=PANEL2, width=44)
        il.pack(side="left", padx=(4, 6), pady=3)
        tf = tk.Frame(row, bg=PANEL2)
        tf.pack(side="left", fill="x", expand=True)
        nl = tk.Label(tf, text=module_name(self.proj, b), bg=PANEL2, fg=EDITED_FG if edited else FG, anchor="w")
        nl.pack(fill="x")
        ul = tk.Label(tf, text=key + ("" if not getattr(b, "vanilla", False) else "   · base game"), bg=PANEL2, fg=DIM, anchor="w", font=("Segoe UI", 8))
        ul.pack(fill="x")
        ws = (row, il, tf, nl, ul, tl, star)
        for w in ws:
            w.bind("<Enter>", lambda _e, b=b, ws=ws: self.item_enter(b, ws))
            w.bind("<Leave>", lambda _e: self.item_leave())
            if w is not star:
                w.bind("<Button-1>", lambda _e, b=b: self.open_module(b))
            for bn in ("<Button-3>", "<Button-2>"):
                w.bind(bn, lambda e, b=b: self.row_menu(b, e))
        star.bind("<Button-1>", lambda _e, k=key, st=star: self._toggle_star(k, st))

    def open_module(self, b):
        self.hide_fly()
        self.stage_box.place_forget()
        if self.editor:
            self.editor.destroy()
        self.editor = BuildingEditor(self.stage, self.app, self, b)
        self.editor.pack(fill="both", expand=True)

    def open_in_table(self, b):
        self.hide_fly()
        g = getattr(self.app, "bgrid", None)
        if g is None:
            return
        self.app.select_grid(g)
        g.q.set(doc_key(b))

    def _render_popup(self, b):
        p = self.proj
        key = doc_key(b)
        self.pop_img.configure(image=self.icon(p.building_pic(b), 150, key))
        self.pop_title["text"] = module_name(p, b)
        self.pop_sub["text"] = key
        self.pop_fits["text"] = "   ·   ".join(("Category: " + building_category(b), "Source: " + source_label(b)))
        e = p.text_display(b, "DescriptionIndex")
        desc = e.get("ENG").strip() if e else ""
        self.pop_desc.configure(text=desc or "(no description text)", fg=FG if desc else DIM)
        for c in self.pop_stats.winfo_children():
            c.destroy()
        for i, (label, val, edited, obj, tag) in enumerate(building_stats(p, b)):
            r, c = divmod(i, 2)
            lb = tk.Label(self.pop_stats, text=label, bg=PANEL, fg=DIM, anchor="w", cursor="hand2")
            lb.grid(row=r, column=c * 2, sticky="w", padx=(0, 8), pady=1)
            vl = tk.Label(self.pop_stats, text=val, bg=PANEL, fg=EDITED_FG if edited else FG, anchor="e", cursor="hand2")
            vl.grid(row=r, column=c * 2 + 1, sticky="e", padx=(0, 26), pady=1)
            for wdg in (lb, vl):
                wdg.bind("<Double-1>", lambda _e, lab=label, o=obj, t=tag: self.edit_target(lab, o, t))

    def edit_target(self, label, obj, tag, multiline=False):
        b = self.hover_m
        v = obj.get(tag).strip().lower()
        if v in ("true", "false"):                                         # a switch: flip it
            ok, msg = try_set(obj, tag, "false" if v == "true" else "true")
            if msg:
                messagebox.showwarning("Not applied", msg)
            self.app.refresh()
            if b is not None and self.hover_m is b:
                self._render_popup(b)
            return
        TechTree.edit_target(self, label, obj, tag, multiline)

    def edit_name(self, b):
        e = self.proj.text_for(b, "NameTranslationIndex") if b else None
        if e:
            self.edit_target("Name", e, "ENG")
        else:
            self.app.say("This building's name text belongs to the base game (read only here).")

    def edit_desc(self, b):
        e = self.proj.text_for(b, "DescriptionIndex") if b else None
        if e:
            self.edit_target("Description", e, "ENG", True)
        else:
            self.app.say("This building's description text belongs to the base game (read only here).")

    def edit_slot(self, b):
        pass


# ----------------------------------------------------------------------------------------------------------------------
# Balance: damage per tile of ship space, counting the power and ordnance support a weapon needs.
BAL_GROUPS = (("Point defence", "Tag_PD"), ("Beam", "Tag_Beam"), ("Torpedo", "Tag_Torpedo"), ("Missile", "Tag_Missile"),
              ("Plasma", "Tag_Plasma"), ("Cannon", "Tag_Cannon"), ("Kinetic", "Tag_Kinetic"), ("Explosive", "Tag_Explosive"),
              ("Energy", "Tag_Energy"))
BAL_ENERGY_TYPES = ("PowerPlant", "FuelCell")       # modules that supply power (PowerFlowMax per second + PowerStoreMax)
BAL_ORD_TYPES = ("Storage",)                         # modules that supply ordnance (OrdnanceAddedPerSecond + OrdinanceCapacity)
BAL_GUIDED_EVADE = 3.0     # a guided weapon steers after its target, so the target has this many times longer to dodge it
BAL_MODS = (   # (key, label, default weight, what it does)
    ("reach", "Reach", 1.0, "A weapon whose Range is shorter than the fight distance cannot hit at all (0); otherwise 1."),
    ("travel", "Travel time", 1.0, "ESTIMATE (the game has no single rule for this). Time to hit = distance / ProjectileSpeed (beams: 0). The longer the shot is in "
                                   "flight the more likely the target has moved: 1 / (1 + time / evasion time) (guided weapons: evasion time x 3), and the "
                                   "damage also arrives later in the fight: (fight length - time) / fight length."),
    ("pd", "Point defence", 1.0, "From the game: only point-defence weapons (Tag_PD / TruePD) shoot at shots tagged Tag_Intercept, and every hit takes the shot's "
                                 "HitPoints (x ProjectileHitpointsMultiplier in Globals.yaml) down. Survival = e ^ -(time in flight x point defence damage per "
                                 "second / HitPoints)."),
    ("mix", "Shields / armor / pen", 1.0, "From the game: a shot that meets shields does damage x EffectVsShields x (1 - the shield's resist for the weapon's type: "
                                          "explosive, plasma, kinetic, beam, energy); one that meets armor does damage x EffectVsArmor x (1 - the armor's resist). "
                                          "ShieldPenChance is the chance a shot skips the shields. A shot below the module's deflection value (ShieldDeflection / "
                                          "Deflection) does nothing (not beams, not plasma). The resists and deflection are the averages of the mod's real "
                                          "shield and armor modules available at the weapon's tech level."),
    ("spread", "Fire cone", 1.0, "From the game: each shot leaves at a random angle within FireCone degrees (not guided weapons, not beams). The chance it still "
                                 "hits a target of the set radius at the fight distance = 2 x atan(radius / distance) / FireCone."),
    ("splash", "Splash", 0.5, "ESTIMATE. Area damage: 1 + 0.5 x radius / (radius + 150), radius = DamageRadius or ExplosionRadius."),
    ("arc", "Firing arc", 0.5, "The game's own valuation (WeaponTemplate.CalculateOffense): FieldOfFire / 61 degrees, kept between 1 and 4, here divided by 4 so "
                               "a wide arc is 1. Weapons without FieldOfFire count 1."),
    ("restrict", "Target limits", 0.5, "The game's own valuation: -15% cannot hit fighters, -15% corvettes, -45% capitals, -25% stations."),
)
BAL_DEFAULTS = {"T": 60.0, "dist": 5000.0, "evade": 6.0, "pd": 5.0, "shield_mix": 50.0, "extra_block": 0.0, "target_r": 150.0,
                "own_draw": False,
                "skip": "Remnant, Ancient, Pirate", "level": "own", "group": "(all)", "w": {}, "mult": {}}


def bal_depths(proj):
    """{module uid (lower case): steps from a root tech down the research tree (LeadsTo)} - the earliest tech that unlocks the module.
    In this mod the steps match the <TechLevel> numbers one to one, so a module without a TechLevel gets its level from here."""
    by = {t.uid.lower(): t for t in proj.techs}
    has_parent = {l.lower() for t in proj.techs for l in t.leads}
    depth, queue = {}, [u for u in by if u not in has_parent]
    for u in queue:
        depth[u] = 0
    i = 0
    while i < len(queue):
        u = queue[i]
        i += 1
        for l in by[u].leads:
            l = l.lower()
            if l in by and l not in depth:
                depth[l] = depth[u] + 1
                queue.append(l)
    out = {}
    for t in proj.techs:
        d = depth.get(t.uid.lower())
        if d is not None:
            for mu, _ty in t.unlocks:
                k = mu.lower()
                out[k] = min(out.get(k, d), d)
    return out


def bal_level(m, depths=None):
    """The module's <TechLevel>; if it has none, how many steps down the tech tree its tech is; if it is not in the tree, 0."""
    v = _g(m, "TechLevel")
    if v is not None and v >= 0:
        return int(v)
    return int((depths or {}).get(m.get("UID").strip().lower(), 0))


def bal_group(w):
    for name, tag in BAL_GROUPS:
        if w.get(tag).strip().lower() == "true":
            return name
    return "Other"


def bal_support(mods, proj, opts):
    """{level: (energy per tile, module name, ordnance per tile, module name)}: the best support tile you can build at each tech level
    (levels count up: a level-3 ship can use level 0-3 modules). 'per tile' covers a whole fight of T seconds: production x T + storage."""
    T = opts["T"]
    dep = opts.get("_depths")
    skip = [s.strip().lower() for s in str(opts.get("skip", "")).split(",") if s.strip()]
    cands = []
    for m in mods:
        if proj.weapon_for(m) is not None:
            continue
        a = _area(m)
        mt = m.get("ModuleType").strip()
        if not a or (mt not in BAL_ENERGY_TYPES and mt not in BAL_ORD_TYPES):
            continue
        uid = m.get("UID").strip() or m.path.stem
        if any(s in (uid + " " + m.get("Name")).lower() for s in skip):
            continue
        e = ((_g(m, "PowerFlowMax", 0) or 0) * T + (_g(m, "PowerStoreMax", 0) or 0)) / a if mt in BAL_ENERGY_TYPES else 0
        o = ((_g(m, "OrdnanceAddedPerSecond", 0) or 0) * T + (_g(m, "OrdinanceCapacity", 0) or 0)) / a if mt in BAL_ORD_TYPES else 0
        if e > 0 or o > 0:
            cands.append((bal_level(m, dep), uid, e, o))
    top = max([c[0] for c in cands] + [bal_level(m, dep) for m in mods] + [0])
    opts["_def"] = bal_defense(mods, proj, opts, top)
    opts["_hpmult"] = bal_hp_mult(proj)
    out = {}
    for lv in range(0, top + 1):
        be_, bo = (0, ""), (0, "")
        for l, uid, e, o in cands:
            if l <= lv:
                if e > be_[0]:
                    be_ = (e, uid)
                if o > bo[0]:
                    bo = (o, uid)
        out[lv] = (be_[0], be_[1], bo[0], bo[1])
    return out


BAL_RESIST_TAGS = (("Explodes", "Explosive"), ("Tag_Plasma", "Plasma"), ("Tag_Kinetic", "Kinetic"), ("Tag_Beam", "Beam"), ("Tag_Energy", "Energy"))


def bal_hp_mult(proj):
    """ProjectileHitpointsMultiplier from the mod's (or the game's) Globals.yaml: every shot's HitPoints are multiplied by it."""
    try:
        for f in (proj.root / "Globals.yaml", (proj.game_dir / "Content" / "Globals.yaml") if proj.game_dir else None):
            if f and f.is_file():
                mt = re.search(r"ProjectileHitpointsMultiplier:\s*([\d.]+)", f.read_text(encoding="utf-8-sig", errors="replace"))
                if mt:
                    return float(mt.group(1))
    except Exception:
        pass
    return 1.0


def bal_defense(mods, proj, opts, top):
    """{level: {'shield': {type: mean resist}, 'armor': {type: mean resist}, 'sdefl': [ShieldDeflection of each shield module], 'adefl': [Deflection of each
    armor module]}} for the shield and armor modules you can have by that level: what a shot meets in the game (ShipModule.Damage)."""
    dep = opts.get("_depths")
    skip = [x.strip().lower() for x in str(opts.get("skip", "")).split(",") if x.strip()]
    shields, armors = [], []
    for m in mods:
        mt = m.get("ModuleType").strip()
        if mt not in ("Shield", "Armor"):
            continue
        uid = m.get("UID").strip() or m.path.stem
        if any(x in (uid + " " + m.get("Name")).lower() for x in skip):
            continue
        (shields if mt == "Shield" else armors).append((bal_level(m, dep), m))
    out = {}
    for lv in range(0, top + 1):
        d = {"shield": {}, "armor": {}, "sdefl": [], "adefl": []}
        for key, lst, pre in (("shield", shields, "Shield"), ("armor", armors, "")):
            have = [m for l, m in lst if l <= lv]
            for _t, nm in BAL_RESIST_TAGS:
                vals = [_g(m, pre + nm + "Resist", 0) or 0 for m in have]
                d[key][nm] = sum(vals) / len(vals) if vals else 0.0
            d["sdefl" if key == "shield" else "adefl"] = [_g(m, "ShieldDeflection" if key == "shield" else "Deflection", 0) or 0 for m in have]
        out[lv] = d
    return out


def bal_resist(w, table):
    """The game's rule: an exploding shot uses only the explosive resist; any other shot multiplies (1 - resist) for each of its types."""
    if w.get("Explodes").strip().lower() == "true":
        return 1.0 - table.get("Explosive", 0.0)
    r = 1.0
    for tag, nm in BAL_RESIST_TAGS[1:]:
        if w.get(tag).strip().lower() == "true":
            r *= 1.0 - table.get(nm, 0.0)
    return r


def bal_factors(m, w, opts):
    """({key: multiplier} for every modifier before the weights are applied, seconds a shot is in flight, text of the special effects)."""
    beam = bal_is_beam(w)
    guided = w.get("Tag_Guided").strip().lower() == "true"
    f = {}
    D, T = opts["dist"], opts["T"]
    r = _g(w, "Range")
    f["reach"] = 0.0 if r is not None and r < D else 1.0
    spd = _g(w, "ProjectileSpeed")
    t = 0.0 if beam or not spd or spd <= 0 else D / spd
    tau = max(0.01, opts["evade"]) * (BAL_GUIDED_EVADE if guided else 1.0)
    f["travel"] = (1.0 / (1.0 + t / tau)) * (max(0.0, T - t) / T if T > 0 else 1.0)
    if w.get("Tag_Intercept").strip().lower() == "true" and t > 0:
        hp = (_g(w, "HitPoints") or 100.0) * (opts.get("_hpmult") or 1.0)
        f["pd"] = math.exp(-t * max(0.0, opts["pd"]) / hp)
    else:
        f["pd"] = 1.0
    s = min(1.0, max(0.0, opts["shield_mix"] / 100.0))
    blk = min(1.0, max(0.0, opts.get("extra_block", 0.0) / 100.0))
    arm = _g(w, "EffectVsArmor", 1.0)
    shd = _g(w, "EffectVsShields")
    if shd is None:
        shd = _g(w, "EffectVsShield", 1.0)
    pen = min(1.0, max(0.0, (_g(w, "ShieldPenChance", 0) or 0) / 100.0))
    dfn = (opts.get("_def") or {})
    dfn = dfn.get(min(bal_level(m, opts.get("_depths")), max(dfn))) if dfn else None
    dmg1 = _g(w, "DamageAmount", 0) or 0
    plasma = w.get("Tag_Plasma").strip().lower() == "true"
    S = shd * (1 - blk)
    A = arm * (1 - blk)
    if dfn:
        S *= bal_resist(w, dfn["shield"])
        A *= bal_resist(w, dfn["armor"])
        if not beam and not plasma:             # a shot weaker than the module's deflection does nothing
            if dfn["sdefl"]:
                S *= sum(1 for x in dfn["sdefl"] if dmg1 * shd >= x) / float(len(dfn["sdefl"]))
            if dfn["adefl"]:
                A *= sum(1 for x in dfn["adefl"] if dmg1 * arm >= x) / float(len(dfn["adefl"]))
    f["mix"] = (1 - s) * A + s * ((1 - pen) * S + pen * A)
    cone = _g(w, "FireCone", 0) or 0
    if cone > 0 and not beam and not guided:
        f["spread"] = min(1.0, 2.0 * math.atan(max(1.0, opts.get("target_r", 150.0)) / max(1.0, D)) / math.radians(cone))
    else:
        f["spread"] = 1.0
    rad = max(_g(w, "DamageRadius", 0) or 0, _g(w, "ExplosionRadius", 0) or 0)
    f["splash"] = 1.0 + 0.5 * rad / (rad + 150.0) if rad > 0 else 1.0
    fov = _g(m, "FieldOfFire")
    f["arc"] = (min(4.0, max(1.0, fov / 61.2)) / 4.0) if fov and fov > 0 else 1.0
    f["restrict"] = max(0.0, 1.0 - sum(c for tg, c in (("ExcludesFighters", 0.15), ("ExcludesCorvettes", 0.15), ("ExcludesCapitals", 0.45),
                                                      ("ExcludesStations", 0.25)) if w.get(tg).strip().lower() == "true"))
    extra = []
    for tag, label in (("EMPDamage", "EMP"), ("PowerDamage", "power drain"), ("TractorDamage", "tractor"), ("SiphonDamage", "siphon"),
                       ("RepulsionDamage", "repulsion"), ("TroopDamageChance", "troop kill %"), ("ArmorPen", "armor pen")):
        v = _g(w, tag)
        if v:
            extra.append("%s %s" % (label, fmtv(v)))
    return f, t, ", ".join(extra)


def bal_is_beam(w):
    return w.get("Tag_Beam").strip().lower() == "true" or w.get("IsBeam").strip().lower() == "true"


def bal_game_rates(w):
    """(damage per second, fire cycle in seconds, power per second, ordnance per second) exactly as the game's WeaponTemplate works them out
    (DamagePerSecond, NetFireDelay, PowerFireUsagePerSecond, AverageOrdnanceUsagePerSecond), before any modifiers.
    A beam deals DamageAmount x 60 for every second it is on; its cycle is FireDelay + BeamDuration. Any other weapon fires SalvoCount x
    ProjectileCount shots of DamageAmount per cycle of FireDelay + SalvoTimer."""
    delay = max(0.016, _g(w, "FireDelay", 0) or 0)
    salvo = max(1, int(_g(w, "SalvoCount", 1) or 1))
    proj = max(1, int(_g(w, "ProjectileCount", 1) or 1))
    dmg = _g(w, "DamageAmount", 0) or 0
    pwr = (_g(w, "PowerRequiredToFire", 0) or 0) * proj * salvo
    ordn = (_g(w, "OrdinanceRequiredToFire", 0) or 0) * proj * salvo
    if bal_is_beam(w):
        dur = _g(w, "BeamDuration", 0) or 0
        dur = dur if dur > 0 else 2.0
        cycle = delay + dur
        dmg = dmg or (_g(w, "PowerDamage", 0) or 0)
        return dmg * dur * 60.0 / cycle, cycle, ((_g(w, "BeamPowerCostPerSecond", 0) or 0) * dur + pwr) / cycle, ordn / cycle
    cycle = delay + max(0.0, _g(w, "SalvoTimer", 0) or 0)
    return salvo / cycle * proj * dmg, cycle, pwr / cycle, ordn / cycle


def bal_row(proj, m, w, opts, support, at_level=None):
    """One weapon module -> a dict of its numbers, or None when it has no damage."""
    dps, cycle, pw_s, ord_s = bal_game_rates(w)
    if not dps or dps <= 0:
        return None
    T, area = opts["T"], _area(m)
    if not area:
        return None
    lvl = bal_level(m, opts.get("_depths"))
    from_tree = _g(m, "TechLevel") is None
    use = lvl if at_level is None else max(lvl, at_level)
    group = bal_group(w)
    f, flight, extra = bal_factors(m, w, opts)
    weights = opts.get("w", {})
    mod = 1.0
    shown = []
    for key, label, dflt, _h in BAL_MODS:
        wt = weights.get(key, dflt)
        v = f[key] ** wt if f[key] > 0 else (0.0 if wt > 0 else 1.0)
        mod *= v
        if wt and abs(v - 1.0) >= 0.005:
            shown.append("%s %.2f" % (label.split(" /")[0].lower(), v))
    gm = opts.get("mult", {}).get(group, 1.0)
    eff = dps * mod * gm
    need_e = pw_s + ((_g(m, "PowerDraw", 0) or 0) if opts.get("own_draw") else 0)
    need_o = ord_s
    sup = support.get(min(use, max(support))) if support else None
    et = ot = 0.0
    note = ""
    if need_e > 0:
        if sup and sup[0] > 0:
            et = need_e * T / sup[0]
        else:
            et = None
            note = "no power module at this level"
    if need_o > 0:
        if sup and sup[2] > 0:
            ot = need_o * T / sup[2]
        else:
            ot = None
            note = (note + "; " if note else "") + "no ordnance module at this level"
    total = None if et is None or ot is None else area + et + ot
    if from_tree:
        note = (note + "; " if note else "") + "level from tech tree"
    if extra:
        note = (note + "; " if note else "") + "also: " + extra
    return {"m": m, "uid": m.get("UID").strip() or m.path.stem, "name": m.get("Name").strip(), "group": group, "level": lvl, "use": use,
            "area": area, "dps": dps, "t": flight, "mod": mod * gm, "eff": eff, "et": et, "ot": ot, "total": total, "why": ", ".join(shown),
            "per_tile": (eff / total) if total else None, "note": note}


def bal_rows(proj, mods, opts, at_level=None):
    opts = dict(opts, _depths=bal_depths(proj))
    support = bal_support(mods, proj, opts)
    rows = []
    for m in mods:
        w = proj.weapon_for(m)
        if w is None:
            continue
        r = bal_row(proj, m, w, opts, support, at_level)
        if r:
            rows.append(r)
    return rows, support


def bal_curves(proj, mods, opts):
    """{group: [(level, best damage per tile among that group's weapons you can have by that level, assessed with that level's support)]}."""
    opts = dict(opts, _depths=bal_depths(proj))
    support = bal_support(mods, proj, opts)
    top = max(support) if support else 0
    byg = {}
    for lv in range(0, top + 1):
        rows = [r for r in (bal_row(proj, m, proj.weapon_for(m), opts, support, lv) for m in mods if proj.weapon_for(m) is not None) if r]
        best = {}
        for r in rows:
            if r["level"] <= lv and r["per_tile"] is not None:
                best[r["group"]] = max(best.get(r["group"], 0), r["per_tile"])
        for g, v in best.items():
            byg.setdefault(g, []).append((lv, v))
    return byg


def bal_opts_from_cfg(cfg):
    """Balance settings (the dict the Balance tab saves, or nothing) -> the numbers the calculation uses."""
    cfg = dict(BAL_DEFAULTS, **(cfg or {}))

    def f(k, lo=None):
        try:
            v = float(str(cfg.get(k)).replace(",", "."))
        except ValueError:
            v = BAL_DEFAULTS[k]
        return v if lo is None else max(lo, v)
    o = {k: cfg[k] for k in BAL_DEFAULTS if k not in ("w", "mult")}
    for k, lo in (("T", 1.0), ("dist", 0.0), ("evade", 0.01), ("pd", 0.0), ("shield_mix", 0.0), ("extra_block", 0.0), ("target_r", 1.0)):
        o[k] = f(k, lo)
    o["w"] = {}
    for k, _l, d, _h in BAL_MODS:
        try:
            o["w"][k] = max(0.0, float(str((cfg.get("w") or {}).get(k, d)).replace(",", ".")))
        except ValueError:
            o["w"][k] = d
    o["mult"] = {}
    for g, v in (cfg.get("mult") or {}).items():
        try:
            o["mult"][g] = float(str(v).replace(",", "."))
        except ValueError:
            o["mult"][g] = 1.0
    return o


def bal_metric(proj, m, key):
    """A balance number for one module (used by the Compare tab): bal_eff, bal_tile, bal_tiles or bal_flight; None if it is not a weapon."""
    w = proj.weapon_for(m)
    if w is None:
        return None
    o = dict(bal_opts_from_cfg(getattr(proj, "bal_cfg", None)), _depths=bal_depths(proj))
    mods = list(proj.modules) + list(proj.base_modules)
    r = bal_row(proj, m, w, o, bal_support(mods, proj, o))
    if r is None:
        return None
    return {"bal_eff": r["eff"], "bal_tile": r["per_tile"], "bal_tiles": r["total"], "bal_flight": r["t"]}.get(key)


def bal_fmt_damage(old, new):
    """The new damage as text: a whole number if the old one was whole, otherwise with a few decimals."""
    old = str(old).strip()
    if INT_RE.match(old) or abs(new) >= 100:
        return str(int(round(new)))
    s = ("%.1f" % new) if abs(new) >= 10 else ("%.2f" % new)
    return s.rstrip("0").rstrip(".") if "." in s else s


def bal_race_mods(proj, race):
    """({module uid: True} for modules a race can use, {module uid: True} for those only it can use). race=None: every module."""
    of = proj.race_info().of
    usable, own = set(), set()
    for m in list(proj.modules) + list(proj.base_modules):
        uid = (m.get("UID") or m.path.stem).strip().lower()
        rs = of.get(uid, set())
        if race is None or not rs or race in rs:
            usable.add(uid)
        if race is not None and rs and rs == {race}:
            own.add(uid)
    return usable, own


def bal_plan(proj, opts, group="(all)", race=None, target="typical", base=100.0, growth=0.0, strength=1.0, shared=False, only=None):
    """Work out the DamageAmount change that brings each weapon's DPS per tile to its target.
    race=None balances every weapon (all races); a race name balances the weapons that race can use and changes only the ones that are
    its own (and the ones every race shares if shared=True). target='typical': the median DPS per tile of the weapons in scope at the
    same tech level (levels either side are pooled when too few). target='curve': base x (1 + growth) ^ level.
    only = a set of lower-case module UIDs: just those weapons change (the Compare tab's tagged ones). target='tagged': the median of the tagged weapons.
    Returns (plan, skipped): plan = [dict(weapon, mods, old, new, mult, before, after, group, level)], skipped = [(name, why)]."""
    o = dict(opts)
    mods = list(proj.modules) + list(proj.base_modules)
    rows, _sup = bal_rows(proj, mods, o)
    usable, own = bal_race_mods(proj, race)
    of = proj.race_info().of
    rows = [r for r in rows if r["uid"].lower() in usable and r["per_tile"]]
    bylevel, bylevel_all = {}, {}
    for r in rows:
        bylevel_all.setdefault(r["level"], []).append(r["per_tile"])
        if group in ("(all)", None) or r["group"] != group:       # balancing one type: aim at the OTHER types, so a second run changes nothing
            bylevel.setdefault(r["level"], []).append(r["per_tile"])

    tagged_med = None
    if target == "tagged" and only is not None:
        tv = sorted(r["per_tile"] for r in rows if r["uid"].lower() in only)
        tagged_med = tv[len(tv) // 2] if tv else None

    def typical(lv):
        for src in (bylevel, bylevel_all):
            pool = []
            for d in range(0, 4):
                pool = [v for l in range(lv - d, lv + d + 1) for v in src.get(l, [])]
                if len(pool) >= 3 or d == 3:
                    break
            if pool:
                pool.sort()
                return pool[len(pool) // 2]
        return None
    users = {}
    for m in mods:
        w = proj.weapon_for(m)
        if w is not None:
            users.setdefault(id(w), []).append(m)
    plan, skipped, seen = [], [], {}
    for r in rows:
        if group not in ("(all)", r["group"]):
            continue
        uid = r["uid"].lower()
        rs = of.get(uid, set())
        if only is not None and uid not in only:
            continue
        if race is not None and not (uid in own or (shared and not rs)):
            continue
        w = proj.weapon_for(r["m"])
        if target == "tagged":
            tgt = tagged_med
        else:
            tgt = typical(r["level"]) if target == "typical" else base * (1.0 + growth / 100.0) ** r["level"]
        if not tgt or r["per_tile"] <= 0:
            continue
        mult = (tgt / r["per_tile"]) ** max(0.0, min(1.0, strength))
        seen.setdefault(id(w), (w, []))[1].append((r, mult))
    for _k, (w, items) in seen.items():
        others = [m for m in users.get(id(w), []) if not any(m is r["m"] for r, _x in items)]
        if others and race is not None:
            skipped.append((w.get("UID").strip(), "also used by %d module(s) outside this race (%s)" % (len(others), others[0].get("UID").strip())))
            continue
        old = w.get("DamageAmount")
        ov = num(old)
        if ov is None or ov <= 0:
            skipped.append((w.get("UID").strip(), "no positive DamageAmount"))
            continue
        lg = sum(math.log(max(1e-9, x)) for _r, x in items) / len(items)
        mult = math.exp(lg)
        newtxt = bal_fmt_damage(old, ov * mult)
        nv = num(newtxt)
        if nv is None or nv <= 0 or newtxt.strip() == old.strip():
            continue
        r0 = items[0][0]
        plan.append({"weapon": w, "mods": [r["m"] for r, _x in items], "old": old.strip(), "new": newtxt, "mult": nv / ov,
                     "before": sum(r["per_tile"] for r, _x in items) / len(items), "after": sum(r["per_tile"] for r, _x in items) / len(items) * nv / ov,
                     "group": r0["group"], "level": r0["level"], "name": r0["uid"], "shared_by": len(items)})
    plan.sort(key=lambda p: (p["group"], p["level"], p["name"].lower()))
    return plan, skipped


def bal_plan_each_race(proj, opts, group="(all)", **kw):
    """bal_plan once for every race on its own: each race's own weapons are balanced against the weapons that race can use."""
    plan, skipped, done = [], [], set()
    for race in proj.race_info().names:
        p, s = bal_plan(proj, opts, group, race=race, **kw)
        for x in p:
            if id(x["weapon"]) not in done:
                done.add(id(x["weapon"]))
                x["race"] = race
                plan.append(x)
        skipped += [(n, "%s: %s" % (race, why)) for n, why in s]
    plan.sort(key=lambda p: (p["group"], p["level"], p["name"].lower()))
    return plan, skipped



class BalanceView(tk.Frame):
    """Compare > Balance: every weapon's damage per tile of ship space, support included. The power and ordnance a weapon needs are turned
    into tiles of reactors / magazines (the best ones you can have at its tech level), so a weapon that eats a lot of power or ammo
    is not flattered by its raw DPS."""
