        tk.Label(fr, text="Type", bg=BG, fg=FG).pack(side="left", padx=(12, 2))
        self.gcb = ttk.Combobox(fr, textvariable=self.v["group"], values=["(all)"] + [g for g, _t in BAL_GROUPS] + ["Other"], state="readonly", width=13)
        self.gcb.pack(side="left")
        tip(self.gcb, "Show one weapon type only (Beam, Cannon, Torpedo ...). A weapon's type comes from its Tag_ flags; weapons with none of them are 'Other'.")
        tk.Label(fr, text="Race", bg=BG, fg=FG).pack(side="left", padx=(12, 2))
