        tk.Label(fr, text="Sort by", bg=BG, fg=FG).pack(side="left", padx=(12, 2))
        so = ttk.Combobox(fr, textvariable=self.sort_v, values=[c[1] for c in self.COLS], state="readonly", width=12)
