        for c, t, w in (("p", "!", 28), ("name", "Design", 200), ("hull", "Hull", 190), ("n", "Mods", 50)):
            self.tv.heading(c, text=t)
            self.tv.column(c, width=w, anchor="w" if c in ("name", "hull") else "center", stretch=c in ("name", "hull"))
