        self.tv.configure(yscrollcommand=sb.set)
        self.tv.pack(side="left", fill="both", expand=True)
        sb.pack(side="right", fill="y")
        self.tv.bind("<<TreeviewSelect>>", lambda _e: self.pick())
        self._hov_row, self._hov_job, self._hov_win = None, None, None
        if embedded:                                                # the checks and numbers pop up beside the list instead of taking room under it
            self.tv._auto_tip = True                                # (no second hint on top of the hover box)
