def write_png(path, w, h, rows):
    """rows: list of bytes, 3 per pixel (RGB). A PNG written with zlib only."""
    import zlib, struct

    def chunk(t, d):
        c = struct.pack(">I", len(d)) + t + d
        return c + struct.pack(">I", zlib.crc32(t + d) & 0xffffffff)
    raw = b"".join(b"\x00" + r for r in rows)
    Path(path).write_bytes(b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0)) + chunk(b"IDAT", zlib.compress(raw, 6)) + chunk(b"IEND", b""))


def write_png_rgba(path, w, h, rows):
    """rows: list of bytes, 4 per pixel (RGBA)."""
    import zlib, struct

    def chunk(t, d):
        c = struct.pack(">I", len(d)) + t + d
        return c + struct.pack(">I", zlib.crc32(t + d) & 0xffffffff)
    raw = b"".join(b"\x00" + r for r in rows)
    Path(path).write_bytes(b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 6, 0, 0, 0)) + chunk(b"IDAT", zlib.compress(raw, 6)) + chunk(b"IEND", b""))


def hull_textures(folder, key, base, accent, size=512, seed=7):
    rnd = random.Random(seed)
    step = size // 16
    px = [bytearray(bytes(base) * size) for _ in range(size)]

    def rect(x0, y0, x1, y1, col):
        col = bytes(col)
        for y in range(max(0, y0), min(size, y1)):
            row = px[y]
            for x in range(max(0, x0), min(size, x1)):
                row[x * 3:x * 3 + 3] = col
    for y in range(0, size, step):                                   # plating: a slightly different shade on each plate
        for x in range(0, size, step * 2):
            xo = x + (step if (y // step) % 2 else 0)
            k = rnd.randint(-14, 14)
            rect(xo + 2, y + 2, xo + step * 2 - 2, y + step - 2, [max(0, min(255, c + k)) for c in base])
    for _ in range(10):                                              # accent stripes
        x, w = rnd.randrange(size), rnd.choice((3, 6, 10))
        rect(x, 0, x + w, size, [int(a * 0.55 + b * 0.45) for a, b in zip(base, accent)])
    for _ in range(260):                                             # windows
        x, y = rnd.randrange(size), rnd.randrange(size)
        rect(x, y, x + rnd.choice((2, 3, 4)), y + 2, (235, 230, 180) if rnd.random() < 0.6 else (60, 70, 90))
    write_png(Path(folder) / (key + "_hull.png"), size, size, [bytes(r) for r in px])
    rows = []                                                        # normal map: grooves along the plate edges
    for y in range(size):
        r = bytearray()
        for x in range(size):
            gx = 128 + (60 if x % (step * 2) in (0, 1) else -60 if x % (step * 2) in (2, 3) else 0)
            gy = 128 + (60 if y % step in (0, 1) else -60 if y % step in (2, 3) else 0)
            r += bytes((max(0, min(255, gx)), max(0, min(255, gy)), 255))
        rows.append(bytes(r))
    write_png(Path(folder) / (key + "_hull_n.png"), size, size, rows)
    s = 128
    rows = []
    for y in range(s):
        r = bytearray()
        for x in range(s):
            g = max(0.0, 1.0 - math.hypot(x - s / 2.0, y - s / 2.0) / (s / 2.0)) ** 0.7
            r += bytes(min(255, int(g * c + 40)) for c in accent)
        rows.append(bytes(r))
    write_png(Path(folder) / (key + "_glow.png"), s, s, rows)


def make_ship_models(folder, key, which, base, accent, flip=False):
    """Writes <key>_<model>.obj / .mtl and the three PNGs into folder. Returns the file names."""
    folder = Path(folder)
    folder.mkdir(parents=True, exist_ok=True)
    hull_textures(folder, key, base, accent)
    for name in which:
        SHIP_MODELS[name][1]().write(folder / ("%s_%s.obj" % (key, name)), "%s_%s.mtl" % (key, name), flip)
        (folder / ("%s_%s.mtl" % (key, name))).write_text(
            "newmtl hull\nKa 1 1 1\nKd 1 1 1\nKs 0.35 0.35 0.35\nNs 40\nmap_Kd {0}_hull.png\nmap_Bump {0}_hull_n.png\n\n"
            "newmtl glow\nKa 1 1 1\nKd 1 1 1\nKe 1 1 1\nmap_Kd {0}_glow.png\nmap_Ke {0}_glow.png\n".format(key), encoding="ascii")
    return sorted(p.name for p in folder.iterdir())


class ShipModelDialog(_Dialog):
    """Make simple 3D ship models (.obj + .mtl + PNG textures) for a race, staged into the mod's 'mod Model\\<race>' folder, and optionally point the race's hulls at them."""

    COLORS = {"Steel grey": ((120, 126, 136), (70, 140, 200)), "Federation white": ((205, 210, 218), (90, 160, 230)), "Klingon green-grey": ((86, 98, 84), (230, 120, 40)),
              "Romulan green": ((70, 110, 84), (120, 230, 140)), "Dark red": ((110, 60, 58), (255, 90, 60)), "Sand / gold": ((168, 150, 112), (255, 200, 80)),
              "Black": ((40, 42, 48), (160, 80, 220))}

    def __init__(self, master, app, key="", hull=None, role="", new_ship=None):
        super().__init__(master, "3D ship models")
        self.app, self.proj = app, app.proj
        self.hull, self.role, self.new_ship, self.chosen = hull, (role or "").strip().lower(), new_ship, None
        P = self.proj
        keys = sorted({re.search(r"<ShipType>\s*([^<]*?)\s*</ShipType>", r.text or "").group(1) for r in P.race_docs()
                       if re.search(r"<ShipType>\s*([^<]*?)\s*</ShipType>", r.text or "")}, key=str.lower)
        if key and key not in keys:
            keys = sorted(keys + [key], key=str.lower)
        self.v_key = tk.StringVar(value=key or (keys[0] if keys else ""))
        self.v_one = tk.BooleanVar(value=hull is not None)
        self.v_col = tk.StringVar(value="Steel grey")
        self.v_flip = tk.BooleanVar(value=False)
        self.v_hulls = tk.BooleanVar(value=False)
        self.v_models = {k: tk.BooleanVar(value=True) for k in SHIP_MODELS}
        tk.Label(self, text="Makes simple 3D ships (.obj with .mtl and PNG textures) in the mod's 'mod Model\\<ship type>' folder when you Save.\n"
                            "They are plain geometric placeholders: check size, facing and textures in the game.", bg=PANEL, fg=DIM, justify="left").grid(
            row=0, column=0, columnspan=2, sticky="w", padx=14, pady=(12, 6))
        self.label(1, "Ship type (the race's key)", "The folder name and the start of each file name, e.g. vulcan.")
        cb = ttk.Combobox(self, textvariable=self.v_key, values=keys, width=28)
        cb.grid(row=1, column=1, sticky="w", pady=4)
        self.label(2, "Colours")
        ttk.Combobox(self, textvariable=self.v_col, values=list(self.COLORS), width=28, state="readonly").grid(row=2, column=1, sticky="w", pady=4)
        self.label(3, "Models")
        mf = tk.Frame(self, bg=PANEL)
        mf.grid(row=3, column=1, sticky="w", pady=4)
        for k, (lab, _fn) in SHIP_MODELS.items():
            tk.Checkbutton(mf, text=lab, variable=self.v_models[k], bg=PANEL, fg=FG, selectcolor=PANEL2, activebackground=PANEL, anchor="w").pack(anchor="w")
        if hull is not None:
            tk.Checkbutton(self, text="Point the selected ship (%s) at the best-fitting new model" % (P.hull_key(hull) or "ship"), variable=self.v_one, bg=PANEL, fg=FG,
                           selectcolor=PANEL2, activebackground=PANEL).grid(row=7, column=0, columnspan=2, sticky="w", padx=14, pady=2)
        tk.Checkbutton(self, text="Also point ALL of this race's hulls at them, replacing their current models (by hull role) - leave off to do it hull by hull", variable=self.v_hulls, bg=PANEL, fg=FG,
                       selectcolor=PANEL2, activebackground=PANEL).grid(row=4, column=0, columnspan=2, sticky="w", padx=14, pady=2)
        tk.Checkbutton(self, text="Nose points to -Z (turn on if the ships fly backwards in the game)", variable=self.v_flip, bg=PANEL, fg=FG,
                       selectcolor=PANEL2, activebackground=PANEL).grid(row=5, column=0, columnspan=2, sticky="w", padx=14, pady=2)
        bt = tk.Frame(self, bg=PANEL)
        bt.grid(row=6, column=0, columnspan=2, sticky="e", padx=14, pady=12)
        ttk.Button(bt, text="Make the models", command=self.make).pack(side="left", padx=6)
        if new_ship is not None:
            b = ttk.Button(bt, text="New ship…", command=self.open_new_ship)
            b.pack(side="left", padx=6)
            tip(b, "Close this window and open the New ship wizard (its Model row has a 'Make 3D model…' button too).")
        ttk.Button(bt, text="Close", command=self.destroy).pack(side="left")

    def open_new_ship(self):
        cb = self.new_ship
        self.destroy()
        self.after(50, cb)

    def make(self):
        import tempfile
        P = self.proj
        key = re.sub(r"[^\w\-]+", "_", self.v_key.get().strip())
        which = [k for k, v in self.v_models.items() if v.get()]
        if not key or not which:
            messagebox.showwarning("3D ship models", "Type a ship type and tick at least one model.", parent=self)
            return
        base, accent = self.COLORS[self.v_col.get()]
        tmp = Path(tempfile.mkdtemp(prefix="sdmodels_"))
        try:
            names = make_ship_models(tmp, key, which, base, accent, self.v_flip.get())
        except Exception as e:
            messagebox.showerror("3D ship models", "Could not make the models: %s" % e, parent=self)
            return
        n = 0
        for fn in names:
            tex = "mod Model/%s/%s" % (key, Path(fn).stem)
            dest = P.root / "mod Model" / key / fn
            P.file_docs = [f for f in P.file_docs if f.path != dest]
            P.file_docs.append(FileCopyDoc(tmp / fn, dest, P.root, tex if fn.endswith(".obj") else "ModelFiles/%s/%s" % (key, fn)))
            n += 1
        P._models = None
        done = 0
        role_model = lambda r: (lambda m: m if m in which else which[0])(HULL_ROLE_MODEL.get((r or "").strip().lower(), "wedge_cruiser"))
        self.chosen = "mod Model/%s/%s_%s" % (key, key, role_model(self.role))
        if self.hull is not None and self.v_one.get():
            self.hull.set("ModelPath", "mod Model/%s/%s_%s" % (key, key, role_model(self.hull.get("Role"))))
            done += 1
        if self.v_hulls.get():
            for h in P.race_hulls(key):
                if h is self.hull:
                    continue
                h.set("ModelPath", "mod Model/%s/%s_%s" % (key, key, role_model(h.get("Role"))))
                done += 1
        self.app.refresh()
        self.app.say("Made %d model file(s) for %s%s. Save (Ctrl+S) to write them into mod Model\\%s." % (n, key, ", %d hull(s) now use them" % done if done else "", key))
        messagebox.showinfo("3D ship models", "%d file(s) are ready for %s%s.\n\nPress Save (Ctrl+S) to write them into the mod, then look at a ship in the game: "
                            "check its size, which way it faces and its textures." % (n, key, "; %d hull(s) now point at them" % done if done else ""), parent=self)
        self.destroy()


class GenerateDesignDialog(_Dialog):
    """Make a new ship design for any hull with the game's own placement rules; see the checks and numbers before anything is written."""

    def __init__(self, master, proj, hull=None, view=None):
        super().__init__(master, "Generate a ship design")
        self.proj, self.view, self.done = proj, view, None
        self.gen = DesignGenerator(proj)
        self.result_text = None
        hulls = sorted(list(proj.hulls) + list(proj.base_hulls), key=lambda h: proj.hull_key(h).lower())
        self.hulls = {proj.hull_key(h): h for h in hulls}
        self.v_hull = tk.StringVar(value=proj.hull_key(hull) if hull is not None else (next(iter(self.hulls), "")))
        self.v_goal = tk.StringVar(value=next(iter(GEN_GOALS)))
        self.v_name, self.v_style = tk.StringVar(), tk.StringVar()
        self.v_unl, self.v_lim = tk.BooleanVar(value=True), tk.StringVar(value="0")
        self.v_en, self.v_ord = tk.BooleanVar(value=True), tk.BooleanVar(value=True)
        tk.Label(self, text="Builds a design that obeys the game's slot rules, then shows what the game would work out for it. Nothing is written until you press "
                            "Create, and then it is staged like every other change (Save writes the file).", bg=PANEL, fg=DIM, wraplength=760,
                 justify="left", anchor="w").grid(row=0, column=0, columnspan=4, sticky="ew", padx=12, pady=(10, 6))
        self.label(1, "Hull", "The hull the design is built on.")
        cb = ttk.Combobox(self, textvariable=self.v_hull, values=list(self.hulls), width=34)
        cb.grid(row=1, column=1, sticky="w", padx=4)
        cb.bind("<<ComboboxSelected>>", lambda _e: self.on_hull())
        tip(cb, "Pick the hull. Type to jump to one.")
        self.label(2, "Purpose", "What the ship is for.")
        gb = ttk.Combobox(self, textvariable=self.v_goal, values=list(GEN_GOALS), state="readonly", width=34)
        gb.grid(row=2, column=1, sticky="w", padx=4)
        self.about = tk.Label(self, text="", bg=PANEL, fg=DIM, anchor="w")
        self.about.grid(row=2, column=2, columnspan=2, sticky="w")
        gb.bind("<<ComboboxSelected>>", lambda _e: self.on_goal())
        self.label(3, "Design name", "The design's name (and file name). It must be new.")
        ttk.Entry(self, textvariable=self.v_name, width=36).grid(row=3, column=1, sticky="w", padx=4)
        self.label(4, "Race (Style)", "The race the design is for. Modules unlocked only for other races are left out.")
        ttk.Entry(self, textvariable=self.v_style, width=36).grid(row=4, column=1, sticky="w", padx=4)
        c1 = ttk.Checkbutton(self, text="Only modules some tech unlocks", variable=self.v_unl)
        c1.grid(row=5, column=1, sticky="w", padx=4, pady=(6, 0))
        tip(c1, "A module no tech lists can never be built by a player, and makes the whole design unbuildable (§5.3).")
        wf = tk.Frame(self, bg=PANEL)
        wf.grid(row=5, column=2, columnspan=2, sticky="w", pady=(6, 0))
        tk.Label(wf, text="Main weapons:", bg=PANEL, fg=FG).pack(side="left", padx=(0, 6))
        c2 = ttk.Checkbutton(wf, text="Energy (beams, plasma, cannons)", variable=self.v_en)
        c2.pack(side="left", padx=(0, 10))
        tip(c2, "Allow weapons that need no ordnance. Untick it to build with ordnance weapons only.")
        c3 = ttk.Checkbutton(wf, text="Ordnance (missiles, torpedoes)", variable=self.v_ord)
        c3.pack(side="left")
        tip(c3, "Allow weapons that use ordnance (missiles, torpedoes ...); the design then also gets ordnance stores. Untick it to build with energy weapons only.")
        self.label(6, "Research limit", "Leave out modules whose tech path costs more than this (0 = no limit). Keeps a design to early techs.")
        ttk.Entry(self, textvariable=self.v_lim, width=10).grid(row=6, column=1, sticky="w", padx=4)
        bb = tk.Frame(self, bg=PANEL)
        bb.grid(row=7, column=0, columnspan=4, sticky="ew", padx=12, pady=8)
        b = ttk.Button(bb, text="Build a preview", command=self.preview)
        b.pack(side="left")
        tip(b, "Place the modules and show the result and the checks. You can press it again after changing the choices.")
        self.b_create = ttk.Button(bb, text="Create this design", command=self.create, state="disabled")
        self.b_create.pack(side="left", padx=8)
        tip(self.b_create, "Add the design to the mod (staged; Save writes the .design file).")
        ttk.Button(bb, text="Close", command=self.destroy).pack(side="right")
        self.msg = None
        self.sum = DesignSummary(self, view) if view is not None and getattr(view, "ctx", None) else None
        if self.sum is not None:
            self.sum.grid(row=8, column=0, columnspan=4, sticky="nsew", padx=12, pady=(0, 6))
            self.msg = tk.Label(self, text="", bg=PANEL, fg="#e07070", anchor="w", justify="left", wraplength=900)
            self.msg.grid(row=10, column=0, columnspan=4, sticky="ew", padx=12)
            try:
                self.geometry("1100x860")
            except Exception:
                pass
        self.txt = tk.Text(self, width=96, height=30, bg=BG, fg=PEACH, font=("Consolas", 9), relief="flat", wrap="none")
        if self.sum is None:
            self.txt.grid(row=8, column=0, columnspan=4, sticky="nsew", padx=12, pady=(0, 6))
        self.txt.tag_configure("ERROR", foreground="#e07070")
        self.txt.tag_configure("WARN", foreground="#e0b060")
        self.txt.tag_configure("INFO", foreground=DIM)
        tk.Label(self, text=SHIP_RULES_CREDIT, bg=PANEL, fg=DIM, anchor="w").grid(row=9, column=0, columnspan=4, sticky="ew", padx=12, pady=(0, 8))
        self.grid_columnconfigure(3, weight=1)
        self.grid_rowconfigure(8, weight=1)
        self.on_goal()
        self.on_hull()

    def show(self):                      # not modal: the links in the preview jump to the module editor behind this window
        center_on(self, self.master)

    def kinds(self):
        k = tuple(n for n, v in (("energy", self.v_en), ("ordnance", self.v_ord)) if v.get())
        return k or ("energy", "ordnance")

    def _err(self, text):
        if getattr(self, "msg", None) is not None:
            self.msg["text"] = text
        else:
            self.txt.insert("end", text + "\n", "ERROR")

    def on_goal(self):
        self.about["text"] = GEN_GOALS.get(self.v_goal.get(), {}).get("about", "")
        self.b_create.configure(state="disabled")

    def on_hull(self):
        h = self.hulls.get(self.v_hull.get())
        if h is not None:
            if not self.v_style.get().strip():
                self.v_style.set(h.get("Style").strip())
            base = (h.get("VisibleName").strip() or h.path.stem)
            self.v_name.set(self.unique_name("%s %s" % (base, self.v_goal.get().split(" ")[0])))
        self.b_create.configure(state="disabled")

    def unique_name(self, base):
        taken = {d.name.strip().lower() for d in self.proj.load_designs()} | {d.path.stem.lower() for d in self.proj.load_designs()}
        n, name = 1, base
        while name.lower() in taken:
            n += 1
            name = "%s %d" % (base, n)
        return name

    def preview(self):
        h = self.hulls.get(self.v_hull.get())
        self.txt.configure(state="normal")
        self.txt.delete("1.0", "end")
        self.result_text = None
        if self.sum is not None:
            self.sum.clear()
            self.msg["text"] = ""
        if h is None:
            self._err("Pick a hull first.")
            return
        try:
            lim = float(self.v_lim.get() or 0)
        except ValueError:
            lim = 0.0
        try:
            text, notes, di, rep, grid = self.gen.build(h, self.v_goal.get(), self.v_name.get().strip() or "New design", self.v_style.get().strip(),
                                                        self.v_unl.get(), lim, self.kinds())
        except Exception as e:
            log_exc("design generator", sys.exc_info())
            self._err("Could not build a design: %s" % e)
            return
        rows, issues, _nums = rep
        if self.sum is not None:
            self.sum.set_design(di, "%s\non %s" % (self.v_goal.get(), self.v_hull.get()), issues, notes, rows)
            self.result_text = text
            self.b_create.configure(state="disabled" if any(sv == "ERROR" for sv, _t in issues) else "normal")
            return
        self.txt.insert("end", "%s on %s - %d modules placed\n\n" % (self.v_goal.get(), self.v_hull.get(), len(di.slots)), "INFO")
        self.txt.insert("end", grid + "\n\n")
        self.txt.insert("end", "C command  E engine  P power  W weapon  S shield  A armour  H cargo  o ordnance  # other  . empty slot\n\n", "INFO")
        for n in notes:
            self.txt.insert("end", "NOTE  %s\n" % n, "WARN")
        for sv, t in issues:
            self.txt.insert("end", "%-5s %s\n" % ({"ERROR": "ERROR", "WARN": "WARN", "INFO": "info"}.get(sv, sv), t), sv)
        if not issues and not notes:
            self.txt.insert("end", "No problems found.\n", "INFO")
        self.txt.insert("end", "\nWhat the game works out (baseline, no empire bonuses):\n", "INFO")
        for lab, val in rows:
            self.txt.insert("end", "  %-32s %s\n" % (lab, val))
        self.txt.configure(state="disabled")
        self.result_text = text
        bad = any(s == "ERROR" for s, _t in issues)
        self.b_create.configure(state="disabled" if bad else "normal")

    def create(self):
        if not self.result_text:
            return
        name = self.v_name.get().strip()
        style = self.v_style.get().strip() or "NewRace"
        try:
            self.proj.stage_design_text(style, name, self.result_text, "generated design, %s" % self.v_goal.get())
        except ValueError as e:
            messagebox.showwarning("Generate a design", str(e), parent=self)
            return
        self.done = name
        self.destroy()


class DesignImportDialog(_Dialog):
    """Lists the designs the game saved on this computer and copies the chosen ones into the mod's ShipDesigns folder."""

    def __init__(self, master, proj, folder):
        super().__init__(master, "Import new designs")
        self.proj, self.folder, self.rows, self.done = proj, Path(folder), {}, 0
        try:
            self.geometry("%dx%d" % (min(1000, self.winfo_screenwidth() - 60), min(600, self.winfo_screenheight() - 110)))
        except Exception:
            self.geometry("1000x600")
        self.head = tk.Label(self, bg=PANEL, fg=PEACH, anchor="w", justify="left", wraplength=940)
        self.head.pack(fill="x", padx=14, pady=(12, 4))
        nav = tk.Frame(self, bg=PANEL)
        nav.pack(side="bottom", fill="x", padx=14, pady=10)
        ttk.Button(nav, text="Import the selected designs", command=self.do_import).pack(side="right")
        ttk.Button(nav, text="Close", command=self.destroy).pack(side="right", padx=8)
        b = ttk.Button(nav, text="Other folder…", command=self.other)
        b.pack(side="left")
        tip(b, "Look for the saved designs in another folder.")
        fr = tk.Frame(self, bg=PANEL)
        fr.pack(fill="both", expand=True, padx=14)
        self.tv = ttk.Treeview(fr, columns=("hull", "role", "mod", "status", "to"), show="tree headings", selectmode="extended")
        for c, t, w in (("#0", "Design", 200), ("hull", "Hull", 170), ("role", "Role", 80), ("mod", "Made for", 90), ("status", "Status", 160), ("to", "Goes to", 190)):
            self.tv.heading(c, text=t)
            self.tv.column(c, width=w)
        sb = ttk.Scrollbar(fr, orient="vertical", command=self.tv.yview)
        self.tv.configure(yscrollcommand=sb.set)
        sb.pack(side="right", fill="y")
        self.tv.pack(side="left", fill="both", expand=True)
        self.fill()

    def other(self):
        f = filedialog.askdirectory(parent=self, title="Folder with the game's saved designs")
        if f:
            self.folder = Path(f)
            self.fill()

    def fill(self):
        self.tv.delete(*self.tv.get_children())
        self.rows = {}
        cands = self.proj.import_candidates(self.folder)
        modname = self.proj.root.name.lower()
        for i, (di, status, target) in enumerate(cands):
            iid = str(i)
            self.rows[iid] = (di, status, target)
            self.tv.insert("", "end", iid=iid, text=di.name or di.path.stem, values=(di.hull, di.role, di.f.get("ModName", ""), status,
                                                                                    target.relative_to(self.proj.root).as_posix()))
            if status == "new" and di.f.get("ModName", "").strip().lower() in ("", modname):
                self.tv.selection_add(iid)
        n_new = sum(1 for r in self.rows.values() if r[1] == "new")
        self.head["text"] = ("Saved designs in:  %s\n%d design file(s) found, %d new. The new ones made for this mod are already selected. "
                             "Importing copies the file into the mod's ShipDesigns folder now (a design of the same file name is backed up first)." % (
                                 self.folder, len(self.rows), n_new)) if self.rows else ("No .design files found in %s." % self.folder)

    def do_import(self):
        sel = [self.rows[i] for i in self.tv.selection() if i in self.rows]
        if not sel:
            messagebox.showinfo("Import", "Select the designs to import first.", parent=self)
            return
        repl = [r for r in sel if r[1] == "different version in mod"]
        if repl and not messagebox.askyesno("Replace", "%d selected design(s) already exist in the mod in a different version.\n\nReplace them? The old files are "
                                            "backed up in %s first." % (len(repl), BACKUP_DIR), parent=self, icon="warning"):
            sel = [r for r in sel if r[1] != "different version in mod"]
        n = 0
        for di, status, target in sel:
            if status == "same as the mod's":
                continue
            try:
                self.proj.import_design_file(di.path, target)
                n += 1
            except OSError as e:
                messagebox.showwarning("Import", "%s could not be copied: %s" % (di.path.name, e), parent=self)
        self.done = n
        self.destroy()


def planet_label(types, n):
    try:
        n = int(float(n))
    except (TypeError, ValueError):
        return str(n or "")
    nm = types.get(n, ("", None))[0]
    return "%d - %s" % (n, nm) if nm else str(n)


PLAYER_RX = re.compile(r"player|you|reply|response|answer|option|choice|accept|decline|reject|yes|no\\b", re.I)
META_RX = re.compile(r"^(name|id|key|type|index|order|weight|priority|condition|trigger|version)$", re.I)
TEXTY_RX = re.compile(r"text|string|line|dialog|say|index", re.I)


def dialog_scenes(root, resolve=None):
    """Turn any dialogue xml into conversations: [(title, [(side, speaker, text, note)])]. Every element that holds text lines becomes one scene.
    side is 'L' (the race speaking) or 'R' (the player's replies: tags that look like replies / options)."""
    scenes = []

    def label(el):
        for c in el:
            if isinstance(c.tag, str) and META_RX.match(c.tag) and len(c) == 0 and (c.text or "").strip() and c.tag.lower() in ("name", "id", "key", "type"):
                return c.text.strip()
        return ""

    def walk(el, trail):
        leaves = [c for c in el if isinstance(c.tag, str) and len(c) == 0]
        kids = [c for c in el if isinstance(c.tag, str) and len(c) > 0]
        lines = []
        for c in leaves:
            txt = (c.text or "").strip()
            if not txt or META_RX.match(c.tag):
                continue
            note = ""
            if txt.isdigit() and TEXTY_RX.search(c.tag):
                got = resolve(int(txt)) if resolve else None
                if got:
                    note, txt = "text #%s" % txt, got
                else:
                    continue
            elif txt.isdigit() or len(txt) < 3 and " " not in txt:
                continue
            side = "R" if PLAYER_RX.search(c.tag + " " + " ".join(trail)) else "L"
            lines.append((side, c.tag, " ".join(txt.split()), note))
        if lines:
            ttl = " › ".join(trail + ([label(el)] if label(el) and (not trail or trail[-1] != label(el)) else []))
            scenes.append((ttl or el.tag, lines))
        seen = {}
        for c in kids:
            seen[c.tag] = seen.get(c.tag, 0) + 1
        idx = {}
        for c in kids:
            idx[c.tag] = idx.get(c.tag, 0) + 1
            nm = label(c) or (("%s %d" % (c.tag, idx[c.tag])) if seen[c.tag] > 1 else c.tag)
            walk(c, trail + [nm] if trail or el.tag != c.tag else [nm])
    walk(root, [])
    return scenes


DL_TONES = {"friendly": "Friendly", "neutral": "Neutral", "hostile": "Hostile", "default": "", "dl_ruth": "Ruthless", "dl_agg": "Aggressive",
            "dl_xeno": "Xenophobic", "dl_hon": "Honorable", "dl_pac": "Pacifist", "dl_cunn": "Cunning", "dl_ind": "Industrialist",
            "dl_exp": "Expansionist", "dl_mil": "Militarist", "dl_gen": "Generalist", "dl_tech": "Technologist"}


def dialog_parents(names):
    """{index: (parent index, label)}: which situation a situation follows. Racial_Inquiry_1 -> Racial_Response_1, Offer Trade -> Trade Accepted /
    Trade Rejected, HelpUS_War -> HelpUS_War_Yes / _No, Xeno Demand Tech -> ... Accepted. Judged by the names."""
    norm = lambda t: re.sub(r"[\s_]+", " ", (t or "").strip().lower())
    nm = {i: norm(t) for i, t in names.items()}
    out = {}
    for i, c in nm.items():
        best = None
        for j, p in nm.items():
            if j == i or not p:
                continue
            score = label = None
            if "response" in c and c.replace("response", "inquiry") == p:
                score, label = 100, "answers"
            else:
                for cand in {p, p[6:] if p.startswith("offer ") else p}:
                    if cand and c.startswith(cand + " ") and len(c) > len(cand) + 1:
                        if score is None or len(cand) > score:
                            score, label = len(cand), c[len(cand) + 1:].strip().title()
            if score is not None and (best is None or score > best[0]):
                best = (score, j, label)
        if best:
            out[i] = (best[1], best[2])
    return out


def pretty_dialog_type(t):
    t = (t or "").strip()
    if t.isupper() or "_" in t:
        t = t.replace("_", " ").strip().capitalize()
    return t


def diplomacy_scenes(root):
    """The game's real diplomacy format: <DialogLine><DialogType>..</DialogType> then one line per mood (Friendly / Neutral / Hostile / Default)
    or per personality (DL_Ruth, DL_Agg ...). Returns [(title, [(side, label, text, note)])] or None if this is not that format."""
    lines = [e for e in root.iter() if isinstance(e.tag, str) and e.tag == "DialogLine"]
    if not lines:
        return None
    out = []
    for dl in lines:
        ttl = pretty_dialog_type(next(((c.text or "") for c in dl if c.tag == "DialogType"), "")) or "(no type)"
        ls = []
        for c in dl:
            if not isinstance(c.tag, str) or c.tag == "DialogType" or not (c.text or "").strip():
                continue
            lab = DL_TONES.get(c.tag.lower(), c.tag)
            ls.append(("L", lab or "Says", " ".join(c.text.split()), c.tag if lab and lab != c.tag else ""))
        if ls:
            out.append((ttl, ls))
    return out


class DialogueWindow(tk.Toplevel):
    """A race's diplomacy dialogue file shown as a conversation: the race on the left, the player's replies on the right."""

    def __init__(self, master, view, race, path):
        super().__init__(master)
        self.title("Diplomacy - %s" % (race.name() or race.path.stem))
        self.configure(bg=PANEL)
        self.view, self.race, self.path = view, race, path
        try:
            self.geometry("%dx%d" % (min(900, self.winfo_screenwidth() - 80), min(760, self.winfo_screenheight() - 110)))
        except Exception:
            pass
        P_ = view.proj
        try:
            root = ET.fromstring(read_file(path)[0].encode("utf-8"))
            self.scenes = diplomacy_scenes(root)
            if self.scenes is None:
                self.scenes = dialog_scenes(root, lambda n: self.lookup(P_, n))
            self.err = ""
        except Exception as e:
            self.scenes, self.err = [], str(e)
        top = tk.Frame(self, bg=PANEL)
        top.pack(fill="x", padx=12, pady=(10, 4))
        tk.Label(top, text="%s   -   %s" % (race.name() or race.path.stem, path.name), bg=PANEL, fg=ORANGE, font=("Segoe UI", 13, "bold"), anchor="w").pack(side="left")
        self.q = tk.StringVar()
        e = ttk.Entry(top, textvariable=self.q, width=26)
        e.pack(side="right")
        tk.Label(top, text="Find", bg=PANEL, fg=DIM).pack(side="right", padx=6)
        self.q.trace_add("write", lambda *_a: self.draw())
        tip(e, "Show only the parts of the conversation with these words.")
        self.note = tk.Label(self, bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=840)
        self.note.pack(fill="x", padx=12)
        self.sf = ScrollFrame(self, bg=PANEL)
        self.sf.pack(fill="both", expand=True, padx=8, pady=8)
        self.pic = None
        pp = view.pic(race)
        if pp:
            self.pic = view.img(pp, 40)
        self.draw()

    @staticmethod
    def lookup(P_, n):
        e = (P_.text.by_id.get(n) if P_.text else None) or P_.ext_by_id.get(n)
        return (e.get("ENG").strip() if e else "") or None

    def draw(self):
        self.sf.clear()
        body = self.sf.inner
        words = self.q.get().lower().split()
        shown = 0
        if self.err:
            self.note["text"] = "The file could not be read as xml: %s" % self.err
        for title, lines in self.scenes:
            if words and not all(w in (title + " " + " ".join(l[2] for l in lines)).lower() for w in words):
                continue
            shown += 1
            tk.Label(body, text=title, bg=PANEL, fg=PEACH, anchor="w", font=("Segoe UI", 10, "bold")).pack(fill="x", padx=6, pady=(14, 2))
            for side, spk, txt, note in lines:
                row = tk.Frame(body, bg=PANEL)
                row.pack(fill="x", padx=6, pady=2)
                bcol = SEL if side == "R" else PANEL2
                bub = tk.Frame(row, bg=bcol, padx=10, pady=6)
                if side == "R":
                    bub.pack(side="right")
                else:
                    if self.pic is not None:
                        tk.Label(row, image=self.pic, bg=PANEL).pack(side="left", padx=(0, 6), anchor="n")
                    bub.pack(side="left")
                tk.Label(bub, text=spk + ("   (%s)" % note if note else ""), bg=bcol, fg=DIM, anchor="w", font=("Segoe UI", 8)).pack(fill="x")
                tk.Label(bub, text=txt, bg=bcol, fg=FG, anchor="w", justify="left", wraplength=560).pack(fill="x")
        if not self.err:
            self.note["text"] = ("%d conversation part(s). Lines from the race are on the left, the player's replies on the right; the small grey label is the tag the line "
                                 "came from." % shown) if self.scenes else "No readable lines were found in this file."


