def weights_to_counts(items):
    """['A','B','A'] -> (['A','B'], {'A': 2, 'B': 1}): the game picks a trait by chance from the list, so a value listed twice is twice as likely."""
    order, counts = [], {}
    for v in items:
        if v not in counts:
            order.append(v)
            counts[v] = 0
        counts[v] += 1
    return order, counts


def counts_to_weights(order, counts):
    return [v for v in order for _ in range(max(0, counts.get(v, 0)))]


def ring_get(ring, tag, default=""):
    return next((v for t, v in ring if t == tag), default)


def ring_set(ring, tag, value):
    """A ring (tuple of (tag, value)) with `tag` set; '' removes the tag. Tags this editor does not know stay where they were."""
    out, done = [], False
    for t, v in ring:
        if t == tag:
            done = True
            if value != "":
                out.append((t, value))
        else:
            out.append((t, v))
    if not done and value != "":
        out.append((tag, value))
    return tuple(out)


def ring_kind(ring):
    if ring_get(ring, "Asteroids").strip().lower() in ("yes", "true"):
        return "Asteroid belt"
    if ring_get(ring, "HomePlanet").strip().lower() in ("yes", "true"):
        return "★ Home planet"
    if ring_get(ring, "Planet"):
        return "Planet"
    return "Empty ring"


