def ai_weights(scores, names, cap=5):
    """scores {value: nudge} -> (order, counts) over `names`: every value starts at weight 1, nudges move it, 0 removes it, at most `cap`;
    at least three values always stay so the AI keeps some variety."""
    w = {n: max(0, min(cap, 1 + scores.get(n, 0))) for n in names}
    if sum(1 for v in w.values() if v > 0) < 3:
        for n in sorted(names, key=lambda n: -scores.get(n, 0)):
            if w[n] == 0:
                w[n] = 1
            if sum(1 for v in w.values() if v > 0) >= 3:
                break
    order = [n for n in names if w[n] > 0]
    return order, {n: w[n] for n in order}


class WeightEditor(tk.Frame):
    """A list of values where a value listed several times is more likely (the game's trait weights): value | times listed."""

    def __init__(self, master, view, key, title, hint, choices):
        super().__init__(master, bg=PANEL2)
        self.view, self.key, self.choices = view, key, choices
        tk.Label(self, text=title, bg=PANEL2, fg=PEACH, anchor="w", font=("Segoe UI", 9, "bold")).pack(fill="x")
        self.tv = ttk.Treeview(self, columns=("w", "chance"), show="tree headings", height=7, selectmode="browse")
        self.tv.heading("#0", text="Value")
        self.tv.heading("w", text="Weight")
        self.tv.heading("chance", text="Chance")
        self.tv.column("#0", width=170)
        self.tv.column("w", width=60, anchor="center")
        self.tv.column("chance", width=70, anchor="center")
        self.tv.pack(fill="x")
        tip(self.tv, hint)
        self.tv.bind("<Button-3>", self.ctx)
        bf = tk.Frame(self, bg=PANEL2)
        bf.pack(fill="x", pady=2)
        for text, cmd, h in (("＋ Add…", self.add, "Add a value (pick one the other races use, or type your own)."),
                             ("▲ Weight", lambda: self.bump(1), "List the selected value one more time = more likely."),
                             ("▼ Weight", lambda: self.bump(-1), "List it one time less (the last one removes it)."),
                             ("Remove", self.remove, "Take the selected value out completely.")):
            b = ttk.Button(bf, text=text, command=cmd)
            b.pack(side="left", padx=(0, 3))
            tip(b, h)
        self.refresh()

    def ctx(self, ev):
        iid = self.tv.identify_row(ev.y)
        if iid:
            self.tv.selection_set(iid)
        m = tk.Menu(self, tearoff=0, **MENU_OPTS)
        has = bool(iid)
        m.add_command(label="＋ Add…", command=self.add)
        m.add_command(label="▲ More likely (weight +1)", command=lambda: self.bump(1), state="normal" if has else "disabled")
        m.add_command(label="▼ Less likely (weight -1)", command=lambda: self.bump(-1), state="normal" if has else "disabled")
        m.add_command(label="Remove", command=self.remove, state="normal" if has else "disabled")
        popup(m, ev)

    def items(self):
        return self.view.cur.lists.get(self.key, [])

    def refresh(self, keep=None):
        self.tv.delete(*self.tv.get_children())
        order, counts = weights_to_counts(self.items())
        total = float(sum(counts.values())) or 1.0
        for v in order:
            self.tv.insert("", "end", iid=v, text=v, values=(counts[v], "%d%%" % round(100 * counts[v] / total)))
        if keep and self.tv.exists(keep):
            self.tv.selection_set(keep)

    def put(self, order, counts, keep=None):
        self.view.cur.lists[self.key] = counts_to_weights(order, counts)
        self.refresh(keep)
        self.view.after_edit()

    def sel(self):
        s = self.tv.selection()
        return s[0] if s else None

    def add(self):
        v = ask_choice(self, "Add", "Value to add:", [c for c in self.choices() if c not in self.items()])
        if not v:
            return
        order, counts = weights_to_counts(self.items())
        if v not in counts:
            order.append(v)
            counts[v] = 0
        counts[v] += 1
        self.put(order, counts, v)

    def bump(self, d):
        v = self.sel()
        if v is None:
            return
        order, counts = weights_to_counts(self.items())
        counts[v] = counts.get(v, 0) + d
        if counts[v] <= 0:
            order.remove(v)
            counts.pop(v)
            v = None
        self.put(order, counts, v)

    def remove(self):
        v = self.sel()
        if v is None:
            return
        order, counts = weights_to_counts(self.items())
        order.remove(v)
        counts.pop(v)
        self.put(order, counts)


class TraitPickDialog(_Dialog):
    """The game's racial trait list: name, category, point cost and description for every trait, searchable and filterable, with the race's points total
    updating as traits are ticked. result = [trait names]."""

    def __init__(self, master, proj, have, limit=None, title="Add traits"):
        super().__init__(master, title)
        try:
            sw, sh = int(self.winfo_screenwidth()), int(self.winfo_screenheight())
        except Exception:
            sw, sh = 1400, 900
        w, h = min(1250, int(sw * 0.9)), min(800, int(sh * 0.88))
        self.geometry("%dx%d+%d+%d" % (w, h, max(0, (sw - w) // 2), max(0, (sh - h) // 2 - 20)))
        self.minsize(760, 460)
        self.proj, self.have, self.limit, self.result = proj, list(have), limit, []
        self.costs = proj.trait_costs()
        td = proj.traits_doc()
        self.rows = []                                              # (name, shown name, category, cost, description, excludes)
        seen = set()
        for it in (td.lists["traits"] if td is not None else []):
            nm = trait_get(it, "TraitName")
            if not nm or nm in seen:
                continue
            seen.add(nm)
            nt, ds = self.text_of(trait_get(it, "TraitIndex")), self.text_of(trait_get(it, "Description"))
            cost = self.costs.get(nm)
            self.rows.append((nm, nt or nm, trait_get(it, "Category"), cost, ds or trait_describe(nt or nm, it), tuple(trait_get(it, "Excludes", ()))))
        for nm in sorted({n for n in proj.trait_names() if n not in seen}, key=str.lower):      # traits only races mention
            self.rows.append((nm, nm, "", self.costs.get(nm), "(no definition for this trait was found in the trait file)", ()))
        bt = tk.Frame(self, bg=PANEL)
        bt.pack(side="bottom", fill="x", padx=14, pady=10)
        self.ok_btn = ttk.Button(bt, text="Add the ticked traits", style="Save.TButton", command=self.ok)
        self.ok_btn.pack(side="right")
        ttk.Button(bt, text="Cancel", command=self.destroy).pack(side="right", padx=8)
        self.sum = tk.Label(bt, bg=PANEL, fg=PEACH, anchor="w", justify="left", wraplength=700)
        self.sum.pack(side="left", fill="x", expand=True)
        top = tk.Frame(self, bg=PANEL)
        top.pack(fill="x", padx=14, pady=(12, 4))
        tk.Label(top, text="Search", bg=PANEL, fg=DIM).pack(side="left")
        self.flt = tk.StringVar()
        e = ttk.Entry(top, textvariable=self.flt, width=34)
        e.pack(side="left", padx=6)
        e.focus_set()
        tip(e, "Type part of a trait name, category or description; several words must all match.")
        self.flt.trace_add("write", lambda *_a: self.fill())
        tk.Label(top, text="Category", bg=PANEL, fg=DIM).pack(side="left", padx=(12, 0))
        self.cat = tk.StringVar(value="(all)")
        cats = ["(all)"] + sorted({r[2] for r in self.rows if r[2]}, key=str.lower)
        cb = ttk.Combobox(top, textvariable=self.cat, values=cats, state="readonly", width=16)
        cb.pack(side="left", padx=6)
        cb.bind("<<ComboboxSelected>>", lambda _e: self.fill())
        self.only = tk.IntVar(value=0)
        ck = ttk.Checkbutton(top, text="Hide traits already on the race", variable=self.only, command=self.fill)
        ck.pack(side="left", padx=10)
        tip(ck, "Leave out the traits this race already has.")
        self.cnt = tk.Label(top, bg=PANEL, fg=DIM)
        self.cnt.pack(side="right")
        fr = tk.Frame(self, bg=PANEL)
        fr.pack(fill="both", expand=True, padx=14, pady=4)
        self.tv = ttk.Treeview(fr, columns=("cat", "pts", "desc"), show="tree headings", selectmode="extended")
        for c, t, wd, st in (("cat", "Category", 110, False), ("pts", "Points", 60, False), ("desc", "Description", 640, True)):
            self.tv.heading(c, text=t)
            self.tv.column(c, width=wd, anchor="center" if c == "pts" else "w", stretch=st)
        self.tv.heading("#0", text="Trait")
        self.tv.column("#0", width=210, stretch=False)
        sb = ttk.Scrollbar(fr, orient="vertical", command=self.tv.yview)
        self.tv.configure(yscrollcommand=sb.set)
        sb.pack(side="right", fill="y")
        self.tv.pack(side="left", fill="both", expand=True)
        self.tv.bind("<<TreeviewSelect>>", lambda _e: self.on_sel())
        self.tv.bind("<Double-Button-1>", lambda _e: self.ok())
        tip(self.tv, "Click a trait (Ctrl / Shift for several). Its full description and what it excludes show below. Double-click to add it straight away.")
        self.det = tk.Text(self, height=5, wrap="word", bg=PANEL2, fg=FG, relief="flat", padx=8, pady=6, font=("Segoe UI", 10))
        self.det.pack(fill="x", padx=14, pady=4)
        self.det.configure(state="disabled")
        self.shown = []
        self.fill()
        self.bind("<Return>", lambda _e: self.ok())
        self.bind("<Escape>", lambda _e: self.destroy())

    def text_of(self, tid):
        tid = str(tid).strip()
        if not tid.isdigit():
            return ""
        e = self.proj.text_display_by_id(int(tid))
        try:
            return (e.get("ENG") if e is not None else "") or ""
        except Exception:
            return ""

    def row(self, name):
        return next((r for r in self.rows if r[0] == name), None)

    def fill(self):
        words = self.flt.get().lower().split()
        cat = self.cat.get()
        self.tv.delete(*self.tv.get_children())
        self.shown = []
        for r in self.rows:
            nm, shown, c, cost, desc, ex = r
            if cat != "(all)" and c != cat:
                continue
            if self.only.get() and nm in self.have:
                continue
            hay = (nm + " " + shown + " " + c + " " + desc).lower()
            if not all(w in hay for w in words):
                continue
            self.shown.append(r)
            on = "  ✔" if nm in self.have else ""
            self.tv.insert("", "end", iid=str(len(self.shown) - 1), text="  " + (shown if shown == nm else "%s (%s)" % (shown, nm)) + on,
                           values=(c, fmtv(cost) if cost is not None else "?", " ".join(desc.split())))
        self.cnt.configure(text="%d of %d traits" % (len(self.shown), len(self.rows)))
        self.on_sel()

    def picked(self):
        return [self.shown[int(i)][0] for i in self.tv.selection() if str(i).isdigit() and int(i) < len(self.shown)]

    def conflicts(self, names):
        """Pairs that exclude each other among the traits already on the race and the ticked ones."""
        allv = self.have + [n for n in names if n not in self.have]
        out = []
        for n in names:
            r = self.row(n)
            for o in allv:
                ro = self.row(o)
                if o != n and ((r and o in r[5]) or (ro and n in ro[5])):
                    out.append("%s  excludes / is excluded by  %s" % (n, o))
        return out

    def on_sel(self):
        names = [n for n in self.picked() if n not in self.have]
        tot = sum(self.costs.get(n, 0.0) for n in self.have + names)
        add = sum(self.costs.get(n, 0.0) for n in names)
        txt = "Points now: %s" % fmtv(sum(self.costs.get(n, 0.0) for n in self.have))
        if names:
            txt = "Ticked: %d trait(s), %s points  ->  total %s" % (len(names), fmtv(add), fmtv(tot))
        bad = False
        if self.limit:
            txt += "   of  %s allowed" % fmtv(self.limit[1])
            bad = tot > self.limit[1]
            if bad:
                txt += "   ✖ over by %s" % fmtv(tot - self.limit[1])
        cf = self.conflicts(names)
        if cf:
            txt += "\n✖ " + "; ".join(cf[:3])
        self.sum.configure(text=txt, fg="#e07070" if bad or cf else PEACH)
        self.ok_btn.configure(state="normal" if names else "disabled")
        sel = self.picked()
        self.det.configure(state="normal")
        self.det.delete("1.0", "end")
        if sel:
            r = self.row(sel[-1])
            self.det.insert("1.0", "%s%s   |   %s points%s\n\n%s%s" % (
                r[1], "" if r[1] == r[0] else " (%s)" % r[0], fmtv(r[3]) if r[3] is not None else "?", ("   |   " + r[2]) if r[2] else "",
                r[4], ("\n\nCannot be combined with: " + ", ".join(r[5])) if r[5] else ""))
        self.det.configure(state="disabled")

    def ok(self):
        names = [n for n in self.picked() if n not in self.have]
        if not names:
            return
        cf = self.conflicts(names)
        if cf and not messagebox.askyesno("Traits exclude each other", "\n".join(cf[:6]) + "\n\nAdd them anyway?", icon="warning", default="no", parent=self):
            return
        tot = sum(self.costs.get(n, 0.0) for n in self.have + names)
        if self.limit and self.costs and tot > self.limit[1]:
            if not messagebox.askyesno("Over the points limit", "That makes %s points, over the limit of %s (%s).\n\nAdd them anyway?" % (fmtv(tot), fmtv(self.limit[1]), self.limit[0]),
                                       icon="warning", default="no", parent=self):
                return
        self.result = names
        self.destroy()


class VideoPreview(tk.Frame):
    """A small player for a race's diplomacy video. Plays the real video file through ffmpeg when it is installed (picture only, no sound), shows a still frame
    otherwise, and always offers 'Open in player' (Windows' own player, with sound)."""
    W, H, FPS = 400, 225, 15

    def __init__(self, master, proj):
        super().__init__(master, bg=PANEL2)
        self.proj, self.stem, self.src, self.run, self.q, self.img = proj, "", None, 0, None, None
        self.lb = tk.Label(self, bg="#000000", fg=DIM, width=50, height=14, text="no video", compound="center")
        self.lb.pack()
        bf = tk.Frame(self, bg=PANEL2)
        bf.pack(fill="x", pady=4)
        self.pb = ttk.Button(bf, text="▶ Play", command=self.toggle)
        self.pb.pack(side="left")
        tip(self.pb, "Plays the video in this box (the picture only - the editor has no sound). Needs ffmpeg installed; without it use Open in player.")
        b = ttk.Button(bf, text="Open in player", command=self.external)
        b.pack(side="left", padx=6)
        tip(b, "Opens the video file in your computer's own video player, with sound.")
        self.st = tk.Label(self, bg=PANEL2, fg=DIM, anchor="w", justify="left", wraplength=self.W)
        self.st.pack(fill="x")

    def ffmpeg(self):
        return shutil.which("ffmpeg")

    def set_stem(self, stem):
        self.stop()
        self.stem = stem
        srcs = self.proj.video_sources(stem)
        self.src = srcs[0] if srcs else None
        if self.src is None:
            self.lb.configure(image="", text="no video file found\nfor '%s'" % (stem or "-"))
            self.st.configure(text="The game loads the compiled .xnb; the video file it points at (.wmv ...) was not found in the mod, the base game or the other mods.")
            self.pb.configure(state="disabled")
            return
        self.pb.configure(state="normal")
        self.st.configure(text="%s   (%s)" % (self.src.name, self.src.parent.name))
        self.poster()

    def cmd(self, extra, loop=False):
        c = [self.ffmpeg(), "-v", "error"] + (["-stream_loop", "-1"] if loop else []) + extra[:1] + ["-i", str(self.src)] + extra[1:]
        return c + ["-vf", "scale=%d:%d" % (self.W, self.H), "-an"]

    def poster(self):
        if not self.ffmpeg() or self.src is None:
            self.lb.configure(image="", text="(preview needs ffmpeg)\nuse Open in player")
            return
        try:
            c = self.cmd(["-ss", "1", "-frames:v", "1"]) + ["-f", "image2pipe", "-vcodec", "ppm", "-"]
            data = subprocess.run(c, capture_output=True, timeout=20).stdout
            if not data:
                c = self.cmd(["-ss", "0", "-frames:v", "1"]) + ["-f", "image2pipe", "-vcodec", "ppm", "-"]
                data = subprocess.run(c, capture_output=True, timeout=20).stdout
            self.show_ppm(data)
        except Exception as e:
            self.lb.configure(image="", text="could not read a frame:\n%s" % e)

    def show_ppm(self, data):
        if not data:
            return
        self.img = tk.PhotoImage(data=data)
        self.lb.configure(image=self.img, text="")

    def toggle(self):
        if self.run:
            self.stop()
        else:
            self.play()

    def play(self):
        if self.src is None:
            return
        if not self.ffmpeg():
            self.external()
            return
        self.run += 1
        gen = self.run
        import queue
        self.q = queue.Queue(maxsize=6)
        self.pb.configure(text="■ Stop")
        size = self.W * self.H * 3
        c = self.cmd([], loop=True) + ["-r", str(self.FPS), "-f", "rawvideo", "-pix_fmt", "rgb24", "-"]

        def reader():
            try:
                pr = subprocess.Popen(c, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
                hdr = b"P6\n%d %d\n255\n" % (self.W, self.H)
                while self.run == gen:
                    buf = pr.stdout.read(size)
                    if len(buf) < size:
                        break
                    self.q.put(hdr + buf)
                pr.kill()
            except Exception:
                pass
            if self.run == gen:
                self.q.put(None)
        threading.Thread(target=reader, daemon=True).start()
        self.pump(gen)

    def pump(self, gen):
        if self.run != gen:
            return
        try:
            f = self.q.get_nowait()
        except Exception:
            f = b""
        if f is None:
            self.stop()
            return
        if f:
            try:
                self.show_ppm(f)
            except tk.TclError:
                self.run += 1
                return
        self.after(int(1000 / self.FPS), lambda: self.pump(gen))

    def stop(self):
        self.run += 1
        self.pb.configure(text="▶ Play")

    def external(self):
        if self.src is None:
            return
        try:
            if hasattr(os, "startfile"):
                os.startfile(str(self.src))
            else:
                subprocess.Popen(["xdg-open", str(self.src)])
        except Exception as e:
            messagebox.showwarning("Video", "Could not open the video: %s" % e)

    def destroy(self):
        self.run += 1
        super().destroy()


class StringListEditor(tk.Frame):
    """An ordered list of text values (a race's racial traits): add, remove, move."""

    def __init__(self, master, view, key, title, hint, choices):
        super().__init__(master, bg=PANEL2)
        self.view, self.key, self.choices = view, key, choices
        tk.Label(self, text=title, bg=PANEL2, fg=PEACH, anchor="w", font=("Segoe UI", 9, "bold")).pack(fill="x")
        self.tv = ttk.Treeview(self, columns=("pts",), show="tree headings", height=10, selectmode="browse")
        self.tv.heading("#0", text="Trait")
        self.tv.heading("pts", text="Points")
        self.tv.column("#0", width=300)
        self.tv.column("pts", width=70, anchor="center")
        self.tv.pack(fill="x")
        self.sum_lb = tk.Label(self, bg=PANEL2, fg=DIM, anchor="w", justify="left", wraplength=420)
        self.sum_lb.pack(fill="x")
        tip(self.tv, hint)
        self.tv.bind("<Button-3>", self.ctx)
        bf = tk.Frame(self, bg=PANEL2)
        bf.pack(fill="x", pady=2)
        for text, cmd, h in (("＋ Add…", self.add, "Add a trait (pick one the other races use, or type your own)."),
                             ("▲", lambda: self.move(-1), "Move up"), ("▼", lambda: self.move(1), "Move down"),
                             ("Remove", self.remove, "Take the selected trait out.")):
            b = ttk.Button(bf, text=text, command=cmd, width=8 if len(text) < 3 else None)
            b.pack(side="left", padx=(0, 3))
            tip(b, h)
        self.refresh()

    def ctx(self, ev):
        iid = self.tv.identify_row(ev.y)
        if iid:
            self.tv.selection_set(iid)
        m = tk.Menu(self, tearoff=0, **MENU_OPTS)
        has = bool(iid)
        m.add_command(label="＋ Add…", command=self.add)
        m.add_command(label="▲ Move up", command=lambda: self.move(-1), state="normal" if has else "disabled")
        m.add_command(label="▼ Move down", command=lambda: self.move(1), state="normal" if has else "disabled")
        m.add_command(label="Remove", command=self.remove, state="normal" if has else "disabled")
        popup(m, ev)

    def items(self):
        return self.view.cur.lists.get(self.key, [])

    def refresh(self, keep=None):
        self.tv.delete(*self.tv.get_children())
        costs = self.view.proj.trait_costs()
        for i, v in enumerate(self.items()):
            self.tv.insert("", "end", iid=str(i), text=v, values=(fmtv(costs[v]) if v in costs else "?",))
        if keep is not None and self.tv.exists(str(keep)):
            self.tv.selection_set(str(keep))
        self.show_sum()

    def total(self, items=None):
        costs = self.view.proj.trait_costs()
        return sum(costs.get(v, 0.0) for v in (self.items() if items is None else items))

    def show_sum(self):
        lim = self.view.proj.trait_limit()
        costs = self.view.proj.trait_costs()
        unk = [v for v in self.items() if v not in costs]
        tot = self.total()
        if not self.items():
            self.sum_lb.configure(fg=DIM, text="No traits chosen. That is fine for a race players cannot pick (pirate-style races such as Remnant, Corsairs or the Orion Syndicate).")
            return
        if not costs:
            self.sum_lb.configure(fg=DIM, text="Trait point costs were not found in the game files (looked for a Name + Cost in xml / yaml files)."
                                  + ("  Limit: %s = %s (%s)." % (lim[0], fmtv(lim[1]), lim[2]) if lim else "  No points limit found in Globals.yaml."))
            return
        txt = "Points used: %s" % fmtv(tot)
        bad = False
        if lim:
            txt += "  of  %s   (%s in %s)" % (fmtv(lim[1]), lim[0], lim[2])
            bad = tot > lim[1]
            if bad:
                txt += "   ✖ over the limit by %s" % fmtv(tot - lim[1])
        else:
            txt += "   (no points limit found in Globals.yaml)"
        if unk:
            txt += "\n%d trait(s) with no known cost (?)" % len(unk)
        self.sum_lb.configure(fg="#e07070" if bad else PEACH, text=txt)

    def sel(self):
        s = self.tv.selection()
        return int(s[0]) if s else None

    def put(self, items, keep=None):
        self.view.cur.lists[self.key] = items
        self.refresh(keep)
        self.view.after_edit()

    def add(self):
        if self.key.startswith("traits"):                           # the game's trait list: points, category and description for each
            dlg = TraitPickDialog(self, self.view.proj, self.items(), self.view.proj.trait_limit())
            dlg.show()
            self.wait_window(dlg)
            if dlg.result:
                self.put(self.items() + dlg.result, len(self.items()))
            return
        costs = self.view.proj.trait_costs()
        labelled = ["%s   [%s pts]" % (c, fmtv(costs[c])) if c in costs else c for c in self.choices() if c not in self.items()]
        v = ask_choice(self, "Add", "Item to add:", labelled)
        v = re.sub(r"\s+\[-?[\d.]+ pts\]$", "", v or "")
        if not v:
            return
        self.put(self.items() + [v], len(self.items()))

    def remove(self):
        i = self.sel()
        if i is not None:
            self.put(self.items()[:i] + self.items()[i + 1:], min(i, len(self.items()) - 2) if len(self.items()) > 1 else None)

    def move(self, d):
        i = self.sel()
        its = list(self.items())
        if i is None or not 0 <= i + d < len(its):
            return
        its[i], its[i + d] = its[i + d], its[i]
        self.put(its, i + d)


class GameDocView(ImageCache, ttk.Frame):
    """Base of the Races / Troops / Solar systems screens: a searchable list on the left, an editor for the selected file on the right."""
    KIND, WHAT, ALL = "races", "race", "(all)"
    COLS = (("name", "Name", 170), ("extra", "", 110), ("src", "From", 60))
    LABEL_W = 22

    def __init__(self, master, app, tab):
        super().__init__(master)
        self.app, self.proj, self.tab = app, app.proj, tab
        self.cur, self.items, self.imgs, self.vars, self.widgets, self._filled = None, {}, {}, {}, {}, False
        left = tk.Frame(self, bg=PANEL, width=self.LEFT_W)
        left.pack(side="left", fill="y")
        left.pack_propagate(False)
        bar = tk.Frame(left, bg=PANEL)                              # same layout as the Ships tab: a full-width orange New, then Copy / Delete as an equal pair
        bar.pack(fill="x", padx=8, pady=8)
        bar.columnconfigure(0, weight=1, uniform="gdbtn")
        bar.columnconfigure(1, weight=1, uniform="gdbtn")
        b = ttk.Button(bar, text="＋  New %s…" % self.WHAT, style="Save.TButton", command=self.new)
        b.grid(row=0, column=0, columnspan=2, sticky="ew", pady=(0, 4))
        tip(b, "Make a new %s." % self.WHAT)
        for col, (text, cmd, hint) in enumerate((("Copy existing %s…" % self.WHAT, self.copy, "Start a new %s from the selected one (all its settings are copied)." % self.WHAT),
                                                 ("Delete…", self.delete, "Delete the selected %s (mod files only). Asks first; Undo / Recycle Bin bring it back." % self.WHAT))):
            b = ttk.Button(bar, text=text, command=cmd)
            b.grid(row=1, column=col, sticky="ew", padx=(0, 3) if col == 0 else (3, 0))
            tip(b, hint)
        xb = self.extra_buttons()
        for i, (text, cmd, hint) in enumerate(xb):                  # extra buttons: full width, one per row
            b = ttk.Button(bar, text=text, command=cmd)
            b.grid(row=2 + i, column=0, columnspan=2, sticky="ew", pady=(4, 0))
            tip(b, hint)
        self.flt = tk.StringVar()
        e = ttk.Entry(left, textvariable=self.flt)
        e.pack(fill="x", padx=8)
        self.flt.trace_add("write", lambda *_a: self.fill())
        tip(e, "Type part of a name or file name to narrow the list.\nSeveral words must all match.")
        fb = tk.Frame(left, bg=PANEL)                               # the filters in equal columns, like the Ships tab
        fb.pack(fill="x", padx=8, pady=(6, 0))
        fb.columnconfigure(0, weight=1, uniform="gdflt")
        fb.columnconfigure(1, weight=1, uniform="gdflt")
        self.f_src, self.f_a = tk.StringVar(value=self.ALL), tk.StringVar(value=self.ALL)
        c0 = tk.Frame(fb, bg=PANEL)
        c0.grid(row=0, column=0, sticky="w", pady=2)
        self.cb_src = filter_combo(c0, "From", self.f_src, "Show only the files that live in your mod (\"mod\"), or only the ones that come with the base game (\"base game\").", 11, self.fill, [self.ALL, "mod", "base game"], label_width=5)
        self.cb_a = None
        if self.FILTER_A:
            c1 = tk.Frame(fb, bg=PANEL)
            c1.grid(row=0, column=1, sticky="w", pady=2)
            self.cb_a = filter_combo(c1, self.FILTER_A, self.f_a, "Show only one %s." % self.FILTER_A.lower(), 13, self.fill, [self.ALL], label_width=5)
        self.count_tip = "How many of the files match the search box and the filters, out of all of them."
        self.count = tk.Label(left, bg=PANEL, fg=DIM, anchor="w")
        self.count.pack(fill="x", padx=10)
        tip(self.count, self.count_tip)
        fr = tk.Frame(left, bg=PANEL)
        fr.pack(fill="both", expand=True, padx=8, pady=8)
        self.tv = ttk.Treeview(fr, columns=[c[0] for c in self.COLS[1:]], show="tree headings", selectmode="browse", style="Icons.Treeview")
        icons_style()
        self.tv.heading("#0", text=self.COLS[0][1])
        self.tv.column("#0", width=self.COLS[0][2])
        for c, t, w in self.COLS[1:]:
            self.tv.heading(c, text=t)
            self.tv.column(c, width=w, anchor="w")
        sb = ttk.Scrollbar(fr, orient="vertical", command=self.tv.yview)
        self.tv.configure(yscrollcommand=sb.set)
        sb.pack(side="right", fill="y")
        self.tv.pack(side="left", fill="both", expand=True)
        self.tv.bind("<<TreeviewSelect>>", lambda _e: self.on_pick())
        self.tv.bind("<Button-3>", self.ctx)
        self.tv.bind("<Button-2>", self.ctx)
        self.sf = ScrollFrame(self, bg=PANEL2)
        self.sf.pack(side="left", fill="both", expand=True)
        self.blank = tk.PhotoImage(width=34, height=34)
        self.show(None)

    FILTER_A = ""
    PIC_SUB, PIC_FIELD = "", ""
    LEFT_W = 460

    def extra_buttons(self):
        return ()

    def change_pic(self, d=None):
        d = d or self.cur
        if d is None or not self.PIC_SUB:
            return
        dlg = PicDialog(self, self.proj, self, self.PIC_SUB, "Change picture of %s" % (d.name() or d.path.stem), d.name() or d.path.stem,
                        "%s: %s" % (getattr(self, "WHAT", "item"), d.name() or d.path.stem))
        dlg.show()
        self.wait_window(dlg)
        if not dlg.result:
            return
        k, path = dlg.result
        stem = k
        if k == "__import":
            stem = re.sub(r"[^\w\-]+", "_", Path(path).stem).strip("_") or "picture"
            try:
                self.proj.stage_copy(path, self.PIC_SUB, stem)
            except ValueError as e:
                messagebox.showwarning("Picture", str(e), parent=self)
                return
        d.set(self.PIC_FIELD, stem)
        self.proj._icons.clear()
        self.after_edit()
        self.show(d)
        self.fill(d)

    def pic_menu(self, ev, d):
        m = tk.Menu(self, tearoff=0, **MENU_OPTS)
        m.add_command(label="Change picture…", command=lambda: self.change_pic(d))
        m.add_command(label="Pick a picture file on this computer…", command=lambda: self.browse_pic(self.PIC_FIELD, self.PIC_SUB, "picture", refresh=True))
        m.add_command(label="Make a picture with an AI…", command=lambda: self.ai_pic(self.PIC_FIELD, self.PIC_SUB, "picture", refresh=True))
        m.add_command(label="Clear the picture", command=lambda: (d.set(self.PIC_FIELD, ""), self.after_edit(), self.show(d), self.fill(d)),
                      state="normal" if d.get(self.PIC_FIELD) else "disabled")
        popup(m, ev)

    def label_of(self, d):
        return "  " + (d.name() or d.path.stem)

    # ---- right-click menu
    def menu_items(self, d):
        """[(label, command, enabled)] or None for a separator; views add their own."""
        return []

    def ctx(self, ev):
        iid = self.tv.identify_row(ev.y)
        if iid and iid in self.items:
            self.tv.selection_set(iid)
            d = self.items[iid]
            if d is not self.cur:
                self.show(d)
        else:
            d = self.cur if iid else None
        m = tk.Menu(self, tearoff=0, **MENU_OPTS)
        if d is None:
            m.add_command(label="＋ New %s…" % self.WHAT, command=self.new)
        else:
            m.add_command(label="＋ New %s…" % self.WHAT, command=self.new)
            m.add_command(label="Copy %s…" % self.WHAT, command=self.copy)
            if self.PIC_SUB:
                m.add_command(label="Change picture…", command=lambda: self.change_pic(d))
            for it in self.menu_items(d):
                if it is None:
                    m.add_separator()
                else:
                    m.add_command(label=it[0], command=it[1], state="normal" if it[2] else "disabled")
            m.add_separator()
            m.add_command(label="Revert changes in this file", command=lambda: self.revert_doc(d), state="normal" if d.has_changes() else "disabled")
            m.add_command(label="Delete %s…" % self.WHAT, command=self.delete, state="disabled" if d.vanilla else "normal")
        popup(m, ev)

    def revert_doc(self, d):
        for tag in list(d.cur):
            if d.changed(tag):
                d.revert(tag)
        d.revert_lists()
        self.app.update_status()
        self.show(d)
        self.fill(d)

    # ---- list
    def docs(self):
        return list(getattr(self.proj, self.KIND)) + list(getattr(self.proj, "base_" + self.KIND))

    def ensure(self):
        if not self._filled:
            self._filled = True
            self.fill()

    def a_values(self):
        return set()

    def sort_key(self, d):
        return (d.name() or d.path.stem).lower()

    def row(self, d):
        return ()

    def a_of(self, d):
        return ""

    def pic(self, d):
        return None

    def fill(self, select=None):
        keep = select or self.cur
        words = self.flt.get().lower().split()
        docs = self.docs()
        if self.cb_a is not None:
            self.cb_a["values"] = [self.ALL] + sorted((v for v in self.a_values() if v), key=str.lower)
        src, fa = self.f_src.get(), self.f_a.get()
        self.tv.delete(*self.tv.get_children())
        self.items = {}
        for i, d in enumerate(sorted(docs, key=self.sort_key)):
            txt = "%s %s %s" % (d.name(), d.path.stem, " ".join(str(x) for x in self.row(d)))
            if words and not all(w in txt.lower() for w in words):
                continue
            if (src != self.ALL and ("base game" if d.vanilla else "mod") != src) or (fa != self.ALL and self.a_of(d) != fa):
                continue
            iid = str(i)
            self.items[iid] = d
            im = None
            p = self.pic(d)
            if p:
                im = self.img(p, 34)
            self.tv.insert("", "end", iid=iid, text=self.label_of(d), image=im or self.blank,
                           values=tuple(self.row(d)) + ("game" if d.vanilla else "mod",))
            if d is keep:
                self.tv.selection_set(iid)
                self.tv.see(iid)
        self.count.configure(text="%d of %d shown" % (len(self.items), len(docs)))
        try:
            self.tab.update_title()
        except Exception:
            pass

    def on_pick(self):
        sel = self.tv.selection()
        d = self.items.get(sel[0]) if sel else None
        if d is not None and d is not self.cur:
            self.show(d)

    def reload(self):
        if not self._filled:
            return
        if self.cur is not None and not any(self.cur is d for d in self.docs()):
            self.cur = None
        self.fill()
        self.show(self.cur)

    def select(self, doc):
        self.ensure()
        self.f_src.set(self.ALL)
        self.f_a.set(self.ALL)
        self.flt.set("")
        self.fill(doc)
        self.show(doc)

    # ---- editor building blocks
    def show(self, d):
        self.cur = d
        self.vars, self.widgets = {}, {}
        self.sf.clear()
        try:
            self.sf.canvas.itemconfigure(self.sf.win, height="")
        except tk.TclError:
            pass
        p = self.sf.inner
        if d is None:
            tk.Label(p, text="Pick a %s on the left to edit it." % self.WHAT, bg=PANEL2, fg=DIM).pack(padx=20, pady=20, anchor="w")
            return
        head = tk.Frame(p, bg=PANEL2)
        head.pack(fill="x", padx=14, pady=(12, 2))
        if self.PIC_SUB:
            pth = self.pic(d)
            im = self.img(pth, 72) if pth else None
            self.hdr_img = tk.Label(head, image=im if im is not None else "", text="" if im is not None else "no picture\n(click to pick)", bg=PANEL, fg=DIM,
                                    width=11 if im is None else 0, height=4 if im is None else 0, cursor="hand2")
            self.hdr_img.image = im
            self.hdr_img.pack(side="left", padx=(0, 12))
            self.hdr_img.bind("<Button-1>", lambda _e: self.change_pic(d))
            self.hdr_img.bind("<Button-3>", lambda ev: self.pic_menu(ev, d))
            tip(self.hdr_img, "Click to change the picture (right-click for more).")
        tk.Label(head, text=d.name() or d.path.stem, bg=PANEL2, fg=ORANGE, font=("Segoe UI", 15, "bold"), anchor="w").pack(side="left")
        self.hint_lbl = None
        if self.TAB_HINTS:                                          # a hint for the sub tab you are on, in the space right of the picture and name
            hb = tk.Frame(head, bg=PANEL, highlightthickness=1, highlightbackground=EDGE)
            hb.pack(side="left", fill="both", expand=True, padx=(22, 4))
            tk.Label(hb, text="HINT", bg=PANEL, fg=ORANGE, font=("Segoe UI", 8, "bold"), anchor="w").pack(fill="x", padx=10, pady=(6, 0))
            self.hint_lbl = tk.Label(hb, text="", bg=PANEL, fg=FG, anchor="nw", justify="left", wraplength=520, font=("Segoe UI", 9))
            self.hint_lbl.pack(fill="x", padx=10, pady=(0, 8))
            hb.bind("<Configure>", lambda e: self.hint_lbl.configure(wraplength=max(220, e.width - 26)))
        note = "%s   ·   %s" % (d.rel.as_posix(), "base game - editing it saves a copy into your mod" if d.vanilla else ("NEW - not saved yet" if d.new else "your mod"))
        tk.Label(p, text=note, bg=PANEL2, fg=DIM, anchor="w").pack(fill="x", padx=14, pady=(0, 6))
        self.build(d, p)

    TAB_HINTS = {}

    def show_hint(self, title):
        lb = getattr(self, "hint_lbl", None)
        if lb is not None:
            try:
                lb.configure(text=self.TAB_HINTS.get(title, ""))
            except tk.TclError:
                pass

    def build(self, d, p):
        pass

    def sub_tabs(self, p):
        """Sub tabs for the editor (like the module editor): returns T(title) -> the frame of that tab. Each tab scrolls on its own and the
        notebook takes exactly the rest of the window height. The chosen tab is kept when another file is picked."""
        nb = self.sub_nb = ttk.Notebook(p)
        nb.pack(fill="both", expand=True, padx=10, pady=(4, 8))
        tabs = {}
        cls = type(self)

        def T(title):
            if title not in tabs:
                sf = ScrollFrame(nb, bg=PANEL2)
                nb.add(sf, text=title)
                tabs[title] = sf.inner
            return tabs[title]

        def fit(_e=None):                                           # the page is exactly as tall as the window; the notebook expands into the rest
            try:
                h = self.sf.canvas.winfo_height()
                if h > 200:
                    self.sf.canvas.itemconfigure(self.sf.win, height=h)
            except tk.TclError:
                pass
        self.sf.canvas.bind("<Configure>", lambda e: (self.sf.canvas.itemconfigure(self.sf.win, width=e.width), fit()))
        self.sf.canvas.yview_moveto(0)
        nb.after(80, fit)
        nb.after(400, fit)

        def remember(_e=None):
            try:
                cls._last_sub = nb.index("current")
                self.show_hint(nb.tab(nb.select(), "text"))
            except tk.TclError:
                pass
        nb.bind("<<NotebookTabChanged>>", remember)

        def restore():
            try:
                nb.select(min(getattr(cls, "_last_sub", 0), len(nb.tabs()) - 1))
                self.show_hint(nb.tab(nb.select(), "text"))
            except tk.TclError:
                pass
        T.restore = restore
        return T

    def section(self, parent, title, hint=""):
        f = tk.LabelFrame(parent, text=" %s " % title, bg=PANEL2, fg=PEACH, bd=1, relief="groove", labelanchor="nw")
        f.pack(fill="x", padx=14, pady=6)
        f.columnconfigure(1, weight=1)
        f.nrow = 0
        if hint:
            tip(f, hint)
        return f

    def field(self, sec, path, label, kind="text", hint="", choices=None, width=36, note=None):
        """One editable value of the selected file, stored under its path ('Traits/Name')."""
        d = self.cur
        r = sec.nrow
        sec.nrow += 1
        lb = tk.Label(sec, text=label, bg=PANEL2, fg=FG, anchor="w", width=self.LABEL_W)
        lb.grid(row=r, column=0, sticky="nw", padx=(8, 6), pady=2)
        if hint:
            tip(lb, hint)
        var = tk.StringVar(value=d.get(path))
        self.vars[path] = var
        if kind == "bool":
            w = make_switch(sec, var, lambda p=path: self.commit(p))
            w.grid(row=r, column=1, sticky="w", pady=2)
        elif kind == "multi":
            w = tk.Text(sec, height=4, wrap="word", width=width, **TEXT_OPTS)
            w.insert("1.0", d.get(path))
            w.grid(row=r, column=1, sticky="we", pady=2, padx=(0, 8))
            w.bind("<FocusOut>", lambda _e, p=path, w=w: (var.set(w.get("1.0", "end-1c")), self.commit(p)))
        elif kind == "combo":
            vals = list(choices() if callable(choices) else (choices or []))
            w = ttk.Combobox(sec, textvariable=var, values=vals, width=width - 2)
            w.grid(row=r, column=1, sticky="we", pady=2, padx=(0, 8))
            w.bind("<<ComboboxSelected>>", lambda _e, p=path: self.commit(p))
            w.bind("<Return>", lambda _e, p=path: self.commit(p))
            w.bind("<FocusOut>", lambda _e, p=path: self.commit(p))
        else:
            w = ttk.Entry(sec, textvariable=var, width=width if kind == "text" else 12)
            w.grid(row=r, column=1, sticky="w" if kind == "int" else "we", pady=2, padx=(0, 8))
            w.bind("<Return>", lambda _e, p=path, k=kind: self.commit(p, k))
            w.bind("<FocusOut>", lambda _e, p=path, k=kind: self.commit(p, k))
        if hint:
            tip(w, hint)
        self.widgets[path] = w
        if note is not None:
            nl = tk.Label(sec, text="", bg=PANEL2, fg="#e07070", anchor="w")
            nl.grid(row=r, column=2, sticky="w", padx=(0, 8))
            self.widgets[path + "#note"] = nl
            nl.configure(text=note(d.get(path)) if callable(note) else note)
            var.trace_add("write", lambda *_a, nl=nl, note=note, var=var: nl.configure(text=note(var.get()) if callable(note) else note))
        return w

    def ai_pic(self, path, sub, label="picture", number=False, refresh=False):
        """Make the picture with an AI (prompt out, picture back), then add it exactly like a picture picked from this computer."""
        d = self.cur
        nm = (d.name() or d.path.stem) if d is not None else label
        dlg = AiAssetDialog(self, self.proj, sub, nm, label)
        self.wait_window(dlg)
        if dlg.result and dlg.result[1]:
            return self.browse_pic(path, sub, label, number, refresh, src=dlg.result[1])
        return None

    def browse_pic(self, path, sub, label="picture", number=False, refresh=False, src=None):
        """Look on this computer for a picture: it is copied to Textures\\<sub> when you Save, and the field is set to its name."""
        f = src or filedialog.askopenfilename(parent=self, title="Pick a %s (.png is best)" % label,
                                              filetypes=[("Pictures", "*.png *.gif *.dds *.xnb *.jpg *.jpeg *.bmp"), ("All files", "*.*")])
        if not f:
            return None
        stem = re.sub(r"[^\w\-]+", "_", Path(f).stem).strip("_") or "picture"
        if number:
            stem = "flag_%d" % (max([n for n, _p in self.flag_list() if n is not None] + [0]) + 1)
        try:
            self.proj.stage_copy(f, sub, stem)
        except Exception as e:
            messagebox.showwarning("Picture", "That picture could not be added: %s" % e, parent=self)
            return None
        self.proj._icons.clear()
        self._flags = None
        if path and path in self.vars:
            self.vars[path].set(stem)
            self.commit(path)
        self.app.say("%s added as Textures\\%s\\%s - copied into the mod when you Save." % (label.capitalize(), sub, stem))
        if refresh and self.cur is not None:
            self.show(self.cur)
            self.fill(self.cur)
        return stem

    def browse_button(self, sec, row, path, sub, label="picture"):
        fr = tk.Frame(sec, bg=PANEL)
        fr.grid(row=row, column=3, padx=(0, 8), sticky="w")
        b = ttk.Button(fr, text="Browse PC…", command=lambda: self.browse_pic(path, sub, label))
        b.pack(side="left")
        b0 = ttk.Button(fr, text="Make with an AI…", command=lambda: self.ai_pic(path, sub, label))
        b0.pack(side="left", padx=(4, 0))
        tip(b0, "Builds a prompt for any AI, takes the picture back and adds it to the mod.")
        tip(b, "Look on this computer for a %s file. It is copied into the mod's Textures\\%s folder when you Save." % (label, sub))
        b1 = ttk.Button(fr, text="Library…", command=lambda: self.library_pic(path, sub, label))
        b1.pack(side="left", padx=(4, 0))
        tip(b1, "Pick a %s from this mod, BB+ or the other mods in your Mods folder; it is copied into the mod's Textures\\%s folder when you Save." % (label, sub))

    def library_pic(self, path, sub, label):
        r = pick_library(self, self.app, ["race", "picture"], "Pick a %s from the library" % label, stage=False)
        if r:
            self.browse_pic(path, sub, label, src=str(r[1] / r[2]))

    def ai_video(self, path, browse=False):
        d = self.cur
        dlg = AiVideoDialog(self, self.app, (d.name() or d.path.stem) if d is not None else "race", self.vars[path].get() if path in self.vars else "")
        if browse:
            dlg.pick()                                                # Browse PC…: choose the file first; the window then checks it and makes the .xnb
        dlg.show()
        self.wait_window(dlg)
        if dlg.result:
            if path in self.vars:
                self.vars[path].set(dlg.result)
                self.commit(path)
            self.app.say("Video '%s' chosen: %d file(s) will be copied into the mod's Video folder when you Save." % (dlg.result, getattr(dlg, "staged", 0)))

    def video_button(self, sec, row, path):
        fr = tk.Frame(sec, bg=PANEL)
        fr.grid(row=row, column=3, padx=(0, 8), sticky="w")
        bb = ttk.Button(fr, text="Browse PC…", command=lambda: self.ai_video(path, browse=True))
        bb.pack(side="left", padx=(0, 4))
        tip(bb, "Look on this computer for a video file (.wmv, .mp4 or a compiled .xnb). The next window checks it against the game's own race videos, makes the .xnb the game loads "
                "and copies both into the mod's Video folder when you Save.")
        b0 = ttk.Button(fr, text="Make with an AI…", command=lambda: self.ai_video(path))
        b0.pack(side="left", padx=(0, 4))
        tip(b0, "Builds a prompt for any AI that makes videos, with the file size, frame rate, length and codec measured from the race videos already in the game and your mods. Then you pick the finished file.")
        b = ttk.Button(fr, text="Library…", command=lambda: self.library_video(path))
        b.pack(side="left")
