    @staticmethod
    def _true(d, tag):
        return d.get(tag).strip().lower() == "true"

    def kind_of(self, d):
        """'' for a playable race, else 'pirate' / 'remnant' / 'minor' (any other race with Faction set)."""
        if self._true(d, "IsPirateFaction"):
            return "pirate"
        if self._true(d, "IsRemnantFaction"):
            return "remnant"
        return "minor" if d.get("Faction").strip() not in ("", "0") else ""

    def a_values(self):
        return set(self.KIND_LABEL.values())

    def a_of(self, d):
        return self.KIND_LABEL[self.kind_of(d)]

    def label_of(self, d):
        return self.KIND_MARK[self.kind_of(d)] + (d.name() or d.path.stem)

    def row(self, d):
        return (self.KIND_LABEL[self.kind_of(d)], d.get("Traits/ShipType"), d.get("Traits/HomeSystemName"))

    def extra_buttons(self):
        return (("☠ New non-player race…", self.new_npc,
                 "Make a pirate, Remnant or other non-player race: it is marked as not playable and gets the ship slots and settings those races need."),)

    def new_npc(self):
        dlg = NpcDialog(self, [d for d in self.docs() if self.kind_of(d)], self.kind_of)
        dlg.show()
        self.wait_window(dlg)
        r = dlg.result
        if not r:
            return
        try:
            doc = self.proj.new_npc_race(r["name"], r["kind"], r["copy"])
        except ValueError as e:
            messagebox.showwarning("New non-player race", str(e), parent=self)
            return
        self.app.update_status()
        self.f_a.set(self.ALL)
        self.select(doc)
        self.app.say("Created the non-player race '%s'. Fill in its ships below; use 'Edit encounters' to set what it asks the player for. Save (Ctrl+S) to write it." % r["name"])

    def menu_items(self, d):
        return [None, ("Open home system", self.open_system, self.proj.system_by_name(d.get("Traits/HomeSystemName")) is not None),
                ("＋ New home system…", self.new_home, True),
                ("Show this race's troops", lambda: self.show_troops(d), bool(self.proj.troops_of_race(d)))]

    def show_troops(self, d):
        ts = self.proj.troops_of_race(d)
        if ts:
            self.tab.open("troops", ts[0])

    # ---- flag + colour mixing
    _flags = None

    def flag_dirs(self):
        """Folders named Flags (in the mod, then the game; also under Textures), mod first."""
        P_, out = self.proj, []
        tops = [P_.root] + [b / "Content" for b in P_.base_roots] + list(P_.base_roots)
        for top in tops:
            for base in (top, top / "Textures"):
                try:
                    for d in base.iterdir():
                        if d.is_dir() and d.name.lower() == "flags" and d not in out:
                            out.append(d)
                except OSError:
                    continue
        return out

    def flag_list(self):
        """[(number, path)]: every picture in the Flags folders, sorted by file name; the flag number is its place in that list (counting from 0)."""
        if self._flags is None:
            exts, seen, files = self.proj.img_exts(), {}, []
            for d in self.flag_dirs():
                try:
                    for f in d.iterdir():
                        if f.is_file() and f.suffix.lower() in exts and f.stem.lower() not in seen and BACKUP_DIR not in f.parts:
                            seen[f.stem.lower()] = f
                except OSError:
                    continue
            for fd in self.proj.file_docs:                    # added from this PC, not saved yet
                if fd.path.parent.name.lower() == "flags" and fd.path.stem.lower() not in seen:
                    seen[fd.path.stem.lower()] = fd.src
            files = sorted(seen.items(), key=lambda kv: [int(t) if t.isdigit() else t for t in re.split(r"(\d+)", kv[0])])
            self._flags = [(i, p) for i, (_k, p) in enumerate(files)]
        return self._flags

    def flag_for(self, n):
        fl = self.flag_list()
        try:
            n = int(float(n))
        except (TypeError, ValueError):
            return None
        return fl[n][1] if 0 <= n < len(fl) else None

    def rgb_of(self, d):
        out = []
        for c in "RGB":
            try:
                out.append(int(float(d.get("Traits/" + c) or 0)))
            except ValueError:
                out.append(0)
        return out

    def build_preview(self, s, d):
        r = s.nrow
        s.nrow += 1
        box = tk.Frame(s, bg=PANEL2)
        box.grid(row=r, column=0, columnspan=3, sticky="we", padx=8, pady=6)
        fbox = tk.Frame(box, bg=PANEL, width=130, height=100)
        fbox.pack(side="left", padx=(0, 12))
        fbox.pack_propagate(False)
        self.flag_lb = tk.Label(fbox, bg=PANEL, fg=DIM, text="flag", cursor="hand2")
        self.flag_lb.pack(fill="both", expand=True)
        self.flag_lb.bind("<Button-1>", lambda _e: self.choose_flag())
        self.flag_lb.bind("<Button-3>", self.flag_menu)
        tip(self.flag_lb, "Click to choose another flag (right-click for more).")
        mid = tk.Frame(box, bg=PANEL2)
        mid.pack(side="left")
        self.flag_note = tk.Label(mid, bg=PANEL2, fg=DIM, anchor="w", justify="left", wraplength=260)
        self.flag_note.pack(fill="x")
        b = ttk.Button(mid, text="Choose a flag…", command=self.choose_flag)
        b.pack(anchor="w", pady=4)
        b2 = ttk.Button(mid, text="Add a flag from my PC…", command=self.add_flag)
        b2.pack(anchor="w")
        tip(b2, "Look on this computer for a flag picture. It is copied into the mod's Flags folder as the next flag and chosen for this race. The game's own flags are .xnb files, so a .png may need converting first.")
        tip(b, "Pick one of the flag pictures; sets the Flag number.")
        self.mix = tk.Frame(box, bg="#000000", width=130, height=100, relief="solid", bd=1)
        self.mix.pack(side="left", padx=14)
        tip(self.mix, "The empire colour made from Colour R, G and B (values above 255 are shown as 255).")
        sl = tk.Frame(box, bg=PANEL2)
        sl.pack(side="left")
        self.mix_hex = tk.Label(sl, bg=PANEL2, fg=FG, anchor="w")
        self.mix_hex.pack(fill="x")
        self.sliders, self._sync_sl = {}, False
        for c, col in zip("RGB", ("#e06c6c", "#6ce08a", "#6c9ce0")):
            row = tk.Frame(sl, bg=PANEL2)
            row.pack(fill="x")
            tk.Label(row, text=c, bg=PANEL2, fg=col, width=2).pack(side="left")
            sc = tk.Scale(row, from_=0, to=255, orient="horizontal", length=200, showvalue=False, bg=PANEL2, fg=FG, troughcolor=PANEL,
                          highlightthickness=0, command=lambda v, c=c: self.slide(c, v))
            sc.pack(side="left")
            self.sliders[c] = sc
        tip(sl, "Drag to mix the empire colour. Sets Colour R / G / B.")
        self.on_edited()

    def slide(self, c, v):
        if self._sync_sl or self.cur is None:
            return
        path = "Traits/" + c
        val = str(int(float(v)))
        if path in self.vars and self.cur.get(path) != val:
            self.vars[path].set(val)
            self.cur.set(path, val)
            self.after_edit()

    def choose_flag(self):
        d = self.cur
        fl = self.flag_list()
        if d is None:
            return
        if not fl:
            messagebox.showinfo("Flags", "No flag pictures were found (a Flags folder in the mod or the game). The flag number can still be typed.")
            return
        top = _Dialog(self, "Choose a flag")
        top.geometry("640x520")
        cv = ScrollFrame(top, bg=PANEL)
        cv.pack(fill="both", expand=True, padx=8, pady=8)
        for i, (n, p) in enumerate(fl):
            im = self.img(p, 56)
            b = tk.Button(cv.inner, image=im, text=str(i), compound="top", bg=PANEL2, fg=FG, relief="flat",
                          command=lambda i=i, top=top: self.pick_flag(i, top))
            b.grid(row=i // 8, column=i % 8, padx=3, pady=3)
        top.show()

    def flag_menu(self, ev):
        m = tk.Menu(self, tearoff=0, **MENU_OPTS)
        m.add_command(label="Choose a flag…", command=self.choose_flag)
        m.add_command(label="Add a flag from the library (BB+ / other mods)…", command=lambda: self.add_flag(library=True))
        m.add_command(label="Add a flag from my PC…", command=self.add_flag)
        popup(m, ev)

    def add_flag(self, library=False):
        """Look on this computer (or in the library) for a flag picture; it is copied into the mod's Flags folder as the next file in the list when you Save."""
        if library:
            r = pick_library(self, self.app, ["race", "picture"], "Pick a flag from the library", stage=False)
            f = str(r[1] / r[2]) if r else None
        else:
            f = filedialog.askopenfilename(parent=self, title="Pick a flag picture",
                                           filetypes=[("Pictures", "*.png *.gif *.dds *.xnb *.jpg *.jpeg *.bmp"), ("All files", "*.*")])
        d = self.cur
        if not f or d is None:
            return
        P_ = self.proj
        dirs = [x for x in self.flag_dirs() if str(x).lower().startswith(str(P_.root).lower())]
        fdir = dirs[0] if dirs else P_.root / "Flags"
        fl = self.flag_list()
        last = fl[-1][1].stem if fl else "Flag_00"
        m = re.match(r"^(.*?)(\d+)$", last)
        stem = (m.group(1) + str(int(m.group(2)) + 1).zfill(len(m.group(2)))) if m else last + "_01"
        dest = fdir / (stem + Path(f).suffix.lower())
        if dest.exists():
            messagebox.showwarning("Flag", "%s already exists in the mod." % dest.name, parent=self)
            return
        P_.file_docs.append(FileCopyDoc(f, dest, P_.root, "Flags/" + stem))
        P_._icons.clear()
        self._flags = None
        n = len(self.flag_list()) - 1
        self.vars["Traits/FlagIndex"].set(str(n))
        d.set("Traits/FlagIndex", str(n))
        self.after_edit()
        self.app.say("Flag %d added as %s (copied into the mod's Flags folder when you Save). The game's own flags are .xnb files - a .png may need converting." % (n, dest.name))

    def pick_flag(self, n, top):
        top.destroy()
        d = self.cur
        if d is not None and "Traits/FlagIndex" in self.vars:
            self.vars["Traits/FlagIndex"].set(str(n))
            d.set("Traits/FlagIndex", str(n))
            self.after_edit()

    def pic(self, d):
        for n in (d.get("PortraitName"), d.path.stem):
            if n:
                p = self.proj.find_file("Textures/portraits/" + n) or self.proj.find_file("portraits/" + n) or self.proj.find_file("Races/" + n) or self.proj.find_file(n)
                if p:
                    return p
        return None

    def copy_tech_unlocks(self):
        d = self.cur
        if d is None:
            return
        mine = d.get("Traits/ShipType").strip()
        if not mine:
            messagebox.showinfo("Tech unlocks", "This race has no ship type key yet (Traits / ShipType).")
            return
        types = {"%s   (%d module unlocks in %d techs)" % (ty, n, t): ty for ty, (n, t) in sorted(self.proj.race_unlock_types().items(), key=lambda kv: kv[0].lower())
                 if ty.upper() != "ALL" and ty.lower() != mine.lower()}
        if not types:
            messagebox.showinfo("Tech unlocks", "No other race type has module unlocks in the techs.")
            return
        pick = ask_choice(self, "Copy tech unlocks", "Copy every module unlock of this race type to %s (ship type '%s'):" % (d.name() or d.path.stem, mine), list(types))
        src = types.get(pick)
        if not src:
            return
        got = self.proj.copy_type_unlocks(src, mine)
        if not got:
            messagebox.showinfo("Tech unlocks", "Nothing to add: every module '%s' unlocks is already unlocked for '%s'." % (src, mine))
            return
        self.app.update_status()
        try:
            self.tab.reload()
        except Exception:
            pass
        self.app.say("Added %d module unlock(s) in %d tech(s) for '%s' (copied from '%s'). Save to write them." % (sum(len(a) for _t, a in got), len(got), mine, src))

    def gen_personality(self):
        d = self.cur
        if d is None:
            return
        sets = sorted(k for k in d.lists if k.startswith("traits") and k[6:].isdigit())
        mine = list(d.lists.get(sets[0], ())) if sets else []
        known = [t for t in mine if t.strip() in TRAIT_AI]
        opts = ["From this race's racial traits  (%s)" % (", ".join(t.strip() for t in known[:4]) + (" ..." if len(known) > 4 else "") if known else "no known traits - will be balanced")] + list(AI_PRESETS)
        pick = ask_choice(self, "Generate personality", "How should the AI of this race behave?", opts)
        if not pick:
            return
        sc = {}
        if pick == opts[0]:
            for t in mine:
                for k, v in TRAIT_AI.get(t.strip(), {}).items():
                    sc[k] = sc.get(k, 0) + v
        else:
            sc = dict(AI_PRESETS[pick])
        # the game's own values for these lists: keep any extra values this mod already uses
        pn = list(AI_PERSONALITY) + [x for x in self.trait_choices("personality") if x not in AI_PERSONALITY and x in sc]
        en = list(AI_ECONOMY) + [x for x in self.trait_choices("economic") if x not in AI_ECONOMY and x in sc]
        po, pc = ai_weights(sc, pn)
        eo, ec = ai_weights(sc, en)
        show = lambda o, c: ", ".join("%s x%d" % (n, c[n]) for n in o)
        if not messagebox.askyesno("Generate personality", "Personality:  %s\n\nEconomy:  %s\n\nReplace this race's two lists with these?  (Undo brings the old ones back.)" % (show(po, pc), show(eo, ec))):
            return
        d.lists["personality"] = counts_to_weights(po, pc)
        d.lists["economic"] = counts_to_weights(eo, ec)
        self.wed_p.refresh()
        self.wed_e.refresh()
        self.after_edit()

    def trait_choices(self, key):
        out = set()
        for r in self.docs():
            for k, v in r.lists.items():
                if k == key or (key == "traits" and k.startswith("traits")):
                    out.update(x for x in v if isinstance(x, str))
        if key == "traits":
            out.update(self.proj.defined_traits())
        return sorted(out, key=str.lower)

    def system_names(self):
        return sorted({s.get("Name") or s.path.stem for s in self.proj.systems + self.proj.base_systems}, key=str.lower)

    def planets_of(self, name):
        s = self.proj.system_by_name(name)
        if s is None:
            return []
        return [ring_get(r, "Planet") for r in s.lists.get("rings", []) if ring_get(r, "Planet")]

    def ships_for(self, d):
        k = self.kind_of(d)
        if k == "pirate":
            return (self.SHIPS[0],) + PIRATE_SHIPS
        if k == "remnant":
            return self.SHIPS[:2] + REMNANT_SHIPS
        return self.SHIPS

    def global_switch(self, sec, key, label, hint):
        """A switch bound to a line of Globals.yaml (not to this race's file)."""
        r = sec.nrow
        sec.nrow += 1
        lb = tk.Label(sec, text=label, bg=PANEL2, fg=FG, anchor="w", width=self.LABEL_W)
        lb.grid(row=r, column=0, sticky="nw", padx=(8, 6), pady=2)
        tip(lb, hint + "\n\nThis is a setting for the whole game (Globals.yaml), not for this race only.")
        var = tk.StringVar(value=self.proj.global_value(key, "false"))

        def go():
            try:
                self.proj.set_global(key, var.get())
                self.app.update_status()
            except ValueError as e:
                messagebox.showwarning("Globals.yaml", str(e), parent=self)
        w = make_switch(sec, var, go)
        w.grid(row=r, column=1, sticky="w", pady=2)
        tk.Label(sec, text="(whole game - Globals.yaml)", bg=PANEL2, fg=DIM).grid(row=r, column=2, sticky="w")
        return w

    def build_npc(self, p, d, k):
        """The sections only non-player races have."""
        s = self.section(p, "Non-player settings")
        self.field(s, "Faction", "Non-player flag (Faction)", "int", "Faction: 1 marks the race as a non-player faction (players cannot pick it). 0 or missing = a normal race.")
        if k == "pirate":
            self.field(s, "IsPirateFaction", "Pirate faction", "bool", "IsPirateFaction: true = this race acts as pirates (raids, demands protection money).")
            tt = self.proj.global_value("TurnTimer", "5")

            def mins(v):
                try:
                    return "about %.1f minutes between demands (at %s s per turn)" % (float(v) * float(tt) / 60.0, tt)
                except ValueError:
                    return ""
            self.field(s, "PiratePaymentPeriodTurns", "Turns between demands", "int",
                       "PiratePaymentPeriodTurns: how many turns pass before the pirates ask the player for protection money again. How much they ask is set in the encounters (below).", note=mins)
            self.field(s, "MinimumColoniesForStartPayment", "Colonies before they ask", "int",
                       "MinimumColoniesForStartPayment: the pirates do not demand money until the player has at least this many colonies.")
            self.global_switch(s, "DisablePirates", "Pirates off in this game", "DisablePirates: turn this on to remove all pirates from the game.")
        elif k == "remnant":
            self.field(s, "IsRemnantFaction", "Remnant faction", "bool", "IsRemnantFaction: true = this race is the Remnant (the ancient guardians).")
            self.field(s, "BaseShipLevel", "Base ship level", "int", "BaseShipLevel: the tech level of the Remnant's ships at the start.")
            self.field(s, "PreferredEnv", "Preferred environment", "combo", "PreferredEnv: planet type this race prefers.", list(REMNANT_ENVS))
            for e in REMNANT_ENVS:
                if "Env" + e in d.cur or e in ("Terran", "Oceanic"):
                    self.field(s, "Env" + e, "Guardians on %s" % e, "int", "Env%s: for the Remnant this controls how many guardian fleets are placed on %s planets when the game is created (higher = more)." % (e, e))
            self.global_switch(s, "DisableRemnantStory", "Remnant story off in this game", "DisableRemnantStory: turn this on to switch off the Remnant story events.")
            tk.Label(s, bg=PANEL2, fg=DIM, anchor="w", justify="left", wraplength=520,
                     text="The Remnant's own stories (picked at random when a game starts) are not in the Races folder. 'Look for Remnant story files' searches the mod and "
                          "the base game and writes what it finds to Test Reports and Backups\\remnant_story_search.txt - send me that file and I will add an editor here."
                     ).grid(row=s.nrow, column=0, columnspan=3, sticky="w", padx=8, pady=6)
            s.nrow += 1
            b = ttk.Button(s, text="Look for Remnant story files", command=self.look_for_stories)
            b.grid(row=s.nrow, column=1, sticky="w", padx=0, pady=(0, 6))
            tip(b, "Searches the mod folder and the base game for files that could hold the Remnant stories and shows what it found.")
            s.nrow += 1
        # interactions with the player
        s = self.section(p, "Interactions with the player (what they say and ask for)",
                         "Encounter files in the Encounter Dialogs folder whose Faction is this race: first contact, demands for money, what happens if the player pays or refuses.")
        es = self.proj.encounters_of(d)
        if not es:
            tk.Label(s, bg=PANEL2, fg=DIM, anchor="w", justify="left", wraplength=520,
                     text="No encounter files found for '%s'. Encounter files are named like 'Orion Syndicate000_ToPlayerDemandtMoney.xml' and hold <Faction>%s</Faction>."
                     % (d.get("Traits/Name") or d.path.stem, d.get("Traits/Name") or d.path.stem)).grid(row=0, column=0, columnspan=3, sticky="w", padx=8, pady=4)
            s.nrow = 1
        for e in sorted(es, key=lambda x: (x.get("Step").strip().zfill(4), x.path.name)):
            pct, amts = e.money()
            asks = []
            if pct:
                asks.append("asks %s%% of the treasury" % pct)
            if amts:
                asks.append("answers offering %s credits" % ", ".join(amts))
            r = tk.Frame(s, bg=PANEL2)
            r.grid(row=s.nrow, column=0, columnspan=3, sticky="we", padx=8, pady=1)
            s.nrow += 1
            tk.Label(r, text="Step %s - %s%s" % (e.get("Step").strip(), e.get("Name").strip(), ("   [" + "; ".join(asks) + "]") if asks else ""), bg=PANEL2, fg=FG, anchor="w",
                     justify="left", wraplength=470).pack(side="left", fill="x", expand=True)
            b = ttk.Button(r, text="Edit…", command=lambda e=e: self.open_encounters(d, e))
            b.pack(side="right", padx=4)
        bf = tk.Frame(s, bg=PANEL2)
        bf.grid(row=s.nrow, column=0, columnspan=3, sticky="w", padx=8, pady=6)
        s.nrow += 1
        b = ttk.Button(bf, text="Edit all encounters…", command=lambda: self.open_encounters(d), state="normal" if es else "disabled")
        b.pack(side="left", padx=(0, 6))
        tip(b, "Opens every encounter of this race: what they say, how much money they ask for, and what each answer leads to.")
        b = ttk.Button(bf, text="Copy the encounters of another faction…", command=lambda: self.copy_encounters(d))
        b.pack(side="left")
        tip(b, "Start this race's encounters as copies of another pirate faction's (new files in Encounter Dialogs, Faction set to this race). Then edit the words and amounts.")

    def open_encounters(self, d, doc=None):
        es = self.proj.encounters_of(d)
        if not es:
            self.app.say("This race has no encounter files yet.")
            return
        try:
            EncounterWindow(self, self, d, es, doc)
        except Exception as e:
            log_exc("encounter window")
            messagebox.showwarning("Encounters", "The encounters could not be shown: %s" % e)

    def copy_encounters(self, d):
        mine = (d.get("Traits/Name") or d.path.stem).strip()
        facs = [f for f in self.proj.encounter_factions() if f.lower() != mine.lower()]
        if not facs:
            messagebox.showinfo("Encounters", "There are no other factions' encounter files to copy.", parent=self)
            return
        src = ask_choice(self, "Copy encounters", "Copy the encounters of which faction?", facs)
        if not src or src not in facs:
            return
        n = 0
        try:
            for e in [x for x in self.proj.encounters + self.proj.base_encounters if x.faction() == src]:
                stem = e.path.stem
                new = (mine + stem[len(src):]) if stem.lower().startswith(src.lower()) else "%s_%s" % (mine, stem)
                nd = self.proj.new_gdoc("encounters", new, base=e)
                nd.set("Faction", mine)
                n += 1
        except ValueError as ex:
            messagebox.showwarning("Encounters", str(ex), parent=self)
        self.app.update_status()
        self.show(d)
        self.app.say("Copied %d encounter file(s) from %s. Their texts still use the old wording - open 'Edit encounters' to change the words and the amounts." % (n, src))

    def build(self, d, p):
        self.swatch, self.flame, self.mix = [], None, None
        k = self.kind_of(d)
        hid = tk.Frame(p)                    # sections that do not apply to this race are built here and never shown
        if k:
            bn = tk.Frame(p, bg="#4a2a1a")
            bn.pack(fill="x", padx=14, pady=(0, 6))
            tk.Label(bn, text="%s %s" % (self.KIND_MARK[k].strip(), self.KIND_TEXT[k]), bg="#4a2a1a", fg="#ffd9b0", anchor="w", justify="left", wraplength=640,
                     font=("Segoe UI", 10, "bold")).pack(fill="x", padx=10, pady=6)
        nb = self.race_nb = ttk.Notebook(p)                         # sub tabs like the module editor; each one scrolls on its own
        nb.pack(fill="both", expand=True, padx=10, pady=(4, 8))
        tabs = {}

        def T(title):
            if title not in tabs:
                sf = ScrollFrame(nb, bg=PANEL2)
                nb.add(sf, text=title)
                tabs[title] = sf.inner
            return tabs[title]

        def H(title):                                               # sections that do not apply to this race are built in the hidden frame
            return hid if k in ("pirate", "remnant") else T(title)

        def fit(_e=None):                                           # the page is exactly as tall as the window, so the notebook (packed to expand) fills the rest
            try:
                h = self.sf.canvas.winfo_height()
                if h > 200:
                    self.sf.canvas.itemconfigure(self.sf.win, height=h)
            except tk.TclError:
                pass
        self.sf.canvas.bind("<Configure>", lambda e: (self.sf.canvas.itemconfigure(self.sf.win, width=e.width), fit()))
        self.sf.canvas.yview_moveto(0)
        nb.after(80, fit)
        nb.after(400, fit)

        def remember(_e=None):
            try:
                RaceView._last_tab = nb.index("current")
                self.show_hint(nb.tab(nb.select(), "text"))
            except tk.TclError:
                pass
        nb.bind("<<NotebookTabChanged>>", remember)
        s = self.section(T("Who they are"), "Who they are")
        self.build_preview(s, d)                                    # the flag chooser and the colour mixer come first
        for path, lab, hint in (("Traits/Name", "Name", "The race's name in the game (e.g. StarFleet)."),
                                ("Traits/Singular", "Singular", "One member of the race (a StarFleet officer)."),
                                ("Traits/Plural", "Plural", "Several members."),
                                ("PortraitName", "Portrait", "Picture of the race's leader. FILE: a picture - .png is best (.xnb or .dds also work) - in a Textures\\Races folder of the mod or the game. Type its name without the extension, or use Browse PC… / click the picture at the top to import one."),
                                ("Traits/VideoPath", "Video", "The race's intro video. FILE: a video in the game's Video folder (usually compiled .xnb); type its name without the extension. This editor can't add videos - copy the file into the mod's Video folder yourself."),
                                ("DiplomacyDialogPath", "Diplomacy dialog", "The diplomacy dialogue set. FILE: an .xml dialogue file with this name, usually in the Diplomacy folder of the mod or the game. Pick a name another race uses, or type one for a file you added."),
                                ("MusicCue", "Music cue", "Music for this race. NOT a file you add here: it is a cue name from the game's sound bank (.xwb / .xsb), e.g. sd_races_Terran. Pick one another race uses."),
                                ("Traits/ShipType", "Ship type", "Key that ties ships, troops and modules to this race (e.g. fed). Not a file - letters and digits, no spaces. Troop files (.xml in the Troops folder) use it as their RaceType."),
                                ("Traits/Adj1", "Look 1", "Describes the race in the race list."),
                                ("Traits/Adj2", "Look 2", "Describes the race in the race list.")):
            self.field(s, path, lab, hint=hint)
            if path == "PortraitName":
                self.browse_button(s, s.nrow - 1, path, "portraits", "portrait")
            if path == "Traits/VideoPath":
                self.video_button(s, s.nrow - 1, path)
        for path, lab, hint in (("Traits/FlagIndex", "Flag number", "Which flag picture the race uses. FILE: a flag picture in the Flags folder of the mod or the game (the game uses .xnb files). The number is the picture's place in that folder sorted by name, counting from 0. Click the flag preview to choose, or add one from your PC."),
                                ("Traits/R", "Colour R", "Empire colour: red part (0-255). Not a file."), ("Traits/G", "Colour G", "Empire colour: green part (0-255). Not a file."),
                                ("Traits/B", "Colour B", "Empire colour: blue part (0-255). Not a file.")):
            self.field(s, path, lab, "int", hint)
        if k:
            self.build_npc(T("Non-player"), d, k)
        T("Ships")                                                  # tab order: Ships first, then the solar system
        # ---- home
        s = self.section(H("Solar system"), "Home system")
        self.field(s, "Traits/HomeSystemName", "Home system", "combo", "The solar system the race starts in. FILE: a solar system .xml in the SolarSystems folder (made on the Solar systems tab). Must match a system's Name.", self.system_names,
                   note=lambda v: "" if not v.strip() or self.proj.system_by_name(v) else "no such system")
        self.field(s, "Traits/HomeworldName", "Home world", "combo", "The planet in that system the race starts on (a Planet name from that system's .xml; normally the one marked Home planet).", lambda: self.planets_of(d.get("Traits/HomeSystemName")))
        bf = tk.Frame(s, bg=PANEL2)
        bf.grid(row=s.nrow, column=1, sticky="w", pady=4)
        for text, cmd, hint in (("Open in the solar system editor ›", self.open_system, "Open this system in the Solar systems tab, where planets, suns and everything in it can be edited."),
                                ("＋ New home system…", self.new_home, "Make a new solar system for this race and set it as the home system.")):
            b = ttk.Button(bf, text=text, command=cmd)
            b.pack(side="left", padx=(0, 6))
            tip(b, hint)
        s.nrow += 1
        # ---- ships
        ships = self.ships_for(d)
        s = self.section(T("Ships"), "Starting ships and default ships" if not k else "Ships this %s race uses" % self.KIND_LABEL[k].lower(),
                         "Names of ship designs (see the Designs tab). FILE: a .design file (made in the game's design screen, saved in the mod's ShipDesigns folder - use Import designs in the Ships tab). A red note means no design has that name.")
        names = None

        def missing(v):
            nonlocal names
            if names is None:
                names = {x.lower() for x in self.design_names()}
            return "" if not v.strip() or v.strip().lower() in names else "no design with this name"
        old_w, self.LABEL_W = self.LABEL_W, 16                       # these labels are short: keep the boxes close to them
        for path, lab, hint in ships:
            w = self.field(s, path, lab, "text", "", note=missing)
