def is_remnant_event(d):
    """True for the Remnant story events (they live on Remnants > Stories, not in the Events tab)."""
    try:
        if d.story() or d.get("AllRemnantStories").strip().lower() == "true":
            return True
    except Exception:
        pass
    try:
        return "remnant" in (d.name() or "").lower() or "remnant" in str(getattr(d, "path", "") or "").lower().replace("\\", "/").split("/")[-1]
    except Exception:
        return False


class EventsView(GameDocView):
    """The exploration events (Exploration Events folder, including the scripted Remnant story): a searchable list, and for the picked event
    its story and step, and every outcome with its text, rewards and the ships / troops that appear."""
    KIND, WHAT, FILTER_A = "events", "event", "Story"
    COLS = (("name", "Event", 330), ("story", "Story", 150), ("step", "Step", 45), ("src", "From", 55))
    LEFT_W = 640
    LABEL_W = 22

    def docs(self):
        return [d for d in GameDocView.docs(self) if not is_remnant_event(d)]

    def __init__(self, master, app, tab):
        GameDocView.__init__(self, master, app, tab)
        self.blank = tk.PhotoImage(width=1, height=1)               # no picture column: the names get the room

    def sort_key(self, d):
        return (d.story() == "", d.story().lower(), d.step(), d.name().lower())

    def a_values(self):
        return {d.story() for d in self.docs()}

    def a_of(self, d):
        return d.story()

    def row(self, d):
        return (d.story(), d.step() or "")

    def label_of(self, d):
        return "  " + d.name()

    def stories(self):
        return sorted({d.story() for d in self.docs() if d.story()}, key=str.lower)

    def extra_buttons(self):
        return (("✦ Multi-stage…", lambda: self.tab.wizard(), "A step by step helper for events that lead on to more events."),)

    def new(self):
        name = self.app.line_dialog("New event - name", "New event")
        if not name:
            return
        try:
            nd = self.proj.new_gdoc("events", name)
        except ValueError as e:
            messagebox.showwarning("New event", str(e))
            return
        nd.set("Name", name)
        self.app.update_status()
        self.fill(nd)
        self.show(nd)

    def known_names(self, tag):
        if tag == "TroopsToSpawn":
            return {x.strip().lower() for t in self.proj.troops + self.proj.base_troops for x in ((t.get("Name") or ""), t.path.stem) if x.strip()}
        return {d.name.strip().lower() for d in self.proj.load_designs()}

    def show(self, d):
        if d is not getattr(self, "_out_doc", None):
            self._out_doc, self.out_i, self.shown_lists = d, 0, set()
        GameDocView.show(self, d)

    PV_W = 520

    def preview(self, p, d):
        """What the player sees in the game: the picture, the title and the story text under it, and the button. Everything on it can be
        edited right here: click the picture to change it, click the words to type."""
        BG2 = "#0b0e14"
        card = tk.Frame(p, bg=BG2, highlightbackground=ORANGE, highlightthickness=1)
        card.pack(padx=14, pady=(4, 8), anchor="w")
        self.pv_img = tk.Label(card, bg=BG2, fg=DIM, cursor="hand2")
        self.pv_img.pack(padx=8, pady=(8, 4))
        self.pv_img.bind("<Button-1>", lambda _e: self.pv_change_pic())
        tip(self.pv_img, "Click to change the picture of this outcome.")
        self.pv_title = tk.Entry(card, bg=BG2, fg=ORANGE, insertbackground=ORANGE, relief="flat", font=("Segoe UI", 13, "bold"), width=44,
                                 highlightthickness=1, highlightbackground=BG2, highlightcolor=ORANGE)
        self.pv_title.pack(fill="x", padx=12)
        tip(self.pv_title, "The headline. Click and type.")
        self.pv_text = tk.Text(card, bg=BG2, fg=FG, insertbackground=ORANGE, relief="flat", wrap="word", width=62, height=6, font=("Segoe UI", 10),
                               highlightthickness=1, highlightbackground=BG2, highlightcolor=ORANGE)
        self.pv_text.pack(fill="x", padx=12, pady=(2, 6))
        tip(self.pv_text, "The story text. Click and type; a new line starts a new line in the game.")
        self.pv_btn = tk.Entry(card, bg=PANEL, fg=FG, insertbackground=ORANGE, relief="groove", bd=2, justify="center", width=18)
        self.pv_btn.pack(pady=(0, 10))
        tip(self.pv_btn, "The text of the button. Click and type.")
        for w, kind in ((self.pv_title, "TitleText"), (self.pv_text, "DescriptionText"), (self.pv_btn, "ConfirmText")):
            w.bind("<FocusOut>", lambda _e, k=kind: self.pv_commit(k))
        for w in (self.pv_title, self.pv_btn):
            w.bind("<Return>", lambda _e, k=("TitleText" if w is self.pv_title else "ConfirmText"): self.pv_commit(k))
        self.refresh_preview(force=True)

    def pv_path(self, kind):
        d = self.cur
        return d.opath(min(self.out_i, d.nout - 1)) + "/" + kind

    def pv_commit(self, kind):
        d = self.cur
        if d is None or not d.nout or not hasattr(self, "pv_title"):
            return
        path = self.pv_path(kind)
        if kind == "DescriptionText":
            shown = d.get(path).replace("\\n", "\n")
            new = self.pv_text.get("1.0", "end-1c")
            if new.strip() == shown.strip():
                return
            val = new.strip().replace("\r\n", "\n").replace("\n", "\\n")
        else:
            val = (self.pv_title if kind == "TitleText" else self.pv_btn).get()
            if val == d.get(path) or (kind == "ConfirmText" and path not in d.cur and not val.strip()):
                return
        d.set(path, val)
        self._pv_busy = True
        try:
            self.after_edit()
        finally:
            self._pv_busy = False
        if kind == "TitleText":
            self.show_total()

    def pv_change_pic(self):
        d = self.cur
        if d is None or not d.nout:
            return
        try:
            dlg = PicDialog(self, self.proj, self, "Encounters", "Change picture of this outcome")
            dlg.show()
            self.wait_window(dlg)
        except Exception:
            log_exc("event picture")
            self.app.say("The picture list could not be opened. Type the picture's name in the Picture box instead.")
            return
        if not dlg.result:
            return
        k, path = dlg.result
        if k == "__import":
            stem = re.sub(r"[^\w\-]+", "_", Path(path).stem).strip("_") or "picture"
            try:
                self.proj.stage_copy(path, "Encounters", stem)
            except ValueError as e:
                messagebox.showwarning("Picture", str(e), parent=self)
                return
            val = "Encounters/%s%s" % (stem, Path(path).suffix.lower() or ".png")
        else:
            f = self.proj.find_file("Encounters/" + k)
            val = "Encounters/%s%s" % (k, f.suffix if f else ".png")
        d.set(self.pv_path("Image"), val)
        self.proj._icons.clear()
        self.after_edit()
        self.show(d)

    def refresh_preview(self, force=False):
        d = self.cur
        if d is None or not hasattr(self, "pv_img") or not d.nout:
            return
        try:
            pre = d.opath(min(self.out_i, d.nout - 1))
            name = d.get(pre + "/Image").strip()
            path = self.proj.find_file(name) if name else None
            im = self.img(path, self.PV_W) if path else None
            self.pv_img.configure(image=im if im is not None else "",
                                  text="" if im is not None else ("(picture not found: %s)\nclick to pick one" % name if name else "(no picture - click to pick one)"),
                                  width=0 if im is not None else 40, height=0 if im is not None else 4)
            self.pv_img.image = im
            if force or not getattr(self, "_pv_busy", False):
                def put(w, text):
                    if self.focus_get() is w:
                        return
                    if isinstance(w, tk.Text):
                        w.delete("1.0", "end")
                        w.insert("1.0", text)
                    else:
                        w.delete(0, "end")
                        w.insert(0, text)
                put(self.pv_title, d.get(pre + "/TitleText"))
                put(self.pv_text, d.get(pre + "/DescriptionText").replace("\\n", "\n").strip())
                put(self.pv_btn, d.get(pre + "/ConfirmText").strip())
                lines = sum(max(1, -(-len(x) // 62)) for x in self.pv_text.get("1.0", "end-1c").split("\n"))
                self.pv_text.configure(height=max(4, min(lines + 1, 22)))
        except Exception:
            log_exc("event preview")

    def on_edited(self):
        self.refresh_preview()

    def build(self, d, p):
        if d.nout:
            self.out_i = min(self.out_i, d.nout - 1)
            self.preview(p, d)
        s = self.section(p, "Event")
        self.field(s, "Name", "Name", hint="The event's name (shown in lists; the game finds the event by its file).")
        if d.story() or "Story" in d.cur or d.get("TriggerWhenOnlyRemnantsLeft") or d.get("AllRemnantStories"):
            self.field(s, "Story", "Remnant story", "combo", "The Remnant story line this event belongs to (e.g. AncientExterminators). Leave empty for an ordinary event.", self.stories)
            self.field(s, "StoryStep", "Story step", "int", "Which step of the story this is (1 = the first message, 3, 4, 5 ... later ones).")
            self.field(s, "TriggerWhenOnlyRemnantsLeft", "Only when Remnants are left", "bool", "On = the event fires only when the Remnants are the last enemy.")
            self.field(s, "AllRemnantStories", "Shared by all stories", "bool", "On = the same event is used by every Remnant story.")
        else:
            r = s.nrow
            s.nrow += 1
            b = ttk.Button(s, text="＋ Make it a Remnant story step", command=lambda: (d.set("Story", ""), d.set("StoryStep", "1"), self.after_edit(), self.show(d)))
            b.grid(row=r, column=1, sticky="w", pady=2)
            tip(b, "Ordinary events do not need this. Story events belong to one of the Remnant story lines and have a step number.")
        # which outcome is shown: a row of buttons, one per outcome
        self.out_i = min(self.out_i, max(0, d.nout - 1))
        bar = tk.Frame(p, bg=PANEL2)
        bar.pack(fill="x", padx=14, pady=(8, 0))
        tk.Label(bar, text="Outcomes:", bg=PANEL2, fg=PEACH).pack(side="left", padx=(0, 6))
        for i in range(d.nout):
            ttl = d.get(d.opath(i) + "/TitleText").strip()
            sel = i == self.out_i
            tk.Button(bar, text="%d  %s" % (i + 1, clip_text(ttl, 18)) if ttl else str(i + 1), relief="sunken" if sel else "flat", bd=1,
                      bg=ORANGE if sel else PANEL, fg="#10131a" if sel else FG, cursor="hand2",
                      command=lambda i=i: self.pick_outcome(i)).pack(side="left", padx=2)
        b = ttk.Button(bar, text="＋", width=3, command=self.add_outcome)
        b.pack(side="left", padx=4)
        tip(b, "Add another possible result of this event. When there are several, each one is picked by its Chance (percent).")
        self.total = tk.Label(bar, text="", bg=PANEL2, fg=DIM, anchor="w")
        self.total.pack(side="left", padx=8)
        self.show_total()
        if d.nout:
            self.outcome(d, p, self.out_i)

    def pick_outcome(self, i):
        self.out_i = i
        self.show(self.cur)

    def show_total(self):
        d = self.cur
        if d is None or not hasattr(self, "total"):
            return
        t = 0
        for i in range(d.nout):
            v = d.get(d.opath(i) + "/Chance").strip()
            if re.fullmatch(r"\d+(\.\d+)?", v):
                t += float(v)
        self.total.configure(text=("chances add up to %g%%" % t + ("" if abs(t - 100) < 0.01 else "  (usually 100)")) if d.nout > 1 else "")

    def add_outcome(self):
        d = self.cur
        if d is None:
            return
        self.out_i = d.add_outcome([("Chance", "100" if d.nout == 0 else "0"), ("TitleText", "New outcome"), ("DescriptionText", "")])
        self.after_edit()
        self.show(d)

    def outcome(self, d, p, i):
        pre = d.opath(i)
        s = self.section(p, "This outcome")
        for tag, lab, kind, hint in (
                ("Chance", "Chance (%)", "int", "How likely this outcome is when the event fires (the chances of all outcomes should add up to 100)."),
                ("Image", "Picture", "text", "Picture shown in the pop-up (e.g. Encounters/remn.png). FILE: a picture in the game's Textures folder, name with its folder."),
                ("RemoveTrigger", "Remove trigger", "bool", "On = the exploration marker on the planet disappears after this outcome.")):
            w = self.field(s, pre + "/" + tag, lab, kind, hint)
            if kind == "multi":
                w.configure(height=8)
            if kind == "int":
                w.bind("<KeyRelease>", lambda _e: self.show_total(), add="+")
        # rewards and changes: only the ones this outcome has, plus a menu to add more
        s2 = self.section(p, "Rewards and changes")
        present = [t for t in EVENT_EFFECTS if (pre + "/" + t[0]) in d.cur]
        for tag, lab, hint, _dflt in present:
            self.field(s2, pre + "/" + tag, lab, "text", hint)
        rest = [t for t in EVENT_EFFECTS if (pre + "/" + t[0]) not in d.cur]
        if rest:
            r = s2.nrow
            s2.nrow += 1
            fr = tk.Frame(s2, bg=PANEL2)
            fr.grid(row=r, column=0, columnspan=3, sticky="w", padx=8, pady=(2, 6))
            var = tk.StringVar()
            cb = ttk.Combobox(fr, textvariable=var, values=["%s  (%s)" % (t[0], t[1]) for t in rest], width=44, state="readonly")
            cb.pack(side="left")
            tip(cb, "Pick an extra effect this outcome should have (credits, tech, artifact, planet changes ...).")

            def add(_e=None, var=var, rest=rest, pre=pre):
                tag = var.get().split("  ", 1)[0]
                if tag:
                    d.set(pre + "/" + tag, next((t[3] for t in rest if t[0] == tag), ""))
                    self.after_edit()
                    self.show(d)
            ttk.Button(fr, text="＋ Add", command=add).pack(side="left", padx=6)
        # ships and troops that appear: the lists that have names, plus a menu for the others
        s3 = self.section(p, "Ships and troops that appear")
        hidden = []
        for tag, lab, hint in EVENT_LISTS:
            if d.get_list(i, tag) or (i, tag) in self.shown_lists:
                self.list_box(s3, d, i, tag, lab, hint)
            else:
                hidden.append((tag, lab))
        if hidden:
            r = s3.nrow
            s3.nrow += 1
            fr = tk.Frame(s3, bg=PANEL2)
            fr.grid(row=r, column=0, columnspan=3, sticky="w", padx=8, pady=(2, 6))
            var = tk.StringVar()
            ttk.Combobox(fr, textvariable=var, values=[h[1] for h in hidden], width=24, state="readonly").pack(side="left")

            def addl(var=var, hidden=hidden, i=i):
                tag = next((t for t, l in hidden if l == var.get()), None)
                if tag:
                    self.shown_lists.add((i, tag))
                    self.show(d)
            ttk.Button(fr, text="＋ Add list", command=addl).pack(side="left", padx=6)

    def list_box(self, sec, d, i, tag, label, hint):
        r = sec.nrow
        sec.nrow += 1
        lb = tk.Label(sec, text=label, bg=PANEL2, fg=FG, anchor="w", width=self.LABEL_W)
        lb.grid(row=r, column=0, sticky="nw", padx=(8, 6), pady=2)
        tip(lb, hint)
        fr = tk.Frame(sec, bg=PANEL2)
        fr.grid(row=r, column=1, columnspan=2, sticky="we", padx=(0, 8), pady=2)
        items = d.get_list(i, tag)
        t = tk.Text(fr, height=max(2, min(len(items) + 1, 10)), wrap="none", width=36, **TEXT_OPTS)
        t.insert("1.0", "\n".join(items))
        t.pack(side="left", fill="x", expand=True)
        side = tk.Frame(fr, bg=PANEL2)
        side.pack(side="left", padx=6, anchor="n")
        info = tk.Label(side, text="", bg=PANEL2, fg=DIM, anchor="w", justify="left", wraplength=260)
        known = self.known_names(tag)

        def paint(lst):
            bad = sorted({x for x in lst if x.strip().lower() not in known}, key=str.lower)
            info.configure(text="%d listed" % len(lst) + (("   ·   no %s called: %s" % ("troop" if tag == "TroopsToSpawn" else "ship design", ", ".join(bad[:4]) + ("…" if len(bad) > 4 else ""))) if bad else ""),
                           fg="#e07070" if bad else DIM)

        def commit(_e=None):
            new = [x.strip() for x in t.get("1.0", "end-1c").split("\n") if x.strip()]
            if new != d.get_list(i, tag):
                d.set_list(i, tag, new)
                self.after_edit()
            paint(new)
        t.bind("<FocusOut>", commit)
        var = tk.StringVar()
        cb = ttk.Combobox(side, textvariable=var, values=sorted(known_display(self.proj, tag), key=str.lower), width=26)
        cb.pack(anchor="w")
        tip(cb, "Pick a name and press 'Add' to put it on a new line.")

        def add():
            v = var.get().strip()
            if v:
                t.insert("end", ("" if not t.get("1.0", "end-1c") or t.get("1.0", "end-1c").endswith("\n") else "\n") + v)
                commit()
        ttk.Button(side, text="Add", command=add).pack(anchor="w", pady=2)
        info.pack(anchor="w")
        paint(items)


def known_display(proj, tag):
    """The names offered for a ship / troop list (as the person knows them, not lower-cased)."""
    if tag == "TroopsToSpawn":
        return {(t.get("Name") or t.path.stem).strip() for t in proj.troops + proj.base_troops if (t.get("Name") or t.path.stem).strip()}
    return {d.name.strip() for d in proj.load_designs() if d.name.strip()}


class RemnantView(ttk.Frame):
    """The Remnants in one place: their race, ships, designs, modules, weapons and techs, and the story events that use them. Double-click a row
    to open it in its own tab. Things are found by name (remnant, ancient, xeno, drone ...), so the list is a guide, not a promise."""

    def __init__(self, master, app, tab):
        super().__init__(master)
        self.app, self.proj, self.tab = app, app.proj, tab
        self._filled, self.rows, self.group = False, {}, None
        self.imgs, self.pv, self.pv_job, self.pv_row = {}, None, None, None
        top = tk.Frame(self, bg=BG)
        top.pack(fill="x", padx=12, pady=(10, 2))
        tk.Label(top, text="REMNANTS   ·   race, ships and story", bg=BG, fg=ORANGE, font=("Segoe UI", 14, "bold")).pack(side="left")
        bar = tk.Frame(self, bg=BG)
        bar.pack(fill="x", padx=12, pady=2)
        tk.Label(bar, text="Filter", bg=BG, fg=DIM).pack(side="left")
        self.flt = tk.StringVar()
        e = ttk.Entry(bar, textvariable=self.flt, width=30)
        e.pack(side="left", padx=6)
        self.flt.trace_add("write", lambda *_a: self.fill())
        b = ttk.Button(bar, text="Rescan", command=self.reload)
        b.pack(side="left", padx=4)
        tip(b, "Look again (after you change events, designs or names).")
        self.sum = tk.Label(self, text="", bg=BG, fg=PEACH, anchor="w", justify="left", wraplength=1100)
        self.sum.pack(fill="x", padx=12)
        fr = tk.Frame(self, bg=BG)
        fr.pack(fill="both", expand=True, padx=12, pady=8)
        self.tv = ttk.Treeview(fr, columns=("detail", "src"), show="tree headings", selectmode="browse")
        self.tv.heading("#0", text="Remnant things (double-click to open)")
        self.tv.heading("detail", text="Detail")
        self.tv.heading("src", text="From")
        self.tv.column("#0", width=380)
        self.tv.column("detail", width=620)
        self.tv.column("src", width=70)
        sb = ttk.Scrollbar(fr, orient="vertical", command=self.tv.yview)
        self.tv.configure(yscrollcommand=sb.set)
        sb.pack(side="right", fill="y")
        self.tv.pack(side="left", fill="both", expand=True)
        self.tv.bind("<Double-1>", self.open_row)
        self.tv.bind("<Return>", self.open_row)
        self.tv.bind("<Motion>", self.on_motion, add="+")
        self.tv.bind("<Leave>", lambda _e: self.pv_close(), add="+")
        self.tv.bind("<MouseWheel>", lambda _e: self.pv_close(), add="+")
        self.tv.tag_configure("bad", foreground="#e07070")
        self.tv.tag_configure("grp", foreground=ORANGE)

    def ensure(self):
        if not self._filled:
            self._filled = True
            self.fill()

    def reload(self):
        if self._filled:
            self.fill()

    design_by_name = GameDocView.design_by_name
    design_text = GameDocView.design_text

    def icon_of(self, jump):
        """Ship picture for a hull / design row (the hull's IconPath)."""
        kind, obj = jump
        key = (kind, obj if isinstance(obj, str) else getattr(obj, "path", obj))
        if kind not in ("hull", "design"):
            return None
        if key not in self.imgs:
            im = None
            try:
                P = self.proj
                if kind == "design":
                    d = self.design_by_name(obj)
                    h = P.hull_by_name(d.hull) if d is not None and d.hull else None
                else:
                    h = P.hull_by_name(obj)
                pic = P.find_file(h.get("IconPath").strip()) if h is not None and h.get("IconPath").strip() else None
                im = self.app.icon(pic, 36, h.path.stem if h is not None else "") if pic else None
            except Exception:
                im = None
            self.imgs[key] = im
        return self.imgs[key]

    def pv_close(self):
        if self.pv_job is not None:
            try:
                self.tv.after_cancel(self.pv_job)
            except Exception:
                pass
            self.pv_job = None
        if self.pv is not None:
            self.pv.close()
        self.pv_row = None

    def on_motion(self, e):
        if self.group != "Ships":
            return
        row = self.tv.identify_row(e.y)
        if row == self.pv_row:
            return
        self.pv_close()
        self.pv_row = row
        j = self.rows.get(row) if row else None
        if not j or j[0] not in ("hull", "design"):
            return
        name = j[1] if j[0] == "design" else None
        if name is None:                                        # a hull: show the first design built on it
            try:
                name = next((d.name for d in self.proj.load_designs() if d.hull and self.proj.hull_key(self.proj.hull_by_name(d.hull)) == j[1]), None)
            except Exception:
                name = None
        if not name:
            return
        if self.pv is None:
            self.pv = DesignPreview(self)
        self.pv_job = self.tv.after(400, lambda: self.pv.show(self.tv, name, self.tv.winfo_rootx() + self.tv.winfo_width() + 10, self.tv.winfo_pointery() - 60))

    @staticmethod
    def is_rem(*names):
        return any(RE_REMNANT.search(n or "") for n in names)

    def collect(self):
        P = self.proj
        out = []                                                     # (group, label, detail, source, jump, bad)
        for src, docs in (("mod", P.races), ("game", P.base_races)):
            for r in docs:
                if self.is_rem(r.name(), r.path.stem):
                    out.append(("Race", r.name(), "%s  ·  ships: %s" % (r.rel.as_posix(), r.get("DefaultSalvageShip") or "-"), src, ("race", r), False))
        for src, hs in (("mod", P.hulls), ("game", P.base_hulls)):
            for h in hs:
                if self.is_rem(h.path.stem, h.get("VisibleName")) or "remnant" in h.path.as_posix().lower():
                    out.append(("Ships", "hull: " + (h.get("VisibleName") or h.path.stem), "%s  ·  role %s  ·  model %s" % (h.path.name, h.get("Role") or "-", h.get("ModelPath") or "-"),
                                src, ("hull", P.hull_key(h)), False))
        for d in P.load_designs():
            if self.is_rem(d.name) or "remnant" in d.sub.lower():
                out.append(("Ships", "design: " + d.name, "hull %s  ·  role %s  ·  %d modules" % (d.hull or "-", d.role or "-", len(d.slots)), "game" if d.is_base else "mod",
                            ("design", d.name), False))
        for grp, key, mods in (("Parts and tech", "module", [(m, "mod") for m in P.modules] + [(m, "game") for m in P.base_modules]),
                               ("Parts and tech", "weapon", [(w, "mod") for w in P.weapons] + [(w, "game") for w in P.base_weapons])):
            for m, src in mods:
                uid = (m.get("UID") or m.path.stem).strip()
                if self.is_rem(uid) or "remnant" in m.path.as_posix().lower():
                    out.append((grp, "%s: %s" % (key, uid), m.path.name, src, (key, uid), False))
        for t in P.techs:
            uid = (getattr(t, "uid", "") or t.path.stem).strip()
            if self.is_rem(uid, t.path.stem):
                out.append(("Parts and tech", "tech: " + uid, t.path.name, "mod", ("tech", t), False))
        known = {d.name.strip().lower() for d in P.load_designs()}
        troops = {x.strip().lower() for t in P.troops + P.base_troops for x in ((t.get("Name") or ""), t.path.stem) if x.strip()}
        tech_ids = {(getattr(t, "uid", "") or t.path.stem).strip().lower() for t in P.techs}
        for src, docs in (("mod", P.events), ("game", P.base_events)):
            for ev in docs:
                if ev.story() or self.is_rem(ev.name(), ev.path.stem):
                    sp = ev.spawned()
                    n = sum(len(v) for v in sp.values())
                    out.append(("Story events", ev.name(), "%s%s  ·  %d outcome(s)%s" % (ev.story() or "-", (" step %d" % ev.step()) if ev.step() else "", ev.nout,
                                ("  ·  %d ships / troops appear" % n) if n else ""), src, ("event", ev), False))
                for tag, names in ev.spawned().items():
                    pool = troops if tag == "TroopsToSpawn" else known
                    for nm in sorted({x for x in names if x.strip().lower() not in pool}, key=str.lower):
                        out.append(("Problems", "%s: '%s'" % (ev.name(), nm),
                                    "%s lists %s '%s' but no %s has that name - the game cannot spawn it" % (ev.path.name, "a troop" if tag == "TroopsToSpawn" else "a ship", nm,
                                                                                                         "troop" if tag == "TroopsToSpawn" else "ship design"), src, ("event", ev), True))
        return out

    def fill(self):
        words = self.flt.get().lower().split()
        self.tv.delete(*self.tv.get_children())
        self.rows = {}
        groups = {}
        n = 0
        flat = bool(self.group)
        if self.group == "Ships":
            icons_style()
            self.tv.configure(style="Icons.Treeview")
        for grp, label, detail, src, jump, bad in self.collect():
            if self.group and grp != self.group:
                continue
            if words and not all(w in ("%s %s %s" % (grp, label, detail)).lower() for w in words):
                continue
            if not flat and grp not in groups:
                groups[grp] = self.tv.insert("", "end", text=grp, open=grp in ("Race", "Problems", "Story events"), tags=("grp",))
            kw = {}
            if self.group == "Ships":
                im = self.icon_of(jump)
                if im is not None:
                    kw["image"] = im
            iid = self.tv.insert("" if flat else groups[grp], "end", text=("  " + label) if flat else label, values=(detail, src), tags=("bad",) if bad else (), **kw)
            self.rows[iid] = jump
            n += 1
        for grp, iid in groups.items():
            self.tv.item(iid, text="%s (%d)" % (grp, len(self.tv.get_children(iid))))
        probs = len(self.tv.get_children(groups["Problems"])) if "Problems" in groups else 0
        extra = "   Rest the pointer on a ship to see its modules laid out on the hull." if self.group == "Ships" else ""
        self.sum.configure(text="%d things found.   %s%s" % (n, ("%d problem(s): events list ships or troops that do not exist." % probs) if probs else
                                                          ("" if self.group else "No problems found in the events' ship and troop lists."), extra))

    def open_row(self, _e=None):
        sel = self.tv.selection()
        self.open_jump(self.rows.get(sel[0]) if sel else None)

    def open_jump(self, j):
        if not j:
            return
        kind, obj = j
        a = self.app
        try:
            if kind == "race" and a.racev is not None:
                a.nb.select(a.racev)
                a.racev.open("races", obj)
            elif kind == "hull":
                a.show_hull(obj)
            elif kind == "design":
                a.open_design(obj)
            elif kind in ("module", "weapon"):
                a.debug_goto((kind, obj))
            elif kind == "tech" and a.research is not None:
                a.nb.select(a.research)
                a.research.open_editor(obj)
            elif kind == "event":
                self.tab.open_event(obj)
        except Exception:
            log_exc("remnant open")
            a.say("That item could not be opened from here.")


def event_chain(proj, only_linked=True, story_only=False, on_change=None, actions=None):
    """(nodes, edges) for TreeBox: every exploration event as a box; an arrow when an outcome spawns / turns into a building whose
    EventTriggerUID is another event (that is how a story goes on: find it -> next place -> next event)."""
    evs = list(proj.events) + list(proj.base_events)
    by_stem = {}
    for e in evs:
        by_stem.setdefault(e.path.stem.lower(), e)
    leaves = {}
    edges_raw, missing = [], {}                                 # (src event, dst event or ('x', text), label)
    for e in evs:
        for i in range(e.nout):
            pre = e.opath(i)
            for tag, verb in (("SpawnBuildingOnPlanet", "spawns"), ("ReplaceWith", "turns into")):
                bn = e.get(pre + "/" + tag).strip()
                if not bn:
                    continue
                b = proj.building_by_name(bn)
                lab = "%s '%s'" % (verb, bn)
                if b is None:
                    edges_raw.append((e, ("x", "No building called '%s' was found (mod or base game)." % bn), lab))
                    continue
                trg = b.get("EventTriggerUID").strip()
                dst = by_stem.get(trg.lower()) if trg else None
                if dst is None and trg:
                    dst = next((x for x in evs if x.name().lower() == trg.lower()), None)
                if not trg:                                  # an ordinary building (mine, refinery ...): the chain ends here
                    leaves.setdefault(id(e), []).append(bn)
                elif dst is None:
                    edges_raw.append((e, ("x", "Building '%s' triggers event '%s', but no event has that name." % (bn, trg)), lab))
                else:
                    edges_raw.append((e, dst, lab))
    linked = {id(e) for e, d, _l in edges_raw} | {id(d) for e, d, _l in edges_raw if not isinstance(d, tuple)}
    nodes, edges, ids = [], [], {}

    def nid(e):
        return "e:" + e.path.stem

    def node(e):
        if nid(e) in ids:
            return
        ids[nid(e)] = e
        t0 = (e.get(e.opath(0) + "/DescriptionText") if e.nout else "").replace("\\n", "\n").strip()
        rew = []
        for i in range(e.nout):
            pre = e.opath(i)
            for tag, lab in (("UnlockTech", "tech"), ("SecretTechDiscovered", "secret tech"), ("GrantArtifact", "artifact"), ("MoneyGranted", "credits")):
                v = e.get(pre + "/" + tag).strip()
                if v and v.lower() != "false" and v != "0":
                    rew.append("%s%s" % (lab, (": " + v) if tag in ("UnlockTech", "SecretTechDiscovered", "MoneyGranted") else ""))
            n = sum(len(e.get_list(i, t)) for t, *_r in EVENT_LISTS)
            if i == 0 and leaves.get(id(e)):
                rew.append("leaves: " + ", ".join(sorted(set(leaves[id(e)]))[:3]))
            if n:
                rew.append("%d ships/troops" % n)
        st = ("%s step %d  ·  " % (e.story(), e.step()) if e.story() else "")
        nodes.append({"id": nid(e), "title": "%s%s" % (e.name(), "  (your mod)" if not e.vanilla else ""), "text": t0 or "(no text)",
                      "note": st + ("gives: " + ", ".join(rew[:4]) if rew else "no reward"), "fill": PANEL2, "outline": ORANGE if e.story() else BLUE,
                      "set": (lambda v, e=e: e.set(e.opath(0) + "/DescriptionText", v)) if e.nout else None,
                      "actions": (actions(e) if actions else [])})
    for e in evs:
        if (not only_linked or id(e) in linked) and (not story_only or e.story()):
            node(e)
    for e, d, lab in edges_raw:
        if nid(e) not in ids:
            continue
        if isinstance(d, tuple):
            if d[1] not in missing:                       # one red box per problem, however many outcomes lead to it
                missing[d[1]] = "x%d" % len(missing)
                nodes.append({"id": missing[d[1]], "title": "Missing", "text": d[1], "set": None, "fill": PANEL, "outline": "#e07070"})
            if not any(a == nid(e) and b == missing[d[1]] for a, b, _l in edges):
                edges.append((nid(e), missing[d[1]], lab))
        else:
            node(d)
            edges.append((nid(e), nid(d), lab))
    return nodes, edges


class ChainWizard(_Dialog):
    """Step by step: make a multi-stage exploration chain. Page 1: name + number of stages + where it starts. Then one page per stage
    (what the player reads, the reward, who guards it), then a review. result = a spec dict for make_chain(), or None."""
    REWARDS = ("Nothing", "Credits", "Tech", "Artifact")
    GUARDS = ("No guards", "Remnant ships", "Pirate ships", "Troops")

    def __init__(self, master, proj, events):
        super().__init__(master, "New multi-stage event")
        self.proj, self.events = proj, list(events)
        try:
            self.geometry("%dx%d" % (min(760, self.winfo_screenwidth() - 60), min(640, self.winfo_screenheight() - 110)))
        except Exception:
            self.geometry("760x640")
        self.page, self.stages, self.res = 0, [], {}
        self.v_name, self.v_n = tk.StringVar(value="My story"), tk.StringVar(value="3")
        self.v_hook, self.v_where = tk.StringVar(value="(I will hook the start up myself)"), tk.StringVar(value="On a random planet")
        self.head = tk.Label(self, bg=PANEL, fg=ORANGE, font=("Segoe UI", 13, "bold"), anchor="w")
        self.head.pack(fill="x", padx=14, pady=(12, 2))
        self.sub = tk.Label(self, bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=700)
        self.sub.pack(fill="x", padx=14)
        self.body = tk.Frame(self, bg=PANEL)
        self.body.pack(fill="both", expand=True, padx=14, pady=8)
        self.msg = tk.Label(self, bg=PANEL, fg="#ff8080", anchor="w", wraplength=700, justify="left")
        self.msg.pack(fill="x", padx=14)
        nav = tk.Frame(self, bg=PANEL)
        nav.pack(side="bottom", fill="x", padx=14, pady=10)
        self.b_back = ttk.Button(nav, text="◀ Back", command=self.back)
        self.b_back.pack(side="left")
        self.b_next = ttk.Button(nav, text="Next ▶", command=self.next)
        self.b_next.pack(side="right")
        ttk.Button(nav, text="Cancel", command=self.destroy).pack(side="right", padx=8)
        self.draw()

    def n(self):
        try:
            return max(2, min(6, int(self.v_n.get())))
        except ValueError:
            return 3

    def clear(self):
        for w in self.body.winfo_children():
            w.destroy()
        self.msg.configure(text="")

    def draw(self):
        self.clear()
        n = self.n() if self.page else 3
        b = self.body
        if self.page == 0:
            self.head.configure(text="Step 1: the chain")
            self.sub.configure(text="A chain is a row of places to explore. Each stage is an event (what the player reads) and a building on a planet that starts it. "
                                    "Finishing a stage makes the next place appear.")
            tk.Label(b, text="Name of the chain", bg=PANEL, fg=FG).grid(row=0, column=0, sticky="w", pady=6)
            ttk.Entry(b, textvariable=self.v_name, width=36).grid(row=0, column=1, sticky="w", padx=8)
            tk.Label(b, text="Number of stages (2 - 6)", bg=PANEL, fg=FG).grid(row=1, column=0, sticky="w", pady=6)
            ttk.Spinbox(b, from_=2, to=6, textvariable=self.v_n, width=5).grid(row=1, column=1, sticky="w", padx=8)
            tk.Label(b, text="Where does stage 1 come from?", bg=PANEL, fg=FG).grid(row=2, column=0, sticky="w", pady=6)
            names = ["(I will hook the start up myself)"] + sorted({"%s   [%s]" % (e.name(), e.path.stem) for e in self.events}, key=str.lower)
            ttk.Combobox(b, textvariable=self.v_hook, values=names, width=40, state="readonly").grid(row=2, column=1, sticky="w", padx=8)
            tk.Label(b, text="It appears when…", bg=PANEL, fg=FG).grid(row=3, column=0, sticky="w", pady=6)
            ttk.Combobox(b, textvariable=self.v_where, values=["On a random planet", "On the same planet"], width=26, state="readonly").grid(row=3, column=1, sticky="w", padx=8)
            tk.Label(b, text="Pick an existing event to start the chain from its first outcome (for example a Remnant story step), or hook it up yourself later.",
                     bg=PANEL, fg=DIM, wraplength=680, justify="left").grid(row=4, column=0, columnspan=2, sticky="w", pady=8)
            self.b_next.configure(text="Next ▶")
            self.b_back.configure(state="disabled")
        elif self.page <= n:
            i = self.page - 1
            st = self.stages[i]
            last = self.page == n
            self.head.configure(text="Stage %d of %d%s" % (self.page, n, "  (the last one)" if last else ""))
            self.sub.configure(text="What the player reads when they explore this place, what they get, and who is guarding it." +
                               ("" if last else " Finishing it makes stage %d appear." % (self.page + 1)))
            st["w"] = {}
            tk.Label(b, text="Title", bg=PANEL, fg=FG).grid(row=0, column=0, sticky="nw", pady=4)
            st["w"]["title"] = e1 = ttk.Entry(b, width=60)
            e1.insert(0, st["title"])
            e1.grid(row=0, column=1, columnspan=3, sticky="we", padx=8)
            tk.Label(b, text="Text", bg=PANEL, fg=FG).grid(row=1, column=0, sticky="nw", pady=4)
            st["w"]["text"] = t = tk.Text(b, width=60, height=8, wrap="word", **TEXT_OPTS)
            t.insert("1.0", st["text"])
            t.grid(row=1, column=1, columnspan=3, sticky="we", padx=8)
            tk.Label(b, text="Button says", bg=PANEL, fg=FG).grid(row=2, column=0, sticky="w", pady=4)
            st["w"]["btn"] = e2 = ttk.Entry(b, width=30)
            e2.insert(0, st["btn"])
            e2.grid(row=2, column=1, sticky="w", padx=8)
            tk.Label(b, text="Reward", bg=PANEL, fg=FG).grid(row=3, column=0, sticky="w", pady=4)
            rv = tk.StringVar(value=st["rew"])
            st["w"]["rew"] = rv
            ttk.Combobox(b, textvariable=rv, values=list(self.REWARDS), width=12, state="readonly").grid(row=3, column=1, sticky="w", padx=8)
            st["w"]["rval"] = ev_ = IconCombo(b, values=sorted({(getattr(t_, "uid", "") or t_.path.stem) for t_ in self.proj.techs}, key=str.lower), width=34)
            ev_.set(st["rval"])
            ev_.grid(row=3, column=2, sticky="w")
            tk.Label(b, text="Credits: a number.  Tech: pick or type its name.  Artifact: leave empty.", bg=PANEL, fg=DIM).grid(row=4, column=1, columnspan=3, sticky="w", padx=8)
            tk.Label(b, text="Guards", bg=PANEL, fg=FG).grid(row=5, column=0, sticky="nw", pady=4)
            gv = tk.StringVar(value=st["gkind"])
            st["w"]["gkind"] = gv
            ttk.Combobox(b, textvariable=gv, values=list(self.GUARDS), width=14, state="readonly").grid(row=5, column=1, sticky="nw", padx=8)
            st["w"]["guards"] = g = tk.Text(b, width=34, height=4, wrap="none", **TEXT_OPTS)
            g.insert("1.0", st["guards"])
            g.grid(row=5, column=2, columnspan=2, sticky="w")
            tk.Label(b, text="Guards: one name per line (a ship design or a troop). Leave 'No guards' for none.", bg=PANEL, fg=DIM).grid(row=6, column=1, columnspan=3, sticky="w", padx=8)
            self.b_next.configure(text="Next ▶" if not last else "Review ▶")
            self.b_back.configure(state="normal")
        else:
            self.head.configure(text="Review")
            lines = ["Chain '%s' - %d stages." % (self.v_name.get().strip(), n)]
            for i, st in enumerate(self.stages[:n]):
                lines.append("  %d. %s%s%s" % (i + 1, st["title"] or "(no title)", "   · reward: %s %s" % (st["rew"], st["rval"]) if st["rew"] != "Nothing" else "",
                                                "   · guards: %d" % len([x for x in st["guards"].split("\n") if x.strip()]) if st["gkind"] != "No guards" else ""))
            hook = self.v_hook.get()
            lines.append("")
            lines.append("Stage 1 starts from: %s." % ("the first outcome of '%s' (%s)" % (hook.split("   [")[0], self.v_where.get().lower()) if not hook.startswith("(") else "nothing yet - hook it up yourself"))
            lines.append("")
            lines.append("This makes %d events and %d buildings (that start them). Nothing is written until you press Save in the editor." % (n, n))
            self.sub.configure(text="Check it, then press Create.")
            tk.Label(b, text="\n".join(lines), bg=PANEL, fg=FG, justify="left", anchor="w", wraplength=700).pack(anchor="w")
            self.b_next.configure(text="Create")

    def grab(self):
        """Copy the page's fields into the stage record."""
        if 1 <= self.page <= self.n():
            st = self.stages[self.page - 1]
            w = st.get("w") or {}
            try:
                st["title"], st["text"] = w["title"].get().strip(), w["text"].get("1.0", "end-1c").strip()
                st["btn"], st["rew"], st["rval"] = w["btn"].get().strip(), w["rew"].get(), w["rval"].get().strip()
                st["gkind"], st["guards"] = w["gkind"].get(), w["guards"].get("1.0", "end-1c")
            except Exception:
                pass

    def ensure_stages(self):
        n = self.n()
        while len(self.stages) < n:
            k = len(self.stages) + 1
            self.stages.append({"title": "%s %d" % (self.v_name.get().strip() or "Stage", k), "text": "", "btn": "Continue", "rew": "Nothing", "rval": "", "gkind": "No guards", "guards": ""})

    def next(self):
        self.grab()
        if self.page == 0:
            nm = self.v_name.get().strip()
            if not nm or not re.fullmatch(r"[^\\/:*?\"<>|]+", nm):
                self.msg.configure(text="Give the chain a name without special characters.")
                return
            self.ensure_stages()
        elif self.page <= self.n():
            st = self.stages[self.page - 1]
            if not st["title"] or not st["text"]:
                self.msg.configure(text="Fill in the title and the text of this stage.")
                return
            if st["rew"] == "Credits" and not re.fullmatch(r"\d+", st["rval"]):
                self.msg.configure(text="Credits must be a whole number.")
                return
            if st["rew"] == "Tech" and not st["rval"]:
                self.msg.configure(text="Pick the tech this stage gives.")
                return
        else:
            n = self.n()
            self.result = {"name": self.v_name.get().strip(), "stages": self.stages[:n],
                           "hook": "" if self.v_hook.get().startswith("(") else self.v_hook.get(), "random": self.v_where.get().startswith("On a random")}
            self.destroy()
            return
        self.page += 1
        self.draw()

    def back(self):
        self.grab()
        if self.page > 0:
            self.page -= 1
            self.draw()


def make_chain(proj, spec):
    """Create the events and buildings of a ChainWizard spec (staged until Save). Returns the list of new event docs."""
    name, stages = spec["name"], spec["stages"]
    n = len(stages)
    names = ["%s %d" % (name, i + 1) for i in range(n)]
    for nm in names:                                           # check everything first so nothing is half made
        if proj.building_by_name(nm) is not None or any(e.path.stem.lower() == nm.lower() for e in proj.events + proj.base_events):
            raise ValueError("'%s' already exists - pick another chain name." % nm)
    made = []
    for i, st in enumerate(stages):
        ev = proj.new_gdoc("events", names[i])
        ev.set("Name", names[i])
        pre = ev.opath(0)
        ev.set(pre + "/TitleText", st["title"])
        ev.set(pre + "/DescriptionText", st["text"])
        ev.set(pre + "/ConfirmText", st["btn"] or "Continue")
        if st["rew"] == "Credits":
            ev.set(pre + "/MoneyGranted", st["rval"])
        elif st["rew"] == "Tech":
            ev.set(pre + "/UnlockTech", st["rval"])
        elif st["rew"] == "Artifact":
            ev.set(pre + "/GrantArtifact", "true")
        guards = [x.strip() for x in st["guards"].split("\n") if x.strip()]
        if guards and st["gkind"] != "No guards":
            ev.set_list(0, {"Remnant ships": "RemnantShipsToSpawn", "Pirate ships": "PirateShipsToSpawn", "Troops": "TroopsToSpawn"}[st["gkind"]], guards)
        if i + 1 < n:
            ev.set(pre + "/SelectRandomPlanet", "true")
            ev.set(pre + "/SpawnBuildingOnPlanet", names[i + 1])
        made.append(ev)
        proj.create_building_spec({"name": names[i], "desc": "A place to explore: %s" % st["title"], "short": st["title"], "folder": "Events", "cost": "40", "maint": "0",
                                   "icon": ("__none", None), "effects": [("EventTriggerUID", ev.path.stem), ("CanBuildAnywhere", "true"),
                                                                         ("Scrappable", "false"), ("NoRandomSpawn", "true")]})
    if spec.get("hook"):
        stem = re.search(r"\[([^\[\]]+)\]\s*$", spec["hook"])
        src = next((e for e in proj.events + proj.base_events if stem and e.path.stem == stem.group(1)), None) or \
            next((e for e in proj.events + proj.base_events if e.name() == spec["hook"]), None)
        if src is not None and src.nout:
            p0 = src.opath(0)
            if spec.get("random"):
                src.set(p0 + "/SelectRandomPlanet", "true")
                src.set(p0 + "/SpawnBuildingOnPlanet", names[0])
            else:
                src.set(p0 + "/ReplaceWith", names[0])
    return made


class EventChainView(ttk.Frame):
    """The exploration events as a map: which event leads to which. Orange boxes belong to a Remnant story; click a box to read or edit its text."""

    def __init__(self, master, app, tab):
        super().__init__(master)
        self.app, self.proj, self.tab, self._filled = app, app.proj, tab, False
        top = tk.Frame(self, bg=BG)
        top.pack(fill="x", padx=12, pady=(10, 2))
        tk.Label(top, text="EVENT CHAINS   ·   what leads to what", bg=BG, fg=ORANGE, font=("Segoe UI", 14, "bold")).pack(side="left")
        bar = tk.Frame(self, bg=BG)
        bar.pack(fill="x", padx=12, pady=2)
        tk.Label(bar, text="Show", bg=BG, fg=DIM).pack(side="left")
        self.mode = tk.StringVar(value="Linked events")
        cb = ttk.Combobox(bar, textvariable=self.mode, values=["Linked events", "Remnant story events", "All events"], state="readonly", width=22)
        cb.pack(side="left", padx=6)
        cb.bind("<<ComboboxSelected>>", lambda _e: self.refresh())
        tip(cb, "Linked events = only the ones that lead to another event or are led to. All events also shows the single ones.")
        b = ttk.Button(bar, text="Refresh", command=self.refresh)
        b.pack(side="left", padx=4)
        b = ttk.Button(bar, text="✦ New multi-stage event…", command=lambda: self.tab.wizard())
        b.pack(side="left", padx=12)
        tip(b, "A step by step helper: name the chain, write each stage, pick rewards and guards - it makes the events and buildings and links them.")
        tk.Label(self, text="Read left to right. An arrow means an outcome spawns (or turns the marker into) a building whose event comes next. "
                            "Orange = Remnant story, blue = other events, red = a link that goes nowhere. Click a box to edit its text or add a next stage.",
                 bg=BG, fg=DIM, anchor="w", justify="left", wraplength=1100).pack(fill="x", padx=12, pady=(2, 6))
        self.box = TreeBox(self, height=460, on_change=lambda: self.app.update_status())
        self.box.pack(fill="both", expand=True, padx=8, pady=(0, 8))

    def ensure(self):
        if not self._filled:
            self._filled = True
            self.refresh()

    def reload(self):
        if self._filled:
            self.refresh()

    def refresh(self, select=None):
        m = self.mode.get()
        nodes, edges = event_chain(self.proj, only_linked=m == "Linked events", story_only=m == "Remnant story events", actions=self.actions)
        self.box.set(nodes, edges, select=select)

    def actions(self, e):
        return [("Open in Events", lambda e=e: self.tab.open_event(e)), ("＋ Next stage…", lambda e=e: self.next_stage(e))]

    def next_stage(self, e):
        P = self.proj
        if not e.nout:
            return
        oi = 0
        if e.nout > 1:
            opts = ["%d: %s" % (i + 1, e.get(e.opath(i) + "/TitleText").strip() or "(no title)") for i in range(e.nout)]
            pick = ask_choice(self, "Next stage", "Which outcome of '%s' leads on?" % e.name(), opts)
            if not pick or pick not in opts:
                return
            oi = opts.index(pick)
        where = ask_choice(self, "Next stage", "Where does the next stage appear?",
                           ["On a random planet (a new place to explore)", "On this same planet (the marker turns into the next one)"])
        if not where:
            return
        name = self.app.line_dialog("Name of the next stage (its event and its building)", (e.name() + " 2")[:60])
        if not name or not name.strip():
            return
        name = name.strip()
        try:
            ne = P.new_gdoc("events", name)
            ne.set("Name", name)
            if e.story():
                ne.set("Story", e.story())
                ne.set("StoryStep", str(e.step() + 1 if e.step() else 1))
            P.create_building_spec({"name": name, "desc": "A place to explore: %s" % name, "short": name, "folder": "Events", "cost": "40", "maint": "0",
                                    "icon": ("__none", None), "effects": [("EventTriggerUID", ne.path.stem), ("CanBuildAnywhere", "true"),
                                                                           ("Scrappable", "false"), ("NoRandomSpawn", "true")]})
        except ValueError as ex:
            messagebox.showwarning("Next stage", str(ex))
            return
        pre = e.opath(oi)
        if where.startswith("On a random"):
            e.set(pre + "/SelectRandomPlanet", "true")
            e.set(pre + "/SpawnBuildingOnPlanet", name)
        else:
            e.set(pre + "/ReplaceWith", name)
        self.app.update_status()
        try:
            self.app.refresh()
        except Exception:
            pass
        self.tab.reload()
        self.refresh(select="e:" + ne.path.stem)
        self.app.say("Made the next stage '%s': a new event and a building that triggers it, linked from '%s'. Write its text on the Events page, then Save (Ctrl+S)." % (name, e.name()))


class RemnantSettingsView(ttk.Frame):
    """Everything that controls the Remnants, in one tab window: the game-wide switches and numbers in Globals.yaml (found by name, so none are missed -
    each shows the comment the game's own file has for it), the Remnant race's own settings, and the story chains."""
    KEYS = re.compile(r"remnant|ancient|exterminat|guardian|portal|hibernat|inhibitor|armageddon", re.I)

    def __init__(self, master, app, tab):
        super().__init__(master)
        self.app, self.proj, self.tab, self._filled = app, app.proj, tab, False
        self.sf = ScrollFrame(self, bg=PANEL2)
        self.sf.pack(fill="both", expand=True)

    def ensure(self):
        if not self._filled:
            self._filled = True
            self.build()

    def reload(self):
        if self._filled:
            self.build()

    def comments(self):
        """{key: the comment lines written just above it in Globals.yaml, plus a trailing comment}."""
        P = self.proj
        try:
            src = P.globals_path()
            text = read_file(src)[0] if src is not None else ""
        except Exception:
            return {}
        out, pend = {}, []
        for line in text.splitlines():
            st = line.strip()
            if st.startswith("#"):
                pend.append(st.lstrip("# ").rstrip())
                continue
            m = re.match(r"\s+([A-Za-z_]\w*)\s*:\s*[^#]*?(?:#\s*(.*))?$", line)
            if m:
                out[m.group(1)] = " ".join(pend + ([m.group(2).strip()] if m.group(2) else []))
            pend = [] if st else pend
        return out

    def section(self, title, hint=""):
        f = tk.LabelFrame(self.sf.inner, text=" %s " % title, bg=PANEL2, fg=PEACH, bd=1, relief="groove", labelanchor="nw")
        f.pack(fill="x", padx=14, pady=6)
        f.columnconfigure(1, weight=1)
        f.nrow = 0
        if hint:
            tip(f, hint)
        return f

    def build(self):
        for w in self.sf.inner.winfo_children():
            w.destroy()
        P = self.proj
        tk.Label(self.sf.inner, text="REMNANT SETTINGS   -   what controls the Remnants", bg=PANEL2, fg=ORANGE, font=("Segoe UI", 13, "bold"), anchor="w").pack(fill="x", padx=14, pady=(10, 2))
        tk.Label(self.sf.inner, bg=PANEL2, fg=DIM, anchor="w", justify="left", wraplength=1000,
                 text="The Remnants are driven from four places: (1) the Remnant race file (guardian fleets per planet type, ship level), (2) game-wide numbers and switches in "
                      "Globals.yaml, (3) the story chains - exploration events with a Story / Step - and (4) their ships, techs and buildings (the Remnants tab lists them).").pack(fill="x", padx=14)
        # ---- Globals.yaml
        s = self.section("Game-wide Remnant settings (Globals.yaml)", "Numbers and switches that apply to the whole game, not to one race. Saved into the mod's Globals.yaml.")
        try:
            gd = P.globals_doc()
            keys = sorted((k for k in gd.cur if self.KEYS.search(k)), key=str.lower)
            note = self.comments()
        except Exception as e:
            gd, keys, note = None, [], {}
            tk.Label(s, text="Globals.yaml could not be read: %s" % e, bg=PANEL2, fg="#e07070").grid(row=0, column=0, sticky="w", padx=8, pady=6)
        if gd is not None and not keys:
            tk.Label(s, text="No Remnant lines were found in Globals.yaml.", bg=PANEL2, fg=DIM).grid(row=0, column=0, sticky="w", padx=8, pady=6)
        for r, k in enumerate(keys[:60]):
            tk.Label(s, text=k, bg=PANEL2, fg=FG, anchor="w").grid(row=r * 2, column=0, sticky="nw", padx=(8, 10), pady=(6, 0))
            var = tk.StringVar(value=gd.cur.get(k, ""))
            lowv = var.get().strip().lower()

            def commit(_e=None, k=k, var=var):
                try:
                    P.set_global(k, var.get())
                    self.app.update_status()
                except ValueError as e:
                    messagebox.showwarning("Globals.yaml", str(e), parent=self)
            if lowv in ("true", "false"):
                w = make_switch(s, var, commit)
                w.grid(row=r * 2, column=1, sticky="w", pady=(6, 0))
            else:
                w = ttk.Entry(s, textvariable=var, width=18)
                w.grid(row=r * 2, column=1, sticky="w", pady=(6, 0))
                w.bind("<FocusOut>", commit)
                w.bind("<Return>", commit)
            tk.Label(s, text=note.get(k, "") or "(the file has no comment for this line)", bg=PANEL2, fg=DIM, anchor="w", justify="left", wraplength=900).grid(
                row=r * 2 + 1, column=0, columnspan=3, sticky="w", padx=(8, 8), pady=(0, 2))
            tip(w, "%s\n\n%s" % (k, note.get(k, "")))
        # ---- race
        s = self.section("The Remnant race", "Races\\Remnant.xml: the race that owns the Remnant fleets.")
        rem = [(r, "mod") for r in P.races if str(r.get("IsRemnantFaction")).strip().lower() == "true"] + [(r, "game") for r in P.base_races if str(r.get("IsRemnantFaction")).strip().lower() == "true"]
        if not rem:
            tk.Label(s, text="No race has IsRemnantFaction = true.", bg=PANEL2, fg=DIM).grid(row=0, column=0, sticky="w", padx=8, pady=6)
        seen = set()
        for r, src in rem:
            if r.path.stem.lower() in seen:
                continue
            seen.add(r.path.stem.lower())
            envs = ", ".join("%s %s" % (e, r.get("Env" + e)) for e in REMNANT_ENVS if r.get("Env" + e).strip() not in ("", "0"))
            tk.Label(s, bg=PANEL2, fg=FG, anchor="w", justify="left", wraplength=800,
                     text="%s  (%s)   -   base ship level %s;  prefers %s\nGuardian fleets per planet type: %s" % (
                         r.name() or r.path.stem, src, r.get("BaseShipLevel") or "-", r.get("PreferredEnv") or "-", envs or "(none set)")).grid(row=s.nrow, column=0, columnspan=2, sticky="w", padx=8, pady=4)
            s.nrow += 1
            b = ttk.Button(s, text="Edit %s in the Races tab…" % (r.name() or r.path.stem), command=lambda r=r: self.open_race(r))
            b.grid(row=s.nrow, column=0, columnspan=2, sticky="w", padx=8, pady=(0, 8))
            tip(b, "Opens the race: its Non-player tab has the guardian counts (Env...), the ship level and the story switch.")
            s.nrow += 1
        # ---- stories
        s = self.section("Story chains", "Exploration events with a Story and a StoryStep. The game starts one story at random (unless the story is switched off above).")
        stories = {}
        for src, docs in (("mod", P.events), ("game", P.base_events)):
            for ev in docs:
                if ev.story():
                    stories.setdefault(ev.story(), {}).setdefault(ev.path.stem, (ev.step(), ev, src))
                elif ev.get("AllRemnantStories").strip().lower() == "true":
                    stories.setdefault("(all stories)", {}).setdefault(ev.path.stem, (ev.step(), ev, src))
        if not stories:
            tk.Label(s, text="No story events were found.", bg=PANEL2, fg=DIM).grid(row=0, column=0, sticky="w", padx=8, pady=6)
        for name in sorted(stories, key=str.lower):
            evs = sorted(stories[name].values(), key=lambda x: (x[0], x[1].name().lower()))
            tk.Label(s, text=name, bg=PANEL2, fg=ORANGE, anchor="w", font=("Segoe UI", 10, "bold")).grid(row=s.nrow, column=0, sticky="nw", padx=(8, 10), pady=(6, 0))
            fr = tk.Frame(s, bg=PANEL2)
            fr.grid(row=s.nrow, column=1, sticky="w", pady=(6, 0))
            for stp, ev, src in evs:
                b = ttk.Button(fr, text="%s %s" % (("step %d:" % stp) if stp else "-", ev.name()[:26]), command=lambda ev=ev: self.tab.open_event(ev))
                b.pack(side="left", padx=2)
                tip(b, "Open this story event (%s, %s) in the Events tab." % (ev.path.name, src))
            s.nrow += 1

    def open_race(self, r):
        a = self.app
        try:
            if a.racev is not None:
                a.nb.select(a.racev)
                a.racev.open("races", r)
        except Exception:
            log_exc("remnant race", sys.exc_info())

    # ---- find any setting / search the game's code
    CODE_RX = re.compile(rb"[A-Za-z_][A-Za-z0-9_]{3,70}")
    CODE_KEYS = re.compile(r"remnant|ancient|exterminat|guardian|portal|hibernat|inhibitor|armageddon", re.I)

    def build_finder(self, gd, note):
        s = self.section("All game settings (Globals.yaml)", "Every simple setting of the game's Globals.yaml. Type part of a name or its comment (level, fleet, attack, wave, spawn ...); change a value and press Enter.")
        self.gd, self.note = gd, note
        top = tk.Frame(s, bg=PANEL2)
        top.grid(row=0, column=0, columnspan=3, sticky="we", padx=8, pady=4)
        tk.Label(top, text="Search", bg=PANEL2, fg=DIM).pack(side="left")
        self.fq = tk.StringVar()
        e = ttk.Entry(top, textvariable=self.fq, width=34)
        e.pack(side="left", padx=6)
        tip(e, "Part of a setting's name or of what the file says about it. Several words must all match.")
        self.fq.trace_add("write", lambda *_a: self.fill_finder())
        self.fcnt = tk.Label(top, bg=PANEL2, fg=DIM)
        self.fcnt.pack(side="left", padx=8)
        self.frows = tk.Frame(s, bg=PANEL2)
        self.frows.grid(row=1, column=0, columnspan=3, sticky="we", padx=8, pady=(0, 8))
        self.frows.columnconfigure(2, weight=1)
        self.fill_finder()

    FIND_MAX = 60

    def fill_finder(self):
        for w in self.frows.winfo_children():
            w.destroy()
        words = self.fq.get().lower().split()
        keys = [k for k in sorted(self.gd.cur, key=str.lower) if all(w in ("%s %s" % (k, self.note.get(k, ""))).lower() for w in words)]
        self.fcnt.configure(text="%d of %d settings%s" % (min(len(keys), self.FIND_MAX), len(self.gd.cur), "  (type to narrow the list)" if len(keys) > self.FIND_MAX else ""))
        for r, k in enumerate(keys[:self.FIND_MAX]):
            changed = self.gd.cur.get(k) != self.gd.orig.get(k)
            lb = tk.Label(self.frows, text=k, bg=PANEL2, fg=ORANGE if changed else FG, anchor="w", width=34)
            lb.grid(row=r, column=0, sticky="nw", padx=(0, 8), pady=3)
            var = tk.StringVar(value=self.gd.cur.get(k, ""))
            lowv = var.get().strip().lower()

            def commit(_e=None, k=k, var=var, lb=lb):
                try:
                    self.proj.set_global(k, var.get())
                    self.app.update_status()
                    lb.configure(fg=ORANGE if self.gd.cur.get(k) != self.gd.orig.get(k) else FG)
                except ValueError as ex:
                    messagebox.showwarning("Globals.yaml", str(ex), parent=self)
            if lowv in ("true", "false"):
                w = make_switch(self.frows, var, commit)
            else:
                w = ttk.Entry(self.frows, textvariable=var, width=22)
                w.bind("<FocusOut>", commit)
                w.bind("<Return>", commit)
            w.grid(row=r, column=1, sticky="nw", pady=3)
            ds = tk.Label(self.frows, text=self.note.get(k, "") or "", bg=PANEL2, fg=DIM, anchor="w", justify="left", wraplength=760)
            ds.grid(row=r, column=2, sticky="nw", padx=(12, 0), pady=3)
            for wdg in (lb, w, ds):
                tip(wdg, "%s\n\n%s\n\nCurrent value: %s   (game file value: %s)" % (k, self.note.get(k, "") or "(no comment in the file)", var.get(), self.gd.orig.get(k, "")))

    def code_files(self):
        out = []
        for b in getattr(self.proj, "base_roots", []):
            for pat in ("*.dll", "*.exe"):
                out += [p for p in Path(b).glob(pat) if p.is_file()]
        return out

    def scan_code(self):
        names = {}
        files = self.code_files()
        for f in files:
            try:
                data = f.read_bytes()
            except OSError:
                continue
            for m in self.CODE_RX.finditer(data):
                t = m.group().decode("ascii", "ignore")
                if self.CODE_KEYS.search(t):
                    names.setdefault(t, set()).add(f.name)
        have = set(self.gd.cur) if getattr(self, "gd", None) is not None else set()
        lines = ["REMNANT NAMES FOUND IN THE GAME'S PROGRAM FILES  (%s)" % VERSION, "Looked in: %s" % ", ".join(sorted({f.name for f in files})) if files else "No program files (.dll / .exe) were found next to the game.", "",
                 "  * = also a line in Globals.yaml (editable in this tab)", ""]
        for t in sorted(names, key=str.lower):
            lines.append("%s %-48s %s" % ("*" if t in have else " ", t, ", ".join(sorted(names[t]))[:60]))
        try:
            d = Path(self.proj.root) / BACKUP_DIR
            d.mkdir(parents=True, exist_ok=True)
            (d / "remnant_code_search.txt").write_text("\n".join(lines) + "\n", encoding="utf-8")
        except OSError:
            pass
        return lines, len(names), len([t for t in names if t in have])

    def run_scan(self):
        lines, n, k = self.scan_code()
        self.code_out.configure(state="normal")
        self.code_out.delete("1.0", "end")
        self.code_out.insert("1.0", "\n".join(lines))
        self.code_out.configure(state="disabled")
        self.code_lb.configure(text="%d Remnant-related names found in the game's program; %d of them are Globals.yaml settings (marked *). Saved to Test Reports and Backups\\remnant_code_search.txt." % (n, k))

    def build_code(self, s):
        b = ttk.Button(s, text="Search the game's program files…", command=self.run_scan)
        b.grid(row=0, column=0, sticky="w", padx=8, pady=6)
        tip(b, "Reads the game's .dll / .exe files for every name that has Remnant, Ancient, Guardian, Portal, Hibernation ... in it. Names that are also lines of Globals.yaml can be edited in this tab.")
        self.code_lb = tk.Label(s, bg=PANEL2, fg=DIM, anchor="w", justify="left", wraplength=900, text="Settings can live in the game's code. This lists the names it contains.")
        self.code_lb.grid(row=1, column=0, sticky="w", padx=8)
        self.code_out = tk.Text(s, height=12, wrap="none", bg=PANEL, fg=FG, relief="flat", padx=8, pady=6, font=("Consolas", 9))
        self.code_out.grid(row=2, column=0, sticky="we", padx=8, pady=6)
        self.code_out.configure(state="disabled")


class RemnantStoriesView(EventsView):
    """The Remnant story chains, shown like the Events tab (list on the left sorted by story and step, the selected step's editor on the right) but
    only for the events that belong to a story (Story + StoryStep) or introduce the Remnants to every game (AllRemnantStories)."""

    def docs(self):
        return [d for d in GameDocView.docs(self) if is_remnant_event(d)]

    def sort_key(self, d):
        return (d.story() == "", d.story().lower(), d.step(), d.name().lower())

    def a_of(self, d):
        return d.story() or "(all stories)"

    def a_values(self):
        return {self.a_of(d) for d in self.docs()}

    def row(self, d):
        return (self.a_of(d), d.step() or "")


