def hsv_hex(h, sat, val):
    import colorsys
    a, b, c = colorsys.hsv_to_rgb(h % 1.0, sat, val)
    return "#%02x%02x%02x" % (int(a * 255), int(b * 255), int(c * 255))


def tk_rotate_photo(path, size, rot):
    """A picture scaled to 'size' and turned clockwise by 'rot' degrees using plain Tk (no Pillow needed). Nearest-neighbour; the result is cached by the caller."""
    import math
    src = tk.PhotoImage(file=str(path))
    sw, sh = src.width(), src.height()
    sub = int(max(sw, sh) // max(8, size))
    if sub > 1:
        src = src.subsample(sub)
        sw, sh = src.width(), src.height()
    grid = [[None] * sw for _ in range(sh)]
    for y in range(sh):
        row = grid[y]
        for x in range(sw):
            if not src.transparency_get(x, y):
                rgb = src.get(x, y)
                row[x] = "#%02x%02x%02x" % (rgb[0], rgb[1], rgb[2])
    k = size / float(max(sw, sh))
    w2, h2 = sw * k, sh * k
    a = math.radians(rot)
    ca, sa = math.cos(a), math.sin(a)
    W, H = int(abs(w2 * ca) + abs(h2 * sa)) + 2, int(abs(w2 * sa) + abs(h2 * ca)) + 2
    out = tk.PhotoImage(width=W, height=H)
    cx, cy, scx, scy = W / 2.0, H / 2.0, sw / 2.0, sh / 2.0
    for y in range(H):
        dy = y + 0.5 - cy
        cols, clear = [], []
        for x in range(W):
            dx = x + 0.5 - cx
            sx, sy = int(scx + (dx * ca + dy * sa) / k), int(scy + (-dx * sa + dy * ca) / k)
            c = grid[sy][sx] if (0 <= sx < sw and 0 <= sy < sh) else None
            if c is None:
                cols.append("#000000")
                clear.append(x)
            else:
                cols.append(c)
        out.put("{" + " ".join(cols) + "}", to=(0, y))
        for x in clear:
            out.transparency_set(x, y, True)
    return out


def auto_rot(path):
    """Guess how many degrees clockwise a ship picture must be turned so its nose points up: the picture's long axis, nose = the narrower end
    (needs Pillow). Snapped to 15 degrees. None when it cannot tell."""
    import math
    try:
        if Image is not None:
            im = Image.open(path).convert("RGBA")
            im.thumbnail((96, 96))
            w, h = im.size
            px = im.load()
            pts = [(x, y) for y in range(h) for x in range(w) if px[x, y][3] > 60]
        else:                                                           # no Pillow: read the picture with Tk itself
            src = tk.PhotoImage(file=str(path))
            sub = int(max(src.width(), src.height()) // 64)
            if sub > 1:
                src = src.subsample(sub)
            pts = [(x, y) for y in range(src.height()) for x in range(src.width()) if not src.transparency_get(x, y)]
        if len(pts) < 30:
            return None
        n = float(len(pts))
        cx, cy = sum(p[0] for p in pts) / n, sum(p[1] for p in pts) / n
        sxx = sum((x - cx) ** 2 for x, _y in pts)
        syy = sum((y - cy) ** 2 for _x, y in pts)
        sxy = sum((x - cx) * (y - cy) for x, y in pts)
        th = 0.5 * math.atan2(2 * sxy, sxx - syy)
        ux, uy = math.cos(th), math.sin(th)
        proj = [((x - cx) * ux + (y - cy) * uy, -(x - cx) * uy + (y - cy) * ux) for x, y in pts]
        lo, hi = min(a for a, _b in proj), max(a for a, _b in proj)
        span = hi - lo
        if span <= 0:
            return None
        ea = [b for a, b in proj if a <= lo + 0.25 * span]
        eb = [b for a, b in proj if a >= hi - 0.25 * span]
        ra = math.sqrt(sum(b * b for b in ea) / max(1, len(ea)))
        rb = math.sqrt(sum(b * b for b in eb) / max(1, len(eb)))
        sg = 1 if rb < ra else -1                                        # the nose is at the narrower end
        phi = math.degrees(math.atan2(uy * sg, ux * sg))                  # nose direction, clockwise from east (y points down)
        return int(round(((270 - phi) % 360) / 15.0)) * 15 % 360
    except Exception:
        return None


def mod_cat(m):
    """Which Arcade slot a module fits: weapon / shield / engine (speed) / power / ord (ordnance), or None."""
    mt = (m.get("ModuleType") or "").strip()
    if mt == "Armor":
        return "armor"
    if mt == "Hangar" or _n(m, "MaximumHangarShipSize") > 0:
        return "hangar"
    if (m.get("WeaponType") or "").strip():
        return "weapon"
    if mt == "Shield" and _n(m, "ShieldPowerMax") > 0:
        return "shield"
    if _n(m, "Thrust") > 0:
        return "engine"
    if _n(m, "PowerFlowMax") > 0:
        return "power"
    if _n(m, "OrdinanceCapacity") > 0:
        return "ord"
    return None


def mod_stats(proj, m, cat):
    """Three numbers to show for a module in the shop (the files' own values)."""
    if cat == "weapon":
        w = proj.weapon_for(m)
        if w is not None:
            return (max(_n(w, "DamageAmount"), _n(w, "PowerDamage")), _n(w, "FireDelay"), _n(w, "Range"))
        return (0, 0, 0)
    if cat == "shield":
        return (_n(m, "ShieldPowerMax"), _n(m, "ShieldRechargeRate"), _n(m, "ShieldRadius"))
    if cat == "power":
        return (_n(m, "PowerFlowMax"), _n(m, "PowerStoreMax"), _n(m, "Mass"))
    if cat == "ord":
        return (_n(m, "OrdinanceCapacity"), _n(m, "Mass"), _n(m, "PowerDraw"))
    if cat == "armor":
        return (_n(m, "HealthMax"), _n(m, "Mass"), _n(m, "Cost"))
    if cat == "hangar":
        return (_n(m, "MaximumHangarShipSize"), _n(m, "Mass"), _n(m, "Cost"))
    return (_n(m, "Thrust"), _n(m, "TurnThrust"), _n(m, "Mass"))


class RotCanvas:
    """The Arcade is played in 'upright' coordinates (enemies come from the top, you fly up). This wrapper turns every drawing call a quarter turn so the
    game really scrolls sideways: enemies come in from the right, you fly right. HUD items (tag 'hud' or 'raw') are placed in plain screen coordinates."""

    def __init__(self, cv, view):
        self.cv, self.v, self.kind = cv, view, {}

    def __getattr__(self, name):
        return getattr(self.cv, name)

    def pt(self, x, y):
        return self.v.SW - y, x

    @staticmethod
    def flat(a):
        out = []
        for x in a:
            if isinstance(x, (list, tuple)):
                out += list(x)
            else:
                out.append(x)
        return out

    @staticmethod
    def raw(kw):
        t = kw.get("tags") or ()
        t = (t,) if isinstance(t, str) else tuple(t)
        return "hud" in t or "raw" in t

    def tr(self, kind, c):
        if kind == "point":
            return list(self.pt(c[0], c[1]))
        if kind == "box":
            (a, b), (d, e) = self.pt(c[0], c[1]), self.pt(c[2], c[3])
            return [min(a, d), min(b, e), max(a, d), max(b, e)]
        out = []
        for i in range(0, len(c) - 1, 2):
            out += list(self.pt(c[i], c[i + 1]))
        return out

    def make(self, fn, kind, a, kw):
        c = self.flat(a)
        if self.raw(kw):
            return fn(*c, **kw)
        i = fn(*self.tr(kind, c), **kw)
        self.kind[i] = kind
        return i

    def create_image(self, *a, **kw):
        return self.make(self.cv.create_image, "point", a, kw)

    def create_text(self, *a, **kw):
        return self.make(self.cv.create_text, "point", a, kw)

    def create_oval(self, *a, **kw):
        return self.make(self.cv.create_oval, "box", a, kw)

    def create_rectangle(self, *a, **kw):
        return self.make(self.cv.create_rectangle, "box", a, kw)

    def create_arc(self, *a, **kw):
        if "start" in kw and not self.raw(kw):
            kw["start"] = (float(kw["start"]) - 90) % 360
        return self.make(self.cv.create_arc, "box", a, kw)

    def create_polygon(self, *a, **kw):
        return self.make(self.cv.create_polygon, "poly", a, kw)

    def create_line(self, *a, **kw):
        return self.make(self.cv.create_line, "poly", a, kw)

    def coords(self, item, *c):
        if not c:
            return self.cv.coords(item)
        k = self.kind.get(item) if isinstance(item, int) else None
        if k is None:
            return self.cv.coords(item, *self.flat(c))
        return self.cv.coords(item, *self.tr(k, self.flat(c)))

    def move(self, item, dx, dy):
        k = self.kind.get(item) if isinstance(item, int) else None
        if k is None and not isinstance(item, int):
            return self.cv.move(item, dx, dy)
        return self.cv.move(item, -dy, dx) if k is not None else self.cv.move(item, dx, dy)

    def delete(self, *ids):
        if "all" in ids:
            self.kind.clear()
        return self.cv.delete(*ids)


class ShipPick:
    """The Arcade's ship list (left side): races as groups, ships inside each sorted by cost. Behaves like the old drop-down (current / values)."""

    def __init__(self, view, tv):
        self.view, self.tv, self.last = view, tv, None
        tv.bind("<<TreeviewSelect>>", self.picked)

    def picked(self, _e=None):
        sel = self.tv.selection()
        if not sel:
            return
        if sel[0].isdigit():
            self.last = sel[0]
            self.view.ship_chosen()
        elif self.last is not None:                              # a race heading was clicked: keep the ship, fold / unfold the race
            try:
                self.tv.item(sel[0], open=str(self.tv.item(sel[0], "open")).lower() not in ("1", "true"))
            except Exception:
                pass
            self.tv.selection_set(self.last)

    def current(self, i=None):
        if i is None:
            sel = self.tv.selection()
            if sel and sel[0].isdigit():
                return int(sel[0])
            return int(self.last) if self.last is not None else -1       # the chosen ship may be hidden by the filter
        if self.tv.exists(str(i)):
            self.last = str(i)
            self.tv.selection_set(str(i))
            self.tv.see(str(i))
        elif self.last is not None and self.last == str(i):
            pass

    def __setitem__(self, _k, _v):
        self.rebuild()

    def rebuild(self):
        v, tv = self.view, self.tv
        tv.delete(*tv.get_children())
        races = {}
        words = ((v.v_filter.get() if getattr(v, "v_filter", None) is not None else "") or "").lower().split()
        for i, r in enumerate(v.hulls):
            if words and not all(w in ("%s %s %s %s" % (r["name"], r["role"], r["style"], "owned" if v.ship_owned(r) else "locked")).lower() for w in words):
                continue
            if v.f_race.get() not in ("(all)", "") and (r["style"] or "other") != v.f_race.get().lower():
                continue
            if v.f_role.get() not in ("(all)", "") and r["role"] != v.f_role.get():
                continue
            if v.f_src.get() not in ("(all)", "") and r.get("src") != v.f_src.get():
                continue
            races.setdefault(r["style"] or "other", []).append((v.ship_cost(r["role"]), r["name"].lower(), i))
        for race in sorted(races, key=lambda k: (k == "other", k)):
            tv.insert("", "end", iid="r:" + race, text=race.title(), open=True)
            for cost, _n, i in sorted(races[race]):
                r = v.hulls[i]
                im = v.pic(r["icon"], 28, 0, False)
                kw = {"image": im} if im is not None else {}
                tv.insert("r:" + race, "end", iid=str(i), text="%s  (%s)" % (r["name"], r["role"] or "ship"),
                          values=("✔" if v.ship_owned(r) else "🔒 %d" % cost,), **kw)
        if self.last is not None and tv.exists(self.last):
            tv.selection_set(self.last)


class ArcadeTune(_Dialog):
    """Sliders for the arcade's numbers (saved per mod). Changes apply straight away; the game must not be running."""

    def __init__(self, master, view):
        super().__init__(master, "Arcade tuning")
        self.v = view
        tk.Label(self, text="Tune the game (kept per mod)", bg=PANEL, fg=ORANGE, font=("Segoe UI", 12, "bold")).grid(row=0, column=0, columnspan=3, sticky="w", padx=14, pady=(12, 6))
        self.vars, self.vals = {}, {}
        for i, (key, label, unit, lo, hi, dflt, hint) in enumerate(ARCADE_TUNE):
            lb = tk.Label(self, text=label, bg=PANEL, fg=FG, anchor="w")
            lb.grid(row=i + 1, column=0, sticky="w", padx=(14, 8), pady=3)
            tip(lb, hint)
            var = tk.DoubleVar(value=view.tn(key))
            self.vars[key] = var
            sc = ttk.Scale(self, from_=lo, to=hi, variable=var, length=260, command=lambda _v, k=key: self.changed(k))
            sc.grid(row=i + 1, column=1, padx=6)
            vl = tk.Label(self, bg=PANEL, fg=DIM, width=8, anchor="e")
            vl.grid(row=i + 1, column=2, sticky="e", padx=(0, 14))
            self.vals[key] = vl
            self.show(key)
        bt = tk.Frame(self, bg=PANEL)
        bt.grid(row=len(ARCADE_TUNE) + 1, column=0, columnspan=3, sticky="ew", padx=14, pady=12)
        ttk.Button(bt, text="Reset to defaults", command=self.reset).pack(side="left")
        ttk.Button(bt, text="Close", style="Save.TButton", command=self.destroy).pack(side="right")

    def show(self, key):
        spec = next(t for t in ARCADE_TUNE if t[0] == key)
        v = self.vars[key].get()
        self.vals[key].configure(text=("%d %%" % round(v)) if spec[2] == "%" else "x %.2f" % v)

    def changed(self, key):
        spec = next(t for t in ARCADE_TUNE if t[0] == key)
        v = float(self.vars[key].get())
        v = round(v) if spec[2] == "%" else round(v, 2)
        self.v.proj.settings.setdefault("arcade_tune", {})[key] = v
        self.show(key)
        self.v.tune_changed()

    def reset(self):
        self.v.proj.settings["arcade_tune"] = {}
        for t in ARCADE_TUNE:
            self.vars[t[0]].set(t[5])
            self.show(t[0])
        self.v.tune_changed()


