class MainMenuView(ttk.Frame):
    """Main tab: the game's main menu. The menu picture is the backdrop; every ship / asteroid of the scene file is drawn over it as a small generic ship or rock
    (one for each Count, spread through the zone the numbers describe), with sliders for every number. The projection is my best reading of the game's camera:
    the field-of-view slider lines it up."""
    COLS = ["#ffb347", "#6fd0ff", "#a5e86a", "#ff7a9c", "#d49bff", "#ffe56b", "#6fffd2", "#ff9f6f"]
    SIZES = {"fighter": 30, "corvette": 60, "frigate": 110, "cruiser": 200, "battleship": 320, "capital": 420, "titen": 600, "titan": 600,
             "freighter": 160, "station": 500, "asteroid": 120, "spacejunk": 40, "platform": 150, "carrier": 300, "scout": 40}
    DRAW_MAX = 400                                          # most things drawn for one line (the number shown is noted on the label)
    RANGES = {"SunPos": (-100000, 100000, 100), "CameraPos": (-20000, 20000, 50), "LookAt": (-60000, 60000, 100), "MinPos": (-30000, 30000, 50),
              "MaxPos": (-30000, 30000, 50), "Position": (-10000, 10000, 10), "Offset": (0, 5000, 10), "Rotation": (-360, 360, 1), "RandRot": (0, 360, 1),
              "SunColor": (0, 255, 1), "AmbientColor": (0, 255, 1), "SunIntensity": (0, 10, 0.05), "AmbientIntensity": (0, 3, 0.05), "Count": (0, 300, 1),
              "Scale": (0, 5, 0.05), "Speed": (0, 500, 1), "Orbit": (-100000, 100000, 50)}

    def __init__(self, master, app):
        super().__init__(master)
        self.app, self.proj, self._filled = app, app.proj, False
        self.fov = tk.DoubleVar(value=float(self.proj.settings.get("menu_fov", 45)))
        self.show_boxes, self.show_labels = tk.BooleanVar(value=False), tk.BooleanVar(value=True)
        self.sel = None
        self.bgimg, self.bgsize, self.vars, self.svars, self.hits = None, None, {}, {}, []
        self.PW, self.PH, self.ox, self.oy = 800, 450, 0, 0
        self._busy = False
        self._pending = None
        self.anim_t, self.playing, self._last = 0.0, False, 0.0
        self.anim_mult = tk.DoubleVar(value=float(self.proj.settings.get("menu_anim_mult", 20)))

    def update_title(self):
        try:
            self.app.nb.tab(self, text="Main menu")
        except Exception:
            pass

    def ensure(self):
        if not self._filled:
            self._filled = True
            self.build()

    def reload(self):
        if self._filled:
            self.build()

    # ---- files
    def scene(self):
        P = self.proj
        gd = next((d for d in P.extra_docs if isinstance(d, SceneDoc)), None)
        if gd is not None:
            return gd
        rel = main_menu_files(P)["scene"]
        if not rel:
            raise ValueError("No MainMenus.yaml with a SceneFile was found in the mod or the game.")
        src = find_content_file(P, rel)
        if src is None:
            raise ValueError("The scene file %s was not found." % rel)
        if src.is_relative_to(P.root):
            gd = SceneDoc(src, P.root)
        else:
            text, bom, enc = read_file(src)
            gd = SceneDoc(P.root / rel, P.root, text=text, bom=bom, enc=enc)
        P.extra_docs.append(gd)
        return gd

    def background_name(self):
        rel = main_menu_files(self.proj)["layout"]
        f = find_content_file(self.proj, rel) if rel else None
        if f:
            t = read_file(f)[0]
            m = re.search(r"Name:\s*background\s*\n\s*Texture:\s*(\S+)", t)
            if m:
                return m.group(1)
        return "MMenu/new_background.png"

    def background_path(self):
        """The picture the game's menu layout names (MMenu/new_background.png ...): a staged one, the mod's, BB+'s, then any other mod's; any format the editor reads."""
        P = self.proj
        name = self.background_name()
        stem = name.rsplit("/", 1)[-1].rsplit(".", 1)[0].lower()
        for fd in reversed(P.file_docs):                      # a picture staged but not saved yet
            if fd.tex.rsplit("/", 1)[-1].lower() == stem and fd.tex.lower().startswith("mmenu/"):
                return fd.src
        for st, path, _o in P.texture_choices("MMenu"):
            if st.lower() == stem:
                return path
        try:
            p = P.find_file(name)
            if p:
                return p
        except Exception:
            pass
        try:                                                   # the whole library (this mod, BB+, other mods), any folder depth
            best = None
            for label, top, rel, ext, _size, _k in P.library_scan(False):
                low = rel.lower()
                if ext in P.PIC_EXTS and low.rsplit("/", 1)[-1].rsplit(".", 1)[0] == stem and "mmenu" in low:
                    rank = (label != "This mod", label != "BB+ (base game)", ext not in (".png", ".jpg", ".jpeg"))
                    if best is None or rank < best[0]:
                        best = (rank, Path(top) / rel)
            if best:
                return best[1]
        except Exception:
            log_exc("menu picture search")
        return None

    # ---- build
    def build(self):
        for w in self.winfo_children():
            w.destroy()
        self.vars, self.svars = {}, {}
        head = tk.Frame(self, bg=BG)
        head.pack(fill="x", padx=10, pady=(6, 0))
        tk.Label(head, text="▣", bg=BG, fg=ORANGE, font=("Segoe UI Symbol", 22), width=2).pack(side="left", padx=(0, 8))
        mid = tk.Frame(head, bg=BG)
        mid.pack(side="left", fill="x", expand=True)
        tk.Label(mid, text="Main menu", bg=BG, fg=ORANGE, font=("Segoe UI", 16, "bold"), anchor="w").pack(fill="x")
        tk.Label(mid, bg=BG, fg=DIM, anchor="w", justify="left", wraplength=1100,
                 text="The picture behind the game's main menu with its ships and asteroids drawn over it - one small ship or rock for each Count. "
                      "Drag a slider (or type a number) and they move. Edits live in UI\\\\MMenu.*.scene.yaml and are saved with Save all.").pack(fill="x")
        ttk.Button(head, text="Change menu picture…", command=self.change_picture).pack(side="right", padx=4)
        try:
            self.doc = self.scene()
        except Exception as e:
            tk.Label(self, text="The main menu scene could not be read: %s" % e, bg=PANEL2, fg="#e07070").pack(padx=14, pady=10, anchor="w")
            return
        body = tk.Frame(self, bg=BG)
        body.pack(fill="both", expand=True, padx=6, pady=4)
        right = ScrollFrame(body, bg=PANEL2)
        right.canvas.configure(width=560)
        right.pack(side="right", fill="y")
        self.rf = right.inner
        left = tk.Frame(body, bg=BG)
        left.pack(side="left", fill="both", expand=True, padx=(0, 6))
        bar = tk.Frame(left, bg=BG)
        bar.pack(side="bottom", fill="x", pady=2)
        tk.Label(bar, text="Field of view", bg=BG, fg=DIM).pack(side="left")
        sc = ttk.Scale(bar, from_=20, to=100, variable=self.fov, command=lambda _v: self.fov_changed(), length=220)
        sc.pack(side="left", padx=6)
        tip(sc, "The game's real camera angle is not stored in the scene file, so this lines the picture and the ships up (preview only, not saved in the mod).")
        self.fovl = tk.Label(bar, bg=BG, fg=FG, width=5)
        self.fovl.pack(side="left")
        ttk.Checkbutton(bar, text="names", variable=self.show_labels, command=self.draw).pack(side="left", padx=8)
        ttk.Checkbutton(bar, text="zone outlines", variable=self.show_boxes, command=self.draw).pack(side="left")
        bar2 = tk.Frame(left, bg=BG)
        bar2.pack(side="bottom", fill="x", pady=2)
        self.play_btn = ttk.Button(bar2, text="▶ Play", width=9, command=self.toggle_play)
        self.play_btn.pack(side="left")
        tip(self.play_btn, "Moves the ships across the preview at their Speed (the ships fly along the direction of their Rotation and start again at the other side of their zone).")
        ttk.Button(bar2, text="⟲", width=3, command=self.restart).pack(side="left", padx=3)
        tk.Label(bar2, text="Preview speed", bg=BG, fg=DIM).pack(side="left", padx=(10, 2))
        ms = ttk.Scale(bar2, from_=1, to=100, variable=self.anim_mult, length=200, command=lambda _v: self.mult_changed())
        ms.pack(side="left")
        tip(ms, "How much faster than the game the preview runs. At 1x the ships move at the real Speed numbers, which is very slow to watch on a 30000-wide zone.")
        self.multl = tk.Label(bar2, bg=BG, fg=FG, width=6)
        self.multl.pack(side="left")
        self.mult_changed()
        self.info = tk.Label(bar, bg=BG, fg=DIM, anchor="w")
        self.info.pack(side="left", padx=10)
        self.cv = tk.Canvas(left, bg="#05060c", highlightthickness=1, highlightbackground="#444")
        self.cv.pack(fill="both", expand=True)
        self.cv.bind("<Button-1>", self.click)
        self.cv.bind("<Configure>", self.resized)
        self.build_fields()
        self.fovl.configure(text="%d°" % round(self.fov.get()))
        self.after(50, lambda: self.resized())

    def mult_changed(self):
        self.multl.configure(text="%dx" % round(self.anim_mult.get()))
        self.proj.settings["menu_anim_mult"] = round(self.anim_mult.get())

    def toggle_play(self):
        self.playing = not self.playing
        self.play_btn.configure(text="⏸ Pause" if self.playing else "▶ Play")
        if self.playing:
            import time
            self._last = time.perf_counter()
            self.after(50, self.tick)

    def restart(self):
        self.anim_t = 0.0
        self.draw()

    def tick(self):
        import time
        if not self.playing:
            return
        try:
            if not self.winfo_ismapped():                    # another tab is showing: wait without moving
                self._last = time.perf_counter()
            else:
                now = time.perf_counter()
                self.anim_t += (now - self._last) * self.anim_mult.get()
                self._last = now
                self.draw()
            self.after(50, self.tick)
        except tk.TclError:
            self.playing = False

    def resized(self, _e=None):
        try:
            w, h = self.cv.winfo_width(), self.cv.winfo_height()
        except tk.TclError:
            return
        if w < 50 or h < 50:
            return
        pw, ph = w - 2, int((w - 2) * 9 / 16)
        if ph > h - 2:
            ph, pw = h - 2, int((h - 2) * 16 / 9)
        self.PW, self.PH, self.ox, self.oy = pw, ph, (w - pw) // 2, (h - ph) // 2
        self.load_bg()
        self.draw()

    # ---- fields with sliders
    @staticmethod
    def numbers(text):
        t = (text or "").strip()
        if not t or not re.match(r"^\[?\s*-?\d+(\.\d+)?(\s*,\s*-?\d+(\.\d+)?)*\s*\]?$", t):
            return None
        return [float(x) for x in re.findall(r"-?\d+(?:\.\d+)?", t)]

    def fmt(self, key, orig, vals, step):
        def one(v):
            return ("%d" % round(v)) if step >= 1 or abs(v - round(v)) < 1e-9 else ("%.2f" % v).rstrip("0").rstrip(".")
        body = ", ".join(one(v) for v in vals) if ", " in (orig or "") else ",".join(one(v) for v in vals)
        return ("[%s]" % body) if (orig or "").strip().startswith("[") else body

    def field_row(self, parent, row, label, key):
        doc = self.doc
        kname = key.rsplit("/", 1)[-1]
        lb = tk.Label(parent, text=label, bg=PANEL2, fg=ORANGE if doc.changed(key) else FG, anchor="nw", width=14)
        lb.grid(row=row, column=0, sticky="nw", padx=(6, 4), pady=2)
        cell = tk.Frame(parent, bg=PANEL2)
        cell.grid(row=row, column=1, sticky="w", pady=2)
        var = tk.StringVar(value=doc.cur.get(key, ""))
        e = ttk.Entry(cell, textvariable=var, width=26)
        e.pack(anchor="w")
        nums = self.numbers(doc.cur.get(key, ""))
        sl = []
        if nums and kname in self.RANGES and len(nums) <= 3:
            lo, hi, step = self.RANGES[kname]
            lo = min(lo, min(nums)); hi = max(hi, max(nums))
            row2 = tk.Frame(cell, bg=PANEL2)
            row2.pack(anchor="w")
            orig = doc.cur.get(key, "")
            for i, v in enumerate(nums):
                dv = tk.DoubleVar(value=v)
                sl.append(dv)

                def moved(_x=None, key=key, var=var, sl=sl, step=step, orig=orig, lb=lb):
                    if self._busy:
                        return
                    vals = [d.get() for d in sl]
                    if step < 1:
                        vals = [round(x / step) * step for x in vals]
                    text = self.fmt(key, orig, vals, step)
                    var.set(text)
                    doc.set(key, text)
                    lb.configure(fg=ORANGE if doc.changed(key) else FG)
                    self.app.update_status()
                    self.redraw_soon()
                ttk.Scale(row2, from_=lo, to=hi, variable=dv, command=moved, length=max(70, 150 // len(nums))).pack(side="left", padx=(0, 4))
        self.svars[key] = sl

        def commit(_e=None, key=key, var=var, lb=lb, sl=sl):
            doc.set(key, var.get().strip())
            lb.configure(fg=ORANGE if doc.changed(key) else FG)
            vals = self.numbers(var.get())
            if vals and len(vals) == len(sl):
                self._busy = True
                try:
                    for d, v in zip(sl, vals):
                        d.set(v)
                finally:
                    self._busy = False
            self.app.update_status()
            self.redraw_soon()
        e.bind("<FocusOut>", commit)
        e.bind("<Return>", commit)
        if kname in MENU_KEY_HELP:
            tk.Label(parent, text=MENU_KEY_HELP[kname], bg=PANEL2, fg=DIM, anchor="nw", justify="left", wraplength=250).grid(row=row, column=2, sticky="nw", padx=6, pady=2)
        self.vars[key] = var

    SPEEDS = {"fighter": (99, 200), "corvette": (99, 200), "frigate": (40, 200), "cruiser": (70, 110), "battleship": (80, 200), "capital": (40, 110),
              "titen": (70, 110), "titan": (70, 110), "freighter": (70, 110), "asteroid": (24, 40), "spacejunk": (20, 40)}
    MAXN = {"fighter": 30, "corvette": 25, "frigate": 20, "cruiser": 14, "battleship": 8, "capital": 6, "titen": 6, "titan": 6, "freighter": 40,
            "asteroid": 300, "spacejunk": 60}

    def build_random(self):
        f = tk.LabelFrame(self.rf, text=" Random generator ", bg=PANEL2, fg=PEACH, bd=1, relief="groove")
        f.pack(fill="x", padx=6, pady=4)
        self.rv_crowd = getattr(self, "rv_crowd", None) or tk.DoubleVar(value=25)
        self.rv_n, self.rv_sp, self.rv_zone, self.rv_rock = (getattr(self, "rv_n", None) or tk.BooleanVar(value=True), getattr(self, "rv_sp", None) or tk.BooleanVar(value=True),
                                                             getattr(self, "rv_zone", None) or tk.BooleanVar(value=False), getattr(self, "rv_rock", None) or tk.BooleanVar(value=False))
        self.rv_seed = getattr(self, "rv_seed", None) or tk.StringVar()
        tk.Label(f, text="Picks new numbers for the ship lines. The slider sets how crowded: towards 'a handful' most rolls give few ships and only now and then a "
                         "lot; towards 'crowded' most give many.", bg=PANEL2, fg=DIM, anchor="w", justify="left", wraplength=520).grid(row=0, column=0, columnspan=4, sticky="w", padx=6, pady=(2, 4))
        tk.Label(f, text="A handful", bg=PANEL2, fg=FG).grid(row=1, column=0, sticky="e", padx=(6, 2))
        sc = ttk.Scale(f, from_=0, to=100, variable=self.rv_crowd, length=200)
        sc.grid(row=1, column=1, columnspan=2)
        tk.Label(f, text="Crowded", bg=PANEL2, fg=FG).grid(row=1, column=3, sticky="w", padx=2)
        tip(sc, "Weights the random number of ships: left = mostly a handful (1 to a few of each type), right = mostly many.")
        for i, (t, v, h) in enumerate((("Counts", self.rv_n, "New Count for each ship line."), ("Speeds", self.rv_sp, "New Speed range for each line, fitted to the ship type."),
                                       ("Move zones a little", self.rv_zone, "Shift and resize each line's MinPos / MaxPos box by up to about 30%."),
                                       ("Include asteroids", self.rv_rock, "Also randomise the asteroid and space junk lines."))):
            cb = ttk.Checkbutton(f, text=t, variable=v)
            cb.grid(row=2 + i // 2, column=(i % 2) * 2, columnspan=2, sticky="w", padx=6)
            tip(cb, h)
        tk.Label(f, text="Seed (optional)", bg=PANEL2, fg=DIM).grid(row=4, column=0, columnspan=2, sticky="e", padx=(6, 2), pady=4)
        ttk.Entry(f, textvariable=self.rv_seed, width=12).grid(row=4, column=2, sticky="w")
        bb = tk.Frame(f, bg=PANEL2)
        bb.grid(row=5, column=0, columnspan=4, sticky="w", padx=6, pady=(0, 6))
        b = ttk.Button(bb, text="🎲 Randomize", command=self.randomize)
        b.pack(side="left")
        tip(b, "Roll new numbers. Press again for another roll; a seed makes the same roll every time. Nothing is saved until Save all, and Undo goes back.")
        self.rv_undo = ttk.Button(bb, text="Undo last roll", command=self.undo_random)
        self.rv_undo.pack(side="left", padx=8)

    def randomize(self):
        import random
        doc = self.doc
        seed = self.rv_seed.get().strip()
        rnd = random.Random(seed) if seed else random.Random()
        crowd = max(0.0, min(1.0, self.rv_crowd.get() / 100.0))
        k = 0.5 + 5.0 * (1.0 - crowd)                       # frac = u ** k: a big k piles the rolls near zero (few ships), a small one spreads them out
        changed = []
        for gi, g in enumerate(doc.groups):
            for oi, ln in enumerate(g["lines"]):
                typ = (doc.cur.get("G%d/%d/Type" % (gi, oi)) or "").strip().lower()
                rock = typ in ("asteroid", "spacejunk")
                if typ == "station" or (rock and not self.rv_rock.get()):
                    continue
                if self.rv_n.get() and "Count" in ln["keys"]:
                    mx = self.MAXN.get(typ, 20)
                    n = max(1, int(round(1 + (rnd.random() ** k) * (mx - 1))))
                    changed.append(("G%d/%d/Count" % (gi, oi), str(n)))
                if self.rv_sp.get() and "Speed" in ln["keys"]:
                    key = "G%d/%d/Speed" % (gi, oi)
                    old = doc.cur.get(key, "")
                    a, b = self.SPEEDS.get(typ, (40, 200))
                    lo = rnd.uniform(a, (a + b) / 2)
                    hi = rnd.uniform(lo + 1, max(lo + 2, b))
                    vals = [round(lo)] if len(self.numbers(old) or [0, 0]) == 1 else [round(lo), round(hi)]
                    changed.append((key, self.fmt(key, old, vals, 1)))
                if self.rv_zone.get() and "MinPos" in ln["keys"] and "MaxPos" in ln["keys"]:
                    kmin, kmax = "G%d/%d/MinPos" % (gi, oi), "G%d/%d/MaxPos" % (gi, oi)
                    a, b = vec_of(doc.cur.get(kmin)), vec_of(doc.cur.get(kmax))
                    na, nb = [], []
                    for i in range(3):
                        c, half = (a[i] + b[i]) / 2, (b[i] - a[i]) / 2
                        half2 = half * rnd.uniform(0.7, 1.3)
                        c2 = c + abs(half) * rnd.uniform(-0.3, 0.3)
                        na.append(round(c2 - half2))
                        nb.append(round(c2 + half2))
                    changed.append((kmin, self.fmt(kmin, doc.cur.get(kmin), na, 1)))
                    changed.append((kmax, self.fmt(kmax, doc.cur.get(kmax), nb, 1)))
        if not changed:
            self.app.say("Nothing to randomise (tick Counts, Speeds or Move zones).")
            return
        self.undo_stack = [(k, doc.cur.get(k)) for k, _v in changed]
        for k, v in changed:
            doc.set(k, v)
        self.app.update_status()
        self.refresh_fields()
        self.app.say("Rolled new numbers for %d settings (not saved yet: Save all keeps them, 'Undo last roll' goes back)." % len(changed))

    def undo_random(self):
        st = getattr(self, "undo_stack", None)
        if not st:
            self.app.say("Nothing to undo.")
            return
        for k, v in st:
            self.doc.set(k, v)
        self.undo_stack = None
        self.app.update_status()
        self.refresh_fields()

    def refresh_fields(self):
        """Rebuild the settings column (after a roll) and redraw the preview."""
        for w in self.rf.winfo_children():
            w.destroy()
        self.vars, self.svars = {}, {}
        self.build_fields()
        self.redraw_soon()

    def build_fields(self):
        doc = self.doc
        self.build_random()
        f = tk.LabelFrame(self.rf, text=" Light and camera ", bg=PANEL2, fg=PEACH, bd=1, relief="groove")
        f.pack(fill="x", padx=6, pady=4)
        for r, k in enumerate(SceneDoc.TOP):
            if k in doc.cur:
                self.field_row(f, r, k, k)
        for gi, g in enumerate(doc.groups):
            col = self.COLS[gi % len(self.COLS)]
            lf = tk.LabelFrame(self.rf, text=" %s " % (g["name"] or "Group %d" % (gi + 1)), bg=PANEL2, fg=col, bd=1, relief="groove")
            lf.pack(fill="x", padx=6, pady=4)
            r = 0
            if g["ai"]:
                tk.Label(lf, text="Behaviour: " + "  →  ".join("[%s]" % a for a in g["ai"]), bg=PANEL2, fg=DIM, anchor="w", justify="left", wraplength=520).grid(row=r, column=0, columnspan=3, sticky="w", padx=6)
                r += 1
            for oi, ln in enumerate(g["lines"]):
                t = doc.cur.get("G%d/%d/Type" % (gi, oi), "?")
                hd = tk.Label(lf, text="— %s —" % t, bg=PANEL2, fg=col, anchor="w", cursor="hand2")
                hd.grid(row=r, column=0, columnspan=3, sticky="w", padx=6, pady=(6, 0))
                hd.bind("<Button-1>", lambda _e, gi=gi: self.select(gi))
                r += 1
                for k in ln["keys"]:
                    if k == "Type":
                        continue
                    self.field_row(lf, r, k, "G%d/%d/%s" % (gi, oi, k))
                    r += 1

    # ---- picture
    def load_bg(self):
        p = self.background_path()
        self.bgpath = p
        key = (str(p), self.PW, self.PH)
        if self.bgsize == key:
            return
        self.bgimg, self.bgsize = None, key
        if not p:
            return
        if Image and Path(p).suffix.lower() != ".xnb":
            try:
                im = Image.open(p).convert("RGB").resize((self.PW, self.PH), getattr(Image, "Resampling", Image).LANCZOS)
                self.bgimg = ImageTk.PhotoImage(im)
                return
            except Exception:
                self.bgimg = None
        try:                                                  # no Pillow, or a .dds / .xnb it can't open: the built-in readers (scaled to about this size)
            self.bgimg = stretch_photo(read_photo(p), self.PW, self.PH)
        except Exception:
            log_exc("menu picture")
            self.bgimg = None

    def change_picture(self):
        f = filedialog.askopenfilename(parent=self, title="Pick the new main menu picture",
                                       filetypes=[("Pictures", "*.png *.jpg *.jpeg *.bmp *.tga"), ("All files", "*.*")])
        if not f:
            return
        src = Path(f)
        name = self.background_name()
        rel = "Textures/" + name
        try:
            if Image and src.suffix.lower() != ".png":
                import tempfile
                tmp = Path(tempfile.mkdtemp()) / (name.rsplit("/", 1)[-1].rsplit(".", 1)[0] + ".png")
                Image.open(src).convert("RGBA").save(tmp)
                src = tmp
            elif src.suffix.lower() != ".png":
                raise ValueError("Pillow is needed to convert %s to .png; pick a .png file." % src.suffix)
            self.proj.stage_asset(src, rel, replace=True)
        except Exception as e:
            messagebox.showwarning("Main menu picture", str(e), parent=self)
            return
        self.app.update_status()
        self.bgsize = None
        self.load_bg()
        self.draw()
        self.app.say("Menu picture will be copied to %s when you Save (the game's layout calls it %s; 16:9, e.g. 1920x1080, fits best)." % (rel, name))

    # ---- drawing
    def fov_changed(self):
        self.fovl.configure(text="%d°" % round(self.fov.get()))
        self.proj.settings["menu_fov"] = round(self.fov.get())
        self.redraw_soon()

    def redraw_soon(self):
        if self._pending is None:
            self._pending = self.after(30, self._redraw)

    def _redraw(self):
        self._pending = None
        self.draw()

    def project(self, p):
        """World (x, y, z) -> (canvas x, canvas y, depth) or None when behind the camera. Camera looks from CameraPos toward LookAt, +Y up."""
        import math
        cam, look = vec_of(self.doc.cur.get("CameraPos", "[0,0,-1000]")), vec_of(self.doc.cur.get("LookAt", "[0,0,10000]"))
        fw = [look[i] - cam[i] for i in range(3)]
        n = math.sqrt(sum(x * x for x in fw)) or 1.0
        fw = [x / n for x in fw]
        rt = [fw[2], 0.0, -fw[0]]
        rn = math.sqrt(sum(x * x for x in rt)) or 1.0
        rt = [x / rn for x in rt]
        u = [fw[1] * rt[2] - fw[2] * rt[1], fw[2] * rt[0] - fw[0] * rt[2], fw[0] * rt[1] - fw[1] * rt[0]]
        d = [p[i] - cam[i] for i in range(3)]
        z = sum(d[i] * fw[i] for i in range(3))
        if z < 50:
            return None
        x = sum(d[i] * rt[i] for i in range(3))
        y = sum(d[i] * u[i] for i in range(3))
        f = (self.PH / 2) / math.tan(math.radians(self.fov.get()) / 2)
        return (self.PW / 2 + x / z * f, self.PH / 2 - y / z * f, z, f / z)

    def scene_items(self):
        """Everything to draw: [{gi, oi, kind, x, y, z, size, dir, col, i}] far to near. One item for each Count (at most DRAW_MAX a line)."""
        import math
        import random
        out, labels = [], {}
        doc = self.doc
        orbits = {}
        for gi, g in enumerate(doc.groups):
            for a in g["ai"]:
                m = re.match(r"Orbit,\s*\[[^\]]*\],\s*\[([^\]]*)\]", a)
                if m:
                    orbits[gi] = vec_of(m.group(1))
        for gi, g in enumerate(doc.groups):
            for oi, _ln in enumerate(g["lines"]):
                get = lambda k, gi=gi, oi=oi: doc.cur.get("G%d/%d/%s" % (gi, oi, k))
                typ = (get("Type") or "ship").strip().lower()
                try:
                    cnt = max(1, int(float((get("Count") or "1").strip().strip("[]") or 1)))
                except ValueError:
                    cnt = 1
                sc = self.numbers(get("Scale")) or [1.0]
                base = self.SIZES.get(typ, 150)
                rnd = random.Random(gi * 7919 + oi * 104729 + 17)
                rot = vec_of(get("Rotation") or "[0,0,0]")
                direction = -1 if rot[2] < 0 else 1
                kind = "rock" if typ in ("asteroid", "spacejunk") else ("station" if typ == "station" else "ship")
                col = "#8a7f74" if kind == "rock" else self.COLS[gi % len(self.COLS)]
                shown = min(cnt, self.DRAW_MAX)
                lo, hi = vec_of(get("MinPos")) if get("MinPos") else None, vec_of(get("MaxPos")) if get("MaxPos") else None
                pos1 = vec_of(get("Position")) if get("Position") else None
                orb = self.numbers(get("Orbit")) if get("Orbit") else None
                off = vec_of(get("Offset") or "[0,0,0]")
                n_in = 0
                spd = self.numbers(get("Speed")) or [0.0]
                t = self.anim_t
                for i in range(shown):
                    if lo is not None and hi is not None:
                        w = [min(lo[k], hi[k]) + rnd.random() * abs(hi[k] - lo[k]) for k in range(3)]
                    elif pos1 is not None:
                        w = list(pos1)
                    elif orb and gi in orbits and len(orb) >= 3:
                        a = math.radians(orb[1] + rnd.random() * (orb[2] - orb[1]))
                        c = orbits[gi]
                        w = [c[0] + orb[0] * math.cos(a) + (rnd.random() - .5) * 2 * off[0], c[1] + (rnd.random() - .5) * 2 * off[1],
                             c[2] + orb[0] * math.sin(a) + (rnd.random() - .5) * 2 * off[2]]
                    else:
                        continue
                    my = spd[0] + rnd.random() * (spd[-1] - spd[0])
                    if t:                                          # move it: ships along X (direction from Rotation), wrapping inside their zone; rocks round their orbit
                        if lo is not None and hi is not None and kind == "ship":
                            span = abs(hi[0] - lo[0]) or 1.0
                            x0 = min(lo[0], hi[0])
                            w[0] = x0 + ((w[0] - x0 + direction * my * t) % span)
                        elif orb and gi in orbits and len(orb) >= 3 and orb[0]:
                            c = orbits[gi]
                            a0, a1 = sorted((orb[1], orb[2]))
                            ang = a0 + ((math.degrees(math.atan2(w[2] - c[2], w[0] - c[0])) - a0 + math.degrees(my * t / orb[0])) % ((a1 - a0) or 1.0))
                            w[0] = c[0] + orb[0] * math.cos(math.radians(ang))
                            w[2] = c[2] + orb[0] * math.sin(math.radians(ang))
                    q = self.project(w)
                    if not q:
                        continue
                    size = base * (sc[0] + rnd.random() * (sc[-1] - sc[0])) * q[3]
                    out.append({"gi": gi, "oi": oi, "kind": kind, "x": q[0], "y": q[1], "z": q[2], "size": max(2.0, size), "dir": direction, "col": col, "i": i})
                    n_in += 1
                labels.setdefault(gi, []).append("%s x%d%s" % (typ, cnt, " (showing %d)" % shown if shown < cnt else ""))
        out.sort(key=lambda d: -d["z"])
        return out, labels

    def draw(self):
        if not getattr(self, "cv", None):
            return
        try:
            cv = self.cv
            cv.delete("all")
            ox, oy, PW, PH = self.ox, self.oy, self.PW, self.PH
            if self.bgimg is not None:
                cv.create_image(ox, oy, image=self.bgimg, anchor="nw")
            else:
                import random
                r = random.Random(5)
                cv.create_rectangle(ox, oy, ox + PW, oy + PH, fill="#070914", outline="")
                for _i in range(160):
                    x, y = ox + r.random() * PW, oy + r.random() * PH
                    cv.create_oval(x, y, x + 1.5, y + 1.5, fill="#8890b0", outline="")
                cv.create_text(ox + 8, oy + PH - 8, anchor="sw", fill="#55607a", font=("Segoe UI", 8),
                               text="(no menu picture found for Textures\\%s in this mod, BB+ or the other mods - use Change menu picture…)" % self.background_name())
            items, labels = self.scene_items()
            self.hits = []
            for it in items:
                x, y, s, col = it["x"] + ox, it["y"] + oy, it["size"], it["col"]
                if x < ox - 40 or x > ox + PW + 40 or y < oy - 40 or y > oy + PH + 40:
                    continue
                hot = it["gi"] == self.sel
                ol = "#ffffff" if hot else "#0a0b10"
                if it["kind"] == "rock":
                    import random
                    rr = random.Random(it["gi"] * 100003 + it["i"])
                    pts = []
                    for k in range(7):
                        ang = k * 6.2832 / 7
                        rad = s / 2 * (0.65 + rr.random() * 0.5)
                        pts += [x + rad * __import__("math").cos(ang), y + rad * __import__("math").sin(ang)]
                    cv.create_polygon(pts, fill=col, outline=ol, width=1 if (hot or s > 6) else 0)
                elif it["kind"] == "station":
                    cv.create_oval(x - s / 2, y - s / 2, x + s / 2, y + s / 2, fill="", outline=col, width=2 if s > 8 else 1)
                    cv.create_oval(x - s / 4, y - s / 4, x + s / 4, y + s / 4, fill=col, outline=ol)
                    cv.create_line(x - s * 0.7, y, x + s * 0.7, y, fill=col)
                else:
                    d = it["dir"]
                    hull = [(1.0, 0), (0.35, -0.22), (-0.55, -0.2), (-1.0, -0.38), (-0.85, 0), (-1.0, 0.38), (-0.55, 0.2), (0.35, 0.22)]
                    pts = []
                    for hx, hy in hull:
                        pts += [x + hx * d * s / 2, y + hy * s / 2]
                    cv.create_polygon(pts, fill=col, outline=ol, width=1 if (hot or s > 8) else 0)
                    if s > 14:
                        cv.create_oval(x - s * 0.12 + d * s * 0.2, y - s * 0.12, x + s * 0.12 + d * s * 0.2, y + s * 0.12, fill="#ffffffaa" if False else "#e8eef8", outline="")
                self.hits.append((x, y, max(s / 2, 4), it["gi"]))
            if self.show_boxes.get():
                for gi, g in enumerate(self.doc.groups):
                    for oi, _ln in enumerate(g["lines"]):
                        lo, hi = self.doc.cur.get("G%d/%d/MinPos" % (gi, oi)), self.doc.cur.get("G%d/%d/MaxPos" % (gi, oi))
                        if lo and hi:
                            a, b = vec_of(lo), vec_of(hi)
                            pts = [self.project([x, y, z]) for x in (a[0], b[0]) for y in (a[1], b[1]) for z in (a[2], b[2])]
                            pts = [p for p in pts if p]
                            if pts:
                                cv.create_rectangle(min(p[0] for p in pts) + ox, min(p[1] for p in pts) + oy, max(p[0] for p in pts) + ox, max(p[1] for p in pts) + oy,
                                                    outline=self.COLS[gi % len(self.COLS)], width=1)
            if self.show_labels.get():
                y0 = oy + 6
                for gi, g in enumerate(self.doc.groups):
                    if gi in labels:
                        cv.create_text(ox + 8, y0, anchor="nw", fill=self.COLS[gi % len(self.COLS)], font=("Segoe UI", 9, "bold" if gi == self.sel else "normal"),
                                       text="%s: %s" % (g["name"] or "group", ", ".join(labels[gi])))
                        y0 += 15
            self.info.configure(text="Sun %s   Camera %s → %s   (approximate view; click a ship to select its group)" %
                                (self.doc.cur.get("SunPos", "?"), self.doc.cur.get("CameraPos", "?"), self.doc.cur.get("LookAt", "?")))
        except Exception:
            log_exc("main menu draw")

    def select(self, gi):
        self.sel = gi
        self.draw()

    def click(self, e):
        best = None
        for x, y, r, gi in self.hits:
            dd = (e.x - x) ** 2 + (e.y - y) ** 2
            if dd <= r * r and (best is None or dd < best[0]):
                best = (dd, gi)
        if best:
            self.select(best[1])


def parse_globals_file(path):
    """{key: value} of every simple 'Key: value' line of a Globals.yaml (comments stripped)."""
    out = {}
    try:
        text = read_file(path)[0]
    except Exception:
        return out
    for m in GlobalsDoc.LINE.finditer(text):
        if m.group(4).strip():
            out.setdefault(m.group(2), m.group(4).strip())
    return out


def globals_sources(proj):
    """[(label, path)] of the Globals.yaml files the mod can be compared with: the base game's, then the other mods next to this one."""
    out, seen = [], set()
    mine = proj.globals_path()
    for b in getattr(proj, "base_roots", []):
        for cand in (Path(b) / "Content" / "Globals.yaml", Path(b) / "Globals.yaml", Path(b) / "Content" / "Globals" / "Globals.yaml"):
            if cand.is_file() and str(cand).lower() not in seen:
                seen.add(str(cand).lower())
                out.append(("Base game  (%s)" % Path(b).name, cand))
                break
    try:
        for sib in sorted(proj.root.parent.iterdir(), key=lambda x: x.name.lower()):
            f = sib / "Globals.yaml"
            if sib.is_dir() and sib.resolve() != proj.root.resolve() and f.is_file():
                out.append(("Mod: " + sib.name, f))
    except (OSError, ValueError):
        pass
    return out


class GameSettingsView(ttk.Frame):
    """General settings for the whole mod: every simple line of Globals.yaml with the game file's own comment, searchable and editable."""
    comments = RemnantSettingsView.comments
    section = RemnantSettingsView.section
    build_finder = RemnantSettingsView.build_finder
    fill_finder = RemnantSettingsView.fill_finder
    FIND_MAX = 400

    def __init__(self, master, app):
        super().__init__(master)
        self.app, self.proj, self._filled = app, app.proj, False
        self.sf = ScrollFrame(self, bg=PANEL2)
        self.sf.pack(fill="both", expand=True)

    def update_title(self):
        try:
            self.app.nb.tab(self, text="Globals.yaml")
        except Exception:
            pass

    def ensure(self):
        if not self._filled:
            self._filled = True
            self.build()

    def reload(self):
        if self._filled:
            self.build()

    def build(self):
        for w in self.sf.inner.winfo_children():
            w.destroy()
        tk.Label(self.sf.inner, text="Globals.yaml", bg=PANEL2, fg=ORANGE, font=("Segoe UI", 18, "bold"), anchor="w").pack(fill="x", padx=14, pady=(10, 0))
        tk.Label(self.sf.inner, bg=PANEL2, fg=DIM, anchor="w", justify="left", wraplength=1000,
                 text="The settings of the whole mod, from Globals.yaml (research pace, repair, construction, AI, the Remnants ...). Search by name or by what the file says "
                      "(level, fleet, attack, repair, cost ...), change a value and press Enter. Changes are saved into the mod's Globals.yaml with Save all (Ctrl+S).").pack(fill="x", padx=14)
        try:
            gd = self.proj.globals_doc()
        except Exception as e:
            tk.Label(self.sf.inner, text="Globals.yaml could not be read: %s" % e, bg=PANEL2, fg="#e07070").pack(padx=14, pady=10, anchor="w")
            return
        try:
            self.build_changes(gd)
        except Exception as e:
            log_exc()
            tk.Label(self.sf.inner, text="The base-game comparison failed: %s" % e, bg=PANEL2, fg="#e07070").pack(padx=14, anchor="w")
        self.build_finder(gd, self.comments())

    # ---- compare with the base game and the other mods
    def build_changes(self, gd):
        P = self.proj
        s = self.section("Game version and changes in the base game / other mods",
                         "Compares your mod's Globals.yaml with the base game's and the other mods' next to it, so you can see settings the game added, changed or removed.")
        v = read_versions(P.root, getattr(P, "log", None))
        tk.Label(s, bg=PANEL2, fg=FG, anchor="w", justify="left",
                 text="Your mod: %s     Game (from blackbox.log): %s     Branch: %s" % (v.get("mod") or "?", v.get("game") or "(run the game once so the log is written)", v.get("branch") or "?")
                 ).grid(row=0, column=0, columnspan=3, sticky="we", padx=8, pady=(4, 2))
        self.srcs = globals_sources(P)
        top = tk.Frame(s, bg=PANEL2)
        top.grid(row=1, column=0, columnspan=3, sticky="we", padx=8, pady=2)
        tk.Label(top, text="Compare with", bg=PANEL2, fg=DIM).pack(side="left")
        self.cmp_src = tk.StringVar(value=self.srcs[0][0] if self.srcs else "")
        cb = ttk.Combobox(top, textvariable=self.cmp_src, values=[x[0] for x in self.srcs], state="readonly", width=40)
        cb.pack(side="left", padx=6)
        ttk.Button(top, text="Check", command=self.run_changes).pack(side="left")
        self.cmp_only = tk.BooleanVar(value=False)
        ttk.Checkbutton(top, text="only changes since I last checked", variable=self.cmp_only, command=self.run_changes).pack(side="left", padx=10)
        self.cmp_note = tk.Label(s, bg=PANEL2, fg=DIM, anchor="w", justify="left", wraplength=1000)
        self.cmp_note.grid(row=2, column=0, columnspan=3, sticky="we", padx=8)
        self.cmp_rows = tk.Frame(s, bg=PANEL2)
        self.cmp_rows.grid(row=3, column=0, columnspan=3, sticky="we", padx=8, pady=(0, 8))
        self.cmp_rows.columnconfigure(3, weight=1)
        if not self.srcs:
            self.cmp_note.configure(text="No other Globals.yaml was found (no base game folder or other mods next to this one).")
        else:
            self.run_changes()

    def run_changes(self):
        P = self.proj
        for w in self.cmp_rows.winfo_children():
            w.destroy()
        src = next((x for x in self.srcs if x[0] == self.cmp_src.get()), None)
        if src is None:
            return
        label, path = src
        theirs = parse_globals_file(path)
        mine = dict(self.proj.globals_doc().cur)
        seen = P.settings.setdefault("globals_seen", {})
        if not hasattr(self, "_prev"):
            self._prev = {}
        if label not in self._prev:                      # what was seen the last time the editor was used (kept while this tab is open)
            self._prev[label] = seen.get(label)
        prev = self._prev[label]
        diff = []
        for k in sorted(set(theirs) | set(mine), key=str.lower):
            a, b = mine.get(k), theirs.get(k)
            if a == b:
                continue
            kind = "gone" if a is None else ("new" if b is None else "differs")
            fresh = prev is None or prev.get(k) != b
            if self.cmp_only.get() and prev is not None and not fresh:
                continue
            diff.append((k, a, b, kind))
        self.cmp_note.configure(text="%d difference(s) from %s.  %s" % (len(diff), label, "First check of this source - everything counts as new." if prev is None else
                                "'Only changes since I last checked' hides settings whose value in that file is the same as when the editor last looked."))
        for r, (k, a, b, kind) in enumerate(diff[:self.FIND_MAX]):
            tk.Label(self.cmp_rows, text=k, bg=PANEL2, fg=FG, anchor="w", width=34).grid(row=r, column=0, sticky="nw", padx=(0, 8), pady=2)
            tk.Label(self.cmp_rows, text="yours: %s" % ("-" if a is None else a), bg=PANEL2, fg=DIM, anchor="w", width=22).grid(row=r, column=1, sticky="nw")
            tk.Label(self.cmp_rows, text="theirs: %s" % ("-" if b is None else b), bg=PANEL2, fg=ORANGE, anchor="w", width=22).grid(row=r, column=2, sticky="nw")
            what = {"new": "only in your mod (the other file lacks it)", "gone": "NEW there - not in your Globals.yaml yet", "differs": "different value"}[kind]
            f = tk.Frame(self.cmp_rows, bg=PANEL2)
            f.grid(row=r, column=3, sticky="nw")
            tk.Label(f, text=what, bg=PANEL2, fg=DIM).pack(side="left")
            if kind == "differs":
                def take(k=k, b=b):
                    try:
                        P.set_global(k, b)
                        self.app.update_status()
                        self.build()
                    except ValueError as ex:
                        messagebox.showwarning("Globals.yaml", str(ex), parent=self)
                ttk.Button(f, text="Use theirs", width=11, command=take).pack(side="left", padx=8)
        if len(diff) > self.FIND_MAX:
            tk.Label(self.cmp_rows, text="... %d more (the list shows the first %d)" % (len(diff) - self.FIND_MAX, self.FIND_MAX), bg=PANEL2, fg=DIM).grid(columnspan=4, sticky="w")
        if seen.get(label) != theirs:
            seen[label] = dict(theirs)
            P.save_settings()


class RemnantEventsTab(ttk.Frame):
    """Main tab: the Remnants, in the same window format as the module / building editors: a header (picture, title, what it is, buttons) over a row of
    sub tabs. The list tabs open an item in its own editor on double-click."""
    PAGE_SETS = {"remnants": (("settings", "Settings"), ("Race", "Race"), ("Ships", "Ships"), ("stories", "Stories"), ("Problems", "Problems")),
                 "events": (("events", "All events"), ("chains", "Event chains"))}

    def __init__(self, master, app, kind="remnants"):
        super().__init__(master)
        self.app, self.proj, self.kind = app, app.proj, kind
        self.PAGES = self.PAGE_SETS[kind]
        head = tk.Frame(self, bg=BG)
        head.pack(fill="x", padx=10, pady=(8, 0))
        tk.Label(head, text="✦" if kind == "remnants" else "◇", bg=BG, fg=ORANGE, font=("Segoe UI Symbol", 34), width=2).pack(side="left", padx=(0, 10))
        mid = tk.Frame(head, bg=BG)
        mid.pack(side="left", fill="x", expand=True)
        tk.Label(mid, text="Remnants" if kind == "remnants" else "Events", bg=BG, fg=ORANGE, font=("Segoe UI", 20, "bold"), anchor="w").pack(fill="x")
        self.sub = tk.Label(mid, bg=BG, fg=DIM, anchor="w")
        self.sub.pack(fill="x")
        bar = tk.Frame(mid, bg=BG)
        bar.pack(fill="x", pady=(6, 4))
        for text, cmd, hint, sty in (("Rescan", self.reload, "Look again at the files (after you change events, designs or names).", None),
                                     ("＋ New multi-stage event…", self.wizard, "A chain of linked events and buildings for a new story.", None),
                                     ("Save all  (Ctrl+S)", app.save, "Write every change to the mod.", "Save.TButton")):
            if kind == "remnants" and text.startswith("＋"):
                continue
            b = ttk.Button(bar, text=text, command=cmd, **({"style": sty} if sty else {}))
            b.pack(side="left", padx=(0, 8))
            tip(b, hint)
        self.nb = ttk.Notebook(self)
        self.nb.pack(fill="both", expand=True, padx=0, pady=(4, 0))
        self.rem = self.rset = self.ev = self.chain = None
        if kind == "remnants":
            self.rset = RemnantSettingsView(self.nb, app, self)
        else:
            self.ev = EventsView(self.nb, app, self)
            self.chain = EventChainView(self.nb, app, self)
        self.page, self.groups = {}, []
        for key, title in self.PAGES:
            if key == "settings":
                w = self.rset
            elif key == "stories":
                w = RemnantStoriesView(self.nb, app, self)
                self.groups.append(w)
            elif key == "events":
                w = self.ev
            elif key == "chains":
                w = self.chain
            else:
                w = RemnantView(self.nb, app, self)
                w.group = key
                self.groups.append(w)
            self.page[key] = w
            self.nb.add(w, text="  %s  " % title)
        self.nb.bind("<<NotebookTabChanged>>", lambda _e: self.on_tab())
        self.refresh_sub()

    def refresh_sub(self):
        try:
            self.sub.configure(text=("The Remnant race, their ships, their story chains and the settings that control them" if self.kind == "remnants" else
                                     "Exploration events - what happens when you explore, and how events lead on to each other   ·   %d events (the base game's and this mod's)" % (
                                         len(self.proj.events) + len(self.proj.base_events))))
        except Exception:
            pass

    def on_tab(self):
        try:
            self.nb.nametowidget(self.nb.select()).ensure()
        except Exception:
            pass

    def ensure(self):
        self.on_tab()

    def pick(self, key):
        try:
            self.nb.select(self.page[key])
        except Exception:
            pass

    def open_event(self, doc):
        if self.kind == "remnants":                                 # events live on their own tab
            et = getattr(self.app, "evtab", None)
            if et is not None:
                et.open_event(doc)
            return
        try:
            self.app.nb.select(self)
        except Exception:
            pass
        self.pick("events")
        try:
            self.ev.select(doc)
        except Exception:
            log_exc("open event", sys.exc_info())

    def reload(self):
        for w in [self.ev, self.rset, self.chain] + self.groups:
            if w is None:
                continue
            try:
                w.reload()
            except Exception:
                pass
        self.refresh_sub()

    def wizard(self):
        w = ChainWizard(self, self.proj, list(self.proj.events) + list(self.proj.base_events))
        w.show()
        self.wait_window(w)
        if not w.result:
            return
        try:
            made = make_chain(self.proj, w.result)
        except ValueError as e:
            messagebox.showwarning("New multi-stage event", str(e))
            return
        self.app.update_status()
        try:
            self.app.refresh()
        except Exception:
            pass
        self.reload()
        self.pick("chains")
        self.chain.mode.set("All events")
        self.chain.refresh(select="e:" + made[0].path.stem)
        self.app.say("Made %d linked events and buildings for '%s'. Check them on the Events page, then Save (Ctrl+S)." % (len(made), w.result["name"]))

    def update_title(self):
        try:
            self.app.nb.tab(self, text="Remnants" if self.kind == "remnants" else "Events (%d)" % (len(self.proj.events) + len(self.proj.base_events)))
        except Exception:
            pass


class TraitDialog(_Dialog):
    """New racial trait: name, category, cost, description, optionally a copy of an existing trait. result = dict or None."""
    CATS = ("Physical", "Sociological", "HistoryAndTradition", "Environment")

    def __init__(self, master, names, cats, copy_of=""):
        super().__init__(master, "New racial trait")
        self.names = list(names)
        self.v_name, self.v_cat, self.v_cost, self.v_copy = tk.StringVar(), tk.StringVar(value=(cats or self.CATS)[0]), tk.StringVar(value="1"), tk.StringVar(value=copy_of or "(blank trait)")
        self.label(0, "Name", "The trait's name. It is also the key races use in their trait lists, so keep it unique. Not a file.")
        ttk.Entry(self, textvariable=self.v_name, width=34).grid(row=0, column=1, sticky="we", padx=8, pady=4)
        self.label(1, "Category", "Which group the trait is listed under in the game's race screen.")
        ttk.Combobox(self, textvariable=self.v_cat, values=list(cats or self.CATS), width=32).grid(row=1, column=1, sticky="we", padx=8, pady=4)
        self.label(2, "Cost (points)", "Points the trait costs the player. A negative number is a drawback that gives points back.")
        ttk.Entry(self, textvariable=self.v_cost, width=10).grid(row=2, column=1, sticky="w", padx=8, pady=4)
        self.label(3, "Start from", "Copy all the effects (modifier tags and Excludes) of an existing trait, or begin with none.")
        ttk.Combobox(self, textvariable=self.v_copy, values=["(blank trait)"] + self.names, width=32, state="readonly").grid(row=3, column=1, sticky="we", padx=8, pady=4)
        self.label(4, "Description", "The text players read for this trait. Stored in GameText.yaml (the editor adds the text entries for you).")
        self.desc = tk.Text(self, width=40, height=5, wrap="word")
        self.desc.grid(row=4, column=1, sticky="we", padx=8, pady=4)
        self.msg = tk.Label(self, text="", bg=PANEL, fg="#ff8080", anchor="w", wraplength=380, justify="left")
        self.msg.grid(row=5, column=0, columnspan=2, sticky="we", padx=14)
        bf = tk.Frame(self, bg=PANEL)
        bf.grid(row=6, column=0, columnspan=2, pady=10)
        ttk.Button(bf, text="Create", command=self.ok).pack(side="left", padx=6)
        ttk.Button(bf, text="Cancel", command=self.destroy).pack(side="left", padx=6)
        self.columnconfigure(1, weight=1)

    def ok(self):
        nm = self.v_name.get().strip()
        if not nm:
            self.msg["text"] = "Give the trait a name."
            return
        if nm.lower() in {n.lower() for n in self.names}:
            self.msg["text"] = "A trait called '%s' already exists." % nm
            return
        try:
            cost = float(self.v_cost.get().strip())
        except ValueError:
            self.msg["text"] = "The cost must be a number."
            return
        cp = self.v_copy.get()
        self.result = {"name": nm, "cat": self.v_cat.get().strip() or "Physical", "cost": ("%d" % cost) if cost == int(cost) else str(cost),
                       "copy": "" if cp == "(blank trait)" else cp, "desc": self.desc.get("1.0", "end").strip()}
        self.destroy()


class TraitsTab(ttk.Frame):
    """The racial traits (RacialTraits.xml): every trait with its cost, category, texts, what it excludes and its effect tags. Edit, copy, create, delete."""
    CATS = TraitDialog.CATS

    def __init__(self, master, app):
        super().__init__(master)
        self.app, self.proj = app, app.proj
        self.sel, self._build_id = None, 0
        self.vcat, self.vfind = tk.StringVar(value="All"), tk.StringVar()
        top = tk.Frame(self, bg=BG)
        top.pack(fill="x", padx=8, pady=6)
        self.banner = tk.Label(top, bg=BG, fg=DIM, anchor="w", justify="left", wraplength=900)
        self.banner.pack(side="left", fill="x", expand=True)
        self.vpts = tk.StringVar()
        pf = tk.Frame(top, bg=BG)
        pf.pack(side="right")
        tk.Label(pf, text="Starting trait points:", bg=BG, fg=FG).pack(side="left")
        pe = ttk.Entry(pf, textvariable=self.vpts, width=6)
        pe.pack(side="left", padx=4)
        pe.bind("<Return>", lambda _e: self.set_points())
        pe.bind("<FocusOut>", lambda _e: self.set_points())
        tip(pe, "TraitPoints in Globals.yaml: the points every player starts with to spend on racial traits. Whole number. Changing it edits that one value (a copy of the file goes into the mod if it is only in the base game).")
        pw = tk.Frame(self, bg=BG)
        pw.pack(fill="both", expand=True, padx=8, pady=4)
        left = tk.Frame(pw, bg=BG, width=600)
        left.pack(side="left", fill="y")
        left.pack_propagate(False)
        # the list itself is the in-game trait screen; this table only keeps the traits in order behind the scenes (never shown)
        self.tv = ttk.Treeview(pw, columns=("cat", "cost", "used"), show="tree headings", selectmode="browse")
        bar = tk.Frame(left, bg=BG)
        bar.pack(fill="x", pady=(0, 4))
        tk.Label(bar, text="Find", bg=BG, fg=DIM).pack(side="left")
        e = ttk.Entry(bar, textvariable=self.vfind, width=14)
        e.pack(side="left", padx=(4, 10))
        self.vfind.trace_add("write", lambda *_a: self.draw_game())
        tip(e, "Find a trait by name (looks in every category).")
        for txt, fn, hint in (("New", self.new_trait, "Create a new racial trait (also adds its GameText entries)."),
                              ("Copy", self.copy_trait, "Create a new trait that starts as a copy of the selected one."),
                              ("Delete", self.delete_trait, "Remove the selected trait from RacialTraits.xml.")):
            b = ttk.Button(bar, text=txt, command=fn, width=7)
            b.pack(side="left", padx=2)
            tip(b, hint)
        gv = tk.Frame(left, bg=PANEL)
        gv.pack(fill="both", expand=True)
        self.gcat, self.grace = tk.StringVar(value=self.CATS[0]), tk.StringVar(value="(no race)")
        self.gtabs = tk.Frame(gv, bg=PANEL)
        self.gtabs.pack(fill="x", padx=8, pady=(6, 2))
        gtop = tk.Frame(gv, bg=PANEL)
        gtop.pack(fill="x", padx=8, pady=(0, 6))
        tk.Label(gtop, text="Race:", bg=PANEL, fg=DIM).pack(side="left")
        self.grace_cb = ttk.Combobox(gtop, textvariable=self.grace, values=["(no race)"], width=22, state="readonly")
        self.grace_cb.pack(side="left", padx=4)
        self.grace_cb.bind("<<ComboboxSelected>>", lambda _e: self.draw_game())
        tip(self.grace_cb, "Show the traits of one race as chosen (green = taken, red = drawback taken) with the points left to spend, like the game's race screen.")
        self.gpts = tk.Label(gtop, text="", bg=PANEL, fg=FG)
        self.gpts.pack(side="right")
        self.gsf = ScrollFrame(gv, bg="#0b0d12")
        self.gsf.pack(fill="both", expand=True, padx=6, pady=(0, 6))
        self.sf = ScrollFrame(pw, bg=PANEL)
        self.sf.pack(side="left", fill="both", expand=True, padx=(8, 0))
        self._ready = False

    # ---- data
    def doc(self):
        return self.proj.traits_doc()

    def items(self):
        d = self.doc()
        return d.lists["traits"] if d is not None else []

    def cats(self):
        found = []
        for it in self.items():
            c = trait_get(it, "Category")
            if c and c not in found and c not in self.CATS:
                found.append(c)
        return list(self.CATS) + found

    def ensure(self):
        if not self._ready:
            self._ready = True
        self.reload()

    def reload(self):
        keep = self.sel
        self.fill()
        n = len(self.items())
        if keep is not None and keep < n:
            self.select(keep)
        else:
            self.sel = None
            self.show()
        self.update_title()
        self.draw_game()

    def update_title(self):
        try:
            self.app.nb.tab(self, text="Racial traits (%d)" % len(self.items()))
        except Exception:
            pass

    def banner_text(self):
        lim = self.proj.trait_limit()
        d = self.doc()
        t = ("Racial traits from %s. " % (d.rel.as_posix() if d is not None else "(no RacialTraits.xml found - New creates one)"))
        t += ("Players start with %s trait points (%s in %s). " % (fmtv(lim[1]), lim[0], lim[2])) if lim else "No trait points limit found in Globals.yaml. "
        return t + "A positive cost spends points; a negative cost (a drawback) gives points back. Names are what races list in their trait sets."

    def users_count(self, name):
        return len(self.proj.trait_users(name))

    def set_points(self):
        v = self.vpts.get().strip()
        lim = self.proj.trait_limit()
        if not v or (lim and v == fmtv(lim[1])):
            return
        try:
            if not re.fullmatch(r"-?\d+(\.\d+)?", v):
                raise ValueError("The points limit must be a number.")
            self.proj.set_trait_limit(float(v))
        except ValueError as e:
            messagebox.showwarning("Not applied", str(e))
            self.vpts.set(fmtv(lim[1]) if lim else "")
            return
        self.banner["text"] = self.banner_text()
        self.app.update_status()
        self.draw_game()
        self.app.say("Trait points limit set to %s. Save (Ctrl+S) to write Globals.yaml." % v)

    def fill(self):
        self.banner["text"] = self.banner_text()
        lim = self.proj.trait_limit()
        self.vpts.set(fmtv(lim[1]) if lim else "")
        for i in self.tv.get_children():
            self.tv.delete(i)
        cat, words = self.vcat.get(), self.vfind.get().lower().split()
        for i, it in enumerate(self.items()):
            nm = trait_get(it, "TraitName")
            if cat not in ("", "All") and trait_get(it, "Category") != cat:
                continue
            if words and not all(w in nm.lower() for w in words):
                continue
            self.tv.insert("", "end", iid=str(i), text=nm, values=(trait_get(it, "Category"), trait_get(it, "Cost"), self.users_count(nm)))

    def select(self, i):
        self.sel = i
        try:
            if self.tv.exists(str(i)):
                self.tv.selection_set(str(i))
        except Exception:
            pass
        try:
            c = trait_get(self.items()[i], "Category")
            if c and c != self.gcat.get() and not self.vfind.get().strip():
                self.gcat.set(c)
            self.draw_game()
        except Exception:
            pass
        self.show()

    def on_select(self):
        s = self.tv.selection()
        if s:
            self.sel = int(s[0])
            self.show()

    def draw_game(self):
        """The trait list laid out like the game's race screen: name ..... cost, the description under it, drawbacks in red."""
        for w in self.gtabs.winfo_children():
            try:
                w.destroy()
            except Exception:
                pass
        for i, c in enumerate(self.cats()):                 # a grid, six to a row, so long category names are never cut off
            tk.Button(self.gtabs, text=c.upper().replace("HISTORYANDTRADITION", "HISTORY AND TRADITION"), relief="flat", padx=6,
                      bg=SEL if c == self.gcat.get() else PANEL2, fg=FG, command=lambda c=c: (self.gcat.set(c), self.draw_game())).grid(
                          row=i // 6, column=i % 6, padx=1, pady=1, sticky="ew")
            self.gtabs.grid_columnconfigure(i % 6, weight=1, uniform="cat")
        races = sorted(self.proj.races + self.proj.base_races, key=lambda r: r.name().lower())
        self.grace_cb["values"] = ["(no race)"] + [r.name() for r in races if r.lists.get("traits0")]
        race = next((r for r in races if r.name() == self.grace.get()), None)
        taken = {x.strip().lower() for x in race.lists.get("traits0", ())} if race is not None else set()
        costs = {trait_get(i, "TraitName").lower(): trait_get(i, "Cost") for i in self.items()}
        lim = self.proj.trait_limit()
        if race is not None and lim:
            spent = 0.0
            for n in taken:
                try:
                    spent += float(costs.get(n, 0) or 0)
                except ValueError:
                    pass
            self.gpts["text"] = "Points to spend: %s   (limit %s, traits cost %s)" % (fmtv(lim[1] - spent), fmtv(lim[1]), fmtv(spent))
        else:
            self.gpts["text"] = ""
        key = (self.gcat.get(), self.vfind.get())
        try:
            y0 = self.gsf.canvas.yview()[0] if key == getattr(self, "_gkey", None) else 0.0
        except Exception:
            y0 = 0.0
        self._gkey = key
        self.gsf.clear()
        body = self.gsf.inner
        words = self.vfind.get().lower().split()
        for idx, it in enumerate(self.items()):
            nm = trait_get(it, "TraitName")
            if words:
                if not all(w in nm.lower() for w in words):
                    continue
            elif trait_get(it, "Category") != self.gcat.get():
                continue
            try:
                cost = float(trait_get(it, "Cost") or 0)
            except ValueError:
                cost = 0.0
            on = nm.lower() in taken
            col = ("#7bd88f" if cost >= 0 else "#ff6b6b") if on else ("#ff8a8a" if cost < 0 else "#a9a9b3")
            bgc = "#1c2a4a" if idx == self.sel else "#0b0d12"
            fr = tk.Frame(body, bg=bgc, cursor="hand2")
            fr.pack(fill="x", padx=10, pady=(8, 0))
            head = tk.Frame(fr, bg=bgc)
            head.pack(fill="x")
            tk.Label(head, text=nm, bg=bgc, fg=col, font=("Segoe UI", 11, "bold")).pack(side="left")
            tk.Label(head, text=fmtv(cost), bg=bgc, fg=col, font=("Segoe UI", 11, "bold")).pack(side="right")
            tk.Frame(head, bg="#55555f", height=1).pack(side="left", fill="x", expand=True, padx=8, pady=(10, 0))
            did = trait_get(it, "Description")
            e_ = self.proj.text_display_by_id(int(did)) if did.isdigit() else None
            desc = (e_.get("ENG") if e_ is not None else "") or "(no description text)"
            tk.Label(fr, text=desc, bg=bgc, fg=col, font=("Segoe UI", 8), anchor="w", justify="left", wraplength=500).pack(fill="x")
            for w in [fr] + list(fr.winfo_children()):
                try:
                    w.bind("<Button-1>", lambda _e, i=idx: self.pick_from_game(i))
                except Exception:
                    pass
        if y0:
            try:
                self.after_idle(lambda: self._restore_scroll(y0))
            except Exception:
                pass

    def _restore_scroll(self, y0):
        try:
            self.gsf.canvas.yview_moveto(y0)
        except Exception:
            pass

    def pick_from_game(self, i):
        self.select(i)

    def after_edit(self, refill=False):
        self.proj._trait_costs = None
        if refill:
            self.fill()
            if self.sel is not None and self.tv.exists(str(self.sel)):
                self.tv.selection_set(str(self.sel))
        elif self.sel is not None and self.tv.exists(str(self.sel)):
            it = self.items()[self.sel]
            nm = trait_get(it, "TraitName")
            self.tv.item(str(self.sel), text=nm, values=(trait_get(it, "Category"), trait_get(it, "Cost"), self.users_count(nm)))
        self.app.update_status()
        try:
            self.banner["text"] = self.banner_text()
            self.draw_game()
        except Exception:
            pass

    def update_item(self, fn):
        L = self.items()
        if self.sel is None or self.sel >= len(L):
            return False
        new = fn(L[self.sel])
        if new == L[self.sel]:
            return False
        L[self.sel] = new
        self.after_edit()
        return True

    # ---- the editor on the right
    def show(self):
        self.sf.clear()
        body = self.sf.inner
        L = self.items()
        if self.sel is None or self.sel >= len(L):
            tk.Label(body, bg=PANEL, fg=DIM, justify="left", anchor="w", wraplength=520,
                     text="Pick a trait on the left to edit it, or press New to create one." if self.doc() is not None or True else "").pack(fill="x", padx=14, pady=14)
            return
        it = L[self.sel]
        nm = trait_get(it, "TraitName")
        self._idvars, self._nolabels = {}, {}
        tk.Label(body, text=nm, bg=PANEL, fg=ORANGE, font=("Segoe UI", 13, "bold"), anchor="w").pack(fill="x", padx=14, pady=(10, 4))
        grid = tk.Frame(body, bg=PANEL)
        grid.pack(fill="x", padx=14)
        grid.columnconfigure(1, weight=1)
        row = [0]

        def lab(text, hint):
            lb = tk.Label(grid, text=text, bg=PANEL, fg=FG, anchor="w")
            lb.grid(row=row[0], column=0, sticky="nw", padx=(0, 8), pady=3)
            tip(lb, hint)
            return lb

        def entry(tag, text, hint, width=34, check=None):
            lab(text, hint)
            v = tk.StringVar(value=trait_get(it, tag))
            e = ttk.Entry(grid, textvariable=v, width=width)
            e.grid(row=row[0], column=1, sticky="w", pady=3)
            tip(e, hint)

            def go(_e=None):
                val = v.get().strip()
                if check:
                    err = check(val)
                    if err:
                        messagebox.showwarning("Not applied", err)
                        v.set(trait_get(it, tag))
                        return
                self.update_item(lambda t: trait_set(t, tag, val))
            e.bind("<Return>", go)
            e.bind("<FocusOut>", go)
            row[0] += 1
            return v

        # name (rename also updates races and Excludes)
        lab("Name", "TraitName: the key races use in their trait sets and other traits use in Excludes. Not a file. Renaming updates those too.")
        vn = tk.StringVar(value=nm)
        en = ttk.Entry(grid, textvariable=vn, width=34)
        en.grid(row=row[0], column=1, sticky="w", pady=3)
        tip(en, "TraitName. Renaming changes it in every race that uses it and in other traits' Excludes.")
        en.bind("<Return>", lambda _e: self.rename(vn.get()))
        en.bind("<FocusOut>", lambda _e: self.rename(vn.get()))
        row[0] += 1
        lab("Category", "Category: the group the trait is listed under on the game's race screen.")
        vc = tk.StringVar(value=trait_get(it, "Category"))
        cb = ttk.Combobox(grid, textvariable=vc, values=self.cats(), width=32)
        cb.grid(row=row[0], column=1, sticky="w", pady=3)
        cb.bind("<<ComboboxSelected>>", lambda _e: self._set_cat(vc.get()))
        cb.bind("<Return>", lambda _e: self._set_cat(vc.get()))
        cb.bind("<FocusOut>", lambda _e: self._set_cat(vc.get()))
        row[0] += 1

        def chk_num(v):
            try:
                float(v)
            except ValueError:
                return "The cost must be a number."
            return ""
        entry("Cost", "Cost (points)", "Cost: points the trait costs. Negative = a drawback that gives points back. Number, not a file.", 10, chk_num)

        proj = self.proj
        for tag, title, multi in (("TraitIndex", "Name text", False), ("Description", "Description text", True)):
            tid = trait_get(it, tag)
            lab(title, "%s is a text id in GameText.yaml (mod or base game). Editing the text below changes that entry; if it comes from the base game a new entry is made for the mod." % tag)
            f = tk.Frame(grid, bg=PANEL)
            f.grid(row=row[0], column=1, sticky="we", pady=3)
            v = tk.StringVar(value=tid)
            ide = ttk.Entry(f, textvariable=v, width=8)
            ide.pack(side="left")
            tip(ide, "%s: the text id (a number in GameText.yaml)." % tag)

            def go_id(_e=None, tag=tag, v=v):
                val = v.get().strip()
                if not val.isdigit():
                    messagebox.showwarning("Not applied", "Text ids are whole numbers.")
                    v.set(trait_get(self.items()[self.sel], tag))
                    return
                if self.update_item(lambda t: trait_set(t, tag, val)):
                    self.show()
            ide.bind("<Return>", go_id)
            ide.bind("<FocusOut>", go_id)
            e_ = proj.text_display_by_id(int(tid)) if tid.isdigit() else None
            cur = (e_.get("ENG") if e_ is not None else "") or ""
            self._idvars[tag] = v
            if not tid.isdigit() or e_ is None:
                nl = tk.Label(f, text="  (no text found for this id)", bg=PANEL, fg=DIM)
                nl.pack(side="left")
                self._nolabels[tag] = nl
            else:
                self._nolabels.pop(tag, None)
            if multi:
                gb = ttk.Button(f, text="Write from effects", command=self.gen_desc)
                gb.pack(side="left", padx=8)
                tip(gb, "Writes a description from the effect tags below (for example 'Smart races gain +20% research.'). It replaces the text; you can edit it afterwards.")
            row[0] += 1
            lab("", "")
            if multi:
                tx = tk.Text(grid, width=52, height=5, wrap="word", bg=PANEL2, fg=FG, insertbackground=FG, relief="flat")
                tx.insert("1.0", cur)
                tx.grid(row=row[0], column=1, sticky="we", pady=3)
                tx.bind("<FocusOut>", lambda _e, tag=tag, tx=tx, cur=cur: tx.winfo_exists() and tx.get("1.0", "end").strip() != cur.strip()
                        and self.set_text(tag, tx.get("1.0", "end").strip()))      # only when the user really changed it
                tip(tx, "The text players read (ENG). Saved in GameText.yaml.")
                self.desc_tx = tx
            else:
                vt = tk.StringVar(value=cur)
                te = ttk.Entry(grid, textvariable=vt, width=52)
                te.grid(row=row[0], column=1, sticky="we", pady=3)
                te.bind("<Return>", lambda _e, tag=tag, vt=vt: self.set_text(tag, vt.get().strip()))
                te.bind("<FocusOut>", lambda _e, tag=tag, vt=vt, cur=cur, te=te: te.winfo_exists() and vt.get().strip() != cur.strip()
                        and self.set_text(tag, vt.get().strip()))
                tip(te, "The trait's name as players see it (ENG). Saved in GameText.yaml.")
            row[0] += 1

        # excludes
        sec = tk.Frame(body, bg=PANEL2)
        sec.pack(fill="x", padx=14, pady=(10, 4))
        tk.Label(sec, text="Excludes (cannot be taken together with)", bg=PANEL2, fg=PEACH, anchor="w", font=("Segoe UI", 9, "bold")).pack(fill="x", padx=6, pady=(4, 0))
        ex = list(trait_get(it, "Excludes", ()))
        lb = tk.Listbox(sec, height=max(2, min(8, len(ex))), bg=PANEL, fg=FG, selectmode="extended", exportselection=False)
        for x in ex:
            lb.insert("end", x)
        lb.pack(fill="x", padx=6, pady=4)
        bf = tk.Frame(sec, bg=PANEL2)
        bf.pack(fill="x", padx=6, pady=(0, 6))
        ttk.Button(bf, text="Add…", command=self.add_exclude).pack(side="left", padx=2)
        ttk.Button(bf, text="Remove selected", command=lambda: self.remove_excludes([lb.get(i) for i in lb.curselection()])).pack(side="left", padx=2)
        ttk.Button(bf, text="Also add the reverse", command=self.mirror_excludes).pack(side="left", padx=2)
        tip(bf, "Add and Remove change this trait. 'Also add the reverse' makes every trait listed here also exclude this one.")

        # modifiers
        mods = [(t, v) for t, v in it if t not in TRAIT_CORE]
        sec2 = tk.Frame(body, bg=PANEL2)
        sec2.pack(fill="x", padx=14, pady=(8, 4))
        tk.Label(sec2, text="Effects (modifier tags)", bg=PANEL2, fg=PEACH, anchor="w", font=("Segoe UI", 9, "bold")).pack(fill="x", padx=6, pady=(4, 0))
        for t, v in mods:
            r = tk.Frame(sec2, bg=PANEL2)
            r.pack(fill="x", padx=6, pady=1)
            tk.Label(r, text=t, bg=PANEL2, fg=FG, width=30, anchor="w").pack(side="left")
            sv = tk.StringVar(value=v)
            ee = ttk.Entry(r, textvariable=sv, width=14)
            ee.pack(side="left")
            tip(ee, "Value of <%s>. A number (for example 0.25 = +25%%), or text such as an environment name." % t)
            pl = tk.Label(r, text=trait_effect_text(t, v), bg=PANEL2, fg=PEACH, anchor="w")
            pl.pack(side="left", padx=(6, 0))
            sv.trace_add("write", lambda *_a, t=t, sv=sv, pl=pl: pl.config(text=trait_effect_text(t, sv.get())))
            ee.bind("<Return>", lambda _e, t=t, sv=sv: self.update_item(lambda it_: trait_set(it_, t, sv.get().strip())))
            ee.bind("<FocusOut>", lambda _e, t=t, sv=sv: self.update_item(lambda it_: trait_set(it_, t, sv.get().strip())))
            b = ttk.Button(r, text="✕", width=3, command=lambda t=t: self.drop_tag(t))
            b.pack(side="left", padx=4)
            tip(b, "Remove <%s> from this trait." % t)
        if not mods:
            tk.Label(sec2, text="No effect tags on this trait.", bg=PANEL2, fg=DIM, anchor="w").pack(fill="x", padx=6)
        af = tk.Frame(sec2, bg=PANEL2)
        af.pack(fill="x", padx=6, pady=6)
        known = self.known_tags()
        self.fx_tree(sec2, [t for t, _v in mods])
        self.vtag, self.vval = tk.StringVar(), tk.StringVar(value="1")
        ttk.Combobox(af, textvariable=self.vtag, values=known, width=30).pack(side="left")
        ttk.Entry(af, textvariable=self.vval, width=10).pack(side="left", padx=4)
        b = ttk.Button(af, text="Add effect", command=self.add_tag)
        b.pack(side="left")
        tip(b, "Pick an effect tag another trait already uses (or type its exact name) and give it a value.")

        users = self.proj.trait_users(nm)
        tk.Label(body, bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=520,
                 text="Used by %d race(s): %s" % (len(users), ", ".join(r.name() for r in users) or "none")).pack(fill="x", padx=14, pady=(8, 14))

    def known_tags(self):
        out = set(TRAIT_EFFECTS)
        for it in self.items():
            out.update(t for t, _v in it if t not in TRAIT_CORE)
        return sorted(out, key=str.lower)

    def fx_tree(self, parent, have):
        """The effects a trait can carry: tag, a typical value from the file, how many traits use it, and what it does. Double-click adds one."""
        use, ex = {}, {}
        for it in self.items():
            for t, v in it:
                if t not in TRAIT_CORE:
                    use[t] = use.get(t, 0) + 1
                    ex.setdefault(t, v)
        tk.Label(parent, text="All effects you can add (double-click one to add it with its typical value; meanings are inferred from the tag names and the game's trait texts):",
                 bg=PANEL2, fg=DIM, anchor="w", justify="left", wraplength=500).pack(fill="x", padx=6, pady=(6, 0))
        tv = ttk.Treeview(parent, columns=("ex", "n", "what"), show="tree headings", height=9, selectmode="browse")
        tv.heading("#0", text="Effect tag")
        tv.heading("ex", text="Typical")
        tv.heading("n", text="Traits")
        tv.heading("what", text="What it does")
        tv.column("#0", width=190)
        tv.column("ex", width=60)
        tv.column("n", width=45, anchor="e")
        tv.column("what", width=380)
        for t in sorted(set(TRAIT_EFFECTS) | set(use), key=str.lower):
            tv.insert("", "end", iid=t, text=t, values=(ex.get(t, ""), use.get(t, 0), TRAIT_EFFECTS.get(t, "(used in the file; meaning unknown)")),
                      tags=("have",) if t in have else ())
        try:
            tv.tag_configure("have", foreground="#7bd88f")
        except Exception:
            pass
        tv.pack(fill="x", padx=6, pady=4)

        def add(_e=None):
            s = tv.selection()
            if s and s[0] not in have:
                self.vtag.set(s[0])
                self.vval.set(ex.get(s[0], "1"))
                self.add_tag()
        tv.bind("<Double-1>", add)
        tv.bind("<<TreeviewSelect>>", lambda _e: (self.vtag.set(tv.selection()[0]), self.vval.set(ex.get(tv.selection()[0], "1"))) if tv.selection() else None)

    # ---- edits
    def rename(self, new):
        new = new.strip()
        L = self.items()
        if self.sel is None or self.sel >= len(L):
            return
        old = trait_get(L[self.sel], "TraitName")
        if not new or new == old:
            return
        if any(trait_get(x, "TraitName").lower() == new.lower() for i, x in enumerate(L) if i != self.sel):
            messagebox.showwarning("Not applied", "Another trait is already called '%s'." % new)
            return
        users = self.proj.trait_users(old)
        if users and not messagebox.askyesno("Rename trait", "%d race(s) use '%s' (%s).\n\nRename it there too?" % (len(users), old, ", ".join(r.name() for r in users[:6]))):
            return
        L[self.sel] = trait_set(L[self.sel], "TraitName", new)
        self.proj.rename_trait(old, new)
        self.after_edit(refill=True)
        self.show()
        self.app.say("Renamed '%s' to '%s'." % (old, new))

    def _set_cat(self, v):
        v = v.strip()
        if v:
            self.update_item(lambda t: trait_set(t, "Category", v))

    def fresh_text_id(self):
        """A text id that is free in GameText AND not already promised to a trait (a new trait gets ids before their text exists)."""
        used = set()
        for it in self.items():
            for tg in ("TraitIndex", "Description"):
                v = trait_get(it, tg)
                if str(v).isdigit():
                    used.add(int(v))
        nid = self.proj.next_text_id()
        while nid in used:
            nid += 1
        return nid

    def gen_desc(self):
        try:
            L = self.items()
            if self.sel is None or self.sel >= len(L):
                messagebox.showinfo("Write from effects", "Pick a trait first.")
                return
            it = L[self.sel]
            text = trait_describe(trait_get(it, "TraitName"), it)
            if not self.proj.text:
                messagebox.showwarning("Write from effects", "This mod has no GameText.yaml to put the text in.")
                return
            tid = trait_get(it, "Description")
            e = self.proj.text.by_id.get(int(tid)) if tid.isdigit() else None
            if e is not None and not e.external:
                e.set("ENG", text)                                   # the entry exists: change it
                self.after_edit()
            else:                                                    # no entry (or a base-game one): make the mod's own
                nid = self.fresh_text_id()
                self.proj.text.add_entry("BB_Trait_%s_Desc" % trait_get(it, "TraitName"), nid, text)
                L[self.sel] = trait_set(it, "Description", str(nid))
                self.after_edit()
            self.show()
            self.app.update_status()
            self.app.say("Description written from the effects. Press Save (Ctrl+S) to keep it.")
            did = trait_get(self.items()[self.sel], "Description")
            e2 = self.proj.text_display_by_id(int(did)) if did.isdigit() else None
            if e2 is None or e2.get("ENG") != text:                   # only speak up when something is wrong
                messagebox.showerror("Write from effects", "The description was written but could not be read back.\n\nText id %s, entry found = %s, entries in GameText = %d.\nPlease send me this message."
                                     % (did, e2 is not None, len(self.proj.text.entries)))
        except Exception as ex:
            log_exc("trait description")
            messagebox.showerror("Write from effects", "That did not work:\n%s: %s" % (type(ex).__name__, ex))

    def set_text(self, tag, text):
        L = self.items()
        if self.sel is None or self.sel >= len(L):
            return
        it = L[self.sel]
        tid = trait_get(it, tag)
        P_ = self.proj
        if not P_.text:
            return
        e = P_.text.by_id.get(int(tid)) if tid.isdigit() else None
        old = (P_.text_display_by_id(int(tid)).get("ENG") if tid.isdigit() and P_.text_display_by_id(int(tid)) is not None else "") or ""
        if text == old.strip():
            return
        if e is not None and not e.external:
            e.set("ENG", text)
            self.after_edit()                                        # the list on the left shows the description too
        else:
            nid = self.fresh_text_id()
            P_.text.add_entry("BB_Trait_%s_%s" % (trait_get(it, "TraitName"), "Name" if tag == "TraitIndex" else "Desc"), nid, text)
            L[self.sel] = trait_set(it, tag, str(nid))
            self.after_edit()
            try:                                                     # update the id box in place - a rebuild would steal the focus
                self._idvars[tag].set(str(nid))
                self._nolabels.pop(tag).destroy()
            except Exception:
                pass
        self.app.update_status()

    def drop_tag(self, t):
        if self.update_item(lambda it: trait_drop(it, t)):
            self.show()

    def add_tag(self):
        t, v = self.vtag.get().strip(), self.vval.get().strip()
        if not re.fullmatch(r"[A-Za-z_]\w*", t) or t in TRAIT_CORE:
            messagebox.showwarning("Not applied", "Type or pick the exact name of an effect tag (letters and digits).")
            return
        if self.update_item(lambda it: trait_set(it, t, v)):
            self.show()

    def add_exclude(self):
        cur = trait_get(self.items()[self.sel], "TraitName")
        have = set(trait_get(self.items()[self.sel], "Excludes", ()))
        choices = [n for n in self.proj.defined_traits() if n != cur and n not in have]
        if not choices:
            messagebox.showinfo("Excludes", "There is no other trait to add.")
            return
        pick = ask_choice(self, "Excludes", "Choose a trait that cannot be taken together with '%s':" % cur, choices)
        if pick:
            if self.update_item(lambda it: trait_set(it, "Excludes", tuple(trait_get(it, "Excludes", ())) + (pick,))):
                self.show()

    def remove_excludes(self, names):
        if names and self.update_item(lambda it: trait_set(it, "Excludes", tuple(x for x in trait_get(it, "Excludes", ()) if x not in names))):
            self.show()

    def mirror_excludes(self):
        L = self.items()
        me = trait_get(L[self.sel], "TraitName")
        n = 0
        for x in trait_get(L[self.sel], "Excludes", ()):
            for i, it in enumerate(L):
                if trait_get(it, "TraitName") == x and me not in trait_get(it, "Excludes", ()):
                    L[i] = trait_set(it, "Excludes", tuple(trait_get(it, "Excludes", ())) + (me,))
                    n += 1
        self.after_edit(refill=True)
        self.app.say("Added '%s' to the Excludes of %d trait(s)." % (me, n))

    # ---- list actions
    def new_trait(self, copy_of=""):
        d = self.doc()
        names = self.proj.defined_traits()
        dlg = TraitDialog(self, names, self.cats(), copy_of)
        dlg.show()
        self.wait_window(dlg)
        r = dlg.result
        if not r:
            return None
        return self.create(r)

    def create(self, r):
        P_ = self.proj
        d = P_.traits_doc(create=True)
        base = next((i for i in d.lists["traits"] if trait_get(i, "TraitName") == r["copy"]), None) if r["copy"] else None
        ids = {"TraitIndex": trait_get(base, "TraitIndex", "0") if base else "0", "Description": trait_get(base, "Description", "0") if base else "0"}
        if P_.text:
            for tag, txt, suf in (("TraitIndex", r["name"], "Name"), ("Description", r["desc"], "Desc")):
                nid = P_.next_text_id()
                P_.text.add_entry("BB_Trait_%s_%s" % (r["name"], suf), nid, txt)
                ids[tag] = str(nid)
        core = (("TraitName", r["name"]), ("TraitIndex", ids["TraitIndex"]), ("Category", r["cat"]), ("Cost", r["cost"]), ("Description", ids["Description"]))
        extra = tuple((t, v) for t, v in base if t not in TRAIT_CORE[:5]) if base else ()
        item = core + extra
        d.lists["traits"].append(item)
        self.proj._trait_costs = None
        self.vcat.set("All")
        self.vfind.set("")
        self.fill()
        self.select(len(d.lists["traits"]) - 1)
        self.update_title()
        self.app.update_status()
        self.app.say("Created trait '%s'. Save (Ctrl+S) to write it%s." % (r["name"], "" if P_.text else "; no GameText.yaml was found, so set its text ids by hand"))
        return item

    def copy_trait(self):
        L = self.items()
        if self.sel is None or self.sel >= len(L):
            messagebox.showinfo("Copy trait", "Select a trait first.")
            return
        self.new_trait(trait_get(L[self.sel], "TraitName"))

    def delete_trait(self):
        L = self.items()
        if self.sel is None or self.sel >= len(L):
            return
        nm = trait_get(L[self.sel], "TraitName")
        users = self.proj.trait_users(nm)
        msg = "Remove the trait '%s' from RacialTraits.xml?" % nm
        if users:
            msg += "\n\n%d race(s) still list it: %s.\nIt will also be taken out of their trait sets." % (len(users), ", ".join(r.name() for r in users[:8]))
        if not messagebox.askyesno("Delete trait", msg + "\n\nUndo brings it back until you Save.", icon="warning", default="no"):
            return
        del L[self.sel]
        for i, it in enumerate(L):
            ex = trait_get(it, "Excludes", ())
            if nm in ex:
                L[i] = trait_set(it, "Excludes", tuple(x for x in ex if x != nm))
        for r in users:
            for k, v in r.lists.items():
                if k.startswith("traits") and nm in v:
                    r.lists[k] = [x for x in v if x != nm]
        self.sel = None
        self.proj._trait_costs = None
        self.fill()
        self.show()
        self.update_title()
        self.app.update_status()
        self.app.say("Deleted trait '%s'. Save to write it; Undo brings it back." % nm)

    def on_menu(self, ev):
        try:
            iid = self.tv.identify_row(ev.y)
            if iid:
                self.tv.selection_set(iid)
                self.sel = int(iid)
                self.show()
        except Exception:
            pass
        m = tk.Menu(self, tearoff=0)
        m.add_command(label="New trait…", command=self.new_trait)
        m.add_command(label="Copy this trait…", command=self.copy_trait)
        m.add_separator()
        m.add_command(label="Delete this trait", command=self.delete_trait)
        try:
            m.tk_popup(ev.x_root, ev.y_root)
        finally:
            m.grab_release()


class TextImportView(ttk.Frame):
    """Bulk names and descriptions: export every module's text to a CSV, edit it (or let someone draft it), then load the CSV here to write all of it at once.
    Nothing is saved until you press Save (Ctrl+S) like any other edit; Undo works too."""
    HEAD = ("uid", "file", "kind", "current_name", "new_name", "current_description", "new_description")

    def __init__(self, master, app):
        super().__init__(master)
        self.app, self.proj, self.rows = app, app.proj, []
        top = ttk.Frame(self)
        top.pack(fill="x", padx=10, pady=(10, 4))
        ttk.Label(top, text="Bulk names & descriptions", font=("Segoe UI", 13, "bold")).pack(side="left")
        bar = ttk.Frame(self)
        bar.pack(fill="x", padx=10, pady=4)
        ttk.Button(bar, text="Open CSV...", command=self.open_csv).pack(side="left")
        ttk.Button(bar, text="Paste CSV from clipboard", command=self.paste_csv).pack(side="left", padx=6)
        ttk.Button(bar, text="Export all modules to CSV...", command=self.export_csv).pack(side="left")
        self.btn_apply = ttk.Button(bar, text="Apply to the editor", command=self.apply, state="disabled")
        self.btn_apply.pack(side="right")
        ttk.Label(self, wraplength=1000, justify="left", foreground=DIM,
                  text="The CSV needs a 'uid' column plus 'new_name' and / or 'new_description' (other columns are ignored; an empty cell leaves that text alone). "
                       "Apply changes the module's GameText name / description entries (a module that shares an entry with another module, or uses the base game's text, "
                       "gets its own new entry) and its inline <Name> / <Description>. Check the list, press Apply, look at the result in Ship Modules, then Save.").pack(fill="x", padx=10)
        self.info = ttk.Label(self, text="No CSV loaded.", foreground=ORANGE)
        self.info.pack(fill="x", padx=10, pady=4)
        cols = ("uid", "state", "name", "desc")
        fr = ttk.Frame(self)
        fr.pack(fill="both", expand=True, padx=10, pady=(0, 10))
        self.tv = ttk.Treeview(fr, columns=cols, show="headings", selectmode="browse")
        for c, w, t in (("uid", 200, "UID"), ("state", 170, "Result"), ("name", 330, "Name:  now  ->  new"), ("desc", 460, "Description (new)")):
            self.tv.heading(c, text=t)
            self.tv.column(c, width=w, anchor="w")
        sb = ttk.Scrollbar(fr, orient="vertical", command=self.tv.yview)
        self.tv.configure(yscrollcommand=sb.set)
        self.tv.pack(side="left", fill="both", expand=True)
        sb.pack(side="right", fill="y")

    # ---- reading a CSV
    def _module(self, uid):
        u = uid.strip().lower()
        for m in self.proj.modules:
            if m.get("UID").strip().lower() == u:
                return m, False
        for m in self.proj.base_modules:
            if m.get("UID").strip().lower() == u:
                return m, True
        for m in self.proj.techs:                                            # a research-tree tech: its name / description text works the same way
            if m.get("UID").strip().lower() == u:
                return m, False
        return None, False

    def current_text(self, m, tag, inline):
        e = self.proj.text_for(m, tag)
        if e is not None:
            return e.get("ENG").strip()
        v = m.get(tag).strip()
        if v.isdigit():
            e2 = self.proj.text_display_by_id(int(v))
            if e2 is not None:
                return (e2.get("ENG") or "").strip()
        return re.sub(r"\s+", " ", m.get(inline)).strip()

    def load_text(self, text):
        import io
        text = text.lstrip("\ufeff")
        try:
            rd = csv.DictReader(io.StringIO(text))
            heads = {(h or "").strip().lower(): h for h in (rd.fieldnames or [])}
        except Exception as ex:
            messagebox.showerror("Text import", "That is not a readable CSV:\n%s" % ex)
            return
        def col(*names):
            for n in names:
                if n in heads:
                    return heads[n]
            return None
        cu, cn, cd = col("uid", "id"), col("new_name", "name"), col("new_description", "description", "desc")
        if cu is None or (cn is None and cd is None):
            messagebox.showerror("Text import", "The CSV needs a 'uid' column and a 'new_name' and / or 'new_description' column.\nColumns found: %s" % ", ".join(h for h in heads) or "(none)")
            return
        self.rows = []
        for rec in rd:
            uid = (rec.get(cu) or "").strip()
            if not uid:
                continue
            nn = (rec.get(cn) or "").strip() if cn else ""
            nd = (rec.get(cd) or "").strip() if cd else ""
            m, base = self._module(uid)
            self.rows.append({"uid": uid, "m": m, "base": base, "name": nn, "desc": nd})
        self.show_rows()

    def show_rows(self):
        self.tv.delete(*self.tv.get_children())
        ok = same = miss = 0
        for i, r in enumerate(self.rows):
            m = r["m"]
            if m is None:
                state, nm = "not found", r["name"]
                miss += 1
            else:
                cn = self.current_text(m, "NameIndex", "Name")
                cd = self.current_text(m, "DescriptionIndex", "Description")
                chg = (r["name"] and r["name"] != cn) or (r["desc"] and r["desc"] != cd)
                state = ("will change" if chg else "already the same") + ("  (base-game module: copied into the mod)" if r["base"] and chg else "")
                nm = "%s  ->  %s" % (cn, r["name"] or "(unchanged)")
                r["chg"] = bool(chg)
                if chg:
                    ok += 1
                else:
                    same += 1
            self.tv.insert("", "end", iid=str(i), values=(r["uid"], state, nm, r["desc"] or "(unchanged)"))
        self.info.configure(text="%d rows: %d will change, %d already the same, %d not found in this mod." % (len(self.rows), ok, same, miss))
        self.btn_apply.configure(state="normal" if ok else "disabled")

    def open_csv(self):
        f = filedialog.askopenfilename(parent=self, title="Pick the CSV", filetypes=[("CSV", "*.csv"), ("All files", "*.*")])
        if f:
            try:
                self.load_text(Path(f).read_text(encoding="utf-8-sig"))
            except Exception as ex:
                messagebox.showerror("Text import", "Could not read that file:\n%s" % ex)

    def paste_csv(self):
        try:
            t = self.clipboard_get()
        except Exception:
            messagebox.showinfo("Text import", "The clipboard is empty. Copy the CSV text first.")
            return
        self.load_text(t)

    # ---- writing
    def export_csv(self):
        f = filedialog.asksaveasfilename(parent=self, title="Save the module text as CSV", defaultextension=".csv", filetypes=[("CSV", "*.csv")], initialfile="module_text.csv")
        if not f:
            return
        with open(f, "w", newline="", encoding="utf-8-sig") as fh:
            w = csv.writer(fh)
            w.writerow(self.HEAD)
            for m in self.proj.modules:
                w.writerow([m.get("UID").strip(), str(m.rel).replace("\\", "/"), "weapon" if m.get("WeaponType").strip() else "module",
                            self.current_text(m, "NameIndex", "Name"), "", self.current_text(m, "DescriptionIndex", "Description"), ""])
        self.app.say("Saved %d modules to %s - fill in new_name / new_description and load it back here." % (len(self.proj.modules), f))

    def _put(self, m, idx_tag, inline_tag, text, suffix, shared):
        """Write one text. Returns a short note about what happened."""
        P = self.proj
        done = False
        if P.text and idx_tag in m.cur:
            v = m.get(idx_tag).strip()
            e = P.text.by_id.get(int(v)) if v.isdigit() else None
            if e is not None and not e.external and (int(v) not in shared or shared[int(v)] <= 1):
                if e.get("ENG").strip() != text:
                    e.set("ENG", text)
                done = True
            else:                                                       # missing, the base game's or shared with other modules: its own entry
                nid = P.next_text_id()
                P.text.add_entry("%s_%s" % (m.get("UID").strip() or "Module", suffix), nid, text)
                m.set(idx_tag, str(nid))
                done = True
        if inline_tag and inline_tag in m.cur and m.get(inline_tag).strip() != text:
            m.set(inline_tag, text)
            done = True
        return done

    def apply(self):
        P = self.proj
        if not self.rows:
            return
        shared = collections.Counter()
        for m in P.modules + P.base_modules + P.techs:
            for tag in ("NameIndex", "DescriptionIndex"):
                v = m.get(tag).strip()
                if v.isdigit():
                    shared[int(v)] += 1
        n = skipped = 0
        notes = []
        for r in self.rows:
            m = r["m"]
            if m is None or not r.get("chg"):
                continue
            try:
                tech = m in P.techs                                           # a tech's own <Name> is an identifier: only its GameText entries are changed
                a = self._put(m, "NameIndex", None if tech else "Name", r["name"], "Name", shared) if r["name"] else False
                b = self._put(m, "DescriptionIndex", None if tech else "Description", r["desc"], "Desc", shared) if r["desc"] else False
                if a or b:
                    n += 1
                else:
                    skipped += 1
                    notes.append("%s: nothing to write the text into" % r["uid"])
            except Exception as ex:
                log_exc("text import")
                skipped += 1
                notes.append("%s: %s" % (r["uid"], ex))
        self.app.update_status()
        try:
            self.app.refresh()
        except Exception:
            pass
        self.show_rows()
        msg = "Applied to %d module(s). Look at them in Ship Modules, then press Save (Ctrl+S) to keep them - or Undo." % n
        if notes:
            msg += "  %d could not be written: %s" % (skipped, "; ".join(notes[:4]))
        self.info.configure(text=msg)
        self.app.say(msg)


class ModulePicturesView(ttk.Frame):
    """Bulk module pictures: open a picture pack (a .zip or a folder of PNGs named after the module UID, like kli_Shield_10KW.png),
    see which modules each picture belongs to, then apply: every picture is copied flat into Textures\\Modules\\<UID>.png when you Save
    and the module's IconTexturePath becomes Modules/<UID>. Undo works like any other edit."""
    IMG = (".png",)

    def __init__(self, master, app):
        super().__init__(master)
        self.app, self.proj, self.rows, self.tmp, self.src = app, app.proj, [], None, ""
        top = ttk.Frame(self)
        top.pack(fill="x", padx=10, pady=(10, 4))
        ttk.Label(top, text="Bulk module pictures", font=("Segoe UI", 13, "bold")).pack(side="left")
        bar = ttk.Frame(self)
        bar.pack(fill="x", padx=10, pady=4)
        ttk.Button(bar, text="Open picture pack (.zip)...", command=self.open_zip).pack(side="left")
        ttk.Button(bar, text="Open folder...", command=self.open_folder).pack(side="left", padx=6)
        self.only = tk.BooleanVar(value=True)
        ttk.Checkbutton(bar, text="Hide pictures that are already in place", variable=self.only, command=self.show_rows).pack(side="left", padx=12)
        self.btn_apply = ttk.Button(bar, text="Apply to the editor", command=self.apply, state="disabled")
        self.btn_apply.pack(side="right")
        ttk.Label(self, wraplength=1000, justify="left", foreground=DIM,
                  text="A pack is any .zip or folder holding PNG files named after the module's UID (folders inside it do not matter: every picture ends up flat in Textures\\Modules, "
                       "which is where the game looks). Apply stages the pictures and sets each module's IconTexturePath; look at the result in Ship Modules, then Save (Ctrl+S). "
                       "Pictures with no matching module are listed and ignored.").pack(fill="x", padx=10)
        self.info = ttk.Label(self, text="No pack loaded.", foreground=ORANGE)
        self.info.pack(fill="x", padx=10, pady=4)
        fr = ttk.Frame(self)
        fr.pack(fill="both", expand=True, padx=10, pady=(0, 10))
        self.tv = ttk.Treeview(fr, columns=("uid", "state", "now", "name"), show="headings", selectmode="browse")
        for c, w, t in (("uid", 230, "UID"), ("state", 190, "Result"), ("now", 260, "Picture now"), ("name", 420, "Module")):
            self.tv.heading(c, text=t)
            self.tv.column(c, width=w, anchor="w")
        sb = ttk.Scrollbar(fr, orient="vertical", command=self.tv.yview)
        self.tv.configure(yscrollcommand=sb.set)
        self.tv.pack(side="left", fill="both", expand=True)
        sb.pack(side="right", fill="y")
        self.prev = ttk.Label(fr, text="")
        self.prev.pack(side="right", padx=10, anchor="n")
        self.tv.bind("<<TreeviewSelect>>", self.preview)
        self._img = None

    def _module(self, uid):
        u = uid.strip().lower()
        for m in self.proj.modules:
            if m.get("UID").strip().lower() == u:
                return m, False
        for m in self.proj.base_modules:
            if m.get("UID").strip().lower() == u:
                return m, True
        return None, False

    def _clean(self):
        if self.tmp:
            shutil.rmtree(self.tmp, ignore_errors=True)
        self.tmp = None

    def open_zip(self):
        import zipfile, tempfile
        f = filedialog.askopenfilename(parent=self, title="Picture pack", filetypes=[("Zip files", "*.zip"), ("All files", "*.*")])
        if not f:
            return
        try:
            self._clean()
            self.tmp = tempfile.mkdtemp(prefix="sdbe_pics_")
            files, dup = {}, 0
            with zipfile.ZipFile(f) as z:
                for n in z.namelist():
                    base = n.replace("\\", "/").rsplit("/", 1)[-1]
                    if n.endswith("/") or "__MACOSX" in n or not base.lower().endswith(self.IMG):
                        continue
                    stem = base[:-4]
                    if stem.lower() in files:
                        dup += 1
                    dest = Path(self.tmp) / base
                    with z.open(n) as s, open(dest, "wb") as d:
                        shutil.copyfileobj(s, d)
                    files[stem.lower()] = dest
            self.src = Path(f).name
            self.load_files(files, dup)
        except Exception as ex:
            log_exc("module pictures zip")
            messagebox.showerror("Module pictures", "Could not read that zip:\n%s" % ex, parent=self)

    def open_folder(self):
        d = filedialog.askdirectory(parent=self, title="Folder of module pictures")
        if not d:
            return
        files, dup = {}, 0
        for p in Path(d).rglob("*"):
            if p.is_file() and p.suffix.lower() in self.IMG:
                if p.stem.lower() in files:
                    dup += 1
                files[p.stem.lower()] = p
        self.src = Path(d).name
        self.load_files(files, dup)

    def load_files(self, files, dup=0):
        P = self.proj
        self.rows, self.dup = [], dup
        for stem, path in sorted(files.items()):
            m, base = self._module(stem)
            self.rows.append({"uid": path.stem, "m": m, "base": base, "file": path})
        for r in self.rows:
            m = r["m"]
            if m is None:
                r["state"], r["now"], r["name"], r["chg"] = "no such module", "", "", False
                continue
            uid = m.get("UID").strip()
            now = m.get("IconTexturePath").strip()
            e = None
            try:
                e = P.text_for(m, "NameIndex")
            except Exception:
                pass
            r["name"] = (e.get("ENG").strip() if e is not None else m.get("Name").strip())
            r["now"] = now
            same = False
            if now.lower() == ("modules/" + uid).lower():
                try:
                    cur = P.find_file(now)
                    same = cur is not None and Path(cur).read_bytes() == r["file"].read_bytes()
                except Exception:
                    same = False
            r["chg"] = not same
            r["state"] = "already in place" if same else ("will replace" if now.lower() == ("modules/" + uid).lower() else "will be set")
        self.show_rows()

    def show_rows(self):
        self.tv.delete(*self.tv.get_children())
        ok = same = miss = 0
        for i, r in enumerate(self.rows):
            if r["state"] == "no such module":
                miss += 1
            elif r["state"] == "already in place":
                same += 1
            else:
                ok += 1
            if self.only.get() and r["state"] == "already in place":
                continue
            self.tv.insert("", "end", iid=str(i), values=(r["uid"], r["state"], r["now"], r["name"]))
        self.btn_apply.configure(state="normal" if ok else "disabled")
        self.info.configure(text="%s: %d picture(s) to apply, %d already in place, %d with no module%s." % (
            self.src or "pack", ok, same, miss, ("; %d name clash(es) in the pack (the last one is used)" % self.dup) if getattr(self, "dup", 0) else ""))

    def preview(self, _e=None):
        sel = self.tv.selection()
        if not sel:
            return
        try:
            f = self.rows[int(sel[0])]["file"]
            img = tk.PhotoImage(file=str(f))
            z = max(1, 128 // max(img.width(), img.height(), 1))
            self._img = img.zoom(z) if z > 1 else img
            self.prev.configure(image=self._img)
        except Exception:
            self.prev.configure(image="", text="")

    def apply(self):
        P = self.proj
        n, notes = 0, []
        for r in self.rows:
            m = r["m"]
            if m is None or not r.get("chg"):
                continue
            try:
                P.set_icon("module", m, "__import", str(r["file"]))
                n += 1
            except Exception as ex:
                log_exc("module pictures")
                notes.append("%s: %s" % (r["uid"], ex))
        self.app.update_status()
        try:
            self.app.refresh()
        except Exception:
            pass
        for r in self.rows:
            if r["m"] is not None and r.get("chg") and not any(r["uid"] in x for x in notes):
                r["chg"], r["state"], r["now"] = False, "applied (Save to keep)", "Modules/" + r["m"].get("UID").strip()
        self.show_rows()
        msg = "Applied %d picture(s). Look at them in Ship Modules, then press Save (Ctrl+S) to keep them - or Undo." % n
        if notes:
            msg += "  %d could not be applied: %s" % (len(notes), "; ".join(notes[:3]))
        self.info.configure(text=msg)
        self.app.say(msg)


class ShipModelsView(ttk.Frame):
    """Bulk ship models (drop-in): open a .zip or folder holding .fbx ship models (with their .dds / .png textures beside them). Each model is matched to the
    hull(s) whose ModelPath ends in the same name (TypeIX.fbx -> ModelPath 'mod Model/Vulfar/TypeIX'); Apply stages the model and its textures into the
    mod's own 'mod Model' folder (the old file is backed up on Save) and points the hull at it. Undo works like any other edit."""
    MODELS = (".fbx", ".obj")
    TEX = (".dds", ".png", ".tga", ".jpg", ".jpeg", ".bmp")

    def __init__(self, master, app):
        super().__init__(master)
        self.app, self.proj, self.rows, self.tmp, self.src = app, app.proj, [], None, ""
        ttk.Label(self, text="Bulk ship models (drop-in)", font=("Segoe UI", 13, "bold")).pack(anchor="w", padx=10, pady=(10, 4))
        bar = ttk.Frame(self)
        bar.pack(fill="x", padx=10, pady=4)
        ttk.Button(bar, text="Open model pack (.zip)...", command=self.open_zip).pack(side="left")
        ttk.Button(bar, text="Open folder...", command=self.open_folder).pack(side="left", padx=6)
        self.btn_apply = ttk.Button(bar, text="Apply to the editor", command=self.apply, state="disabled")
        self.btn_apply.pack(side="right")
        ttk.Label(self, wraplength=1000, justify="left", foreground=DIM,
                  text="A pack is a .zip or a folder with .fbx ship models and the textures they use (.dds / .png). Each model is matched to the hull whose ModelPath ends in its file name "
                       "(TypeIX.fbx matches ModelPath 'mod Model/Vulfar/TypeIX'). Apply stages the model and its textures into the mod's 'mod Model' folder, next to where the hull's model "
                       "lives, and points the hull at it. Look at it in the game, then Save (Ctrl+S); the old model is backed up first, so it can be put back.").pack(fill="x", padx=10)
        self.info = ttk.Label(self, text="No pack loaded.", foreground=ORANGE)
        self.info.pack(fill="x", padx=10, pady=4)
        fr = ttk.Frame(self)
        fr.pack(fill="both", expand=True, padx=10, pady=(0, 10))
        self.tv = ttk.Treeview(fr, columns=("file", "state", "hull", "target", "tex"), show="headings", selectmode="browse")
        for c, w, t in (("file", 170, "Model"), ("state", 200, "Result"), ("hull", 200, "Hull(s) using it"), ("target", 330, "Goes to (inside the mod)"), ("tex", 260, "Textures")):
            self.tv.heading(c, text=t)
            self.tv.column(c, width=w, anchor="w")
        sb = ttk.Scrollbar(fr, orient="vertical", command=self.tv.yview)
        self.tv.configure(yscrollcommand=sb.set)
        self.tv.pack(side="left", fill="both", expand=True)
        sb.pack(side="right", fill="y")

    def _clean(self):
        if self.tmp:
            shutil.rmtree(self.tmp, ignore_errors=True)
            self.tmp = None

    def open_zip(self):
        import zipfile, tempfile
        f = filedialog.askopenfilename(parent=self, title="Model pack", filetypes=[("Zip files", "*.zip"), ("All files", "*.*")])
        if not f:
            return
        try:
            self._clean()
            self.tmp = tempfile.mkdtemp(prefix="sdbe_models_")
            with zipfile.ZipFile(f) as z:
                for n in z.namelist():
                    base = n.replace("\\", "/").rsplit("/", 1)[-1]
                    if n.endswith("/") or "__MACOSX" in n or not base.lower().endswith(self.MODELS + self.TEX):
                        continue
                    with z.open(n) as s, open(Path(self.tmp) / base, "wb") as d:
                        shutil.copyfileobj(s, d)
            self.src = Path(f).name
            self.load_dir(Path(self.tmp))
        except Exception as ex:
            log_exc("ship models zip")
            messagebox.showerror("Ship models", "Could not read that zip:\n%s" % ex, parent=self)

    def open_folder(self):
        d = filedialog.askdirectory(parent=self, title="Folder of ship models")
        if d:
            self.src = Path(d).name
            self.load_dir(Path(d))

    def _target(self, h):
        """(rel path without extension, new ModelPath or None) for a hull: the mod's 'mod Model' folder."""
        mp = (h.get("ModelPath") or "").strip().replace("\\", "/").strip("/")
        raw = re.sub(r"\.(obj|fbx|xnb)$", "", mp, flags=re.I)
        if re.match(r"mod\s", raw, re.I):
            return raw, None
        tail = re.sub(r"^(Model/)?(Ships/)?", "", raw, flags=re.I)
        return "mod Model/" + tail, "mod Model/" + tail

    def _dest(self, rel):
        """Path in the mod for rel, re-using folders that exist with other capitals."""
        p = Path(self.proj.root)
        for part in rel.split("/"):
            q = p / part
            if not q.exists() and p.is_dir():
                q = next((x for x in p.iterdir() if x.name.lower() == part.lower()), q)
            p = q
        return p

    def load_dir(self, d):
        P = self.proj
        files = [p for p in Path(d).rglob("*") if p.is_file()]
        tex = {p.name.lower(): p for p in files if p.suffix.lower() in self.TEX}
        hulls = list(P.hulls) + list(P.base_hulls)
        self.rows = []
        for f in sorted((p for p in files if p.suffix.lower() in self.MODELS), key=lambda x: x.name.lower()):
            users = [h for h in hulls if Project.norm_model(h.get("ModelPath")).rsplit("/", 1)[-1] == f.stem.lower()]
            names = ", ".join(sorted({(h.get("VisibleName") or h.get("HullName") or h.path.stem).strip() for h in users}))
            used = []
            try:
                blob = f.read_bytes().lower()
                for m in re.finditer(rb"([\w\- .]+\.(?:dds|png|tga|jpg|jpeg|bmp))", blob):
                    n = m.group(1).decode("latin1").strip()
                    if n in tex and tex[n] not in used:
                        used.append(tex[n])
            except OSError:
                pass
            row = {"file": f, "users": users, "names": names, "tex": used, "state": "", "target": "", "rel": None, "newmp": None}
            if not users:
                row["state"] = "no hull uses this name"
            else:
                rel, newmp = self._target(users[0])
                dest = self._dest(rel + f.suffix.lower())
                row["rel"], row["newmp"], row["dest"], row["target"] = rel, newmp, dest, rel + f.suffix.lower()
                if dest.exists():
                    try:
                        same = dest.read_bytes() == f.read_bytes()
                    except OSError:
                        same = False
                    row["state"] = "already in place" if same else "will replace (old one backed up)"
                else:
                    row["state"] = "will be added"
            self.rows.append(row)
        self.show_rows()

    def show_rows(self):
        self.tv.delete(*self.tv.get_children())
        ok = 0
        for i, r in enumerate(self.rows):
            if r["state"].startswith("will"):
                ok += 1
            self.tv.insert("", "end", iid=str(i), values=(r["file"].name, r["state"], r["names"], r["target"], ", ".join(t.name for t in r["tex"])))
        self.btn_apply.configure(state="normal" if ok else "disabled")
        self.info.configure(text="%s: %d model(s) to apply, %d row(s) in all." % (self.src or "pack", ok, len(self.rows)))

    def apply(self):
        P, n, notes = self.proj, 0, []
        for r in self.rows:
            if not r["state"].startswith("will"):
                continue
            try:
                dest = r["dest"]
                folder = dest.parent
                items = [(r["file"], dest, r["rel"])] + [(t, folder / t.name, None) for t in r["tex"]]
                for src, dst, tex in items:
                    P.file_docs = [f for f in P.file_docs if f.path != dst]
                    if dst.exists() and dst.read_bytes() == src.read_bytes():
                        continue
                    P.file_docs.append(FileCopyDoc(src, dst, P.root, tex or str(dst.relative_to(P.root)).replace("\\", "/")))
                if r["newmp"]:
                    for h in r["users"]:
                        h.set("ModelPath", r["newmp"])
                r["state"] = "applied (Save to keep)"
                n += 1
            except Exception as ex:
                log_exc("ship models")
                notes.append("%s: %s" % (r["file"].name, ex))
        try:
            P._icons.clear()
        except Exception:
            pass
        self.app.update_status()
        try:
            self.app.refresh()
        except Exception:
            pass
        self.show_rows()
        msg = "Applied %d model(s). Press Save (Ctrl+S) to write them into the mod - or Undo." % n
        if notes:
            msg += "  %d could not be applied: %s" % (len(notes), "; ".join(notes[:3]))
        self.info.configure(text=msg)
        self.app.say(msg)


# ---- Remove or restore race: nothing is deleted. Files move to <mod>\Test Reports and Backups\Removed races\<Race>\ with a manifest. ----
RR_DIR = "Removed races"
RR_SCAN = ("Races", "RacialTraits", "Hulls", "ShipDesigns", "DiplomacyDialogs", "SolarSystems", "Troops", "NameGenerators", "Flags",
           "Textures/Races", "Textures/portraits", "Textures/Troops")
RR_PROTECT = {"remnant", "unknown", "starfleet", "human"}


def _rr_text(p):
    return Path(p).read_text(encoding="utf-8-sig", errors="replace")


def rr_aliases(root, race):
    """Names the race goes by: its file name plus PortraitName / DiplomacyDialogPath / TechTree from its Races file."""
    out = [race]
    try:
        t = _rr_text(Path(root) / "Races" / (race + ".xml"))
        for tag in ("PortraitName", "DiplomacyDialogPath", "TechTree", "VideoPath", "ShipType", "Singular"):
            for v in re.findall(r"<%s>\s*([^<]+?)\s*</%s>" % (tag, tag), t):
                if v not in out:
                    out.append(v)
    except Exception:
        pass
    return out


def _rr_prefix(a, b):
    n = 0
    for x, y in zip(a, b):
        if x != y:
            break
        n += 1
    return n


def rr_scan(root, race, aliases):
    """Returns (items, tech). items = [(relpath, kind, count, checked, why)]; tech = {relpath: [block text, ...]} (unlock entries tagged for the race)."""
    root = Path(root)
    al = [_norm(a) for a in aliases if len(_norm(a)) >= 2]
    items, seen = [], set()
    for sub in RR_SCAN:
        d = root / sub
        if not d.is_dir():
            continue
        for e in sorted(d.iterdir(), key=lambda x: x.name.lower()):
            n = _norm(e.stem if e.is_file() else e.name)
            if not n:
                continue
            hit = ""
            if any(n == a for a in al):
                hit = "name matches"
            elif any(len(a) >= 4 and n.startswith(a) for a in al) and sub not in ("Textures/Races",):
                hit = "name starts with the race"
            elif e.is_dir() and sub in ("ShipDesigns", "Hulls") and any(len(a) >= 5 and _rr_prefix(n, a) >= 4 for a in al):
                hit = "folder looks like the race's (similar spelling) - check it"
            if not hit:
                continue
            rel = e.relative_to(root).as_posix()
            cnt = sum(1 for x in e.rglob("*") if x.is_file()) if e.is_dir() else 1
            items.append((rel, "folder" if e.is_dir() else "file", cnt, True, hit))
            seen.add(rel)
    def have(rel):
        return rel in seen or any(rel.startswith(s_ + "/") for s_ in seen)

    for sub in ("DiplomacyDialogs", "Encounter Dialogs", "Video", "Textures/portraits", "Textures/Races", "Textures/Troops", "Textures/TroopIcons", "Flags", "Troops",
                "RacialTraits", "NameGenerators", "Textures/Flags"):
        d = root / sub
        if not d.is_dir():
            continue
        for f in sorted(d.rglob("*")):
            if not f.is_file():
                continue
            rel = f.relative_to(root).as_posix()
            if have(rel):
                continue
            n = _norm(f.stem)
            why = ""
            if any(n == a_ or (len(a_) >= 4 and n.startswith(a_)) for a_ in al):
                why = "named after the race"
            elif sub == "Troops" and f.suffix.lower() == ".xml":
                try:
                    t = _rr_text(f)
                except Exception:
                    t = ""
                for tag in ("RaceType", "Icon"):
                    mm = re.search(r"<%s>\s*([^<]+?)\s*</%s>" % (tag, tag), t)
                    if mm and _norm(mm.group(1)) in al:
                        why = "troop of the race (%s)" % tag
            if why:
                items.append((rel, "file", 1, True, why))
                seen.add(rel)
    for sub, ext, pats in (("ShipDesigns", "*.design", (r"(?m)^Style=\s*(.+?)\s*$", r"(?m)^Hull=\s*([^/\r\n]+)/")), ("Hulls", "*.hull", (r"(?m)^Style=\s*(.+?)\s*$",))):
        d = root / sub
        if not d.is_dir():
            continue
        for f in sorted(d.rglob(ext)):
            rel = f.relative_to(root).as_posix()
            if have(rel):
                continue
            try:
                head = _rr_text(f)[:3000]
            except Exception:
                continue
            if any(_norm(mm.group(1)) in al for pt in pats for mm in re.finditer(pt, head)):
                items.append((rel, "file", 1, True, "Style / hull of the race"))
                seen.add(rel)
    dd = root / "ShipDesigns"
    if dd.is_dir():                                           # loose designs named after the race in other folders (salvage ships, prototypes...)
        for f in sorted(dd.rglob("*.design")):
            rel = f.relative_to(root).as_posix()
            if any(rel.startswith(s_ + "/") for s_ in seen) or rel in seen:
                continue
            n = _norm(f.stem)
            if any(len(a) >= 4 and n.startswith(a) for a in al):
                items.append((rel, "file", 1, True, "design named after the race"))
                seen.add(rel)
    sd = root / "SolarSystems"
    if sd.is_dir():
        for f in sorted(sd.glob("*.xml")):
            rel = f.relative_to(root).as_posix()
            if rel in seen:
                continue
            try:
                t = _rr_text(f).lower()
            except Exception:
                continue
            if any(len(a) >= 4 and re.search(r"\b" + re.escape(a) + r"\b", t) for a in [x.lower() for x in aliases]):
                items.append((rel, "file", 1, False, "mentions the race (its home system?) - tick it to move it"))
    tech = {}
    td = root / "Technology"
    al_l = {a.lower() for a in aliases}
    if td.is_dir():
        for f in td.rglob("*.xml"):
            try:
                t = _rr_text(f)
            except Exception:
                continue
            if "<Type>" not in t:
                continue
            blocks = []
            for m in re.finditer(r"[ \t]*<(Unlocked\w+)>(.*?)</\1>[ \t]*\r?\n?", t, re.S):
                ty = re.search(r"<Type>\s*([^<]+?)\s*</Type>", m.group(2))
                if ty and ty.group(1).strip().lower() in al_l:
                    blocks.append(m.group(0))
            if blocks:
                tech[f.relative_to(root).as_posix()] = blocks
    return items, tech


def rr_novanilla(root):
    """Globals.yaml: UseVanillaRaces false, so the base game's own copies of removed races do not show through. Returns True if changed."""
    p = Path(root) / "Globals.yaml"
    if not p.is_file():
        return False
    raw = p.read_bytes()
    t = raw.decode("utf-8-sig", errors="replace")
    n = re.sub(r"(?m)^(\s*UseVanillaRaces\s*:\s*)true\b", r"\g<1>false", t)
    if n == t:
        return False
    p.write_bytes(n.encode("utf-8-sig") if raw.startswith(b"\xef\xbb\xbf") else n.encode("utf-8"))
    return True


def rr_remove(root, race, aliases, rels, tech):
    """Moves rels and strips the tech entries. Returns (moved, edited, manifest path)."""
    import hashlib
    import json
    import shutil
    root = Path(root)
    arch = root / BACKUP_DIR / RR_DIR / race
    if arch.exists():
        arch = arch.with_name(race + " (" + datetime.datetime.now().strftime("%Y%m%d_%H%M%S") + ")")
    (arch / "files").mkdir(parents=True)
    man = {"race": race, "aliases": aliases, "removed": datetime.datetime.now().isoformat(timespec="seconds"), "moved": [], "edited": []}
    for rel in rels:
        src = root / rel
        if not src.exists():
            continue
        dst = arch / "files" / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.move(str(src), str(dst))
        man["moved"].append(rel)
    for rel, blocks in tech.items():
        p = root / rel
        if not p.exists():
            continue
        raw = p.read_bytes()
        txt = raw.decode("utf-8-sig", errors="replace")
        new = txt
        for b in blocks:
            new = new.replace(b, "", 1)
        bk = arch / "edited" / rel
        bk.parent.mkdir(parents=True, exist_ok=True)
        bk.write_bytes(raw)
        data = new.encode("utf-8-sig") if raw.startswith(b"\xef\xbb\xbf") else new.encode("utf-8")
        p.write_bytes(data)
        man["edited"].append({"rel": rel, "blocks": blocks, "after": hashlib.sha1(data).hexdigest()})
    (arch / "manifest.json").write_text(json.dumps(man, indent=1), encoding="utf-8")
    lines = ["Removed race: %s" % race, "Made by the Balance Editor: Races > Remove or restore race.", "",
             "files\\  = the files and folders that were moved out of the mod (same paths as in the mod).",
             "edited\\ = the Technology files as they were before the unlock entries for this race were taken out.",
             "manifest.json = the list the editor uses to put everything back.", "",
             "To bring the race back: open the editor, Races > Remove or restore race, pick it in the lower list, press Restore.",
             "By hand: copy everything inside files\\ back over the mod folder and copy edited\\ over the Technology files."]
    (arch / "README.txt").write_text("\n".join(lines), encoding="utf-8")
    return len(man["moved"]), len(man["edited"]), arch


def rr_list(root):
    import json
    out = []
    base = Path(root) / BACKUP_DIR / RR_DIR
    if base.is_dir():
        for d in sorted(base.iterdir()):
            mf = d / "manifest.json"
            if mf.is_file():
                try:
                    m = json.loads(mf.read_text(encoding="utf-8"))
                    out.append((d, m))
                except Exception:
                    pass
    return out


def rr_restore(root, arch):
    """Puts a removed race back. Returns (moved back, tech files fixed, problems)."""
    import hashlib
    import json
    import shutil
    root, arch = Path(root), Path(arch)
    man = json.loads((arch / "manifest.json").read_text(encoding="utf-8"))
    probs, nm, ne = [], 0, 0
    for rel in man["moved"]:
        src, dst = arch / "files" / rel, root / rel
        if not src.exists():
            probs.append("missing in the archive: " + rel)
            continue
        if dst.exists():
            probs.append("already exists in the mod, left in the archive: " + rel)
            continue
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.move(str(src), str(dst))
        nm += 1
    for ed in man["edited"]:
        p = root / ed["rel"]
        if not p.exists():
            probs.append("tech file is gone: " + ed["rel"])
            continue
        raw = p.read_bytes()
        if hashlib.sha1(raw).hexdigest() == ed["after"] and (arch / "edited" / ed["rel"]).exists():
            p.write_bytes((arch / "edited" / ed["rel"]).read_bytes())
            ne += 1
            continue
        txt = raw.decode("utf-8-sig", errors="replace")
        add = [b for b in ed["blocks"] if b.strip() not in txt]
        if add:
            k = txt.rfind("</Technology>")
            if k < 0:
                probs.append("could not re-insert the entries into " + ed["rel"])
                continue
            txt = txt[:k] + "".join(b if b.endswith("\n") else b + "\n" for b in add) + txt[k:]
            p.write_bytes(txt.encode("utf-8-sig") if raw.startswith(b"\xef\xbb\xbf") else txt.encode("utf-8"))
            ne += 1
    done = arch.with_name(arch.name + " (restored " + datetime.datetime.now().strftime("%Y%m%d_%H%M%S") + ")")
    try:
        (arch / "manifest.json").rename(arch / "manifest.restored.json")
        if not probs:
            arch.rename(done)
    except Exception:
        pass
    return nm, ne, probs


class RaceRemoveView(ttk.Frame):
    """Races > Remove or restore race. Nothing is deleted: the race's files move into Test Reports and Backups\\Removed races\\<Race>, the tech unlock
    entries tagged for it are taken out of the Technology files, and a manifest is written so Restore can put it all back."""

    def __init__(self, master, app):
        super().__init__(master)
        self.app, self.proj = app, app.proj
        self.items, self.tech, self.checked = [], {}, {}
        ttk.Label(self, text="Remove or restore race", font=("Segoe UI", 13, "bold")).pack(anchor="w", padx=10, pady=(10, 2))
        ttk.Label(self, wraplength=1000, justify="left", foreground=DIM,
                  text="Remove moves a race's files (race file, ship designs, hulls, dialogs, portraits...) into Test Reports and Backups\\Removed races\\<race> and takes the "
                       "race's tech unlock entries out of the Technology files, so the game no longer finds anything of it. Nothing is deleted and everything is listed first; "
                       "Restore puts it all back. Modules and generic files stay where they are. Save your edits first, and close/reopen the editor after a change.").pack(fill="x", padx=10)
        top = ttk.Frame(self)
        top.pack(fill="x", padx=10, pady=6)
        ttk.Label(top, text="Race:").pack(side="left")
        self.race = tk.StringVar()
        self.cb = ttk.Combobox(top, textvariable=self.race, state="readonly", width=28)
        self.cb.pack(side="left", padx=6)
        ttk.Button(top, text="Scan", command=self.scan).pack(side="left")
        ttk.Label(top, text="  Also known as:").pack(side="left")
        self.als = tk.StringVar()
        ttk.Entry(top, textvariable=self.als, width=40).pack(side="left", padx=4)
        self.nov = tk.BooleanVar(value=True)
        ttk.Checkbutton(top, text="Hide the base game's copy too (Globals.yaml UseVanillaRaces: false)", variable=self.nov).pack(side="left", padx=10)
        self.btn_rm = ttk.Button(top, text="Remove race (move to backup)", command=self.remove, state="disabled")
        self.btn_rm.pack(side="right")
        self.info = ttk.Label(self, text="Pick a race and press Scan.", foreground=ORANGE)
        self.info.pack(fill="x", padx=10)
        fr = ttk.Frame(self)
        fr.pack(fill="both", expand=True, padx=10, pady=4)
        self.tv = ttk.Treeview(fr, columns=("on", "what", "n", "why"), show="headings", height=12, selectmode="browse")
        for c, w, t in (("on", 50, "Move"), ("what", 520, "Path in the mod"), ("n", 80, "Files"), ("why", 380, "Why")):
            self.tv.heading(c, text=t)
            self.tv.column(c, width=w, anchor="w")
        sb = ttk.Scrollbar(fr, orient="vertical", command=self.tv.yview)
        self.tv.configure(yscrollcommand=sb.set)
        self.tv.pack(side="left", fill="both", expand=True)
        sb.pack(side="right", fill="y")
        self.tv.bind("<Button-1>", self.click)
        ttk.Separator(self).pack(fill="x", padx=10, pady=6)
        bot = ttk.Frame(self)
        bot.pack(fill="x", padx=10)
        ttk.Label(bot, text="Removed races (can be restored)", font=("Segoe UI", 11, "bold")).pack(side="left")
        ttk.Button(bot, text="Restore selected race", command=self.restore).pack(side="right")
        ttk.Button(bot, text="Refresh", command=self.ensure).pack(side="right", padx=6)
        self.lv = ttk.Treeview(self, columns=("race", "when", "n", "folder"), show="headings", height=5, selectmode="browse")
        for c, w, t in (("race", 200, "Race"), ("when", 170, "Removed"), ("n", 160, "Files moved / tech files"), ("folder", 560, "Archive folder")):
            self.lv.heading(c, text=t)
            self.lv.column(c, width=w, anchor="w")
        self.lv.pack(fill="x", padx=10, pady=(4, 10))
        self.archives = {}
        self.cb.bind("<<ComboboxSelected>>", lambda _e: self.picked())
        self.ensure()

    def ensure(self):
        root = Path(self.proj.root)
        rd = root / "Races"
        names = sorted((f.stem for f in rd.glob("*.xml")), key=str.lower) if rd.is_dir() else []
        self.cb.configure(values=names)
        self.lv.delete(*self.lv.get_children())
        self.archives = {}
        for d, m in rr_list(root):
            iid = self.lv.insert("", "end", values=(m.get("race", d.name), m.get("removed", ""), "%d / %d" % (len(m.get("moved", [])), len(m.get("edited", []))), str(d)))
            self.archives[iid] = d

    def picked(self):
        self.als.set(", ".join(rr_aliases(self.proj.root, self.race.get())))

    def scan(self):
        race = self.race.get()
        if not race:
            return
        als = [a.strip() for a in self.als.get().split(",") if a.strip()] or rr_aliases(self.proj.root, race)
        self.items, self.tech = rr_scan(self.proj.root, race, als)
        self.checked = {it[0]: it[3] for it in self.items}
        self.show()
        n = sum(len(v) for v in self.tech.values())
        warn = "  WARNING: %s is a core race - removing it can break the mod." % race if race.lower() in RR_PROTECT else ""
        self.info.configure(text="%d items to move, %d tech unlock entries in %d Technology files to take out. Untick anything you want to keep.%s" % (len(self.items), n, len(self.tech), warn))
        self.btn_rm.configure(state="normal" if (self.items or self.tech) else "disabled")

    def show(self):
        self.tv.delete(*self.tv.get_children())
        for rel, kind, cnt, _c, why in self.items:
            self.tv.insert("", "end", iid=rel, values=("[x]" if self.checked.get(rel) else "[ ]", rel + ("/" if kind == "folder" else ""), cnt, why))

    def click(self, ev):
        iid = self.tv.identify_row(ev.y)
        if iid and self.tv.identify_column(ev.x) == "#1":
            self.checked[iid] = not self.checked.get(iid)
            self.tv.set(iid, "on", "[x]" if self.checked[iid] else "[ ]")

    def _saved(self):
        try:
            if self.proj.pending():
                messagebox.showwarning("Remove or restore race", "You have unsaved edits. Save (Ctrl+S) first, then try again.")
                return False
        except Exception:
            pass
        return True

    def remove(self):
        race = self.race.get()
        if not race or not self._saved():
            return
        rels = [r for r, on in self.checked.items() if on]
        nt = sum(len(v) for v in self.tech.values())
        if not messagebox.askyesno("Remove race", "Move %d items of %s into Test Reports and Backups\\Removed races and take %d tech unlock entries out?\n\nNothing is deleted; Restore brings it back." % (len(rels), race, nt)):
            return
        try:
            als = [a.strip() for a in self.als.get().split(",") if a.strip()]
            nm, ne, arch = rr_remove(self.proj.root, race, als, rels, self.tech)
            if self.nov.get():
                import shutil
                shutil.copy2(Path(self.proj.root) / "Globals.yaml", arch / "Globals.yaml.before")
                rr_novanilla(self.proj.root)
        except Exception as e:
            log_exc("remove race")
            messagebox.showerror("Remove race", "Stopped part way: %s\n\nWhatever was moved is in Test Reports and Backups\\Removed races." % e)
            return
        self.items, self.tech, self.checked = [], {}, {}
        self.show()
        self.btn_rm.configure(state="disabled")
        self.ensure()
        self.info.configure(text="Removed %s: %d items moved, %d tech files edited. Close and reopen the editor so every tab sees the change." % (race, nm, ne))
        messagebox.showinfo("Remove race", "Done. Archive: %s\n\nClose and reopen the editor so every tab sees the change." % arch)

    def restore(self):
        sel = self.lv.selection()
        if not sel or not self._saved():
            return
        arch = self.archives.get(sel[0])
        if not arch or not messagebox.askyesno("Restore race", "Put %s back into the mod?" % self.lv.set(sel[0], "race")):
            return
        try:
            nm, ne, probs = rr_restore(self.proj.root, arch)
        except Exception as e:
            log_exc("restore race")
            messagebox.showerror("Restore race", str(e))
            return
        self.ensure()
        msg = "Restored %d items and fixed %d tech files. Close and reopen the editor." % (nm, ne)
        if probs:
            msg += "\n\nProblems (left in the archive):\n" + "\n".join(probs[:15])
        self.info.configure(text=msg.split("\n")[0])
        messagebox.showinfo("Restore race", msg)


