class RaceWeaponsView(ttk.Frame):
    """Give a race its own copies of the weapons its designs use: new modules and weapon files with race names and descriptions, balanced against the
    Balance page, unlocked by the same techs, and the race's designs switched over. Everything is staged until Save (and Undo works)."""

    def __init__(self, master, app):
        super().__init__(master)
        self.app, self.proj, self.rows = app, app.proj, []
        ttk.Label(self, text="Race weapons", font=("Segoe UI", 13, "bold")).pack(anchor="w", padx=10, pady=(10, 2))
        ttk.Label(self, wraplength=1000, justify="left", foreground=DIM,
                  text="Pick a race and press Scan: every weapon module its designs use is listed. 'Make race weapons' copies each one as a new module + weapon file named for the race "
                       "('Kulrathi Fang Cannon Mk1'), changes the damage so the DPS per tile on the Balance page stays the same for the race's range / reload, unlocks it under the same techs "
                       "(for that race), and switches the race's designs to the new modules. The old modules stay in the game. Pictures: the new modules use the old module's picture until you give them their own.").pack(fill="x", padx=10)
        top = ttk.Frame(self)
        top.pack(fill="x", padx=10, pady=6)
        self.v = {k: tk.StringVar() for k in ("race", "prefix", "word", "rng", "delay")}
        self.conv = tk.BooleanVar(value=True)
        self.allw = tk.BooleanVar(value=True)
        self.secret = tk.BooleanVar(value=False)
        ttk.Label(top, text="Race (design Style)").grid(row=0, column=0, sticky="w")
        self.cb = ttk.Combobox(top, textvariable=self.v["race"], width=22, state="readonly")
        self.cb.grid(row=1, column=0, padx=(0, 8))
        self.cb.bind("<<ComboboxSelected>>", lambda _e: self.profile())
        for i, (k, lab, w) in enumerate((("prefix", "File prefix", 8), ("word", "Name word", 12), ("rng", "Range x", 6), ("delay", "Reload time x", 8)), 1):
            ttk.Label(top, text=lab).grid(row=0, column=i, sticky="w")
            ttk.Entry(top, textvariable=self.v[k], width=w).grid(row=1, column=i, padx=(0, 8))
        ttk.Checkbutton(top, text="Switch this race's designs to the new modules", variable=self.conv).grid(row=1, column=5, padx=8)
        ttk.Checkbutton(top, text="Every weapon the race can unlock (not only those its designs use)", variable=self.allw).grid(row=0, column=5, columnspan=2, padx=8, sticky="w")
        ttk.Checkbutton(top, text="Include secret / test modules", variable=self.secret).grid(row=1, column=6, padx=8)
        bar = ttk.Frame(self)
        bar.pack(fill="x", padx=10, pady=4)
        ttk.Button(bar, text="Scan", command=self.scan).pack(side="left")
        ttk.Button(bar, text="Balance report", command=self.balance_report).pack(side="left", padx=6)
        ttk.Button(bar, text="Export text CSV...", command=self.export_csv).pack(side="left")
        ttk.Button(bar, text="Import text CSV...", command=self.import_csv).pack(side="left", padx=6)
        self.btn = ttk.Button(bar, text="Make race weapons", command=self.make, state="disabled")
        self.btn.pack(side="right")
        self.info = ttk.Label(self, text="Pick a race and press Scan.", foreground=ORANGE, wraplength=1000, justify="left")
        self.info.pack(fill="x", padx=10, pady=2)
        cols = ("uid", "uses", "group", "size", "now", "newuid", "newname")
        fr = ttk.Frame(self)
        fr.pack(fill="both", expand=True, padx=10, pady=(0, 10))
        self.tv = ttk.Treeview(fr, columns=cols, show="headings", selectmode="browse")
        for c, w, t in (("uid", 190, "Module"), ("uses", 55, "Designs"), ("group", 80, "Class"), ("size", 50, "Size"), ("now", 190, "Name now"), ("newuid", 190, "New UID"), ("newname", 300, "New name")):
            self.tv.heading(c, text=t)
            self.tv.column(c, width=w, anchor="w")
        sb = ttk.Scrollbar(fr, orient="vertical", command=self.tv.yview)
        self.tv.configure(yscrollcommand=sb.set)
        self.tv.pack(side="left", fill="both", expand=True)
        sb.pack(side="right", fill="y")
        self.tv.bind("<Double-1>", self.edit_name)
        self.bind("<Map>", lambda _e: self.fill_races())

    def fill_races(self):
        try:
            styles = sorted({di.f.get("Style", "").strip() for di in self.proj.load_designs() if not di.is_base and di.f.get("Style", "").strip()}, key=str.lower)
        except Exception:
            styles = []
        self.cb["values"] = styles
        if not self.v["race"].get() and styles:
            pick = next((x for x in styles if x in RACE_WEAPON_PROFILES), styles[0])
            self.v["race"].set(pick)
            self.profile()

    def profile(self):
        race = self.v["race"].get()
        pf = RACE_WEAPON_PROFILES.get(race)
        self.v["prefix"].set(pf["prefix"] if pf else (re.sub(r"[^a-z]", "", race.lower())[:3] + "_"))
        self.v["word"].set(pf["word"] if pf else "")
        self.v["rng"].set("%g" % (pf["rng"] if pf else 1.0))
        self.v["delay"].set("%g" % (pf["delay"] if pf else 1.0))

    def _mods(self):
        d = {}
        for m in list(self.proj.base_modules) + list(self.proj.modules):          # the mod's own file wins over the base game's
            d[(m.get("UID") or m.path.stem).strip().lower()] = m
        return d

    def current_name(self, m):
        e = self.proj.text_for(m, "NameIndex")
        if e is not None:
            return e.get("ENG").strip()
        v = m.get("NameIndex").strip()
        e2 = self.proj.text_display_by_id(int(v)) if v.isdigit() else None
        return ((e2.get("ENG") if e2 is not None else "") or m.get("Name")).strip()

    def scan(self):
        P = self.proj
        race = self.v["race"].get()
        if not race:
            return
        mods, uses = self._mods(), collections.Counter()
        for di in P.load_designs():
            if di.is_base or di.f.get("Style", "").strip() != race:
                continue
            for u in set(x.lower() for x in di._uids):
                uses[u] += 1
        pref = self.v["prefix"].get().strip().lower()
        found = []
        cand = dict(uses)
        if self.allw.get():                                                        # the race keeps the same number of weapons it has now, used by a design or not
            usable, _own = bal_race_mods(P, race)
            for u in usable:
                m = mods.get(u)
                if m is not None and u not in cand and P.unlocked_by.get(u):
                    cand[u] = 0
        for u, n in cand.items():
            m = mods.get(u)
            if m is None or not m.get("WeaponType").strip() or u.startswith(pref):
                continue
            if not self.secret.get() and n == 0 and (re.search(r"(?i)secret|mandatory|remnant|zz_|test", str(m.rel)) or re.search(r"(?i)^(zz_|test)", u)):
                continue
            w = P.weapon_for(m)
            if w is None or not (w.get("DamageAmount").strip() or w.get("PowerDamage").strip()):
                continue
            found.append((m, w, n))
        pf = RACE_WEAPON_PROFILES.get(race, {})
        bycls = collections.defaultdict(list)
        for m, w, n in found:
            bycls[RACE_CLASS_WORD.get(bal_group(w), "Weapon")].append((m, w, n))
        self.rows = []
        word = self.v["word"].get().strip()
        TIER = ("A light, early design.", "A standard design in wide use.", "A refined, later design.", "A heavy design for the largest ships.")
        for cw, lst in bycls.items():
            lst.sort(key=lambda t: (_area(t[0]) or 0, _g(t[1], "DamageAmount", 0) or 0))
            sizes = collections.Counter("%dx%d" % (_g(t[0], "XSize", 0), _g(t[0], "YSize", 0)) for t in lst)
            seen = collections.Counter()
            for k, (m, w, n) in enumerate(lst, 1):
                uid = (m.get("UID") or m.path.stem).strip()
                grp = bal_group(w)
                vg = pf.get("voice", {}).get(grp if grp in ("Beam", "Cannon", "Torpedo", "Missile") else "other", "")
                vg = (vg + " " + TIER[min(3, (k - 1) * 4 // max(1, len(lst)))]).strip()
                sz = "%dx%d" % (_g(m, "XSize", 0), _g(m, "YSize", 0))
                if len(lst) > 8:                                                    # a long list: the size tells the weapons apart, Mk only separates same-size ones
                    seen[sz] += 1
                    name = " ".join(x for x in (race, word, cw, sz) + (("Mk%d" % seen[sz],) if sizes[sz] > 1 else ()) if x)
                else:
                    name = " ".join(x for x in (race, word, cw, "Mk%d" % k) if x)
                mech = "%s mount, %s." % ("%dx%d" % (_g(m, "XSize", 0), _g(m, "YSize", 0)), ("%d degree arc" % _g(m, "FieldOfFire")) if _g(m, "FieldOfFire") else "turret or fixed mount")
                self.rows.append({"m": m, "w": w, "uses": n, "group": cw, "uid": uid, "newuid": re.sub(r"[^A-Za-z0-9_]", "_", self.v["prefix"].get().strip() + uid),
                                  "name": name, "desc": (vg + " " + mech).strip()})
        self.rows.sort(key=lambda r: (r["group"], -r["uses"]))
        self.show()

    def show(self):
        self.tv.delete(*self.tv.get_children())
        for i, r in enumerate(self.rows):
            m = r["m"]
            self.tv.insert("", "end", iid=str(i), values=(r["uid"], r["uses"], r["group"], "%dx%d" % (_g(m, "XSize", 0), _g(m, "YSize", 0)), self.current_name(m), r["newuid"], r["name"]))
        self.info.configure(text="%d weapon modules are used by the %s designs. Double-click a row to change its new name; use the CSV buttons to edit the descriptions."
                            % (len(self.rows), self.v["race"].get()) if self.rows else "No weapon modules found for that race's designs (or they all have race copies already).")
        self.btn.configure(state="normal" if self.rows else "disabled")

    def edit_name(self, _e=None):
        sel = self.tv.selection()
        if not sel:
            return
        r = self.rows[int(sel[0])]
        from tkinter import simpledialog
        v = simpledialog.askstring("New name", "Name for %s:" % r["uid"], initialvalue=r["name"], parent=self)
        if v and v.strip():
            r["name"] = v.strip()
            self.show()

    def export_csv(self):
        if not self.rows:
            return
        f = filedialog.asksaveasfilename(parent=self, defaultextension=".csv", filetypes=[("CSV", "*.csv")], initialfile="race_weapons_%s.csv" % self.v["race"].get())
        if not f:
            return
        with open(f, "w", newline="", encoding="utf-8-sig") as fh:
            w = csv.writer(fh)
            w.writerow(("uid", "new_uid", "class", "current_name", "new_name", "new_description"))
            for r in self.rows:
                w.writerow((r["uid"], r["newuid"], r["group"], self.current_name(r["m"]), r["name"], r["desc"]))
        self.app.say("Saved %d rows to %s. Edit new_name / new_description, then load it back with 'Import text CSV'." % (len(self.rows), f))

    def import_csv(self):
        f = filedialog.askopenfilename(parent=self, filetypes=[("CSV", "*.csv"), ("All files", "*.*")])
        if not f or not self.rows:
            return
        n = 0
        with open(f, newline="", encoding="utf-8-sig") as fh:
            for rec in csv.DictReader(fh):
                r = next((x for x in self.rows if x["uid"].lower() == (rec.get("uid") or "").strip().lower()), None)
                if r is None:
                    continue
                if (rec.get("new_name") or "").strip():
                    r["name"] = rec["new_name"].strip()
                if (rec.get("new_description") or "").strip():
                    r["desc"] = rec["new_description"].strip()
                nu = re.sub(r"[^A-Za-z0-9_]", "_", (rec.get("new_uid") or "").strip())
                if nu:
                    r["newuid"] = nu
                n += 1
        self.show()
        self.info.configure(text="Read the text for %d weapons from the CSV." % n)

    def _bal(self):
        P = self.proj
        o = dict(bal_opts_from_cfg(getattr(P, "bal_cfg", None)), _depths=bal_depths(P))
        return o, bal_support(list(P.modules) + list(P.base_modules), P, o)

    def balance_report(self):
        """DPS per tile of every weapon module the race's designs use, against the median of its class (flags the ones far from it)."""
        P = self.proj
        race = self.v["race"].get()
        mods, uses = self._mods(), set()
        for di in P.load_designs():
            if not di.is_base and di.f.get("Style", "").strip() == race:
                uses |= {x.lower() for x in di._uids}
        o, sup = self._bal()
        allrows = collections.defaultdict(list)
        mine = []
        for u, m in mods.items():
            w = P.weapon_for(m)
            if w is None:
                continue
            rr = bal_row(P, m, w, o, sup)
            if rr is None or not rr["per_tile"]:
                continue
            allrows[rr["group"]].append(rr["per_tile"])
            if u in uses:
                mine.append(rr)
        lines = ["Balance report for %s: DPS per tile of the weapons its designs use, against the median of the whole class." % race, ""]
        for rr in sorted(mine, key=lambda x: (x["group"], x["per_tile"])):
            vals = sorted(allrows[rr["group"]])
            med = vals[len(vals) // 2]
            ratio = rr["per_tile"] / med if med else 0
            lines.append("%-34s %-8s tiles %5.1f  DPS/tile %7.1f  = %3.0f%% of the class median%s" % (rr["uid"][:34], rr["group"], rr["total"] or 0, rr["per_tile"], ratio * 100,
                         "   <-- outlier" if ratio > 1.35 or ratio < 0.65 else ""))
        top = tk.Toplevel(self)
        top.title("Balance report - " + race)
        txt = tk.Text(top, width=130, height=34, font=("Consolas", 9))
        txt.pack(fill="both", expand=True)
        txt.insert("1.0", "\n".join(lines))

    def make(self):
        P = self.proj
        race = self.v["race"].get()
        try:
            rx, dx = float(self.v["rng"].get()), float(self.v["delay"].get())
        except ValueError:
            messagebox.showwarning("Race weapons", "Range x and Reload time x must be numbers (1 = unchanged).", parent=self)
            return
        if not (0.3 <= rx <= 3 and 0.3 <= dx <= 3):
            messagebox.showwarning("Race weapons", "Range x and Reload time x must be between 0.3 and 3.", parent=self)
            return
        if not messagebox.askyesno("Race weapons", "Make %d new weapon modules for %s%s?\n\nNothing is saved until you press Save, and Undo works." % (
                len(self.rows), race, " and switch its designs to them" if self.conv.get() else ""), parent=self):
            return
        o, sup = self._bal()
        mapping, notes, made, made_w = {}, [], 0, {}
        for r in self.rows:
            m, w = r["m"], r["w"]
            try:
                r0 = bal_row(P, m, w, o, sup)
                lvl = r0["use"] if r0 else None
                dmg0 = _g(w, "DamageAmount", 0) or 0
                rng0, del0 = _g(w, "Range"), _g(w, "FireDelay")
                dmgx = (dx if del0 else 1.0) / (rx ** 0.5)
                wuid = re.sub(r"[^A-Za-z0-9_]", "_", self.v["prefix"].get().strip() + (w.get("UID") or w.path.stem).strip())
                shared_w = wuid.lower() in made_w                                           # two modules that use the same weapon file share the race's copy of it
                if shared_w:
                    nw = made_w[wuid.lower()]
                else:
                    nw = P.new_weapon(wuid, w, damage=("%g" % round(dmg0 * dmgx, 2)) if dmg0 else "", rng=("%d" % round(rng0 * rx)) if rng0 else "",
                                      delay=("%g" % round(del0 * dx, 2)) if del0 else "")
                    made_w[wuid.lower()] = nw
                folder = "Race weapons/" + race
                nm = P.new_module(r["newuid"], r["name"], r["desc"], m.get("ModuleType"), m.get("XSize"), m.get("YSize"), folder, wuid, m)
                if "IconTexturePath" in nm.cur and m.get("IconTexturePath").strip():
                    nm.set("IconTexturePath", m.get("IconTexturePath").strip())         # the old picture until the race gets its own
                if r0 and r0["per_tile"] and not shared_w:
                    for _i in range(4):                                                    # keep DPS per tile equal to the old weapon's
                        rn = bal_row(P, nm, nw, o, sup, at_level=lvl)
                        if rn is None or not rn["per_tile"]:
                            break
                        k = r0["per_tile"] / rn["per_tile"]
                        if abs(k - 1.0) < 0.02:
                            break
                        for tag in ("DamageAmount", "PowerDamage"):
                            v = _g(nw, tag)
                            if v:
                                nw.set(tag, bal_fmt_damage(nw.get(tag), v * k))
                n_unl = 0
                for t, ty in list(P.unlocked_by.get(r["uid"].lower(), [])):
                    if ty in ("", race) and (r["newuid"], race) not in t.unlocks:
                        t.unlocks.append((r["newuid"], race))
                        n_unl += 1
                if not n_unl:
                    notes.append("%s: no tech in this mod unlocks the original, so the copy is not unlocked anywhere yet" % r["uid"])
                mapping[r["uid"].lower()] = r["newuid"]
                made += 1
            except Exception as ex:
                log_exc("race weapons")
                notes.append("%s: %s" % (r["uid"], ex))
        nd = 0
        if self.conv.get() and mapping:
            for di in P.load_designs():
                if di.is_base or di.f.get("Style", "").strip() != race:
                    continue
                new = [mapping.get(u.lower(), u) for u in di._uids]
                if new != list(di._uids):
                    P.design_doc(di).set("ModuleUIDs", ";".join(new))
                    nd += 1
        self.app.update_status()
        try:
            self.app.refresh()
        except Exception:
            pass
        msg = "Made %d race weapons for %s%s. Look at them in Ship Modules and Balance, then Save (Ctrl+S) - or Undo." % (made, race, (" and switched %d designs" % nd) if self.conv.get() else "")
        if notes:
            msg += "  %d problem(s): %s" % (len(notes), "; ".join(notes[:3]))
        self.info.configure(text=msg)
        self.app.say(msg)


class DebugView(ttk.Frame):
    """Health check: missing images, duplicate / shared / missing text indexes, broken links.
    The 'Where' column links to the real file position; many problems have an auto-fix."""
    SEVS = {"ERROR": "✖ ERROR", "WARN": "▲ WARN", "INFO": "● info"}
    FILTERS = ("All", "Errors", "Errors + warnings", "Fixable", "Game log only", "Game log errors", "Ignored")

    def __init__(self, master, app):
        super().__init__(master)
        self.app = app
        self.issues, self.shown, self.counts = [], [], {"ERROR": 0, "WARN": 0, "INFO": 0}
        self.all_issues = []
        self._probe_cache, self._probe_deadline = {}, 0.0
        top = tk.Frame(self, bg=BG)
        top.pack(fill="x", padx=12, pady=(10, 2))
        tk.Label(top, text="DEBUG   ·   mod health check", bg=BG, fg=ORANGE,
                 font=("Segoe UI", 14, "bold")).pack(side="left")
        top = tk.Frame(self, bg=BG)                          # the buttons get their own row so none is squeezed off the screen
        top.pack(fill="x", padx=12, pady=(2, 2))
        for text, cmd, hint, style in (
                ("Export CSV…", self.export, "Save the whole report as a CSV file.", "TButton"),
                ("BB+ log errors", self.show_game_errors, "Show only the errors the game itself wrote in blackbox.log (crashes, 'could not find …', load failures) - not the editor's own checks.", "TButton"),
                ("Copy report", self.copy, "Copy the whole report to the clipboard.", "TButton"),
                ("Texture folder…", self.add_texture_dir,
                 "Tell the editor where more textures live (e.g. the base game's Content\\Textures), so icons that are not in the "
                 "mod are found. Remembered for this mod.", "TButton"),
                ("Game log…", self.pick_log,
                 "Pick the game's blackbox.log. The editor normally finds it by itself (next to the game or the mod).", "TButton"),
                ("Copy error log", lambda: self.copy_log(), "Copy everything useful for finding a problem (version, folders searched, the editor's own errors, the first Debug rows) to the clipboard - paste it into the chat.", "TButton"),
                ("Self-test", lambda: self.app.self_test(), "Open every tab of the editor and check that each one builds. Errors are listed here as 'Editor internal error'.", "TButton"),
                ("Rescan", self.scan, "Check the mod again (also re-reads blackbox.log and picks up new image files).", "TButton"),
                ("Ask an AI about this…", self.ask_ai, "Builds a prompt about the selected finding (what it is, where, what the game itself says about the tag) to paste into any AI "
                 "for a plain-words explanation.", "TButton"),
                ("Auto-fix selected", self.fix_selected, "Apply the fix for the selected row(s) that have one.", "TButton"),
                ("Select fixable", self.select_fixable, "Select every listed row that has an auto-fix (Ctrl+A selects all rows). Then press 'Auto-fix selected'.", "TButton")):
            b = ttk.Button(top, text=text, command=cmd, style=style)
            b.pack(side="right", padx=3)
            tip(b, hint)
        self.btn_all = ttk.Button(top, text="Auto-fix all", style="Save.TButton", command=self.fix_all)
        self.btn_all.pack(side="right", padx=3)
        tip(self.btn_all, "Apply every available auto-fix. You see the list first. Fixes only change the editor - press Save to write them.")
        self.summary = tk.Label(self, bg=BG, fg=PEACH, anchor="w", justify="left", wraplength=1200)
        self.summary.pack(fill="x", padx=12, pady=(0, 0))
        self.logline = tk.Label(self, bg=BG, fg=DIM, anchor="w", justify="left", wraplength=1200)
        self.logline.pack(fill="x", padx=12, pady=(0, 4))

        flt = tk.Frame(self, bg=BG)
        flt.pack(fill="x", padx=12, pady=2)
        tk.Label(flt, text="Show", bg=BG, fg=DIM).pack(side="left")
        self.sev = tk.StringVar(value="All")
        cb = ttk.Combobox(flt, textvariable=self.sev, values=list(self.FILTERS), state="readonly", width=16)
        cb.pack(side="left", padx=(4, 12))
        cb.bind("<<ComboboxSelected>>", lambda _e: self.populate())
        tip(cb, "Filter by severity, or show only problems that can be fixed automatically.")
        tk.Label(flt, text="Category", bg=BG, fg=DIM).pack(side="left")
        self.cat = tk.StringVar(value="All")
        self.cat_cb = ttk.Combobox(flt, textvariable=self.cat, values=["All"], state="readonly", width=34)
        self.cat_cb.pack(side="left", padx=(4, 12))
        self.cat_cb.bind("<<ComboboxSelected>>", lambda _e: self.populate())
        tk.Label(flt, text="Filter", bg=BG, fg=DIM).pack(side="left")
        self.q = tk.StringVar()
        self.q.trace_add("write", lambda *_: self.populate())
        ttk.Entry(flt, textvariable=self.q, width=30).pack(side="left", padx=4)
        self.count = tk.Label(flt, bg=BG, fg=DIM)
        self.count.pack(side="right")

        box = tk.Frame(self, bg=BG)
        box.pack(fill="both", expand=True, padx=12, pady=6)
        cols = ("sev", "cat", "item", "detail", "where", "fix")
        self.tree = ttk.Treeview(box, columns=cols, show="headings", selectmode="extended", style="Debug.Treeview")
        try:                                                # every row is two lines tall, so long details wrap instead of being cut off
            import tkinter.font as tkfont
            ttk.Style().configure("Debug.Treeview", rowheight=2 * tkfont.nametofont("TkDefaultFont").metrics("linespace") + 8)
        except Exception:
            pass
        self._wrapw = None
        for c, text, w in (("sev", "Severity", 90), ("cat", "Problem", 220), ("item", "Item", 200),
                           ("detail", "Detail", 520), ("where", "Where  (click to open the file at that line)", 330),
                           ("fix", "Auto-fix", 260)):
            self.tree.heading(c, text=text)
            self.tree.column(c, width=w, minwidth=60, stretch=(c == "detail"))
        vsb = ttk.Scrollbar(box, orient="vertical", command=self.tree.yview)
        hsb = ttk.Scrollbar(box, orient="horizontal", command=self.tree.xview)
        self.tree.configure(yscrollcommand=vsb.set, xscrollcommand=hsb.set)
        self.tree.grid(row=0, column=0, sticky="nsew")
        vsb.grid(row=0, column=1, sticky="ns")
        hsb.grid(row=1, column=0, sticky="ew")
        box.rowconfigure(0, weight=1)
        box.columnconfigure(0, weight=1)
        self.tree.tag_configure("ERROR", background="#4a1f24", foreground="#ffd0d0")
        self.tree.tag_configure("WARN", background="#4a3a12", foreground="#ffe9b0")
        self.tree.bind("<<TreeviewSelect>>", self.on_select)
        self.tree.bind("<Configure>", lambda _e: self.after(250, self.rewrap))
        self.tree.bind("<Control-a>", self.select_everything)
        self.tree.bind("<Double-1>", self.on_open)
        self.tree.bind("<ButtonRelease-1>", self.on_click)
        self.tree.bind("<Motion>", self.on_motion)
        for b in ("<Button-3>", "<Button-2>") if sys.platform == "darwin" else ("<Button-3>",):
            self.tree.bind(b, self.on_menu)
        self.wtip = ToolTip(self.tree, self._where_tip, delay=450)

        self.detail = tk.Text(self, height=7, wrap="word", **TEXT_OPTS)
        self.detail.pack(fill="x", padx=12, pady=(0, 6))
        self.detail.configure(state="disabled")
        bf = tk.Frame(self, bg=BG)
        bf.pack(fill="x", padx=12, pady=(0, 10))
        self.btns = []
        for text, cmd, hint in (
                ("Go to item", self.on_open, "Open the module / weapon / text this problem is about in the editor."),
                ("View file at line", lambda: self.open_locs(self._selected(), None, "view"),
                 "Show the file inside this program, scrolled to the line and highlighted."),
                ("Open in editor app", lambda: self.open_locs(self._selected(), None, "ext"),
                 "Open the file in Notepad++ / VS Code (at the line) or your default app."),
                ("Show in folder", lambda: self.open_locs(self._selected(), None, "dir"), "Show the file in your file manager.")):
            b = ttk.Button(bf, text=text, command=cmd)
            b.pack(side="left", padx=(0, 6))
            tip(b, hint)
            self.btns.append(b)
        self.b_fix = ttk.Button(bf, text="Auto-fix this", style="Save.TButton", command=self.fix_selected)
        self.b_fix.pack(side="left", padx=(12, 6))
        tip(self.b_fix, "Apply the suggested fix to the selected row(s).")
        self.b_ign = ttk.Button(bf, text="Ignore", command=self.ignore_selected)
        self.b_ign.pack(side="left", padx=(0, 6))
        tip(self.b_ign, "Hide the selected problem(s) from now on (harmless warnings, base-game quirks ...). "
                        "Remembered for this mod; the 'Ignored' filter shows them again.")
        self.ignored = []
        self.scanned = False
        self.summary["text"] = "Not checked yet - the check runs when you open this tab (it takes a few seconds on a big mod), or press Rescan."

    def ensure(self):
        """The health check is slow on a big mod, so it runs the first time this tab is opened (not while the editor starts)."""
        if not self.scanned:
            self.summary["text"] = "Checking the mod…"
            self.update_idletasks()
            self.scan()

    # ---- scanning
    def _probe(self, path):
        """Can this image really be opened? (cached per file + modification time; gives up after a few seconds per scan)"""
        try:
            key = (str(path), Path(path).stat().st_mtime)
        except OSError:
            return "file not readable"
        if key in self._probe_cache:
            return self._probe_cache[key]
        if time.time() > self._probe_deadline:
            return None
        try:
            load_image(path, 24)
            err = None
        except Exception as e:
            err = "%s: %s" % (type(e).__name__, e)
        self._probe_cache[key] = err
        return err

    def scan(self):
        proj = self.app.proj
        proj._icons.clear()                       # forget cached "not found" results so new files are noticed
        proj._tex = None
        proj._any = None
        proj.reload_log()                         # a newer blackbox.log (the game was run again) is picked up here
        proj.icon_probe = self._probe
        self._probe_deadline = time.time() + 8.0
        self.scanned = True
        self.all_issues = diagnose(proj)
        self._split()
        self.populate()
        self.app.update_debug_tab()

    def _split(self):
        proj = self.app.proj
        ign = set(proj.settings.get("ignored", []))
        self.issues = [i for i in self.all_issues if issue_key(i) not in ign]
        self.ignored = [i for i in self.all_issues if issue_key(i) in ign]
        self.counts = {s: sum(1 for i in self.issues if i.sev == s) for s in ("ERROR", "WARN", "INFO")}
        self.cat_cb["values"] = ["All"] + sorted({i.cat for i in self.all_issues})
        if self.cat.get() not in self.cat_cb["values"]:
            self.cat.set("All")
        nfix = sum(1 for i in self.issues if i.fix)
        self.btn_all["text"] = "Auto-fix all (%d)" % nfix
        self.btn_all.state(["!disabled"] if nfix else ["disabled"])
        self.summary["text"] = "✖ %d errors      ▲ %d warnings      ● %d notes      ⚙ %d auto-fixable      🚫 %d ignored" % (
            self.counts["ERROR"], self.counts["WARN"], self.counts["INFO"], nfix, len(self.ignored))
        lg = proj.log
        if lg:
            when = lg.started.strftime("%Y-%m-%d %H:%M") + " UTC" if lg.started else "unknown time"
            self.logline["text"] = "Game log:  %s   ·   run at %s   ·   %s   ·   game folder: %s" % (
                lg.path, when, "exited normally" if lg.exited_normally else "DID NOT EXIT NORMALLY",
                proj.game_dir or lg.game_dir or "?")
            self.logline["fg"] = DIM if lg.exited_normally else "#ff8a8a"
        else:
            self.logline["text"] = "Game log:  none found  -  run the game once, then press Rescan (or pick it with 'Game log…')"
            self.logline["fg"] = DIM

    def check_log(self):
        """Called when this tab is shown: if the game has been run again, read the new log."""
        if self.app.proj.reload_log():
            self.scan()
            self.app.say("blackbox.log has changed - the Debug tab now shows the latest run.")

    def pick_log(self):
        proj = self.app.proj
        start = proj.log_path.parent if proj.log_path else (proj.game_dir or proj.root)
        p = filedialog.askopenfilename(title="Pick the game's blackbox.log", initialdir=str(start),
                                       filetypes=[("Game log", "*.log"), ("All files", "*.*")])
        if p:
            proj.reload_log(p)
            self.scan()

    def add_texture_dir(self):
        proj = self.app.proj
        start = (proj.game_dir / "Content" / "Textures") if proj.game_dir and (proj.game_dir / "Content" / "Textures").is_dir() \
            else (proj.game_dir or proj.root)
        d = filedialog.askdirectory(title="Pick a folder that contains textures (e.g. <game>\\Content\\Textures)",
                                    initialdir=str(start))
        if not d:
            return
        extra = proj.settings.setdefault("extra_texture_dirs", [])
        if d not in extra:
            extra.append(d)
        proj.save_settings()
        proj.setup_dirs()
        self.app.icons_changed()
        self.scan()
        self.app.say("Texture folder added: %s" % d)

    def ignore_selected(self):
        sel = self._selected_all()
        if not sel:
            return
        proj = self.app.proj
        ign = proj.settings.setdefault("ignored", [])
        un = self.sev.get() == "Ignored"
        for i in sel:
            k = issue_key(i)
            if un and k in ign:
                ign.remove(k)
            elif not un and k not in ign:
                ign.append(k)
        proj.save_settings()
        self._split()
        self.populate()
        self.app.update_debug_tab()
        self.app.say("%d problem(s) %s." % (len(sel), "un-ignored" if un else "ignored (use the 'Ignored' filter to see them)"))

    WRAPPED = ("cat", "item", "detail", "where", "fix")

    def widths(self):
        try:
            return tuple(int(self.tree.column(c, "width")) for c in self.WRAPPED)
        except Exception:
            return (220, 200, 520, 330, 260)

    def rewrap(self):
        """Wrap again after the window or a column was resized (only when a column moved by more than a few letters)."""
        w = self.widths()
        if self._wrapw is not None and all(abs(a - b) < 24 for a, b in zip(w, self._wrapw)):
            return
        if not self.shown:
            return
        try:
            sel, y = self.tree.selection(), self.tree.yview()[0]
            self.populate()
            self.tree.selection_set(sel)
            self.tree.yview_moveto(y)
        except Exception:
            pass

    @staticmethod
    def two_lines(text, px):
        """The text broken into at most two lines that fit a column `px` wide (the rest is cut with …; the full text is in the box below)."""
        n = max(10, int(px / 7.3))
        lines = textwrap.wrap(re.sub(r"\s+", " ", text or "").strip(), n, break_long_words=True) or [""]
        if len(lines) > 2:
            lines = [lines[0], lines[1][:max(0, n - 1)] + "…"]
        return "\n".join(lines)

    def populate(self):
        sev, cat, q = self.sev.get(), self.cat.get(), self.q.get().lower().strip()
        self.shown = []
        self.b_ign["text"] = "Stop ignoring" if sev == "Ignored" else "Ignore"
        for i in (self.ignored if sev == "Ignored" else self.issues):
            if sev == "Errors" and i.sev != "ERROR":
                continue
            if sev == "Errors + warnings" and i.sev == "INFO":
                continue
            if sev == "Fixable" and not i.fix:
                continue
            if sev == "Game log only" and not i.cat.startswith("Game log"):
                continue
            if sev == "Game log errors" and not (i.cat.startswith("Game log") and i.sev == "ERROR"):
                continue
            if cat != "All" and i.cat != cat:
                continue
            if q and q not in (i.cat + " " + i.item + " " + i.detail + " " + i.where).lower():
                continue
            self.shown.append(i)
        self.tree.delete(*self.tree.get_children())
        self._wrapw = wd = self.widths()
        for n, i in enumerate(self.shown):
            self.tree.insert("", "end", iid=str(n), tags=(i.sev,) if i.sev != "INFO" else (),
                             values=(self.SEVS[i.sev], self.two_lines(i.cat, wd[0]), self.two_lines(i.item, wd[1]), self.two_lines(i.detail, wd[2]),
                                     self.two_lines(i.where, wd[3]), self.two_lines(("⚙ " + i.fix.label) if i.fix else "", wd[4])))
        self.count["text"] = "%d of %d shown" % (len(self.shown), len(self.ignored if sev == "Ignored" else self.issues))
        self._set_detail("")
        self._buttons(None)

    def _set_detail(self, text):
        self.detail.configure(state="normal")
        self.detail.delete("1.0", "end")
        self.detail.insert("1.0", text)
        self.detail.configure(state="disabled")

    def _selected_all(self):
        return [self.shown[int(s)] for s in self.tree.selection() if int(s) < len(self.shown)]

    def _selected(self):
        sel = self._selected_all()
        return sel[0] if sel else None

    def _buttons(self, i):
        for b in self.btns[1:]:
            b.state(["!disabled"] if i and i.locs else ["disabled"])
        self.btns[0].state(["!disabled"] if i and i.ref else ["disabled"])
        self.b_fix.state(["!disabled"] if any(x.fix for x in self._selected_all()) else ["disabled"])
        self.b_ign.state(["!disabled"] if self._selected_all() else ["disabled"])

    def on_select(self, _e=None):
        i = self._selected()
        self._buttons(i)
        if i:
            locs = "\n".join("   • " + where_text(self.app.proj, [l]) for l in i.locs) or "   -"
            self._set_detail("%s   ·   %s\n\n%s\n\nWhere:\n%s\n\nWhat to do:  %s%s"
                             % (i.cat, i.item, i.detail, locs, i.hint or "-",
                                ("\n\nAuto-fix:  " + i.fix.label) if i.fix else ""))

    def on_open(self, _e=None):
        i = self._selected()
        if i and i.ref:
            self.app.debug_goto(i.ref)

    def ask_ai(self):
        i = self._selected()
        if not i:
            messagebox.showinfo("Ask an AI", "Select a finding first.")
            return
        proj = self.app.proj
        facts = ["Editor: StarDrive Balance Editor %s, Python %s" % (VERSION, sys.version.split()[0]),
                 "Finding: %s - %s" % (i.cat, i.item), "Severity: %s" % i.sev, "Detail: %s" % i.detail,
                 "Where: " + "; ".join(where_text(proj, [l]) for l in i.locs[:5]), "Editor's suggestion: %s" % (i.hint or "-")]
        tags = set(re.findall(r"<(\w+)>", i.item + " " + i.detail))
        for t in sorted(tags)[:3]:
            h = help_game(t)
            if h:
                facts.append("What the game's own code says about <%s>: %s" % (t, h))
        for loc in i.locs[:2]:                                  # the lines around the problem
            try:
                lines = Path(loc[0]).read_text(encoding="utf-8-sig", errors="replace").splitlines()
                n = max(1, int(loc[1]))
                facts.append("File %s around line %d:\n%s" % (Path(loc[0]).name, n, "\n".join(lines[max(0, n - 4):n + 3])))
            except Exception:
                pass

        def apply(text):
            fixes = []
            for ln in text.splitlines():
                m = re.match(r"\s*FIX\s+(.+?)\s*\|\s*<?(\w+)>?\s*\|\s*(.*?)\s*$", ln)
                if m and m.group(1).lower() != "none":
                    fixes.append((m.group(1).strip(), m.group(2), m.group(3)))
            if not fixes:
                messagebox.showinfo("Apply the fix", "No lines in the form  FIX <file name> | <Tag> | <new value>  were found in the answer.")
                return
            docs = {}
            for d in proj.all_docs():
                try:
                    docs.setdefault(d.path.name.lower(), []).append(d)
                except Exception:
                    pass
            where = {str(l[0]).lower() for l in i.locs}
            plan, bad = [], []
            for fname, tag, val in fixes:
                cands = docs.get(fname.lower(), [])
                # several folders can hold a file of the same name: prefer the one named in the finding, then one that has the tag
                d = next((c for c in cands if str(c.path).lower() in where), None) or next((c for c in cands if tag in c.cur), None) or (cands[0] if cands else None)
                if d is None:
                    bad.append("%s: no such file in the project" % fname)
                elif tag not in d.cur and not game_tag_info(tag):
                    bad.append("%s: <%s> is not a tag the game knows" % (fname, tag))
                else:
                    plan.append((d, tag, val))
            if not plan:
                messagebox.showwarning("Apply the fix", "Nothing could be applied:\n" + "\n".join(bad))
                return
            lst = "\n".join("%s:  <%s>  %s  ->  %s" % (d.path.name, t, short(d.get(t).strip(), 24) or "(empty)", short(v, 30)) for d, t, v in plan)
            if not messagebox.askyesno("Apply the fix", "Change these in the editor (nothing is written until you Save)?\n\n%s%s" % (lst, ("\n\nSkipped:\n" + "\n".join(bad)) if bad else "")):
                return
            for d, t, v in plan:
                ok, msg = try_set(d, t, v)
                if msg:
                    messagebox.showwarning("Not applied", "%s <%s>: %s" % (d.path.name, t, msg))
            self.app.refresh()
            self.app.say("AI fix applied to %d value(s). Check it, then Save (Ctrl+S)." % len(plan))
        rules = ["Rules:", "- Explain in plain words what the problem is and why it matters in the game. Be concrete and short.",
                 "- Then, only if a value in a file must change, give each change on its own line in exactly this form:",
                 "  FIX <file name> | <TagName> | <new value>",
                 "- If nothing in the files should change (for example a code error in the editor), write exactly: FIX none",
                 "- Do not invent tags: use only tags that appear above or that the game's own comment names."]
        d = AiTextDialog(self, "Ask an AI", "Explain this finding from a StarDrive mod checker and say how to fix it.", "\n".join(facts), (), apply,
                         "Apply the FIX lines…", rules=rules)
        self.wait_window(d)

    # ---- file links
    def _cell_col(self, ev):
        if self.tree.identify_region(ev.x, ev.y) != "cell":
            return None, None
        return self.tree.identify_row(ev.y), self.tree.identify_column(ev.x)

    def on_click(self, ev):
        iid, col = self._cell_col(ev)
        if iid and col == "#5" and int(iid) < len(self.shown) and len(self.tree.selection()) <= 1:
            self.open_locs(self.shown[int(iid)], ev, "view")

    def on_motion(self, ev):
        iid, col = self._cell_col(ev)
        link = bool(iid and col == "#5" and int(iid) < len(self.shown) and self.shown[int(iid)].locs)
        self.tree.configure(cursor="hand2" if link else "")
        key = (iid, col)
        if key != getattr(self, "_mk", None):
            self._mk = key
            self.wtip.arm()

    def _where_tip(self):
        x = self.tree.winfo_pointerx() - self.tree.winfo_rootx()
        y = self.tree.winfo_pointery() - self.tree.winfo_rooty()
        iid, col = self.tree.identify_row(y), self.tree.identify_column(x)
        if not iid or int(iid) >= len(self.shown) or self.tree.identify_region(x, y) != "cell":
            return ""
        i = self.shown[int(iid)]
        if col == "#5" and i.locs:
            return "Click to open the file at this line.\nRight-click for other positions / external editor."
        if col == "#6" and i.fix:
            return i.fix.label
        if col == "#4":
            return i.detail
        return ""

    def open_locs(self, i, ev=None, mode="view"):
        if not i or not i.locs:
            self.app.say("This problem is not tied to a file position.")
            return
        act = {"view": self.app.view_file, "ext": self.app.open_external,
               "dir": lambda p, ln: self.app.show_in_folder(p)}[mode]
        if len(i.locs) == 1:
            act(*i.locs[0])
            return
        m = tk.Menu(self, tearoff=0, **MENU_OPTS)
        for p, ln in i.locs[:25]:
            m.add_command(label=where_text(self.app.proj, [(p, ln)]), command=lambda p=p, ln=ln: act(p, ln))
        x, y = (ev.x_root, ev.y_root) if ev else (self.winfo_pointerx(), self.winfo_pointery())
        try:
            m.tk_popup(x, y)
        finally:
            m.grab_release()

    def on_menu(self, ev):
        iid, _col = self._cell_col(ev)
        if not iid or int(iid) >= len(self.shown):
            return
        if iid not in self.tree.selection():
            self.tree.selection_set(iid)
        i = self.shown[int(iid)]
        m = tk.Menu(self, tearoff=0, **MENU_OPTS)
        for p, ln in i.locs[:8]:
            w = where_text(self.app.proj, [(p, ln)])
            m.add_command(label="View   " + w, command=lambda p=p, ln=ln: self.app.view_file(p, ln))
        for p, ln in i.locs[:3]:
            m.add_command(label="Open in editor app   " + where_text(self.app.proj, [(p, ln)]),
                          command=lambda p=p, ln=ln: self.app.open_external(p, ln))
        if i.locs:
            m.add_command(label="Show in folder", command=lambda: self.app.show_in_folder(i.locs[0][0]))
            m.add_separator()
        m.add_command(label="Go to item in the editor", command=self.on_open, state="normal" if i.ref else "disabled")
        m.add_command(label="Auto-fix: " + clip_text(i.fix.label, 60) if i.fix else "Auto-fix (none available)",
                      command=self.fix_selected, state="normal" if i.fix else "disabled")
        m.add_command(label="Stop ignoring this" if self.sev.get() == "Ignored" else "Ignore this problem",
                      command=self.ignore_selected)
        m.add_separator()
        m.add_command(label="Copy this row", command=lambda: (self.clipboard_clear(), self.clipboard_append(
            "[%s] %s | %s | %s | %s" % (i.sev, i.cat, i.item, i.detail, i.where))))
        popup(m, ev)

    # ---- auto-fix
    def fix_selected(self):
        sel = [i for i in self._selected_all() if i.fix]
        if not sel:
            self.app.say("Nothing selected has an auto-fix. Pick a row with a ⚙ in the Auto-fix column.")
            return
        self.run_fixes(sel)

    def show_game_errors(self):
        self.ensure()
        self.sev.set("Game log errors")
        self.cat.set("All")
        self.q.set("")
        self.populate()
        n = len(self.shown)
        self.app.say("%d error(s) in the game's blackbox.log%s." % (n, "" if n else " - the log has no errors (or the editor has not found it: press 'Game log…')"))

    def select_fixable(self):
        ids = [str(n) for n, i in enumerate(self.shown) if i.fix]
        try:
            self.tree.selection_set(ids)
        except Exception:
            pass
        self.app.say("%d row(s) with an auto-fix selected - press 'Auto-fix selected' to apply them (you see the list first)." % len(ids))

    def select_everything(self, _e=None):
        try:
            self.tree.selection_set([str(n) for n in range(len(self.shown))])
        except Exception:
            pass
        return "break"

    def fix_all(self):
        todo = [i for i in self.issues if i.fix and not i.fix.risky]
        skipped = sum(1 for i in self.issues if i.fix and i.fix.risky)
        if skipped:
            messagebox.showinfo("Fix all", "%d fix(es) are left out of Fix all because they need your decision (a close-match guess, a choice between two "
                                "designs with the same name, or a text Id that may really live in the base game). Use the row's own fix button for those." % skipped)
        self.run_fixes(todo)

    def run_fixes(self, issues):
        fixes, seen = [], set()
        for i in issues:
            if i.fix.label not in seen:
                seen.add(i.fix.label)
                fixes.append(i.fix)
        if not fixes or not self.app.confirm_fixes(fixes):
            return
        done, errs = 0, []
        for fx in fixes:
            try:
                if fx.apply(self.app.proj) is not False:
                    done += 1
            except Exception as e:
                errs.append("%s: %s" % (fx.label, e))
        self.app.refresh()
        self.scan()
        if errs:
            messagebox.showwarning("Some fixes failed", "\n".join(errs))
        self.app.say("Auto-fix applied %d change(s) in the editor. Review them, then press Save (Ctrl+S) - "
                     "'Revert changes' undoes them." % done)

    # ---- reports
    def _report_lines(self):
        return ["[%s] %s | %s | %s | %s" % (i.sev, i.cat, i.item, i.detail, i.where) for i in self.issues]

    def copy_log(self):
        p = self.app.proj
        L = ["StarDrive Balance Editor %s  ·  Python %s  ·  Pillow %s" % (VERSION, sys.version.split()[0], "yes" if Image else "no"),
             "mod folder: %s" % p.root, "game folders: %s" % ", ".join(str(b) for b in getattr(p, "base_roots", [])),
             "modules %d (+%d base) · weapons %d · techs %d · hulls %d (+%d base, %d outside Hulls) · designs %d" % (
                 len(p.modules), len(p.base_modules), len(p.weapons), len(p.techs), len(p.hulls), len(p.base_hulls),
                 getattr(p, "deep_hulls", 0), len(p.designs or []) if getattr(p, "designs", None) is not None else 0),
             "base folders searched: " + "; ".join("%s=%s" % (k, v[1]) for k, v in getattr(p, "base_found", {}).items()),
             "", "--- editor errors (%d) ---" % len(ERRLOG)]
        for tm, where, txt in ERRLOG[-20:]:
            L += ["[%s] %s" % (tm, where), txt, ""]
        L += ["--- unreadable / skipped files (%d) ---" % len(p.errors)] + list(p.errors[:30])
        L += ["", "--- first Debug rows (%d total) ---" % len(self.issues)] + self._report_lines()[:60]
        self.clipboard_clear()
        self.clipboard_append("\n".join(L))
        self.app.say("Error log copied (%d lines). Paste it into the chat." % len(L))

    def copy(self):
        self.clipboard_clear()
        self.clipboard_append("\n".join(self._report_lines()))
        self.app.say("Copied %d issues to the clipboard." % len(self.issues))

    def export(self):
        root = self.app.proj.root / BACKUP_DIR
        try:
            root.mkdir(parents=True, exist_ok=True)
        except Exception:
            pass
        path = filedialog.asksaveasfilename(title="Save debug report", defaultextension=".csv",
                                            initialdir=str(root), initialfile="debug_report.csv",
                                            filetypes=[("CSV", "*.csv")])
        if not path:
            return
        with open(path, "w", newline="", encoding="utf-8-sig") as f:
            w = csv.writer(f)
            w.writerow(["severity", "problem", "item", "detail", "where", "what to do", "auto-fix"])
            for i in self.issues:
                w.writerow([i.sev, i.cat, i.item, i.detail, i.where, i.hint, i.fix.label if i.fix else ""])
        self.app.say("Saved %d issues to %s" % (len(self.issues), path))


class FileViewer(tk.Toplevel):
    """Read-only view of a file with line numbers, opened at - and highlighting - one line."""

    def __init__(self, app, path, line=1):
        super().__init__(app.tk)
        self.app, self.path, self.line = app, Path(path), max(1, int(line))
        self.configure(bg=BG)
        try:
            rel = self.path.relative_to(app.proj.root)
        except Exception:
            rel = self.path
        self.title("%s  -  line %d" % (rel, self.line))
        self.geometry("1050x680")
        dark_titlebar(self)
        mono = ("Consolas", 10)
        top = tk.Frame(self, bg=BG)
        top.pack(fill="x", padx=10, pady=8)
        tk.Label(top, text=str(self.path), bg=BG, fg=PEACH, anchor="w").pack(side="left")
        b = ttk.Button(top, text="Open in editor app", command=lambda: app.open_external(self.path, self.line))
        b.pack(side="right", padx=3)
        tip(b, "Open the file in Notepad++ / VS Code (jumps to the line) or the default app.")
        b = ttk.Button(top, text="Show in folder", command=lambda: app.show_in_folder(self.path))
        b.pack(side="right", padx=3)
        tip(b, "Show the file in your file manager.")
        self.goto = tk.StringVar(value=str(self.line))
        ge = ttk.Entry(top, textvariable=self.goto, width=7)
        ge.pack(side="right", padx=(3, 10))
        ge.bind("<Return>", lambda _e: self.jump())
        tk.Label(top, text="Go to line", bg=BG, fg=DIM).pack(side="right")
        try:
            text, _bom, _enc = read_file(self.path)
        except Exception as e:
            text = "Could not read the file:\n%s" % e
        text = text.replace("\r\n", "\n")
        self.n = text.count("\n") + 1
        body = tk.Frame(self, bg=BG)
        body.pack(fill="both", expand=True, padx=10)
        self.gut = tk.Text(body, width=6, wrap="none", bg=PANEL, fg=DIM, relief="flat", highlightthickness=0,
                           padx=6, pady=6, font=mono, takefocus=0, cursor="arrow")
        self.txt = tk.Text(body, wrap="none", font=mono, **TEXT_OPTS)
        self.vsb = ttk.Scrollbar(body, orient="vertical", command=self._yview)
        hsb = ttk.Scrollbar(body, orient="horizontal", command=self.txt.xview)
        self.txt.configure(yscrollcommand=self._ysb, xscrollcommand=hsb.set)
        self.gut.grid(row=0, column=0, sticky="ns")
        self.txt.grid(row=0, column=1, sticky="nsew")
        self.vsb.grid(row=0, column=2, sticky="ns")
        hsb.grid(row=1, column=1, sticky="ew")
        body.rowconfigure(0, weight=1)
        body.columnconfigure(1, weight=1)
        self.txt.insert("1.0", text)
        self.gut.insert("1.0", "\n".join(str(i + 1) for i in range(self.n)))
        self.gut.tag_configure("r", justify="right")
        self.gut.tag_add("r", "1.0", "end")
        self.txt.tag_configure("hit", background="#5a4300", foreground="#fff0c0")
        self.gut.tag_configure("ghit", foreground=ORANGE, background="#5a4300")
        self.txt.configure(state="disabled")
        self.gut.configure(state="disabled")
        self.txt.bind("<Button-1>", lambda _e: self.txt.focus_set(), add="+")
        self.gut.bind("<MouseWheel>", lambda e: (self.txt.yview_scroll(-3 if e.delta > 0 else 3, "units"), "break")[1])
        tk.Label(self, text="Shows the file as it is on disk (unsaved edits are not included). Edit values in the editor, "
                 "or use 'Open in editor app' for raw edits.", bg=BG, fg=DIM, anchor="w").pack(fill="x", padx=10, pady=6)
        self.after(50, self.jump)

    def _yview(self, *a):
        self.txt.yview(*a)
        self.gut.yview(*a)

    def _ysb(self, a, b):
        self.vsb.set(a, b)
        self.gut.yview_moveto(a)

    def jump(self):
        try:
            ln = max(1, min(self.n, int(self.goto.get())))
        except ValueError:
            return
        self.line = ln
        self.txt.tag_remove("hit", "1.0", "end")
        self.gut.tag_remove("ghit", "1.0", "end")
        self.txt.tag_add("hit", "%d.0" % ln, "%d.end+1c" % ln)
        self.gut.tag_add("ghit", "%d.0" % ln, "%d.end" % ln)
        self.txt.yview_moveto(max(0.0, (ln - 1 - 8) / float(self.n)))


# ================================================================ research tree
def center_on(win, parent):
    try:
        win.update_idletasks()
        top = parent.winfo_toplevel()
        x = top.winfo_rootx() + max(20, (top.winfo_width() - win.winfo_reqwidth()) // 2)
        y = top.winfo_rooty() + max(20, (top.winfo_height() - win.winfo_reqheight()) // 3)
        win.geometry("+%d+%d" % (x, y))
    except Exception:
        pass


TIP_TECH_UID = ("UID = the tech's unique id. The game finds it by this name, other techs link to it with it (LeadsTo), and it is "
                "also the xml file name. Letters, digits and _ only; it can't be changed later without editing every link to it.")
TIP_MOD_UID = ("UID = the module's unique id. Techs unlock it by this name (ModuleUID), ship designs list it in ModuleUIDs, and it is also "
               "the xml file name. Letters, digits and _ only; changing it later breaks those links.")


TREE_GEO = (290, 92, 70, 22, 26)            # node width, height, gap between columns, gap between rows, margin


def paint_tree(cv, proj, cat, sel=None, plus=True, tile_text="＋ New branch", tile_sel=False, icon_fn=None, zoom=1.0, fade=None):
    """Draw one category of the research tree on a canvas. Tags: n<i> = tech i, a<i> = its + (follow-on) button, u<i> = its
    'unlock a module' button, nb = the new-branch tile. icon_fn(tech, main_size, strip_size) -> {'main', 'strip', 'more'} puts the
    tech / ship icon on the left and the icons of what it unlocks on the right. Returns the list of techs in tag order."""
    z = max(0.25, float(zoom))
    NW, NH, GX, GY, P = [int(v * z) for v in TREE_GEO]
    f = lambda pt: max(5, int(round(pt * z)))
    msz, ssz = max(12, int(64 * z)), max(8, int(28 * z))
    cv.delete("all")
    nodes, edges = tech_layout(proj, cat) if cat else ([], [])
    items = [t for t, _c, _r in nodes]
    idx = {id(t): i for i, t in enumerate(items)}
    pos = {id(t): (P + c * (NW + GX), P + r * (NH + GY)) for t, c, r in nodes}
    for a, b in edges:
        (x1, y1), (x2, y2) = pos[id(a)], pos[id(b)]
        xm = x2 - GX // 2 + int(8 * z)
        cv.create_line(x1 + NW, y1 + NH // 2, xm, y1 + NH // 2, xm, y2 + NH // 2, x2, y2 + NH // 2, fill="#4a5578", width=max(1, int(2 * z)))
    last = -1
    for t, c, r in nodes:
        x, y = pos[id(t)]
        tag = "n%d" % idx[id(t)]
        dirty, chosen = t.has_changes(), t is sel
        dim = bool(fade and fade(t))                                      # a tech that does not apply to the chosen race: drawn dark and grey
        cv.create_rectangle(x, y, x + NW, y + NH, fill=("#0c0e14" if dim else (DIRTY_BG if dirty else PANEL2)), width=3 if chosen else 1,
                            outline=ORANGE if chosen else (EDITED_FG if dirty else EDGE), tags=(tag,), **({"dash": (3, 3)} if dim else {}))
        ic = icon_fn(t, msz, ssz) if icon_fn else None
        tx = x + int(10 * z)
        if ic and ic.get("main") is not None:
            cv.create_image(x + int(8 * z), y + (NH - msz) // 2, image=ic["main"], anchor="nw", tags=("i%d" % idx[id(t)], tag))
            tx = x + int(80 * z)
        strip = (ic or {}).get("strip") or []
        for k, img in enumerate(strip[:4]):
            cv.create_image(x + NW - int(68 * z) + (k % 2) * int(32 * z), y + int(5 * z) + (k // 2) * int(31 * z), image=img, anchor="nw", tags=(tag,))
        cv.create_text(tx, y + int(8 * z), anchor="nw", text=clip_text(proj.tech_name(t), 46), fill=("#5a6078" if dim else FG),
                       width=max(30, (x + NW - (int(74 * z) if strip else int(10 * z))) - tx), font=("Segoe UI", f(9), "bold"), tags=(tag,))
        n = len({u.lower() for u, _ty in t.unlocks}) + len(t.hulls) + len(t.buildings)
        cv.create_text(tx, y + NH - int(8 * z), anchor="sw", text="%s  ·  %d unlock%s%s" % (t.get("Cost"), n, "" if n == 1 else "s", ("  ·  ⬆ %d levels" % t.max_level) if t.max_level > 1 else ""), fill=BLUE,
                       font=("Segoe UI", f(8)), tags=(tag,))
        ub, ubh = "u%d" % idx[id(t)], max(12, int(20 * z))
        ux = x + NW - int(72 * z)                                         # under the icon strip, a little wider and taller than before
        cv.create_rectangle(ux, y + NH - ubh - int(5 * z), x + NW - int(6 * z), y + NH - int(5 * z), fill=PANEL, outline=ORANGE, width=2, tags=(ub,))
        cv.create_text((ux + x + NW - int(6 * z)) // 2, y + NH - int(5 * z) - ubh // 2, text="＋ unlock", fill=ORANGE, font=("Segoe UI", f(8), "bold"), tags=(ub,))
        if (ic or {}).get("more"):
            cv.create_text(ux - int(4 * z), y + NH - int(8 * z), anchor="se", text="+%d" % ic["more"], fill=DIM, font=("Segoe UI", f(8)), tags=(tag,))
        if plus:
            bx, by, ab, rr = x + NW + int(16 * z), y + NH // 2, "a%d" % idx[id(t)], max(7, int(11 * z))
            cv.create_oval(bx - rr, by - rr, bx + rr, by + rr, fill=PANEL, outline=ORANGE, tags=(ab,))
            lw = max(1, int(2 * z))                                       # a Y: two arms meeting in a stem (a branch)
            cv.create_line(bx, by + int(rr * 0.65), bx, by + int(rr * 0.05), fill=ORANGE, width=lw, tags=(ab,))
            cv.create_line(bx - int(rr * 0.55), by - int(rr * 0.6), bx, by + int(rr * 0.05), bx + int(rr * 0.55), by - int(rr * 0.6), fill=ORANGE, width=lw, tags=(ab,))
        last = max(last, r)
    ny = P + (last + 1) * (NH + GY)
    cv.create_rectangle(P, ny, P + NW, ny + NH, outline=ORANGE, width=3 if tile_sel else 1, dash=(4, 3), tags=("nb",))
    cv.create_text(P + NW // 2, ny + NH // 2, text=tile_text, fill=ORANGE, font=("Segoe UI", f(10), "bold"), tags=("nb",))
    bb = cv.bbox("all")
    if bb:
        cv.configure(scrollregion=(0, 0, bb[2] + P, bb[3] + P))
    return items


def tree_extent(proj, cat, zoom=1.0):
    """(width, height) in pixels the tree of a category needs at this zoom."""
    NW, NH, GX, GY, P = [int(v * zoom) for v in TREE_GEO]
    nodes, _e = tech_layout(proj, cat) if cat else ([], [])
    cols = max([c for _t, c, _r in nodes] or [0]) + 1
    rows = max([r for _t, _c, r in nodes] or [0]) + 2
    return 2 * P + cols * (NW + GX), 2 * P + rows * (NH + GY)


def tree_hit(cv, items):
    """What the canvas item under the pointer is: ('nb', None), ('n' or 'a', tech) or (None, None)."""
    it = cv.find_withtag("current")
    for tg in (cv.gettags(it[0]) if it else ()):
        if tg == "nb":
            return "nb", None
        if tg[:1] in "naui" and tg[1:].isdigit() and int(tg[1:]) < len(items):
            return tg[0], items[int(tg[1:])]
    return None, None


class PlaceTechDialog(_Dialog):
    """Step 1 of a new tech: where does it go? Pick a category, then the tech it follows (or start a new branch)."""

    def __init__(self, master, proj, cat, parent=None, title=None, nxt="Next: name it  →"):
        super().__init__(master, title or "New tech - step 1 of 2: where should it go?")
        self.proj, self.parent_tech, self.items, self.owner = proj, parent, [], master
        cats = proj.tech_categories()
        self.cat_var = tk.StringVar(value=proj.tech_category(parent) if parent is not None else (cat if cat in cats else (cats[0] if cats else "")))
        tk.Label(self, bg=PANEL, fg=PEACH, font=("Segoe UI", 10, "bold"), anchor="w", justify="left", wraplength=720,
                 text="Click the tech the new one should come AFTER, or the dashed tile to start a new branch. "
                      "Pick the category first; the next step asks for the name, cost and so on."
                 ).grid(row=0, column=0, columnspan=2, sticky="w", padx=14, pady=(12, 6))
        bar = tk.Frame(self, bg=PANEL)
        bar.grid(row=1, column=0, columnspan=2, sticky="we", padx=14)
        tk.Label(bar, text="Category", bg=PANEL, fg=FG).pack(side="left")
        self.prev_cat = self.cat_var.get()
        self.cb = cb = ttk.Combobox(bar, textvariable=self.cat_var, values=cats + [self.NEWCAT], state="readonly", width=30)
        cb.pack(side="left", padx=8)
        tip(cb, "The line of research (Technology sub-folder) to add the tech to. The last entry creates a whole new line of research.")
        cb.bind("<<ComboboxSelected>>", lambda _e: self.pick_cat())
        self.cv = tk.Canvas(self, width=900, height=460, bg=BG, highlightthickness=1, highlightbackground=EDGE)
        vs = ttk.Scrollbar(self, orient="vertical", command=self.cv.yview)
        hs = ttk.Scrollbar(self, orient="horizontal", command=self.cv.xview)
        self.cv.configure(yscrollcommand=vs.set, xscrollcommand=hs.set)
        self.cv.grid(row=2, column=0, padx=(14, 0), pady=6, sticky="nsew")
        vs.grid(row=2, column=1, sticky="ns", padx=(0, 14))
        hs.grid(row=3, column=0, sticky="we", padx=(14, 0))
        self.cv.bind("<Button-1>", self.on_click)
        self.cv.bind("<MouseWheel>", lambda e: self.cv.yview_scroll(-3 if e.delta > 0 else 3, "units"))
        tip(self.cv, "Click the tech the new one should follow, or the dashed tile for a new branch.")
        self.info = tk.Label(self, bg=PANEL, fg=FG, anchor="w", justify="left", wraplength=720)
        self.info.grid(row=4, column=0, columnspan=2, sticky="w", padx=14, pady=4)
        bt = tk.Frame(self, bg=PANEL)
        bt.grid(row=5, column=0, columnspan=2, sticky="e", padx=14, pady=(4, 12))
        ttk.Button(bt, text="Cancel", command=self.destroy).pack(side="right", padx=(6, 0))
        ttk.Button(bt, text=nxt, command=self.ok).pack(side="right")
        self.draw()
        self.show()

    NEWCAT = "＋ Create new category…"

    def pick_cat(self):
        if self.cat_var.get() == self.NEWCAT:
            d = NewCategoryDialog(self, self.proj)
            self.wait_window(d)
            doc = d.result
            if doc is None:
                self.cat_var.set(self.prev_cat)
            else:
                self.cat_var.set(self.proj.tech_category(doc))
                self.cb["values"] = self.proj.tech_categories() + [self.NEWCAT]
                self.parent_tech = doc                          # the new line's head tech: the tech goes after it
                if hasattr(self.owner, "rail_sig"):
                    self.owner.rail_sig = None
                try:
                    self.owner.app.refresh()
                except Exception:
                    pass
                self.prev_cat = self.cat_var.get()
                self.draw()
                return
        self.prev_cat = self.cat_var.get()
        self.parent_tech = None
        self.draw()

    def draw(self):
        self.items = paint_tree(self.cv, self.proj, self.cat_var.get(), sel=self.parent_tech, plus=False,
                                tile_text="＋ New branch here", tile_sel=self.parent_tech is None,
                                icon_fn=getattr(self.owner, "node_icons", None), zoom=0.6)
        t = self.parent_tech
        if t is None:
            self.info["text"] = "The new tech will START A NEW BRANCH in '%s' (nothing leads to it)." % self.cat_var.get()
        else:
            n = len(t.leads)
            self.info["text"] = "The new tech will come AFTER '%s'%s" % (
                self.proj.tech_name(t), (" - it becomes another follow-on (that tech already leads to %d), so the tree forks there." % n) if n
                else " - the first follow-on of that tech.")

    def on_click(self, _e):
        kind, t = tree_hit(self.cv, self.items)
        if kind == "nb":
            self.parent_tech = None
        elif kind == "n":
            self.parent_tech = t
        else:
            return
        self.draw()

    def ok(self):
        self.result = (self.parent_tech, self.cat_var.get())
        self.destroy()


class BranchWizard(_Dialog):
    """Builds a branch one tech at a time: name / cost / type / text for a tech, it is created, then you choose what comes next: give it
    unlocks, add the next tech along the line, branch off an earlier tech of this wizard, or finish."""

    def __init__(self, master, proj, parent, cat):
        super().__init__(master, "Add new branch wizard")
        self.tree, self.proj, self.cat = master, proj, cat
        self.made, self.parent_tech, self.result = [], parent, []
        self.parent_first = parent
        self.page = tk.Frame(self, bg=PANEL)
        self.page.pack(fill="both", expand=True)
        self.form()
        self.show()

    def _clear(self):
        for c in self.page.winfo_children():
            c.destroy()

    def _uid_for(self, name):
        base = re.sub(r"[^A-Za-z0-9]+", "_", name).strip("_") or "Tech"
        uid, k = base, 2
        while uid.lower() in self.proj.tech_by_uid:
            uid, k = "%s_%d" % (base, k), k + 1
        return uid

    # ---- one tech
    def form(self):
        self._clear()
        P, par, n = self.page, self.parent_tech, len(self.made) + 1
        cost, ttype = 100, "ShipWeapons"
        if par is not None:
            try:
                cost = int(round(float(par.get("Cost") or 100) * 1.4 / 10.0) * 10)
            except ValueError:
                pass
            ttype = par.get("TechnologyType") or ttype
        name = "New Tech %d" % n
        self.v = {k: tk.StringVar(value=val) for k, val in (("name", name), ("uid", self._uid_for(name)), ("cost", str(cost)), ("type", ttype))}
        self.uid_edited = False
        tk.Label(P, bg=PANEL, fg=PEACH, font=("Segoe UI", 10, "bold"), anchor="w", justify="left", wraplength=520,
                 text="Tech %d   ·   category %s\n%s" % (n, self.cat, ("Comes after: %s  (%s)" % (self.proj.tech_name(par), par.uid)) if par is not None
                                                      else "Starts a new branch (no tech leads to it)")).grid(row=0, column=0, columnspan=2, sticky="w", padx=14, pady=(12, 6))
        rows = (("Name in game", "name", None, "The name the research screen shows. Stored in GameText.yaml as BB_Tech_<UID>_Name."),
                ("UID (file name)", "uid", None, TIP_TECH_UID),
                ("Cost", "cost", None, "Research points needed to learn this tech."),
                ("Type / icon", "type", sorted({t.get("TechnologyType") for t in self.proj.techs if t.get("TechnologyType")}),
                 "TechnologyType: the tech's group in the game (ShipWeapons, ShipDefense ...). A TechIcons_... name picks that picture."))
        for r, (lab, key, vals, hint) in enumerate(rows, 1):
            lb = tk.Label(P, text=lab, bg=PANEL, fg=FG, anchor="w")
            lb.grid(row=r, column=0, sticky="nw", padx=(14, 8), pady=4)
            tip(lb, hint)
            w = ttk.Combobox(P, textvariable=self.v[key], values=vals, width=44) if vals else ttk.Entry(P, textvariable=self.v[key], width=47)
            w.grid(row=r, column=1, sticky="we", padx=(0, 14), pady=4)
            tip(w, hint)
            if key == "name":
                w.focus_set()
                w.select_range(0, "end")
            if key == "uid":
                w.bind("<Key>", lambda _e: setattr(self, "uid_edited", True), add="+")
        self.v["name"].trace_add("write", lambda *_a: None if self.uid_edited else self.v["uid"].set(self._uid_for(self.v["name"].get())))
        tk.Label(P, text="Description", bg=PANEL, fg=FG, anchor="w").grid(row=5, column=0, sticky="nw", padx=(14, 8), pady=4)
        self.desc = tk.Text(P, width=46, height=4, wrap="word", **TEXT_OPTS)
        self.desc.grid(row=5, column=1, padx=(0, 14), pady=4)
        tip(self.desc, "The text shown when the tech is selected. Stored in GameText.yaml as BB_Tech_<UID>_Desc.")
        tk.Label(P, bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=520,
                 text="The tech is created when you press the button; you then choose what comes next (unlocks, the next tech, a branch, or finish). "
                      "Nothing is written to the files until you press Save, and Undo last change takes steps back.").grid(row=6, column=0, columnspan=2, sticky="w", padx=14, pady=4)
        bt = tk.Frame(P, bg=PANEL)
        bt.grid(row=7, column=0, columnspan=2, sticky="e", padx=14, pady=(4, 12))
        ttk.Button(bt, text="Cancel" if not self.made else "Back", command=self.destroy if not self.made else self.after_page).pack(side="right", padx=(6, 0))
        ttk.Button(bt, text="Add this tech", command=self.add).pack(side="right")
        self.bind("<Return>", lambda _e: self.add() if self.focus_get() is not self.desc else None)

    def add(self):
        v = {k: x.get() for k, x in self.v.items()}
        try:
            doc = self.proj.new_tech(v["uid"], self.cat, v["type"], v["cost"], v["name"], self.desc.get("1.0", "end").strip(), self.parent_tech)
        except ValueError as e:
            messagebox.showwarning("New tech", str(e), parent=self)
            return
        self.made.append(doc)
        self.result = list(self.made)
        self.last = doc
        self.after_page()

    # ---- what next?
    def after_page(self):
        self._clear()
        P, t = self.page, self.last
        tk.Label(P, bg=PANEL, fg=PEACH, font=("Segoe UI", 10, "bold"), anchor="w", justify="left", wraplength=520,
                 text="Created %s  (%s)" % (self.proj.tech_name(t), t.uid)).grid(row=0, column=0, sticky="w", padx=14, pady=(12, 2))
        lst = tk.Text(P, width=64, height=min(8, len(self.made) + 1), wrap="none", **TEXT_OPTS)
        lst.grid(row=1, column=0, sticky="we", padx=14, pady=4)
        for i, d in enumerate(self.made):
            par = next((m for m in self.made + ([self.parent_first] if getattr(self, "parent_first", None) else []) if d.uid in m.leads), None)
            lst.insert("end", "%2d.  %-30s  %-26s  after %s\n" % (i + 1, self.proj.tech_name(d), d.uid, par.uid if par is not None else "(its own branch start)"))
        lst.configure(state="disabled")
        tk.Label(P, text="What next?", bg=PANEL, fg=ORANGE, font=("Segoe UI", 9, "bold"), anchor="w").grid(row=2, column=0, sticky="w", padx=14, pady=(8, 2))
        bf = tk.Frame(P, bg=PANEL)
        bf.grid(row=3, column=0, sticky="we", padx=14, pady=(0, 4))
        for i, (txt, cmd, hint) in enumerate((
                ("Unlock something with this tech…", self.unlocks, "Give this tech a module, building or upgrade to unlock (the same menu as the tree's + unlock button)."),
                ("Next tech after this one  →", self.next_along, "Add the next tech of the line, coming after the one just made."),
                ("Branch off an earlier tech…", self.branch, "Add another tech after a different tech made in this wizard (or the one you started from), so the tree forks there."),
                ("Finish", self.destroy, "Close the wizard. Click any tech in the tree to carry on editing it."))):
            b = ttk.Button(bf, text=txt, command=cmd, width=32)
            b.grid(row=i // 2, column=i % 2, sticky="we", padx=(0, 6), pady=3)
            tip(b, hint)

    def unlocks(self):
        t = self.last
        try:
            self.grab_release()                                  # the unlock menu and its pickers need the window free
        except Exception:
            pass
        self.tree.insp_tech = t
        self.tree.unlock_add()

    def next_along(self):
        self.parent_tech = self.last
        self.form()

    def branch(self):
        pool = ([self.parent_first] if getattr(self, "parent_first", None) is not None else []) + self.made
        rows = [(d.uid, "%s   (%s)" % (self.proj.tech_name(d), d.uid)) for d in pool]
        dlg = PickDialog(self, "Branch off", "Add the next tech after which one?", rows)
        dlg.show()
        self.wait_window(dlg)
        if dlg.result:
            self.parent_tech = next((d for d in pool if d.uid == dlg.result[0]), self.last)
            self.form()


