def play_sound(proj, cue):
    """Play a separate sound file that matches the cue name. Returns a sentence saying what happened."""
    cue = (cue or "").strip()
    if not cue:
        return "Pick or type a sound name first."
    hits = proj.find_sound(cue)
    if not hits:
        bank = "The game keeps its sounds in wave banks (.xwb / .xsb), which this editor can't play" if proj.has_sound_banks() else \
            "The game's sound cues live in its own sound bank, which this editor can't play"
        return "'%s' is a sound cue name. No separate sound file called that was found in the mod or game folders. %s." % (cue, bank)
    p = hits[0]
    try:
        if sys.platform == "win32":
            if p.suffix.lower() == ".wav":
                import winsound
                winsound.PlaySound(str(p), winsound.SND_FILENAME | winsound.SND_ASYNC)
                return "Playing %s" % p.name
            os.startfile(str(p))                                 # other formats: the default player
            return "Opened %s in your default player" % p.name
        subprocess.Popen(["open" if sys.platform == "darwin" else "xdg-open", str(p)])
        return "Opened %s in your default player" % p.name
    except Exception as e:
        return "Could not play %s: %s" % (p.name, e)


def stop_sound():
    try:
        import winsound
        winsound.PlaySound(None, winsound.SND_PURGE)
    except Exception:
        pass


def module_tip(proj, m):
    """The text of the hover pop-up for a module: name, type, size, races, then every non-zero stat of the module and its weapon."""
    uid = (m.get("UID") or m.path.stem).strip()
    lines = ["%s   (%s)" % (module_name(proj, m), uid)]
    size = "%s x %s" % (m.get("XSize").strip() or "?", m.get("YSize").strip() or "?")
    lines.append("%s   ·   size %s" % (m.get("ModuleType").strip() or "-", size))
    try:
        races = sorted(proj.race_info().of.get(uid.lower(), []))
    except Exception:
        races = []
    if races:
        lines.append("Races: " + ", ".join(races))
    lines.append("")
    for label, v, _ed, _o, tag in module_stats(proj, m):
        if tag == "ModuleType":
            continue
        lines.append("%s: %s" % (label, v))
    if len(lines) <= 4:
        lines.append("(no stats set yet)")
    return "\n".join(lines)


# ---- AI helper: prompt packages you copy into ANY AI (Gemini, Claude, ChatGPT ...) and a way to bring the result back. Nothing is sent by the editor.
AI_GAME = ("StarDrive BB+ is a 2D top-down 4X space strategy game. This mod ('Star Trek') adds Star Trek style races, ships, weapons and technology.")
AI_FIT_MODES = ("Keep the whole picture", "Fill the size (crop the edges)")


def install_pillow(done):
    """Runs  python -m pip install pillow  in the background (needs internet). done(ok, text) is called from that thread when it ends."""
    import threading

    def work():
        try:
            r = subprocess.run([sys.executable, "-m", "pip", "install", "--user", "pillow"], capture_output=True, text=True, timeout=600,
                               creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
            out = (r.stdout or "") + (r.stderr or "")
            if r.returncode == 0:
                import importlib
                importlib.invalidate_caches()
                try:
                    from PIL import Image as _I, ImageTk as _T
                    globals()["Image"], globals()["ImageTk"] = _I, _T
                    done(True, out[-400:])
                    return
                except Exception as e:
                    out += "\nInstalled, but it could not be loaded yet: %s" % e
            done(False, out[-600:])
        except Exception as e:
            done(False, str(e))
    threading.Thread(target=work, daemon=True).start()


def png_size(path):
    """(width, height) of a .png read from its header - works without Pillow. None if it is not a PNG."""
    try:
        with open(path, "rb") as f:
            h = f.read(24)
        if h[:8] == b"\x89PNG\r\n\x1a\n":
            return struct.unpack(">II", h[16:24])
    except OSError:
        pass
    return None


def ai_sizes(proj, sub):
    """[(size, count)] commonest first of the pictures already in Textures\\<sub> (so a new one can match)."""
    c = {}
    for _stem, path, _o in proj.texture_choices(sub)[:120]:
        sz = None
        if Image:
            try:
                with Image.open(path) as im:
                    sz = im.size
            except Exception:
                sz = None
        if sz is None:
            sz = png_size(path)
        if sz:
            c[tuple(sz)] = c.get(tuple(sz), 0) + 1
    return sorted(c.items(), key=lambda kv: -kv[1])


def ai_about(proj, kind, obj):
    """A few lines about an item (module / weapon / tech / building), used in the prompts."""
    out = []
    try:
        if kind == "module":
            out.append("Name: %s" % module_name(proj, obj))
            mt = obj.get("ModuleType").strip()
            if mt:
                out.append("Module type: %s" % mt)
            d = obj.get("Description").strip()
            if d:
                out.append("Description: %s" % d[:300])
            w = proj.weapon_for(obj)
            if w is not None:
                tags = [t[4:] for t in w.cur if t.startswith("Tag_") and w.get(t).strip().lower() == "true"]
                out.append("It is a weapon. Kind: %s. Damage %s, range %s, speed %s." % (", ".join(tags) or "unspecified", w.get("DamageAmount").strip() or "?",
                                                                                          w.get("Range").strip() or "?", w.get("ProjectileSpeed").strip() or "?"))
        elif kind == "tech":
            out.append("Name: %s" % proj.tech_name(obj))
        else:
            out.append("Name: %s" % module_name(proj, obj))
    except Exception:
        pass
    return "\n".join(out)


def ai_icon_prompt(about, sub, size, siblings, extra=""):
    w, h = size
    s = ["Create ONE game icon image.", "",
         "What it shows:", about or "(describe the subject here)", "",
         "Game: " + AI_GAME, "",
         "Technical requirements (important):",
         "- Final size %dx%d pixels. If you make it larger, keep exactly the same proportions (%d:%d) - I will shrink it." % (w, h, w // max(1, math.gcd(w, h)), h // max(1, math.gcd(w, h))),
         "- PNG with a TRANSPARENT background. If you cannot make transparency, use ONE flat plain background colour (no gradient, no shadow, no floor) and tell me the colour.",
         "- One centred subject that fills most of the picture, nothing cut off. No text, no letters, no numbers, no border, no frame, no watermark.",
         "- Clean, high-contrast sci-fi look that stays readable when small."]
    if siblings:
        s.append("- It sits in a set with these existing pictures, so match their style: %s." % ", ".join(siblings[:8]))
    if extra.strip():
        s += ["", "Extra notes: " + extra.strip()]
    s += ["", "Give me only the image."]
    return "\n".join(s)


def ai_key_out(im, tol=40):
    """Make a plain-colour background transparent: flood from the four corners with the corner colour."""
    from PIL import ImageDraw
    im = im.convert("RGBA")
    w, h = im.size
    for xy in ((0, 0), (w - 1, 0), (0, h - 1), (w - 1, h - 1)):
        px = im.getpixel(xy)
        if px[3] > 8:
            ImageDraw.floodfill(im, xy, (px[0], px[1], px[2], 0), thresh=tol)
    return im


def ai_fit(im, size, keep_whole=True, key_out=True):
    """A picture of any size -> exactly `size`, as RGBA."""
    im = im.convert("RGBA")
    w, h = size
    if keep_whole:
        if key_out:
            im = ai_key_out(im)
        bb = im.getchannel("A").point(lambda a: 255 if a > 8 else 0).getbbox()
        if bb:
            im = im.crop(bb)
        k = min(w / float(im.width), h / float(im.height))
        nw, nh = max(1, int(round(im.width * k))), max(1, int(round(im.height * k)))
        im = im.resize((nw, nh), Image.LANCZOS)
        out = Image.new("RGBA", (w, h), (0, 0, 0, 0))
        out.paste(im, ((w - nw) // 2, (h - nh) // 2), im)
        return out
    k = max(w / float(im.width), h / float(im.height))
    nw, nh = max(w, int(round(im.width * k))), max(h, int(round(im.height * k)))
    im = im.resize((nw, nh), Image.LANCZOS)
    x, y = (nw - w) // 2, (nh - h) // 2
    return im.crop((x, y, x + w, y + h))


def ai_model_prompt(about, name, role, style, examples, fmt):
    s = ["Create ONE 3D spaceship model for a game.", "", "What it is:", about or "(describe the ship here)", "",
         "Game: " + AI_GAME + " The ship is seen from above at a distance, so the silhouette matters far more than small details.", "",
         "Technical requirements (important - the game's tools need exactly this):"]
    if fmt == "obj":
        s += ["- Output a Wavefront .obj with its .mtl material file and the texture as PNG file(s). Give me every file, with names that match what the .obj / .mtl refer to (no absolute paths, no spaces in file names).",
              "- The .mtl must use ONE plain diffuse texture per material (map_Kd = a .png). No normal / roughness / metal maps."]
    else:
        s += ["- Output a single .fbx (binary or ASCII) with the mesh, plus the texture(s) as PNG file(s) next to it. No embedded textures, no animation, no armature."]
    s += ["- ONE static mesh, closed and solid, triangles or quads, UV-unwrapped, with normals. Origin in the middle of the ship.",
          "- Y is up. The ship's LENGTH runs along the Z axis (nose at one end, engines at the other); the width is along X. The ship is roughly symmetrical left to right.",
          "- Keep it low-poly (a game model): about %s triangles." % ("%d-%d" % (min(e[3] for e in examples if e[3]) // 1, max(e[3] for e in examples if e[3])) if any(e[3] for e in examples) else "1,000-3,000"),
          "- Texture: PNG, 1024x1024 (or 512x512), power-of-two, painted hull surface with panel lines and lit windows; no transparency needed."]
    if examples:
        s += ["", "It must match the size and proportions of ships the mod already has (%s%s). Existing models (units are the model's own; make yours the same scale):" % (
            "style " + style if style else "", (", " if style and role else "") + ("role " + role if role else ""))]
        for nm, mp, ext, tr in examples:
            ex = sorted(ext)
            s.append("- %s (%s): length %.1f, width %.1f, height %.1f%s" % (nm, mp, ex[2], ex[1], ex[0], (", %d triangles" % tr) if tr else ""))
        s.append("Make the new ship about as long as the closest of these.")
    s += ["", "Name the ship: " + (name or "(ship name)") + ". Make the files <name>.obj / <name>.mtl / <name>.png using that name with no spaces.",
          "Reply with the files (or a download link for each). If you can only write text, give me the complete .obj and .mtl as text blocks I can save."]
    return "\n".join(s)


class AiModelDialog(_Dialog):
    """Builds a prompt for any AI that can make 3D files; the files are then imported with 'Import from PC'."""

    def __init__(self, master, proj, name, role, style, on_import=None):
        super().__init__(master, "Make a 3D model with an AI - %s" % (name or "new ship"))
        self.geometry("780x680")
        self.minsize(620, 520)
        self.proj, self.name, self.role, self.style, self.on_import = proj, name, role, style, on_import
        self.examples = proj.model_examples(style, role)
        bt = tk.Frame(self, bg=PANEL)
        bt.pack(side="bottom", fill="x", padx=14, pady=10)
        ttk.Button(bt, text="Close", command=self.destroy).pack(side="right")
        if on_import is not None:
            b = ttk.Button(bt, text="Import the files it made…", style="Save.TButton", command=self.imp)
            b.pack(side="right", padx=8)
            tip(b, "Pick the .obj / .fbx the AI gave you (its .mtl and PNG textures are copied with it). The ship then uses it as its model.")
        B = tk.Frame(self, bg=PANEL)
        B.pack(fill="both", expand=True, padx=14, pady=(10, 0))
        tk.Label(B, text="1.  Copy this prompt into an AI that can make 3D files (it needs to be able to hand you .obj / .fbx files - for example a "
                         "code-running AI, or a 3D tool such as Meshy, Tripo or Hunyuan3D). Describe the ship first.", bg=PANEL, fg=FG, anchor="w", justify="left",
                 wraplength=720).pack(fill="x")
        r = tk.Frame(B, bg=PANEL)
        r.pack(fill="x", pady=4)
        tk.Label(r, text="File type", bg=PANEL, fg=DIM).pack(side="left")
        self.fmt = tk.StringVar(value="obj")
        for lab, val in (("Wavefront .obj + .mtl + PNG", "obj"), (".fbx + PNG", "fbx")):
            ttk.Radiobutton(r, text=lab, value=val, variable=self.fmt, command=self.rebuild).pack(side="left", padx=8)
        self.about = tk.StringVar(value="a %s %s" % (style or "sci-fi", role or "starship"))
        tk.Label(B, text="What the ship looks like", bg=PANEL, fg=DIM, anchor="w").pack(fill="x")
        e = ttk.Entry(B, textvariable=self.about)
        e.pack(fill="x", pady=(0, 4))
        self.about.trace_add("write", lambda *_a: self.rebuild())
        self.t = tk.Text(B, height=18, wrap="word", **TEXT_OPTS)
        self.t.pack(fill="both", expand=True)
        bb = tk.Frame(B, bg=PANEL)
        bb.pack(fill="x", pady=4)
        ttk.Button(bb, text="Copy prompt", command=self.copy).pack(side="left")
        self.note = tk.Label(bb, text="", bg=PANEL, fg=PEACH)
        self.note.pack(side="left", padx=8)
        tk.Label(B, bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=720,
                 text="2.  Save the files it gives you, then 'Import the files it made…'. In the layout painter the model's outline shows straight away; "
                      "use 'Turn outline' if it faces the wrong way. %s" % (
                          "The sizes in the prompt come from %d existing ship model(s) the editor could read." % len(self.examples) if self.examples
                          else "No existing model of this style could be read here, so the prompt has no size to match.")).pack(fill="x", pady=(4, 0))
        self.rebuild()
        self.show()

    def rebuild(self):
        txt = ai_model_prompt(self.about.get().strip(), self.name, self.role, self.style, self.examples, self.fmt.get())
        self.report = txt
        self.t.delete("1.0", "end")
        self.t.insert("1.0", txt)

    def copy(self):
        try:
            self.report = self.t.get("1.0", "end").strip()
            self.clipboard_clear()
            self.clipboard_append(self.report)
            self.update()
            self.note["text"] = "Copied - paste it into the AI."
        except Exception:
            self.note["text"] = "Could not reach the clipboard."

    def imp(self):
        if self.on_import is not None:
            self.destroy()
            self.on_import()


# ---- measuring race videos (what a diplomacy video has to look like is read from the videos the game and the mods already have)
def _guid(txt):
    import uuid
    return uuid.UUID(txt).bytes_le


_ASF = {k: _guid(v) for k, v in (("header", "75B22630-668E-11CF-A6D9-00AA0062CE6C"), ("file", "8CABDCA1-A947-11CF-8EE4-00C00C205365"),
                                 ("stream", "B7DC0791-A9B7-11CF-8EE6-00C00C205365"), ("video", "BC19EFC0-5B4D-11CF-A8FD-00805F5C442B"),
                                 ("audio", "F8699E40-5B4D-11CF-A8FD-00805F5C442B"), ("ext", "5FBF03B5-A92E-11CF-8EE3-00C00C10D8FF"),
                                 ("extstream", "14E6A5CB-C672-4332-8399-A96952065B5A"))}


def asf_video_info(path):
    """Facts read from a .wmv / .asf file's header: width, height, fps, seconds, codec (FourCC), bitrate, audio. {} when it can't be read."""
    try:
        with open(path, "rb") as f:
            head = f.read(30)
            if len(head) < 30 or head[:16] != _ASF["header"]:
                return {}
            size = struct.unpack_from("<Q", head, 16)[0]
            blob = f.read(min(max(0, size - 30), 4 * 1024 * 1024))
    except OSError:
        return {}
    out, streams, fps_by = {}, {}, {}

    def walk(buf, pos, end):
        while pos + 24 <= end:
            g, sz = buf[pos:pos + 16], struct.unpack_from("<Q", buf, pos + 16)[0]
            if sz < 24 or pos + sz > end + 1:
                break
            d = pos + 24
            if g == _ASF["file"] and sz >= 24 + 80:
                play, _snd, pre = struct.unpack_from("<QQQ", buf, d + 40)
                out["seconds"] = max(0.0, play / 1e7 - pre / 1000.0)
                out["bitrate"] = struct.unpack_from("<I", buf, d + 76)[0]
            elif g == _ASF["stream"] and sz >= 24 + 54:
                kind = buf[d:d + 16]
                tlen, _elen, flags = struct.unpack_from("<IIH", buf, d + 40)
                num = flags & 0x7F
                ts = d + 54
                if kind == _ASF["video"] and tlen >= 11 + 20:
                    w, h = struct.unpack_from("<II", buf, ts)
                    fourcc = buf[ts + 11 + 16:ts + 11 + 20].decode("latin-1", "replace")
                    streams[num] = ("video", w, h, fourcc)
                elif kind == _ASF["audio"] and tlen >= 14:
                    tag, ch, rate, bps = struct.unpack_from("<HHII", buf, ts)
                    streams[num] = ("audio", tag, ch, rate, bps)
            elif g == _ASF["ext"] and sz >= 24 + 22:
                walk(buf, d + 22, pos + sz)
            elif g == _ASF["extstream"] and sz >= 24 + 64:
                num = struct.unpack_from("<H", buf, d + 48)[0]
                avg = struct.unpack_from("<Q", buf, d + 52)[0]
                if avg > 0:
                    fps_by[num] = 1e7 / avg
            pos += sz
    try:
        walk(blob, 0, len(blob))
    except struct.error:
        return {}
    for num, st in streams.items():
        if st[0] == "video" and "width" not in out:
            out.update(width=st[1], height=st[2], codec=st[3])
            if num in fps_by:
                out["fps"] = fps_by[num]
        elif st[0] == "audio" and "audio" not in out:
            out["audio"] = "%d ch, %d Hz" % (st[2], st[3])
    out.setdefault("audio", "none")
    return out if "width" in out else {}


def xnb_video_parse(b):
    """Parse a compiled video .xnb (bytes). -> {} when it is not one, or {'compressed': True} when it is compressed; else the stored path, duration (ms),
    fps, width, height, soundtrack and the byte positions needed to rewrite it for another video."""
    try:
        if len(b) < 20 or b[:3] != b"XNB":
            return {}
        if b[5] & 0xC0:
            return {"compressed": True}
        pos = 10
        n, pos = _xnb_7bit(b, pos)
        names = []
        for _ in range(n):
            ln, pos = _xnb_7bit(b, pos)
            names.append(b[pos:pos + ln].decode("utf-8", "replace"))
            pos += ln + 4
        _shared, pos = _xnb_7bit(b, pos)
        tid, pos = _xnb_7bit(b, pos)
        if not (1 <= tid <= len(names)) or "VideoReader" not in names[tid - 1]:
            return {}
        start = pos
        ln, pos = _xnb_7bit(b, pos)
        path = b[pos:pos + ln].decode("utf-8", "replace")
        pos += ln
        dur, fps, w, h, snd = struct.unpack_from("<ifiii", b, pos)
        if not (0 < w <= 8192 and 0 < h <= 8192):
            return {}
        return {"path": path, "ms": dur, "fps": fps, "width": w, "height": h, "snd": snd, "start": start, "end": pos + 20}
    except (struct.error, ValueError):
        return {}


def xnb_video_info(path):
    """Width, height, fps, seconds and the stored video path of a compiled video .xnb. {} when it is compressed or not a video."""
    try:
        i = xnb_video_parse(Path(path).read_bytes())
    except OSError:
        return {}
    if not i or i.get("compressed"):
        return {}
    return {"width": i["width"], "height": i["height"], "fps": i["fps"], "seconds": i["ms"] / 1000.0, "codec": "(compiled .xnb)", "audio": "?", "points": i["path"]}


def rewrite_video_xnb(template, new_path, ms, fps, w, h):
    """A video .xnb for another video: the template's own header and reader names are kept, only the stored path, length, frame rate and size change."""
    i = xnb_video_parse(template)
    if not i or i.get("compressed"):
        raise ValueError("the template .xnb is not an uncompressed video .xnb")
    raw = new_path.encode("utf-8")
    n, ln = len(raw), bytearray()
    while True:                                                   # 7-bit encoded length
        byte = n & 0x7F
        n >>= 7
        ln.append(byte | (0x80 if n else 0))
        if not n:
            break
    payload = bytes(ln) + raw + struct.pack("<ifiii", int(ms), float(fps), int(w), int(h), i["snd"])
    out = bytearray(template[:i["start"]]) + payload + template[i["end"]:]
    struct.pack_into("<i", out, 6, len(out))                      # the file size stored in the header
    return bytes(out)


def _mp4_boxes(buf, pos, end):
    while pos + 8 <= end:
        size, kind = struct.unpack_from(">I4s", buf, pos)
        hdr = 8
        if size == 1 and pos + 16 <= end:
            size, hdr = struct.unpack_from(">Q", buf, pos + 8)[0], 16
        elif size == 0:
            size = end - pos
        if size < hdr or pos + size > end:
            break
        yield kind.decode("latin-1"), pos + hdr, pos + size
        pos += size


def mp4_video_info(path):
    """Width, height, fps, seconds, codec of an .mp4 / .mov (read from its moov box). {} when it can't be read."""
    try:
        with open(path, "rb") as f:
            f.seek(0, 2)
            total = f.tell()
            pos, moov = 0, None
            while pos + 8 <= total:
                f.seek(pos)
                h = f.read(16)
                size, kind = struct.unpack_from(">I4s", h, 0)
                hdr = 8
                if size == 1:
                    size, hdr = struct.unpack_from(">Q", h, 8)[0], 16
                elif size == 0:
                    size = total - pos
                if size < hdr:
                    break
                if kind == b"moov":
                    f.seek(pos + hdr)
                    moov = f.read(min(size - hdr, 32 * 1024 * 1024))
                    break
                pos += size
    except (OSError, struct.error):
        return {}
    if not moov:
        return {}
    out = {}
    try:
        for k, s0, e0 in _mp4_boxes(moov, 0, len(moov)):
            if k == "mvhd":
                ver = moov[s0]
                if ver == 1:
                    ts, du = struct.unpack_from(">IQ", moov, s0 + 20)
                else:
                    ts, du = struct.unpack_from(">II", moov, s0 + 12)
                if ts:
                    out["seconds"] = du / float(ts)
            elif k == "trak":
                vid, w, h, fps, codec, ts_m = False, 0, 0, 0.0, "", 0
                for k2, s2, e2 in _mp4_boxes(moov, s0, e0):
                    if k2 == "tkhd":
                        o = s2 + (88 if moov[s2] == 1 else 76)
                        w, h = struct.unpack_from(">II", moov, o)
                        w, h = w >> 16, h >> 16
                    elif k2 == "mdia":
                        for k3, s3, e3 in _mp4_boxes(moov, s2, e2):
                            if k3 == "hdlr":
                                vid = moov[s3 + 8:s3 + 12] == b"vide"
                            elif k3 == "mdhd":
                                ts_m = struct.unpack_from(">I", moov, s3 + (20 if moov[s3] == 1 else 12))[0]
                            elif k3 == "minf":
                                for k4, s4, e4 in _mp4_boxes(moov, s3, e3):
                                    if k4 == "stbl":
                                        for k5, s5, e5 in _mp4_boxes(moov, s4, e4):
                                            if k5 == "stsd" and not codec:
                                                codec = moov[s5 + 12:s5 + 16].decode("latin-1", "replace")
                                            elif k5 == "stts":
                                                cnt = struct.unpack_from(">I", moov, s5 + 4)[0]
                                                samples = dur = 0
                                                for j in range(min(cnt, 4096)):
                                                    c, d = struct.unpack_from(">II", moov, s5 + 8 + 8 * j)
                                                    samples, dur = samples + c, dur + c * d
                                                if dur and ts_m:
                                                    fps = samples / (dur / float(ts_m))
                if vid and w and h and "width" not in out:
                    out.update(width=w, height=h, fps=fps, codec=codec or "mp4")
    except (struct.error, IndexError):
        return {}
    out.setdefault("audio", "?")
    return out if "width" in out else {}


def video_file_info(path):
    ext = Path(path).suffix.lower()
    if ext in (".wmv", ".asf"):
        return asf_video_info(path)
    if ext in (".mp4", ".mov", ".m4v"):
        return mp4_video_info(path)
    if ext == ".xnb":
        return xnb_video_info(path)
    return {}


def dialogue_situations(d):
    """[(index, DialogType, {tag: path})] of a diplomacy dialogue doc, in file order (tag DialogType excluded)."""
    out = {}
    for path in d.cur:
        m = re.match(r"^Dialogs/DialogLine(?:\[(\d+)\])?/([^/]+)$", path)
        if m:
            out.setdefault(int(m.group(1) or 0), {})[m.group(2)] = path
    res = []
    for i in sorted(out):
        tags = out[i]
        res.append((i, d.get(tags["DialogType"]).strip() if "DialogType" in tags else "", {t: p_ for t, p_ in tags.items() if t != "DialogType"}))
    return res


DLG_TOKEN = re.compile(r"%(?:\d+\$)?[-+ 0-9.]*[sdfgxXc]|\{[^}]*\}|\\n|<[^>]+>|\[[^\]]+\]")


class AiDialogueDialog(_Dialog):
    """Rewrite a race's diplomacy dialogue with any AI so it sounds like that race. Step 1: describe the race's character and attitude (the boxes are
    prefilled from the race file); step 2: copy the prompt - it carries the existing lines in a fixed layout; step 3: paste the AI's answer back and
    apply it. Lines whose %s / {0} / \\n markers changed are skipped."""
    BATCH = 15

    QUESTIONS = (("species", "Who they are", "The race in a few sentences: species, home, history, how they see themselves.", 3),
                 ("values", "What they value and want", "Their core values, goals and fears: honour, profit, order, conquest, survival ...", 3),
                 ("attitude", "Attitude towards the player", "Default attitude to other empires, and what makes them friendlier or colder: respect, strength, trade, flattery ...", 3),
                 ("voice", "How they speak", "Formal or blunt, long-winded or clipped, poetic, sarcastic, threatening, polite, archaic ... and how they address the player (Commander, outsider, Federation envoy ...).", 3),
                 ("tics", "Catchphrases, quirks and favourite words", "Phrases they like, sayings, metaphors, words or topics they would never use.", 2),
                 ("moods", "How Friendly / Neutral / Hostile differ", "What each mood sounds like for this race: e.g. Friendly = grudging respect, Hostile = cold contempt.", 2),
                 ("avoid", "Things to avoid", "Out-of-character content, real-world references, words that break the setting ...", 2))

    def __init__(self, master, race_doc, dlg_doc, apply, race_name=""):
        super().__init__(master, "Rewrite the dialogue with an AI - %s" % (race_name or dlg_doc.path.stem))
        try:
            sw, sh = int(self.winfo_screenwidth()), int(self.winfo_screenheight())
        except Exception:
            sw, sh = 1400, 900
        w, h = min(1300, int(sw * 0.92)), int(sh * 0.92)
        self.geometry("%dx%d+%d+%d" % (w, h, max(0, (sw - w) // 2), max(0, (sh - h) // 2 - 20)))
        self.minsize(820, 520)
        self.race, self.doc, self.apply_cb, self.name = race_doc, dlg_doc, apply, race_name or dlg_doc.path.stem
        self.sits = dialogue_situations(dlg_doc)
        self.nb = max(1, (len(self.sits) + self.BATCH - 1) // self.BATCH)
        bt = tk.Frame(self, bg=PANEL)
        bt.pack(side="bottom", fill="x", padx=14, pady=10)
        cb = ttk.Button(bt, text="Copy prompt to clipboard", style="Save.TButton", command=self.copy)
        cb.pack(side="left")
        tip(cb, "Copy the whole prompt, ready to paste into any AI.")
        ttk.Button(bt, text="Close", command=self.destroy).pack(side="right")
        self.ap_btn = ttk.Button(bt, text="Apply the AI's answer", style="Save.TButton", command=self.apply_reply)
        self.ap_btn.pack(side="right", padx=8)
        tip(self.ap_btn, "Reads the pasted answer and replaces the lines it contains (Undo brings the old ones back).")
        self.msg = tk.Label(bt, bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=620)
        self.msg.pack(side="left", padx=12, fill="x", expand=True)
        sf = ScrollFrame(self, bg=PANEL)
        sf.pack(fill="both", expand=True)
        B = sf.inner
        self.boxes = {}

        def head(txt):
            tk.Label(B, text=txt, bg=PANEL, fg=PEACH, anchor="w", font=("Segoe UI", 10, "bold")).pack(fill="x", padx=14, pady=(12, 2))
        head("1.  Describe the race's character and attitude (the AI uses this to rewrite every line)")
        tk.Label(B, bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=1100,
                 text="The more specific you are, the less generic the lines. Boxes are prefilled from the race file where it has something; edit freely.").pack(fill="x", padx=14)
        pre = self.prefill()
        for key, lab, hint, hgt in self.QUESTIONS:
            tk.Label(B, text=lab, bg=PANEL, fg=FG, anchor="w").pack(fill="x", padx=14, pady=(6, 0))
            tk.Label(B, text=hint, bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=1100).pack(fill="x", padx=14)
            t = tk.Text(B, height=hgt, wrap="word", bg=PANEL2, fg=FG, insertbackground=ORANGE, relief="flat", padx=8, pady=5, font=("Segoe UI", 10))
            t.insert("1.0", pre.get(key, ""))
            t.pack(fill="x", padx=14, pady=2)
            t.bind("<KeyRelease>", lambda _e: self.build())
            self.boxes[key] = t
        head("2.  Options")
        row = tk.Frame(B, bg=PANEL)
        row.pack(fill="x", padx=14)
        tk.Label(row, text="Lines to send", bg=PANEL, fg=DIM).pack(side="left")
        self.batch = tk.StringVar(value="1")
        vals = [str(i + 1) for i in range(self.nb)]
        cbx = ttk.Combobox(row, textvariable=self.batch, values=vals, state="readonly", width=5)
        cbx.pack(side="left", padx=6)
        cbx.bind("<<ComboboxSelected>>", lambda _e: self.build())
        self.batch_lb = tk.Label(row, bg=PANEL, fg=DIM)
        self.batch_lb.pack(side="left")
        tip(cbx, "Dialogue files are long, so the lines are sent in groups of %d situations. Do group 1, apply, then group 2 ..." % self.BATCH)
        self.interview = tk.IntVar(value=0)
        ck = ttk.Checkbutton(row, text="Let the AI ask me questions first", variable=self.interview, command=self.build)
        ck.pack(side="left", padx=18)
        tip(ck, "Adds an instruction: before rewriting, the AI asks you up to 8 questions about the race's character and attitude and waits for your answers.")
        self.keep_len = tk.IntVar(value=1)
        ck2 = ttk.Checkbutton(row, text="Keep each line about as long", variable=self.keep_len, command=self.build)
        ck2.pack(side="left", padx=8)
        head("3.  Copy this prompt into any AI")
        self.out = tk.Text(B, height=16, wrap="word", bg=PANEL2, fg=FG, relief="flat", padx=8, pady=6, font=("Segoe UI", 10))
        self.out.pack(fill="x", padx=14, pady=2)
        head("4.  Paste the AI's answer here, then press 'Apply the AI's answer'")
        self.reply = tk.Text(B, height=12, wrap="word", bg=PANEL2, fg=FG, insertbackground=ORANGE, relief="flat", padx=8, pady=6, font=("Consolas", 9))
        self.reply.pack(fill="x", padx=14, pady=(2, 14))
        self.build()

    def prefill(self):
        r, out = self.race, {}
        if r is None:
            return out
        try:
            adj = ", ".join(x for x in (r.get("Traits/Adj1"), r.get("Traits/Adj2")) if x.strip())
            sing = r.get("Traits/Singular").strip()
            out["species"] = ("%s%s" % (sing + " " if sing else "", ("(%s)" % adj) if adj else "")).strip()
            pers = [x for x in r.lists.get("personality", []) if isinstance(x, str)]
            eco = [x for x in r.lists.get("economic", []) if isinstance(x, str)]
            tr = [x for k, v in r.lists.items() if k.startswith("traits") for x in v if isinstance(x, str)]
            bits = []
            if pers:
                bits.append("AI personality in the game: %s." % ", ".join(sorted(set(pers))))
            if eco:
                bits.append("Economy focus: %s." % ", ".join(sorted(set(eco))))
            if tr:
                bits.append("Racial traits: %s." % ", ".join(tr[:12]))
            out["values"] = " ".join(bits)
        except Exception:
            pass
        return out

    def answers(self):
        return {k: t.get("1.0", "end-1c").strip() for k, t in self.boxes.items()}

    def chunk(self):
        try:
            b = max(1, min(self.nb, int(self.batch.get())))
        except ValueError:
            b = 1
        return self.sits[(b - 1) * self.BATCH:b * self.BATCH]

    def build(self):
        a = self.answers()
        ch = self.chunk()
        L = ["You are a writer for a space strategy game (StarDrive). Rewrite the diplomacy dialogue of the %s so that every line sounds like that race - its character, attitude and way of speaking - instead of generic text." % self.name, ""]
        if self.interview.get():
            L += ["FIRST: do not rewrite anything yet. Ask me up to 8 short questions about the %s's character, attitude and speech style (what I told you below may be thin), and wait for my answers. After that, do the task." % self.name, ""]
        L.append("THE RACE:")
        for key, lab, _h, _n in self.QUESTIONS:
            L.append("- %s: %s" % (lab, a.get(key) or "(not given - infer something fitting and stay consistent)"))
        L += ["", "RULES:",
              "- Rewrite only the wording of each line. Keep its meaning and what the game situation is (the label in the [[S..]] header tells you the situation: greeting, trade offer, war declaration, ...).",
              "- Keep every placeholder and marker exactly as written: things like %s, %d, {0}, [name], <tags> and the two characters \\n. Do not add or remove any.",
              "- Mood lines: Friendly / Neutral / Hostile must clearly differ in warmth for this race. Lines named DL_... are for an AI personality (Ruth = ruthless, Agg = aggressive, Xeno = xenophobic, Hon = honorable, Pac = pacifist, Cunn = cunning, Ind = industrialist, Exp = expansionist, Mil = militarist, Gen = generalist, Tech = technologist) - lean into that personality.",
              "- Do not invent new lines, do not drop lines, do not rename the tags." + (" Keep each line about as long as the original." if self.keep_len.get() else " Lines may be a little longer or shorter if it helps the character."),
              "- No real-world references, no emoji, no stage directions in brackets.", "",
              "ANSWER FORMAT (important - a program reads it): return ONLY the blocks below, in the same order, one line per tag, nothing before or after:", "",
              "[[S3: Example situation]]", "Default: the rewritten text", "Friendly: the rewritten text", "", "THE LINES TO REWRITE (%d situations):" % len(ch), ""]
        for i, dt, tags in ch:
            L.append("[[S%d: %s]]" % (i, pretty_dialog_type(dt) or dt))
            for tag, path in tags.items():
                L.append("%s: %s" % (tag, " ".join(self.doc.get(path).split())))
            L.append("")
        txt = "\n".join(L)
        self.out.configure(state="normal")
        self.out.delete("1.0", "end")
        self.out.insert("1.0", txt)
        self.batch_lb.configure(text="of %d   (%d situation(s) in this group, %d in the file)" % (self.nb, len(ch), len(self.sits)))
        self.last_prompt = txt

    def copy(self):
        self.clipboard_clear()
        self.clipboard_append(self.out.get("1.0", "end-1c"))
        self.msg.configure(text="Prompt copied - paste it into the AI.", fg=DIM)

    def parse(self, text):
        """{index: {tag: text}} from the AI's answer ([[S3: name]] headers, 'Tag: text' lines)."""
        res, cur, last = {}, None, None
        for raw in text.replace("```", "").splitlines():
            line = raw.strip()
            m = re.match(r"^\[\[\s*S(\d+)\b[^\]]*\]\]", line)
            if m:
                cur, last = int(m.group(1)), None
                res.setdefault(cur, {})
                continue
            if cur is None or not line:
                continue
            m = re.match(r"^([A-Za-z_][\w]*)\s*:\s*(.*)$", line)
            known = {t.lower(): t for _i, _d, tg in self.sits for t in tg}
            if m and m.group(1).lower() in known:
                last = known[m.group(1).lower()]
                res[cur][last] = m.group(2).strip()
            elif last is not None:
                res[cur][last] += " " + line
        return res

    def apply_reply(self):
        txt = self.reply.get("1.0", "end-1c")
        if not txt.strip():
            self.msg.configure(text="Paste the AI's answer into the box first.", fg="#e0b060")
            return
        got = self.parse(txt)
        by = {i: tags for i, _d, tags in self.sits}
        done = same = 0
        bad = []
        for i, lines in got.items():
            for tag, new in lines.items():
                path = by.get(i, {}).get(tag)
                if not path or not new.strip():
                    continue
                old = self.doc.get(path)
                if sorted(DLG_TOKEN.findall(old)) != sorted(DLG_TOKEN.findall(new)):
                    bad.append("S%d %s" % (i, tag))
                    continue
                if " ".join(old.split()) == " ".join(new.split()):
                    same += 1
                    continue
                self.apply_cb(path, new.strip())
                done += 1
        if not got:
            self.msg.configure(text="No [[S..]] blocks were found in the answer - ask the AI to use exactly the layout in the prompt.", fg="#e07070")
            return
        self.msg.configure(text="%d line(s) rewritten, %d unchanged%s. %s" % (done, same, ("; %d skipped because a placeholder (%%s, {0}, \\n ...) differed: %s" % (len(bad), ", ".join(bad[:6]))) if bad else "",
                                                                          "Undo brings them back; Save writes them." if done else ""), fg=DIM if not bad else "#e0b060")


class AiVideoDialog(_Dialog):
    """Make a race's diplomacy video with an AI: the prompt carries the file parameters measured from the race videos the game and the mods already
    have (nothing is guessed). The finished video is picked back and copied into the mod's Video folder. result = the video's name (no extension)."""

    def __init__(self, master, app, race_name, current=""):
        super().__init__(master, "Make a diplomacy video with an AI - %s" % race_name)
        try:
            sw, sh = int(self.winfo_screenwidth()), int(self.winfo_screenheight())
        except Exception:
            sw, sh = 1400, 900
        w, h = min(1400, int(sw * 0.92)), int(sh * 0.92)             # big by default, never larger than the screen
        self.geometry("%dx%d+%d+%d" % (w, h, max(0, (sw - w) // 2), max(0, (sh - h) // 2 - 20)))
        self.minsize(760, 480)
        self.app, self.proj, self.race, self.stem, self.files = app, app.proj, race_name, current, []
        bt = tk.Frame(self, bg=PANEL)
        bt.pack(side="bottom", fill="x", padx=14, pady=10)
        self.use_btn = ttk.Button(bt, text="Use the video", style="Save.TButton", command=self.ok, state="disabled")
        self.use_btn.pack(side="right")
        ttk.Button(bt, text="Cancel", command=self.destroy).pack(side="right", padx=8)
        cb = ttk.Button(bt, text="Copy prompt to clipboard", style="Save.TButton", command=self.copy)
        cb.pack(side="right")
        tip(cb, "Copy the whole prompt to the clipboard, ready to paste into an AI that makes videos.")
        self.msg = tk.Label(bt, bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=620)
        self.msg.pack(side="left", fill="x", expand=True)
        B = tk.Frame(self, bg=PANEL)
        B.pack(fill="both", expand=True, padx=14, pady=(10, 0))
        tk.Label(B, text="0.  What the game's own race videos look like (measured from the files on this computer)", bg=PANEL, fg=PEACH, anchor="w",
                 font=("Segoe UI", 10, "bold")).pack(fill="x")
        fr = tk.Frame(B, bg=PANEL)
        fr.pack(fill="x", pady=(2, 4))
        self.tv = ttk.Treeview(fr, columns=("src", "size", "fps", "sec", "codec", "audio", "points"), show="tree headings", height=4, selectmode="browse")
        for c, t, w in (("#0", "Video file", 190), ("src", "From", 110), ("size", "Size (px)", 75), ("fps", "Frames/s", 65), ("sec", "Seconds", 65), ("codec", "Codec", 85),
                        ("audio", "Audio", 100), ("points", "The .xnb points at", 170)):
            self.tv.heading(c, text=t)
            self.tv.column(c, width=w, anchor="w", stretch=c == "#0")
        sb = ttk.Scrollbar(fr, orient="vertical", command=self.tv.yview)
        self.tv.configure(yscrollcommand=sb.set)
        sb.pack(side="right", fill="y")
        self.tv.pack(side="left", fill="x", expand=True)
        tip(self.tv, "The race videos found in your mod, the base game and the other mods, and what was read from each file's header.")
        self.v = {k: tk.StringVar() for k in ("width", "height", "fps", "seconds", "codec", "audio", "ext", "name")}
        self.template = None                                      # (path of an uncompressed race video .xnb, its parse) - the new .xnb is made from it
        self.note = tk.Label(B, bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=1200)
        self.note.pack(fill="x")
        grid = tk.Frame(B, bg=PANEL)
        grid.pack(fill="x", pady=4)
        for i, (k, lab, w, hint) in enumerate((("width", "Width (px)", 7, "Picture width in pixels."), ("height", "Height (px)", 7, "Picture height in pixels."),
                                                ("fps", "Frames / s", 7, "Frames per second."), ("seconds", "Length (s)", 7, "Length in seconds."),
                                                ("codec", "Codec", 9, "The video codec of the existing videos, e.g. WMV2 or avc1 (H.264)."),
                                                ("ext", "File type", 6, "The file type the game's race videos use (.wmv, .mp4 ...), read from the video the existing .xnb files point at."),
                                                ("audio", "Audio", 14, "What sound the existing videos carry."))):
            tk.Label(grid, text=lab, bg=PANEL, fg=DIM).grid(row=0, column=i * 2, sticky="w", padx=(0 if i == 0 else 10, 3))
            e = ttk.Entry(grid, textvariable=self.v[k], width=w)
            e.grid(row=0, column=i * 2 + 1, sticky="w")
            tip(e, hint + "\nFilled in from the videos above; change it only if you know the game accepts something else.")
            self.v[k].trace_add("write", lambda *_a: self.build())
        tk.Label(B, text="1.  Describe the video, then copy the prompt into any AI that makes videos.", bg=PANEL, fg=PEACH, anchor="w",
                 font=("Segoe UI", 10, "bold")).pack(fill="x", pady=(8, 0))
        self.subject = tk.Text(B, height=3, wrap="word", bg=PANEL2, fg=FG, insertbackground=ORANGE, relief="flat", padx=8, pady=6, font=("Segoe UI", 10))
        self.subject.insert("1.0", "The leader / ambassador of the %s, shown head and shoulders, looking at the camera and speaking to the player. Calm, idle movement. "
                                   "Plain dark background that fits the race." % race_name)
        self.subject.pack(fill="x", pady=2)
        self.subject.bind("<KeyRelease>", lambda _e: self.build())
        self.out = tk.Text(B, height=10, wrap="word", bg=PANEL2, fg=FG, relief="flat", padx=8, pady=6, font=("Segoe UI", 10))
        self.out.pack(fill="both", expand=True, pady=2)
        r = tk.Frame(B, bg=PANEL)
        r.pack(fill="x", pady=4)
        b = ttk.Button(r, text="Copy the prompt", style="Save.TButton", command=self.copy)
        b.pack(side="left")
        tip(b, "Copy the prompt to the clipboard, ready to paste into an AI.")
        b = ttk.Button(r, text="Save a video report…", command=self.report)
        b.pack(side="left", padx=8)
        tip(b, "Writes a text file listing every video file in the game and mod folders and what is inside each .xnb. Send it to get the exact format added if the numbers above could not be measured.")
        tk.Label(B, text="2.  Put the finished video (.wmv, and the compiled .xnb if you have it) here.", bg=PANEL, fg=PEACH, anchor="w",
                 font=("Segoe UI", 10, "bold")).pack(fill="x", pady=(6, 0))
        r2 = tk.Frame(B, bg=PANEL)
        r2.pack(fill="x", pady=4)
        b = ttk.Button(r2, text="Pick the video file(s)…", command=self.pick)
        b.pack(side="left")
        tip(b, "Pick the .wmv (and the .xnb compiled from it) on this computer. They are copied into the mod's Video folder when you Save.")
        self.chk_btn = ttk.Button(r2, text="Check video", command=self.check_video, state="disabled")
        self.chk_btn.pack(side="left", padx=8)
        tip(self.chk_btn, "Checks the picked video against the race videos the game already plays (size, frame rate, codec, file type, the .xnb) and can open it in your video player. "
                          "It cannot start the game - the final proof is the game's own diplomacy screen.")
        tk.Label(r2, textvariable=self.v["name"], bg=PANEL, fg=FG).pack(side="left", padx=10)
        self.scan()
        self.build()
        self.bind("<Escape>", lambda _e: self.destroy())

    def scan(self):
        P = self.proj
        used = {r.get("Traits/VideoPath").strip().lower() for r in P.races + P.base_races if r.get("Traits/VideoPath").strip()}
        try:
            rows = P.library_scan()
        except Exception:
            log_exc("video scan", sys.exc_info())
            rows = []
        vids = [r for r in rows if "video" in r[5] and r[3] in (".wmv", ".xnb", ".asf", ".mp4", ".mov", ".m4v", ".webm", ".ogv", ".avi")]
        pick = [r for r in vids if Path(r[2]).stem.lower() in used] or vids        # the videos the races use; else every video there is
        found, seen = [], set()
        for label, top, rel, ext, size, kinds in pick:
            if (label, rel) in seen:
                continue
            seen.add((label, rel))
            info = video_file_info(top / rel)
            if ext == ".xnb" and self.template is None and info.get("points"):
                self.template = (top / rel, rel)
            found.append((Path(rel).name, label, size, info or {}, ext))
        self.found = [f for f in found if f[3]]
        self.unread = [f for f in found if not f[3]]
        for i, (name, label, size, info, ext) in enumerate(found):
            if info:
                self.tv.insert("", "end", iid=str(i), text=name, values=(label, "%d x %d" % (info["width"], info["height"]), ("%.2f" % info["fps"]) if info.get("fps") else "?",
                                                                          ("%.1f" % info["seconds"]) if info.get("seconds") else "?", info.get("codec", "?"), info.get("audio", "?"),
                                                                          info.get("points", "")))
            else:
                self.tv.insert("", "end", iid=str(i), text=name, values=(label, "(not readable)", "", "", ext, "", ""))
        good = self.found
        if self.template is not None:                                  # the file type the game's .xnb files point at
            pth = xnb_video_info(self.template[0]).get("points", "")
            self.v["ext"].set(Path(pth).suffix.lower())
        else:
            sib = next((f[4] for f in found if f[4] != ".xnb"), "")
            self.v["ext"].set(sib)
        if not good:
            self.note.configure(text="No race video could be measured here (%d file(s) found, %d unreadable - a compressed .xnb or an unknown format). Use 'Save a video report' below and send me the file: it lists what is in the Video folders so the exact format can be added. "
                                     "Until then fill in the boxes yourself." % (len(found), len(self.unread)), fg="#e0b060")
            return
        from collections import Counter
        mode = lambda key: Counter(i[key] for _n, _l, _s, i, _e in good if i.get(key) not in (None, "", "?")).most_common(1)
        for k in ("width", "height", "codec", "audio"):
            m = mode(k)
            if m:
                self.v[k].set(str(m[0][0]))
        for k, fmt in (("fps", "%.2f"), ("seconds", "%.0f")):
            vals = sorted(i[k] for _n, _l, _s, i, _e in good if i.get(k))
            if vals:
                t = fmt % vals[len(vals) // 2]
                self.v[k].set(t.rstrip("0").rstrip(".") if "." in t else t)
        if not self.v["fps"].get().strip():
            self.v["fps"].set("30")                                   # the header gave no frame rate; 30 is the usual one - change it if yours differ
        self.note.configure(text="%d race video(s) measured. The boxes hold the most common values (frame rate and length: the middle one) and the prompt uses them.%s" % (
            len(good), "" if self.template is not None else "  No uncompressed .xnb was found to copy the layout from, so the editor cannot make the .xnb for you."), fg=DIM)

    def spec(self):
        g = lambda k: self.v[k].get().strip()
        return {k: g(k) for k in ("width", "height", "fps", "seconds", "codec", "audio", "ext")}

    def build(self):
        sp = self.spec()
        name = re.sub(r"[^\w\-]+", "_", self.race).strip("_") or "race"
        need = [k for k in ("width", "height", "fps", "seconds") if not sp[k]]
        lines = ["Make a short video for the diplomacy screen of a space strategy game.", "",
                 "WHAT TO SHOW: " + self.subject.get("1.0", "end-1c").strip(), "",
                 "FILE PARAMETERS (these must be exact - the game plays the file as it is):"]
        lines.append("- Picture size: %s x %s pixels (no letterbox bars, no cropping later)" % (sp["width"] or "?", sp["height"] or "?"))
        lines.append("- Frame rate: %s frames per second, constant" % (sp["fps"] or "?"))
        lines.append("- Length: about %s seconds, and it must loop seamlessly (the last frame leads into the first)" % (sp["seconds"] or "?"))
        ext = (sp["ext"] or ".wmv").lower()
        if not ext.startswith("."):
            ext = "." + ext
        kind = {".wmv": "Windows Media Video", ".mp4": "MPEG-4 (H.264)", ".webm": "WebM", ".ogv": "Ogg Theora", ".avi": "AVI", ".mov": "QuickTime"}.get(ext, ext[1:].upper())
        lines.append("- Container / codec: %s (%s)%s" % (kind, ext, (", video codec " + sp["codec"]) if sp["codec"] and not sp["codec"].startswith("(") else ""))
        lines.append("- Sound: %s" % (sp["audio"] or "?"))
        lines.append("- File name: %s%s" % (name, ext))
        lines += ["", "ALSO: no text, subtitles, logos or watermarks in the picture; one steady camera; no scene cuts."]
        fc = sp["codec"]
        quiet = (sp["audio"] or "").lower() in ("none", "")
        enc = {".mp4": "-c:v libx264 -pix_fmt yuv420p -movflags +faststart " + ("-an" if quiet else "-c:a aac"),
               ".webm": "-c:v libvpx-vp9 " + ("-an" if quiet else "-c:a libopus"), ".ogv": "-c:v libtheora -q:v 7 " + ("-an" if quiet else "-c:a libvorbis")}.get(ext)
        if ext == ".wmv" and (fc or "").upper() in ("WMV1", "WMV2"):
            enc = "-c:v %s -b:v 2000k %s" % (fc.lower(), "-an" if quiet else "-c:a wmav2")
        lines += ["", "IF THE AI GIVES YOU A DIFFERENT FILE TYPE (most make .mp4), convert it so it matches the numbers above. With ffmpeg:"]
        if enc and sp["width"] and sp["height"] and sp["fps"]:
            lines.append('  ffmpeg -i input.mp4 -vf "scale=%s:%s" -r %s %s %s%s' % (sp["width"], sp["height"], sp["fps"], enc, name, ext))
        else:
            lines.append("  ffmpeg can scale and re-time it (-vf scale=W:H  -r FPS); %s needs a converter that writes that codec." % (("the existing videos use %s, which" % fc) if fc else "check which codec the existing videos use, it"))
        lines += ["", "THEN: use 'Use the video' in the Balance Editor. It makes the small .xnb the game loads from the layout of your existing race videos and copies both files into the mod's Video folder."]
        if need:
            lines.insert(0, "(fill in: %s)\n" % ", ".join(need))
        self.out.configure(state="normal")
        self.out.delete("1.0", "end")
        self.out.insert("1.0", "\n".join(lines))

    def copy(self):
        self.clipboard_clear()
        self.clipboard_append(self.out.get("1.0", "end-1c"))
        self.msg.configure(text="Prompt copied to the clipboard - paste it into the AI.", fg=DIM)

    def check_video(self):
        vids = [Path(f) for f in self.files if Path(f).suffix.lower() != ".xnb"]
        if not vids:
            messagebox.showinfo("Check video", "Pick the finished video first.", parent=self)
            return
        v = vids[0]
        info = video_file_info(v)
        sp = self.spec()
        good, bad = [], []
        if not info:
            bad.append("The header of %s could not be read - it may be damaged or an unusual format." % v.name)
        else:
            def cmp(label, got, want, tol=0.0):
                if want in ("", None, "?"):
                    return
                try:
                    ok = abs(float(got) - float(want)) <= tol
                except (TypeError, ValueError):
                    ok = str(got).lower() == str(want).lower()
                (good if ok else bad).append("%s: %s%s" % (label, got, "" if ok else "   (the game's videos: %s)" % want))
            cmp("Width", info["width"], sp["width"])
            cmp("Height", info["height"], sp["height"])
            if info.get("fps"):
                cmp("Frames/s", round(info["fps"], 2), sp["fps"], 0.6)
            if info.get("codec") and sp["codec"] and not sp["codec"].startswith("("):
                cmp("Codec", info["codec"], sp["codec"])
            if sp["ext"]:
                cmp("File type", v.suffix.lower(), sp["ext"].lower())
            if info.get("seconds"):
                good.append("Length: %.1f s" % info["seconds"])
        if any(Path(f).suffix.lower() == ".xnb" for f in self.files):
            good.append("A compiled .xnb is included.")
        elif self.template is not None:
            good.append("The editor will make the .xnb from your existing race video layout.")
        else:
            bad.append("No .xnb can be made (no readable race video .xnb to copy) and none was picked - the game loads the .xnb, so add one.")
        txt = ("MATCHES THE GAME'S VIDEOS:\n  " + "\n  ".join(good) if good else "") + ("\n\nPROBLEMS:\n  " + "\n  ".join(bad) if bad else "\n\nNo problems found.")
        txt += "\n\nThis compares the file with the videos the game already plays; it cannot start the game. Open it in your video player now?"
        if messagebox.askyesno("Check video", txt, parent=self):
            try:
                if hasattr(os, "startfile"):
                    os.startfile(str(v))
                else:
                    import subprocess
                    subprocess.Popen(["xdg-open", str(v)])
            except Exception as e:
                messagebox.showwarning("Check video", "Could not open the video: %s" % e, parent=self)

    def pick(self):
        fs = filedialog.askopenfilenames(parent=self, title="Pick the finished video (.wmv and/or the compiled .xnb)",
                                         filetypes=[("Videos", "*.wmv *.xnb *.asf *.mp4 *.webm *.avi *.mov"), ("All files", "*.*")])
        if not fs:
            return
        self.files = list(fs)
        stems = {Path(f).stem for f in fs}
        self.stem = re.sub(r"[^\w\-]+", "_", sorted(stems)[0]).strip("_") or "video"
        self.v["name"].set("%s  (%d file%s)" % (self.stem, len(fs), "" if len(fs) == 1 else "s"))
        bad = [Path(f).name for f in fs if Path(f).suffix.lower() in (".mp4", ".webm", ".avi", ".mov")]
        self.msg.configure(text=("The game cannot play %s directly - convert it to .wmv and compile the .xnb first (see the prompt)." % ", ".join(bad)) if bad else
                           "Ready. 'Use the video' copies the file(s) into the mod's Video folder when you Save.", fg="#e0b060" if bad else DIM)
        self.use_btn.configure(state="normal")
        self.chk_btn.configure(state="normal")

    def report(self):
        P = self.proj
        out = ["VIDEO REPORT  (%s)" % VERSION, ""]
        try:
            rows = P.library_scan()
        except Exception as e:
            rows = []
            out.append("library scan failed: %s" % e)
        for label, top, rel, ext, size, kinds in rows:
            if "video" not in kinds:
                continue
            line = "%-22s %-40s %10d B" % (label, rel, size)
            try:
                if ext == ".xnb":
                    raw = (top / rel).read_bytes()
                    i = xnb_video_parse(raw)
                    line += "   xnb: " + (("COMPRESSED (flags 0x%02x)" % raw[5]) if i.get("compressed") else ("path=%r %dx%d %.2f fps %d ms snd=%d" % (i["path"], i["width"], i["height"], i["fps"], i["ms"], i["snd"]) if i else "not a video xnb"))
                    line += "   head=" + raw[:48].hex()
                else:
                    inf = video_file_info(top / rel)
                    line += "   " + (str(inf) if inf else "(format not read)")
            except Exception as e:
                line += "   error: %s" % e
            out.append(line)
        d = Path(P.root) / BACKUP_DIR
        try:
            d.mkdir(parents=True, exist_ok=True)
            f = d / "video_report.txt"
            f.write_text("\n".join(out) + "\n", encoding="utf-8")
            self.msg.configure(text="Saved: %s  - send me this file." % f, fg=DIM)
        except OSError as e:
            self.msg.configure(text="Could not save the report: %s" % e, fg="#e07070")

    def ok(self):
        n, tmp = 0, None
        stem = self.stem
        vids = [Path(f) for f in self.files if Path(f).suffix.lower() != ".xnb"]
        have_xnb = any(Path(f).suffix.lower() == ".xnb" for f in self.files)
        if vids and not have_xnb:                                     # make the .xnb the game loads, from the layout of an existing one
            if self.template is None:
                messagebox.showwarning("Video", "No existing race video .xnb could be read here to copy the layout from, so the .xnb cannot be made automatically.\n\n"
                                       "The video file is added, but the game also needs its .xnb. Press 'Save a video report' and send me the file.", parent=self)
            else:
                v = vids[0]
                tpl = self.template[0].read_bytes()
                stored = xnb_video_parse(tpl)["path"]
                tail = Path(stored.replace("\\", "/")).suffix.lower()
                if tail and tail != v.suffix.lower():
                    messagebox.showwarning("Video", "The game's own race videos are %s files (their .xnb points at %r). Convert this video to %s first (the prompt has the ffmpeg line), then pick it again."
                                           % (tail, stored, tail), parent=self)
                    return
                info = video_file_info(v) or {}
                try:
                    sp = self.spec()
                    w = int(info.get("width") or sp["width"] or 0)
                    h = int(info.get("height") or sp["height"] or 0)
                    fps = float(info.get("fps") or sp["fps"] or 30)
                    secs = float(info.get("seconds") or sp["seconds"] or 0)
                except ValueError:
                    w = h = 0
                    fps, secs = 30.0, 0.0
                if not (w and h):
                    messagebox.showwarning("Video", "The picture size of this video could not be read - fill in Width and Height above and try again.", parent=self)
                    return
                head, _sep, last = stored.replace("\\", "/").rpartition("/")
                new_stored = (head + "/" if head else "") + stem + (Path(last).suffix if tail else "")
                if "\\" in stored and "/" not in stored:
                    new_stored = new_stored.replace("/", "\\")
                try:
                    data = rewrite_video_xnb(tpl, new_stored, secs * 1000, fps, w, h)
                    import tempfile
                    td = Path(tempfile.gettempdir()) / "balance_editor_video"
                    td.mkdir(parents=True, exist_ok=True)
                    tmp = td / (stem + ".xnb")
                    tmp.write_bytes(data)
                except (ValueError, OSError) as e:
                    messagebox.showwarning("Video", "The .xnb could not be made: %s" % e, parent=self)
                    return
        folder = Path(self.template[1]).parent.as_posix() if self.template is not None else "Video"
        folder = "Video" if folder in (".", "") else folder
        todo = [(Path(f), "%s/%s%s" % (folder, stem, Path(f).suffix.lower())) for f in self.files]
        if tmp is not None:
            todo.append((tmp, "%s/%s.xnb" % (folder, stem)))
        for src, rel in todo:
            try:
                _d, how = self.proj.stage_asset(src, rel, replace=True)
                n += how == "staged"
            except Exception as e:
                messagebox.showwarning("Video", "%s could not be added: %s" % (src.name, e), parent=self)
        self.result = stem
        self.staged = n
        self.destroy()


class AiAssetDialog(_Dialog):
    """Make a picture with an AI: copy the exact prompt, paste the AI's picture (or pick the file), it is fitted to the size the mod uses.
    result = ('__import', path of the fitted PNG)."""

    def __init__(self, master, proj, sub, name, about):
        super().__init__(master, "Make a picture with an AI - %s" % name)
        self.geometry("760x720")
        self.minsize(600, 560)
        self.proj, self.sub, self.name, self.src, self.out, self.photo = proj, sub, name, None, None, None
        sizes = ai_sizes(proj, sub)
        self.sizes = sizes
        self.siblings = [s for s, _p, _o in proj.texture_choices(sub)[:8]]
        self.about = about
        bt = tk.Frame(self, bg=PANEL)
        bt.pack(side="bottom", fill="x", padx=14, pady=10)
        self.use_btn = ttk.Button(bt, text="Use this picture", command=self.ok, state="disabled")
        self.use_btn.pack(side="right")
        ttk.Button(bt, text="Cancel", command=self.destroy).pack(side="right", padx=8)
        B = tk.Frame(self, bg=PANEL)
        B.pack(fill="both", expand=True, padx=14, pady=(10, 0))
        tk.Label(B, text="1.  Copy this prompt and paste it into any AI that makes pictures (Gemini, ChatGPT ...).  Edit it first if you like.",
                 bg=PANEL, fg=FG, anchor="w", justify="left", wraplength=700).pack(fill="x")
        r = tk.Frame(B, bg=PANEL)
        r.pack(fill="x", pady=4)
        tk.Label(r, text="Size", bg=PANEL, fg=DIM).pack(side="left")
        dw, dh = sizes[0][0] if sizes else (64, 64)
        self.vw, self.vh = tk.StringVar(value=str(dw)), tk.StringVar(value=str(dh))
        for v in (self.vw, self.vh):
            e = ttk.Entry(r, textvariable=v, width=5)
            e.pack(side="left", padx=3)
            v.trace_add("write", lambda *_: self.rebuild())
        tk.Label(r, text="px   (the pictures already in %s are mostly %s)" % (sub, ", ".join("%dx%d" % s for s, _c in sizes[:3]) or "unknown"),
                 bg=PANEL, fg=DIM).pack(side="left", padx=6)
        self.note = tk.StringVar()
        ttk.Entry(B, textvariable=self.note).pack(fill="x", pady=(0, 4))
        self.note.trace_add("write", lambda *_: self.rebuild())
        self.t = tk.Text(B, height=11, wrap="word", **TEXT_OPTS)
        self.t.pack(fill="x")
        bb = tk.Frame(B, bg=PANEL)
        bb.pack(fill="x", pady=4)
        ttk.Button(bb, text="Copy prompt", command=self.copy).pack(side="left")
        tk.Label(bb, text="(the box above is a note for the AI, e.g. 'blue glow, red hull')", bg=PANEL, fg=DIM).pack(side="left", padx=8)
        tk.Label(B, text="2.  Bring the AI's picture back:  copy the picture in the AI's window (right-click > Copy image) and press Paste, or save it and pick the file.",
                 bg=PANEL, fg=FG, anchor="w", justify="left", wraplength=700).pack(fill="x", pady=(10, 2))
        b2 = tk.Frame(B, bg=PANEL)
        b2.pack(fill="x")
        ttk.Button(b2, text="Paste picture from clipboard", command=self.paste).pack(side="left")
        ttk.Button(b2, text="Pick a picture file…", command=self.pick).pack(side="left", padx=6)
        o = tk.Frame(B, bg=PANEL)
        o.pack(fill="x", pady=4)
        self.fit = tk.StringVar(value=AI_FIT_MODES[1] if sub.lower() in ("portraits", "races", "shipicons", "flags") else AI_FIT_MODES[0])
        cb = ttk.Combobox(o, textvariable=self.fit, values=AI_FIT_MODES, state="readonly", width=30)
        cb.pack(side="left")
        cb.bind("<<ComboboxSelected>>", lambda _e: self.render())
        self.key = tk.BooleanVar(value=True)
        ck = ttk.Checkbutton(o, text="Make a plain background transparent", variable=self.key, command=self.render)
        ck.pack(side="left", padx=10)
        tip(ck, "AIs often give a solid background. This removes a background of one flat colour (from the corners inward).")
        self.note_lbl = tk.Label(B, bg=PANEL, fg=PEACH, anchor="w", justify="left", wraplength=700,
                                 text="" if Image else "A required Python plugin (Pillow) is not installed, so pictures cannot be pasted, resized or have a background removed: pick a ready .png file.")
        self.note_lbl.pack(fill="x")
        if not Image:
            self.inst_btn = ttk.Button(B, text="Install required Python plugin (Pillow) - needs internet, one time", command=self.install)
            self.inst_btn.pack(anchor="w", pady=2)
            tip(self.inst_btn, "Runs  python -m pip install pillow  for you. It adds pasting, resizing and background removal to the editor. Restart the editor afterwards "
                               "so every part of it can use it.")
        self.prev = tk.Label(B, bg="#202028", text="(no picture yet)", fg=DIM)
        self.prev.pack(fill="both", expand=True, pady=6)
        self.rebuild()
        self.show()

    def size(self):
        try:
            return max(8, min(2048, int(self.vw.get()))), max(8, min(2048, int(self.vh.get())))
        except ValueError:
            return (64, 64)

    def rebuild(self):
        txt = ai_icon_prompt(self.about or "Name: %s" % self.name, self.sub, self.size(), self.siblings)
        n = self.note.get().strip() if hasattr(self, "note") else ""
        if n:
            txt = ai_icon_prompt(self.about or "Name: %s" % self.name, self.sub, self.size(), self.siblings, n)
        self.t.delete("1.0", "end")
        self.t.insert("1.0", txt)

    def copy(self):
        self.clipboard_clear()
        self.clipboard_append(self.t.get("1.0", "end-1c"))
        self.master.winfo_toplevel().update()
        try:
            self.prev.configure(text="Prompt copied. Paste it into the AI." if self.src is None else self.prev.cget("text"))
        except Exception:
            pass

    def paste(self):
        if not Image:
            messagebox.showinfo("Paste", "Pasting a picture needs the Pillow package. Save the AI's picture as a .png and use 'Pick a picture file' instead, "
                                         "or install Pillow (in a command window:  py -m pip install pillow ).", parent=self)
            return
        try:
            from PIL import ImageGrab
            got = ImageGrab.grabclipboard()
        except Exception as e:
            messagebox.showwarning("Paste", "Could not read a picture from the clipboard here (%s). Save the picture and use 'Pick a picture file'." % e, parent=self)
            return
        if got is None:
            messagebox.showinfo("Paste", "There is no picture on the clipboard. In the AI's window right-click the picture and choose 'Copy image', then press Paste again.", parent=self)
            return
        if isinstance(got, list):                       # files copied in Explorer
            try:
                got = Image.open(got[0])
            except Exception as e:
                messagebox.showwarning("Paste", "That file is not a picture: %s" % e, parent=self)
                return
        self.src = got
        self.render()

    def pick(self):
        f = filedialog.askopenfilename(parent=self, title="Pick the AI's picture", filetypes=[("Pictures", "*.png *.jpg *.jpeg *.webp *.bmp *.gif"), ("All files", "*.*")])
        if not f:
            return
        if not Image:                                     # no Pillow: use a PNG as it is
            self.plain(f)
            return
        try:
            self.src = Image.open(f)
            self.src.load()
        except Exception as e:
            messagebox.showwarning("Picture", "Could not open that file: %s" % e, parent=self)
            return
        self.render()

    def install(self):
        self.inst_btn.configure(state="disabled", text="Installing ... (this can take a minute)")
        box = {}

        def done(ok, text):
            box["r"] = (ok, text)

        def poll():
            if "r" not in box:
                self.after(500, poll)
                return
            ok, text = box["r"]
            if ok:
                self.inst_btn.configure(text="Python plugin installed")
                self.note_lbl.configure(text="The Python plugin is installed: pasting, resizing and background removal work now. Restart the editor when convenient so every tab uses it.")
            else:
                self.inst_btn.configure(state="normal", text="Install required Python plugin (Pillow) - needs internet, one time")
                messagebox.showwarning("Install Python plugin", "The install did not work:\n\n%s\n\nTry in a command window:  py -m pip install pillow" % text, parent=self)
        install_pillow(done)
        self.after(500, poll)

    def plain(self, f):
        """Without Pillow the picture cannot be resized or have its background removed: a .png is used exactly as it is."""
        sz = png_size(f)
        if sz is None:
            messagebox.showwarning("Picture", "Without the Pillow package only .png pictures can be used (this one is not a PNG).\nSave the AI's picture as a .png, "
                                              "or install Pillow (in a command window:  py -m pip install pillow ).", parent=self)
            return
        want = self.size()
        msg = "Using the picture as it is (%dx%d)." % sz
        if tuple(sz) != tuple(want):
            msg += "  The mod's pictures here are %dx%d - resize it first (any paint program) or install Pillow so the editor does it for you." % want
        try:
            ph = tk.PhotoImage(file=f)
            k = max(1, int(math.ceil(max(ph.width(), ph.height()) / 240.0)))
            self.photo = ph.subsample(k, k) if k > 1 else ph
            self.prev.configure(image=self.photo, text="")
        except Exception:
            self.prev.configure(text="Picture chosen.", image="")
        self.info_txt = msg
        self.note_lbl.configure(text=msg)
        self.plain_path = f
        self.use_btn.configure(state="normal")

    def render(self):
        if self.src is None or not Image:
            return
        try:
            self.out = ai_fit(self.src, self.size(), self.fit.get() == AI_FIT_MODES[0], self.key.get())
        except Exception as e:
            self.prev.configure(text="Could not process the picture: %s" % e, image="")
            return
        try:
            from PIL import ImageTk
            bg = Image.new("RGBA", self.out.size, (32, 32, 40, 255))
            bg.alpha_composite(self.out)
            k = max(1, min(6, 240 // max(self.out.size)))
            big = bg.resize((self.out.width * k, self.out.height * k), Image.NEAREST)
            self.photo = ImageTk.PhotoImage(big)
            self.prev.configure(image=self.photo, text="")
        except Exception:
            self.prev.configure(text="Picture ready (%dx%d)." % self.out.size)
        self.use_btn.configure(state="normal")

    def ok(self):
        import tempfile
        if not Image:
            if getattr(self, "plain_path", None):
                self.result = ("__import", self.plain_path)
                self.destroy()
            return
        if self.out is None:
            return
        d = Path(tempfile.mkdtemp(prefix="sd_ai_"))
        f = d / (re.sub(r"\W+", "_", self.name).strip("_") or "picture")
        f = f.with_suffix(".png")
        self.out.save(f)
        self.result = ("__import", str(f))
        self.destroy()


def ai_style_examples(proj, m, n=4):
    """Descriptions of other modules of the same type, to copy the tone and length from."""
    out = []
    try:
        mt = m.get("ModuleType").strip()
        for o in proj.modules:
            if o is m or o.get("ModuleType").strip() != mt:
                continue
            d = (o.get("Description").strip() or "")
            if not d:
                e = proj.text_display(o, "DescriptionIndex")
                d = e.get("ENG").strip() if e else ""
            if d:
                out.append(d)
            if len(out) >= n:
                break
    except Exception:
        pass
    return out


def ai_text_prompt(task, about, examples, extra="", rules=None):
    s = ["Task: " + task, "", "Game: " + AI_GAME, "", "About the item:", about or "(nothing)", ""]
    if examples:
        s.append("Existing examples to match in tone and length:")
        s += ['- "%s"' % e.replace("\n", " ")[:260] for e in examples]
        s.append("")
    if rules is None:
        s += ["Rules:", "- Plain text only, no markdown, no quotation marks around it, no explanations.",
              "- Match the tone and length of the examples. Star Trek flavour is welcome but do not copy real episode text.",
              "- Do not invent numbers: if a stat is mentioned it must be one of the facts above."]
    else:
        s += list(rules)
    if extra.strip():
        s += ["", "Extra notes: " + extra.strip()]
    if rules is None:
        s += ["", "Reply with only the text."]
    return "\n".join(s)


class AiTextDialog(_Dialog):
    """Copy a prompt into any AI, paste its answer back, and (when apply is given) put the text into the item.
    apply(text) is called by 'Use this text'; without it the dialog is for reading the answer only."""

    def __init__(self, master, title, task, about, examples=(), apply=None, apply_label="Use this text", limit=0, rules=None):
        super().__init__(master, title)
        self.geometry("740x700")
        self.minsize(560, 520)
        self.task, self.about, self.examples, self.apply_cb, self.limit, self.rules = task, about, list(examples), apply, limit, rules
        bt = tk.Frame(self, bg=PANEL)
        bt.pack(side="bottom", fill="x", padx=14, pady=10)
        ttk.Button(bt, text="Close", command=self.destroy).pack(side="right")
        if apply:
            self.use_btn = ttk.Button(bt, text=apply_label, command=self.use)
            self.use_btn.pack(side="right", padx=8)
        B = tk.Frame(self, bg=PANEL)
        B.pack(fill="both", expand=True, padx=14, pady=(10, 0))
        tk.Label(B, text="1.  Copy this prompt into any AI (Gemini, Claude, ChatGPT ...).", bg=PANEL, fg=FG, anchor="w").pack(fill="x")
        self.note = tk.StringVar()
        r = tk.Frame(B, bg=PANEL)
        r.pack(fill="x", pady=4)
        tk.Label(r, text="Extra notes for the AI", bg=PANEL, fg=DIM).pack(side="left")
        e = ttk.Entry(r, textvariable=self.note)
        e.pack(side="left", fill="x", expand=True, padx=6)
        self.note.trace_add("write", lambda *_: self.rebuild())
        self.t = tk.Text(B, height=14, wrap="word", **TEXT_OPTS)
        self.t.pack(fill="both", expand=True)
        ttk.Button(B, text="Copy prompt", command=self.copy).pack(anchor="w", pady=4)
        tk.Label(B, text="2.  Paste the AI's answer here." if apply else "2.  Paste the AI's answer here to keep it next to the finding (optional).",
                 bg=PANEL, fg=FG, anchor="w").pack(fill="x", pady=(8, 2))
        self.reply = tk.Text(B, height=8, wrap="word", undo=True, **TEXT_OPTS)
        self.reply.pack(fill="both", expand=True)
        self.info = tk.Label(B, text="", bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=680)
        self.info.pack(fill="x", pady=4)
        self.reply.bind("<KeyRelease>", lambda _e: self.check())
        self.rebuild()
        self.show()

    def rebuild(self):
        self.t.delete("1.0", "end")
        self.t.insert("1.0", ai_text_prompt(self.task, self.about, self.examples, self.note.get(), self.rules))

    def copy(self):
        self.clipboard_clear()
        self.clipboard_append(self.t.get("1.0", "end-1c"))
        self.info.configure(text="Prompt copied. Paste it into the AI.")

    def text(self):
        return self.reply.get("1.0", "end-1c").strip().strip('"').strip()

    def check(self):
        t = self.text()
        msg = []
        if self.limit and len(t) > self.limit:
            msg.append("Longer than the existing ones (%d characters, they are up to about %d) - it may not fit on screen." % (len(t), self.limit))
        if re.search(r"[*#`]", t):
            msg.append("Contains markdown characters (* # `) - remove them.")
        if "\n\n\n" in t:
            msg.append("Has blank lines.")
        self.info.configure(text="%d characters.  %s" % (len(t), " ".join(msg)))

    def use(self):
        t = self.text()
        if not t:
            messagebox.showinfo("AI text", "Paste the AI's answer into the lower box first.", parent=self)
            return
        self.apply_cb(t)
        self.destroy()



class IconDialog(_Dialog):
    """Pick a different picture for a tech / module / building. result = (key, path): an existing picture's name, '__import' or '__keep'."""

    def __init__(self, master, proj, title, sub, current, note, name="", about=""):
        super().__init__(master, title)
        self.geometry("720x600")
        self.minsize(560, 420)
        self.proj, self.sub, self.name, self.about = proj, sub, name, about
        bt = tk.Frame(self, bg=PANEL)
        bt.pack(side="bottom", fill="x", padx=14, pady=10)
        ttk.Button(bt, text="Use this picture", command=self.ok).pack(side="right")
        ttk.Button(bt, text="Cancel", command=self.destroy).pack(side="right", padx=8)
        self.picker = PicPicker(self, proj, master, sub, [("__keep", "(keep the current picture)")], default=current, note=note,
                                 name=name, about=about)
        self.picker.pack(fill="both", expand=True, padx=14, pady=(12, 0))
