class BonusDialog(tk.Toplevel):
    """Add / change an upgrade of a tech (BonusUnlocked > UnlockedBonus). result = (Name, BonusType, Bonus, description text) or None."""

    def __init__(self, master, proj, tech, types, bonus=None):
        super().__init__(master)
        self.result = None
        self.title("Upgrade" if bonus is None else "Edit upgrade")
        self.configure(bg=PANEL)
        self.transient(master)
        f = tk.Frame(self, bg=PANEL)
        f.pack(fill="both", expand=True, padx=14, pady=12)
        e = None
        if bonus is not None:
            ix = bonus_get(bonus, "BonusIndex")
            e = proj.text_display_by_id(int(ix)) if ix.isdigit() else None
        self.v_name = tk.StringVar(value=bonus_get(bonus, "Name") if bonus else "")
        self.v_type = tk.StringVar(value=bonus_get(bonus, "BonusType") if bonus else "")
        self.v_amt = tk.StringVar(value=bonus_get(bonus, "Bonus") if bonus else "")
        rows = (("Name", ttk.Entry(f, textvariable=self.v_name, width=44),
                 "<Name>: the upgrade's name, e.g. Hull Strengthening."),
                ("Bonus type", ttk.Combobox(f, textvariable=self.v_type, values=types, width=42),
                 "<BonusType>: what the upgrade changes, e.g. Module HP Bonus, FTL Speed Bonus, Weapon_Damage. The list holds every type already used "
                 "by the techs; typing a new one only works if the game knows it."),
                ("Amount", ttk.Entry(f, textvariable=self.v_amt, width=12),
                 "<Bonus>: the size of the bonus, e.g. 0.3 = +30%. Leave empty for upgrades that are just a switch (e.g. Allow Assimilation)."))
        for r, (lab, w, hint) in enumerate(rows):
            lb = tk.Label(f, text=lab, bg=PANEL, fg=FG)
            lb.grid(row=r, column=0, sticky="w", pady=3)
            w.grid(row=r, column=1, sticky="we", padx=8)
            tip(lb, hint)
            tip(w, hint)
        tk.Label(f, text="Description shown in game (GameText, BonusIndex)", bg=PANEL, fg=FG).grid(row=3, column=0, columnspan=2, sticky="w", pady=(8, 0))
        self.t = tk.Text(f, height=4, width=52, wrap="word", **TEXT_OPTS)
        self.t.grid(row=4, column=0, columnspan=2, sticky="we")
        self.t.insert("1.0", e.get("ENG") if e is not None else "")
        if bonus is None or e is None:
            note = "A new GameText entry is created for it when you Save." if bonus is None else "No GameText entry found for this one; typing text creates a new one."
        else:
            note = "Changing the text edits that GameText entry (Id %s)." % bonus_get(bonus, "BonusIndex")
        tk.Label(f, text=note, bg=PANEL, fg=DIM, wraplength=420, justify="left").grid(row=5, column=0, columnspan=2, sticky="w", pady=(2, 8))
        bf = tk.Frame(f, bg=PANEL)
        bf.grid(row=6, column=0, columnspan=2, sticky="e")
        ttk.Button(bf, text="OK", command=self.ok).pack(side="left", padx=4)
        ttk.Button(bf, text="Cancel", command=self.destroy).pack(side="left")
        self.bind("<Escape>", lambda _e: self.destroy())
        try:
            self.grab_set()
        except tk.TclError:
            pass

    def ok(self):
        a = self.v_amt.get().strip()
        if a:
            try:
                float(a)
            except ValueError:
                messagebox.showwarning("Upgrade", "Amount must be a number (e.g. 0.3), or empty.", parent=self)
                return
        if not self.v_type.get().strip() and not self.v_name.get().strip():
            messagebox.showwarning("Upgrade", "Give the upgrade a name or a bonus type.", parent=self)
            return
        self.result = (self.v_name.get().strip(), self.v_type.get().strip(), a, self.t.get("1.0", "end").strip())
        self.destroy()


class UnlockDialog(PickDialog):
    """Choose modules and the race(s) a tech unlocks them for. result = [(module uid, race type)]"""

    ALL, NONE = "All races used by the techs", "(no race given)"

    def __init__(self, master, proj, tech):
        rows = []
        for m in sorted(proj.modules, key=lambda m: module_name(proj, m).lower()):
            uid = (m.get("UID") or m.path.stem).strip()
            rows.append((uid, "%s   [%s]   %s" % (module_name(proj, m), m.get("ModuleType").strip() or "-", uid)))
        by_uid = {(m.get("UID") or m.path.stem).strip(): m for m in proj.modules}
        owner = master if hasattr(master, "img") else None
        super().__init__(master, "Unlock modules", "Pick the module(s) this tech should unlock (filter by typing), then the race. "
                         "Rest the pointer on a module to see its stats.", rows, multi=True,
                         icons=lambda u: (owner.img(proj.module_pic(by_uid[u]), 36) if owner and u in by_uid and proj.module_pic(by_uid[u]) else
                                          (owner.blank if owner else None)),
                         details=lambda u: module_tip(proj, by_uid[u]) if u in by_uid else "")
        seen, self.types = set(), []
        for t in proj.techs:
            for _m, ty in t.unlocks:
                if ty and ty.lower() not in seen:
                    seen.add(ty.lower())
                    self.types.append(ty)
        lr = tk.Label(self.opts, text="Race", bg=PANEL, fg=FG)
        lr.grid(row=0, column=0, sticky="w", pady=4)
        self.race = tk.StringVar(value=self.ALL)
        cbr = ttk.Combobox(self.opts, textvariable=self.race, state="readonly", width=34, values=[self.ALL, self.NONE] + self.types)
        cbr.grid(row=0, column=1, padx=8)
        for w in (lr, cbr):
            tip(w, "Which race gets the module from this tech (the <Type> of the unlock). 'All races' adds one entry per race the techs "
                   "already use; 'no race given' adds an entry without a Type.")
        tk.Label(self.opts, text="Or a module UID not listed (e.g. a base-game module)", bg=PANEL, fg=DIM).grid(
            row=1, column=0, columnspan=2, sticky="w")
        self.extra = tk.StringVar()
        ex = ttk.Entry(self.opts, textvariable=self.extra, width=40)
        ex.grid(row=2, column=0, columnspan=2, sticky="w", pady=(0, 4))
        tip(ex, "For a module that isn't in this mod's ShipModules (for example a base-game module): type its exact UID.")
        self.show()

    def ok(self):
        uids = self.picked()
        x = self.extra.get().strip()
        if x:
            uids.append(x)
        r = self.race.get()
        types = self.types if r == self.ALL else ([""] if r == self.NONE else [r])
        self.result = [(u, ty) for u in uids for ty in (types or [""])]
        self.destroy()


class UnlockedDialog(PickDialog):
    """The modules and ships a tech already unlocks, with their pictures; hover for stats; select rows and Remove to take them out."""

    def __init__(self, master, proj, tech):
        self.proj, self.tech, self.removed = proj, tech, 0
        self.by_uid = {(m.get("UID") or m.path.stem).strip().lower(): m for m in proj.modules}
        owner = master if hasattr(master, "img") else None
        super().__init__(master, "Unlocked by %s" % proj.tech_name(tech),
                         "%s unlocks these. Rest the pointer on a module to see its stats; select rows and press Remove to take them out "
                         "(nothing is deleted from disk)." % proj.tech_name(tech), self.make_rows(), multi=True,
                         icons=lambda k: self.icon(owner, k), details=self.detail)
        ttk.Button(self.opts, text="Remove selected", command=self.remove).grid(row=0, column=0, sticky="w", pady=4)

    def make_rows(self):
        P, rows = self.proj, []
        for i, (mu, ty) in enumerate(self.tech.unlocks):
            m = self.by_uid.get(mu.lower())
            rows.append(("m%d" % i, "%s   [%s]   %s   -   %s" % (module_name(P, m) if m else "(not in this mod)",
                                                                  (m.get("ModuleType").strip() if m else "") or "-", mu, ty or "any race")))
        for i, hn in enumerate(self.tech.hulls):
            info = P.hull_info(hn)
            rows.append(("h%d" % i, "%s   [ship]   %s" % ((info.get("visible") if info else "") or hn, hn)))
        return rows

    def icon(self, owner, k):
        if owner is None:
            return None
        P = self.proj
        if k[0] == "m":
            mu = self.tech.unlocks[int(k[1:])][0]
            m = self.by_uid.get(mu.lower())
            pic = P.module_pic(m) if m is not None else (P.find_file("TechIcons/" + mu) or P.find_file("Modules/" + mu))
        else:
            info = P.hull_info(self.tech.hulls[int(k[1:])])
            pic = P.find_file(info.get("icon")) if info and info.get("icon") else None
        return (owner.img(pic, 36) if pic else None) or owner.blank

    def detail(self, k):
        if k[0] != "m":
            return "A ship hull this tech unlocks (edited in the hull files)."
        mu = self.tech.unlocks[int(k[1:])][0]
        m = self.by_uid.get(mu.lower())
        return module_tip(self.proj, m) if m is not None else "%s is not a module of this mod (a base-game module?)." % mu

    def remove(self):
        keys = [k for k in self.picked() if k[0] == "m"]
        if not keys:
            return
        for i in sorted((int(k[1:]) for k in keys), reverse=True):
            del self.tech.unlocks[i]
            self.removed += 1
        self.rows = self.make_rows()
        self.fill()


class NewModuleDialog(_Dialog):
    """Create a module from a blank template (or as a copy of an existing one) and, optionally, unlock it with a tech."""
    NO_TECH, NO_BASE, NO_WEAPON = "(none - unlock it later)", "(blank template)", "(none)"

    def __init__(self, master, proj, folder_hint=""):
        super().__init__(master, "New module")
        self.proj = proj
        types = sorted({m.get("ModuleType").strip() for m in proj.modules if m.get("ModuleType").strip()}, key=str.lower)
        self.tech_by_label = {}
        for t in sorted(proj.techs, key=lambda t: proj.tech_name(t).lower()):
            self.tech_by_label["%s  (%s)  [%s]" % (proj.tech_name(t), t.uid, proj.tech_category(t))] = t
        self.base_by_label = {}
        for m in sorted(proj.modules, key=lambda m: module_name(proj, m).lower()):
            self.base_by_label["%s  (%s)" % (module_name(proj, m), (m.get("UID") or m.path.stem).strip())] = m
        weapons = sorted({(w.get("UID") or w.path.stem).strip() for w in proj.weapons}, key=str.lower)
        self.v = {k: tk.StringVar(value=val) for k, val in (
            ("uid", "New_Module"), ("name", "New module"), ("type", types[0] if types else "Turret"), ("x", "1"), ("y", "1"),
            ("folder", folder_hint), ("base", self.NO_BASE), ("weapon", self.NO_WEAPON), ("tech", self.NO_TECH),
            ("race", UnlockDialog.ALL))}
        rows = (("UID (file name)", "uid", None, 46), ("Name in game", "name", None, 46),
                ("Module type", "type", types, 44), ("Width (XSize)", "x", None, 6), ("Height (YSize)", "y", None, 6),
                ("Folder (under %s)" % proj.module_root().name, "folder", proj.module_folders(), 44),
                ("Start from", "base", [self.NO_BASE] + list(self.base_by_label), 44),
                ("Weapon file (WeaponType)", "weapon", [self.NO_WEAPON] + weapons, 44),
                ("Unlocked by tech", "tech", [self.NO_TECH] + list(self.tech_by_label), 44),
                ("…for race", "race", [UnlockDialog.ALL, UnlockDialog.NONE] + proj.unlock_types(), 44))
        hints = {
            "uid": TIP_MOD_UID, "name": "The name shown in game. Stored in GameText.yaml as BB_Module_<UID>_Name.",
            "type": "ModuleType: what kind of module it is (Turret, PowerPlant, Shield, Engine ...). Decides which stats matter.",
            "x": "XSize: how many ship-grid squares wide the module is.", "y": "YSize: how many ship-grid squares tall the module is.",
            "folder": "Where the xml file goes, under the modules folder. Type a new name to create a new folder when you Save.",
            "base": "Copy an existing module's file (all its stats) instead of starting from the blank template.",
            "weapon": "WeaponType: the Weapons file (its UID) this module fires. Leave (none) for non-weapon modules.",
            "tech": "Add the module to this tech's unlock list now, so the research tree gives it to players.",
            "race": "Which race gets the module from that tech: all races the techs already use, one race, or none given."}
        for r, (lab, key, vals, wd) in enumerate(rows):
            self.label(r, lab, hints.get(key))
            if vals is None:
                w = ttk.Entry(self, textvariable=self.v[key], width=wd)
            else:
                w = IconCombo(self, textvariable=self.v[key], values=vals, width=wd - 3,
                                 state="readonly" if key in ("base", "tech", "race", "weapon") else "normal")
            w.grid(row=r, column=1, sticky="w", padx=(0, 14), pady=3)
            if hints.get(key):
                tip(w, hints[key])
            if key == "uid":
                w.focus_set()
        n = len(rows)
        self.label(n, "Description", "Shown in game under the module name. Stored in GameText.yaml as BB_Module_<UID>_Desc.")
        self.desc = tk.Text(self, width=46, height=3, wrap="word", **TEXT_OPTS)
        self.desc.grid(row=n, column=1, padx=(0, 14), pady=3)
        tk.Label(self, bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=470,
                 text="A new folder name is created when you Save. The icon is looked up as Textures\\Modules\\<UID> - add that image "
                      "yourself. Costs, mass, health and the other stats start at safe placeholders: set them in the table afterwards."
                 ).grid(row=n + 1, column=0, columnspan=2, sticky="w", padx=14, pady=4)
        bt = tk.Frame(self, bg=PANEL)
        bt.grid(row=n + 2, column=0, columnspan=2, sticky="e", padx=14, pady=(4, 12))
        ttk.Button(bt, text="Cancel", command=self.destroy).pack(side="right", padx=(6, 0))
        ttk.Button(bt, text="Create", command=self.ok).pack(side="right")
        self.show()

    def ok(self):
        v = {k: x.get() for k, x in self.v.items()}
        base = self.base_by_label.get(v["base"])
        weapon = "" if v["weapon"] == self.NO_WEAPON else v["weapon"]
        try:
            doc = self.proj.new_module(v["uid"], v["name"], self.desc.get("1.0", "end").strip(), v["type"], v["x"], v["y"],
                                       v["folder"], weapon, base)
        except ValueError as e:
            messagebox.showwarning("New module", str(e), parent=self)
            return
        t = self.tech_by_label.get(v["tech"])
        if t is not None:
            uid = v["uid"].strip()
            r = v["race"]
            types = self.proj.unlock_types() if r == UnlockDialog.ALL else ([""] if r == UnlockDialog.NONE else [r])
            for ty in types or [""]:
                if (uid, ty) not in t.unlocks:
                    t.unlocks.append((uid, ty))
        self.result = doc
        self.destroy()


class WeaponPreview(tk.Frame):
    """A small animated sample of what a weapon looks like in flight: its projectile picture / animation frames travelling from a gun to a
    target (speed, size and effects taken from the weapon's tags), or its beam. spec = {tag: value}. Pictures the editor can't read
    (.xnb) are replaced by a placeholder."""
    W, H = 460, 230

    def __init__(self, master, proj, owner):
        super().__init__(master, bg=PANEL)
        self.proj, self.owner, self.spec, self.frames, self.beam_img = proj, owner, {}, [], None
        self.n, self.job, self.cache, self.keep = 0, None, {}, []
        tk.Label(self, text="Sample - what it looks like", bg=PANEL, fg=PEACH, anchor="w").pack(fill="x")
        self.cv = tk.Canvas(self, width=self.W, height=self.H, bg="#05070d", highlightthickness=1, highlightbackground=EDGE)
        self.cv.pack()
        self.cap = tk.Label(self, bg=PANEL, fg=DIM, wraplength=self.W, justify="left", anchor="w", font=("Segoe UI", 8))
        self.cap.pack(fill="x", pady=(3, 0))
        self.bind("<Destroy>", lambda e: self.stop() if e.widget is self else None)
        self.set({})
        self.run()

    def stop(self):
        if self.job is not None:
            try:
                self.after_cancel(self.job)
            except Exception:
                pass
            self.job = None

    def run(self):
        try:
            self.tick()
            self.job = self.after(70, self.run)
        except tk.TclError:
            self.job = None

    def num(self, key, default):
        try:
            return float(str(self.spec.get(key, "")).strip())
        except ValueError:
            return default

    def pic(self, path, size, stretch=None):
        """A PhotoImage of the picture, turned so its top points right (projectile art is drawn pointing up), or stretched to a beam."""
        key = (str(path), size, stretch)
        if key in self.cache:
            return self.cache[key]
        im = None
        if Image is not None and ImageTk is not None:
            try:
                pil = pil_open(path).convert("RGBA")
                if stretch:
                    pil = pil.rotate(-90, expand=True) if pil.height > pil.width else pil
                    pil = pil.resize((max(2, stretch[0]), max(2, stretch[1])))
                else:
                    if pil.height > pil.width:
                        pil = pil.rotate(-90, expand=True)
                    k = size / float(max(pil.size))
                    pil = pil.resize((max(1, int(pil.width * k)), max(1, int(pil.height * k))))
                im = ImageTk.PhotoImage(pil)
            except Exception:
                im = None
        if im is None and not stretch:
            im = self.owner.img(path, size)
        self.cache[key] = im
        return im

    def find_frames(self):
        sp, P = self.spec, self.proj
        ap = str(sp.get("AnimationPath", "")).strip().replace("\\", "/")
        n = int(self.num("Frames", 1))
        if ap:
            for fmt in ("%05d", "%04d", "%03d", "%02d", "%d"):
                if P.find_file(ap + fmt % 0):
                    out = [P.find_file(ap + fmt % i) for i in range(max(1, n))]
                    return [x for x in out if x]
        for tag in ("ProjectileTexturePath",):
            v = str(sp.get(tag, "")).strip()
            hits = [h for h in P.find_by_name(v) if h.suffix.lower() in P.img_exts()] if v else []
            if hits:
                return [hits[0]]
        return []

    def set(self, spec):
        self.spec = dict(spec)
        self.frames = self.find_frames()
        v = str(self.spec.get("BeamTexture", "")).strip()
        hits = [h for h in self.proj.find_by_name(v) if h.suffix.lower() in self.proj.img_exts()] if v else []
        self.beam_img = hits[0] if hits else None
        self.beam = str(self.spec.get("IsBeam", "")).strip().lower() in ("true", "1") or bool(v)
        self.n = 0
        if self.beam:
            what = "Beam" + (": texture %s" % v if v else "")
            if v and not self.beam_img:
                what += " (not a picture this editor can show - drawn as a plain beam)"
        elif self.frames:
            what = "Animation, %d frame(s)" % len(self.frames) if len(self.frames) > 1 else "Picture: %s" % self.frames[0].name
        else:
            what = "No picture found for the projectile (the game may use a file this editor can't read) - showing a placeholder"
        snd = str(self.spec.get("FireCueName", "")).strip()
        self.cap.configure(text=what + (("   ·   fire sound: %s" % snd) if snd else ""))

    def tick(self):
        cv, W, H = self.cv, self.W, self.H
        k = H / 130.0                                           # everything was designed at 130 px high
        cv.delete("all")
        self.n += 1
        cy, gx, tx = H // 2, int(34 * k), W - int(26 * k)
        cv.create_rectangle(4, cy - 12 * k, gx - 8 * k, cy + 12 * k, fill="#2a3350", outline=EDGE)
        cv.create_rectangle(gx - 8 * k, cy - 4 * k, gx + 2 * k, cy + 4 * k, fill="#3a4670", outline=EDGE)
        cv.create_rectangle(tx, cy - 36 * k, tx + 14 * k, cy + 36 * k, fill="#1b2238", outline="#4a5578")
        travel = tx - gx - 10 * k
        scale = max(0.3, self.num("Scale", 1.0))
        rad = max(4.0, self.num("ProjectileRadius", 10.0))
        if self.beam:
            cycle = 46
            ph = self.n % cycle
            if ph < 36:
                length = min(int(travel), int(travel * min(1.0, ph / 5.0)))
                th = int(max(3, min(22, self.num("BeamThickness", 12) / 3.0)) * k)
                img = self.pic(self.beam_img, 0, (length, th)) if self.beam_img and length > 4 else None
                if img is not None:
                    cv.create_image(gx + 2 * k, cy, image=img, anchor="w")
                else:
                    cv.create_line(gx + 2 * k, cy, gx + 2 * k + length, cy, fill="#3a2a10", width=th + 6)
                    cv.create_line(gx + 2 * k, cy, gx + 2 * k + length, cy, fill="#ffb347", width=th)
                    cv.create_line(gx + 2 * k, cy, gx + 2 * k + length, cy, fill="#ffffff", width=max(1, th // 3))
                if length >= travel:
                    r = (6 + (ph % 4) * 2) * k
                    cv.create_oval(tx - r, cy - r, tx + r, cy + r, outline="#ffb347", width=2)
            return
        speed = max(3.0, min(16.0, self.num("ProjectileSpeed", 4000.0) / 500.0)) * k
        cycle = int(travel / speed) + 12
        st = self.n % cycle
        x = gx + st * speed
        if st < 3:
            cv.create_oval(gx - 4 * k, cy - 8 * k, gx + 14 * k, cy + 8 * k, fill="#ffd27f", outline="")
        if x < tx:
            size = int(max(18, min(70, rad * 3 * scale)) * k)
            if self.frames:
                img = self.pic(self.frames[(self.n // 2) % len(self.frames)], size)
                if img is not None:
                    cv.create_image(x, cy, image=img)
                    return
            r = max(4, int(rad * 0.7 * scale * k))
            cv.create_line(x - r * 4, cy, x, cy, fill="#7a5a20", width=max(1, r // 2))
            cv.create_oval(x - r, cy - r, x + r, cy + r, fill="#ffb347", outline="#fff2cc")
        else:
            r = int((6 + (st - int((tx - gx) / speed)) * 3 + min(30, self.num("ExplosionRadius", 40) / 5.0)) * k)
            cv.create_oval(tx - r, cy - r, tx + r, cy + r, outline="#ffb347", width=2)


class PicPicker(tk.Frame):
    """A filterable list of the pictures already in a Textures sub-folder (mod first, then base game), each with its thumbnail and a
    larger preview, plus 'import a picture from my computer'. value() -> (key, path)."""
    ORIGIN = {"mod": "this mod", "game": "BB+ / base game", "new": "added now"}

    def __init__(self, master, proj, owner, sub, specials, default=None, note="", name="", about="", thumb=36, big=96):
        super().__init__(master, bg=PANEL)
        self.thumb, self.big = thumb, big
        self.note, self.sub, self.name, self.about = note, sub, name, about
        self.proj, self.owner, self.specials = proj, owner, list(specials)
        use = proj.icon_users() if sub == "ShipIcons" else None

        def tag(stem):
            if use is None:
                return ""
            u = use.get(stem.lower())
            return "   ·  used by %s" % (", ".join(u[:2]) + ("…" if len(u) > 2 else "")) if u else "   ·  not used yet"
        self.pics = [(stem, "%s   (%s)%s" % (stem, self.ORIGIN.get(o, o), tag(stem)), path) for stem, path, o in proj.texture_choices(sub)]
        self.imported, self.shown = None, []
        top = tk.Frame(self, bg=PANEL)
        top.pack(fill="x")
        tk.Label(top, text="Filter", bg=PANEL, fg=DIM).pack(side="left")
        self.flt = tk.StringVar()
        e = ttk.Entry(top, textvariable=self.flt, width=26)
        e.pack(side="left", padx=6)
        tip(e, "Type part of a picture's name to narrow the list.")
        b = ttk.Button(top, text="Import a picture from my computer…", command=self.import_pic)
        b.pack(side="right")
        ab = ttk.Button(top, text="Make with an AI…", command=self.make_ai)
        ab.pack(side="right", padx=6)
        tip(ab, "Builds an exact prompt (size, background, style of the pictures already here) to paste into any AI, then takes the picture back "
                "from the clipboard or a file and fits it. It is used like an imported picture.")
        if getattr(owner, "app", None) is not None:
            lb = ttk.Button(top, text="From the library…", command=self.from_library)
            lb.pack(side="right", padx=6)
            tip(lb, "Pick any picture from this mod, BB+ or the other mods in your Mods folder (race pictures, flags, effects ...). It is used like an imported picture.")
        tip(b, "Choose a picture file anywhere on your computer: .png is best (.gif, .dds and .xnb also work). It is copied into the mod's "
               "Textures\\%s folder, named after the module's UID, when you Save." % sub)
        if not self.pics:
            tk.Label(self, bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=600,
                     text="No viewable pictures were found in Textures\\%s (the base game's may be .xnb files, which can't be shown here). "
                          "Use the import button to pick your own." % sub).pack(fill="x", pady=(4, 0))
        mid = tk.Frame(self, bg=PANEL)
        mid.pack(fill="both", expand=True, pady=(6, 0))
        st = ttk.Style()
        st.configure("Icons.Treeview", rowheight=44, background=PANEL2, fieldbackground=PANEL2, foreground=FG)
        st.map("Icons.Treeview", background=[("selected", SEL)], foreground=[("selected", FG)])
        self.tree = ttk.Treeview(mid, show="tree", style="Icons.Treeview", height=9, selectmode="browse")
        sb = ttk.Scrollbar(mid, orient="vertical", command=self.tree.yview)
        self.tree.configure(yscrollcommand=sb.set)
        self.tree.column("#0", width=430 if self.thumb < 60 else 560)
        self.pv = tk.Label(mid, bg=PANEL2, width=max(14, self.big // 7), height=7, fg=DIM, text="preview")
        self.pv.pack(side="right", padx=(8, 0), fill="y")
        sb.pack(side="right", fill="y")
        self.tree.pack(side="left", fill="both", expand=True)
        self.tree.bind("<<TreeviewSelect>>", lambda _e: self.preview())
        if note:
            tk.Label(self, text=note, bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=640).pack(fill="x", pady=(6, 0), before=mid)
        self.flt.trace_add("write", lambda *_a: self.fill())
        self.default = default or (self.specials[0][0] if self.specials else None)
        self.fill(select=self.default)

    def rows(self):
        return [(k, lab, None) for k, lab in self.specials] + ([("__import", "★ Imported: %s" % self.imported.name, self.imported)] if self.imported else []) + self.pics

    def fill(self, select=None):
        words = self.flt.get().lower().split()
        keep = select or (self.value()[0] if self.tree.selection() else None)
        self.shown = [r for r in self.rows() if r[0].startswith("__") and not words or all(w in r[1].lower() for w in words)]
        self.tree.delete(*self.tree.get_children())
        pick = None
        for i, (k, lab, path) in enumerate(self.shown):
            im = self.owner.img(path, self.thumb) if path else None
            self.tree.insert("", "end", iid=str(i), text="  " + lab, image=im if im is not None else self.owner.blank)
            if k == keep:
                pick = str(i)
        kids = self.tree.get_children()
        if kids:
            self.tree.selection_set(pick or kids[0])
            self.tree.see(pick or kids[0])
        self.preview()

    def import_pic(self):
        f = filedialog.askopenfilename(parent=self.winfo_toplevel(), title="Pick a picture",
                                       filetypes=[("Pictures", "*.png *.gif *.dds *.xnb *.jpg *.jpeg *.bmp *.tga"), ("All files", "*.*")])
        if f:
            self.imported = Path(f)
            self.flt.set("")
            self.fill(select="__import")

    def from_library(self):
        r = pick_library(self.winfo_toplevel(), self.owner.app, ["picture", "race", "anim"], "Pick a picture from the library", stage=False)
        if r:
            self.imported = r[1] / r[2]
            self.flt.set("")
            self.fill(select="__import")

    def make_ai(self):
        nm = self.name() if callable(self.name) else self.name
        d = AiAssetDialog(self.winfo_toplevel(), self.proj, self.sub, nm or "picture", self.about() if callable(self.about) else self.about)
        self.winfo_toplevel().wait_window(d)
        if d.result and d.result[1]:
            self.imported = Path(d.result[1])
            self.flt.set("")
            self.fill(select="__import")

    def value(self):
        sel = [int(i) for i in self.tree.selection() if str(i).isdigit() and int(i) < len(self.shown)]
        if not sel:
            return (self.default or "__none", None)
        k, _lab, path = self.shown[sel[0]]
        return (k if k.startswith("__") else k, path)

    def preview(self):
        sel = [int(i) for i in self.tree.selection() if str(i).isdigit() and int(i) < len(self.shown)]
        path = self.shown[sel[0]][2] if sel else None
        im = self.owner.img(path, self.big) if path else None
        self.pv.configure(image=im if im is not None else "", text="" if im is not None else "no picture")
        self.pv.image = im


