def _tex_key(v):
    v = (v or "").strip().replace("\\", "/").lstrip("/")
    if v.lower().startswith("textures/"):
        v = v[9:]
    leaf = v.rsplit("/", 1)[-1]
    if "." in leaf:
        v = v[:v.rfind(".")]
    return v.lower()


def library_item_index(proj):
    """{texture path without folder / extension, lower case: [(kind, doc)]} for the pictures that belong to a module, building, tech or ship."""
    idx = {}

    def add(key, kind, d):
        if key:
            lst = idx.setdefault(key, [])
            if not any(x[1] is d for x in lst):
                lst.append((kind, d))
    for m in list(proj.modules) + list(proj.base_modules):
        try:
            add(_tex_key(m.get("IconTexturePath")), "module", m)
            add("modules/" + (m.get("UID") or m.path.stem).lower(), "module", m)
        except Exception:
            pass
    for b in list(proj.buildings) + list(proj.base_buildings):
        try:
            add(_tex_key(b.get("Icon")), "building", b)
        except Exception:
            pass
    for t in list(proj.techs):
        try:
            add("techicons/" + t.uid.lower(), "tech", t)
            add(_tex_key(t.get("IconPath")), "tech", t)
        except Exception:
            pass
    for h in list(proj.hulls) + list(proj.base_hulls):
        try:
            add(_tex_key(h.get("IconPath")), "ship", h)
        except Exception:
            pass
    return idx


LIB_KIND_WORD = {"module": "Ship module", "building": "Building", "tech": "Technology", "ship": "Ship hull"}


def library_item_card(proj, kind, d):
    """[(label, text)] for the hover box of a library picture that belongs to an item."""
    rows = []
    try:
        if kind == "tech":
            rows.append(("Name", d.get("Name").strip() or d.uid))
            rows.append(("UID", d.uid))
            rows += [(l, d.get(t).strip()) for l, t in (("Cost", "Cost"), ("Tech level", "TechLevel")) if d.get(t).strip()]
        elif kind == "ship":
            rows.append(("Name", d.get("VisibleName").strip() or d.path.stem))
            rows += [(l, d.get(t).strip()) for l, t in (("Role", "Role"), ("Style", "Style"), ("Size", "Size")) if d.get(t).strip()]
        else:
            tag = "NameIndex" if kind == "module" else "NameTranslationIndex"
            e = proj.text_display(d, tag)
            nm = (e.get("ENG") if e else "") or d.get("Name").strip() or doc_key(d)
            rows.append(("Name", nm))
            rows.append(("UID" if kind == "module" else "File", d.get("UID").strip() or doc_key(d)))
            tags = (("Cost", "Cost"), ("Power draw", "PowerDraw"), ("Health", "Health"), ("Weapon", "WeaponType"), ("Upkeep", "Maintenance")) \
                if kind == "module" else (("Cost", "Cost"), ("Upkeep", "Maintenance"))
            rows += [(l, d.get(t).strip()) for l, t in tags if d.get(t).strip()]
    except Exception:
        pass
    return rows


def library_open_item(app, kind, d):
    """Jump to the editor of a library item. Returns False when it can't be shown."""
    try:
        if kind == "module" and app.tech:
            app.open_module_editor(d)
        elif kind == "building" and app.btree:
            app.nb.select(app.btree)
            app.btree.open_module(d)
        elif kind == "tech" and app.research:
            app.goto_tech(d)
        elif kind == "ship" and app.hullv:
            app.nb.select(app.hullv)
            app.hullv.select_key(app.proj.hull_key(d))
        else:
            return False
        return True
    except Exception:
        log_exc("library jump")
        return False


class AssetBrowser(tk.Frame):
    """Browse the asset library (this mod, BB+ and the other mods) by kind and source, with a preview, and copy files into the mod.
    pick=True: a chooser for one file (used by the pickers); otherwise the Library tab."""
    SHOW_MAX = 2500

    def __init__(self, master, app, kinds=None, pick=False, on_choose=None, kind="all", stage=True):
        super().__init__(master, bg=PANEL)
        self.app, self.proj, self.pick, self.on_choose, self.stage = app, app.proj, pick, on_choose, stage
        self.kinds = kinds                                       # None = every kind, else a list of kind keys the chooser is limited to
        self.rows, self.shown, self.img = [], [], None
        self.scanned = False
        top = tk.Frame(self, bg=PANEL)
        top.pack(fill="x", padx=8, pady=(8, 4))
        kl = [(k, lab) for k, lab in Project.LIB_KINDS if kinds is None or k in kinds]
        self.kind_names = {lab: k for k, lab in kl}
        self.v_kind = tk.StringVar(value=next((lab for k, lab in kl if k == kind), kl[0][1]))
        tk.Label(top, text="Kind", bg=PANEL, fg=DIM).pack(side="left")
        cb = ttk.Combobox(top, textvariable=self.v_kind, values=[lab for _k, lab in kl], state="readonly", width=32)
        cb.pack(side="left", padx=(4, 12))
        tip(cb, "What to look for: pictures, race pictures and flags, sounds, videos, 3D models, animation frames or data files.")
        self.v_src = tk.StringVar(value="All sources")
        tk.Label(top, text="From", bg=PANEL, fg=DIM).pack(side="left")
        self.cb_src = ttk.Combobox(top, textvariable=self.v_src, values=["All sources"], state="readonly", width=24)
        self.cb_src.pack(side="left", padx=(4, 12))
        tip(self.cb_src, "This mod, BB+ (the base game), or any other mod in your Mods folder.")
        self.v_flt = tk.StringVar()
        tk.Label(top, text="Filter", bg=PANEL, fg=DIM).pack(side="left")
        e = ttk.Entry(top, textvariable=self.v_flt, width=26)
        e.pack(side="left", padx=4)
        tip(e, "Type part of a file or folder name; several words must all match.")
        self.count = tk.Label(top, bg=PANEL, fg=DIM)
        self.count.pack(side="left", padx=10)
        b = ttk.Button(top, text="Rescan", command=lambda: self.scan(True))
        b.pack(side="right")
        tip(b, "Look at the folders again (after you add a mod or a file).")
        for v in (self.v_kind, self.v_src, self.v_flt):
            v.trace_add("write", lambda *_a: self.fill())
        bt = tk.Frame(self, bg=PANEL)
        bt.pack(side="bottom", fill="x", padx=8, pady=8)
        self.info = tk.Label(bt, bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=900)
        self.info.pack(side="left", fill="x", expand=True)
        if pick:
            b = ttk.Button(bt, text="Use this file", command=self.choose)
            b.pack(side="right")
            tip(b, "Use the selected file. If it is not already in your mod it is copied in (at the same folder path) when you Save.")
            b = ttk.Button(bt, text="Cancel", command=lambda: self.winfo_toplevel().destroy())
            b.pack(side="right", padx=6)
        else:
            b = ttk.Button(bt, text="Copy into my mod", command=self.copy_selected, style="Save.TButton")
            b.pack(side="right")
            tip(b, "Copy the selected file(s) into this mod at the same folder path (Textures\\Flags\\x.png, Audio\\..., Video\\...). Written when you Save; "
                   "files the mod already has are left alone.")
        b = ttk.Button(bt, text="Open / play", command=self.open_file)
        b.pack(side="right", padx=6)
        tip(b, "Open the file in your default program (plays sounds and videos).")
        b = ttk.Button(bt, text="Show in folder", command=self.show_folder)
        b.pack(side="right")
        tip(b, "Show the file in its folder.")
        mid = tk.Frame(self, bg=PANEL)
        mid.pack(fill="both", expand=True, padx=8)
        self.pv = tk.Label(mid, bg=PANEL2, fg=DIM, text="preview", width=34, height=14)
        self.pv.pack(side="right", fill="y", padx=(8, 0))
        cols = ("folder", "source", "size")
        tvstyle = {}
        if not pick:
            st = ttk.Style()
            st.configure("Lib.Treeview", rowheight=34, background=PANEL2, fieldbackground=PANEL2, foreground=FG)
            st.map("Lib.Treeview", background=[("selected", SEL)], foreground=[("selected", FG)])
            tvstyle = {"style": "Lib.Treeview"}
        self.tv = ttk.Treeview(mid, columns=cols, show="tree headings", selectmode="browse" if pick else "extended", height=16, **tvstyle)
        self.items, self.item_idx, self.thumbs, self.blank, self.hover_id, self.card = {}, None, {}, tk.PhotoImage(width=1, height=1), None, None
        self.tv.heading("#0", text="File")
        self.tv.heading("folder", text="Folder")
        self.tv.heading("source", text="From")
        self.tv.heading("size", text="Size")
        self.tv.column("#0", width=260)
        self.tv.column("folder", width=260)
        self.tv.column("source", width=140)
        self.tv.column("size", width=70, anchor="e")
        sb = ttk.Scrollbar(mid, orient="vertical", command=self.tv.yview)
        self.tv.configure(yscrollcommand=sb.set)
        sb.pack(side="right", fill="y")
        self.tv.pack(side="left", fill="both", expand=True)
        self.tv.bind("<<TreeviewSelect>>", lambda _e: self.preview())
        self.tv.bind("<Double-1>", lambda _e: self.choose() if pick else self.double())
        if not pick:
            self.tv.bind("<Motion>", self.hover_move)
            self.tv.bind("<Leave>", lambda _e: self.hide_card())
            self.tv.bind("<ButtonPress>", lambda _e: self.hide_card(), add="+")

    def ensure(self):
        if not self.scanned:
            self.scan()

    def scan(self, force=False):
        self.count["text"] = "scanning ..."
        self.update_idletasks()
        self.rows = self.proj.library_scan(force)
        self.scanned = True
        labs = sorted({r[0] for r in self.rows}, key=lambda x: (x != "This mod", x != "BB+ (base game)", x.lower()))
        self.cb_src["values"] = ["All sources"] + labs
        self.fill()

    @staticmethod
    def size_text(n):
        return "%d B" % n if n < 1024 else ("%.0f KB" % (n / 1024) if n < 1048576 else "%.1f MB" % (n / 1048576))

    def fill(self):
        if not self.scanned:
            return
        kind = self.kind_names.get(self.v_kind.get(), "all")
        src, words = self.v_src.get(), self.v_flt.get().lower().split()
        pool = [r for r in self.rows if (kind == "all" or kind in r[5]) and (src == "All sources" or r[0] == src)
                and (self.kinds is None or kind != "all" or any(k in r[5] for k in self.kinds)) and all(w in r[2].lower() for w in words)]
        pool.sort(key=lambda r: (r[0] != "This mod", r[0] != "BB+ (base game)", r[0].lower(), r[2].lower()))
        self.shown = pool[:self.SHOW_MAX]
        self.tv.delete(*self.tv.get_children())
        self.items = {}
        if not self.pick and self.item_idx is None:
            try:
                self.item_idx = library_item_index(self.proj)
            except Exception:
                log_exc("library items")
                self.item_idx = {}
        nthumb = 0
        for i, (label, _top, rel, _ext, size, _k) in enumerate(self.shown):
            d, _s, n = rel.rpartition("/")
            kw = {}
            if self.item_idx:
                hit = self.item_idx.get(_tex_key(rel))
                if hit:
                    self.items[str(i)] = hit
                    if nthumb < 300 and _ext in (".png", ".gif", ".jpg", ".jpeg", ".bmp") and size < 4 * 1048576:
                        nthumb += 1
                        ik = (label, rel)
                        if ik not in self.thumbs:
                            try:
                                self.thumbs[ik] = load_image(self.path_of(self.shown[i]), 28)
                            except Exception:
                                self.thumbs[ik] = self.blank
                        kw["image"] = self.thumbs[ik]
            if self.item_idx is not None and not self.pick and "image" not in kw:
                kw["image"] = self.blank
            self.tv.insert("", "end", iid=str(i), text=("  " + n) if kw else n, values=(d, label, self.size_text(size)), **kw)
        self.count["text"] = "%d file(s)%s" % (len(pool), "  (first %d shown - use the filter)" % self.SHOW_MAX if len(pool) > self.SHOW_MAX else "")
        self.info["text"] = ""
        self.pv.configure(image="", text="preview")

    def current(self):
        sel = self.tv.selection()
        return [self.shown[int(i)] for i in sel if str(i).isdigit() and int(i) < len(self.shown)]

    def path_of(self, r):
        return r[1] / r[2]

    def preview(self):
        rs = self.current()
        if not rs:
            return
        r = rs[0]
        p = self.path_of(r)
        mine = (self.proj.root / r[2]).exists()
        note = "Already in your mod." if (r[0] == "This mod" or mine) else "Not in your mod yet - it is copied in when you use it."
        self.info["text"] = "%s   ·   %s   ·   %s" % (r[2], r[0], note)
        self.img = None
        if r[3] in self.proj.PIC_EXTS and r[4] < 30 * 1048576:
            try:
                self.img = load_image(p, 240)
            except Exception:
                self.img = None
        self.pv.configure(image=self.img or "", text="" if self.img else ("no preview\n\n" + p.name + ("\n(press Open / play)" if r[3] not in self.proj.PIC_EXTS else "")))

    def double(self):
        """Double-click: a picture that belongs to a module / building / tech / ship opens that item's editor, anything else opens the file."""
        sel = self.tv.selection()
        hit = self.items.get(sel[0]) if sel else None
        if hit:
            kind, d = hit[0]
            if library_open_item(self.app, kind, d):
                return
        self.open_file()

    def hide_card(self):
        self.hover_id = None
        if self.card is not None:
            try:
                self.card.destroy()
            except tk.TclError:
                pass
            self.card = None

    def hover_move(self, e):
        iid = self.tv.identify_row(e.y)
        if iid == self.hover_id:
            return
        self.hide_card()
        self.hover_id = iid
        if iid and iid in self.items:
            self.after(380, lambda iid=iid, x=e.x_root, y=e.y_root: self.show_card(iid, x, y))

    def show_card(self, iid, x, y):
        if iid != self.hover_id or iid not in self.items:
            return
        self.hide_card()
        self.hover_id = iid
        try:
            r = self.shown[int(iid)]
            top = tk.Toplevel(self)
            top.overrideredirect(True)
            top.configure(bg=ORANGE)
            f = tk.Frame(top, bg=PANEL2)
            f.pack(padx=1, pady=1)
            self.card = top
            im = None
            if r[3] in (".png", ".gif", ".jpg", ".jpeg", ".bmp"):
                try:
                    im = load_image(self.path_of(r), 120)
                except Exception:
                    im = None
            if im is not None:
                lb = tk.Label(f, image=im, bg=PANEL2)
                lb.image = im
                lb.pack(side="left", padx=8, pady=8)
            col = tk.Frame(f, bg=PANEL2)
            col.pack(side="left", padx=(0, 10), pady=8)
            for kind, d in self.items[iid]:
                tk.Label(col, text=LIB_KIND_WORD.get(kind, kind), bg=PANEL2, fg=ORANGE, font=("Segoe UI", 10, "bold"), anchor="w").pack(fill="x")
                for lab, val in library_item_card(self.proj, kind, d):
                    tk.Label(col, text="%s: %s" % (lab, val), bg=PANEL2, fg=FG, anchor="w", justify="left", wraplength=320).pack(fill="x")
            tk.Label(col, text="Double-click to open it in its editor.", bg=PANEL2, fg=DIM, anchor="w", font=("Segoe UI", 8)).pack(fill="x", pady=(4, 0))
            top.geometry("+%d+%d" % (x + 16, y + 16))
        except Exception:
            log_exc("library card")

    def open_file(self):
        rs = self.current()
        if not rs:
            return
        p = self.path_of(rs[0])
        try:
            if sys.platform == "win32":
                os.startfile(str(p))
            else:
                subprocess.Popen(["open" if sys.platform == "darwin" else "xdg-open", str(p)])
        except Exception as e:
            messagebox.showwarning("Open", "Could not open %s: %s" % (p.name, e), parent=self)

    def show_folder(self):
        rs = self.current()
        if not rs:
            return
        p = self.path_of(rs[0])
        try:
            if sys.platform == "win32":
                subprocess.Popen(["explorer", "/select,", str(p)])
            else:
                subprocess.Popen(["open" if sys.platform == "darwin" else "xdg-open", str(p.parent)])
        except Exception as e:
            messagebox.showwarning("Show in folder", str(e), parent=self)

    def bring(self, r):
        """Make sure the file is in the mod (staged copy). Returns 'mod' / 'staged' / 'exists' / 'same'."""
        if r[0] == "This mod":
            return "mod"
        _dest, how = self.proj.stage_asset(self.path_of(r), r[2])
        return how

    def copy_selected(self):
        rs = self.current()
        if not rs:
            self.app.say("Pick one or more files first.")
            return
        n = {"mod": 0, "staged": 0, "exists": 0, "same": 0}
        for r in rs:
            n[self.bring(r)] += 1
        self.app.update_status()
        msg = "%d file(s) will be copied into the mod when you Save (Ctrl+S)" % n["staged"]
        if n["exists"] or n["same"] or n["mod"]:
            msg += "; %d already in the mod were left alone" % (n["exists"] + n["same"] + n["mod"])
        self.app.say(msg + ".")
        self.info["text"] = msg + "."
        try:
            self.app.icons_changed()
        except Exception:
            pass

    def choose(self):
        rs = self.current()
        if not rs:
            self.info["text"] = "Pick a file first."
            return
        r = rs[0]
        if self.stage:
            self.bring(r)
        if self.on_choose:
            self.on_choose(r)
        self.winfo_toplevel().destroy()


def glob_escape(t):
    return re.sub(r"([\[\]*?])", r"[\1]", t)


def pick_library(parent, app, kinds, title="Pick from the library", kind=None, stage=True):
    """A chooser over this mod, BB+ and the other mods. Returns the chosen row (source label, folder, relative path, ext, size, kinds), already staged
    for copying into the mod, or None."""
    top = _Dialog(parent, title)
    top.geometry("1100x640")
    got = []
    br = AssetBrowser(top, app, kinds=kinds, pick=True, on_choose=got.append, kind=kind or kinds[0], stage=stage)
    br.pack(fill="both", expand=True)
    top.show()
    br.scan()
    parent.wait_window(top)
    return got[0] if got else None


class LibraryView(ttk.Frame):
    """The Library tab: this mod, BB+ and the other mods as one repository of pictures, sounds, videos, models and more to copy from."""

    def __init__(self, master, app):
        super().__init__(master)
        tk.Label(self, text="LIBRARY", bg=BG, fg=ORANGE, font=("Segoe UI", 14, "bold")).pack(anchor="w", padx=12, pady=(10, 0))
        tk.Label(self, bg=BG, fg=DIM, anchor="w", justify="left", wraplength=1000,
                 text="Everything in this mod, in BB+ (the base game) and in the other mods next to this one. Pick what you want and copy it into your mod; "
                      "the same files are offered in every picture / sound / video / model chooser."
                 ).pack(anchor="w", padx=12, pady=(0, 4))
        self.br = AssetBrowser(self, app)
        self.br.pack(fill="both", expand=True)

    def ensure(self):
        self.br.ensure()


class BuildingWizard(_Dialog):
    """Create a NEW building step by step: 1 name + texts, 2 picture, 3 start from (copy) + cost, 4 effect tags, 5 review.
    result = spec for Project.create_building_spec (plus 'unlock': bool when launched from a tech)."""
    STEPS = ("1 of 5 - What is it called?", "2 of 5 - Picture", "3 of 5 - Start from, cost and upkeep", "4 of 5 - Effects", "5 of 5 - Check and create")
    LAST = 4

    def __init__(self, master, proj, tech=None, start=None):
        super().__init__(master, "New building" if start is None else "Copy of a building")
        self.proj, self.tech, self.owner, self.step = proj, tech, master, 0
        self.start_icon = ""
        self.effects = []                                       # [(tag, value)]
        self.copy_doc = None
        self.pic = None
        try:
            self.geometry("%dx%d" % (min(920, self.winfo_screenwidth() - 60), min(740, self.winfo_screenheight() - 110)))
        except Exception:
            self.geometry("920x740")
        self.minsize(700, 520)
        self.v_name, self.v_folder = tk.StringVar(), tk.StringVar(value="Civilian")
        self.v_cost, self.v_maint = tk.StringVar(value="100"), tk.StringVar(value="0.1")
        self.v_base = tk.StringVar(value="(blank - start empty)")
        self.v_unlock = tk.BooleanVar(value=tech is not None)
        self.head = tk.Label(self, bg=PANEL, fg=PEACH, font=("Segoe UI", 13, "bold"), anchor="w")
        self.head.pack(fill="x", padx=16, pady=(12, 4))
        nav = tk.Frame(self, bg=PANEL)                                   # the buttons are packed first so a tall page can never push them off screen
        nav.pack(side="bottom", fill="x", padx=16, pady=10)
        self.body = tk.Frame(self, bg=PANEL)
        self.body.pack(fill="both", expand=True, padx=16, pady=4)
        self.b_back = ttk.Button(nav, text="◀ Go back", command=self.back)
        self.b_back.pack(side="left")
        tip(self.b_back, "Back to the previous page. What you typed is kept.")
        self.b_next = ttk.Button(nav, text="Next ▶", command=self.next)
        self.b_next.pack(side="right")
        ttk.Button(nav, text="Cancel", command=self.destroy).pack(side="right", padx=8)
        if start is not None:
            self.preset(start)
            self.step = 3                                          # straight to the Effects page, the copy is the starting point
        self.draw()
        self.show()

    def preset(self, d):
        P = self.proj
        key = doc_key(d)
        taken = {doc_key(x).lower() for x in P.compare_docs()}
        name, n = key + "_Copy", 2
        while name.lower() in taken:
            name, n = "%s_Copy%d" % (key, n), n + 1
        self.v_name.set(name)
        e, es = P.text_display(d, "DescriptionIndex"), P.text_display(d, "ShortDescriptionIndex")
        self.t_desc_val = (e.get("ENG") if e else "") or ""
        self.t_short_val = (es.get("ENG") if es else "") or ""
        cat = building_category(d)
        self.v_folder.set("" if cat == "Other" else cat)
        self.v_cost.set(d.get("Cost") or "0")
        self.v_maint.set(d.get("Maintenance") or "0")
        self.effects = [(t, v) for t, v in d.cur.items() if t not in P.BUILDING_IDENTITY and t not in d.nested]
        self.copy_doc = d
        self.v_base.set(key)
        self.start_icon = d.get("Icon").strip()
        if self.start_icon:
            self.pic = ("__same", None)

    # -- helpers
    def clear(self):
        for w in self.body.winfo_children():
            w.destroy()

    def note(self, text):
        tk.Label(self.body, text=text, bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=840).pack(fill="x", pady=(0, 6))

    def folders(self):
        seen = []
        for d in self.proj.buildings + self.proj.base_buildings:
            if getattr(d, "sub", None):
                f = d.sub.parent.as_posix()
            else:
                parts = d.rel.parent.parts
                f = "/".join(parts[1:]) if len(parts) > 1 else ""
            if f and f != "." and f not in seen:
                seen.append(f)
        return sorted(seen, key=str.lower) or ["Civilian"]

    def draw(self):
        self.head["text"] = self.STEPS[self.step]
        self.clear()
        getattr(self, "step%d" % self.step)()
        self.b_back.state(["!disabled"] if self.step else ["disabled"])
        self.b_next["text"] = ("Create ✔" if self.step == self.LAST else "Next ▶")

    # -- steps
    def step0(self):
        B = self.body
        self.note("The name is what the game calls the building internally (it is also the file name), so it must be unique. "
                  "The texts are what the player reads. A GameText entry is made for each when you Save.")
        g = tk.Frame(B, bg=PANEL)
        g.pack(fill="x")
        e = ttk.Entry(g, textvariable=self.v_name, width=44)
        cb = ttk.Combobox(g, textvariable=self.v_folder, values=self.folders(), width=30)
        for r, (lab, w, hint) in enumerate((("Name", e, "<Name>: unique building name, e.g. Dilithium Refinery."),
                                            ("Folder", cb, "Buildings\\<folder> in the mod where the file goes. Pick one of the game's (Civilian, Production, Military ...) or type a new one."))):
            lb = tk.Label(g, text=lab, bg=PANEL, fg=FG)
            lb.grid(row=r, column=0, sticky="w", pady=4)
            w.grid(row=r, column=1, sticky="w", padx=8)
            tip(lb, hint)
            tip(w, hint)
        tk.Label(B, text="Description (shown when the building is selected)", bg=PANEL, fg=FG, anchor="w").pack(fill="x", pady=(10, 0))
        self.e_desc = tk.Text(B, height=5, wrap="word", **TEXT_OPTS)
        self.e_desc.pack(fill="x")
        self.e_desc.insert("1.0", getattr(self, "t_desc_val", ""))
        tk.Label(B, text="Short description (one line in lists)", bg=PANEL, fg=FG, anchor="w").pack(fill="x", pady=(10, 0))
        self.e_short = tk.Text(B, height=2, wrap="word", **TEXT_OPTS)
        self.e_short.pack(fill="x")
        self.e_short.insert("1.0", getattr(self, "t_short_val", ""))
        e.focus_set()

    def step1(self):
        self.note("Pick the building's picture (<Icon>). The base game's pictures (Content\\Textures\\Buildings, icon_<name>_64x64) and this mod's are listed. "
                  "To use your own, import a 64x64 .png (.dds / .xnb also work): it is copied to the mod's Textures\\Buildings folder as icon_<name>_64x64 "
                  "when you Save, and <Icon> is set to <name>.")
        self.picker = PicPicker(self.body, self.proj, self.owner, "Buildings", [("__none", "(no picture yet)")] +
                                ([("__same", "Keep the original's picture (%s)" % self.start_icon)] if self.start_icon else []),
                                default=(self.pic[0] if self.pic else None),
                                name=lambda: self.v_name.get().strip() or "building", about="a building icon")
        pk = self.picker
        stems = {x[0].lower() for x in pk.pics}                                     # the base game ships a 48x48 and a 64x64 of each: list the big one
        pk.pics = [x for x in pk.pics if not (re.search(r"_48x48$", x[0], re.I) and re.sub(r"_48x48$", "_64x64", x[0], flags=re.I).lower() in stems)]
        pk.fill(select=(self.pic[0] if self.pic else None))
        self.picker.pack(fill="both", expand=True)

    def step2(self):
        B = self.body
        self.note("Start from an existing building to inherit its effects (you can change them on the next page), or start blank. "
                  "Numbers like cost and upkeep are set here; every other number is an 'effect' on the next page.")
        names = ["(blank - start empty)"] + sorted(({self.label_of(d) for d in self.proj.buildings + self.proj.base_buildings}), key=str.lower)
        g = tk.Frame(B, bg=PANEL)
        g.pack(fill="x")
        tk.Label(g, text="Copy effects from", bg=PANEL, fg=FG).grid(row=0, column=0, sticky="w", pady=4)
        cb = IconCombo(g, textvariable=self.v_base, values=names, width=48)
        cb.grid(row=0, column=1, padx=8, sticky="w")
        tip(cb, "Pick a building whose effects you want as a starting point. Its cost and upkeep fill the boxes below; the original is not changed.")
        cb.bind("<<ComboboxSelected>>", lambda _e: self.pick_base())
        for r, (lab, var, hint) in enumerate((("Cost", self.v_cost, "<Cost>: production needed to build it."),
                                              ("Upkeep (Maintenance)", self.v_maint, "<Maintenance>: credits per turn it costs to keep. Decimals like .1 are normal."))):
            lb = tk.Label(g, text=lab, bg=PANEL, fg=FG)
            lb.grid(row=r + 1, column=0, sticky="w", pady=4)
            en = entry_scale(g, var, list(self.proj.buildings) + list(self.proj.base_buildings), "Cost" if r == 0 else "Maintenance")
            en.grid(row=r + 1, column=1, sticky="w", padx=8)
            tip(lb, hint)
            tip(en.entry, hint)

    def label_of(self, d):
        return doc_key(d)

    def pick_base(self):
        d = self.proj.building_by_name(self.v_base.get())
        self.copy_doc = d
        if d is None:
            return
        self.v_cost.set(d.get("Cost") or "0")
        self.v_maint.set(d.get("Maintenance") or "0")
        self.effects = [(t, v) for t, v in d.cur.items() if t not in self.proj.BUILDING_IDENTITY and t not in d.nested]

    def step3(self):
        B = self.body
        self.note("Effects are the building's tags: production, population, defence, research, special flags. Pick a tag in the list (rest the pointer on it "
                  "for what it does), type a value, press Add. A ? in the hint means my best reading of an unclear name.")
        mid = tk.Frame(B, bg=PANEL)
        mid.pack(fill="both", expand=True)
        left = tk.Frame(mid, bg=PANEL)
        left.pack(side="left", fill="y")
        tk.Label(left, text="All building tags", bg=PANEL, fg=PEACH).pack(anchor="w")
        lf = tk.Frame(left, bg=PANEL)
        lf.pack(fill="both", expand=True)
        self.lb = tk.Listbox(lf, width=30, height=10, bg=PANEL2, fg=FG, selectbackground=SEL, highlightthickness=1, highlightbackground=EDGE,
                             activestyle="none", exportselection=False)
        lsb = ttk.Scrollbar(lf, orient="vertical", command=self.lb.yview)
        self.lb.configure(yscrollcommand=lsb.set)
        lsb.pack(side="right", fill="y")
        self.lb.pack(side="left", fill="both", expand=True)
        for t in self.proj.building_effect_tags():
            self.lb.insert("end", t)
        self.info = tk.Label(left, bg=PANEL, fg=DIM, wraplength=250, justify="left", anchor="w", height=6)
        self.info.pack(fill="x", pady=4)
        self.lb.bind("<<ListboxSelect>>", lambda _e: self.tag_info())
        self.lb.bind("<Double-1>", lambda _e: self.add_effect())
        right = tk.Frame(mid, bg=PANEL)
        right.pack(side="left", fill="both", expand=True, padx=(14, 0))
        row = tk.Frame(right, bg=PANEL)
        row.pack(fill="x")
        self.v_tag, self.v_val = tk.StringVar(), tk.StringVar()
        tk.Label(row, text="Tag", bg=PANEL, fg=FG).pack(side="left")
        ttk.Entry(row, textvariable=self.v_tag, width=26).pack(side="left", padx=6)
        tk.Label(row, text="Value", bg=PANEL, fg=FG).pack(side="left")
        ev = ttk.Entry(row, textvariable=self.v_val, width=12)
        ev.pack(side="left", padx=6)
        ev.bind("<Return>", lambda _e: self.add_effect())
        ttk.Button(row, text="Add", command=self.add_effect).pack(side="left")
        tk.Label(right, text="This building's effects (select one and Remove; double-click flips a switch or puts a number back in the boxes)", bg=PANEL, fg=PEACH,
                 anchor="w", justify="left", wraplength=520).pack(fill="x", pady=(8, 2))
        self.tv = ttk.Treeview(right, columns=("v",), show="tree headings", height=8, selectmode="extended")
        self.tv.heading("#0", text="Tag")
        self.tv.heading("v", text="Value")
        self.tv.column("#0", width=230)
        self.tv.column("v", width=120)
        self.tv.pack(fill="both", expand=True)
        self.tv.bind("<Double-1>", lambda _e: self.edit_effect())
        ttk.Button(right, text="Remove selected", command=self.remove_effect).pack(anchor="w", pady=4)
        self.fill_effects()
        self._hover_rows(self.lb, lambda w, y: w.get(w.nearest(y)) if w.size() else None)
        self._hover_rows(self.tv, lambda w, y: (lambda i: w.item(i, "text") if i else None)(w.identify_row(y)))

    def tag_text(self, t):
        ex = next((d.get(t) for d in self.proj.buildings + self.proj.base_buildings if d.get(t)), "")
        return "%s\n%s%s" % (t, BUILDING_TAG_INFO.get(t, "(no description known for this tag)"), ("\nExample value: " + ex) if ex else "")

    def _hover_rows(self, widget, tag_at):
        """A hint for whichever tag row the pointer rests on (it follows the pointer from row to row)."""
        st = {"row": None}

        def text():
            try:
                y = widget.winfo_pointery() - widget.winfo_rooty()
                t = tag_at(widget, y)
            except Exception:
                return ""
            return self.tag_text(t.strip()) if t else ""

        tt = ToolTip(widget, text, delay=350)

        def moved(e):
            try:
                t = tag_at(widget, e.y)
            except Exception:
                t = None
            if t != st["row"]:
                st["row"] = t
                tt.hide()
                if t:
                    tt.arm()
        widget.bind("<Motion>", moved, add="+")

    def tag_info(self):
        sel = self.lb.curselection()
        if not sel:
            return
        t = self.lb.get(sel[0])
        self.v_tag.set(t)
        ex = next((d.get(t) for d in self.proj.buildings + self.proj.base_buildings if d.get(t)), "")
        self.info["text"] = "%s\n%s%s" % (t, BUILDING_TAG_INFO.get(t, "(no description known)"), ("\nExample value: " + ex) if ex else "")
        if ex and not self.v_val.get():
            self.v_val.set(ex)

    def fill_effects(self):
        self.tv.delete(*self.tv.get_children())
        for i, (t, v) in enumerate(self.effects):
            self.tv.insert("", "end", iid=str(i), text=t, values=((SWITCH_ON if v.strip().lower() == "true" else SWITCH_OFF)
                                                                  if v.strip().lower() in ("true", "false") else v,))

    def add_effect(self):
        t, v = self.v_tag.get().strip(), self.v_val.get().strip()
        if not re.fullmatch(r"\w+", t or ""):
            return
        if t in self.proj.BUILDING_IDENTITY:
            messagebox.showinfo("New building", "%s is set on another page." % t, parent=self)
            return
        self.effects = [(a, b) for a, b in self.effects if a != t] + [(t, v)]
        self.v_val.set("")
        self.fill_effects()

    def edit_effect(self):
        sel = [int(i) for i in self.tv.selection()]
        if sel and self.effects[sel[0]][1].strip().lower() in ("true", "false"):        # a switch: double-click flips it
            t, v = self.effects[sel[0]]
            self.effects[sel[0]] = (t, "false" if v.strip().lower() == "true" else "true")
            self.fill_effects()
            self.tv.selection_set(str(sel[0]))
            return
        if sel:
            self.v_tag.set(self.effects[sel[0]][0])
            self.v_val.set(self.effects[sel[0]][1])

    def remove_effect(self):
        gone = {int(i) for i in self.tv.selection()}
        self.effects = [e for i, e in enumerate(self.effects) if i not in gone]
        self.fill_effects()

    def step4(self):
        B = self.body
        sp = self.spec()
        lines = ["Name: %s" % sp["name"], "File: Buildings\\%s\\%s.xml" % (sp["folder"] or "", sp["name"]),
                 "Picture: %s" % ("none" if sp["icon"][0] == "__none" else ("imported file (copied on Save)" if sp["icon"][0] == "__import" else sp["icon"][0])),
                 "Cost %s, upkeep %s" % (sp["cost"], sp["maint"]), "", "Effects:"] + ["  %s = %s" % e for e in sp["effects"]] + \
                ([] if sp["effects"] else ["  (none)"])
        tk.Label(B, text="\n".join(lines), bg=PANEL, fg=FG, anchor="nw", justify="left").pack(fill="x")
        if self.tech is not None:
            cb = tk.Checkbutton(B, text="Unlock it with %s" % self.proj.tech_name(self.tech), variable=self.v_unlock, bg=PANEL, fg=FG,
                                selectcolor=PANEL2, activebackground=PANEL, activeforeground=FG)
            cb.pack(anchor="w", pady=10)
            tip(cb, "Adds this building to the tech's BuildingsUnlocked so researching the tech lets players build it.")
        tk.Label(B, text="Nothing is written until you press Save all (Ctrl+S).", bg=PANEL, fg=DIM).pack(anchor="w", pady=6)

    # -- navigation
    def spec(self):
        pk = self.picker.value() if getattr(self, "picker", None) is not None and self.picker.winfo_exists() else (self.pic or ("__none", None))
        return {"name": self.v_name.get().strip(), "folder": self.v_folder.get().strip(), "desc": getattr(self, "t_desc_val", ""),
                "short": getattr(self, "t_short_val", ""), "cost": self.v_cost.get().strip(), "maint": self.v_maint.get().strip(),
                "icon": self.pic or pk, "effects": list(self.effects), "same_icon": self.start_icon}

    def keep(self):
        if self.step == 0:
            self.t_desc_val = self.e_desc.get("1.0", "end").strip()
            self.t_short_val = self.e_short.get("1.0", "end").strip()
        elif self.step == 1:
            self.pic = self.picker.value()

    def next(self):
        if self.step == 0 and not self.v_name.get().strip():
            messagebox.showinfo("New building", "Give the building a name first.", parent=self)
            return
        self.keep()
        if self.step == 2:
            for v in (self.v_cost, self.v_maint):
                try:
                    float(v.get().strip() or "0")
                except ValueError:
                    messagebox.showwarning("New building", "Cost and upkeep must be numbers.", parent=self)
                    return
        if self.step == self.LAST:
            sp = self.spec()
            sp["unlock"] = bool(self.v_unlock.get()) and self.tech is not None
            if sp["icon"][0] == "__same" and not self.start_icon:
                sp["icon"] = ("__none", None)
            self.result = sp
            self.destroy()
            return
        self.step += 1
        self.draw()

    def back(self):
        if self.step:
            self.keep()
            self.step -= 1
            self.draw()


class ModuleWizard(_Dialog):
    """Create a NEW module step by step and unlock it with a tech: 1 name / type / size, 2 module picture, 3 research-screen picture,
    4 weapon + starting stats, 5 review. result = the spec dict for Project.create_module_spec (plus 'race')."""
    STEPS = ("1 of 8 - What is it called?", "2 of 8 - Module picture", "3 of 8 - Research-screen picture",
             "4 of 8 - Module file and starting stats", "5 of 8 - Weapon", "6 of 8 - Sound and projectile", "7 of 8 - Weapon traits",
             "8 of 8 - Check and create")
    LAST = 7
    SOUND_TAGS = ("FireCueName", "ToggleSoundName", "InFlightCue", "DieCue")
    FX = (("Fire sound", "FireCueName", "The sound cue played when the weapon fires. Cues live in the game's sound bank, so the ones other weapons use are listed (most used first); you can type any cue name the game knows."),
          ("Beam / loop sound", "ToggleSoundName", "The looping sound of a beam weapon while it fires."),
          ("Flight sound", "InFlightCue", "Sound that loops while the projectile is flying (rockets, torpedoes)."),
          ("Impact sound", "DieCue", "Sound played when the projectile hits / explodes."),
          ("Projectile picture", "ProjectileTexturePath", "The texture drawn for each shot. File type: a picture (.png, .xnb or .dds) found in a Textures folder of the mod or the game - type its name without the extension."),
          ("Projectile model", "ModelPath", "The 3D model used for the shot (ModelPath), e.g. projBall, projTear, MRM."),
          ("Animation frames", "AnimationPath", "A frame-by-frame animation for the shot: the folder / file prefix of the frames (e.g. fed_phasercannon/fed_phasercannon_cc_). File type: one PNG (or .xnb / .dds) per frame, named <prefix>00000, <prefix>00001 ... in a Textures sub-folder; projectile art is drawn pointing up (e.g. 64 × 128). Sets Animated and LoopAnimation to 1."),
          ("Animation frame count", "Frames", "How many frames the animation has."),
          ("Trail effect", "WeaponTrailEffect", "Particle trail left behind the shot."),
          ("Muzzle flash", "MuzzleFlash", "Flash effect at the gun when firing."),
          ("Hit effect", "WeaponHitEffect", "Effect when the shot hits armour / hull."),
          ("Shield hit effect", "WeaponShieldHitEffect", "Effect when the shot hits a shield."),
          ("Beam texture", "BeamTexture", "The texture of a beam weapon's beam. File type: a picture (.png, .xnb or .dds) in a Textures folder - type its name without the extension."))
    NO_BASE, NO_WEAPON = "(blank template)", "(none)"

    def __init__(self, master, proj, tech, start=None):
        super().__init__(master, ("New module - unlocked by %s" % proj.tech_name(tech)) if tech is not None else
                         ("Copy of %s as a new module" % module_name(proj, start) if start is not None else "New module"))
        self.proj, self.tech, self.owner, self.step, self.pages, self.pickers = proj, tech, master, 0, {}, {}
        types = sorted({m.get("ModuleType").strip() for m in proj.modules if m.get("ModuleType").strip()}, key=str.lower)
        self.base_by = {"%s  (%s)" % (module_name(proj, m), (m.get("UID") or m.path.stem).strip()): m
                        for m in sorted(proj.modules, key=lambda m: module_name(proj, m).lower())}
        self.wbase_by = {(w.get("UID") or w.path.stem).strip(): w for w in sorted(proj.weapons, key=lambda w: (w.get("UID") or w.path.stem).lower())}
        self.v = {k: tk.StringVar(value=val) for k, val in (
            ("name", ""), ("uid", ""), ("type", types[0] if types else "Turret"), ("x", "1"), ("y", "1"), ("base", self.NO_BASE),
            ("folder", proj.default_folder(types[0] if types else "")), ("wmode", "none"), ("weapon", ""), ("wbase", ""),
            ("wdmg", ""), ("wrng", ""), ("wdelay", ""), ("Cost", ""), ("Mass", ""), ("HealthMax", ""), ("PowerDraw", ""),
            ("race", UnlockDialog.ALL))}
        self.types, self.uid_touched = types, False
        self.start, self.start_desc = start, ""
        if start is not None:
            self.preset(start)
        self.traits, self.traits_for = {}, None             # tag -> value of the new weapon file (step 6)
        self.head = tk.Label(self, bg=PANEL, fg=PEACH, anchor="w", font=("Segoe UI", 12, "bold"))
        self.head.pack(fill="x", padx=14, pady=(12, 2))
        self.sub = tk.Label(self, bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=640)
        self.sub.pack(fill="x", padx=14)
        self.body = tk.Frame(self, bg=PANEL)
        self.body.pack(fill="both", expand=True, padx=14, pady=8)
        bt = tk.Frame(self, bg=PANEL)
        bt.pack(fill="x", padx=14, pady=(0, 12))
        self.b_cancel = ttk.Button(bt, text="Cancel", command=self.destroy)
        self.b_cancel.pack(side="left")
        self.b_next = ttk.Button(bt, text="Next ›", command=self.next)
        self.b_next.pack(side="right")
        self.b_back = ttk.Button(bt, text="‹ Back", command=self.back)
        self.b_back.pack(side="right", padx=6)
        self.v["name"].trace_add("write", lambda *_a: self.sync_uid())
        self.v["type"].trace_add("write", lambda *_a: self.sync_folder())
        self.goto(0 if start is None else (6 if self.v["wmode"].get() == "new" else 3))      # a copy opens at the tags / stats page
        try:
            sw, sh = self.winfo_screenwidth(), self.winfo_screenheight()
            self.geometry("%dx%d" % (min(980, sw - 60), min(780, sh - 110)))        # big enough for every step
            self.minsize(min(820, sw - 60), min(600, sh - 110))
        except Exception:
            pass
        self.show()

    def destroy(self):
        stop_sound()
        super().destroy()

    def preset(self, d):
        """Start from an existing module: its file as the base, a copy of its weapon, its type / size / texts."""
        P, v = self.proj, self.v
        key = doc_key(d)
        taken = {doc_key(x).lower() for x in P.compare_docs()} | set(P.weap)
        uid, n = key + "_Copy", 2
        while uid.lower() in taken:
            uid, n = "%s_Copy%d" % (key, n), n + 1
        label = "%s  (%s)" % (module_name(P, d), (d.get("UID") or d.path.stem).strip())
        self.base_by.setdefault(label, d)                          # a base-game module is not in the list otherwise
        self.uid_touched = True
        v["base"].set(label)
        v["name"].set(module_name(P, d) + " (copy)")
        v["uid"].set(uid)
        mt = d.get("ModuleType").strip()
        if mt and mt not in self.types:
            self.types.append(mt)
        v["type"].set(mt or v["type"].get())
        v["x"].set(d.get("XSize").strip() or "1")
        v["y"].set(d.get("YSize").strip() or "1")
        try:
            fol = d.path.parent.relative_to(P.module_root()).as_posix()
            v["folder"].set("" if fol == "." else fol)
        except ValueError:
            v["folder"].set(P.default_folder(mt))
        e = P.text_display(d, "DescriptionIndex")
        self.start_desc = (e.get("ENG") if e else "") or d.get("Description")
        w = P.weapon_for(d)
        if w is not None:
            wk = (w.get("UID") or w.path.stem).strip()
            self.wbase_by.setdefault(wk, w)
            v["wmode"].set("new")
            v["wbase"].set(wk)

    # ---- helpers
    def sync_uid(self):
        if not self.uid_touched:
            self.v["uid"].set(re.sub(r"[^A-Za-z0-9_]+", "_", self.v["name"].get().strip()).strip("_"))

    def sync_folder(self):
        self.v["folder"].set(self.proj.default_folder(self.v["type"].get()))

    def row(self, parent, r, text, widget_fn, hint=None):
        lb = tk.Label(parent, text=text, bg=PANEL, fg=FG, anchor="w")
        lb.grid(row=r, column=0, sticky="nw", padx=(0, 8), pady=4)
        w = widget_fn()
        w.grid(row=r, column=1, sticky="w", pady=3)
        if hint:
            tip(lb, hint)
            tip(w, hint)
        return w

    # ---- pages
    def build(self, i):
        f = tk.Frame(self.body, bg=PANEL)
        P, v = self.proj, self.v
        if i == 0:
            e = self.row(f, 0, "Name in game", lambda: ttk.Entry(f, textvariable=v["name"], width=44), "The name players see. Stored in GameText.yaml.")
            e.focus_set()

            def uid_entry():
                en = ttk.Entry(f, textvariable=v["uid"], width=44)
                en.bind("<Key>", lambda _e: setattr(self, "uid_touched", True), add="+")
                return en
            self.row(f, 1, "UID (file name)", uid_entry, TIP_MOD_UID)
            self.row(f, 2, "Module type", lambda: ttk.Combobox(f, textvariable=v["type"], values=self.types, width=41),
                     "ModuleType: Turret, PowerPlant, Shield, Engine ... decides which stats matter.")
            sz = tk.Frame(f, bg=PANEL)
            ttk.Entry(sz, textvariable=v["x"], width=5).pack(side="left")
            tk.Label(sz, text=" wide  ×  ", bg=PANEL, fg=DIM).pack(side="left")
            ttk.Entry(sz, textvariable=v["y"], width=5).pack(side="left")
            tk.Label(sz, text=" tall  (ship-grid squares)", bg=PANEL, fg=DIM).pack(side="left")
            self.row(f, 3, "Size", lambda: sz, "XSize x YSize: how many ship-grid squares the module covers.")
            self.desc = self.row(f, 4, "Description", lambda: tk.Text(f, width=44, height=4, wrap="word", **TEXT_OPTS),
                                 "Shown in game under the name. Stored in GameText.yaml.")
            if self.start_desc:
                self.desc.insert("1.0", self.start_desc)
        elif i == 1:
            pk = PicPicker(f, P, self.owner, "Modules", [("__none", "(no picture yet - I will add Textures\\Modules\\<UID>.png myself)")],
                           note="File type: PNG with a transparent background is best (.dds / .xnb / .gif also display). A picture you pick from the list is "
                                "used where it is; an imported one is copied to Textures\\Modules\\<UID>.png and the module's IconTexturePath becomes "
                                "Modules/<UID>. " + P.picture_facts("Modules"),
                           name=lambda: self.v["name"].get().strip() or "module", about="a ship module icon")
            pk.pack(fill="both", expand=True)
            self.pickers[1] = pk
        elif i == 2:
            pk = PicPicker(f, P, self.owner, "TechIcons",
                           [("__same", "Use the module picture from step 2 (copied as TechIcons\\<UID>.png)"),
                            ("__none", "(none - the research screen falls back to the module picture)")],
                           note="File type: PNG, saved as Textures\\TechIcons\\<UID>.png - the file name must equal the module's UID, that is how the "
                                "research screen finds it. " + P.picture_facts("TechIcons"),
                           name=lambda: self.v["name"].get().strip() or "module", about="a research (tech) icon")
            pk.pack(fill="both", expand=True)
            self.pickers[2] = pk
        elif i == 3:
            self.row(f, 0, "Start from", lambda: IconCombo(f, textvariable=v["base"], values=[self.NO_BASE] + list(self.base_by),
                                                               width=50, state="readonly"),
                     "Copy an existing module's file (all its stats) instead of the blank template.")
            self.row(f, 1, "Folder", lambda: ttk.Combobox(f, textvariable=v["folder"], values=P.module_folders(), width=50),
                     "Where the module's xml goes under the modules folder. Type a new name to create a new folder on Save.")
            tk.Label(f, text="Starting stats (leave empty to keep the template / copied value). The rest is edited later in the module table.",
                     bg=PANEL, fg=DIM, wraplength=620, justify="left").grid(row=2, column=0, columnspan=2, sticky="w", pady=(10, 2))
            sf = tk.Frame(f, bg=PANEL)
            sf.grid(row=3, column=0, columnspan=2, sticky="w")
            for lab, key in (("Cost", "Cost"), ("Mass", "Mass"), ("Health", "HealthMax"), ("Power draw", "PowerDraw")):
                tk.Label(sf, text=lab, bg=PANEL, fg=FG).pack(side="left", padx=(0, 4))
                ttk.Entry(sf, textvariable=v[key], width=8).pack(side="left", padx=(0, 12))
        elif i == 4:
            for k, (val, txt) in enumerate((("none", "No weapon (shield, power, engine, armour ...)"), ("existing", "Fires an existing weapon file"),
                                            ("blank", "A NEW BLANK weapon file - start empty and tag its traits on the next steps"),
                                            ("new", "A NEW weapon file - copy an existing one, then change its traits on the next steps"))):
                tk.Radiobutton(f, text=txt, value=val, variable=v["wmode"], bg=PANEL, fg=FG, selectcolor=PANEL2, activebackground=PANEL,
                               activeforeground=FG, anchor="w", command=self.weapon_state).grid(row=k, column=0, columnspan=2, sticky="w", pady=2)
            wl = list(self.wbase_by)
            tk.Label(f, text="Weapon", bg=PANEL, fg=FG).grid(row=3, column=0, sticky="w", padx=(22, 8), pady=(10, 2))
            self.w_cb = IconCombo(f, textvariable=v["weapon"], values=wl, width=40, state="readonly")
            self.w_cb.grid(row=3, column=1, sticky="w", pady=(10, 2))
            tk.Label(f, text="Copy of", bg=PANEL, fg=FG).grid(row=4, column=0, sticky="w", padx=(22, 8), pady=2)
            self.wb_cb = IconCombo(f, textvariable=v["wbase"], values=wl, width=40, state="readonly")
            self.wb_cb.grid(row=4, column=1, sticky="w", pady=2)
            self.weapon_state()
        elif i == 5:
            self.build_fx(f)
        elif i == 6:
            self.build_traits(f)
        else:
            self.rev = tk.Label(f, bg=PANEL, fg=FG, justify="left", anchor="nw", wraplength=640)
            self.rev.grid(row=0, column=0, columnspan=2, sticky="w")
            races = [UnlockDialog.ALL, UnlockDialog.NONE] + P.unlock_types()
            if self.tech is not None:
                self.row(f, 1, "Unlock it for race", lambda: ttk.Combobox(f, textvariable=v["race"], values=races, width=40, state="readonly"),
                         "Which race gets the module from this tech (the <Type> of the unlock).")
            self.pv = tk.Label(f, bg=PANEL)
            self.pv.grid(row=0, column=2, rowspan=2, padx=12, sticky="ne")
        return f

    def weapon_state(self):
        m = self.v["wmode"].get()
        for w, on in ((self.w_cb, m == "existing"), (self.wb_cb, m == "new")):
            w.configure(state="readonly" if on else "disabled")

    # ---- step 6: sound and projectile
    FX_FILE = ("ProjectileTexturePath", "BeamTexture", "AnimationPath")

    def fx_ai_btn(self, fr, tag, lab, var):
        b = ttk.Button(fr, text="AI…", width=5, command=lambda: self.fx_ai(tag, lab, var))
        b.pack(side="left", padx=(4, 0))
        tip(b, "Make this file with an AI: builds a prompt for any AI (picture, animation frames or sound), then takes the result back.")

    def fx_ai(self, tag, lab, var):
        P = self.proj
        nm = self.v["name"].get().strip() if "name" in getattr(self, "v", {}) else ""
        about = "%s for the weapon '%s' (%s)" % (lab, nm or "new weapon", tag)
        if tag in ("ProjectileTexturePath", "BeamTexture"):
            old = next((x for x in P.tag_values(tag) if "/" in x or "\\" in x), "")
            sub = re.split(r"[\\/]", old)[0] if old else "Projectiles"
            dlg = AiAssetDialog(self, P, sub, nm or "weapon", about)
            self.wait_window(dlg)
            if dlg.result and dlg.result[1]:
                stem = re.sub(r"[^\w\-]+", "_", (nm or "weapon") + "_" + ("beam" if tag == "BeamTexture" else "shot")).strip("_")
                try:
                    P.stage_copy(dlg.result[1], sub, stem)
                except Exception as e:
                    messagebox.showwarning("Picture", "That picture could not be added: %s" % e, parent=self)
                    return
                var.set("%s/%s" % (sub, stem))
            return
        if tag == "AnimationPath":
            task = ("Describe a short looping animation of a weapon shot as a numbered set of PNG frames with transparent background "
                    "(Name_cc_00000.png, Name_cc_00001.png ...), and give one image prompt per frame or one sprite-sheet prompt to cut into frames.")
            tail = "Save the frames in the mod's Textures\\<Name>\\ folder, then type <Name>/<Name>_cc_ here and the frame count below."
        else:
            task = ("Write a prompt for an AI sound generator for this weapon sound: length, character, loop or one-shot, and the file format "
                    "to save (.wav or .m4a).")
            tail = "Save the sound in the mod's Audio\\Weapons folder and register it in the mod's AudioConfig.yaml (Category Weapons: Id, Volume, Sound), then type its Id here."
        AiTextDialog(self, "AI helper - " + lab, task, about + "\n" + tail)

    def library_sound(self, var, tag):
        app = getattr(self.owner, "app", None) or getattr(self, "app", None)
        r = pick_library(self, app, ["sound"], "Pick a sound from the library")
        if not r:
            return
        rel = r[2]
        sub = rel.split("/", 1)[1] if rel.lower().startswith("audio/") else rel
        cue = Path(rel).stem
        snippet = '    - SoundEffect:\n      Id: %s\n      Volume: 0.8\n      Sound: "%s"' % (cue, sub)
        try:
            self.clipboard_clear()
            self.clipboard_append(snippet)
        except Exception:
            pass
        var.set(cue)
        messagebox.showinfo("Sound added", "'%s' will be copied into the mod's Audio folder when you Save.\n\nThe game finds a sound through a cue: add these lines under a Category's "
                            "SoundEffects in your mod's AudioConfig.yaml (they are on your clipboard now):\n\n%s\n\n(If BB+ or the other mod already registers this sound under the "
                            "name '%s', the cue works as it is.)" % (rel, snippet, cue), parent=self)

    def build_fx(self, f):
        self.fxv = {}
        for r, (lab, tag, hint) in enumerate(self.FX):
            var = tk.StringVar()
            self.fxv[tag] = var
            if tag in self.SOUND_TAGS:
                def mk(var=var, tag=tag):
                    fr = tk.Frame(f, bg=PANEL)
                    cb = ttk.Combobox(fr, textvariable=var, values=[""] + self.proj.tag_values(tag), width=29)
                    cb.pack(side="left")
                    bt = ttk.Button(fr, text="▶ Play", width=7, command=lambda: self.fx_msg.configure(text=play_sound(self.proj, var.get())))
                    bt.pack(side="left", padx=(4, 0))
                    tip(bt, "Play a sample of this sound. Works when a separate sound file (.wav plays directly; .ogg / .mp3 / .m4a open in your "
                            "default player) with this cue's name is in the mod or game folders. Cues kept inside the game's sound banks "
                            "(.xwb) can't be played here.")
                    tip(cb, lambda tag=tag, hint=hint: hint + "\n\n" + weapon_tag_tip(self.proj, tag))
                    lb = ttk.Button(fr, text="Library…", width=9, command=lambda var=var, tag=tag: self.library_sound(var, tag))
                    lb.pack(side="left", padx=(4, 0))
                    tip(lb, "Pick a sound file from this mod, BB+ or the other mods in your Mods folder. It is copied into the mod's Audio folder when you Save; "
                            "the cue name is filled in and the AudioConfig.yaml lines to register it are copied to your clipboard.")
                    self.fx_ai_btn(fr, tag, lab, var)
                    return fr
                self.row(f, r, lab, mk, hint)
            elif tag in self.FX_FILE:
                def mk2(var=var, tag=tag, lab=lab):
                    fr = tk.Frame(f, bg=PANEL)
                    cb = ttk.Combobox(fr, textvariable=var, values=[""] + self.proj.tag_values(tag), width=30)
                    cb.pack(side="left")
                    tip(cb, lambda tag=tag: weapon_tag_tip(self.proj, tag))
                    self.fx_ai_btn(fr, tag, lab, var)
                    return fr
                self.row(f, r, lab, mk2, (lambda tag=tag, hint=hint: hint + "\n\n" + weapon_tag_tip(self.proj, tag)))
            else:
                self.row(f, r, lab, lambda var=var, tag=tag: ttk.Combobox(f, textvariable=var, values=[""] + self.proj.tag_values(tag), width=34),
                         (lambda tag=tag, hint=hint: hint + "\n\n" + weapon_tag_tip(self.proj, tag)))
            var.trace_add("write", lambda *_a: self.fx_preview())
        self.wp = WeaponPreview(f, self.proj, self.owner)
        self.wp.grid(row=0, column=2, rowspan=13, sticky="n", padx=(14, 0))
        tk.Label(f, bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=620,
                 text="Leave a box empty for none. Sounds and effects are names the game already knows (no file extension) - the lists show what "
                      "other weapons use. Pictures are .png (or .xnb / .dds) files in a Textures folder, typed without the extension; animation "
                      "frames are numbered PNGs (…00000.png, …00001.png). Each choice becomes a tag in the new weapon; edit them on the next step.").grid(
            row=len(self.FX), column=0, columnspan=3, sticky="w", pady=(8, 0))
        self.fx_msg = tk.Label(f, bg=PANEL, fg=PEACH, anchor="w", justify="left", wraplength=620)
        self.fx_msg.grid(row=len(self.FX) + 1, column=0, columnspan=3, sticky="w")
        self.fx_preview_ready = True
        self.fx_load()

    def fx_load(self):
        self.load_traits()
        for tag, var in self.fxv.items():
            var.set(self.traits.get(tag, ""))
        self.fx_preview()

    def fx_apply(self):
        for tag, var in self.fxv.items():
            val = var.get().strip()
            if val:
                self.traits[tag] = val
            else:
                self.traits.pop(tag, None)
        if self.traits.get("AnimationPath"):
            self.traits["Animated"] = self.traits.get("Animated") or "1"
            self.traits["LoopAnimation"] = self.traits.get("LoopAnimation") or "1"

    def fx_preview(self):
        spec = dict(self.traits)
        for tag, var in self.fxv.items():
            val = var.get().strip()
            if val:
                spec[tag] = val
            else:
                spec.pop(tag, None)
        if hasattr(self, "wp"):
            self.wp.set(spec)

    # ---- step 7: traits (tags) of the new weapon file
    def build_traits(self, f):
        tk.Label(f, text="All weapon tags", bg=PANEL, fg=PEACH).grid(row=0, column=0, sticky="w")
        tk.Label(f, text="Tags in the new weapon", bg=PANEL, fg=PEACH).grid(row=0, column=1, sticky="w", padx=(14, 0))
        self.tflt = tk.StringVar()
        e = ttk.Entry(f, textvariable=self.tflt, width=30)
        e.grid(row=1, column=0, sticky="we")
        tip(e, "Type part of a tag name (damage, range, shield, fire ...) to narrow the menu.")
        self.tflt.trace_add("write", lambda *_a: self.fill_menu())
        f.grid_rowconfigure(2, weight=1)
        self.tmenu = tk.Listbox(f, width=30, height=8, selectmode="extended", bg=PANEL2, fg=FG, selectbackground=SEL,
                                highlightthickness=1, highlightbackground=EDGE, activestyle="none", exportselection=False)
        self.tmenu.grid(row=2, column=0, sticky="nsew", pady=4)
        self.tmenu.bind("<Double-Button-1>", lambda _e: self.add_traits())
        self.tt, self.tt_row = ToolTip(self.tmenu, self.menu_tip, delay=300), None
        self.tmenu.bind("<Motion>", self.menu_motion, add="+")
        ab = ttk.Button(f, text="Add ›", command=self.add_traits)
        ab.grid(row=3, column=0, sticky="we")
        tip(ab, "Add the selected tags to the new weapon, with the value most weapons use (change it here or later in the module table).")
        self.trows = ScrollFrame(f, bg=PANEL)
        self.trows.canvas.configure(width=400, height=160)
        self.trows.grid(row=1, column=1, rowspan=3, sticky="nsew", padx=(14, 0))
        f.grid_columnconfigure(1, weight=1)
        self.tag_default = dict(self.proj.weapon_tags())
        self.fill_menu()
        self.fill_traits()

    def menu_row(self):
        try:
            i = self.tmenu.nearest(self.tmenu.winfo_pointery() - self.tmenu.winfo_rooty())
        except tk.TclError:
            return None
        return i if isinstance(i, int) and 0 <= i < len(self.menu_tags) else None

    def menu_tip(self):
        i = self.menu_row()
        return weapon_tag_tip(self.proj, self.menu_tags[i]) if i is not None else ""

    def menu_motion(self, _e):
        i = self.menu_row()
        if i != self.tt_row:
            self.tt_row = i
            self.tt.hide()
            if i is not None:
                self.tt.arm()

    def load_traits(self):
        """Start the trait list from the weapon being copied (when that changes)."""
        mode = self.v["wmode"].get()
        wb = self.wbase_by.get(self.v["wbase"].get()) if mode == "new" else None
        key = (mode, id(wb))
        if key == self.traits_for:
            return
        self.traits_for = key
        self.traits = {}
        if mode == "blank":                                         # a usable starting point: the basics every weapon has
            td = dict(self.proj.weapon_tags())
            for tag in ("DamageAmount", "FireDelay", "Range", "ProjectileSpeed"):
                if tag in td:
                    self.traits[tag] = td[tag]
        if wb is not None:
            for tag, val in wb.orig.items():
                if tag != "UID" and val != "{nested}":
                    self.traits[tag] = val.strip()

    def fill_menu(self):
        words = self.tflt.get().lower().split()
        self.menu_tags = [t for t in self.tag_default if t not in self.traits and all(w in t.lower() for w in words)]
        self.tmenu.delete(0, "end")
        for t in self.menu_tags:
            self.tmenu.insert("end", t)

    def add_traits(self):
        for i in self.tmenu.curselection():
            t = self.menu_tags[i]
            self.traits[t] = self.tag_default.get(t, "")
        self.fill_menu()
        self.fill_traits()

    def drop_trait(self, tag):
        self.traits.pop(tag, None)
        self.fill_menu()
        self.fill_traits()

    def fill_traits(self):
        self.trows.clear()
        self.tvars = {}
        for r, tag in enumerate(sorted(self.traits, key=str.lower)):
            var = tk.StringVar(value=self.traits[tag])
            self.tvars[tag] = var
            var.trace_add("write", lambda *_a, t=tag, v=var: self.traits.__setitem__(t, v.get()))
            lb = tk.Label(self.trows.inner, text=tag, bg=PANEL, fg=FG, anchor="w", width=24)
            lb.grid(row=r, column=0, sticky="w", pady=1)
            en = ttk.Entry(self.trows.inner, textvariable=var, width=14)
            en.grid(row=r, column=1, padx=4)
            tip(lb, lambda t=tag: weapon_tag_tip(self.proj, t))
            tip(en, lambda t=tag: weapon_tag_tip(self.proj, t))
            x = ttk.Button(self.trows.inner, text="✕", width=3, command=lambda t=tag: self.drop_trait(t))
            x.grid(row=r, column=2)
            tip(x, "Remove this tag from the new weapon file.")
        if not self.traits:
            tk.Label(self.trows.inner, text="(no tags - add some from the menu)", bg=PANEL, fg=DIM).grid(row=0, column=0)

    def goto(self, i):
        for f in self.pages.values():
            f.pack_forget()
        self.step = i
        if i not in self.pages:
            self.pages[i] = self.build(i)
        self.pages[i].pack(fill="both", expand=True)
        subs = ("Give the module a name and say what kind of thing it is. The UID is the file name; it is filled in from the name.",
                "Pick the picture the ship builder shows for the module (Textures\\Modules). These are the pictures already there - or import your own.",
                "Pick the picture the research screen shows for this unlock (Textures\\TechIcons\\<UID>.png). Pictures already in that folder are listed.",
                "Which file to start from, where it goes, and a few starting numbers. The module is saved as an .xml file named <UID>.xml.",
                "Does it fire a weapon? Choose an existing weapon, or make a new weapon file (an .xml named after the module's UID, in the Weapons folder).",
                "Pick the fire sound, the projectile's picture / model / animation and its effects. Names other weapons use are in each list.",
                "Tag the traits (damage, range, fire delay, shield effects ...) the new weapon should have and set their values; the rest is adjusted later in the module editor.",
                "Everything is created in memory; nothing is written until you Save (Ctrl+S).")
        self.head.configure(text=self.STEPS[i])
        self.sub.configure(text=subs[i])
        self.b_back.configure(state="normal" if i else "disabled")
        self.b_next.configure(text=("Create and unlock ✓" if self.tech is not None else "Create copy ✓") if i == self.LAST else "Next ›")
        if i == 5:
            self.fx_load()
        if i == 6:
            self.load_traits()
            self.fill_menu()
            self.fill_traits()
        if i == self.LAST:
            self.review()

    def review(self):
        sp = self.spec()
        tl = ", ".join(sorted(self.traits, key=str.lower)[:8]) + (" ..." if len(self.traits) > 8 else "")
        wl = {"none": "no weapon", "existing": "fires %s" % sp.get("weapon"),
              "blank": "NEW blank weapon file with %d tags: %s" % (len(self.traits), tl),
              "new": "NEW weapon file (copy of %s) with %d tags: %s" % (self.v["wbase"].get() or "?", len(self.traits),
                                                                         ", ".join(sorted(self.traits, key=str.lower)[:8]) + (" ..." if len(self.traits) > 8 else ""))}[sp["weapon_mode"]]
        pic = lambda t: {"__none": "none", "__same": "same as module picture", "__import": "imported file"}.get(t[0], t[0])
        self.rev.configure(text="Module:  %s  (%s)\nType:  %s     Size:  %s × %s\nFile:  %s\nStarts from:  %s\nWeapon:  %s\n"
                                "Module picture:  %s\nResearch picture:  %s\nUnlocked by:  %s"
                           % (sp["name"], sp["uid"], sp["mtype"], sp["x"], sp["y"], (sp["folder"] or "(module root)") + "/" + sp["uid"] + ".xml",
                              self.v["base"].get(), wl, pic(sp["pic2"]), pic(sp["pic3"]),
                              self.proj.tech_name(self.tech) if self.tech is not None else "(nothing - unlock it later in the Tech Tree)"))
        path = sp["pic2"][1] or sp["pic3"][1]
        im = self.owner.img(path, 96) if path else None
        self.pv.configure(image=im if im is not None else "")
        self.pv.image = im

    def spec(self):
        v = {k: x.get() for k, x in self.v.items()}
        return {"uid": v["uid"].strip(), "name": v["name"].strip(), "desc": self.desc.get("1.0", "end").strip() if hasattr(self, "desc") and self.desc.winfo_exists() else self.start_desc,
                "mtype": v["type"].strip(), "x": v["x"], "y": v["y"], "folder": v["folder"].strip().strip("/\\"),
                "base": self.base_by.get(v["base"]), "weapon_mode": v["wmode"], "weapon": v["weapon"],
                "wbase": self.wbase_by.get(v["wbase"]), "traits": dict(self.traits) if v["wmode"] in ("new", "blank") else None,
                "stats": {k: v[k] for k in ("Cost", "Mass", "HealthMax", "PowerDraw")},
                "pic2": self.pickers[1].value() if 1 in self.pickers else ("__none", None),
                "pic3": self.pickers[2].value() if 2 in self.pickers else ("__same", None), "race": v["race"],
                "same_icon": self.start.get("IconTexturePath").strip() if self.start is not None else ""}

    def check(self):
        P, v = self.proj, self.v
        if self.step == 0:
            uid = v["uid"].get().strip()
            if not v["name"].get().strip():
                return "Give the module a name."
            if not re.fullmatch(r"[A-Za-z0-9_]+", uid):
                return "The UID may only use letters, digits and _ ."
            if uid.lower() in {(m.get("UID") or m.path.stem).strip().lower() for m in P.modules}:
                return "A module with UID '%s' already exists." % uid
            if not v["type"].get().strip():
                return "Pick a module type."
            if not (v["x"].get().strip().isdigit() and v["y"].get().strip().isdigit() and int(v["x"].get()) > 0 and int(v["y"].get()) > 0):
                return "Size must be whole numbers, at least 1."
        if self.step == 4:
            m = v["wmode"].get()
            if m == "existing" and not v["weapon"].get():
                return "Pick the weapon the module fires."
            if m == "new" and not v["wbase"].get():
                return "Pick the weapon file to copy."
        return None

    def skip_traits(self):
        return self.v["wmode"].get() not in ("new", "blank")

    def back(self):
        if self.step:
            i = self.step - 1
            if i in (5, 6) and self.skip_traits():
                i = 4
            self.goto(i)

    def next(self):
        err = self.check()
        if err:
            messagebox.showwarning("New module", err, parent=self)
            return
        if self.step < self.LAST:
            i = self.step + 1
            if self.step == 5:
                self.fx_apply()
            if i in (5, 6) and self.skip_traits():
                i = 7
            self.goto(i)
            return
        self.result = self.spec()
        self.destroy()


HULL_BONUS_KEYS = ("Fuel Cell Bonus", "Power Flow Bonus", "Shield Power Bonus", "Module HP Bonus", "Repair Bonus", "Mass Reduction", "ArmourMass")


def apply_hull_bonuses(sp):
    """The hull bonuses ticked in the ship creator become upgrades of the tech that unlocks the ship (the game applies them to every ship of the empire)."""
    t = sp.get("tech")
    if t is None:
        return 0
    n = 0
    have = {(bonus_get(b, "BonusType") or bonus_get(b, "Name")) for b in t.bonuses}
    for key, amt in sp.get("bonuses", []):
        if key not in have:
            t.bonuses.append(bonus_make(key, key, amt, "0"))
            n += 1
    return n


class _WizApp:
    """Stands in for the app inside the layout editor opened from the New ship wizard (the ship is not in the project yet, so there is nothing to undo)."""
    def undo(self): pass
    def update_status(self): pass
    def say(self, *a, **k): pass


class _WizHullView(tk.Frame):
    """What HullGridEditor needs from the Ships tab: .cur (the hull being edited), .app, after_edit(), hull_pic()."""
    def __init__(self, wiz):
        super().__init__(wiz)
        self.wiz, self.app, self.cur = wiz, _WizApp(), None

    def after_edit(self):
        self.wiz.grid_from_doc(self.cur)

    def hull_pic(self, d):
        return None

    def outline(self):
        return self.wiz.proj.model_outline(self.wiz.v["model"].get())

    def turn_outline(self):
        self.wiz.proj.turn_outline(self.wiz.v["model"].get())

    def outline_why(self):
        return self.wiz.proj.__dict__.get("outline_why", {}).get(self.wiz.v["model"].get().strip(), "")

    def auto_fit(self, d):
        self.wiz.proj.auto_orient(self.wiz.v["model"].get(), d.slots)

    def shade(self):
        return self.wiz.proj.model_shade(self.wiz.v["model"].get())


class HullWizard(_Dialog):
    """New ship, laid out like the tech editor: a header with Cancel / Create, tabs (Details, Layout model and picture, Hull bonuses, Unlock) and a
    "this ship" panel on the right. result = spec for Project.create_hull_spec (plus "bonuses" for apply_hull_bonuses)."""
    TABS = ("Details", "Layout, model & picture", "Hull bonuses", "Tech unlock point")
    BLANK = "(blank layout)"

    def __init__(self, master, proj, start=None, tech=None):
        super().__init__(master, "New ship" if start is None else "Copy of a ship")
        self.proj, self.owner, self.icon, self.tech0 = proj, master, None, tech
        try:
            self.geometry("%dx%d" % (min(1420, self.winfo_screenwidth() - 40), min(860, self.winfo_screenheight() - 90)))
        except Exception:
            self.geometry("1300x760")
        hulls = sorted(proj.hulls + proj.base_hulls, key=lambda d: proj.hull_key(d).lower())
        self.by_label = {proj.hull_key(d): d for d in hulls}
        self.v = {k: tk.StringVar(value=val) for k, val in (("name", ""), ("folder", ""), ("vis", ""), ("role", "frigate"), ("style", ""),
                                                            ("base", self.BLANK), ("w", "6"), ("h", "10"), ("model", ""), ("tech", "(none)"))}
        if tech is not None:
            self.v["tech"].set("%s  (%s)" % (proj.tech_name(tech), tech.uid))
        self.hb = {k: (tk.BooleanVar(value=False), tk.StringVar(value="")) for k in HULL_BONUS_KEYS}
        top = tk.Frame(self, bg=PANEL)                                    # header, like the tech editor's
        top.pack(side="top", fill="x", padx=16, pady=(10, 0))
        self.title_lbl = tk.Label(top, bg=PANEL, fg=ORANGE, font=("Segoe UI", 18, "bold"), anchor="w")
        self.title_lbl.pack(fill="x")
        self.sub_lbl = tk.Label(top, bg=PANEL, fg=DIM, anchor="w")
        self.sub_lbl.pack(fill="x")
        bf = tk.Frame(top, bg=PANEL)
        bf.pack(anchor="w", pady=(8, 6))
        b = ttk.Button(bf, text="◀  Cancel", command=self.destroy)
        b.pack(side="left", padx=(0, 8))
        tip(b, "Close without creating the ship.")
        b = ttk.Button(bf, text="Create ship ✔", style="Save.TButton", command=self.create)
        b.pack(side="left")
        tip(b, "Create the ship (nothing is written until you Save, Ctrl+S). The slot layout can be painted on the Ships tab afterwards.")
        main = tk.Frame(self, bg=PANEL)
        main.pack(fill="both", expand=True, padx=16, pady=(0, 12))
        side = tk.Frame(main, bg=PANEL, width=290, highlightthickness=1, highlightbackground=EDGE)       # "this ship" panel on the right
        side.pack(side="right", fill="y", padx=(10, 0))
        side.pack_propagate(False)
        tk.Label(side, text="THIS SHIP (the in-game model, from above)", bg=PANEL, fg=ORANGE, font=("Segoe UI", 9, "bold"), anchor="w").pack(fill="x", padx=8, pady=(6, 0))
        self.pic_lbl = tk.Label(side, bg=PANEL2, width=96, height=72)
        self.pic_lbl.pack(pady=6)
        self.sum_lbl = tk.Label(side, bg=PANEL, fg=FG, justify="left", anchor="nw", wraplength=270)
        self.sum_lbl.pack(fill="both", expand=True, padx=8, pady=4)
        self.nb = ttk.Notebook(main)
        self.nb.pack(side="left", fill="both", expand=True)
        self.tabs = []
        for t in self.TABS:
            f = tk.Frame(self.nb, bg=PANEL)
            self.nb.add(f, text=t)
            self.tabs.append(f)
        if start is not None:
            key = proj.hull_key(start)
            self.v["base"].set(key)
            self.v["name"].set(start.path.stem + "_Copy")
            self.v["folder"].set(Path(key).parent.as_posix() if "/" in key else "")
            self.v["vis"].set((start.get("VisibleName") or start.path.stem) + " (copy)")
            self.pick_base()
        for f, fn in zip(self.tabs, (self.step0, self.step1, self.step_bonus, self.step2)):
            self.body = f
            holder = tk.Frame(f, bg=PANEL)
            holder.pack(fill="both", expand=True, padx=14, pady=10)
            self.body = holder
            fn()
        for var in self.v.values():
            var.trace_add("write", lambda *_a: self.refresh_summary())
        for on, amt in self.hb.values():
            on.trace_add("write", lambda *_a: self.refresh_summary())
            amt.trace_add("write", lambda *_a: self.refresh_summary())
        self.refresh_summary()
        self.show()

    def refresh_summary(self):
        try:
            sp = self.spec()
            key = (sp["folder"] + "/" if sp["folder"] else "") + (sp["name"] or "(name)")
            self.title_lbl["text"] = "%s   (%s)" % (sp["visible"] or sp["name"] or "New ship", sp["name"] or "-")
            self.sub_lbl["text"] = "%s  ·  %s  ·  Hulls/%s.hull" % (sp["role"], sp["style"] or "no style yet", key)
            bn = ", ".join("%s %s" % (k, a) for k, a in sp["bonuses"]) or "none"
            self.sum_lbl["text"] = ("Starts from:  %s\nModel:  %s\nPicture:  %s\nUnlocked by:  %s\nHull bonuses:  %s\n\nNothing is written until you Save (Ctrl+S). "
                                    "After creating, paint the slots on the Ships tab." % (
                                        sp["base"] and self.proj.hull_key(sp["base"]) or "a blank %sx%s grid" % (sp["cols"], sp["rows"]),
                                        sp["model"] or "(none yet)",
                                        "same as the original" if sp["icon"] and sp["icon"][0] == "__same" else (sp["icon"][0] if sp["icon"] else "(none)"),
                                        self.proj.tech_name(sp["tech"]) if sp["tech"] is not None else "(no tech yet)", bn))
            sd = self.proj.model_shade(sp["model"]) if sp["model"] else None
            if sd:
                h, w = len(sd["px"]), len(sd["px"][0])
                f = min(250.0 / w, 190.0 / h)
                tw, th = max(2, int(w * f)), max(2, int(h * f))
                key = (id(sd), tw, th)
                if getattr(self, "_pic_key", None) != key:
                    self._pic_im, self._pic_key = tk.PhotoImage(master=self.pic_lbl, data=shade_ppm(sd["px"], tw, th, (26, 32, 48))), key
                im = self._pic_im
                self.pic_lbl.configure(image=im, width=tw, height=th)
            else:
                bp = self.proj.id_picture(self.proj.hull_key(sp["base"])) if sp["base"] is not None else None
                im = load_image(bp, 64) if bp else None
                if getattr(self, "_blank_im", None) is None:
                    self._blank_im = tk.PhotoImage(master=self.pic_lbl, width=96, height=72)      # an empty label's size counts in text lines, not pixels - keep it small
                self.pic_lbl.configure(image=im or self._blank_im, width=96, height=72)
            self.pic_lbl.image = im
        except Exception:
            pass

    def pick_base(self):
        d = self.by_label.get(self.v["base"].get())
        if d is None:
            return
        self.v["role"].set(d.get("Role") or self.v["role"].get())
        self.v["style"].set(d.get("Style") or self.v["style"].get())
        self.v["model"].set(d.get("ModelPath"))
        ip = d.get("IconPath").strip()
        self.icon = ("__same", None) if ip else None

    def folders(self):
        seen = {Path(self.proj.hull_key(d)).parent.as_posix() for d in self.proj.hulls + self.proj.base_hulls}
        return sorted((f for f in seen if f != "."), key=str.lower)

    def row(self, parent, r, text, w, hint=None):
        lb = tk.Label(parent, text=text, bg=PANEL, fg=FG, anchor="w")
        lb.grid(row=r, column=0, sticky="w", pady=4)
        w.grid(row=r, column=1, sticky="w", padx=8)
        if hint:
            tip(lb, hint)
            tip(w, hint)

