        B, v = self.body, self.v
        tk.Label(B, bg=PANEL, fg=DIM, anchor="w", justify="left", wraplength=700,
                 text="The name is also the file name (Hulls\\<folder>\\<name>.hull) and what techs use to unlock the ship, so it must be unique.").pack(fill="x", pady=(0, 6))
        g = tk.Frame(B, bg=PANEL)
        g.pack(fill="x")
        self.row(g, 0, "Name (file name)", ttk.Entry(g, textvariable=v["name"], width=36),
                 "The ship's file name, e.g. Gunboat.\nIt becomes Hulls\\<folder>\\<name>.hull and is the key techs use to unlock the ship.\nLetters, digits, spaces, _ and - are fine. Must be unique.")
        self.row(g, 1, "Folder", ttk.Combobox(g, textvariable=v["folder"], values=self.folders(), width=33),
                 "The sub-folder of Hulls the file goes in (e.g. Terran).\nPick an existing one, type a new name to make a folder, or leave empty to use the Hulls folder itself.")
        self.row(g, 2, "Name shown in game", ttk.Entry(g, textvariable=v["vis"], width=36),
                 "VisibleName: what players see in the ship list and design screen.\nLeave empty to use the file name.")
        self.row(g, 3, "Role", ttk.Combobox(g, textvariable=v["role"], values=list(HULL_ROLES), width=33), "The ship's type (Role): fighter, frigate, cruiser, battleship, capital ...\nThe game uses it to group ships and for how the AI uses them.")
        styles = sorted({d.get("Style") for d in self.proj.hulls + self.proj.base_hulls if d.get("Style")}, key=str.lower)
        self.row(g, 4, "Style", ttk.Combobox(g, textvariable=v["style"], values=styles, width=33), "The ship's race / style (Style): Terran, Federation, Klingon ...\nUse the same word as the existing ships of that race so the filters group them.")

