        b.pack(side="left", padx=6)
        tip(b, "Open the 3D ship maker: it builds simple 3D ships (.obj with textures) for this ship's style and role, and you use the one that fits.")
        mm = ttk.Menubutton(m1, text="Choose a model  ▾")
        menu = tk.Menu(mm, tearoff=0, bg=PANEL2, fg=FG, activebackground=ORANGE, activeforeground="#000000")
