        menu.add_command(label="From the library…", command=self.library_model)
        menu.add_command(label="Import from PC…", command=self.import_model)
        menu.add_separator()
        menu.add_command(label="Make with an AI…", command=self.ai_model)
        mm["menu"] = menu
