        self.mod_tv.configure(yscrollcommand=sb.set)
        sb.pack(side="right", fill="y")
        self.mod_tv.pack(side="left", fill="both", expand=True)
        self.mod_tv.bind("<Double-1>", lambda _e: self.mod_edit())
